part of 'main.dart';

// Jedna odměna Battle Passu (free nebo prémiová větev, jedna úroveň) - viz
// GameState.battlePassRewardFor().
class BattlePassReward {
  final int gold;
  final int dust;
  final int crystals;
  final bool premium;
  final int level;
  // Truhla - na každém 5. levelu (5/10/15.../40, obě větve) dostane odměna navrch bonusový
  // balíček (viz battlePassRewardFor) a v UI se místo běžných ikon zobrazí jako truhla.
  final bool isChest;
  // Kosmetický rám portrétu (free větev, level 40) - id z GameState.unlockedFrames.
  final String? cosmeticFrameId;
  // Kosmetický skin základního útoku (premium větev, level 40) - odemkne OBĚ varianty
  // (fyzickou i magickou), hra sama vybere podle typu útoku aktuální třídy.
  final String? cosmeticAttackSkinId;
  // Kosmetická aura (premium větev, level 10) a pozadí karty (premium větev, level 30) - viz
  // konverzace "premium BP dej 5 spark na úroveň, na 10 aura/20 rám/30 pozadí/40 skin, v
  // souladu graficky s rift sezónou". Stejný vzor jako cosmeticFrameId/cosmeticAttackSkinId
  // výš - id NENÍ v kCosmeticShopCatalog (nejde koupit zvlášť, jen přes Battle Pass), takže se
  // musí přidat i speciální case do equippedAuraColor/equippedCardBackgroundColor.
  final String? cosmeticAuraId;
  final String? cosmeticCardBackgroundId;
  // Jiskry (viz cosmeticSparks) - 5 na KAŽDÉ prémiové úrovni (viz konverzace), ne jen na
  // milnících jako ostatní kosmetika výš.
  final int sparks;
  // Permanentní pasivní bonus vlastnictví Premium (ne jednorázová odměna k vyzvednutí) - zatím
  // jen level 1 Premium: +20 % Quest XP. Zobrazuje se jako trvalý štítek na dlaždici, funguje
  // bez ohledu na to, jestli hráč level 1 fyzicky "vyzvedl" (viz _addBattlePassRenown).
  final int questXpBonusPercent;
  const BattlePassReward({this.gold = 0, this.dust = 0, this.crystals = 0, required this.premium, required this.level, this.isChest = false, this.cosmeticFrameId, this.cosmeticAttackSkinId, this.cosmeticAuraId, this.cosmeticCardBackgroundId, this.sparks = 0, this.questXpBonusPercent = 0});
}

// Barva pro BP/achievement-exkluzivní kosmetiku Trhliny Osudu (mimo kCosmeticShopCatalog) -
// sdílená mezi Kosmetikou (náhledy dlaždic) a equippedAuraColor/equippedCardBackgroundColor
// getterama výš, ať se paleta nemusí duplikovat na dvou místech. Používá se pro aury a pozadí
// karty (rámy/skiny mají svoje vlastní _frameStyleFor/attackSkinAccent v ui_design.dart).
Color bpRiftCosmeticColor(String id) {
  switch (id) {
    case 'bp_bastion_aura': case 'bp_bastion_bg': case 'bp_bastion_frame': case 'bp_bastion_skin':
      return const Color(0xFF4A90D9);
    case 'bp_plague_aura': case 'bp_plague_bg': case 'bp_plague_frame': case 'bp_plague_skin':
      return const Color(0xFF6B8B3A);
    case 'bp_precision_aura': case 'bp_precision_bg': case 'bp_precision_frame': case 'bp_precision_skin':
      return const Color(0xFFE0A030);
    case 'bp_chaos_aura': case 'bp_chaos_bg': case 'bp_chaos_frame': case 'bp_chaos_skin':
      return const Color(0xFFFF3D7A);
    case 'rift_universal_aura': case 'rift_universal_bg': case 'rift_universal_frame': case 'rift_universal_skin':
      return const Color(0xFF9D7BFF);
    default:
      return const Color(0xFF9D7BFF);
  }
}

class GameState extends ChangeNotifier with WidgetsBindingObserver {
  // ===== AUTOSAVE =====
  // Cíl: hráč nikdy neztratí progress. Dvě vrstvy:
  //  1) Debounced autosave - kdykoliv se stav hry změní (notifyListeners), naplánuje se
  //     uložení za pár sekund. Pokud mezitím přijdou další změny, časovač se NEresetuje
  //     pořád dokola (to by při souvislém auto-boji po 500 ms mohlo uložení navždy
  //     odsouvat) - prostě jen počká, až aktuálně naplánované uložení proběhne, a pak
  //     naplánuje další. V praxi tak při aktivní hře ukládá zhruba každé 2 sekundy.
  //  2) Uložení OKAMŽITĚ při přechodu appky na pozadí (přepnutí appky, zamknutí telefonu,
  //     zavření) - viz didChangeAppLifecycleState - protože OS může appku na mobilu kdykoliv
  //     ukončit bez varování a 2s debounce by to nemuselo stihnout.
  Timer? _autoSaveDebounce;

  void _scheduleAutoSave() {
    if (heroClass == HeroClass.none) return; // není co ukládat, dokud hráč nemá rozehranou postavu
    if (_autoSaveDebounce != null && _autoSaveDebounce!.isActive) return;
    _autoSaveDebounce = Timer(const Duration(seconds: 2), () {
      saveGame();
    });
  }

  @override
  void notifyListeners() {
    super.notifyListeners();
    _scheduleAutoSave();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.paused || state == AppLifecycleState.inactive || state == AppLifecycleState.detached) {
      _autoSaveDebounce?.cancel();
      if (heroClass != HeroClass.none) saveGame();
    }
  }

  @override
  void dispose() {
    _autoSaveDebounce?.cancel();
    WidgetsBinding.instance.removeObserver(this);
    super.dispose();
  }

  // ===== REBALANCE: minimální damage & globální shield cap =====
  // Žádný útok nikdy nesmí způsobit pouze 1 damage - vždy minimálně 10 % teoretického damage útočníka.
  int _minDmg(num attackerAtk, num rawDiff) {
    final floor = (attackerAtk * 0.10).round();
    final diff = rawDiff.toInt();
    return diff > floor ? diff : floor;
  }

  // Všechny absorb štíty sdílí jeden limit: maxShield = maxHp * 1.5.
  void _applyShieldCap() {
    final cap = (maxHp * 1.5 * relicShieldMult * (bulwarkSetSynergy?1.15:1.0) * (isInRift&&currentRiftSeason==RiftSeasonTheme.bastion?1.5:1.0)).toInt();
    if (bonusShield > cap) bonusShield = cap;
    // Centralizované místo pro "vznik štítu" FX - volá se po každém bonusShield += napříč hrou,
    // takže stačí sledovat rozdíl oproti poslední známé hodnotě místo úpravy desítek call sites.
    final delta = bonusShield - _lastKnownBonusShield;
    if (delta > 0) _pushFx(FxKind.shieldGained, FxSide.hero, value: delta);
    _lastKnownBonusShield = bonusShield;
  }

  // ===== DIMINISHING RETURNS pro Crit/Dodge/Block =====
  // Měkký strop (hyperbolická křivka, styl PoE evasion / LoL armor): raw hodnota
  // (součet base + statů + class bonusů + run) se namapuje na efektivní hodnotu,
  // která se ke cap asymptoticky blíží, ale nikdy ho snadno "nedorazí" nahoubáním
  // pár statů. Malé raw hodnoty (<< cap) jsou skoro nedotčené - DR se citelně
  // projeví až v druhé polovině cesty ke capu, takže hráč capu nedosáhne
  // rychle jen z pár položek/run, ale pořád k němu může postupně směřovat.
  double _diminish(double raw, double cap) {
    if (raw <= 0 || cap <= 0) return 0.0;
    return cap * raw / (raw + cap);
  }

  final int baseMaxHp = 150;
  final int basePhysAtk = 20;
  final int baseMagAtk = 20;
  final int basePhysDef = 5;
  final int baseMagDef = 5;

  int hp = 150;
  int xp = 0;
  int xpToLevel = 100;
  // Permanentní úroveň hrdiny - NEresetuje se při smrti (viz resetGame()), podobně
  // jako classRanks (Paragon systém). Talentové body k rozdání po smrti = level.
  int level = 1;
  int gold = 100;
  int crystals = 0;
  int magicDust = 0;
  // Jiskry - samostatná měna VÝHRADNĚ pro Kosmetiku (rámy/skiny/aury/tlačítka/pozadí karty i
  // ruční per-slot symboly a barvy) - viz konverzace "vytvoř currency pro nákup kosmetiky, zruš
  // crystal a goldy". Získává se JEN zhlédnutím rewarded reklamy (+1 ks/reklama, max 10 denně -
  // viz grantCosmeticSparkFromAd() níž a reset v _checkQuestResets()) - ne levelem, ne
  // achievementy, ne zlatem/krystaly.
  int cosmeticSparks = 0;
  int cosmeticSparksFromAdsToday = 0;
  static const int cosmeticSparksMaxPerDay = 10;
  bool get canWatchAdForCosmeticSpark => cosmeticSparksFromAdsToday < cosmeticSparksMaxPerDay;
  int floor = 1;
  // ===== TOWER MODIFIKÁTORY — za KAŽDÉ poražené patro Věže hráč dostane náhodně JEDEN ze 4
  // bonusů (permanentní, nereseuje se smrtí jako floor/level - viz _handleEnemyDeath): +1 % Crit,
  // +1 % Block, +1 % Dodge, nebo +5 % Absorb štít na začátku každého Tower souboje (stack se sčítá).
  int towerModCritStacks = 0;
  int towerModBlockStacks = 0;
  int towerModDodgeStacks = 0;
  int towerModAbsorbStacks = 0;
  int enemiesDefeatedOnFloor = 0;
  HeroClass heroClass = HeroClass.none;
  int talentPoints = 0;
  // Trvalý (na smrt nezávislý) čítač bodů reálně UDĚLENÝCH z lairFloorTalentClaims - na rozdíl
  // od délky toho Setu (což by mohlo počet bodů nadhodnotit po dosažení stropu 100/obtížnost,
  // protože se do Setu dál zapisují navštívená patra i bez udělení bodu). Bez tohohle čítače
  // resetGame() po smrti tyhle natrvalo vydělané body ztrácel (přepisoval talentPoints jen na
  // level) - viz oprava v resetGame().
  int permanentLairTalentPoints = 0;
  // Jednorázová migrace (viz fromJson) - dopočítá lairFloorTalentClaims/permanentLairTalentPoints
  // ZPĚTNĚ z lairRewardClaims pro hráče, co má Lair patra poražená ještě z DOBY PŘED zavedením
  // talent-bodů za Lair floor-clear. Bez tohohle zůstávaly staré (odměnu už dávno vyzvednuté)
  // floory navždy nezapočítané, protože lairFloorTalentClaims se retroaktivně nikdy nenaplnil.
  bool lairTalentBackfillV2Done = false;
  // Jednorázová migrace (viz fromJson) - opravuje hráče, u kterých starý SDÍLENÝ strop
  // (Tower+Lair dohromady, viz floorTalentCapReachedForCurrentDifficulty před opravou) natrvalo
  // zablokoval udělení Lair bodu, i když dané patro hráč skutečně poprvé vyčistil (lairFloorTalentClaims
  // ho eviduje bez ohledu na strop - viz jeho přidání PŘED kontrolou capu v _handleLairBossDeath()).
  // Přepočítá permanentLairTalentPoints čistě z lairFloorTalentClaims (per obtížnost, strop 100
  // každá zvlášť) a dorovná chybějící rozdíl do talentPoints.
  bool lairTalentIndependentCapFixDone = false;

  // ===== ZDROJE PRO SCHOPNOSTI (Mana/Hněv/Energie) =====
  // Léčitel: Mana (spotřebovává se, pomalu regeneruje).
  // Válečník: Hněv (začíná na 0, roste bojem).
  // Lovec: Energie (rychle regeneruje, vysoký strop).
  int mana = 100;
  int maxMana = 100;
  int rage = 0;
  int maxRage = 100;
  int energy = 100;
  int maxEnergy = 100;

  // Cena schopností podle úrovně odemčení (v příslušném zdroji). Platí i v Lair.
  // Hunter Divočina: -25 % náklad (viz specResourceCostMod).
  int get ability1Cost => (30 * specResourceCostMod).round(); // Rank 15+ (pokročilá třída)
  int get ability2Cost => (45 * specResourceCostMod).round(); // Rank 40+ (ultimate)
  int get ability3Cost => (65 * specResourceCostMod).round(); // Rank 75+ (god class)
  int get ability4Cost => (85 * specResourceCostMod).round(); // Rank 100 (volitelná cesta)

  int get currentResourceValue {
    switch (heroClass) {
      case HeroClass.healer:
      case HeroClass.mage:
      case HeroClass.druid:
      case HeroClass.necromancer:
        return mana;
      case HeroClass.warrior:
        return rage;
      case HeroClass.hunter:
      case HeroClass.duelist:
      case HeroClass.monk:
      case HeroClass.demonhunter:
        return energy; // Zuřivost sdílí mechaniku Energie (regeneruje plynule, jako proudění bojem)
      case HeroClass.deathknight:
        return rage; // Temná Síla sdílí mechaniku Hněvu (0→100, buduje se bojem)
      case HeroClass.paladin:
        return rage; // Víra sdílí mechaniku Hněvu (buduje se bojem jako Warrior/DK)
      default:
        return 0;
    }
  }

  int get maxResourceValue {
    switch (heroClass) {
      case HeroClass.healer:
      case HeroClass.mage:
      case HeroClass.druid:
      case HeroClass.necromancer:
        return maxMana;
      case HeroClass.warrior:
        return maxRage;
      case HeroClass.hunter:
      case HeroClass.duelist:
      case HeroClass.monk:
      case HeroClass.demonhunter:
        return maxEnergy;
      case HeroClass.deathknight:
      case HeroClass.paladin:
        return maxRage;
      default:
        return 0;
    }
  }

  String get resourceName {
    switch (heroClass) {
      case HeroClass.healer:
        return "Mana";
      case HeroClass.mage:
        return "Mana";
      case HeroClass.druid:
        return "Přírodní Energie";
      case HeroClass.necromancer:
        return "Duše";
      case HeroClass.warrior:
        return "Hněv";
      case HeroClass.hunter:
        return "Energie";
      case HeroClass.duelist:
        return "Mrštnost";
      case HeroClass.deathknight:
        return "Temná Síla";
      case HeroClass.monk:
        return "Čchi";
      case HeroClass.paladin:
        return "Víra";
      case HeroClass.demonhunter:
        return "Zuřivost";
      default:
        return "";
    }
  }

  // ===== IDENTITA STATŮ TŘÍDY — pro nové sloty Přilba/Opasek/Plášť (viz _applySlotClassBias). =====
  // Přilba nese hlavní bojový stat třídy, Opasek vždy Vitalitu (univerzální odolnost),
  // Plášť signature bojový stat třídy (crit/dodge/block - stejná identita jako ve zbytku hry).
  // ===== SPEC STAT PROFIL — hlavní/vedlejší stat a Tank Armor koeficient PODLE SPECIALIZACE =====
  // Nahrazuje starý systém, kde měla celá TŘÍDA jeden pevný hlavní stat (classMainStat níže
  // zůstává pro itemizaci Přilby/Opasku/Pláště beze změny, ale physAtk/magAtk teď čtou
  // z tohohle spec-přesného profilu). Váhy a Tank koeficienty jsou výsledek designové diskuze -
  // viz komentáře u jednotlivých tříd.
  SpecStatProfile get specStatProfile {
    final spec = specialization <= 1 ? 1 : specialization; // dokud není zvoleno, počítej jako spec 1
    switch (heroClass) {
      case HeroClass.warrior:
        if (spec == 1) return const SpecStatProfile("Strength", "Agility", 0.3);
        if (spec == 2) return const SpecStatProfile("Strength", "Agility", 0.3, tankArmorCoefficient: 1.5);
        return const SpecStatProfile("Strength", "Agility", 0.4);
      case HeroClass.hunter:
        if (spec == 1) return const SpecStatProfile("Agility", "Strength", 0.3);
        if (spec == 2) return const SpecStatProfile("Agility", "Strength", 0.3);
        return const SpecStatProfile("Agility", "Wisdom", 0.35);
      case HeroClass.healer:
        if (spec == 1) return const SpecStatProfile("Wisdom", "Agility", 0.2);
        if (spec == 2) return const SpecStatProfile("Wisdom", "Strength", 0.4);
        return const SpecStatProfile("Wisdom", "Agility", 0.3);
      case HeroClass.deathknight:
        if (spec == 1) return const SpecStatProfile("Strength", "Wisdom", 0.35, tankArmorCoefficient: 1.35);
        if (spec == 2) return const SpecStatProfile("Strength", "Wisdom", 0.25);
        return const SpecStatProfile("Strength", "Wisdom", 0.45);
      case HeroClass.mage:
        if (spec == 1) return const SpecStatProfile("Wisdom", "Agility", 0.2);
        if (spec == 2) return const SpecStatProfile("Wisdom", "Strength", 0.2);
        return const SpecStatProfile("Wisdom", "Agility", 0.3);
      case HeroClass.duelist:
        if (spec == 1) return const SpecStatProfile("Agility", "Strength", 0.3);
        if (spec == 2) return const SpecStatProfile("Agility", "Strength", 0.25);
        return const SpecStatProfile("Agility", "Strength", 0.3);
      case HeroClass.monk:
        // Vichr/Skála: Agility hlavní (Wisdom/Strength vedlejší). Klid: Wisdom hlavní.
        if (spec == 1) return const SpecStatProfile("Agility", "Wisdom", 0.4);
        if (spec == 2) return const SpecStatProfile("Agility", "Strength", 0.4, tankArmorCoefficient: 1.3);
        return const SpecStatProfile("Wisdom", "Agility", 0.3);
      case HeroClass.druid:
        if (spec == 1) return const SpecStatProfile("Wisdom", "Agility", 0.2);
        if (spec == 2) return const SpecStatProfile("Strength", "Wisdom", 0.3, tankArmorCoefficient: 1.4);
        return const SpecStatProfile("Wisdom", "Agility", 0.25);
      case HeroClass.paladin:
        if (spec == 1) return const SpecStatProfile("Strength", "Wisdom", 0.3, tankArmorCoefficient: 1.45);
        if (spec == 2) return const SpecStatProfile("Strength", "Wisdom", 0.25);
        return const SpecStatProfile("Strength", "Wisdom", 0.5);
      case HeroClass.demonhunter:
        if (spec == 1) return const SpecStatProfile("Agility", "Strength", 0.25);
        if (spec == 2) return const SpecStatProfile("Agility", "Strength", 0.35, tankArmorCoefficient: 1.30);
        return const SpecStatProfile("Agility", "Wisdom", 0.3);
      case HeroClass.necromancer:
        if (spec == 1) return const SpecStatProfile("Wisdom", "Agility", 0.25);
        if (spec == 2) return const SpecStatProfile("Wisdom", "Agility", 0.2);
        return const SpecStatProfile("Wisdom", "Strength", 0.3);
      default:
        return const SpecStatProfile("Strength", null, 0.0);
    }
  }

  // Hodnota konkrétního statu podle klíče ("Strength"/"Agility"/"Wisdom") - pomocník pro
  // physAtk/magAtk, co čtou hlavní/vedlejší stat z specStatProfile jménem, ne napevno.
  double _statValueByKey(String? key) {
    switch (key) {
      case "Strength": return totalStrength;
      case "Agility": return totalAgility;
      case "Wisdom": return totalWisdom;
      default: return 0;
    }
  }

  String get classMainStat {
    switch (heroClass) {
      case HeroClass.warrior:
      case HeroClass.deathknight:
      case HeroClass.paladin:
      case HeroClass.monk:
        return "Strength";
      case HeroClass.hunter:
      case HeroClass.duelist:
      case HeroClass.demonhunter:
        return "Agility";
      case HeroClass.healer:
      case HeroClass.mage:
      case HeroClass.druid:
      case HeroClass.necromancer:
        return "Wisdom";
      default:
        return "Strength";
    }
  }

  String get classCombatStat {
    switch (heroClass) {
      case HeroClass.warrior:
      case HeroClass.paladin:
        return "Block"; // Nezlomná hradba / Posvátný štít
      case HeroClass.hunter:
      case HeroClass.duelist:
      case HeroClass.demonhunter:
      case HeroClass.monk:
        return "Dodge"; // Hbitost lovce / Elegantní výpad / Fel hbitost / Plynoucí Čchi
      case HeroClass.healer:
      case HeroClass.deathknight:
      case HeroClass.mage:
      case HeroClass.druid:
      case HeroClass.necromancer:
        return "Crit"; // Posvátný úsudek / Smrtící přesnost / Přírodní úder / Smrtící rituál
      default:
        return "Crit";
    }
  }

  // Přemapuje nejsilnější stat na daném itemu na stat odpovídající identitě AKTUÁLNÍ třídy,
  // pokud jde o jeden z nových "class-identity" slotů. Volá se těsně před vytvořením Item -
  // funguje napříč craftItem/buyItem/_tryDropItem, aniž by bylo nutné upravovat jejich
  // vnitřní generování statů.
  void _applySlotClassBias(Map<String, int> itemStats, EquipSlot? slot) {
    if (itemStats.isEmpty || heroClass == HeroClass.none) return;
    String? targetStat;
    if (slot == EquipSlot.helmet) targetStat = classMainStat;
    else if (slot == EquipSlot.belt) targetStat = "Vitality";
    else if (slot == EquipSlot.cloak) targetStat = classCombatStat;
    else if (slot == EquipSlot.shoulders) targetStat = classMainStat;
    if (targetStat == null) return;
    final topEntry = itemStats.entries.reduce((a, b) => a.value >= b.value ? a : b);
    if (topEntry.key == targetStat) return;
    final value = itemStats.remove(topEntry.key)!;
    itemStats[targetStat] = (itemStats[targetStat] ?? 0) + value;
  }

  Color get resourceColor {
    switch (heroClass) {
      case HeroClass.healer:
      case HeroClass.mage:
        return const Color(0xFF2E86FF); // modrá mana
      case HeroClass.druid:
        return const Color(0xFF43A047); // zelená přírodní energie
      case HeroClass.necromancer:
        return const Color(0xFF6A1B9A); // temně fialová Duše
      case HeroClass.warrior:
        return const Color(0xFFE01F1F); // červený hněv
      case HeroClass.paladin:
        return const Color(0xFFFFD700); // zlatá víra
      case HeroClass.hunter:
        return const Color(0xFFE0C22E); // žlutá energie
      case HeroClass.duelist:
        return const Color(0xFF3EDBB0); // tyrkysová mrštnost
      case HeroClass.demonhunter:
        return const Color(0xFF7B2FBE); // fialová zuřivost
      case HeroClass.deathknight:
        return const Color(0xFF70D7FF); // ledová modrá Temná Síla (stejná jako DK SpellVisual)
      case HeroClass.monk:
        return const Color(0xFFFFB74D); // jantarová Čchi (stejná jako Monk SpellVisual)
      default:
        return Colors.grey;
    }
  }

  // Pokusí se strhnout náklad ze zdroje. Vrací true při úspěchu.
  bool _spendResource(int cost) {
    if (currentResourceValue < cost) return false;
    switch (heroClass) {
      case HeroClass.healer:
      case HeroClass.mage:
      case HeroClass.druid:
      case HeroClass.necromancer:
        mana -= cost;
        break;
      case HeroClass.warrior:
        rage -= cost;
        break;
      case HeroClass.hunter:
      case HeroClass.duelist:
      case HeroClass.monk:
      case HeroClass.demonhunter:
        energy -= cost;
        break;
      case HeroClass.deathknight:
      case HeroClass.paladin:
        rage -= cost;
        break;
      default:
        break;
    }
    return true;
  }

  // Nepřátelské schopnosti (resourceDrain, viz enemyAbilityEffects) potřebují odčerpat % z
  // AKTUÁLNÍHO zdroje hrdiny - currentResourceValue je ale jen getter (dispatchuje na mana/
  // rage/energy podle třídy), nejde do něj přiřazovat přímo. Používá stejný switch jako
  // _spendResource() výš, jen odečítá % místo pevné ceny.
  void _drainResourcePct(double pct) {
    final amount = (maxResourceValue * pct).round();
    switch (heroClass) {
      case HeroClass.healer:
      case HeroClass.mage:
      case HeroClass.druid:
      case HeroClass.necromancer:
        mana = max(0, mana - amount);
        break;
      case HeroClass.warrior:
        rage = max(0, rage - amount);
        break;
      case HeroClass.hunter:
      case HeroClass.duelist:
      case HeroClass.monk:
      case HeroClass.demonhunter:
        energy = max(0, energy - amount);
        break;
      case HeroClass.deathknight:
      case HeroClass.paladin:
        rage = max(0, rage - amount);
        break;
      default:
        break;
    }
  }

  // Regenerace/nárůst zdroje za jedno kolo (základní útok i seslání schopnosti = 1 kolo).
  void _regenResource() {
    switch (heroClass) {
      case HeroClass.healer:
      case HeroClass.mage:
      case HeroClass.druid:
      case HeroClass.necromancer:
        mana = (mana + 6).clamp(0, maxMana);
        break;
      case HeroClass.warrior:
        rage = (rage + 15).clamp(0, maxRage);
        break;
      case HeroClass.hunter:
      case HeroClass.duelist:
      case HeroClass.monk:
      case HeroClass.demonhunter:
        energy = (energy + 12).clamp(0, maxEnergy);
        break;
      case HeroClass.deathknight:
        rage = (rage + 15).clamp(0, maxRage); // Temná Síla roste bojem jako Hněv
        break;
      case HeroClass.paladin:
        rage = (rage + 15).clamp(0, maxRage); // Víra roste bojem jako Hněv
        break;
      default:
        break;
    }
  }

  void _resetResources() {
    mana = maxMana;
    rage = 0;
    energy = maxEnergy;
  }

