  Set<String> unlockedRelicIds={}; Map<String,int> relicXp={}; Map<String,int> relicMastery={}; String? activeRelicId;
  static const int relicXpPerLevel=100,relicMaxLevel=10;
  LegendaryRelic? get activeRelic {final m=LegendaryRelic.values.where((r)=>r.name==activeRelicId);return m.isEmpty?null:m.first;}
  bool relicUnlocked(LegendaryRelic r)=>unlockedRelicIds.contains(r.name);
  int relicLevel(LegendaryRelic r)=>!relicUnlocked(r)?0:(1+(relicXp[r.name]??0)~/relicXpPerLevel).clamp(1,relicMaxLevel).toInt();
  int relicXpInLevel(LegendaryRelic r)=>(relicXp[r.name]??0)%relicXpPerLevel;
  // relicMastery[r.name] je surové, neomezené nastřádané XP (viz addRelicXp - jednou aktivní
  // amulet dosáhne max levelu A jsou objevené všechny amulety, KAŽDÝ zabitý nepřítel navíc
  // sype XP sem, bez stropu). Dřív se tohle číslo použilo PŘÍMO jako "level" v relicMasteryDamageMult
  // (level*0.001) - po delší hře tak level dosahoval statisíců až milionů a damage multiplier
  // exploduje na stovky/tisíce×, místo rozumného postupného bonusu. Dělením stejným tempem jako
  // základní relic leveling (relicXpPerLevel) dostaneme skutečný "level" v rozumném řádu.
  int relicMasteryLevel(LegendaryRelic r)=>(relicMastery[r.name]??0)~/relicXpPerLevel;
  bool get relicMasteryUnlocked=>LegendaryRelic.values.every(relicUnlocked);
  bool relicAt(LegendaryRelic r,int lv)=>activeRelic==r&&relicLevel(r)>=lv;
  void equipRelic(LegendaryRelic r){if(!relicUnlocked(r))return;activeRelicId=r.name;message=tr("Aktivní amulet: ${r.displayName}.", "Active amulet: ${r.displayName}.");notifyListeners();}
  void addRelicXp(int n){final r=activeRelic;if(r==null)return;final old=relicXp[r.name]??0;final cap=(relicMaxLevel-1)*relicXpPerLevel;if(old<cap){relicXp[r.name]=(old+n).clamp(0,cap).toInt();}else if(relicMasteryUnlocked){relicMastery[r.name]=(relicMastery[r.name]??0)+n;}}
  void _rollRelicDrop(double chance){if(Random().nextDouble()>=chance)return;final locked=LegendaryRelic.values.where((r)=>!relicUnlocked(r)).toList();if(locked.isNotEmpty){final r=locked[Random().nextInt(locked.length)];unlockedRelicIds.add(r.name);relicXp[r.name]=0;activeRelicId??=r.name;message+=tr(" ⚜ Nalezen amulet: ${r.displayName}!", " ⚜ Amulet found: ${r.displayName}!");}else{addRelicXp(25);message+=tr(" ⚜ Duplikát převeden na 25 Amulet XP/Mastery.", " ⚜ Duplicate converted into 25 Amulet XP/Mastery.");}}
  double get relicDamageMult=>relicAt(LegendaryRelic.gladiatorCrest,1)?1.10:1.0;
  double get relicCritBonus=>relicAt(LegendaryRelic.gladiatorCrest,5)?0.10:0.0;
  double get relicHpMult=>relicAt(LegendaryRelic.bulwarkCore,1)?1.20:1.0;
  double get relicShieldMult=>relicAt(LegendaryRelic.bulwarkCore,5)?1.20:1.0;
  double get relicLifesteal=>relicAt(LegendaryRelic.soulReaper,1)?0.10:0.0;
  bool get relicExecute=>relicAt(LegendaryRelic.soulReaper,5);
  bool get relicKillHeal=>relicAt(LegendaryRelic.soulReaper,10);
  double get relicCooldownMult=>relicAt(LegendaryRelic.chronosSigil,10)?0.70:relicAt(LegendaryRelic.chronosSigil,5)?0.80:relicAt(LegendaryRelic.chronosSigil,1)?0.90:1.0;
  double get relicMasteryDamageMult=>1.0+(activeRelic==LegendaryRelic.gladiatorCrest?relicMasteryLevel(LegendaryRelic.gladiatorCrest)*0.001:0);
  double get relicMasteryCritBonus=>activeRelic==LegendaryRelic.gladiatorCrest?relicMasteryLevel(LegendaryRelic.gladiatorCrest)*0.0005:0;
  bool get gladiatorSetSynergy=>activeRelic==LegendaryRelic.gladiatorCrest&&activeHardcoreSetDef?.id=="warrior_berserk_hc";
  bool get bulwarkSetSynergy=>activeRelic==LegendaryRelic.bulwarkCore&&(activeHardcoreSetDef?.id=="warrior_ochrance_hc"||activeHardcoreSetDef?.id=="monk_skala_hc");
  bool get reaperSetSynergy=>activeRelic==LegendaryRelic.soulReaper&&activeHardcoreSetDef?.id=="dk_krev_hc";
  int get currentRiftSeasonNumber {final n=DateTime.now();return n.year*12+n.month;}
  RiftSeasonTheme get currentRiftSeason=>RiftSeasonTheme.values[currentRiftSeasonNumber%RiftSeasonTheme.values.length];
  double get seasonRewardMult=>currentRiftSeason==RiftSeasonTheme.chaos?1.5:1.0;
  // ===== WORLD BOSS: denně jeden boss převzatý z Lair poolu =====
  int worldBossHp=0,worldBossMaxHp=0,worldBossAtk=0,worldBossDef=0; String worldBossName="",worldBossAbility=""; bool isInWorldBoss=false; DateTime? lastWorldBossAttempt; int worldBossKills=0;
  bool worldBossAbilityUsed=false, worldBossSecondAbilityUsed=false, worldBossThirdAbilityUsed=false, worldBossFourthAbilityUsed=false;
  bool specRelicUsedWorldBoss=false;
  // Enrage: po worldBossEnrageThreshold kolech boss "zrudne" a jeho útok začne dál narůstat -
  // penalizuje přetahovaný fight, aby nešlo World Bosse jen vytankovat donekonečna.
  int worldBossRoundCount=0;
  static const int worldBossEnrageThreshold=25;
  bool get worldBossEnraged=>worldBossRoundCount>=worldBossEnrageThreshold;
  double get worldBossEnrageDmgMult=>worldBossEnraged?1+(worldBossRoundCount-worldBossEnrageThreshold+1)*.15:1.0;
  bool get worldBossUnlocked => level >= worldBossUnlockLevel;
  bool get worldBossAvailable {final n=DateTime.now(),d=lastWorldBossAttempt;return d==null||d.year!=n.year||d.month!=n.month||d.day!=n.day;}
  void enterWorldBoss(){
    if(level<10){message=tr("World Boss se odemyká na levelu 10 (aktuálně: level $level).", "World Boss unlocks at level 10 (currently: level $level).");notifyListeners();return;}
    if(!worldBossAvailable){message=tr("Dnešní World Boss už byl poražen.", "Today's World Boss has already been defeated.");notifyListeners();return;}
    final n=DateTime.now();
    final lairFloor=1+((n.year*372+n.month*31+n.day)%100);
    final b=getBossDetails(lairFloor);
    worldBossName="${b['name']} • World Boss";
    worldBossAbility=b['ability']!;
    final scale=pow(1.1,lairFloor-1).toDouble();
    worldBossMaxHp=(190*1.83*scale*100).toInt();
    worldBossHp=worldBossMaxHp;
    worldBossAtk=(8*1.6*scale*0.75).toInt();
    worldBossDef=(5*scale).toInt();
    worldBossRoundCount=0;
    hp=maxHp;
    isInWorldBoss=true;
    // lastWorldBossAttempt se NASTAVUJE až při skutečné výhře (viz _handleWorldBossDeath) - prohra
    // tě jen vyžene z boje, ale den ještě neztrácíš a můžeš to zkusit znovu, dokud bosse neporazíš.
    worldBossAbilityUsed=false;
    worldBossSecondAbilityUsed=false;
    worldBossThirdAbilityUsed=false;
    worldBossFourthAbilityUsed=false;
    specRelicUsedWorldBoss=false;
    huntersMarkStacks=0;
    arcaneChargeStacks=0;
    flowingChiStacks=0;
    henryTurnCounter=0;
    vexTurnCounter=0;
    fenwickTurnCounter=0;
    thorinTurnCounter=0;
    rawenTurnCounter=0;
    _resetResources();
    heroEffects.clear();
    enemyEffects.clear();
    message=tr("World Boss přichází: $worldBossName!", "The World Boss appears: $worldBossName!");
    notifyListeners();
  }
  void fightWorldBoss(){
    if(isDead||!isInWorldBoss)return;
    int dmg=classIsMagicAttack?magAtk:physAtk;
    final armorPen=runeEffect(RuneEffectType.armorPen);
    int effDef=armorPen>0?(worldBossDef*(1-armorPen)).clamp(0,double.infinity).toInt():worldBossDef;
    int dealtDmg=_minDmg(dmg,dmg-effDef);
    bool isCrit=nextAttackGuaranteedCrit||Random().nextDouble()<critChance;
    if(nextAttackGuaranteedCrit)nextAttackGuaranteedCrit=false;
    dealtDmg=(dealtDmg*basicAttackRoleMod).toInt();
    if(isCrit)dealtDmg=(dealtDmg*critDamageMultiplier).toInt();
    if(nextAttackDamageBoost){dealtDmg=(dealtDmg*1.1).toInt();nextAttackDamageBoost=false;}
    final bossDmgBonus=runeEffect(RuneEffectType.bossDamage);
    if(bossDmgBonus>0)dealtDmg=(dealtDmg*(1+bossDmgBonus)).toInt();
    dealtDmg=(dealtDmg*specializationBossDamageMod).toInt();
    message=isCrit?"💥 Kritický zásah! Způsobeno $dealtDmg poškození.":"World Boss: -$dealtDmg HP.";
    dealtDmg=_applyGemOffense(dealtDmg,enemyHp:worldBossHp,enemyMaxHp:worldBossMaxHp);
    worldBossHp-=dealtDmg;
    _applyKrevPassiveLifesteal(dealtDmg);
    if (worldBossHp > 0 && rollExtraAttack()) {
      message += tr(' ⚡ Extra Attack!', ' ⚡ Extra Attack!');
      _extraAttackInProgress = true;
      fightWorldBoss();
      _extraAttackInProgress = false;
      return;
    }
    _resolveWorldBossCombatRound();
  }
