    autoCombatEnabled = json["autoCombatEnabled"] as bool? ?? false;
    autoCombatSpeedLevel = (json["autoCombatSpeedLevel"] as num?)?.toInt().clamp(0, 10) ?? 0;
    pauseAutoBattleOnMerchant = json["pauseAutoBattleOnMerchant"] as bool? ?? true;
