    bankItems = (json["bankItems"] as List? ?? []).map((i) => Item.fromJson(Map<String, dynamic>.from(i as Map))).toList();
    bankUnlockedSlots = (json["bankUnlockedSlots"] as int? ?? bankStartingSlots).clamp(bankStartingSlots, bankMaxSize);
    bankGold = json["bankGold"] as int? ?? 0;
