    lairTierRewardClaims = Set<String>.from((json["lairTierRewardClaims"] as List?)?.map((e) => e.toString()) ?? const []);
    lairFloorTalentClaims = Set<String>.from((json["lairFloorTalentClaims"] as List?)?.map((e) => e.toString()) ?? const []);
    // Migrace starých save souborů (bez permanentLairTalentPoints) - dopočítá čítač zpětně
    // z délky lairFloorTalentClaims. Může v extrémně vzácném případě mírně nadhodnotit (pokud
    // hráč na jedné obtížnosti navštívil floor i PO dosažení stropu 100/obtížnost - ten floor se
    // do Setu zapíše, i když bod neudělil), ale je to nesrovnatelně přesnější než ztráta všech
    // natrvalo vydělaných bodů, ke které docházelo před touhle opravou při každé smrti.
    if (permanentLairTalentPoints < 0) {
      permanentLairTalentPoints = lairFloorTalentClaims.length;
      // Jednorázové doplacení: starý save mohl už projít smrtí, která bod bug (viz resetGame())
      // trvale smazal z talentPoints. Doplní jen SKUTEČNĚ chybějící rozdíl (level +
      // permanentLairTalentPoints vs. co má hráč aktuálně nerozdané + rozdané dohromady), ať
      // nikoho nadhodnotíme, pokud bod bug u něj vůbec nenastal (ještě neumřel).
      final int expectedTotal = level + permanentLairTalentPoints;
      final int currentlyAccountedFor = talentPoints + talents.values.fold<int>(0, (sum, v) => sum + v);
      if (expectedTotal > currentlyAccountedFor) {
        talentPoints += (expectedTotal - currentlyAccountedFor);
      }
    }
    // ===== Backfill V2 (jednorázově, viz lairTalentBackfillV2Done) =====
    // Bug: lairFloorTalentClaims byl zaveden AŽ POTÉ, co spousta hráčů měla už dávno poražené a
    // odměnu vyzvednuté desítky Lair pater (viz lairRewardClaims - ten existuje od začátku a
    // eviduje KAŽDÉ patro/obtížnost/prokletí, co kdy bylo skutečně poražené). Migrace výš z toho
    // počítala jen currentlyAccountedFor vs. lairFloorTalentClaims.length, ale lairFloorTalentClaims
    // byl v tu chvíli prázdný/neúplný pro všechny floory poražené PŘED zavedením funkce - takže
    // permanentLairTalentPoints zůstal nespravedlivě nízký (třeba 8 místo 52+, viz nahlášený bug).
    // Řešení: rozparsovat lairRewardKey ('floor_difficulty_curse') ze VŠECH lairRewardClaims,
    // sjednotit do lairFloorTalentClaims (union - nikdy nic needá pryč) a přepočítat
    // permanentLairTalentPoints z výsledku, s respektem ke stropu 100 bodů/obtížnost.
    if (!lairTalentBackfillV2Done) {
      lairTalentBackfillV2Done = true;
      for (final key in lairRewardClaims) {
        final parts = key.split('_');
        if (parts.length < 2) continue;
        final floor = int.tryParse(parts[0]);
        final diffKey = parts[1];
        if (floor == null || diffKey.isEmpty) continue;
        lairFloorTalentClaims.add('${floor}_$diffKey');
      }
      final Map<String, int> perDifficultyCount = {};
      for (final k in lairFloorTalentClaims) {
        final idx = k.indexOf('_');
        if (idx == -1) continue;
        final diffKey = k.substring(idx + 1);
        perDifficultyCount[diffKey] = (perDifficultyCount[diffKey] ?? 0) + 1;
      }
      int recalculated = 0;
      perDifficultyCount.forEach((_, v) { recalculated += min(v, 100); });
      if (recalculated > permanentLairTalentPoints) {
        final int delta = recalculated - permanentLairTalentPoints;
        permanentLairTalentPoints = recalculated;
        talentPoints += delta;
      }
    }
    towerFloorTalentClaims = Set<String>.from((json["towerFloorTalentClaims"] as List?)?.map((e) => e.toString()) ?? const []);
    // ===== Independent-cap fix (jednorázově, viz lairTalentIndependentCapFixDone) =====
    // Bug: floorTalentCapReachedForCurrentDifficulty (viz getter) dřív sčítal Lair+Tower dohromady
