        final diffKey = k.substring(idx + 1);
        perDifficultyLairCount[diffKey] = (perDifficultyLairCount[diffKey] ?? 0) + 1;
      }
      int recalculatedLair = 0;
      perDifficultyLairCount.forEach((_, v) { recalculatedLair += min(v, 100); });
      if (recalculatedLair > permanentLairTalentPoints) {
        final int delta = recalculatedLair - permanentLairTalentPoints;
        permanentLairTalentPoints = recalculatedLair;
        talentPoints += delta;
      }
    }
    lastSeenWorldTabLevel = json["lastSeenWorldTabLevel"] as int? ?? level; // legacy save = žádný falešný badge
    _soulsTabRevealedFlag = json["soulsTabRevealedFlag"] as bool? ?? false; // getter dorovná sama, pokud hráč crystals>0 už teď má
    ascensionLevel = json["ascensionLevel"] as int? ?? 0;
    ascensionPowerSquish = (json["ascensionPowerSquish"] as num?)?.toDouble() ?? 1.0;
    pekloFloor100Cleared = json["pekloFloor100Cleared"] as bool? ?? false;
    endlessScaleUnlocked = json["endlessScaleUnlocked"] as bool? ?? false;
    soulFragments = json["soulFragments"] as int? ?? 0;
    soulDemonKillCount = json["soulDemonKillCount"] as int? ?? 0;
    _syncAscensionLevel(); // pojistka pro staré/importované save, kde by ascensionLevel neodpovídal odemčeným vrstvám
    setSlotUpgradeLevels = Map<String, int>.from((json["setSlotUpgradeLevels"] as Map?)?.map((k, v) => MapEntry(k.toString(), (v as num).toInt())) ?? const {});
    ladder = (json["ladder"] as List? ?? []).map((l) => LadderEntry.fromJson(Map<String, dynamic>.from(l as Map))).toList();

    runeWizardUnlocked = json["runeWizardUnlocked"] as bool? ?? false;
    lairBoss15PlusKills = json["lairBoss15PlusKills"] as int? ?? 0;
    runeTalentPoints = json["runeTalentPoints"] as int? ?? 0;
    unlockedRuneNodeIds = Set<String>.from(json["unlockedRuneNodeIds"] as List? ?? []);
    runeLibrary = List<String>.from(json["runeLibrary"] as List? ?? []);
    weaponRuneSlots = (json["weaponRuneSlots"] as List?)?.map((e) => e as String?).toList() ?? [null, null, null];
    while (weaponRuneSlots.length < 3) {
      weaponRuneSlots.add(null);
    }
    artifactRuneSlots = (json["artifactRuneSlots"] as List?)?.map((e) => e as String?).toList() ?? [null, null, null, null];
    while (artifactRuneSlots.length < 4) {
      artifactRuneSlots.add(null);
    }
    runeStones = json["runeStones"] as int? ?? 0;
    masterRune = json["masterRune"] != null ? MasterRuneData.fromJson(Map<String, dynamic>.from(json["masterRune"] as Map)) : null;
    craftedArtifactWeaponIds = Set<String>.from(json["craftedArtifactWeaponIds"] as List? ?? const []);
    unlockedWeaponSkillNodeIds = Set<String>.from(json["unlockedWeaponSkillNodeIds"] as List? ?? const []);
    artifactMasterRune = json["artifactMasterRune"] != null ? MasterRuneData.fromJson(Map<String, dynamic>.from(json["artifactMasterRune"] as Map)) : null;
    arenaLeagueIndex = (json["arenaLeagueIndex"] as int? ?? 0).clamp(0, ArenaLeague.values.length - 1);
    arenaStars = json["arenaStars"] as int? ?? 0;
    arenaWins = json["arenaWins"] as int? ?? 0;
    specRelicLevels.clear(); final savedRelics=json["specRelicLevels"]; if(savedRelics is Map){savedRelics.forEach((k,v){if(v is num)specRelicLevels[k.toString()]=v.toInt().clamp(0,maxSpecRelicLevel);});}
    unlockedSpecRelics..clear()..addAll((json["unlockedSpecRelics"] as List? ?? const []).map((e)=>e.toString()));
    specRelicPityCounter.clear(); final savedPity=json["specRelicPityCounter"]; if(savedPity is Map){savedPity.forEach((k,v){if(v is num)specRelicPityCounter[k.toString()]=v.toInt();});}
    arenaLosses = json["arenaLosses"] as int? ?? 0;
    arenaLevelIndex = json["arenaLevelIndex"] as int? ?? 0;
    arenaIsGladiator = json["arenaIsGladiator"] as bool? ?? false;
    arenaRating = json["arenaRating"] as int? ?? 0;
    arenaCurrentSeasonNumber = json["arenaCurrentSeasonNumber"] as int? ?? -1;
    arenaSeasonTitleHistory = List<String>.from(json["arenaSeasonTitleHistory"] as List? ?? const []);
    arenaChestPending = json["arenaChestPending"] as bool? ?? false;
    arenaChestGold = json["arenaChestGold"] as int? ?? 0;
    arenaChestDust = json["arenaChestDust"] as int? ?? 0;
    arenaChestCrystals = json["arenaChestCrystals"] as int? ?? 0;
    arenaChestCoins = json["arenaChestCoins"] as int? ?? 0;
    arenaChestSetItemName = json["arenaChestSetItemName"] as String?;
    runicMasteryLevel = json["runicMasteryLevel"] as int? ?? 0;
    weeklyRuneBossKills = json["weeklyRuneBossKills"] as int? ?? 0;
    weeklyRuneBossTarget = json["weeklyRuneBossTarget"] as int? ?? 5;
    weeklyRuneQuestClaimed = json["weeklyRuneQuestClaimed"] as bool? ?? false;

    // Migrace pro staré save, které měly ascensionLevel odemčený ještě před přidáním
    // ascensionPowerSquish (takže ho _syncAscensionLevel výš nepřepočítal - ten reaguje jen na
    // PŘECHOD mezi vrstvami, a tady žádný nenastal, ascensionLevel byl už odemčený). Dopočítá se
    // to tady na konci, až jsou nahraný gear/talenty/rank (physAtk/magAtk teď dají správnou raw hodnotu).
    if (ascensionLevel >= 1 && ascensionPowerSquish == 1.0) {
      final double rawOffense = (classIsMagicAttack ? magAtk : physAtk).toDouble();
      final double targetOffense = _towerFloor1EnemyHp(ascensionLevel.clamp(1, 3)) / _ascensionTargetHits;
      if (rawOffense > 0 && targetOffense > 0) {
        ascensionPowerSquish = max(1.0, rawOffense / targetOffense);
      }
    }

    _fixLegacySpecRelicFallbackBug();
    _fixLegacyParagonMilestonesBug();
    _generateNextEnemy();
    _checkQuestResets(); // pokud uplynul den/týden od uložení, questy se hned obnoví
    _ensureMarketOffers(); // pokud uplynula hodina od uložení, featured nabídky se hned obnoví
    notifyListeners();
  }

  // Jednorázová oprava pro save soubory poškozené starým bugem v relicFor(): před opravou
  // vracel orElse fallback VŽDY warriorBerserkBanner bez ohledu na heroClass, takže hráči
  // jiných tříd si pod tímto klíčem mohli omylem odemknout/vylevelovat/nasadit Warrior relic
  // (typicky v období, kdy ještě neměli zvolenou specializaci). Pokud takový "osiřelý" progres
  // najdeme u non-warrior hrdiny, přesuneme ho na relic odpovídající jeho aktuální třídě/specializaci.
  // Jednorázová oprava pro save soubory poškozené starým bugem v _checkParagonMilestones(): smyčka
  // dřív porovnávala už-v-Paragon-jednotkách hodnotu zpátky násobenou 100, takže se
  // paragonCentMilestones plnil ~100x rychleji, než měl (Paragon 30 na jedné třídě = 30 falešných
  // záznamů místo 0) - a altCatchUpBonus tak byl enormně nafouklý. Přepočítáme Set od nuly čistě
  // z aktuálního nejvyššího Paragonu na účtu (jediný legitimní zdroj, viz oprava výš).
  void _fixLegacyParagonMilestonesBug() {
    final int correctHighestParagon = classRanks.isEmpty ? 0 : classRanks.values.reduce((a, b) => a > b ? a : b) ~/ 100;
    final Set<int> correctMilestones = {for (int m = 100; m <= correctHighestParagon; m += 100) m};
    if (paragonCentMilestones.length > correctMilestones.length) {
      paragonCentMilestones = correctMilestones;
    }
  }

  void _fixLegacySpecRelicFallbackBug() {
    if (heroClass == HeroClass.warrior || heroClass == HeroClass.none) return;
    const legacyKey = 'warriorBerserkBanner';
    final hasLegacyProgress = specRelicLevels.containsKey(legacyKey) ||
        unlockedSpecRelics.contains(legacyKey) ||
        inventory.any((i) => i.specRelicKey == legacyKey);
    if (!hasLegacyProgress) return;
    _migrateSpecRelicKey(legacyKey, currentSpecRelicKey);
  }

  // Vrátí true při úspěchu. Pokud shared_preferences není na dané platformě dostupný
  // (např. omezené sandboxové prostředí), hra pokračuje dál jen v paměti.
  Future<bool> saveGame() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(_saveKey, jsonEncode(toSaveJson()));
      return true;
    } catch (e) {
      return false;
    }
  }

  Future<bool> loadGame() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final jsonStr = prefs.getString(_saveKey);
      if (jsonStr == null) return false;
      loadFromSaveJson(jsonDecode(jsonStr) as Map<String, dynamic>);
      _refreshArtifactStats(); // Napraví staré artefakty zamrzlé na levelu z okamžiku vzniku.
      _computeOfflineProgress();
      _computeBankInterest();
      return true;
    } catch (e) {
      return false;
    }
  }

  // ===== EXPORT/IMPORT POSTUPU (textový kód) — "chudák cloud save" =====
  // Bez Google Play Games/Game Center (vyžadují nativní setup mimo tenhle soubor) nejde udělat
  // automatický cloud save. Tohle je ruční náhrada: hráč si zkopíruje textový kód (base64 JSON,
  // stejná data jako lokální save) a na jiném zařízení/po přeinstalaci ho vloží zpět. Není to
  // automatické, ale řeší to ztrátu postupu při výměně telefonu.
  String exportSaveCode() {
    final jsonStr = jsonEncode(toSaveJson());
    return base64Encode(utf8.encode(jsonStr));
  }

  // Vrací null při úspěchu, jinak chybovou hlášku k zobrazení hráči. Import je DESTRUKTIVNÍ
  // (přepíše aktuální postup) - UI musí před voláním získat potvrzení od hráče.
  Future<String?> importSaveCode(String code) async {
    try {
      final jsonStr = utf8.decode(base64Decode(code.trim()));
      final map = jsonDecode(jsonStr) as Map<String, dynamic>;
      loadFromSaveJson(map);
      _computeOfflineProgress();
      _computeBankInterest();
      await saveGame(); // hned přepiš i lokální save, ať import přežije zavření appky
      notifyListeners();
      return null;
    } catch (e) {
      return tr("Neplatný kód postupu. Zkontroluj, že jsi zkopíroval celý kód beze změny.",
          "Invalid progress code. Make sure you copied the whole code without changes.");
    }
  }

  // Skromný "vítej zpět" bonus - viz poznámka u polí výše. Počítá se jen jednou při načtení
  // (ne při každém tick), a jen pokud má hráč už vybranou třídu (jinak by to nedávalo smysl).
  void _computeOfflineProgress() {
    // Pokud už existuje nevyzvednutá odměna (hráč zavřel appku dřív, než si vybral normální/2×
    // za reklamu), nepřepočítávat znovu - jinak by se ztratila/změnila, zatímco čeká na volbu.
    if (pendingOfflineGold > 0 || pendingOfflineDust > 0) return;
    if (!offlineProgressUnlocked) return;
    if (lastActiveTimestamp == null || heroClass == HeroClass.none) return;
    final elapsed = DateTime.now().difference(lastActiveTimestamp!);
    if (elapsed.inMinutes < offlineMinMinutesToTrigger) return;
    final cappedMinutes = elapsed.inMinutes.clamp(0, offlineMaxHours * 60);
    final hours = cappedMinutes / 60.0;
    // ZTROJNÁSOBENO (viz offlineUnlockDeaths=1) a pak JEŠTĚ JEDNOU ZTROJNÁSOBENO (viz konverzace
    // "dej větší reward za afk *3") - dohromady tedy 9× základ. Zhlédnutí rewarded reklamy dá
    // navíc ještě jednou tolik (viz claimOfflineProgress(doubled:true)).
    final goldEarned = (hours * 9 * (20 + level * 0.5)).round();
    final dustEarned = (hours * 9 * (10 + level * 0.2)).round();
    if (goldEarned <= 0 && dustEarned <= 0) return;
    final wasCapped = elapsed.inMinutes > offlineMaxHours * 60;
    pendingOfflineGold = goldEarned;
    pendingOfflineDust = dustEarned;
    pendingOfflineDurationText = _formatOfflineDuration(elapsed, wasCapped);
  }

  // Vyzvedne čekající offline odměnu - normální (doubled:false), nebo zdvojnásobenou po
  // zhlédnutí rewarded reklamy (doubled:true). Skutečné přehrání reklamy řeší RewardedAdService
  // v UI, tahle metoda jen aplikuje odměnu, jakmile SDK potvrdí zhlédnutí (onUserEarnedReward).
  void claimOfflineProgress({required bool doubled}) {
    if (pendingOfflineGold <= 0 && pendingOfflineDust <= 0) return;
    final mult = doubled ? 2 : 1;
    final goldGained = pendingOfflineGold * mult;
    final dustGained = pendingOfflineDust * mult;
    gold += goldGained;
    magicDust += dustGained;
    pendingOfflineGold = 0;
    pendingOfflineDust = 0;
    pendingOfflineDurationText = null;
    message = doubled
        ? tr("🎬 Reklama dokoukána! Offline odměna zdvojnásobena: +$goldGained 🪙 a +$dustGained Dust.", "🎬 Ad watched! Offline reward doubled: +$goldGained 🪙 and +$dustGained Dust.")
        : tr("Offline odměna vyzvednuta: +$goldGained 🪙 a +$dustGained Dust.", "Offline reward claimed: +$goldGained 🪙 and +$dustGained Dust.");
    saveGame();
    notifyListeners();
  }

  String _formatOfflineDuration(Duration elapsed, bool wasCapped) {
    if (wasCapped) return tr("max. $offlineMaxHours h", "max. $offlineMaxHours h");
    final h = elapsed.inHours;
    final m = elapsed.inMinutes % 60;
    return h > 0 ? "${h}h ${m}m" : "${m}m";
  }

  Future<bool> hasSaveGame() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      return prefs.containsKey(_saveKey);
    } catch (e) {
      return false;
    }
  }

