  int get lairExtraEnrageRounds => max(0, lairCombatRoundCount - lairEnrageStartRound);
  double get lairEnrageDamageMult => 1.0 + min(1.0, lairExtraEnrageRounds * 0.05);
  double get lairSustainMult => !isInLair ? 1.0 : max(0.60, 1.0 - lairExtraEnrageRounds * 0.02);
  double get lairArmorIgnore => min(0.20, lairExtraEnrageRounds * 0.01);
  double get lairBlockPenalty => min(0.10, (lairExtraEnrageRounds ~/ 2) * 0.01);
