  // ===== RUNY OSUDOVÉ VOLBY — druhá záložka u Runového Čaroděje/Ma-Túše, odemyká se jednorázově
  // za Dust. Po odemčení se objeví mřížka 6 řádků × 3 sloupce - hráč zvolí PRÁVĚ JEDNU možnost
  // na řádek, ale každý řádek se musí nejdřív zvlášť odemknout za Krystaly (postupně, řádek po
  // řádku). Ceny řádků i konkrétní volby (co sloupce dělají) jsou zatím placeholdery - Ondřej
  // je doladí/navrhne, až bude UI hotové.
  static const int osudoveVolbyUnlockDustCost = 10000;
  static const int osudovaVolbaRowCount = 6;
  static const List<int> osudovaVolbaRowCosts = [5, 10, 20, 40, 80, 160]; // Krystaly, placeholder
  bool osudoveVolbyUnlocked = false;
  List<bool> osudovaVolbaRowUnlocked = List.filled(osudovaVolbaRowCount, false);
  // Volby jsou VÁZANÉ NA TŘÍDU - přepnutí class (viz "Zvolte si své povolání") teď ukáže volby
  // TÉ třídy, ne globálně poslední zvolené (dřív např. Mnich viděl volby zvolené na Nekromantovi).
  // Odemčení řádků (osudovaVolbaRowUnlocked) a záložky (osudoveVolbyUnlocked) zůstává globální -
  // zaplatil jsi jednou za rámec, ale co si v něm která třída vybere, je čistě její věc.
  Map<String, List<int>> osudovaVolbaChoicePerClass = {};
  List<int> get osudovaVolbaChoice => osudovaVolbaChoicePerClass.putIfAbsent(heroClass.name, () => List.filled(osudovaVolbaRowCount, -1));

  void unlockOsudoveVolby() {
    if (osudoveVolbyUnlocked) return;
    if (magicDust < osudoveVolbyUnlockDustCost) {
      message = tr("Nedostatek Magického prachu ($magicDust/$osudoveVolbyUnlockDustCost).", "Not enough Magic Dust ($magicDust/$osudoveVolbyUnlockDustCost).");
      notifyListeners();
      return;
    }
    magicDust -= osudoveVolbyUnlockDustCost;
    osudoveVolbyUnlocked = true;
    message = tr("Runy osudové volby odemčeny! Ma-Túš ti teď může nabídnout své volby.", "Runes of Fate unlocked! Ma-Túš can now offer you his choices.");
    notifyListeners();
  }

  // Řádky se odemykají POSTUPNĚ (řádek N vyžaduje odemčený řádek N-1) - konzistentní s rostoucí
  // cenou (5/10/20/40/...), ať dává smysl postupovat odshora dolů.
  void unlockOsudovaVolbaRow(int row) {
    if (!osudoveVolbyUnlocked || row < 0 || row >= osudovaVolbaRowCount) return;
    if (osudovaVolbaRowUnlocked[row]) return;
    if (row > 0 && !osudovaVolbaRowUnlocked[row - 1]) {
      message = tr("Nejdřív odemkni řádek ${row}.", "Unlock row $row first.");
      notifyListeners();
      return;
    }
    final cost = osudovaVolbaRowCosts[row];
    if (crystals < cost) {
      message = tr("Nedostatek Krystalů ($crystals/$cost).", "Not enough Crystals ($crystals/$cost).");
      notifyListeners();
      return;
    }
    crystals -= cost;
    osudovaVolbaRowUnlocked[row] = true;
    message = tr("Řádek ${row + 1} osudové volby odemčen!", "Row ${row + 1} of the Fate Choice unlocked!");
    notifyListeners();
  }

  static const int osudovaVolbaChangeCost = 5000; // změna JIŽ zvolené volby (ne první volba) stojí Zlato
  void chooseOsudovaVolba(int row, int col) {
    if (row < 0 || row >= osudovaVolbaRowCount || col < 0 || col > 2) return;
    if (!osudovaVolbaRowUnlocked[row]) return;
    final current = osudovaVolbaChoice[row];
    if (current == col) return; // už zvoleno, není co dělat
    if (current != -1) {
      // Přehození JIŽ zvolené volby na jinou - první volba v řádku je vždy zdarma, tohle je změna.
      if (gold < osudovaVolbaChangeCost) {
        message = tr("Nedostatek Zlata na změnu volby ($gold/$osudovaVolbaChangeCost).", "Not enough Gold to change your choice ($gold/$osudovaVolbaChangeCost).");
        notifyListeners();
        return;
      }
      gold -= osudovaVolbaChangeCost;
      message = tr("Volba v řádku ${row + 1} změněna za $osudovaVolbaChangeCost 🪙.", "Choice in row ${row + 1} changed for $osudovaVolbaChangeCost 🪙.");
    } else {
      message = tr("Volba v řádku ${row + 1} nastavena.", "Choice in row ${row + 1} set.");
    }
    osudovaVolbaChoice[row] = col;
    notifyListeners();
  }

  int hardcoreTier = 1; // Roste s každým Lair 100 clearem v Hardcore s aktivním prokletím - škáluje obtížnost dál.
  bool pekloFloor100Cleared = false; // true po prvním poražení bosse na patře 100 v aktivním Peklo módu - odemyká 4. Ascend + Endless Scale.

  // ===== ASCENSION (Prestige/Squish smyčka) =====
  // 0 = Normal, 1 = po prvním odemčení Hardcore, 2 = po odemčení Předpeklí, 3 = po odemčení
  // Peklo, 4 = po dokončení Pekla (odemyká Endless Scale). Level je natvrdo capnutý na 4 -
  // dál se neroste, místo toho pokračuje Endless Scale (Soul Demon).
  // Účel: squish se dělá NA OBOU STRANÁCH (hráč i enemy), ale s jiným pravidlem:
  //  - Enemy (ascensionSquishDivisor): nová vrstva MUSÍ být silnější než maximum staré vrstvy -
  //    patro 1 Hardcore silnější než patro 100 Normal, patro 1 Předpeklí silnější než patro 100
  //    Hardcore, atd. (s marží _ascensionLayerMargin). Stejné pravidlo platí pro Lair (sdílí
  //    tenhle getter).
  //  - Hráč (ascensionPowerSquish): NENÍ to pevný násobič vázaný na ascensionLevel (×1.5/2.5/3.0)
  //    - to nestačilo, protože hráč s hodně nafarmeným gearem zůstal i po ÷1.5 tak silný, že
  //    zabíjel patro 1 nové vrstvy jedním-dvěma zásahy. Místo toho se při KAŽDÉM odemčení nové
  //    vrstvy udělá snapshot hráčovy AKTUÁLNÍ (nesquishnuté) síly a spočítá se přesně takový
  //    poměr, aby útok na patře 1 nové vrstvy trval přiměřený počet zásahů (_ascensionTargetHits) -
  //    viz _syncAscensionLevel. Čím víc byl hráč před odemčením přerostlý, tím tvrději ho to srazí.
  int ascensionLevel = 0;
  double ascensionPowerSquish = 1.0; // dělí physAtk/magAtk/maxHp/armor, viz _syncAscensionLevel

  // Bezpečnostní marže: nová vrstva musí být SILNĚJŠÍ než maximum staré vrstvy, ne jen stejně silná.
  static const double _ascensionLayerMargin = 1.1;
  // Kolik zásahů běžným útokem by mělo přibližně stačit na zabití běžného nepřítele na patře 1
  // nové vrstvy, hned po odemčení (než hráč znovu nafarmí gear a bude to rychlejší).
  static const double _ascensionTargetHits = 8.0;

  double get ascensionSquishDivisor => _ascensionSquishDivisorFor(ascensionLevel);

  // BUG FIX: ascensionSquishDivisor (nahoře) je vázaný na `ascensionLevel` - nejvyšší kdy
  // odemčenou vrstvu, ne na vrstvu, ve které se PRÁVĚ bojuje. Tower/Lair/Rift ho ale dřív
  // aplikovaly nepodmíněně na `mult` bez ohledu na aktuální obtížnost (viz `mult /=
  // ascensionSquishDivisor` v _generateNextEnemy/fightLairBoss/generateRift...) - takže i boj na
  // čistém Normal (atLeastHardcore == false) dostal vydělený tím samým mikroskopickým číslem
  // kalibrovaným pro Peklo, což enemy mult nafouklo o řády (patro 1 Normal vypadalo jako by
  // mělo sílu patra 100 Pekla). Tenhle getter vrátí divisor jen pro vrstvu, ve které se PRÁVĚ
  // bojuje (0 = Normal = beze změny, 1 = Hardcore, 2 = Předpeklí, 3 = Peklo) - to je jediné
  // správné místo, odkud se má squish na enemy stranu aplikovat.
  double get currentFightAscensionSquishDivisor {
    int lvl = 0;
    if (pekloMode && pekloUnlocked) lvl = 3;
    else if (atLeastPredpekli && predpekliUnlocked) lvl = 2;
    else if (atLeastHardcore) lvl = 1;
    return _ascensionSquishDivisorFor(lvl);
  }

  double _ascensionSquishDivisorFor(int level) {
    if (level <= 0) return 1.0;
    // Stejná křivka jako Tower/Lair (mult = 1.1^(floor-1)), patro 100 = poslední patro vrstvy.
    final double floor100Growth = pow(1.1, 99).toDouble();
    double ownMult = 1.0; // kumulativní vlastní násobič vrstvy (BEZ hardcoreFactor - ten je
    // společný oběma stranám srovnání od Hardcore výš, takže se v poměru vykrátí a nerovnost
    // platí navždy, ne jen v okamžiku odemčení; u Normal->Hardcore přechodu srovnání navíc
    // hardcoreFactor ignoruje úplně, což dává extra marži zdarma, protože HC ho má vždycky navíc).
    double divisor = 1.0;
    double prevLayerFloor100 = floor100Growth; // Normal patro 100 (own mult = 1.0)
    for (int lvl = 1; lvl <= level && lvl <= 3; lvl++) {
      // BUG FIX (viz konverzace - "nemůžu porazit prvního hardcore bosse ani na Paragon 37"):
      // lvl==2/3 násobí ownMult svým vlastním vstupním difficulty multem (predpekli/peklo), ale
      // lvl==1 dřív NEnásobil ničím - přitom skutečný boj (_generateNextEnemy/fightLairBoss)
      // navíc VŽDY násobí (1.0 + 0.5*hardcoreTier), a hardcoreTier je při prvním vstupu do
      // Hardcore vždycky aspoň 1. Bez týhle řádky tak přechod Normal→Hardcore vycházel na 1.65×
      // (marže 1.1× × zapomenutý 1.5× hardcoreTier faktor) místo zamýšlené 1.1× marže - jediný
      // ze tří přechodů, co byl mimo plán, a zrovna ten úplně první, na co hráč narazí.
      if (lvl == 1) ownMult *= 1.5; // baseline (1.0 + 0.5 * hardcoreTier) při hardcoreTier == 1
      if (lvl == 2) ownMult *= predpekliDifficultyMult;
      if (lvl == 3) ownMult *= pekloDifficultyMult;
      divisor = ownMult / (_ascensionLayerMargin * prevLayerFloor100);
      prevLayerFloor100 = (ownMult / divisor) * floor100Growth; // téhle vrstvy patro 100, pro další iteraci
    }
    return divisor;
  }

  // HP běžného nepřítele na patře 1 dané ascension vrstvy s aktuálním hardcoreTier (stejný vzorec
  // jako _generateNextEnemy) - používá se jako cíl pro ascensionPowerSquish snapshot.
  double _towerFloor1EnemyHp(int level) {
    double mult = 1.0; // 1.1^(1-1)
    if (level >= 1) mult *= (1.0 + 0.5 * hardcoreTier);
    if (level >= 2) mult *= predpekliDifficultyMult;
    if (level >= 3) mult *= pekloDifficultyMult;
    mult /= _ascensionSquishDivisorFor(level);
    return 100 * mult;
  }



  // ===== PŘEDPEKLÍ — nová úroveň obtížnosti nad Hardcore =====
  // Odemyká se po dosažení hardcoreTier 5 (= 5× dokončený Hardcore Lair 100 + prokletí loop).
  // Vyžaduje aktivní Hardcore Mode. Přidává další násobnou vrstvu obtížnosti (×2.5) navrch
  // veškerého Hardcore škálování, a odměna se zvyšuje úměrně (+100 % gold/dust/crystal, +2 % loot).
  static const int predpekliUnlockHardcoreTier = 5;
  bool get predpekliUnlocked => hardcoreTier >= predpekliUnlockHardcoreTier;
  bool predpekliMode = false; // permanentní přepínač, nereseuje se smrtí (jako hardcoreMode)
  static const double predpekliDifficultyMult = 2.5;
  static const double predpekliRewardBonus = 1.0; // +100 % navrch k normální/curse odměně
  static const double predpekliLootBonus = 0.02; // +2 % loot chance navrch

  // ===== PEKLO — nová úroveň obtížnosti nad Předpeklí =====
  // Odemyká se po dosažení hardcoreTier 10 (dvojnásobek Předpeklí prahu). Vyžaduje aktivní
  // Předpeklí. Přidává další násobnou vrstvu obtížnosti (×3.0) navrch VŠECH předchozích vrstev
  // (Hardcore × Předpeklí × Peklo), odměna roste úměrně (+150 % gold/dust/xp, +3 % loot).
  static const int pekloUnlockHardcoreTier = 10;
  bool get pekloUnlocked => hardcoreTier >= pekloUnlockHardcoreTier;
  bool pekloMode = false; // permanentní přepínač, nereseuje se smrtí
  static const double pekloDifficultyMult = 3.0;
  static const double pekloRewardBonus = 1.5; // +150 % navrch k normální/curse/Předpeklí odměně
  static const double pekloLootBonus = 0.03; // +3 % loot chance navrch

  // ===== ENDLESS SCALE — Soul Demon (capstone farm boss po dokončení Pekla) =====
  bool endlessScaleUnlocked = false; // odemyká se dokončením Pekla (ascensionLevel dosáhne 4)
  bool isInEndlessScale = false;
  int soulFragments = 0; // nová měna, jen za Soul Demon killy
  int soulDemonKillCount = 0; // roste o 1 za kill; HP/Armor rostou +10 % kumulativně za kill
  int soulDemonHp = 0;
  int soulDemonMaxHp = 0;
  int soulDemonAtk = 0;
  int soulDemonArmor = 0;
  int soulDemonRoundCount = 0; // pro CD spellů + pasivku (Démonův hněv, +1 %dmg/kolo)
  int soulDemonSpell1Cd = 0; // Pohlcení duše (CD 2)
  int soulDemonSpell2Cd = 0; // Řetězy zatracených (CD 4)
  int soulDemonSpell3Cd = 0; // Křik ztracených duší (CD 5)
  int soulDemonSpell4Cd = 0; // Vyrvání duše (CD 20)
  // Hrdinovy VLASTNÍ schopnosti (Runová trhlina/Prokletý úder/Exploze prokletí/Úder smrti apod.)
  // v Endless Scale - zrcadlí lairAbilityUsed/lairSecondAbilityUsed/... (viz useLairActiveAbility),
  // ale samostatné, aby boj v Endless Scale nesdílel cooldowny s Lairem.
  bool endlessScaleAbilityUsed = false;
  bool endlessScaleSecondAbilityUsed = false;
  bool endlessScaleThirdAbilityUsed = false;
  bool endlessScaleFourthAbilityUsed = false;

  // Hardcore/Předpeklí/Peklo jsou EXKLUZIVNÍ volba obtížnosti (jen jeden z hardcoreMode/predpekliMode/
  // pekloMode je true zaráz) - ne stackovatelné vrstvy. Tyhle gettery ale zachovávají "tahle obtížnost
  // nebo vyšší" sémantiku pro škálování/odměny, takže Předpeklí a Peklo pořád těží ze všeho, co dřív
  // dávalo aktivní Hardcore (jen bez nutnosti mít hardcoreMode doslova zapnuté zároveň).
  bool get atLeastHardcore => hardcoreMode || predpekliMode || pekloMode;
  bool get atLeastPredpekli => predpekliMode || pekloMode;
  // 0=Normal, 1=Hardcore, 2=Předpeklí, 3=Peklo.
  int get difficultyTier => pekloMode ? 3 : (predpekliMode ? 2 : (hardcoreMode ? 1 : 0));

  // XP penalta za "outlevelnutou" obtížnost - motivuje hráče postupovat na vyšší tier místo
  // grindění XP na už příliš snadné obtížnosti. Peklo (tier 3, endgame) penaltu nemá, protože
  // není kam dál postoupit.
  double get xpDifficultyPenalty {
    switch (difficultyTier) {
      case 0: return level >= 30 ? 0.10 : 1.0; // Normal: -90 % XP od levelu 30
      case 1: return level >= 60 ? 0.10 : 1.0; // Hardcore: -90 % XP od levelu 60
      case 2: return level >= 90 ? 0.10 : 1.0; // Předpeklí: -90 % XP od levelu 90
      default: return 1.0; // Peklo bez penalty
    }
  }

  // Jed (curse): stackovatelná intenzita na hrdinovi - další aplikace neprodlouží trvání, jen zesílí dmg/kolo.
  int poisonStacks = 0;
  // Oživení padlých (curse): aktuální Tower nepřítel se může oživit jen jednou.
  bool currentEnemyRevived = false;
  // Roztříštění (curse): fronta "úlomků" po smrti Tower nepřítele - další 2 slabší souboje před další floor.
  int pendingFragments = 0;
  int fragmentAtk = 0;
  int fragmentDef = 0;
  int fragmentMaxHp = 0;
  bool fragmentIsMagical = false;
  bool currentEnemyIsFragment = false;

  // ===== ACHIEVEMENTY =====
  Set<AchievementId> unlockedAchievements = {};
  AchievementId? activeTitle; // vybraný kosmetický titul zobrazený v Profilu (musí být odemčený)
  Set<String> everRecruitedCompanions = {}; // celoživotní historie (max 2 aktivních najednou, ale takhle jde sledovat "vyzkoušel jsi všechny")

  // ===== BATTLE PASS =====
  // 30denní sezóna, resetuje se automaticky (viz _checkBattlePassReset). Renown se získává za
  // splnění denních/týdenních/měsíčních questů (viz _checkQuests) - 10/30/100 za splnění.
  // battlePassLevel je odvozený getter z renown, ne samostatně uložený stav.
  static const int battlePassMaxLevel = 40;
  static const int battlePassRenownPerLevel = 45;
  static const int battlePassSeasonDays = 30;
  static const int battlePassPremiumCost = 500; // krystaly za odemčení prémiové větve na sezónu
  int battlePassRenown = 0;
  DateTime? battlePassSeasonStart;
  bool battlePassPremium = false;
  Set<int> battlePassFreeClaimed = {};
  Set<int> battlePassPremiumClaimed = {};

  // ===== KOSMETIKA (rám portrétu + skin základního útoku + aura) =====
  // Odemyká se přes Battle Pass NEBO přes obchod (viz kCosmeticShopCatalog/buyCosmetic), trvalé -
  // nereseuje se sezónou ani smrtí. 'default' je vždycky odemčený a je to i výchozí nasazený.
  Set<String> unlockedFrames = {'default'};
  String equippedFrame = 'default';
  Set<String> unlockedAttackSkins = {'default'};
  String equippedAttackSkin = 'default';
  // Zvýší se při KAŽDÉM základním útoku (fight()) - manuálním i auto-boj tiku - bez ohledu na
  // třídu/typ útoku. UI (viz _BasicAttackSkinOverlay) na tohle poslouchá a přehraje krátký burst
  // v barvě nasazeného skinu základního útoku. Dřív skin neměl vůbec žádný háček, kde by se
  // při základním útoku zobrazil - fungoval jen jako popisek v obchodě/paint na ikoně tlačítka,
  // ale při skutečném zásahu se nic nepřebarvilo (skin se aplikoval jen na SpellFx tier1-4
  // schopnosti, ne na základní útok - viz konverzace).
  int basicAttackFxSeq = 0;
  // Aura - jemný barevný glow/částice kolem portrétu hrdiny v combat kartě (Věž/Lair) - nová
  // kategorie kosmetiky, na rozdíl od rámů/skinů se dá koupit JEN v obchodě, ne přes Battle Pass.
  Set<String> unlockedAuras = {'default'};
  String equippedAura = 'default';
  // Skin tlačítek spellů - barva tlačítka + barva záře + ikona, co nahradí ikonu KAŽDÉHO ability
  // tlačítka (základní útok, tier1-4, relic) napříč všemi bojovými obrazovkami. Na rozdíl od
  // skinu základního útoku (ten jen přidává efekt PŘI zásahu) tenhle mění, jak tlačítka vypadají
  // permanentně, dokud je boj otevřený - viz kButtonSkinStyles a SpellIconButton.
  Set<String> unlockedButtonSkins = {'default'};
  String equippedButtonSkin = 'default';
  // Pozadí karty (uvnitř rámu portrétu v boji) - nezávislé na barvě třídy. 'default' = staré
  // chování (pozadí odvozené z heroAccent).
  Set<String> unlockedCardBackgrounds = {'default'};
  String equippedCardBackground = 'default';

  void equipCardBackground(String id) {
    if (!unlockedCardBackgrounds.contains(id)) return;
    equippedCardBackground = id;
    notifyListeners();
  }

  Color? get equippedCardBackgroundColor {
    if (equippedCardBackground == 'default') return null;
    if (equippedCardBackground.startsWith('bp_') || equippedCardBackground.startsWith('rift_universal_')) {
      return bpRiftCosmeticColor(equippedCardBackground);
    }
    for (final c in kCosmeticShopCatalog) {
      if (c.id == equippedCardBackground) return c.accent;
    }
    return null;
  }
  // Ruční volba PO JEDNOTLIVÝCH SLOTECH (viz konverzace: "meč pro spell 1, kapka pro spell 2,
  // každý svojí barvou") - klíč je 'basicAttack'/'tier1'/'tier2'/'tier3'/'tier4'/'relic' (viz
  // SpellVisual.slotKey). Nezávislé na equippedButtonSkin výš a má PŘEDNOST před ním, pokud je
  // pro daný slot nastavená - prázdný/chybějící klíč = spadá zpět na equippedButtonSkin, nebo
  // na vlastní vzhled spellu, pokud není nasazený ani ten. Uloženo jako String (enum name), ne
  // přímo _SpecAccent, ať to jde triviálně serializovat do JSON.
  Map<String, String> customSlotIcon = {};
  Map<String, int> customSlotButtonColor = {};
  Map<String, int> customSlotGlowColor = {};
  // Odemykání SAMOTNÝCH symbolů/barev pro picker výš (viz konverzace: "každá ikona a každá
  // barva se musí odemknout") - odděleno od toho, co si hráč zrovna NASADIL do daného slotu
  // (customSlotIcon/Color výš). 'default'/'Výchozí' jsou vždycky odemčené zdarma. Zbytek
  // symbolů a 14 z 18 barev jde koupit za Jiskry (viz unlockButtonIconWithSparks/
  // unlockButtonColorWithSparks) - zbylé 4 barvy (Bílá/Červená/Oranžová/Černá) NEJDOU koupit,
  // jen je dá odemknutí Ascension I-IV (viz achievementOnlyButtonColors a _unlockAchievement).
  Set<String> unlockedButtonIcons = {'default'};
  Set<String> unlockedButtonColorNames = {'Výchozí'};
  static const int buttonIconUnlockPrice = 20;
  static const int buttonColorUnlockPrice = 15;
  // Tyhle 4 barvy jsou vyhrazené pro achievementy (Ascension I-IV) - i kdyby měl hráč dost
  // Jisker, nejdou koupit v pickeru, jen se zobrazí požadavek na achievement.
  static const Set<String> achievementOnlyButtonColors = {'Bílá', 'Červená', 'Oranžová', 'Černá'};

  bool isButtonIconUnlocked(String accentName) => accentName == 'default' || unlockedButtonIcons.contains(accentName);
  bool isButtonColorUnlocked(String colorName) => colorName == 'Výchozí' || unlockedButtonColorNames.contains(colorName);

  void unlockButtonIconWithSparks(String accentName) {
    if (isButtonIconUnlocked(accentName)) return;
    if (cosmeticSparks < buttonIconUnlockPrice) {
      message = tr("Nedostatek Jisker (potřeba: $buttonIconUnlockPrice ✦).", "Not enough Sparks (need: $buttonIconUnlockPrice ✦).");
      notifyListeners();
      return;
    }
    cosmeticSparks -= buttonIconUnlockPrice;
    unlockedButtonIcons.add(accentName);
    message = tr("✨ Symbol odemčen!", "✨ Symbol unlocked!");
    notifyListeners();
  }

  void unlockButtonColorWithSparks(String colorName) {
    if (isButtonColorUnlocked(colorName)) return;
    if (achievementOnlyButtonColors.contains(colorName)) {
      message = tr("Tuhle barvu odemkne jen achievement Ascension.", "This color only unlocks via the Ascension achievement.");
      notifyListeners();
      return;
    }
    if (cosmeticSparks < buttonColorUnlockPrice) {
      message = tr("Nedostatek Jisker (potřeba: $buttonColorUnlockPrice ✦).", "Not enough Sparks (need: $buttonColorUnlockPrice ✦).");
      notifyListeners();
      return;
    }
    cosmeticSparks -= buttonColorUnlockPrice;
    unlockedButtonColorNames.add(colorName);
    message = tr("✨ Barva odemčena!", "✨ Color unlocked!");
    notifyListeners();
  }

  void setCustomSlotIcon(String slot, _SpecAccent? accent) {
    if (accent == null) {
      customSlotIcon.remove(slot);
    } else {
      customSlotIcon[slot] = accent.name;
    }
    notifyListeners();
  }

  void setCustomSlotButtonColor(String slot, Color? color) {
    if (color == null) {
      customSlotButtonColor.remove(slot);
    } else {
      customSlotButtonColor[slot] = color.value;
    }
    notifyListeners();
  }

  void setCustomSlotGlowColor(String slot, Color? color) {
    if (color == null) {
      customSlotGlowColor.remove(slot);
    } else {
      customSlotGlowColor[slot] = color.value;
    }
    notifyListeners();
  }

  _SpecAccent? customSlotIconFor(String? slot) {
    if (slot == null) return null;
    final name = customSlotIcon[slot];
    if (name == null) return null;
    for (final a in _SpecAccent.values) {
      if (a.name == name) return a;
    }
    return null;
  }

  Color? customSlotButtonColorFor(String? slot) => slot != null && customSlotButtonColor.containsKey(slot) ? Color(customSlotButtonColor[slot]!) : null;
  Color? customSlotGlowColorFor(String? slot) => slot != null && customSlotGlowColor.containsKey(slot) ? Color(customSlotGlowColor[slot]!) : null;

  void equipFrame(String id) {
    if (!unlockedFrames.contains(id)) return;
    equippedFrame = id;
    notifyListeners();
  }

  void equipAttackSkin(String id) {
    if (!unlockedAttackSkins.contains(id)) return;
    equippedAttackSkin = id;
    notifyListeners();
  }

  void equipAura(String id) {
    if (!unlockedAuras.contains(id)) return;
    equippedAura = id;
    notifyListeners();
  }

  void equipButtonSkin(String id) {
    if (!unlockedButtonSkins.contains(id)) return;
    equippedButtonSkin = id;
    notifyListeners();
  }

  // Barva aktuálně nasazené aury (viz CustomizationScreen/kCosmeticShopCatalog), nebo null,
  // pokud hráč nemá žádnou nasazenou - používá combat karta Věže/Lairu pro glow kolem portrétu.
  Color? get equippedAuraColor {
    if (equippedAura == 'default') return null;
    if (equippedAura.startsWith('bp_') || equippedAura.startsWith('rift_universal_')) {
      return bpRiftCosmeticColor(equippedAura);
    }
    for (final c in kCosmeticShopCatalog) {
      if (c.id == equippedAura) return c.accent;
    }
    return null;
  }

  // Koupí kosmetický předmět z kCosmeticShopCatalog za zlato nebo krystaly (podle toho, co má
  // item nastavené - viz CosmeticShopItem). Položky s isPremiumOnly (real-cash) se přes tuhle
  // metodu koupit nedají - viz onTap v obchodě, který u nich místo nákupu jen ukáže zprávu.
  void buyCosmetic(String id) {
    final item = kCosmeticShopCatalog.firstWhere((c) => c.id == id, orElse: () => throw StateError('unknown cosmetic $id'));
    if (item.isPremiumOnly) return;
    final owned = switch (item.category) {
      CosmeticCategory.frame => unlockedFrames.contains(id),
      CosmeticCategory.attackSkin => unlockedAttackSkins.contains(id),
      CosmeticCategory.aura => unlockedAuras.contains(id),
      CosmeticCategory.buttonSkin => unlockedButtonSkins.contains(id),
      CosmeticCategory.cardBackground => unlockedCardBackgrounds.contains(id),
    };
    if (owned) return;
    if (cosmeticSparks < item.sparkPrice) {
      message = tr("Nedostatek Jisker (potřeba: ${item.sparkPrice} ✦).", "Not enough Sparks (need: ${item.sparkPrice} ✦).");
      notifyListeners();
      return;
    }
    cosmeticSparks -= item.sparkPrice;
    switch (item.category) {
      case CosmeticCategory.frame: unlockedFrames.add(id);
      case CosmeticCategory.attackSkin: unlockedAttackSkins.add(id);
      case CosmeticCategory.aura: unlockedAuras.add(id);
      case CosmeticCategory.buttonSkin: unlockedButtonSkins.add(id);
      case CosmeticCategory.cardBackground: unlockedCardBackgrounds.add(id);
    }
    message = tr("✨ Koupeno: ${item.name}!", "✨ Purchased: ${item.name}!");
    _checkAchievements();
    notifyListeners();
  }

  int get battlePassLevel => (battlePassRenown / battlePassRenownPerLevel).floor().clamp(0, battlePassMaxLevel);
  int get battlePassRenownIntoLevel => battlePassRenown - battlePassLevel * battlePassRenownPerLevel;
  int get battlePassRenownForNextLevel => battlePassLevel >= battlePassMaxLevel ? 0 : battlePassRenownPerLevel;
  int get battlePassDaysLeft {
    if (battlePassSeasonStart == null) return battlePassSeasonDays;
    final elapsed = DateTime.now().difference(battlePassSeasonStart!).inDays;
    return (battlePassSeasonDays - elapsed).clamp(0, battlePassSeasonDays);
  }

  bool get battlePassHasUnclaimedRewards {
    for (int l = 1; l <= battlePassLevel; l++) {
      if (!battlePassFreeClaimed.contains(l)) return true;
      if (battlePassPremium && !battlePassPremiumClaimed.contains(l)) return true;
    }
    return false;
  }

  void _checkBattlePassReset() {
    final now = DateTime.now();
    if (battlePassSeasonStart == null) {
      battlePassSeasonStart = now;
      return;
    }
    if (now.difference(battlePassSeasonStart!).inDays >= battlePassSeasonDays) {
      battlePassRenown = 0;
      battlePassPremium = false;
      battlePassFreeClaimed = {};
      battlePassPremiumClaimed = {};
      battlePassSeasonStart = now;
      message = tr('🎖️ Nová sezóna Battle Passu právě začala!', '🎖️ A new Battle Pass season has just begun!');
    }
  }

  void _addBattlePassRenown(int amount) {
    if (amount <= 0) return;
    // Trvalý pasivní bonus Premium (viz battlePassRewardFor level 1) - +20 % Quest XP, dokud
    // má hráč Premium aktivní. Není to jednorázová odměna, funguje automaticky pořád.
    if (battlePassPremium) amount = (amount * 1.2).round();
    battlePassRenown = (battlePassRenown + amount).clamp(0, battlePassMaxLevel * battlePassRenownPerLevel);
  }

  // Procedurální odměnová křivka - free větev dává hlavně Zlato/Dust s malou ochutnávkou
  // krystalů co 5 úrovní; prémiová větev škáluje výš a co 10 úrovní přidá větší balík krystalů,
  // poslední úroveň (battlePassMaxLevel) má navrch velký bonus. Na každém 5. levelu (obě větve)
  // je odměna navíc "Truhla" - bonusový balíček navrch běžné odměny, v UI zobrazený ikonou
  // truhly místo běžných ikon. Level 40 navíc odemyká kosmetiku: free = rám portrétu, premium =
  // skin základního útoku (obě varianty, fyzická i magická - viz cosmeticAttackSkinId výš).
  BattlePassReward battlePassRewardFor(int level, bool premium) {
    final bool isChestLevel = level % 5 == 0;
    final bool isMaxLevel = level == battlePassMaxLevel;
    if (!premium) {
      int crystals = level % 5 == 0 ? 5 : 0;
      int gold = 40 * level;
      int dust = 25 * level;
      if (isChestLevel) {
        gold += 30 * level;
        dust += 20 * level;
        crystals += 10;
      }
      return BattlePassReward(
        gold: gold, dust: dust, crystals: crystals, premium: false, level: level,
        isChest: isChestLevel,
        cosmeticFrameId: isMaxLevel ? 'battlepass_frame' : null,
      );
    }
    int crystals = 8 + level * 2 + (level % 10 == 0 ? 40 : 0);
    int gold = 100 * level;
    int dust = 70 * level;
    if (isChestLevel) {
      gold += 60 * level;
      dust += 40 * level;
      crystals += 20;
    }
    if (isMaxLevel) {
      crystals += 150;
      gold += 3000;
      dust += 2000;
    }
    return BattlePassReward(
      gold: gold, dust: dust, crystals: crystals, premium: true, level: level,
      isChest: isChestLevel,
      // 4 KOMPLETNÍ sezónní sety Trhliny Osudu (aura+rám+pozadí+skin najednou, ne rozdělené po
      // kusu jako dřív) - level 10 Bašta, 20 Mor (aktuální sezóna dle konverzace), 30 Přesnost,
      // 40 Chaos. Achievementy za Trhlinu (viz kAchievementDefs) dávají místo toho JEDEN
      // univerzální fialový set - sezónní barvy jsou vyhrazené jen pro Battle Pass.
      cosmeticAuraId: level == 10
          ? 'bp_bastion_aura'
          : level == 20
              ? 'bp_plague_aura'
              : level == 30
                  ? 'bp_precision_aura'
                  : level == 40
                      ? 'bp_chaos_aura'
                      : null,
      cosmeticFrameId: level == 10
          ? 'bp_bastion_frame'
          : level == 20
              ? 'bp_plague_frame'
              : level == 30
                  ? 'bp_precision_frame'
                  : level == 40
                      ? 'bp_chaos_frame'
                      : null,
      cosmeticCardBackgroundId: level == 10
          ? 'bp_bastion_bg'
          : level == 20
              ? 'bp_plague_bg'
              : level == 30
                  ? 'bp_precision_bg'
                  : level == 40
                      ? 'bp_chaos_bg'
                      : null,
      cosmeticAttackSkinId: level == 10
          ? 'bp_bastion_skin'
          : level == 20
              ? 'bp_plague_skin'
              : level == 30
                  ? 'bp_precision_skin'
                  : level == 40
                      ? 'bp_chaos_skin'
                      : null,
      // 5 Jisker na KAŽDÉ prémiové úrovni (viz konverzace), ne jen na milnících.
      sparks: 5,
      questXpBonusPercent: level == 1 ? 20 : 0,
    );
  }

  void claimBattlePassReward(int level, bool premium) {
    if (level < 1 || level > battlePassLevel) return;
    if (premium && !battlePassPremium) return;
    final claimedSet = premium ? battlePassPremiumClaimed : battlePassFreeClaimed;
    if (claimedSet.contains(level)) return;
    final reward = battlePassRewardFor(level, premium);
    gold += reward.gold;
    magicDust += reward.dust;
    crystals += reward.crystals;
    cosmeticSparks += reward.sparks;
    claimedSet.add(level);
    if (reward.cosmeticFrameId != null) unlockedFrames.add(reward.cosmeticFrameId!);
    if (reward.cosmeticAttackSkinId != null) unlockedAttackSkins.add(reward.cosmeticAttackSkinId!);
    if (reward.cosmeticAuraId != null) unlockedAuras.add(reward.cosmeticAuraId!);
    if (reward.cosmeticCardBackgroundId != null) unlockedCardBackgrounds.add(reward.cosmeticCardBackgroundId!);
    message = reward.cosmeticFrameId != null
        ? tr('Battle Pass odměna vyzvednuta: nový rám portrétu odemčen!', 'Battle Pass reward claimed: new portrait frame unlocked!')
        : reward.cosmeticAttackSkinId != null
            ? tr('Battle Pass odměna vyzvednuta: nový skin základního útoku odemčen!', 'Battle Pass reward claimed: new basic attack skin unlocked!')
            : reward.cosmeticAuraId != null
                ? tr('Battle Pass odměna vyzvednuta: nová aura odemčena!', 'Battle Pass reward claimed: new aura unlocked!')
                : reward.cosmeticCardBackgroundId != null
                    ? tr('Battle Pass odměna vyzvednuta: nové pozadí karty odemčeno!', 'Battle Pass reward claimed: new card background unlocked!')
                    : tr('Battle Pass odměna vyzvednuta: úroveň $level${premium ? " (prémiová)" : ""}!', 'Battle Pass reward claimed: level $level${premium ? " (premium)" : ""}!');
    notifyListeners();
  }

  void claimAllBattlePassRewards() {
    bool any = false;
    for (int l = 1; l <= battlePassLevel; l++) {
      if (!battlePassFreeClaimed.contains(l)) {
        claimBattlePassReward(l, false);
        any = true;
      }
      if (battlePassPremium && !battlePassPremiumClaimed.contains(l)) {
        claimBattlePassReward(l, true);
        any = true;
      }
    }
    if (!any) message = tr('Žádné nevyzvednuté odměny Battle Passu.', 'No unclaimed Battle Pass rewards.');
  }

  void buyBattlePassPremium() {
    if (battlePassPremium) return;
    if (crystals < battlePassPremiumCost) {
      message = tr('Nedostatek krystalů! Prémiová sezóna stojí $battlePassPremiumCost 💎 (máš $crystals 💎).', 'Not enough crystals! The premium season costs $battlePassPremiumCost 💎 (you have $crystals 💎).');
      notifyListeners();
      return;
    }
    crystals -= battlePassPremiumCost;
    battlePassPremium = true;
    message = tr('Prémiová větev Battle Passu odemčena! Teď můžeš vyzvednout i prémiové odměny za úrovně, které jsi už dosáhl.', 'Battle Pass Premium track unlocked! You can now claim premium rewards for levels you have already reached.');
    notifyListeners();
  }

  // ===== PROMO KÓDY =====
  Set<String> redeemedPromoCodes = {}; // uloženo velkými písmeny, permanentní (nereseuje se smrtí)

  // ===== ÚVODNÍ INTRODUKCE =====
  bool introSeen = false; // permanentní, zobrazí se jen jednou před prvním výběrem třídy

  // ===== TUTORIAL / NÁPOVĚDA (viz TutorialTipId v data_models.dart) =====
  // introTutorialDone: lineární úvodní sekvence proběhla/byla přeskočena. Default TRUE při
  // chybějícím klíči v save - důležité, ať se stará postava (uložená před přidáním téhle
  // funkce) po loadu netváří jako úplný nováček. Skutečně NOVÁ postava (viz selectClass()) si
  // ho explicitně nastaví na false, aby se jí tutoriál spustil.
  bool introTutorialDone = true;
  int introTutorialStep = 0; // index do kTutorialIntroSteps
  final Set<String> shownContextTips = {}; // TutorialTipId.name, které už hráč viděl - permanentní
  final List<TutorialTipId> _pendingContextTips = []; // fronta k zobrazení, čistě "živý" stav (neukládá se)
  // Hub dlaždice, které hráč už navštívil PO jejich odemčení - dokud dlaždice v tomhle setu není,
  // HubTile ji zvýrazní jako "NOVÉ" (viz isNew v ui_design.dart). Klíč je libovolný stabilní
  // string (např. 'lair', 'arena') volený na místě volání - viz onTap v HubScreen.
  final Set<String> seenHubTiles = {};
  void markHubTileSeen(String key) {
    if (seenHubTiles.add(key)) {
      saveGame();
      notifyListeners();
    }
  }

  bool get introTutorialActive => !introTutorialDone && heroClass != HeroClass.none;
  TutorialTipId get currentIntroTutorialTip => kTutorialIntroSteps[introTutorialStep.clamp(0, kTutorialIntroSteps.length - 1)];

  void advanceIntroTutorial() {
    if (introTutorialStep < kTutorialIntroSteps.length - 1) {
      introTutorialStep++;
    } else {
      introTutorialDone = true;
    }
    saveGame();
    notifyListeners();
  }

  void previousIntroTutorialStep() {
    if (introTutorialStep > 0) introTutorialStep--;
    notifyListeners();
  }

  void skipIntroTutorial() {
    introTutorialDone = true;
    saveGame();
    notifyListeners();
  }

  // Zařadí kontextový tip do fronty k zobrazení - jen pokud ho hráč ještě neviděl a není už
  // ve frontě. Volej z míst, kde se hráči poprvé odemyká daná mechanika (viz volání níž).
  void _queueContextTip(TutorialTipId id) {
    if (shownContextTips.contains(id.name)) return;
    if (_pendingContextTips.contains(id)) return;
    _pendingContextTips.add(id);
  }

  TutorialTipId? get pendingContextTip => (introTutorialActive || _pendingContextTips.isEmpty) ? null : _pendingContextTips.first;

  void dismissContextTip(TutorialTipId id) {
    shownContextTips.add(id.name);
    _pendingContextTips.remove(id);
    saveGame();
    notifyListeners();
  }

  // ===== PARAGON SETNINY — catch-up bonus pro alty =====
  // Za KAŽDÝCH 100 Paragon dosažených na NEJVYŠŠÍ třídě účtu (permanentní, nikdy neklesá) hráč
  // získá +50 % rychlejší rank/Paragon postup pro třídy, co jsou AKTUÁLNĚ pozadu (= "alty") -
  // respektuje čas investovaný do hlavní postavy a nabídne rychlejší rozjezd další třídě.
  // Set je deduplikovaný napříč třídami, takže i kdyby víc tříd nezávisle prošlo stejnou setninou,
  // počítá se jen jednou - altCatchUpBonus tak fakticky vychází čistě z NEJVYŠŠÍHO dosaženého
  // Paragonu na účtu (viz _checkParagonMilestones), ne z nasčítání napříč všemi třídami zvlášť.
  Set<int> paragonCentMilestones = {}; // uložené hodnoty: 100, 200, 300, ... (v jednotkách Paragon levelu)

  // ===== GEMY V PRSTENU OSUDU =====
  // Hráč může mít aktivní jen JEDEN typ gemu najednou (viz activeGemType) - efekt síla škáluje
  // s POČTEM gemů tohoto typu vsazených v Prstenu (2 %/gem, viz gemMagnitudePerCount). Permanentní
  // volba, nereseuje se smrtí (prsten samotný taky ne).
  String? activeGemType;
  static const double gemMagnitudePerCount = 0.02; // 2 % za každý gem stejného typu

  // Kolik gemů daného jména (dle gemNameFor) je vsazeno v Prstenu Osudu.
  int gemCountOf(String gemName) {
    final ringMatches = inventory.where((i) => i.isArtifact).toList();
    if (ringMatches.isEmpty) return 0;
    final ring = ringMatches.first;
    return ring.gemSlots.where((g) => g == gemName).length;
  }

  int get activeGemCount => activeGemType == null ? 0 : gemCountOf(activeGemType!);

  // Mapování jména gemu na odpovídající větev stromu artefaktu (Runový kovář).
  static const Map<String, WeaponSkillBranch> _gemBranchMap = {
    "Gem Jedu": WeaponSkillBranch.poison,
    "Gem Oživení": WeaponSkillBranch.revival,
    "Gem Temnoty": WeaponSkillBranch.darkness,
    "Gem Krvavé lázně": WeaponSkillBranch.bloodbath,
    "Gem Roztříštění": WeaponSkillBranch.fragmentation,
    "Gem Odrazu": WeaponSkillBranch.reflection,
  };

  // Bonus k magnitude AKTIVNÍHO gemu ze stromu artefaktu - platí jen NEJVYŠŠÍ odemčený běžný
  // (ne-master) tier dané větve, ne součet všech odemčených uzlů (upgrade-styl, ne stacking).
  // Platí jen s nasazeným artefaktem (viz volání v activeGemMagnitude).
  double weaponSkillGemBonus(String? gemName) {
    if (gemName == null) return 0;
    final branch = _gemBranchMap[gemName];
    if (branch == null) return 0;
    final unlockedInBranch = WeaponSkillTree.branchNodes(branch).where((n) => !n.isMaster && unlockedWeaponSkillNodeIds.contains(n.id)).toList();
    if (unlockedInBranch.isEmpty) return 0;
    unlockedInBranch.sort((a, b) => b.tier.compareTo(a.tier));
    return unlockedInBranch.first.value;
  }

  double get activeGemMagnitude {
    double base = activeGemCount * gemMagnitudePerCount;
    if (equippedWeapon?.isArtifact == true) base += weaponSkillGemBonus(activeGemType);
    return base;
  }

  // ===== SYNERGIE: Gem × Master runa dané větve × identita třídy (ne specializace) =====
  // Podmínka: nasazený artefakt (zbraň), nasazený Prsten (artefakt na slotu ring) s alespoň
  // 1 kusem daného gemu (NEMUSÍ být aktivní - jen fyzicky vsazený), a vykovaný/odemčený master
  // uzel dané větve. Čtyři třídní skupiny sdílí identický efekt v duchu: Warrior+Šermíř
  // (frontline fyzický), Mnich+Léčitel (heal/support), Mág+DK (temná magie/DoT), Lovec (sólo).
  bool _hasGemSynergy(String gemName, String masterNodeId) {
    if (equippedWeapon?.isArtifact != true) return false;
    if (!equipment.any((i) => i.isArtifact && i.slot == EquipSlot.ring)) return false;
    if (gemCountOf(gemName) <= 0) return false;
    return unlockedWeaponSkillNodeIds.contains(masterNodeId);
  }

  bool get _isWarriorLikeClass => heroClass == HeroClass.warrior || heroClass == HeroClass.duelist;
  bool get _isHealLikeClass => heroClass == HeroClass.monk || heroClass == HeroClass.healer;
  bool get _isCasterLikeClass => heroClass == HeroClass.mage || heroClass == HeroClass.deathknight;
  bool get _isDruidClass => heroClass == HeroClass.druid;
  bool get _isPaladinClass => heroClass == HeroClass.paladin;
  bool get _isDemonHunterClass => heroClass == HeroClass.demonhunter;
  bool get _isNecromancerClass => heroClass == HeroClass.necromancer;

  void setActiveGem(String? gemName) {
    if (gemName != null && gemCountOf(gemName) == 0) {
      message = tr("Nemáš vsazený žádný „$gemName“ v Prstenu Osudu.", "You do not have any \u201e$gemName\u201c socketed in the Ring of Fate.");
      notifyListeners();
      return;
    }
    activeGemType = gemName;
    message = gemName == null ? "Aktivní gem zrušen." : "Aktivní gem: $gemName (síla efektu: ${(gemCountOf(gemName) * gemMagnitudePerCount * 100).round().toString()} %).";
    notifyListeners();
  }

  // Zkratky pro jednotlivé gem efekty - true jen když je DANÝ typ zvolen jako activeGemType.
  bool get gemPoisonActive => activeGemType == "Gem Jedu";
  bool get gemRevivalActive => activeGemType == "Gem Oživení";
  bool get gemDarknessActive => activeGemType == "Gem Temnoty";
  bool get gemBloodbathActive => activeGemType == "Gem Krvavé lázně";
  bool get gemFragmentationActive => activeGemType == "Gem Roztříštění";
  bool get gemReflectionActive => activeGemType == "Gem Odrazu";

  // Popis efektu daného gemu - pro UI výběr (viz _gemPanel v ProfileScreen).
  String gemEffectDescriptionFor(String gemName) {
    switch (gemName) {
      case "Gem Jedu":
        return "Šance aplikovat Jed na nepřítele při útoku (Věž/Lair): 2 % za gem.";
      case "Gem Oživení":
        return "Šance přežít smrtelný zásah s 33 % HP: 2 % za gem.";
      case "Gem Temnoty":
        return "Zvýší účinnost heal/block/dodge/absorb: +2 % za gem.";
      case "Gem Krvavé lázně":
        return "Bonus poškození proti nepříteli pod 30 % HP: +2 % za gem.";
      case "Gem Roztříštění":
        return "Šance na dvojitý zásah (\"Ozvěna\"): 2 % za gem.";
      case "Gem Odrazu":
        return "Vrátí % obdrženého poškození útočníkovi: 2 % za gem.";
      default:
        return "";
    }
  }

  // Kdy hrdina POPRVÉ dosáhl daného levelu - klíč je level (int), hodnota timestamp. Používá se
  // pro plovoucí expiraci promo kódů (viz PromoCodeDef.floatingExpiry) a případně jinde v budoucnu.
  // Permanentní, nereseuje se smrtí (level taky ne).
  Map<int, DateTime> levelMilestoneReachedAt = {};

  // ===== OFFLINE PROGRESS =====
  // Záměrně velmi skromné - jen malý "vítej zpět" bonus zlata/dustu, ŽÁDNÉ krystaly (ty jsou
  // hlavní rank-up gate a mají zůstat čistě za aktivní hraní), ŽÁDNÉ XP/kills/floor postup
  // (žádná simulace boje offline). Cíl: ať se nevyplatí appku nechávat zavřenou místo hraní.
  // Odemyká se až po offlineUnlockDeaths úmrtích - viz totalDeaths (permanentní počítadlo,
  // inkrementuje se v confirmDeath()).
  int totalDeaths = 0;
  // Tutorial gate: Družina je zamčená (šedá) až do PRVNÍ smrti - pak hráč dostane 150 zlata a
  // MUSÍ si najmout aspoň jednoho společníka, než se mu odemkne zbytek hry (viz
  // mustHireFirstCompanion níže + overlay v hlavní obrazovce). Jakmile jednou najme, natrvalo
  // se to odemyká a už se to nikdy nevrátí (i kdyby později propustil všechny společníky).
  bool get companionsTileLocked => totalDeaths == 0;
  bool get mustHireFirstCompanion => totalDeaths > 0 && everRecruitedCompanions.isEmpty;
  int totalQuestsCompleted = 0; // permanentní, na rozdíl od Quest.isCompleted (to se u daily/weekly/monthly resetuje)
  bool everCompletedMonthlyQuest = false;
  bool everWatchedRiftAd = false;
  static const int offlineUnlockDeaths = 1;
  bool get offlineProgressUnlocked => totalDeaths >= offlineUnlockDeaths;
  DateTime? lastActiveTimestamp;
