  // Denní Rift mutátor je deterministický podle kalendářního dne.
  RiftDailyMutator get currentRiftMutator {
    final n=DateTime.now();
    final seed=n.year*372+n.month*31+n.day;
    return RiftDailyMutator.values[seed % RiftDailyMutator.values.length];
  }
  double get riftMutatorRewardMult => currentRiftMutator==RiftDailyMutator.frozenCurse ? 1.25 : 1.0;
  double get riftMutatorDirectDamageMult => currentRiftMutator==RiftDailyMutator.decay ? 1.20 : 1.0;
  double get riftMutatorDotMult => currentRiftMutator==RiftDailyMutator.decay ? 0.60 : 1.0;
