  int _relicArmorShredAmount = 0; // Sdílené napříč VŠEMI relicy s efektem "snižuje/sníží Armor
  // cíle" (jen jeden relic je aktivní najednou, takže sdílení je bezpečné) - kolik bylo skutečně
  // odečteno z currentEnemyDef, aby šlo po vypršení efektu přesně vrátit zpět (viz _tickEffects()).
  String? _relicArmorShredDebuffName; // jméno StatusEffectu, co shred způsobil - viz _tickEffects()
  // Srazí currentEnemyDef o pct (jen pokud právě žádný shred neběží - ochrana proti dvojímu
  // strhnutí) a zapamatuje si jméno debuffu, co ho drží, pro pozdější přesnou obnovu.
  void _applyRelicArmorShred(String debuffName, double pct) {
    if (_relicArmorShredAmount > 0) return;
    _relicArmorShredAmount = (currentEnemyDef * pct).round();
    currentEnemyDef -= _relicArmorShredAmount;
    _relicArmorShredDebuffName = debuffName;
  }
  // Vrátí Armor zpět, pokud právě mizí ten SAMÝ debuff, co ho srazil (ať už přirozeným vypršením
  // v _tickEffects(), nebo ručním odebráním při refresh/Shatter apod. přímo v _castXSigil).
  void _restoreRelicArmorShredIfMatches(String debuffName) {
    if (_relicArmorShredDebuffName == debuffName && _relicArmorShredAmount > 0) {
      currentEnemyDef += _relicArmorShredAmount;
      _relicArmorShredAmount = 0;
      _relicArmorShredDebuffName = null;
    }
  }
