  // ===== BANKA — trvalé úložiště NAPŘÍČ ÚČTEM, nezávislé na aktuální třídě/buildu =====
  // Řeší situaci "přerolluju z DK na Mnicha a vybavení pro DK je najednou k ničemu" - místo aby
  // se muselo prodat/roztavit, jde ho uložit do Banky a vytáhnout zpět, kdyby se hráč vrátil
  // k původní třídě později. Bankovní itemy se NEPOČÍTAJÍ do bestPossibleGearItemLevel (Aréna
  // gear scoring) ani do žádného jiného výpočtu - jsou to čistě "na sklad", dokud se nevytáhnou
  // zpět do inventáře.
  //
  // SLOTY SE ODEMYKAJÍ ZA ZLATO - bankMaxSize je tvrdý strop (60), ale hráč začíná jen s
  // bankStartingSlots odemčenými. Každý další slot stojí čím dál víc (viz bankSlotUnlockCost) -
  // skutečná dlouhodobá investice, ne jen limit na velikost seznamu.
  static const int bankMaxSize = 60;
  static const int bankStartingSlots = 5;
  int bankUnlockedSlots = bankStartingSlots;
  List<Item> bankItems = [];
  // ===== ZLATÝ TREZOR — oddělená hromádka od běžného `gold`, s pasivním úrokem (1 %/den, se
  // stropem), ať má banka pro zlato skutečnou herní hodnotu, ne jen "schovej si to tu". Stejný
  // princip jako Offline Progress bonus - úrok se dopočítá při načtení podle uplynulého času.
  int bankGold = 0;
  DateTime? lastBankInterestTimestamp;
  static const double bankInterestRatePerDay = 0.01; // 1 %/den
  static const int bankInterestMaxDays = 14; // strop - max 14 dní nastřádaného úroku najednou

  // Cena za odemčení DALŠÍHO slotu (1-indexed - "nextSlotNumber" = kolikátý v pořadí ho kupuješ).
  // Rostoucí křivka: začíná levně, ke konci (blízko bankMaxSize) je to velká investice.
  int bankSlotUnlockCost(int nextSlotNumber) => (150 * pow(nextSlotNumber, 1.6)).round();

  void unlockNextBankSlot() {
    if (bankUnlockedSlots >= bankMaxSize) {
      message = tr("Banka je plně odemčená (max $bankMaxSize slotů).", "The Bank is fully unlocked (max $bankMaxSize slots).");
      notifyListeners();
      return;
    }
    final cost = bankSlotUnlockCost(bankUnlockedSlots + 1);
    if (bankGold < cost) {
      message = tr("Nedostatek uloženého zlata v Bance! Potřeba: $cost 🪙 (v trezoru).", "Not enough gold stored in the Bank! Needed: $cost 🪙 (in the vault).");
      notifyListeners();
      return;
    }
    bankGold -= cost;
    bankUnlockedSlots++;
    message = tr("Odemčen další slot Banky! ($bankUnlockedSlots/$bankMaxSize)", "Another Bank slot unlocked! ($bankUnlockedSlots/$bankMaxSize)");
    notifyListeners();
  }

  void depositGold(int amount) {
    if (amount <= 0 || amount > gold) {
      message = tr("Neplatná částka.", "Invalid amount.");
      notifyListeners();
      return;
    }
    gold -= amount;
    bankGold += amount;
    message = tr("Uloženo $amount 🪙 do Banky.", "Deposited $amount 🪙 into the Bank.");
    notifyListeners();
  }

  void withdrawGold(int amount) {
    if (amount <= 0 || amount > bankGold) {
      message = tr("Neplatná částka.", "Invalid amount.");
      notifyListeners();
      return;
    }
    bankGold -= amount;
    gold += amount;
    message = tr("Vytaženo $amount 🪙 z Banky.", "Withdrew $amount 🪙 from the Bank.");
    notifyListeners();
  }

  // Voláno při loadGame() - stejný "vítej zpět" princip jako _computeOfflineProgress().
  void _computeBankInterest() {
    if (bankGold <= 0 || lastBankInterestTimestamp == null) {
      lastBankInterestTimestamp = DateTime.now();
      return;
    }
    final elapsedDays = DateTime.now().difference(lastBankInterestTimestamp!).inHours / 24.0;
    final cappedDays = elapsedDays.clamp(0.0, bankInterestMaxDays.toDouble());
    if (cappedDays < 0.04) return; // méně než ~1 hodina - nestojí to za zprávu
    final earned = (bankGold * bankInterestRatePerDay * cappedDays).round();
    if (earned > 0) {
      bankGold += earned;
      message = tr("Banka: úrok +$earned 🪙 (za ${cappedDays.toStringAsFixed(1)} dní)!", "Bank: interest +$earned 🪙 (over ${cappedDays.toStringAsFixed(1)} days)!");
    }
    lastBankInterestTimestamp = DateTime.now();
  }

  // Katalog setů (zelená barva). Každý set má 4 kusy:
  // 1x zbraň, 1x zbroj, 2x přívěsek. 2 kusy = menší bonus, 4 kusy = velký bonus.
  // 21 setů (7 tříd × 3 specializace) - 8 kusů, bez zbraně a prstenu. Staty (statName/statValue)
  // jsou slabší verze odpovídajícího Hardcore setu (viz hardcoreSets výše) se stejným zaměřením
  // statu; 4/6/8pc dá slabší, ale reálně funkční bonus poškození/obrany/HP (viz gearSetPhysDmgBonus
  // / gearSetMagDmgBonus / gearSetDefHpBonus) - na rozdíl od Hardcore setu ale neupravuje jednotlivé
  // schopnosti jmenovitě, jen plošně zesílí poškození a přežitelnost dané třídy.
  // ===== ARTEFAKTOVÉ ZBRANĚ (Runový kovář) — 1 unikátní zbraň na (třída, specializace) =====
  final List<ArtifactWeaponDef> artifactWeapons = [
    ArtifactWeaponDef(id: "warrior_1_artifact", heroClass: HeroClass.warrior, specialization: 1, name: "Vzteklina Krve", description: "Berserkerova zbraň zrozená z nekonečného vzteku."),
