  List<Item> get equipment => inventory.where((i) => !i.isConsumable && i.isActive).toList();
  List<Item> get inactiveEquipment => inventory.where((i) => !i.isConsumable && !i.isActive).toList();
  // Kolik nenasazených a nezamčených kusů dané kvality lze hromadně roztavit - viz salvageAllByRarity().
  int countInactiveByRarity(Rarity r) => inactiveEquipment.where((i) => i.rarity == r && !i.isLocked && !i.isArtifact).length;
  List<Item> get consumables => inventory.where((i) => i.isConsumable).toList();
  List<Companion> get activeCompanions => companions.where((c) => c.isRecruited).toList();

  int get companionPhysBonus {
    int total = 0;
    for (var c in activeCompanions) {
      if (c.role == CompanionRole.archer || c.role == CompanionRole.warrior) total += c.powerBonus;
    }
    return total;
  }

  int get companionMagBonus {
    int total = 0;
    for (var c in activeCompanions) {
      if (c.role == CompanionRole.healer) total += c.powerBonus;
    }
    return total;
  }

  // ===== SET BONUSY =====
  // Spočítá, kolik kusů z každého setu má hráč aktuálně nasazeno.
  Map<String, int> get equippedSetCounts {
    Map<String, int> counts = {};
    for (var item in equipment) {
      if (item.setId != null) {
        counts[item.setId!] = (counts[item.setId!] ?? 0) + 1;
      }
    }
    return counts;
  }

