  Map<String, int> get equippedHardcoreSetCounts {
    Map<String, int> counts = {};
    for (var item in equipment) {
      if (item.hardcoreSetId != null) {
        counts[item.hardcoreSetId!] = (counts[item.hardcoreSetId!] ?? 0) + 1;
      }
    }
    return counts;
  }

  // Hardcore set odpovídající AKTUÁLNÍ třídě a specializaci hráče (max 1 relevantní najednou).
  HardcoreSetDef? get activeHardcoreSetDef {
    final matches = hardcoreSets.where((s) => s.heroClass == heroClass && s.specialization == specialization);
    return matches.isNotEmpty ? matches.first : null;
  }

  // 0/2/4/6/8 - kolik kusů aktivního setu má hráč nasazeno (prahové úrovně).
  int get activeHardcoreSetTier {
    final def = activeHardcoreSetDef;
    if (def == null) return 0;
    final count = equippedHardcoreSetCounts[def.id] ?? 0;
    if (count >= 8) return 8;
    if (count >= 6) return 6;
    if (count >= 4) return 4;
    if (count >= 2) return 2;
    return 0;
  }

  // Set odpovídající AKTUÁLNÍ třídě a specializaci hráče (max 1 relevantní najednou) - stejný
  // princip jako activeHardcoreSetDef, jen pro běžné (ne-hardcore) SET vybavení.
  GearSetDef? get activeGearSetDef {
    final matches = gearSets.where((s) => s.heroClass == heroClass && s.specialization == specialization);
    return matches.isNotEmpty ? matches.first : null;
  }

  // 0/2/4/6/8 - kolik kusů aktivního setu má hráč nasazeno (prahové úrovně, sada má 8 kusů).
  int get activeGearSetTier {
    final def = activeGearSetDef;
    if (def == null) return 0;
    final count = equippedSetCounts[def.id] ?? 0;
    if (count >= 8) return 8;
    if (count >= 6) return 6;
    if (count >= 4) return 4;
    if (count >= 2) return 2;
    return 0;
  }

  static const Set<HeroClass> _gearSetPhysClasses = {HeroClass.warrior, HeroClass.hunter, HeroClass.duelist, HeroClass.monk, HeroClass.paladin, HeroClass.demonhunter};
  static const Set<HeroClass> _gearSetMagClasses = {HeroClass.healer, HeroClass.mage, HeroClass.druid, HeroClass.necromancer};

  // +6 % na 4pc, +10 % navíc na 8pc (celkem +16 %) k poškození schopností i základních útoků -
  // aplikuje se přes physAtk/magAtk modifier, takže to reálně zesílí VŠECHNO poškození dané
  // třídy (schopnosti počítají dmg jako násobek physAtk/magAtk). DK sdílí bonus napůl mezi obojí.
  double get gearSetPhysDmgBonus {
    final isHybrid = heroClass == HeroClass.deathknight;
    if (!_gearSetPhysClasses.contains(heroClass) && !isHybrid) return 0;
    final share = isHybrid ? 0.5 : 1.0;
    final tier = activeGearSetTier;
    double bonus = 0;
    if (tier >= 4) bonus += 0.06 * share;
    if (tier >= 8) bonus += 0.10 * share;
    return bonus;
  }

  double get gearSetMagDmgBonus {
    final isHybrid = heroClass == HeroClass.deathknight;
    if (!_gearSetMagClasses.contains(heroClass) && !isHybrid) return 0;
    final share = isHybrid ? 0.5 : 1.0;
    final tier = activeGearSetTier;
    double bonus = 0;
    if (tier >= 4) bonus += 0.06 * share;
    if (tier >= 8) bonus += 0.10 * share;
    return bonus;
  }

  // +7 % na 6pc, +7 % navíc na 8pc (celkem +14 %) k obraně a max HP - stejné pro všechny třídy.
  double get gearSetDefHpBonus {
    final tier = activeGearSetTier;
    double bonus = 0;
    if (tier >= 6) bonus += 0.07;
    if (tier >= 8) bonus += 0.07;
    return bonus;
  }

  // ===== ELITNÍ SETY (Hardcore/Předpeklí/Peklo) — DYNAMICKÝ 2pc mainstat bonus + GENERICKÝ 8pc =====
  // Na rozdíl od klasického zeleného setu (mainstat zapečený přímo v itemu při dropu) je 2pc
  // bonus elitních setů ŽIVĚ PŘEPOČÍTÁVANÝ: def.statValue × level hráče × počet AKTUÁLNĚ
  // nasazených kusů - roste tedy s levelem i s tím, kolik kusů máš zrovna na sobě, ne jen
  // jednou napevno při dropu. Hardcore/Předpeklí/Peklo jsou EXKLUZIVNÍ (jen jeden aktivní
  // zaráz - viz atLeastHardcore/atLeastPredpekli/pekloMode), takže se vždy počítá jen ten
  // aktuálně aktivní tier, ne součet všech tří.
  MapEntry<String, double>? get _activeEliteSetMainStatBonus {
    HardcoreSetDef? def;
    int count;
    if (pekloMode) {
      def = activePekloSetDef;
      count = def == null ? 0 : (equippedPekloSetCounts[def.id] ?? 0);
    } else if (predpekliMode) {
      def = activePredpekliSetDef;
      count = def == null ? 0 : (equippedPredpekliSetCounts[def.id] ?? 0);
    } else if (hardcoreMode) {
      def = activeHardcoreSetDef;
      count = def == null ? 0 : (equippedHardcoreSetCounts[def.id] ?? 0);
    } else {
      return null;
    }
    if (def == null || count < 2) return null;
    return MapEntry(def.statName, (def.statValue * level * count).toDouble());
  }

  double eliteSetMainStatBonus(String statName) {
    final entry = _activeEliteSetMainStatBonus;
    return (entry != null && entry.key == statName) ? entry.value : 0;
  }

  // Generický 8pc bonus (stejný pro všech 100 elitních set definic, viz HardcoreSetDef.
  // eightPieceDesc): +5 % poškození schopností a útoků, +10 % obrana a max HP. Aktivní tier
  // (Hardcore/Předpeklí/Peklo) se řeší stejně jako výš - jen jeden zaráz.
  int get _activeEliteSetTier {
    if (pekloMode) return activePekloSetTier;
    if (predpekliMode) return activePredpekliSetTier;
    if (hardcoreMode) return activeHardcoreSetTier;
    return 0;
  }
  double get eliteSet8pcDmgBonus => _activeEliteSetTier >= 8 ? 0.05 : 0;
  double get eliteSet8pcDefHpBonus => _activeEliteSetTier >= 8 ? 0.10 : 0;

  // Vytvoří konkrétní kus vybavení patřící do setu, škálovaný podle powerLevel (např. rank kováře
  // nebo patro/10). Stat je vždy set.statName/statValue (třídě odpovídající primární stat), ne
  // náhodný - viz GearSetDef.
  // Vitality misto flat "HP" statu - flat HP nezíská paragonMultiplierFor() ani další
  // multiplikativní škálování, které dostávají ostatní staty (viz _itemStatSum), takže na
  // pozdější hře byl v podstatě irelevantní (pár set desítek HP proti milionům max HP).
  // Vitality naopak paragon multiplier VŽDY dostává (viz paragonMultiplierFor), takže roste
  // se zbytkem buildu. 5 Vitality * maxHp koeficient 8 = stejný ZÁKLADNÍ příspěvek jako dřívějších 40 HP.
  Item _createSetItem(GearSetDef set, EquipSlot slot, int powerLevel) {
    // mainStat × level × tier multiplikátor (Normal ×1, Hardcore ×1,5, Předpeklí ×2,5, Peklo ×4,5)
    // - všechny 4 tiery stejného setu sdílí STEJNÉ set.statValue (mainStat), škáluje se jen tímhle
    // multiplikátorem. Viz _createHardcoreSetItem/_createPredpekliSetItem/_createPekloSetItem.
    final primaryAmount = max(1, (set.statValue * level * 1.0).round());
    // Vitality bonus dřív škáloval z powerLevel (rank kováře/patro) - na vysokém levelu postavy
    // tak zůstával v jednotkách, zatímco hlavní stat rostl do tisíců. Teď škáluje stejně jako
    // hlavní stat (10 % z primaryAmount), takže zůstává smysluplný v každé fázi hry.
    final vitalityFromHp = max(1, (primaryAmount * 0.10).round());
    // Třetí stat navíc (na žádost) - malé množství Attack Speed (= mírně vyšší šance na Extra
    // Attack, viz extraAttackChance). Sety mají oproti legendary itemům jen 2 staty (mainstat +
    // Vitalita), takže v itemPowerScore() vždy prohrávaly s itemem, co má naroleované 4-5 statů
    // najednou, i když je každý jednotlivě slabší. Drží se úmyslně nízko (~1% dopad na chance na
    // kus u nízkého ratingu, s klesajícím přínosem při stackování víc kusů díky tvaru křivky
    // extraAttackChance) - není to náhrada za mainstat, jen malý bonus navíc.
    final attackSpeedBonus = max(1, (level / 20).round());
    final stats = <String, int>{set.statName: primaryAmount};
    stats["Vitality"] = (stats["Vitality"] ?? 0) + vitalityFromHp;
    stats["Attack Speed"] = attackSpeedBonus;
    return Item(
      name: "${set.name}: ${slotDisplayName(slot)}",
      value: 500 * powerLevel,
      stats: stats,
      rarity: Rarity.legendary,
      slot: slot,
      setId: set.id,
    );
  }

  // Hardcore set itemy (neonově modrá) - viz HardcoreSetDef. Padají jen v Hardcore Mode:
  // 5 % z Hardcore Lair bosse, 1 % z Tower bosse, 2 % z Poklad-skřeta v Rift.
  static const List<EquipSlot> _hardcoreSetSlots = [EquipSlot.armor, EquipSlot.accessory, EquipSlot.gloves, EquipSlot.boots, EquipSlot.helmet, EquipSlot.belt, EquipSlot.cloak, EquipSlot.shoulders];

  Item _createHardcoreSetItem(HardcoreSetDef def, EquipSlot slot, int powerLevel) {
    // Mainstat 2pc bonus (def.statName) se od teď počítá ŽIVĚ (statValue × level × počet
    // nasazených kusů - viz GameState._activeEliteSetMainStatBonus), ne zapečený do itemu -
    // proto ho tenhle item na rozdíl od dřívějška NEDOSTÁVÁ. Vitality zůstává baked-in, ale
    // odvozená přímo z def.statValue × level (bez tier multiplikátoru primaryAmount, který
    // sloužil hlavně mainstatu), aby item pořád nesl nějaké HP i sám o sobě.
    final vitalityFromHp = max(1, (def.statValue * level * 0.15).round());
    // Třetí stat navíc (viz stejná poznámka u _createSetItem výš).
    final attackSpeedBonus = max(1, (level / 20).round());
    final stats = <String, int>{"Vitality": vitalityFromHp, "Attack Speed": attackSpeedBonus};
    return Item(
      name: "${def.name}: ${slotDisplayName(slot)}",
      value: 1000 * powerLevel,
      stats: stats,
      rarity: Rarity.legendary,
      slot: slot,
      hardcoreSetId: def.id,
    );
  }

  // Zkusí dropnout kus Hardcore setu odpovídajícího AKTUÁLNÍ třídě a specializaci hráče.
  // Nic nedělá, pokud hráč nemá zvolenou specializaci (žádný set by neodpovídal) nebo není v Hardcore.
  void _tryDropHardcoreSetPiece(double chance, {required int powerLevel}) {
    if (!atLeastHardcore || specialization == 0) return;
    if (bagItemCount >= maxInventorySize) return;
    if (Random().nextDouble() >= chance) return;
    final matches = hardcoreSets.where((s) => s.heroClass == heroClass && s.specialization == specialization);
    if (matches.isEmpty) return;
    final def = matches.first;
    final slot = _hardcoreSetSlots[Random().nextInt(_hardcoreSetSlots.length)];
    final item = _createHardcoreSetItem(def, slot, powerLevel.clamp(1, 999));
    inventory.add(item);
    message += " 💠 Hardcore set: ${item.name}!";
  }


