  Map<String, int> get equippedPredpekliSetCounts {
    Map<String, int> counts = {};
    for (var item in equipment) {
      if (item.predpekliSetId != null) {
        counts[item.predpekliSetId!] = (counts[item.predpekliSetId!] ?? 0) + 1;
      }
    }
    return counts;
  }

  // Předpeklí set odpovídající AKTUÁLNÍ třídě a specializaci hráče (max 1 relevantní najednou).
  HardcoreSetDef? get activePredpekliSetDef {
    final matches = predpekliSets.where((s) => s.heroClass == heroClass && s.specialization == specialization);
    return matches.isNotEmpty ? matches.first : null;
  }

  // 0/2/4/6/8 - kolik kusů aktivního Předpeklí setu má hráč nasazeno (prahové úrovně).
  int get activePredpekliSetTier {
    final def = activePredpekliSetDef;
    if (def == null) return 0;
    final count = equippedPredpekliSetCounts[def.id] ?? 0;
    if (count >= 8) return 8;
    if (count >= 6) return 6;
    if (count >= 4) return 4;
    if (count >= 2) return 2;
    return 0;
  }

  Item _createPredpekliSetItem(HardcoreSetDef def, EquipSlot slot, int powerLevel) {
    // Mainstat 2pc bonus se počítá živě (viz _createHardcoreSetItem výš) - item nese jen Vitality.
    final vitalityFromHp = max(1, (def.statValue * level * 0.20).round());
    // Třetí stat navíc (viz stejná poznámka u _createSetItem výš).
    final attackSpeedBonus = max(1, (level / 20).round());
    final stats = <String, int>{"Vitality": vitalityFromHp, "Attack Speed": attackSpeedBonus};
    return Item(
      name: "${def.name}: ${slotDisplayName(slot)}",
      value: 1500 * powerLevel,
      stats: stats,
      rarity: Rarity.legendary,
      slot: slot,
      predpekliSetId: def.id,
    );
  }

  // Zkusí dropnout kus Předpeklí setu odpovídajícího AKTUÁLNÍ třídě a specializaci hráče.
  // Nic nedělá, pokud hráč nemá zvolenou specializaci nebo není alespoň v Předpeklí.
  void _tryDropPredpekliSetPiece(double chance, {required int powerLevel}) {
    if (!atLeastPredpekli || specialization == 0) return;
    if (bagItemCount >= maxInventorySize) return;
    if (Random().nextDouble() >= chance) return;
    final matches = predpekliSets.where((s) => s.heroClass == heroClass && s.specialization == specialization);
    if (matches.isEmpty) return;
    final def = matches.first;
    final slot = _hardcoreSetSlots[Random().nextInt(_hardcoreSetSlots.length)];
    final item = _createPredpekliSetItem(def, slot, powerLevel.clamp(1, 999));
    inventory.add(item);
    message += tr(" 😈 Předpeklí set: ${item.name}!", " 😈 Netherworld set: ${item.name}!");
  }

  // ===== PEKLO SETY (ohnivě rudá) — nejvyšší tier, mainStat × level × 4,5 =====
  Map<String, int> get equippedPekloSetCounts {
    Map<String, int> counts = {};
    for (var item in equipment) {
      if (item.pekloSetId != null) {
        counts[item.pekloSetId!] = (counts[item.pekloSetId!] ?? 0) + 1;
      }
    }
    return counts;
  }

  HardcoreSetDef? get activePekloSetDef {
    final matches = pekloSets.where((s) => s.heroClass == heroClass && s.specialization == specialization);
    return matches.isNotEmpty ? matches.first : null;
  }

  int get activePekloSetTier {
    final def = activePekloSetDef;
    if (def == null) return 0;
    final count = equippedPekloSetCounts[def.id] ?? 0;
    if (count >= 8) return 8;
    if (count >= 6) return 6;
    if (count >= 4) return 4;
    if (count >= 2) return 2;
    return 0;
  }

  Item _createPekloSetItem(HardcoreSetDef def, EquipSlot slot, int powerLevel) {
    // Mainstat 2pc bonus se počítá živě (viz _createHardcoreSetItem výš) - item nese jen Vitality.
    final vitalityFromHp = max(1, (def.statValue * level * 0.25).round());
    // Třetí stat navíc (viz stejná poznámka u _createSetItem výš).
    final attackSpeedBonus = max(1, (level / 20).round());
    final stats = <String, int>{"Vitality": vitalityFromHp, "Attack Speed": attackSpeedBonus};
    return Item(
      name: "${def.name}: ${slotDisplayName(slot)}",
      value: 2000 * powerLevel,
      stats: stats,
      rarity: Rarity.legendary,
      slot: slot,
      pekloSetId: def.id,
    );
  }

  // Zkusí dropnout kus Peklo setu odpovídajícího AKTUÁLNÍ třídě a specializaci hráče.
  // Nic nedělá, pokud hráč nemá zvolenou specializaci nebo není v Peklo.
  void _tryDropPekloSetPiece(double chance, {required int powerLevel}) {
    if (!(pekloMode && pekloUnlocked) || specialization == 0) return;
    if (bagItemCount >= maxInventorySize) return;
    if (Random().nextDouble() >= chance) return;
    final matches = pekloSets.where((s) => s.heroClass == heroClass && s.specialization == specialization);
    if (matches.isEmpty) return;
    final def = matches.first;
    final slot = _hardcoreSetSlots[Random().nextInt(_hardcoreSetSlots.length)];
    final item = _createPekloSetItem(def, slot, powerLevel.clamp(1, 999));
    inventory.add(item);
    message += " 🔥 Peklo set: ${item.name}!";
  }

  // ===== RUNOVÝ KOVÁŘ — unikátní artefaktová zbraň pro (třída, specializace) =====
  // Vyžaduje odemčenou specializaci (specialization != 0). Staty jsou pevné (nescálují s patrem),
  // podobně jako u Prstenu Osudu - primární stat podle toho, na čem třída staví útok
  // (stejná logika jako u physAtk/magAtk gettery), plus útočný stat a jeden bojový stat
  // odlišený podle specializace (1=Crit útočná, 2=Block obranná, 3=Dodge utilitní).
  ArtifactWeaponDef? get activeArtifactWeaponDef {
    if (specialization == 0) return null;
    final matches = artifactWeapons.where((w) => w.heroClass == heroClass && w.specialization == specialization);
    return matches.isNotEmpty ? matches.first : null;
  }

  bool get hasCraftedActiveArtifactWeapon {
    final def = activeArtifactWeaponDef;
    return def != null && craftedArtifactWeaponIds.contains(def.id);
  }

  static const int artifactWeaponDustCost = 10000;
  static const int artifactWeaponEssenceCost = 1000;
  static const int artifactWeaponMaterialsCost = 100;

  // První vykovaná artefaktová zbraň stojí plnou cenu (artifactWeaponEssenceCost). Každá další
  // (druhá, třetí specializace atd.) stojí jen polovic Esence - hráč si už jednou celý craft
  // "odemkl", takže se mu neplatí dvakrát plná cena za stejnou mechaniku.
  int get currentArtifactWeaponEssenceCost => craftedArtifactWeaponIds.isEmpty ? artifactWeaponEssenceCost : (artifactWeaponEssenceCost / 2).round();

  // Artefakty (Prsten Osudu, artefaktová zbraň) mají hlavní staty svázané s levelem hráče
  // (10 × level) - při vykování/dropu se ale zapečou natvrdo do item.stats mapy jako čísla, takže
  // by bez refreshe zůstaly navždy zamrzlé na hodnotě z okamžiku vzniku. Volá se po každém
  // level-upu (viz _addXp), aby oba artefakty zůstaly relevantní po celou hru, ne jen krátce po
  // získání. Funguje i na kusy v batohu (ne jen nasazené), aby se hodnoty neseknuly, kdyby si
  // hráč artefakt dočasně sundal.
  void _refreshArtifactStats() {
    for (final item in inventory) {
      if (!item.isArtifact) continue;
      if (item.slot == EquipSlot.ring) {
        for (final stat in ["Vitality", "Strength", "Agility", "Wisdom"]) {
          if (item.stats.containsKey(stat)) item.stats[stat] = 10 * level;
        }
      } else if (item.slot == EquipSlot.weapon) {
        for (final stat in ["Strength", "Agility", "Wisdom"]) {
          if (item.stats.containsKey(stat)) item.stats[stat] = 10 * level;
        }
      }
    }
  }

  Item _createArtifactWeapon(ArtifactWeaponDef def) {
    final bool wisdomPrimary = def.heroClass == HeroClass.monk || def.heroClass == HeroClass.healer || def.heroClass == HeroClass.mage || def.heroClass == HeroClass.druid || def.heroClass == HeroClass.necromancer;
    final bool agilityPrimary = def.heroClass == HeroClass.duelist || def.heroClass == HeroClass.hunter || def.heroClass == HeroClass.demonhunter;
    final String primaryStatName = wisdomPrimary ? "Wisdom" : (agilityPrimary ? "Agility" : "Strength");
    // Main stat teď škáluje s levelem hráče (10 × level) místo pevných 150 - artefaktová zbraň
    // tak zůstává relevantní i v pozdní hře, ne jen krátce po vykování.
    final Map<String, int> stats = {primaryStatName: 10 * level};
    if (def.heroClass == HeroClass.deathknight) {
      stats["P.ATK"] = 70;
      stats["M.ATK"] = 70;
    } else if (def.heroClass == HeroClass.healer || def.heroClass == HeroClass.mage || def.heroClass == HeroClass.druid || def.heroClass == HeroClass.necromancer) {
      stats["M.ATK"] = 100;
    } else {
      stats["P.ATK"] = 100;
    }
    final String combatStat = def.specialization == 1 ? "Crit" : (def.specialization == 2 ? "Block" : "Dodge");
    stats[combatStat] = 30;
    return Item(
      name: def.name,
      value: 999999,
      stats: stats,
      rarity: Rarity.artifact,
      slot: EquipSlot.weapon,
      isArtifact: true,
    );
  }

  void craftArtifactWeapon() {
    final def = activeArtifactWeaponDef;
    if (def == null) {
      message = tr("Nejprve si musíš zvolit specializaci.", "You must choose a specialization first.");
      notifyListeners();
      return;
    }
    if (craftedArtifactWeaponIds.contains(def.id)) {
      message = tr("Tuhle unikátní zbraň už máš vykovanou.", "You have already forged this unique weapon.");
      notifyListeners();
      return;
    }
    if (magicDust < artifactWeaponDustCost || legendaryEssence < currentArtifactWeaponEssenceCost || materials < artifactWeaponMaterialsCost) {
      message = tr("Nedostatek zdrojů (potřeba $artifactWeaponDustCost ✨ Dust, $currentArtifactWeaponEssenceCost 🔥 Esence, $artifactWeaponMaterialsCost ⚒️ Surovin).", "Not enough resources (needed: $artifactWeaponDustCost ✨ Dust, $currentArtifactWeaponEssenceCost 🔥 Essence, $artifactWeaponMaterialsCost ⚒️ Materials).");
      notifyListeners();
      return;
    }
    if (bagItemCount >= maxInventorySize) {
      message = tr("Inventář je plný!", "Your inventory is full!");
      notifyListeners();
      return;
    }
    magicDust -= artifactWeaponDustCost;
    legendaryEssence -= currentArtifactWeaponEssenceCost;
    materials -= artifactWeaponMaterialsCost;
    craftedArtifactWeaponIds.add(def.id);
    inventory.add(_createArtifactWeapon(def));
    message = tr("✨ Runový kovář vykoval: ${def.name}!", "✨ The Rune Blacksmith forged: ${def.name}!");
    _queueContextTip(TutorialTipId.tipArtifactWeapon);
    notifyListeners();
  }

  // ===== RUNOVÝ KOVÁŘ: VYLEPŠENÍ ARTEFAKTOVÉ ZBRANĚ =====
  // Artefaktová zbraň má fixní vzorec statů (viz _createArtifactWeapon - škáluje jen s levelem
  // hráče), takže ji časem přeroste obyčejná dropnutá zbraň s vysokým powerLevelem (Peklo apod.).
  // Tohle vylepšení zajistí, že artefakt zůstane VŽDY nejsilnější: obětuješ zbraň z batohu, která
  // je silnější (dle itemLevelScore) než tvá aktuálně nasazená artefaktová zbraň + 1000 Surovin.
  // Obětovaná zbraň se zničí, artefakt dostane +1 Forge úroveň (+5 % ke statům/úroveň).
  // NEMÁ STROP - lze opakovat do nekonečna, pokaždé potřebuješ ještě silnější zbraň než ta
  // předchozí (protože itemLevelScore artefaktu po forge stoupne taky).
  static const int artifactForgeMaterialsCost = 1000;

  Item? get equippedArtifactWeapon => equipment.where((i) => i.isArtifact && i.slot == EquipSlot.weapon).isNotEmpty
      ? equipment.firstWhere((i) => i.isArtifact && i.slot == EquipSlot.weapon)
      : null;

  // Zbraně z batohu, které jsou aktuálně silnější než nasazený artefakt - jediné platné
  // "obětiny" pro forgeArtifactWeapon(). Prázdné, pokud artefakt není nasazený.
  List<Item> get artifactForgeCandidates {
    final artifact = equippedArtifactWeapon;
    if (artifact == null) return [];
    final artifactScore = itemLevelScore(artifact);
    return inventory.where((i) => i.slot == EquipSlot.weapon && !i.isArtifact && itemLevelScore(i) > artifactScore).toList();
  }

  void forgeArtifactWeapon(String fodderItemId) {
    final artifact = equippedArtifactWeapon;
    if (artifact == null) {
      message = tr("Musíš mít nasazenou artefaktovou zbraň.", "You must have the artifact weapon equipped.");
      notifyListeners();
      return;
    }
    if (materials < artifactForgeMaterialsCost) {
      message = tr("Nedostatek surovin (potřeba $artifactForgeMaterialsCost ⚒️).", "Not enough materials (needed: $artifactForgeMaterialsCost ⚒️).");
      notifyListeners();
      return;
    }
    final fodderIdx = inventory.indexWhere((i) => i.id == fodderItemId);
    if (fodderIdx == -1) {
      message = tr("Tahle zbraň už není v batohu.", "This weapon is no longer in your bag.");
      notifyListeners();
      return;
    }
    final fodder = inventory[fodderIdx];
    if (fodder.slot != EquipSlot.weapon || fodder.isArtifact) {
      message = tr("Na vylepšení jde obětovat jen běžnou zbraň, ne artefakt.", "Only a regular weapon can be sacrificed for the upgrade, not the artifact.");
      notifyListeners();
      return;
    }
    if (itemLevelScore(fodder) <= itemLevelScore(artifact)) {
      message = tr("Tahle zbraň není silnější než tvůj artefakt - nejde ji použít k vylepšení.", "This weapon is not stronger than your artifact - it cannot be used for the upgrade.");
      notifyListeners();
      return;
    }
    materials -= artifactForgeMaterialsCost;
    inventory.removeAt(fodderIdx);
    artifact.artifactWeaponForgeLevel++;
    message = tr("⚒️✨ Artefaktová zbraň vylepšena! Forge úroveň ${artifact.artifactWeaponForgeLevel} (+${(artifact.artifactWeaponForgeLevel * Item.artifactForgeBonusPerLevel * 100).round()} % ke statům).", "⚒️✨ Artifact weapon upgraded! Forge level ${artifact.artifactWeaponForgeLevel} (+${(artifact.artifactWeaponForgeLevel * Item.artifactForgeBonusPerLevel * 100).round()}% to stats).");
    if (artifact.artifactWeaponForgeLevel == 1) _queueContextTip(TutorialTipId.tipArtifactForge);
    notifyListeners();
  }



  // Prsten Osudu - artefakt, garantovaný jednorázový drop z bosse v Lair 100 (viz _handleLairBossDeath).
  // Vysoká Vitalita + bonus na všechny 4 hlavní staty (nezávislý na volbě třídy), 6 gem slotů
  // (mechanika gemů TBD), nelze zničit/prodat/roztavit (viz salvageItem). Všechny 4 staty škálují
  // s levelem hráče (10 × level) místo pevných čísel - artefakt tak zůstává relevantní i pozdě ve hře.
  Item _createFateRing() {
    return Item(
      name: "Prsten Osudu",
      value: 999999,
      stats: {
        "Vitality": 10 * level,
        "Strength": 10 * level,
        "Agility": 10 * level,
        "Wisdom": 10 * level,
      },
      rarity: Rarity.artifact,
      slot: EquipSlot.ring,
      isArtifact: true,
      gemSlotCount: 6,
    );
  }

  // ===== CENTRÁLNÍ VÝPOČET STATŮ (Strength, Agility, Wisdom, Vitality) =====
  // Každý stat se počítá takto:
  //   1. Základ = talentové body (přímo) + body z itemů (vynásobené Paragon bonusem, pokud platí)
  //   2. Na základ se navíc aplikuje +1 % za KAŽDÝ investovaný talentový bod do TOHOTO statu
  //      (tj. talent nejen přidá 1 bod, ale zesílí i všechny ostatní zdroje stejného statu).
  double _itemStatSum(String statName) {
    double sum = 0;
    for (var item in equipment) {
      if (item.stats.containsKey(statName)) {
        sum += item.stats[statName]! * paragonMultiplierFor(statName) * item.upgradeMultiplier * setSlotUpgradeMultiplier(item);
      }
    }
    return sum;
  }

  // BUG FIX 2 (viz konverzace o balance - "itemy dávají staty ve velkém, uvažuj Kovárnu na ranku
  // 100 a hardcore Paragon"): první oprava (multiplikátor ze SOUČTU item+talent) vypadala rozumně
  // izolovaně, ale item staty mají VLASTNÍ neomezený násobič (paragonMultiplierFor, roste lineárně
  // s Paragonem navždy) - takže `base` u gearnutého hardcore hrdiny byl už tak obrovský (v řádu
  // tisíců), že násobení SEBE SAMA (`base*(1+base*k)`) druhotně explodovalo úplně stejně jako
  // předtím, jen to teď spouštěl gear místo talent bodů (ověřeno: Paragon 37 + Kovárna rank 100,
  // JEN ze 4 kusů gearu, 0 talent bodů → 99,8 % Block capu). Item staty (+ z nich odvozené relic/
  // set bonusy - taky nejsou VOLBA hráče, jen odměna z gearu) se teď přičítají AŽ ZA
  // multiplikátorem, beze změny. Multiplikátor `points*(1+points*k)` počítá VÝHRADNĚ z
  // talentových bodů - jít do jednoho statu pořád dává reálnou výhodu (ten stat dostane svůj
  // vlastní bonus), ale gear už ho druhotně nezesiluje.
  double get totalStrength {
    final int points = talents["Strength"]!;
    final double itemAndGearBonuses = _itemStatSum("Strength") + ((heroClass==HeroClass.warrior||heroClass==HeroClass.deathknight||heroClass==HeroClass.duelist||heroClass==HeroClass.monk)?specRelicMainStatBonus:0) + eliteSetMainStatBonus("Strength");
    return itemAndGearBonuses + points * (1 + points * 0.0025);
  }

  double get totalAgility {
    final int points = talents["Agility"]!;
    final double itemAndGearBonuses = _itemStatSum("Agility") + (heroClass==HeroClass.hunter?specRelicMainStatBonus:0) + eliteSetMainStatBonus("Agility");
    return itemAndGearBonuses + points * (1 + points * 0.0025);
  }

  double get totalWisdom {
    final int points = talents["Wisdom"]!;
    final double itemAndGearBonuses = _itemStatSum("Wisdom") + ((heroClass==HeroClass.mage||heroClass==HeroClass.healer)?specRelicMainStatBonus:0) + eliteSetMainStatBonus("Wisdom");
    return itemAndGearBonuses + points * (1 + points * 0.0025);
  }

  double get totalVitality {
    final int points = talents["Vitality"]!;
    final double itemAndGearBonuses = _itemStatSum("Vitality") + specRelicVitalityBonus + eliteSetMainStatBonus("Vitality");
    return itemAndGearBonuses + points * (1 + points * 0.0025);
  }

  int get itemBonusHp {
    int total = 0;
    for (var item in equipment) {
      if (item.stats.containsKey("HP")) total += (item.stats["HP"]! * item.upgradeMultiplier * setSlotUpgradeMultiplier(item)).round();
    }
    for (var c in activeCompanions) {
      if (c.role == CompanionRole.tank) total += c.level * 100;
    }
    return total;
  }

  int get itemBonusPhysAtk {
    int total = 0;
    for (var item in equipment) {
      if (item.stats.containsKey("P.ATK")) total += (item.stats["P.ATK"]! * item.upgradeMultiplier * setSlotUpgradeMultiplier(item)).round();
    }
    return total + companionPhysBonus;
  }

  int get itemBonusMagAtk {
    int total = 0;
    for (var item in equipment) {
      if (item.stats.containsKey("M.ATK")) total += (item.stats["M.ATK"]! * item.upgradeMultiplier * setSlotUpgradeMultiplier(item)).round();
    }
    return total + companionMagBonus;
  }

  int get classMultiplier => classRanks[heroClass] ?? 1;

  // PARAGON SYSTÉM
  // Za každých 100 ranků aktuální třídy hráč získá 1 Paragon level.
  // Rank 100 = Paragon 1, Rank 250 = Paragon 2, Rank 999 = Paragon 9... roste bez stropu.
  int get paragonLevel => classMultiplier ~/ 100;

  // Paragon 150 - odemyká nový "signature" základní útok, který nahradí volbu
  // Fyzický/Magický útok jedním tématickým útokem se synergií na identitu třídy.
  bool get hasParagon150 => paragonLevel >= 15;

  // Každá třída má jen JEDEN typ základního útoku (žádná volba hráče) - fyzický je výchozí,
  // magický jen pro čistě kouzelnické třídy. Deathknight je hybrid a v fight() počítá poškození
  // z obou statů bez ohledu na tuhle hodnotu (viz "heroClass == HeroClass.deathknight" větev),
  // takže mu na hodnotě fakticky nezáleží.
  bool get classIsMagicAttack => heroClass == HeroClass.mage || heroClass == HeroClass.healer || heroClass == HeroClass.druid || heroClass == HeroClass.necromancer;

  String get signatureAttackLabel {
    switch (heroClass) {
      case HeroClass.warrior:
        return "Hněv šampiona";
      case HeroClass.hunter:
        return "Znamení lovce";
      case HeroClass.healer:
        return "Trest Světla";
      case HeroClass.deathknight:
        return "Runová trhlina";
      case HeroClass.mage:
        return "Arkánový výbuch";
      case HeroClass.duelist:
        return "Elegantní výpad";
      case HeroClass.monk:
        return "Plynoucí Čchi";
      case HeroClass.druid:
        return "Volání Divočiny";
      case HeroClass.paladin:
        return "Posvěcený Úder";
      case HeroClass.demonhunter:
        return "Fel Vzplanutí";
      case HeroClass.necromancer:
        return "Dotek Smrti";
      case HeroClass.none:
        return "Útok";
    }
  }

  // ============================================================
  // PARAGON 50 — SPECIALIZACE (tři odlišné build cesty na třídu)
  // ============================================================
  // 0 = žádná zvolená, 1/2/3 = zvolená větev (význam závisí na heroClass, viz specializationName).
  // Permanentní jako Paragon/classRanks - nereseuje se smrtí. Respec za zlato (viz respecSpecialization()).
  int specialization = 0;

  static const int specializationUnlockLevel = 25; // + Paragon 10 (viz canChooseSpecialization)
  bool get canChooseSpecialization => level >= specializationUnlockLevel && paragonLevel >= 10;

  static const int _respecCost = 5000;
  int get respecCost => _respecCost;

  String get specializationName {
    if (specialization == 0) return tr("Žádná", "None");
    switch (heroClass) {
      case HeroClass.warrior:
        return specialization == 1 ? tr("Berserk", "Berserker") : (specialization == 2 ? tr("Ochránce", "Protector") : tr("Krvežíznivý", "Bloodthirsty"));
      case HeroClass.hunter:
        return specialization == 1 ? tr("Stopař", "Tracker") : (specialization == 2 ? tr("Divočina", "Wilderness") : tr("Stín", "Shadow"));
      case HeroClass.healer:
        return specialization == 1 ? tr("Světlo", "Light") : (specialization == 2 ? tr("Odplata", "Retribution") : tr("Battle Priest", "Battle Priest"));
      case HeroClass.deathknight:
        return specialization == 1 ? tr("Krev", "Blood") : (specialization == 2 ? tr("Mráz", "Frost") : tr("Nákaza", "Plague"));
      case HeroClass.mage:
        return specialization == 1 ? tr("Plamen", "Flame") : (specialization == 2 ? tr("Led", "Ice") : tr("Aether", "Aether"));
      case HeroClass.duelist:
        return specialization == 1 ? tr("Vendetta", "Vendetta") : (specialization == 2 ? tr("Grácie", "Grace") : tr("Virtuóz", "Virtuoso"));
      case HeroClass.monk:
        return specialization == 1 ? tr("Vichr", "Gale") : (specialization == 2 ? tr("Skála", "Stone") : tr("Klid", "Serenity"));
      case HeroClass.druid:
        return specialization == 1 ? tr("Rovnováha", "Balance") : (specialization == 2 ? tr("Divoký tvar", "Wild Shape") : tr("Obnova", "Restoration"));
      case HeroClass.paladin:
        return specialization == 1 ? tr("Ochránce Víry", "Protector of Faith") : (specialization == 2 ? tr("Trestající", "Retribution") : tr("Posvěcený", "Consecrated"));
      case HeroClass.demonhunter:
        return specialization == 1 ? tr("Zkáza", "Havoc") : (specialization == 2 ? tr("Pomsta", "Vengeance") : tr("Stín Propasti", "Shadow of the Abyss"));
      case HeroClass.necromancer:
        return specialization == 1 ? tr("Vládce Kostí", "Bone Lord") : (specialization == 2 ? tr("Morová Kletba", "Plague Curse") : tr("Krvavý Rituál", "Blood Ritual"));
      case HeroClass.none:
        return tr("Žádná", "None");
    }
  }

  // Stejné jméno specializace jako specializationNameFor(), ale pro LIBOVOLNOU třídu, ne jen tu
  // aktuálně hranou - potřeba pro Arénu, kde soupeřova třída != heroClass hráče.
  String specNameForClass(HeroClass cls, int spec) {
    switch (cls) {
      case HeroClass.warrior:
        return spec == 1 ? tr("Berserk", "Berserker") : (spec == 2 ? tr("Ochránce", "Protector") : tr("Krvežíznivý", "Bloodthirsty"));
      case HeroClass.hunter:
        return spec == 1 ? tr("Stopař", "Tracker") : (spec == 2 ? tr("Divočina", "Wilderness") : tr("Stín", "Shadow"));
