      case HeroClass.hunter: return spec == 1 ? "CRIT DPS" : (spec == 2 ? "TEMPO / SUSTAIN" : "DOT / DODGE DPS");
      case HeroClass.healer: return spec == 1 ? "HEAL / SHIELD" : (spec == 2 ? "REFLECT HYBRID" : "MAGIC DPS");
      case HeroClass.deathknight: return spec == 1 ? "DRAIN TANK" : (spec == 2 ? "BURST CRIT DPS" : "DOT DPS");
      case HeroClass.mage: return spec == 1 ? "BURST / DOT DPS" : (spec == 2 ? "SHIELD CONTROL" : "RESOURCE TEMPO DPS");
      case HeroClass.duelist: return spec == 1 ? "EXECUTE DPS" : (spec == 2 ? "EVASION COUNTER" : "CRIT TEMPO DPS");
      case HeroClass.monk: return spec == 1 ? "COMBO DPS" : (spec == 2 ? "TANK" : "HEAL HYBRID");
      case HeroClass.druid: return spec == 1 ? "MAGIC DOT/BURST DPS" : (spec == 2 ? "PHYS TANK HYBRID" : "HEAL / SUSTAIN");
      case HeroClass.paladin: return spec == 1 ? "TANK / BLOCK" : (spec == 2 ? "BURST PHYS DPS" : "HEAL / HYBRID TANK");
      case HeroClass.demonhunter: return spec == 1 ? "MOBILE CRIT DPS" : (spec == 2 ? "LIFESTEAL TANK" : "DOT / CRIT HYBRID");
