  String specializationFantasyFor(int spec) {
    switch (heroClass) {
      case HeroClass.warrior:
        return spec == 1 ? tr("Agresivní válečník, který mění obranu za silný okamžitý tlak.", "An aggressive warrior who trades defense for powerful immediate pressure.")
          : spec == 2 ? tr("Nezlomný obránce stavějící na bloku, štítech a přežití dlouhého boje.", "An unbreakable defender built around blocking, shields, and surviving long fights.")
          : tr("Krvavý bojovník, který nepřítele oslabuje krvácením a déle vydrží v boji.", "A bloodied fighter who weakens the enemy with bleeds and outlasts them in combat.");
      case HeroClass.hunter:
        return spec == 1 ? tr("Přesný lovec budující Znamení lovce a připravující ničivé kritické zásahy.", "A precise hunter building Hunter's Mark stacks and setting up devastating critical hits.")
          : spec == 2 ? tr("Pohyblivý lovec s efektivnějšími schopnostmi, úhybem a stabilním sustainem.", "A mobile hunter with more efficient abilities, dodge, and steady sustain.")
          : tr("Stínový lovec spoléhající na jed, poškození v čase a vyhýbání útokům.", "A shadow hunter relying on poison, damage over time, and evading attacks.");
      case HeroClass.healer:
        return spec == 1 ? tr("Čistá podpůrná větev zaměřená na léčení, absorb a bezpečný postup.", "A pure support branch focused on healing, absorption, and safe progress.")
          : spec == 2 ? tr("Hybrid, který část obrany převádí na odražené poškození proti nepříteli.", "A hybrid that converts part of its defense into damage reflected back at the enemy.")
          : tr("Ofenzivní kněz obětující část podpory za výrazně vyšší magické poškození.", "An offensive priest sacrificing some support for significantly higher magic damage.");
      case HeroClass.deathknight:
        return spec == 1 ? tr("Odolný rytíř smrti využívající vysávání života, štíty a fyzicko-magický tlak.", "A resilient death knight using life drain, shields, and physical-magical pressure.")
          : spec == 2 ? tr("Kritická burst větev soustředěná na rychlé fyzické zásahy a výbuchy prokletí.", "A critical burst branch focused on fast physical strikes and curse detonations.")
          : tr("Morový rytíř prodlužující prokletí a rozkládající nepřítele poškozením v čase.", "A plague knight who prolongs curses and wears the enemy down with damage over time.");
      case HeroClass.mage:
        return spec == 1 ? tr("Výbušný mág s vysokým přímým poškozením a ohnivým DoT.", "An explosive mage with high direct damage and fire DoT.")
          : spec == 2 ? tr("Obranný mág proměňující kouzla ve štíty a kontrolovaný dlouhý boj.", "A defensive mage converting spells into shields for a controlled, prolonged fight.")
          : tr("Arkánový specialista budující Arcane Charge a vítězící přes tempo a efektivitu zdrojů.", "An arcane specialist building Arcane Charge and winning through tempo and resource efficiency.");
      case HeroClass.duelist:
        return spec == 1 ? tr("Popravčí duelista zesilující útoky proti nepříteli s nízkými životy.", "An executioner duelist who strengthens attacks against low-HP enemies.")
          : spec == 2 ? tr("Úhybový šermíř trestající nepřátelské útoky protiútokem.", "An evasive swordsman who punishes enemy attacks with a counterattack.")
          : tr("Technický kritik s levnějšími schopnostmi, kratšími cooldowny a přesnými zásahy.", "A technical critical striker with cheaper abilities, shorter cooldowns, and precise hits.");
      case HeroClass.monk:
        return spec == 1 ? tr("Rychlý útočník budující Plynoucí Čchi a řetězící silná komba.", "A fast striker building Flowing Chi and chaining powerful combos.")
          : spec == 2 ? tr("Kamenný tank převádějící schopnosti na štíty a odolnost.", "A stone tank converting abilities into shields and resilience.")
          : tr("Klidný hybrid kombinující fyzické útoky, léčení a obranné posílení.", "A serene hybrid combining physical attacks, healing, and defensive buffs.");
      case HeroClass.druid:
        return spec == 1 ? tr("Astrální kouzelník budující tlak přírodní magií a DoT efekty na dálku.", "An astral spellcaster building pressure with nature magic and ranged DoT effects.")
          : spec == 2 ? tr("Tvaroměnič, který se mění do zvířecí podoby pro fyzický tlak a odolnost.", "A shapeshifter who takes animal form for physical pressure and resilience.")
          : tr("Přírodní léčitel udržující tým naživu regenerací a ochrannými symbioly.", "A nature healer keeping the party alive through regeneration and protective symbiosis.");
      case HeroClass.paladin:
        return spec == 1 ? tr("Nezlomný obránce s vysokým blokem a velkými svatými štíty.", "An unbreakable defender with high block and large holy shields.")
          : spec == 2 ? tr("Trestající bojovník, který mění svatý hněv v okamžitý fyzický burst.", "A retributive fighter who turns holy wrath into immediate physical burst.")
          : tr("Posvěcený hybrid kombinující fyzické útoky s vlastním léčením a odolností.", "A consecrated hybrid combining physical attacks with self-healing and resilience.");
      case HeroClass.demonhunter:
        return spec == 1 ? tr("Mobilní útočník dvojitých čepelí soustředěný na kritické zásahy a rychlé ukončení boje.", "A mobile dual-blade striker focused on critical hits and quickly finishing fights.")
          : spec == 2 ? tr("Fel-posílený tank vysávající život z nepřítele démonickou energií.", "A fel-empowered tank draining life from the enemy with demonic energy.")
          : tr("Hybrid kombinující fel poškození v čase s vysokou šancí na kritický zásah.", "A hybrid combining fel damage over time with a high chance to land critical hits.");
      case HeroClass.necromancer:
        return spec == 1 ? tr("Přivolává kostěné sluhy, kteří bojují po jeho boku a znásobují magický tlak.", "Summons bone servants that fight at its side and multiply magic pressure.")
          : spec == 2 ? tr("Rozkladač prokletí a moru, co nepřítele pomalu zabíjí poškozením v čase.", "A curse and plague weaver that slowly kills the enemy with damage over time.")
          : tr("Krví a smrtí čerpá život z nepřítele pro vlastní přežití.", "Draws life from the enemy through blood and death for its own survival.");
      case HeroClass.none: return "";
    }
  }

  String specializationStrengthsFor(int spec) {
    switch (heroClass) {
      case HeroClass.warrior: return spec == 1 ? tr("Burst, vysoký ability damage, rychlé ukončení boje", "Burst, high ability damage, fast fight endings") : spec == 2 ? tr("Block, silné štíty, stabilita proti bossům", "Block, strong shields, stability against bosses") : tr("Bleed, sustain, dobrý výkon v dlouhém boji", "Bleed, sustain, good performance in long fights");
      case HeroClass.hunter: return spec == 1 ? tr("Crit scaling, silná Znamení lovce, přesný single target", "Crit scaling, strong Hunter's Mark, precise single target") : spec == 2 ? tr("Nižší náklady, kratší cooldowny, heal a dodge", "Lower costs, shorter cooldowns, heal and dodge") : tr("Jed, dlouhý DoT tlak, vysoký dodge", "Poison, sustained DoT pressure, high dodge");
      case HeroClass.healer: return spec == 1 ? tr("Nejvyšší heal, absorb, bezpečnost", "Highest heal, absorb, safety") : spec == 2 ? tr("Reflect, hybridní obrana a damage", "Reflect, hybrid defense and damage") : tr("Nejvyšší přímé magické poškození Healera", "Healer's highest direct magic damage");
      case HeroClass.deathknight: return spec == 1 ? tr("Lifesteal, štíty, výdrž", "Lifesteal, shields, endurance") : spec == 2 ? tr("Crit burst, rychlé exploze prokletí", "Crit burst, fast curse detonations") : tr("Dlouhá prokletí, DoT, opakované aplikace", "Long curses, DoT, repeated applications");
      case HeroClass.mage: return spec == 1 ? tr("Vysoký burst, oheň, silné krátké boje", "High burst, fire, strong short fights") : spec == 2 ? tr("Štíty, bezpečný casting, kontrola", "Shields, safe casting, control") : tr("Arcane Charge, resource tempo, kratší cooldowny", "Arcane Charge, resource tempo, shorter cooldowns");
      case HeroClass.duelist: return spec == 1 ? tr("Execute, silné dokončení bossů", "Execute, strong boss finishing") : spec == 2 ? tr("Dodge, counter-attack, vysoké přežití", "Dodge, counter-attack, high survivability") : tr("Crit, levnější schopnosti, rychlá rotace", "Crit, cheaper abilities, fast rotation");
      case HeroClass.monk: return spec == 1 ? tr("Combo damage, rychlý tlak", "Combo damage, fast pressure") : spec == 2 ? tr("Štíty, redukce poškození, tankování", "Shields, damage reduction, tanking") : tr("Heal, sustain, univerzálnost", "Heal, sustain, versatility");
      case HeroClass.druid: return spec == 1 ? tr("Vysoký DoT tlak, magický burst na dálku", "High DoT pressure, ranged magic burst") : spec == 2 ? tr("Fyzická odolnost, štíty ze zvířecí formy", "Physical resilience, shields from animal form") : tr("Nejvyšší heal ze všech tříd, dlouhodobý sustain", "Highest heal of all classes, long-term sustain");
      case HeroClass.paladin: return spec == 1 ? tr("Nejvyšší block/štít ze všech tanků, extrémní stabilita", "Highest block/shield of all tanks, extreme stability") : spec == 2 ? tr("Vysoký fyzický burst, silné dokončení boje", "High physical burst, strong fight finishing") : tr("Vyvážený mix damage, healu a odolnosti", "Balanced mix of damage, healing, and resilience");
      case HeroClass.demonhunter: return spec == 1 ? tr("Nejvyšší crit ze všech tříd, extrémně rychlá rotace", "Highest crit of all classes, extremely fast rotation") : spec == 2 ? tr("Silný lifesteal, dobrá výdrž v dlouhém boji", "Strong lifesteal, good endurance in long fights") : tr("Vyvážený DoT + crit tlak, flexibilní", "Balanced DoT + crit pressure, flexible");
      case HeroClass.necromancer: return spec == 1 ? tr("Nejvyšší magický DPS s pet synergií, silný burst", "Highest magic DPS with pet synergy, strong burst") : spec == 2 ? tr("Dlouhý DoT tlak, spolehlivý proti vysoké obraně", "Sustained DoT pressure, reliable against high defense") : tr("Silný lifesteal, dobrá výdrž v dlouhém boji", "Strong lifesteal, good endurance in long fights");
      case HeroClass.none: return "";
    }
  }

  String specializationWeaknessesFor(int spec) {
    switch (heroClass) {
      case HeroClass.warrior: return spec == 1 ? tr("Slabší sustain a horší dlouhé obranné souboje", "Weaker sustain and worse in long defensive fights") : spec == 2 ? tr("Nižší damage a riziko enrage v příliš dlouhém boji", "Lower damage and enrage risk in overly long fights") : tr("Pomalejší náběh a závislost na DoT", "Slower ramp-up and reliance on DoT");
      case HeroClass.hunter: return spec == 1 ? tr("Potřebuje crit a stacky; slabší při krátké špatné rotaci", "Needs crit and stacks; weaker on a short, poorly-timed rotation") : spec == 2 ? tr("Nižší damage na jeden zásah", "Lower damage per hit") : tr("DoT potřebuje čas a trpí proti rychlým encounterům", "DoT needs time and suffers against fast encounters");
      case HeroClass.healer: return spec == 1 ? tr("Nejnižší přímý damage", "Lowest direct damage") : spec == 2 ? tr("Výkon závisí na příchozím poškození a štítech", "Performance depends on incoming damage and shields") : tr("Slabší heal a absorb než podpůrné větve", "Weaker heal and absorb than the support branch");
      case HeroClass.deathknight: return spec == 1 ? tr("Nižší burst", "Lower burst") : spec == 2 ? tr("Slabší sustain a závislost na critu", "Weaker sustain and reliance on crit") : tr("Pomalejší damage a slabší okamžité ukončení boje", "Slower damage and weaker immediate fight-ending power");
      case HeroClass.mage: return spec == 1 ? tr("Nižší sustain a citlivost na dlouhý boj", "Lower sustain and vulnerability in long fights") : spec == 2 ? tr("Nižší přímý damage", "Lower direct damage") : tr("Potřebuje vybudovat Arcane Charge a správně řídit manu", "Needs to build up Arcane Charge and manage mana carefully");
      case HeroClass.duelist: return spec == 1 ? tr("Hlavní bonus se projeví až při nízkém HP nepřítele", "The main bonus only kicks in once the enemy is at low HP") : spec == 2 ? tr("Nižší damage a závislost na úspěšném dodge", "Lower damage and reliance on successful dodges") : tr("Menší obranná rezerva", "Smaller defensive buffer");
      case HeroClass.monk: return spec == 1 ? tr("Nižší obrana a sustain", "Lower defense and sustain") : spec == 2 ? tr("Nízký přímý damage", "Low direct damage") : tr("Nižší specializovaný strop než čistý DPS nebo tank", "Lower specialized ceiling than a pure DPS or tank");
      case HeroClass.druid: return spec == 1 ? tr("Nízká obrana, závislost na DoT náběhu", "Low defense, reliance on DoT ramp-up") : spec == 2 ? tr("Nižší damage než čistý DPS", "Lower damage than a pure DPS") : tr("Nejnižší přímý damage ze všech specializací", "Lowest direct damage of all specializations");
      case HeroClass.paladin: return spec == 1 ? tr("Nejnižší damage ze všech Paladinových větví", "Lowest damage of all Paladin branches") : spec == 2 ? tr("Nižší obrana, méně sustainu", "Lower defense, less sustain") : tr("Nižší strop v obou směrech než čisté specializace", "Lower ceiling in both directions than the pure specializations");
      case HeroClass.demonhunter: return spec == 1 ? tr("Nízká obrana, křehký proti burst poškození", "Low defense, fragile against burst damage") : spec == 2 ? tr("Nižší damage než čisté DPS větve", "Lower damage than the pure DPS branch") : tr("Nižší strop v obou směrech než čisté specializace", "Lower ceiling in both directions than the pure specializations");
      case HeroClass.necromancer: return spec == 1 ? tr("Nízká obrana, křehký proti burst poškození", "Low defense, fragile against burst damage") : spec == 2 ? tr("DoT potřebuje čas, slabší proti rychlým encounterům", "DoT needs time, weaker against fast encounters") : tr("Nižší přímý damage než čisté DPS větve", "Lower direct damage than the pure DPS branch");
      case HeroClass.none: return "";
    }
  }

  String specializationRecommendedBuildFor(int spec) {
    switch (heroClass) {
      case HeroClass.warrior: return spec == 1 ? "Strength, Crit, Crit Damage • Krvavý Vztek" : spec == 2 ? "Vitality, Block, Shield • Nezdolná Pevnost" : "Strength, Bleed, Lifesteal • Krvavá Žeň";
      case HeroClass.hunter: return spec == 1 ? "Agility, Crit, Crit Damage • Neomylná Stopa" : spec == 2 ? "Agility, Dodge, cooldown • Divoký Hon" : "Agility, Dodge, Poison/DoT • Stínový Vládce";
      case HeroClass.healer: return spec == 1 ? "Wisdom, Heal, Shield • Posvátné Světlo" : spec == 2 ? "Wisdom, Shield, Reflect • Božská Odplata" : "Wisdom, Crit, Magic Damage • Bojový Kněz";
      case HeroClass.deathknight: return spec == 1 ? "Strength, Lifesteal, Shield • Krvavý Pakt" : spec == 2 ? "Strength, Crit, Crit Damage • Věčný Mráz" : "Wisdom, DoT, Curse duration • Morová Rána";
      case HeroClass.mage: return spec == 1 ? "Wisdom, Magic Damage, DoT • Věčný Plamen" : spec == 2 ? "Wisdom, Shield, cooldown • Věčný Led" : "Wisdom, resource efficiency, cooldown • Arkánová Nekonečnost";
      case HeroClass.duelist: return spec == 1 ? "Agility, Execute, Crit • Krvavá Msta" : spec == 2 ? "Agility, Dodge, Counter • Elegantní Tanec" : "Agility, Crit, cooldown • Mistrovská Čepel";
      case HeroClass.monk: return spec == 1 ? "Wisdom, Crit, Combo • Vichr Bouře" : spec == 2 ? "Vitality, Shield, Dodge • Skalní Pevnost" : "Wisdom, Heal, sustain • Tichá Meditace";
      case HeroClass.druid: return spec == 1 ? "Wisdom, DoT, Crit • Astrální Tlak" : spec == 2 ? "Wisdom, Vitality, Shield • Forma Medvěda" : "Wisdom, Heal, Vitality • Srdce Lesa";
      case HeroClass.paladin: return spec == 1 ? "Strength, Block, Shield • Posvátný Val" : spec == 2 ? "Strength, Crit, Crit Damage • Boží Trest" : "Strength, Vitality, Heal • Posvěcená Cesta";
      case HeroClass.demonhunter: return spec == 1 ? "Agility, Crit, Crit Damage • Čepele Zkázy" : spec == 2 ? "Agility, Lifesteal, Vitality • Pomsta Propasti" : "Agility, DoT, Crit • Stín Propasti";
      case HeroClass.necromancer: return spec == 1 ? "Wisdom, Crit, Magic Damage • Armáda Nemrtvých" : spec == 2 ? "Wisdom, DoT, Curse duration • Vládce Rozkladu" : "Wisdom, Lifesteal, Vitality • Pakt s Podsvětím";
      case HeroClass.none: return "";
    }
  }

  String specializationDescriptionFor(int spec) {
    switch (heroClass) {
      case HeroClass.warrior:
        if (spec == 1) return tr("+20 % damage na všech schopnostech, -25 % štít/sustain z abilit.", "+20% damage on all abilities, -25% shield/sustain from abilities.");
        if (spec == 2) return tr("-15 % damage, +50 % štít z abilit, +5 % flat block chance.", "-15% damage, +50% shield from abilities, +5% flat block chance.");
        return tr("Fyzické ability navíc aplikují krvácení (20 % dmg / 3 kola). Damage beze změny.", "Physical abilities additionally apply bleed (20% dmg / 3 rounds). Damage unchanged.");
      case HeroClass.hunter:
        if (spec == 1) return tr("+15 % crit chance na abilitách. Znamení lovce: max 8 stacků, +4 % dmg/stack.", "+15% crit chance on abilities. Hunter's Mark: max 8 stacks, +4% dmg/stack.");
        if (spec == 2) return tr("Náklady schopností -25 %, cooldowny -20 %, +5 % dodge.", "Ability costs -25%, cooldowns -20%, +5% dodge.");
        return tr("Ability navíc aplikují jed (10 % dmg / 3 kola). +10 % dodge passivně.", "Abilities additionally apply poison (10% dmg / 3 rounds). +10% dodge passively.");
      case HeroClass.healer:
        if (spec == 1) return tr("Heal/štít z abilit +30 %. Božská odplata 10 % → 15 %.", "Heal/shield from abilities +30%. Divine Retribution 10% → 15%.");
        if (spec == 2) return tr("Božská odplata 10 % → 25 %. Heal/štít z abilit -15 %.", "Divine Retribution 10% → 25%. Heal/shield from abilities -15%.");
        return tr("Damage abilit +15 %. Heal/štít i reflect beze změny.", "Ability damage +15%. Heal/shield and reflect unchanged.");
      case HeroClass.deathknight:
        if (spec == 1) return tr("Lifesteal ze všech zdrojů +40 %. Damage -15 %.", "Lifesteal from all sources +40%. Damage -15%.");
        if (spec == 2) return tr("Fyzická složka hybridního útoku +25 %. Prokletí trvá o 1 kolo méně. Runová trhlina crit +10 %.", "Physical component of the hybrid attack +25%. Curse lasts 1 round less. Rune Rift crit +10%.");
        return tr("Magická/DoT složka +25 %. Prokletí lze prodloužit až na 9 kol. Dmg/kolo Prokletí +20 %.", "Magic/DoT component +25%. Curse can be extended up to 9 rounds. Curse dmg/round +20%.");
      case HeroClass.mage:
        if (spec == 1) return tr("+20 % damage na všech schopnostech. Damage ability navíc aplikují Popálení (15 % dmg / 3 kola).", "+20% damage on all abilities. Damage abilities additionally apply Burn (15% dmg / 3 rounds).");
        if (spec == 2) return tr("-15 % damage, +40 % štít/ward z abilit (i signature útok).", "-15% damage, +40% shield/ward from abilities (including the signature attack).");
        return tr("Náklady many -25 %, cooldowny -20 %. Arcane Charge stacky rostou o 50 % rychleji.", "Mana costs -25%, cooldowns -20%. Arcane Charge stacks build 50% faster.");
      case HeroClass.duelist:
        if (spec == 1) return tr("+20 % damage na všech schopnostech. +30 % damage navíc proti nepříteli pod 30 % HP.", "+20% damage on all abilities. An additional +30% damage against enemies below 30% HP.");
        if (spec == 2) return tr("-15 % damage, +10 % flat dodge chance. Signature útok navíc uděluje counter-attack šanci.", "-15% damage, +10% flat dodge chance. The signature attack additionally grants a counter-attack chance.");
        return tr("Náklady Mrštnosti -25 %, cooldowny -20 %, +15 % crit chance na abilitách.", "Agility costs -25%, cooldowns -20%, +15% crit chance on abilities.");
      case HeroClass.monk:
        if (spec == 1) return tr("Vichr (DMG): +20 % damage na všech schopnostech. Fyzické ability navíc aplikují krvácení (15 % dmg / 3 kola).", "Gale (DMG): +20% damage on all abilities. Physical abilities additionally apply bleed (15% dmg / 3 rounds).");
        if (spec == 2) return tr("Skála (Tank): -15 % damage, +40 % heal/štít z abilit, +2,5 % flat dodge. 30 % obdrženého poškození se přemění na krvácení místo přímého zásahu.", "Stone (Tank): -15% damage, +40% heal/shield from abilities, +2.5% flat dodge. 30% of damage taken is converted into bleed instead of a direct hit.");
        return tr("Klid (Heal): abilita navíc vyléčí 25 % způsobeného poškození jako HP - meditativní léčivý styl boje.", "Serenity (Heal): abilities additionally heal 25% of damage dealt as HP - a meditative healing combat style.");
      case HeroClass.druid:
        if (spec == 1) return tr("Rovnováha (DMG): +20 % damage na všech schopnostech. Magické ability navíc aplikují Uvadnutí (15 % dmg / 3 kola).", "Balance (DMG): +20% damage on all abilities. Magic abilities additionally apply Wither (15% dmg / 3 rounds).");
        if (spec == 2) return tr("Divoký tvar (Tank): -15 % damage, +45 % štít z abilit, +5 % flat block chance ze zvířecí kůže.", "Wild Shape (Tank): -15% damage, +45% shield from abilities, +5% flat block chance from animal hide.");
        return tr("Obnova (Heal): heal/štít z abilit +35 %. Signature útok navíc vyléčí 15 % způsobeného poškození jako HP.", "Restoration (Heal): heal/shield from abilities +35%. The signature attack additionally heals 15% of damage dealt as HP.");
      case HeroClass.paladin:
        if (spec == 1) return tr("Ochránce Víry (Tank): -15 % damage, +50 % štít z abilit, +7,5 % flat block chance.", "Protector of Faith (Tank): -15% damage, +50% shield from abilities, +7.5% flat block chance.");
        if (spec == 2) return tr("Trestající (DMG): +20 % damage na všech schopnostech, -25 % štít/sustain z abilit.", "Retribution (DMG): +20% damage on all abilities, -25% shield/sustain from abilities.");
        return tr("Posvěcený (Hybrid): heal/štít z abilit +25 %. Fyzické ability navíc vyléčí 15 % způsobeného poškození jako HP.", "Consecrated (Hybrid): heal/shield from abilities +25%. Physical abilities additionally heal 15% of damage dealt as HP.");
      case HeroClass.demonhunter:
        if (spec == 1) return tr("Zkáza (DMG): +20 % damage na všech schopnostech, +15 % crit chance na abilitách.", "Havoc (DMG): +20% damage on all abilities, +15% crit chance on abilities.");
        if (spec == 2) return tr("Pomsta (Tank): -15 % damage, +40 % lifesteal ze všech zdrojů.", "Vengeance (Tank): -15% damage, +40% lifesteal from all sources.");
        return tr("Stín Propasti (Hybrid): fyzické ability navíc aplikují Fel oheň (15 % dmg / 3 kola).", "Shadow of the Abyss (Hybrid): physical abilities additionally apply Fel Fire (15% dmg / 3 rounds).");
      case HeroClass.necromancer:
        if (spec == 1) return tr("Vládce Kostí (DMG): +20 % damage na všech schopnostech, +15 % crit chance na abilitách (kostěný sluha zesiluje zásahy).", "Bone Lord (DMG): +20% damage on all abilities, +15% crit chance on abilities (the bone servant amplifies hits).");
        if (spec == 2) return tr("Morová Kletba (DoT): magické ability navíc aplikují Rozklad (20 % dmg / 3 kola). Damage beze změny.", "Plague Curse (DoT): magic abilities additionally apply Decay (20% dmg / 3 rounds). Damage unchanged.");
        return tr("Krvavý Rituál (Hybrid): lifesteal ze všech zdrojů +40 %. Damage -15 %.", "Blood Ritual (Hybrid): lifesteal from all sources +40%. Damage -15%.");
      case HeroClass.none:
        return "";
    }
  }

  // První volba zdarma, jakmile hráč dosáhne level 25 a Paragon 10. Další volby (respec) stojí zlato.
  void chooseSpecialization(int spec) {
    if (!canChooseSpecialization || spec < 1 || spec > 3) return;
    if (specialization == 0) {
      final oldKey = currentSpecRelicKey; // relic přiřazený fallbackem před volbou specializace (viz relicFor())
      specialization = spec;
      _migrateSpecRelicKey(oldKey, currentSpecRelicKey);
      message = tr("Zvolena specializace: ${specializationNameFor(spec)}!", "Specialization chosen: ${specializationNameFor(spec)}!");
      _triggerCelebration('SPECIALIZACE ZVOLENA!', subtitle: specializationNameFor(spec), icon: Icons.hub, color: const Color(0xFFFF8000));
      notifyListeners();
      return;
    }
    respecSpecialization(spec);
  }

  // Přenese progres (level/unlock/pity) a nasazený item ze starého klíče relicu (přiřazeného
  // fallbackem v relicFor() před volbou specializace / na starém save z doby bugu) na nový,
  // správný relic klíč po zvolení specializace. Nic nedělá, pokud se klíč nezměnil.
  void _migrateSpecRelicKey(String oldKey, String newKey) {
    if (oldKey == newKey) return;
    final lvl = specRelicLevels.remove(oldKey);
    if (lvl != null) specRelicLevels[newKey] = lvl;
    final pity = specRelicPityCounter.remove(oldKey);
    if (pity != null) specRelicPityCounter[newKey] = pity;
    if (unlockedSpecRelics.remove(oldKey)) unlockedSpecRelics.add(newKey);
    final newName = kSpecRelics.values.firstWhere((r) => r.kind.name == newKey, orElse: () => currentSpecRelic).name;
    void migrateList(List<Item> list) {
      final idx = list.indexWhere((i) => i.specRelicKey == oldKey);
      if (idx == -1) return;
      final old = list[idx];
      list[idx] = Item(
        name: newName, value: old.value, stats: old.stats, rarity: old.rarity,
        isActive: old.isActive, upgradeLevel: old.upgradeLevel, isLocked: old.isLocked,
        isArtifact: old.isArtifact, slot: old.slot, specRelicKey: newKey,
      );
    }
    // equipment je jen odvozený filtr nad inventory (isActive:true), takže stačí migrovat inventory -
    // nasazený item (isActive) se přenese včetně stavu, protože je to fyzicky tentýž seznam.
    migrateList(inventory);
  }

  void respecSpecialization(int spec) {
    if (!canChooseSpecialization || spec < 1 || spec > 3) return;
    if (spec == specialization) return;
    if (gold < respecCost) {
      message = tr("Nedostatek zlata na respec specializace! Potřeba: $respecCost.", "Not enough gold to respec your specialization! Needed: $respecCost.");
      notifyListeners();
      return;
    }
    gold -= respecCost;
    specialization = spec;
    message = tr("Respec: nová specializace ${specializationNameFor(spec)}!", "Respec: new specialization ${specializationNameFor(spec)}!");
    notifyListeners();
  }

  // ===== HARDCORE MODE + PŘEDPEKLÍ + PEKLO — exkluzivní volba obtížnosti =====
  // 0=Normal, 1=Hardcore, 2=Předpeklí, 3=Peklo. Jde mít aktivní vždy jen jednu z nich, ne
  // stackovat víc najednou - vybraná obtížnost ale pořád těží ze škálování/odměn všech nižších
  // vrstev (viz atLeastHardcore/atLeastPredpekli), takže Peklo je pořád "Hardcore × Předpeklí × Peklo"
  // silné/výnosné, jen se to navenek chová jako jeden přepínač se 4 polohami.
  void setDifficultyTier(int tier) {
    final int previousTier = difficultyTier;
    if (tier >= 1 && !hardcoreUnlocked) {
      message = tr("Hardcore mód je zamčený. Poraz bosse v Lair 100, abys ho odemkl.", "Hardcore Mode is locked. Defeat the boss in Lair 100 to unlock it.");
      notifyListeners();
      return;
    }
    if (tier >= 2 && !predpekliUnlocked) {
      message = tr("Předpeklí je zamčené. Dosáhni Hardcore tieru $predpekliUnlockHardcoreTier, abys ho odemkl (aktuálně: $hardcoreTier).", "The Netherworld is locked. Reach Hardcore tier $predpekliUnlockHardcoreTier to unlock it (currently: $hardcoreTier).");
      notifyListeners();
      return;
    }
    if (tier >= 3 && !pekloUnlocked) {
      message = tr("Peklo je zamčené. Dosáhni Hardcore tieru $pekloUnlockHardcoreTier, abys ho odemkl (aktuálně: $hardcoreTier).", "Hell is locked. Reach Hardcore tier $pekloUnlockHardcoreTier to unlock it (currently: $hardcoreTier).");
      notifyListeners();
      return;
    }
    hardcoreMode = tier == 1;
    predpekliMode = tier == 2;
    pekloMode = tier == 3;
    if (tier == 1 && previousTier != 1 && !metMaTus) {
      metMaTus = true;
      maTusIntroPending = true;
    }
    if (tier == 0) activeCurse = CurseOfFate.none; // bez Hardcore+ nedává prokletí smysl
    // Věž (Tower) se při každé skutečné změně obtížnosti resetuje na patro 1 - staré patro by
    // mělo jinou škálovací křivku (jiný difficulty multiplier) a nedávalo by smysl v novém
    // režimu pokračovat odtud. Lair/Rift/World Boss mají vlastní nezávislý reward-key systém
    // (viz lairRewardKey) a tady se nemění.
    if (tier != previousTier) {
      floor = 1;
      enemiesDefeatedOnFloor = 0;
      // Tower modifikátor (Crit/Block/Dodge/Absorb stacky nepřítele) se váže na aktuální běh Věže
      // od patra 1 - při skutečném restartu (změna obtížnosti) se maže spolu s patrem.
      towerModCritStacks = 0;
      towerModBlockStacks = 0;
      towerModDodgeStacks = 0;
      towerModAbsorbStacks = 0;
      _generateNextEnemy();
    }
    switch (tier) {
      case 0:
        message = tr("Vrátil ses do Normal módu.", "You returned to Normal mode.");
        break;
      case 1:
        message = tr("☠ Hardcore Mode aktivován. Ať tě provází štěstí.", "☠ Hardcore Mode activated. May fortune be with you.");
        break;
      case 2:
        message = tr("🔥 PŘEDPEKLÍ OTEVŘENO. Vše je teď ${predpekliDifficultyMult}× obtížnější než Hardcore - ale odměna roste úměrně.", "🔥 THE NETHERWORLD OPENS. Everything is now ${predpekliDifficultyMult}× harder than Hardcore - but the reward scales accordingly.");
        break;
      case 3:
        message = tr("😈 PEKLO OTEVŘENO. Vše je teď ${pekloDifficultyMult}× obtížnější než Předpeklí (a to je navrch Hardcore) - odměna roste úměrně.", "😈 HELL OPENS. Everything is now ${pekloDifficultyMult}× harder than the Netherworld (on top of Hardcore) - the reward scales accordingly.");
        break;
    }
    _checkAchievements();
    notifyListeners();
  }

