  void selectCurse(CurseOfFate curse) {
    if (!atLeastHardcore) {
      message = tr("Prokletí lze vybrat jen v Hardcore módu.", "A curse can only be chosen in Hardcore mode.");
      notifyListeners();
      return;
    }
    activeCurse = curse;
    message = curse == CurseOfFate.none ? tr("Prokletí zrušeno.", "Curse cleared.") : tr("Zvoleno prokletí: ${curseNameFor(curse)}!", "Curse chosen: ${curseNameFor(curse)}!");
    notifyListeners();
  }

  // ----- Modifikátory aplikované napříč schopnostmi (viz useXAbility/useLairXAbility) -----

  // ===== ŽIVÝ NÁHLED ČÍSEL SPELLU (Kniha kouzel) =====
  // Vrací krátký text s aktuálním poškozením/healem/štítem spellu podle SOUČASNÝCH statů
  // (physAtk/magAtk/maxHp), spočítaný ze STEJNÝCH násobičů jako skutečné vzorce v
  // useActiveAbility/useSecondAbility/useThirdAbility/useFourthAbility. Přímé zásahy se navíc
  // mitigují obranou AKTUÁLNÍHO nepřítele ve Věži (currentEnemyDef) - to je jediný nepřítel,
  // co existuje nezávisle na tom, jaký mód hráč zrovna hraje/prohlíží, takže je to nejbližší
  // rozumná aproximace "co bych dal, kdybych zaútočil hned teď". Heal/štít/DoT se defenzí
  // neovlivňují (ta se odečítá jen z přímého zásahu, stejně jako ve skutečném souboji).
  // Hardcore set bonusy (2/4/6/8pc) do čísla záměrně nejdou - jsou to podmíněné navýšení nad
  // tenhle základ, ne součást spellu samotného.
  int _previewHit(num rawAtk, double mult) {
    final raw = rawAtk * mult;
    return _minDmg(raw, raw - currentEnemyDef);
  }

  String spellLiveEffectText(int tier, {int choice = 1}) {
    final c = heroClass;
    final dmgMod = specAbilityDamageMod;
    String fmt(num n) => formatCompactNumber(n);
    // Exploze Prokletí (DK tier2 / tier4 volba 1): dmg = zbývající DoT × kola × curseDmgMod,
    // stejný vzorec jako v useSecondAbility/useFourthAbility. Počítá se ze SKUTEČNÉHO aktivního
    // "Prokletí" na nepříteli, pokud tam právě teď je - jinak nejde předpovědět (kletba
    // ještě nebyla nasazena), takže se vrátí vysvětlující text místo čísla.
    String curseDetonatePreview() {
      final prokl = enemyEffects.firstWhere((e) => e.name == "Prokletí", orElse: () => StatusEffect(name: "", description: "", duration: 0, isBuff: false));
      if (prokl.name != "Prokletí") return "Odpálí aktivní Prokletí za okamžité dmg - zatím žádné neběží, nejdřív použij Prokletý úder.";
      final dmg = (prokl.dotDamage * prokl.duration * curseDmgMod).toInt();
      return "≈${fmt(dmg)} dmg (odpálí ${prokl.duration} zbývajících kol × ${prokl.dotDamage}/kolo aktivní kletby)";
    }
    switch (tier) {
      case 0: // základní útok
        if (c == HeroClass.deathknight) {
          final totalAtk = physAtk + magAtk;
          return "≈${fmt(_previewHit(totalAtk / 2, 1.0))} dmg (fyz+mag)";
        }
        final dmg = classIsMagicAttack ? magAtk : physAtk;
        return "≈${fmt(_previewHit(dmg, 1.0))} dmg";
      case 1:
        switch (c) {
          case HeroClass.warrior: return "≈${fmt(_previewHit(physAtk, 2.5 * dmgMod))} dmg";
          case HeroClass.hunter: final d = _previewHit(physAtk, 2.0); return "≈${fmt(d)} dmg + ${fmt(d * 0.5)} heal";
          case HeroClass.healer: return "Heal ≈${fmt(maxHp * 0.5 * specAbilitySustainMod)}, Štít ≈${fmt(maxHp * 0.10 * specAbilitySustainMod)}";
          case HeroClass.deathknight: return "≈${fmt(_previewHit(physAtk, 1.5))} dmg + Prokletí ≈${fmt(magAtk * 0.5 * curseDmgMod)}/kolo";
          case HeroClass.mage: return "≈${fmt(_previewHit(magAtk, 2.5 * dmgMod))} dmg";
          case HeroClass.duelist: return "≈${fmt(_previewHit(physAtk, 2.2 * dmgMod))} dmg";
          case HeroClass.monk: return "≈${fmt(_previewHit(physAtk, 2.2 * dmgMod))} dmg";
          case HeroClass.druid: final raw = magAtk * 2.3 * dmgMod; return "≈${fmt(_previewHit(magAtk, 2.3 * dmgMod))} dmg + DoT ≈${fmt(raw * 0.18 / 3)}/kolo";
          case HeroClass.paladin: return "≈${fmt(_previewHit(physAtk, 2.2 * dmgMod))} dmg + Štít ≈${fmt(maxHp * (specialization == 1 ? 0.18 : 0.12) * specAbilitySustainMod)}";
          case HeroClass.demonhunter: final raw = physAtk * 2.4 * dmgMod; return "≈${fmt(_previewHit(physAtk, 2.4 * dmgMod))} dmg + Fel oheň ≈${fmt(raw * 0.15 / 3)}/kolo";
          case HeroClass.necromancer: return "≈${fmt(_previewHit(magAtk, 2.3 * dmgMod))} dmg + pet ≈${fmt(_previewHit(magAtk, 0.6 * dmgMod * (specialization == 1 ? 1.25 : 1.0)))} dmg";
          default: return "";
        }
      case 2:
        switch (c) {
          case HeroClass.warrior: return "≈${fmt(_previewHit(physAtk, 4.0 * dmgMod))} dmg + Štít ≈${fmt(maxHp * 0.25 * specAbilitySustainMod)}";
          case HeroClass.hunter: return "≈${fmt(_previewHit(physAtk, 5.0))} dmg";
          case HeroClass.healer: return "Plné HP + ≈${fmt(_previewHit(magAtk, 3.5 * dmgMod))} dmg";
          case HeroClass.deathknight: return curseDetonatePreview();
          case HeroClass.mage: return "≈${fmt(_previewHit(magAtk, 4.5 * dmgMod))} dmg";
          case HeroClass.duelist: return "≈${fmt(_previewHit(physAtk, 5.0 * dmgMod))} dmg";
          case HeroClass.monk: return "≈${fmt(_previewHit(physAtk, 4.5 * dmgMod))} dmg + Štít";
          case HeroClass.druid: return "≈${fmt(_previewHit(magAtk, 3.2 * dmgMod))} dmg (burst)";
          case HeroClass.paladin: return "≈${fmt(_previewHit(physAtk, 4.5 * dmgMod))} dmg (burst)";
          case HeroClass.demonhunter: return "≈${fmt(_previewHit(physAtk, 4.8 * dmgMod))} dmg (burst)";
          case HeroClass.necromancer: return "≈${fmt(_previewHit(magAtk, 4.5 * dmgMod))} dmg (burst)";
          default: return "";
        }
      case 3:
        switch (c) {
          case HeroClass.warrior: return "≈${fmt(_previewHit(physAtk, 7.5 * dmgMod))} dmg + obří štít";
          case HeroClass.hunter: return "≈${fmt(_previewHit(physAtk, 8.0))} dmg + plné HP";
          case HeroClass.healer: return "Božská sprcha ≈${fmt(_previewHit(magAtk, 7.0 * dmgMod))} dmg + plné HP + štít";
          case HeroClass.deathknight: return "≈${fmt(_previewHit(physAtk, 2.0))} dmg + ≈${fmt(magAtk * 2.0)} heal/štít";
          case HeroClass.mage: return "≈${fmt(_previewHit(magAtk, 8.0 * dmgMod))} dmg + ward";
          case HeroClass.duelist: return "≈${fmt(_previewHit(physAtk, 8.5 * dmgMod))} dmg + plné HP";
          case HeroClass.monk: return "≈${fmt(_previewHit(physAtk, 7.5 * dmgMod))} dmg + plné HP + štít";
          case HeroClass.druid: return "≈${fmt(_previewHit(magAtk, 3.6 * dmgMod))} dmg + plné HP + velký štít";
          case HeroClass.paladin: return "≈${fmt(_previewHit(physAtk, 3.6 * dmgMod))} dmg + plné HP + velký štít";
          case HeroClass.demonhunter: return "≈${fmt(_previewHit(physAtk, 3.2 * dmgMod))} dmg + dlouhý lifesteal";
          case HeroClass.necromancer: return "≈${fmt(_previewHit(magAtk, 3.2 * dmgMod))} dmg + plné HP + dlouhý lifesteal";
          default: return "";
        }
      case 4:
        switch (c) {
          case HeroClass.warrior:
            if (choice == 1) return "≈${fmt(_previewHit(physAtk, 12.0 * dmgMod))} dmg + obří štít";
            if (choice == 2) return "≈${fmt(_previewHit(physAtk, 15.0 * dmgMod))} dmg (čistě ofenzivní)";
            return "Plné HP + masivní štít, bez dmg";
          case HeroClass.hunter:
            if (choice == 1) return "≈${fmt(_previewHit(physAtk, 13.0))} dmg";
            if (choice == 2) return "≈${fmt(_previewHit(physAtk, 11.0))} dmg + dlouhý lifesteal";
            return "≈${fmt(_previewHit(physAtk, 14.0))} dmg + plné HP";
          case HeroClass.healer:
            if (choice == 1) return "Plné HP + ≈${fmt(_previewHit(magAtk, 10.0 * dmgMod))} dmg + štít";
            if (choice == 2) return "Plné HP + dlouhý lifesteal, bez dmg";
            return "≈${fmt(_previewHit(magAtk, 16.0 * dmgMod))} dmg (čistě ofenzivní)";
          case HeroClass.deathknight:
            if (choice == 1) return curseDetonatePreview();
            final base = "≈${fmt(_previewHit((physAtk + magAtk).toDouble(), 5.0))} dmg";
            return choice == 3 ? "$base + lifesteal" : base;
          case HeroClass.mage:
            if (choice == 1) return "≈${fmt(_previewHit(magAtk, 11.0 * dmgMod))} dmg";
            if (choice == 2) return "≈${fmt(_previewHit(magAtk, 9.0 * dmgMod))} dmg (část many se vrátí)";
            return "≈${fmt(_previewHit(magAtk, 8.0 * dmgMod))} dmg (nejnižší, ale nejlevnější varianta)";
          case HeroClass.duelist:
            if (choice == 1) return "≈${fmt(_previewHit(physAtk, 13.0 * dmgMod))} dmg";
            if (choice == 2) return "≈${fmt(_previewHit(physAtk, 11.0 * dmgMod))} dmg + úhyb buff";
            return "≈${fmt(_previewHit(physAtk, 12.0 * dmgMod))} dmg";
          case HeroClass.monk:
            if (choice == 1) return "≈${fmt(_previewHit(physAtk, 10.0 * dmgMod))} dmg";
            if (choice == 2) return "≈${fmt(_previewHit(physAtk, 6.0 * dmgMod))} dmg + heal";
            return "≈${fmt(_previewHit(physAtk, 5.0 * dmgMod))} dmg + štít";
          case HeroClass.druid:
            if (choice == 1) return "≈${fmt(_previewHit(magAtk, 11.0 * dmgMod))} dmg";
            if (choice == 2) return "≈${fmt(_previewHit(magAtk, 6.0 * dmgMod))} dmg + heal";
            return "Plné HP + velký štít, nižší dmg";
          case HeroClass.paladin:
            if (choice == 1) return "≈${fmt(_previewHit(physAtk, 7.0 * dmgMod))} dmg + štít";
            if (choice == 2) return "≈${fmt(_previewHit(physAtk, 15.0 * dmgMod))} dmg (čistě ofenzivní)";
            return "Plné HP + masivní štít, bez dmg";
          case HeroClass.demonhunter:
            if (choice == 1) return "≈${fmt(_previewHit(physAtk, 14.0 * dmgMod))} dmg";
            if (choice == 2) return "≈${fmt(_previewHit(physAtk, 7.0 * dmgMod))} dmg + dlouhý lifesteal";
            return "≈${fmt(_previewHit(physAtk, 9.0 * dmgMod))} dmg + plné HP";
          case HeroClass.necromancer:
            if (choice == 1) return "≈${fmt(_previewHit(magAtk, 11.0 * dmgMod))} dmg";
            if (choice == 2) return "≈${fmt(_previewHit(magAtk, 6.0 * dmgMod))} dmg + heal";
            return "≈${fmt(_previewHit(magAtk, 7.0 * dmgMod))} dmg + dlouhý lifesteal";
          default: return "";
        }
      default:
        return "";
    }
  }

  double get specAbilityDamageMod {
    // Damage z abilit 1-4 (ne základní/signature útok). Warrior Berserk/Ochránce, Healer Battle Priest.
    if (specialization == 0) return 1.0;
    if (heroClass == HeroClass.warrior) {
      if (specialization == 1) return 1.20; // Berserk
      if (specialization == 2) return 0.85; // Ochránce
    }
    if (heroClass == HeroClass.healer && specialization == 3) return 1.15; // Battle Priest
    if (heroClass == HeroClass.mage) {
      if (specialization == 1) return 1.20; // Plamen
      if (specialization == 2) return 0.95; // Led
    }
    if (heroClass == HeroClass.duelist) {
      if (specialization == 1) return 1.20; // Vendetta
      if (specialization == 2) return 0.85; // Grácie
    }
    if (heroClass == HeroClass.monk) {
      if (specialization == 1) return 1.20; // Vichr (DMG)
      if (specialization == 2) return 0.85; // Skála (Tank)
    }
    if (heroClass == HeroClass.druid && specialization == 1) return 1.10; // Rovnováha
    if (heroClass == HeroClass.paladin && specialization == 2) return 1.15; // Trestající
    return 1.0;
  }

  // Heal/štít generovaný abilitami 1-4. Warrior Berserk/Ochránce, Healer Světlo/Odplata, Mage Plamen/Led.
  // ===== ARÉNA — "VYČERPÁVACÍ" DEBUFF OD 11. KOLA (safe mechanika, ať souboj nemůže trvat věčně) =====
  // Od 11. kola se hráči i soupeři každé další kolo o kus zhorší obranné/sustain schopnosti -
  // -1 %/kolo Dodge, -1 %/kolo Block (hrdina), -1 %/kolo Def (soupeř, jeho ekvivalent bloku) a
  // -3 %/kolo efektivita Heal/Absorb (hrdina, přes specAbilitySustainMod - jednotné místo pro
  // VŠECHNY heal/štít výpočty napříč sdílenými ability funkcemi, viz níže). 0 mimo aktivní Arena
  // souboj (arenaOpponentClass != null && arenaOpponentHp > 0).
  int get arenaStallRounds {
    if (arenaOpponentClass == null || arenaOpponentHp <= 0) return 0;
    return max(0, arenaCombatRoundCount - 10);
  }

  double get specAbilitySustainMod {
    double mod = 1.0;
    if (specialization != 0) {
      if (heroClass == HeroClass.warrior) {
        if (specialization == 1) mod = 0.75; // Berserk -25 %
        if (specialization == 2) mod = 1.50; // Ochránce +50 %
      }
      if (heroClass == HeroClass.healer) {
        if (specialization == 1) mod = 1.30; // Světlo +30 %
        if (specialization == 2) mod = 0.85; // Odplata -15 %
      }
      if (heroClass == HeroClass.mage) {
        if (specialization == 1) mod = 0.85; // Plamen: méně wardu, víc dmg
        if (specialization == 2) mod = 1.40; // Led +40 %
      }
      if (heroClass == HeroClass.monk) {
        if (specialization == 2) mod = 1.40; // Skála (Tank) +40 % heal/štít z abilit
      }
    }
    // Probuzení Ducha (Mnich rank100 volba 3): +15 % heal/absorb na 3 kola, časově omezené (nezávislé na specializaci).
    if (heroEffects.any((e) => e.name == "Probuzení Ducha")) mod *= 1.15;
    // Vyčerpávací debuff (Aréna, od 11. kola): -3 %/kolo efektivita heal/štítu - viz arenaStallRounds.
    if (arenaStallRounds > 0) mod *= (1 - 0.03 * arenaStallRounds).clamp(0.0, 1.0);
    return mod * curseDarknessMod * gemSustainBonus * lairSustainMult; // Temnota (curse): -30 % efektivita heal/štítu z abilit; Gem Temnoty: opačný efekt navrch
  }

  // Probuzení Ducha (Mnich rank100 volba 3): -15 % obdrženého poškození na 3 kola.
  double get monkAwakenedSpiritDmgReduction => heroEffects.any((e) => e.name == "Probuzení Ducha") ? 0.15 : 0.0;

  // ===== MNICH — SKÁLA (Tank spec) =====
  // +2,5 % flat dodge (žádný block bonus - dodge místo bloku, na rozdíl od Warrior Ochránce).
  double get monkRockDodgeBonus => (heroClass == HeroClass.monk && specialization == 2) ? 0.025 : 0.0;

  // 30 % obdrženého poškození se PŘEMĚNÍ na krvácení (DoT přes 3 kola) místo okamžitého dmg -
  // vyhlazuje burst poškození na sustain, typický tank trade-off. Volá se z _resolveCombatRound()/
  // _resolveLairCombatRound() PŘED odečtením rawDamage z HP.
  int _applyMonkRockDamageConversion(int rawDamage) {
    if (heroClass != HeroClass.monk || specialization != 2 || rawDamage <= 0) return rawDamage;
    final converted = (rawDamage * 0.30).round();
    final remaining = rawDamage - converted;
    if (converted > 0) {
      final dot = (converted / 3).round().clamp(1, 999999);
      // Krvácení (Skála) krvácí HRDINU (vlastní DoT v heroEffects), ne nepřítele.
      heroEffects.removeWhere((e) => e.name == "Krvácení (Skála)");
      heroEffects.add(StatusEffect(name: "Krvácení (Skála)", description: "Krvácení $dot/kolo (přeměněno z útoku)", duration: 3, isBuff: false, dotDamage: dot));
    }
    return remaining;
  }

  // ===== MNICH — KLID (Heal spec) =====
  // Abilita vyléčí Mnicha za % způsobeného poškození (heal z dmg) - meditativní bojový styl.
  double get monkCalmHealFromDamage => (heroClass == HeroClass.monk && specialization == 3) ? 0.275 : 0.0;

  // Božská odplata (Healer reflect passiv) - základ 10 %.
  double get specReflectMod {
    if (heroClass != HeroClass.healer || specialization == 0) return 1.0;
    if (specialization == 1) return 1.5; // Světlo: 10 % -> 15 %
    if (specialization == 2) return 2.5; // Odplata: 10 % -> 25 %
    return 1.0; // Battle Priest beze změny
  }

  // Lifesteal ze všech zdrojů (DK Krev).
  double get specLifestealMod => (heroClass == HeroClass.deathknight && specialization == 1) ? 1.40 : 1.0;

  // Pasivní lifesteal Krev specializace - 5 % z KAŽDÉHO způsobeného poškození (základní útok
  // i abilita), bez ohledu na lifestealTurns/runy. Funguje ve všech třech kontextech (Věž/Lair/Rift).
  void _applyKrevPassiveLifesteal(int dmg) {
    if (heroClass != HeroClass.deathknight || specialization != 1 || dmg <= 0) return;
    hp = (hp + (dmg * 0.05).toInt()).clamp(0, maxHp);
  }

  // DK hybridní útok: fyzická složka (Mráz +25 %) / magická+DoT složka (Nákaza +25 %).
  double get specDkPhysMod => (heroClass == HeroClass.deathknight && specialization == 2) ? 1.25 : 1.0;
  double get specDkMagMod => (heroClass == HeroClass.deathknight && specialization == 3) ? 1.25 : 1.0;

  // DK Prokletí: max trvání po prodloužení (Nákaza 6->9), dmg/kolo (Nákaza +20 %), posun při seslání (Mráz -1).
  int get curseMaxDuration => (heroClass == HeroClass.deathknight && specialization == 3) ? 9 : 6;
  double get curseDmgMod => (heroClass == HeroClass.deathknight && specialization == 3) ? 1.20 : 1.0;
  // P1 specialization tuning. These modifiers are centralized so every combat mode reads the same values.
  double get specializationDotDamageMod {
    if (heroClass == HeroClass.mage && specialization == 1) return 1.10;
    if (heroClass == HeroClass.necromancer && specialization == 2) return 1.15;
    return 1.0;
  }
  double get specializationBossDamageMod =>
      (heroClass == HeroClass.druid && specialization == 1) ? 1.10 : 1.0;

  // Balance 34: tank specializations trade basic-attack speed for survivability.
  // Oprava: specialization==0 (nezvoleno, platí do lvl 25+Paragon 10) NESMÍ počítat jako
  // "má tank spec" - specStatProfile interně padá na spec 1 jako fallback pro staty/scaling,
  // ale u DK (Krev) a Paladina (Posvěcený) je zrovna spec 1 tanková, takže bez týhle podmínky
  // dostával postih každý DK/Paladin ještě předtím, než si vůbec nějakou specializaci zvolil.
  double get basicAttackRoleMod => (specialization != 0 && specStatProfile.tankArmorCoefficient > 1.0) ? 0.88 : 1.0;

  // Balance 38: Stopař keeps crit chance identity and gains +10% critical damage.
  double get specializationCritDamageBonus =>
      (heroClass == HeroClass.hunter && specialization == 1) ? 0.10 : 0.0;

  // Balance 36: Trestající deals +10% ability damage to targets below 35% HP.
  int applyAbilityExecute(int damage, int targetHp, int targetMaxHp) {
    if (damage <= 0 || targetMaxHp <= 0) return damage;
    if (heroClass == HeroClass.paladin && specialization == 2 && targetHp / targetMaxHp < 0.35) {
      return (damage * 1.10).round();
    }
    return damage;
  }
  int get felFireDuration =>
      (heroClass == HeroClass.demonhunter && specialization == 3) ? 5 : 3;
  int cappedVichrBleed(int proposed) => min(proposed, (physAtk * 1.5).round());
  int get curseCastDurationDelta => (heroClass == HeroClass.deathknight && specialization == 2) ? -1 : 0;

  // DK Runová trhlina (signature útok) crit bonus (Mráz) / Hunter Stopař / Duelist Virtuóz.
  double get specCritBonus {
    double bonus = 0.0;
    if (heroClass == HeroClass.hunter && specialization == 1) bonus += 0.15; // Stopař
    if (heroClass == HeroClass.deathknight && specialization == 2) bonus += 0.10; // Mráz
    if (heroClass == HeroClass.duelist && specialization == 3) bonus += 0.15; // Virtuóz
    return bonus;
  }

  // Hunter dodge bonus (Divočina/Stín), Warrior block bonus (Ochránce), Duelist Grácie dodge - flat přídavek do getterů.
  double get specDodgeBonus {
    if (heroClass == HeroClass.hunter) {
      if (specialization == 2) return 0.05; // Divočina
      if (specialization == 3) return 0.10; // Stín
    }
    if (heroClass == HeroClass.duelist && specialization == 2) return 0.10; // Grácie
    return 0.0;
  }

  double get specBlockBonus => (heroClass == HeroClass.warrior && specialization == 2) ? 0.05 : 0.0;

  // Hunter Divočina / Mage Aether / Duelist Virtuóz: náklady schopností -25 %, cooldowny -20 %
  // (jen Tower - Lair má 1x-použití flagy, ne cooldown).
  double get specResourceCostMod {
    if (heroClass == HeroClass.hunter && specialization == 2) return 0.75; // Divočina
    if (heroClass == HeroClass.mage && specialization == 3) return 0.75; // Aether
    if (heroClass == HeroClass.duelist && specialization == 3) return 0.75; // Virtuóz
    return 1.0;
  }

  double get specCooldownMod {
    if (heroClass == HeroClass.hunter && specialization == 2) return 0.80; // Divočina
    if (heroClass == HeroClass.mage && specialization == 3) return 0.80; // Aether
    if (heroClass == HeroClass.duelist && specialization == 3) return 0.80; // Virtuóz
    return 1.0;
  }
  int _scaledCooldown(int base) => (base * specCooldownMod * relicCooldownMult).round().clamp(1, base);

  // Hunter Znamení lovce (signature útok) - Stopař má víc stacků a silnější stack.
  int get huntersMarkMaxStacks => (heroClass == HeroClass.hunter && specialization == 1) ? 8 : 5;
  double get huntersMarkPerStack => (heroClass == HeroClass.hunter && specialization == 1) ? 0.04 : 0.03;

  // Mage Arcane Charge (signature útok) - Aether spec nabíjí rychleji.
  int get arcaneChargeMaxStacks => 5;
  double get arcaneChargePerStack => 0.04;
  int get arcaneChargeGainPerHit => (heroClass == HeroClass.mage && specialization == 3) ? 2 : 1;

  // Monk Plynoucí Čchi (signature útok).
  int get flowingChiMaxStacks => 5;
  double get flowingChiPerStack => 0.03;

  // Duelist Grácie: šance na counter-attack při úspěšném úhybu.
  bool get hasGraceCounter => heroClass == HeroClass.duelist && specialization == 2;

  // Warrior Krvežíznivý / Hunter Stín: fyzické ability navíc aplikují DoT na nepřítele.
  bool get appliesBleedOnAbility => heroClass == HeroClass.warrior && specialization == 3;
  bool get appliesPoisonOnAbility => heroClass == HeroClass.hunter && specialization == 3;

  void _applyAbilityDot(int baseDmg) {
    if (baseDmg <= 0) return;
    if (appliesBleedOnAbility) {
      final dot = (baseDmg * 0.20 / 3).round();
      enemyEffects.removeWhere((e) => e.name == "Krvácení (Krvežíznivý)");
      enemyEffects.add(StatusEffect(name: "Krvácení (Krvežíznivý)", description: "Krvácení $dot/kolo", duration: 3, isBuff: false, dotDamage: dot));
    }
    if (appliesPoisonOnAbility) {
      final dot = (baseDmg * 0.10 / 3).round();
      enemyEffects.removeWhere((e) => e.name == "Jed (Stín)");
      enemyEffects.add(StatusEffect(name: "Jed (Stín)", description: "Jed $dot/kolo", duration: 3, isBuff: false, dotDamage: dot));
    }
  }

  // ===== HARDCORE/PŘEDPEKLÍ SETY V RIFT — parita pro Rift, jinou formou než Tower/Lair =====
  // Rift nemá cooldown-gated ability1/2/3 jako Tower/Lair (jen základní útok), takže 1:1 replika
  // 21 unikátních 2pc/4pc/6pc mechanik sem strukturálně nejde přenést beze změny (nejsou 3
  // samostatné akce, na které by se daly navázat). Místo toho aplikujeme bonusy podle ROLE
  // specializace (DMG/Tank/Heal - stejné rozdělení, co mají všechny třídy), škálované dolů, ať to
  // sedí do spamovatelného základního útoku, ne jednorázové cooldown ability:
  //   DMG (spec1):  2pc +8 % dmg, 4pc +15 % dmg, 6pc +25 % dmg
  //   Tank (spec2): 2pc heal/štít +5 % dmg jako štít, 4pc +10 %, 6pc +10 % a 5 % šance na negaci útoku
  //   Heal (spec3): 2pc heal +5 % dmg jako HP, 4pc +10 %, 6pc +15 % a malý štít navrch
  // Předpeklí set je o 50 % silnější než Hardcore - pokud má hráč nasazený Předpeklí set na
  // vyšším (nebo stejném) tieru než Hardcore, počítá se z něj (×1.5 na všechny procentní bonusy).
  int _applyHardcoreSetRiftOffense(int dealtDmg) {
    if (dealtDmg <= 0 || specialization == 0) return dealtDmg;
    final ppTier = activePredpekliSetTier;
    final hcTier = activeHardcoreSetTier;
    final usePredpekli = ppTier >= 2 && ppTier >= hcTier;
    final tier = usePredpekli ? ppTier : hcTier;
    if (tier < 2) return dealtDmg;
    final scale = usePredpekli ? 1.5 : 1.0;
    if (specialization == 1) {
      // DMG role - stejné napříč všemi třídami (Vichr/Vendetta/Berserk/atd.)
      final bonus = (tier >= 6 ? 0.25 : (tier >= 4 ? 0.15 : 0.08)) * scale;
      return (dealtDmg * (1 + bonus)).toInt();
    }
    return dealtDmg;
  }

  // Tank/Heal role - vedlejší efekty (štít/heal) po odečtení dmg z HP nepřítele. Volá se z
  // fightRiftGuardian() po _applyGemOffense(), s finálním dealtDmg.
  void _applyHardcoreSetRiftSustain(int dealtDmg) {
    if (dealtDmg <= 0 || specialization == 0) return;
    final ppTier = activePredpekliSetTier;
    final hcTier = activeHardcoreSetTier;
    final usePredpekli = ppTier >= 2 && ppTier >= hcTier;
    final tier = usePredpekli ? ppTier : hcTier;
    if (tier < 2) return;
    final scale = usePredpekli ? 1.5 : 1.0;
    final setLabel = usePredpekli ? 'Předpeklí' : 'Hardcore';
    if (specialization == 2) {
      // Tank role
      final shieldPercent = (tier >= 4 ? 0.10 : 0.05) * scale;
      final shieldGain = (dealtDmg * shieldPercent).toInt();
      if (shieldGain > 0) {
        bonusShield += shieldGain;
        _applyShieldCap();
      }
      if (tier >= 6 && Random().nextDouble() < (0.05 * scale).clamp(0.0, 1.0)) {
        hardcoreInvulnerableActive = true;
        message += "🛡️ $setLabel set: " + tr("příští útok bude negován!", "the next attack will be negated!");
      }
    } else if (specialization == 3) {
      // Heal role
      final healPercent = (tier >= 6 ? 0.15 : (tier >= 4 ? 0.10 : 0.05)) * scale;
      final selfHeal = (dealtDmg * healPercent).toInt();
      if (selfHeal > 0) hp = (hp + selfHeal).clamp(0, maxHp);
      if (tier >= 6) {
        final shieldGain = (dealtDmg * 0.05 * scale).toInt();
        if (shieldGain > 0) {
          bonusShield += shieldGain;
          _applyShieldCap();
        }
      }
    }
  }

  // ===== GEM EFEKTY (Prsten Osudu) — volané ze základních útoků/combat resolverů =====
  // Ofenzivní část: Gem Jedu (DoT), Gem Roztříštění ("Echo" dvojitý zásah), Gem Krvavé lázně
  // (execute bonus proti nízkému HP nepřítele). Volá se PO výpočtu dealtDmg, PŘED odečtením z HP -
  // vrací upravený dealtDmg (execute/echo mohou číslo zvýšit).
  int _applyGemOffense(int dealtDmg, {required int enemyHp, required int enemyMaxHp, bool allowPoisonDot = true}) {
    if (dealtDmg <= 0 || activeGemType == null) return dealtDmg;
    int result = dealtDmg;
    // Gem Krvavé lázně -> "Poprava": bonus dmg proti nepříteli pod 30 % HP.
    if (gemBloodbathActive && enemyMaxHp > 0 && enemyHp / enemyMaxHp < 0.3) {
      result = (result * (1 + activeGemMagnitude)).toInt();
    }
    // ===== SYNERGIE: Gem Krvavé lázně (execute pod 30 % HP) =====
    if (enemyMaxHp > 0 && enemyHp / enemyMaxHp < 0.3 && _hasGemSynergy("Gem Krvavé lázně", "ws_bloodbath7")) {
      if (_isWarriorLikeClass) {
        result = (result * 1.25).toInt();
        message += "⚔️ Poprava: " + tr("+25 % dmg!", "+25% dmg!");
      } else if (_isHealLikeClass) {
        final healPulse = (magAtk * 0.15).round();
        hp = (hp + healPulse).clamp(0, maxHp);
        message += "✨ Dorážející milost: " + tr("+$healPulse HP!", "+$healPulse HP!");
      } else if (_isCasterLikeClass) {
        result = (result * 1.25).toInt();
        message += "💀 Temný dozvuk: " + tr("+25 % dmg!", "+25% dmg!");
      } else if (heroClass == HeroClass.hunter) {
        result = (result * 1.25).toInt();
        message += "🏹 Lovecký instinkt: " + tr("+25 % dmg!", "+25% dmg!");
      } else if (_isDruidClass) {
        result = (result * 1.15).toInt();
        final healPulse = (magAtk * 0.05).round();
        hp = (hp + healPulse).clamp(0, maxHp);
        message += "🐺 Divoký hlad: " + tr("+15 % dmg a +$healPulse HP!", "+15% dmg and +$healPulse HP!");
      } else if (_isPaladinClass) {
        result = (result * 1.25).toInt();
        message += "☀️ Boží soud: " + tr("+25 % dmg!", "+25% dmg!");
      } else if (_isDemonHunterClass) {
        result = (result * 1.25).toInt();
        message += "😈 Rozsudek Zkázy: " + tr("+25 % dmg!", "+25% dmg!");
      } else if (_isNecromancerClass) {
        result = (result * 1.20).toInt();
        final healPulse = (result * 0.08).round();
        hp = (hp + healPulse).clamp(0, maxHp);
        message += "💀 Hostina duší: " + tr("+20 % dmg a +$healPulse HP!", "+20% dmg and +$healPulse HP!");
      }
    }
    // Gem Roztříštění -> "Ozvěna": šance zasáhnout dvakrát.
    if (gemFragmentationActive && Random().nextDouble() < activeGemMagnitude) {
      result *= 2;
      message += "✨ Ozvěna gemu: " + tr("dvojitý zásah!", "double hit!");
      // ===== SYNERGIE: Gem Roztříštění (proklo echo) =====
      if (_hasGemSynergy("Gem Roztříštění", "ws_fragmentation7")) {
        if (_isWarriorLikeClass) {
          result = (result * 1.15).toInt();
          message += "(Zesílená ozvěna " + tr("+15 % dmg!)", "+15% dmg!)");
        } else if (_isHealLikeClass) {
          final healPulse = (magAtk * 0.10).round();
          hp = (hp + healPulse).clamp(0, maxHp);
          message += "(Ozvěna léčení: " + tr("+$healPulse HP!)", "+$healPulse HP!)");
        } else if (_isCasterLikeClass) {
          result = (result * 1.20).toInt();
          message += "(Dvojitý dozvuk " + tr("+20 % dmg!)", "+20% dmg!)");
        } else if (heroClass == HeroClass.hunter) {
          result = (result * 1.20).toInt();
          message += "(Volný šíp " + tr("+20 % dmg!)", "+20% dmg!)");
        } else if (_isDruidClass) {
          final dot = (magAtk * 0.10).round().clamp(1, 999999);
          enemyEffects.removeWhere((e) => e.name == "Šeptající kořeny");
          enemyEffects.add(StatusEffect(name: "Šeptající kořeny", description: "Jed $dot/kolo", duration: 2, isBuff: false, dotDamage: dot));
          message += "(Šeptající kořeny: " + tr("nepřítel otráven!)", "enemy poisoned!)");
        } else if (_isPaladinClass) {
          result = (result * 1.15).toInt();
          message += "(Ozvěna světla " + tr("+15 % dmg!)", "+15% dmg!)");
        } else if (_isDemonHunterClass) {
          result = (result * 1.15).toInt();
          message += "(Šířící se zkáza " + tr("+15 % dmg!)", "+15% dmg!)");
        } else if (_isNecromancerClass) {
          final petDmg = (result * 0.20).round();
          result += petDmg;
          message += "(Rozkaz sluhovi: " + tr("+$petDmg dmg navíc!)", "+$petDmg extra dmg!)");
        }
      }
    }
    // Gem Jedu -> aplikuje jed na nepřítele (jen Tower/Lair - Rift guardian nemá DoT tick systém).
    if (allowPoisonDot && gemPoisonActive && Random().nextDouble() < activeGemMagnitude) {
      final dot = (dealtDmg * 0.15).round().clamp(1, 999999);
      enemyEffects.removeWhere((e) => e.name == "Jed (Gem)");
      enemyEffects.add(StatusEffect(name: "Jed (Gem)", description: "Jed $dot/kolo", duration: 3, isBuff: false, dotDamage: dot));
      message += "☠️ Gem Jedu: " + tr("nepřítel otráven!", "enemy poisoned!");
    }
    // ===== SYNERGIE: Gem Jedu (vždy při zásahu, nezávisle na náhodné šanci samotného gemu) =====
    if (allowPoisonDot && _hasGemSynergy("Gem Jedu", "ws_poison7")) {
      if (_isWarriorLikeClass) {
        final dot = (physAtk * 0.20).round().clamp(1, 999999);
        enemyEffects.removeWhere((e) => e.name == "Otrávené ostří");
        enemyEffects.add(StatusEffect(name: "Otrávené ostří", description: "Jed $dot/kolo", duration: 2, isBuff: false, dotDamage: dot));
        message += " ☠️ Otrávené ostří!";
      } else if (_isCasterLikeClass) {
        final dot = (magAtk * 0.20).round().clamp(1, 999999);
        enemyEffects.removeWhere((e) => e.name == "Temný mor");
        enemyEffects.add(StatusEffect(name: "Temný mor", description: "Jed $dot/kolo", duration: 2, isBuff: false, dotDamage: dot));
        message += " ☠️ Temný mor!";
      } else if (heroClass == HeroClass.hunter) {
        final dot = (physAtk * 0.30).round().clamp(1, 999999);
        enemyEffects.removeWhere((e) => e.name == "Jedový hrot");
        enemyEffects.add(StatusEffect(name: "Jedový hrot", description: "Jed $dot/kolo", duration: 1, isBuff: false, dotDamage: dot));
        message += " ☠️ Jedový hrot!";
      } else if (_isDruidClass) {
        final dot = (magAtk * 0.25).round().clamp(1, 999999);
        enemyEffects.removeWhere((e) => e.name == "Trní rozkladu");
        enemyEffects.add(StatusEffect(name: "Trní rozkladu", description: "Jed $dot/kolo", duration: 3, isBuff: false, dotDamage: dot));
        message += " 🌿 Trní rozkladu!";
      } else if (_isPaladinClass) {
        final dot = (magAtk * 0.20).round().clamp(1, 999999);
        enemyEffects.removeWhere((e) => e.name == "Svaté spálení");
        enemyEffects.add(StatusEffect(name: "Svaté spálení", description: "Jed $dot/kolo", duration: 2, isBuff: false, dotDamage: dot));
        message += " ☀️ Svaté spálení!";
      } else if (_isDemonHunterClass) {
        final dot = (physAtk * 0.25).round().clamp(1, 999999);
        enemyEffects.removeWhere((e) => e.name == "Fel oheň");
        enemyEffects.add(StatusEffect(name: "Fel oheň", description: "Jed $dot/kolo", duration: 2, isBuff: false, dotDamage: dot));
        message += " 😈 Fel oheň!";
      } else if (_isNecromancerClass) {
        final dot = (magAtk * 0.28).round().clamp(1, 999999);
        enemyEffects.removeWhere((e) => e.name == "Morová kletba");
        enemyEffects.add(StatusEffect(name: "Morová kletba", description: "Jed $dot/kolo", duration: 3, isBuff: false, dotDamage: dot));
        message += " 💀 Morová kletba!";
      }
      // Mnich+Léčitel u Jedu nedostávají útočný efekt - jejich synergie je defenzivní (viz níže,
      // volá se při jakémkoliv vlastním heal/lifesteal - _cleansePoisonSynergy()).
    }
    if(relicExecute&&enemyMaxHp>0&&enemyHp/enemyMaxHp<0.20)result=(result*1.25).round();
    if(isInRift&&currentRiftSeason==RiftSeasonTheme.plague)result=(result*0.85).round();
    return result;
  }

  // ===== SYNERGIE: Gem Jedu × Mnich/Léčitel — neutralizace jedu (jako debuffu) s každým
  // vlastním heal efektem. Volá se odkudkoliv, kde si hrdina léčí HP (lifesteal, štít z útoku
  // léčitele...). Nesouvisí s activeGemType (funguje, i když je aktivní jiný gem) - stačí mít
  // Gem Jedu fyzicky vsazený + master runu odemčenou.
  void _cleansePoisonSynergy() {
    if (!_isHealLikeClass) return;
    if (!_hasGemSynergy("Gem Jedu", "ws_poison7")) return;
    final hadPoison = heroEffects.any((e) => !e.isBuff && e.name.contains("Jed"));
    if (hadPoison) {
      heroEffects.removeWhere((e) => !e.isBuff && e.name.contains("Jed"));
      message += " 💧 Neutralizace jedu!";
    }
  }

  // Defenzivní část: Gem Odrazu (thorns - vrátí % obdrženého dmg útočníkovi), Gem Oživení
  // (šance přežít smrtelný zásah s 33 % HP). Volá se z _resolveXCombatRound() při zpracování
  // poškození, co hrdina obdržel. Vrací true, pokud gem "zachránil" hrdinu před smrtí.
  // ===== SDÍLENÁ PIPELINE ZPRACOVÁNÍ PŘÍCHOZÍHO POŠKOZENÍ =====
  // Dřív bylo zkopírováno samostatně v každé z 5 _resolveXCombatRound() funkcí (Věž/Lair/
  // Aréna/World Boss/Rift) - při sjednocování vyšlo najevo, že Aréna a Rift verze časem
  // "zaostaly" a chyběla jim redukce poškození z run (damageReduction) i aplikace Jedu
  // (curse) - teď mají všechny módy identickou, kompletní pipeline.
  // Volající si PŘED zavoláním zpracuje mode-specific věci (Krvavá lázeň dle vlastního
  // max/aktuálního HP nepřítele, enrage, isBoss split) - tahle funkce řeší jen společnou
  // část od bloku dál: rune reduction → shield absorb → Božská odplata → Jed → Mnich
  // konverze → HP odečet → gem defense. Vrací true, pokud gem "zachránil" hrdinu před smrtí.
  // enemyDamage: callback pro poškození vrácené nepříteli (Božská odplata, gem reflect) -
  // volající předá lambda mířící na svoje vlastní pole (currentEnemyHp/arenaOpponentHp/...).
  bool _applyIncomingDamage(int rawDamage, void Function(int) enemyDamage, {void Function(int)? onShieldAbsorbed, void Function(int)? onFinalDamage, bool isCrit = false}) {
    bool blocked = Random().nextDouble() < blockChance;
    if (blocked) rawDamage = (rawDamage * (1 - blockReduction)).toInt();
    // Guardian Banner Lv30/40/60 "Ocelová odveta"/"Prasklina v pancíři"/"Mistrovský blok" (viz
    // _castWarriorSigil) a stejný efekt na Druid Wild Totem "Trnitá odveta" (viz _castDruidSigil):
    // úspěšný blok vrátí útočníkovi poškození podle Armor. enemyDamage() je stejný callback, co
    // používá Božská odplata/gem defense níž, takže míří vždy na správné HP pole (Tower/Lair/
    // Arena/WorldBoss/Rift/Soul Demon).
    final bool _hasBlockCounterRelic = isSpecRelicEquipped &&
        ((heroClass == HeroClass.warrior && currentSpecRelic.kind == SpecRelicKind.warriorGuardianBanner) ||
         (heroClass == HeroClass.druid && currentSpecRelic.kind == SpecRelicKind.druidWildTotem) ||
         (heroClass == HeroClass.paladin && currentSpecRelic.kind == SpecRelicKind.paladinGuardianSeal));
    if (blocked && _hasBlockCounterRelic && relicEffectActive(30)) {
      final counterDmg = (armor * (relicEffectActive(60) ? 0.34 : 0.20)).round();
      if (counterDmg > 0) {
        enemyDamage(counterDmg);
        message = tr("🛡️⚔️ Odveta: $counterDmg poškození útočníkovi!", "🛡️⚔️ Retaliation: $counterDmg damage to the attacker!");
      }
      // Lv40 "Prasklina v pancíři/kůře/temnotě" - protiútok skutečně sníží Armor nepřítele (dřív
      // bez efektu). Lehký sledovací debuff bez vlastního dmg jen proto, aby existovalo jméno,
      // co drží shred, dokud přirozeně nevyprší (viz _restoreRelicArmorShredIfMatches v _tickEffects()).
      if (relicEffectActive(40)) {
        _restoreRelicArmorShredIfMatches('Prasklina v pancíři');
        enemyEffects.removeWhere((e) => e.name == 'Prasklina v pancíři');
        _applyRelicArmorShred('Prasklina v pancíři', 0.10);
        enemyEffects.add(StatusEffect(name: 'Prasklina v pancíři', description: 'Armor cíle -10 %', duration: 3, isBuff: false));
      }
    }
    // Stone Mala Lv30 "Pevnost" (viz _castMonkSigil): úspěšný blok přidá stack (max 5).
    if (blocked && heroClass == HeroClass.monk && isSpecRelicEquipped && currentSpecRelic.kind == SpecRelicKind.monkStoneMala && relicEffectActive(30)) {
      specRelicStacks = min(5, specRelicStacks + 1);
    }
    // Runa obrany: procentuální snížení veškerého obdrženého poškození.
    final dmgReduction = runeEffect(RuneEffectType.damageReduction);
    if (dmgReduction > 0) rawDamage = (rawDamage * (1 - dmgReduction)).clamp(0, double.infinity).toInt();

    int absorbedByShield = 0;
    final int _shieldBeforeThisHit = bonusShield;
    if (bonusShield > 0) {
      // Temnota (curse): efektivní absorpce štítu snížena o 30 % - část dmg "prosákne".
      final effectiveShield = (bonusShield * curseDarknessMod).toInt();
      if (rawDamage > effectiveShield) {
        absorbedByShield = effectiveShield;
        rawDamage -= effectiveShield;
        bonusShield -= effectiveShield;
      } else {
        absorbedByShield = rawDamage;
        bonusShield -= rawDamage;
        rawDamage = 0;
      }
      _lastKnownBonusShield = bonusShield; // sync pro _applyShieldCap() FX diffing (tohle je pokles, ne zisk)
    }
    // Guardian Banner Lv50 "Výbuch bašty" / Wild Totem Lv50 "Výbuch lesa" (viz _castWarriorSigil/
    // _castDruidSigil): štít se tímhle zásahem úplně rozbil (byl aktivní, teď je na 0) -> exploduje
    // podle absorbovaného poškození.
    final bool _hasShieldBreakRelic = isSpecRelicEquipped &&
        ((heroClass == HeroClass.warrior && currentSpecRelic.kind == SpecRelicKind.warriorGuardianBanner) ||
         (heroClass == HeroClass.druid && currentSpecRelic.kind == SpecRelicKind.druidWildTotem) ||
         (heroClass == HeroClass.paladin && currentSpecRelic.kind == SpecRelicKind.paladinGuardianSeal));
    if (_shieldBeforeThisHit > 0 && bonusShield <= 0 && absorbedByShield > 0 && _hasShieldBreakRelic && relicEffectActive(50)) {
      final burstDmg = (absorbedByShield * 0.6).round();
      if (burstDmg > 0) {
        enemyDamage(burstDmg);
        _pushFx(FxKind.explosionDamage, FxSide.enemy, value: burstDmg, burstKind: heroClass == HeroClass.druid ? RelicBurstKind.forestBurst : (heroClass == HeroClass.paladin ? RelicBurstKind.faithBurst : RelicBurstKind.guardianBreak));
        message = tr("💥 Výbuch: $burstDmg poškození!", "💥 Burst: $burstDmg damage!");
      }
    }
    onShieldAbsorbed?.call(absorbedByShield); // Tower: _rewardTowerDefense() při plném vykrytí bossem
    // Healer pasivní schopnost "Božská odplata": 10 % poškození absorbovaného štítem se vrátí
    // nepříteli. Ignoruje Armor/block/resist/dodge, nekritne, nespouští lifesteal ani další shield/reflect.
    if (heroClass == HeroClass.healer && absorbedByShield > 0) {
      final holyReflectCap = (magAtk * 3);
      int holyReflect = (absorbedByShield * 0.10 * specReflectMod).toInt();
      if (holyReflect > holyReflectCap) holyReflect = holyReflectCap;
      if (holyReflect > 0) {
        enemyDamage(holyReflect);
        message = tr("✨ Božská odplata! Štít vrátil $holyReflect poškození nepříteli.", "✨ Divine Retribution! The shield reflected $holyReflect damage back at the enemy.");
      }
    }
    // Jed (curse): útok nepřítele aplikuje/zesílí Jed na hrdinovi. Další aplikace neprodlouží
    // trvání (refresh na fixní počet kol), ale zvýší dmg/kolo - stackuje se intenzita, ne délka.
    if (activeCurse == CurseOfFate.poison && rawDamage > 0) {
      poisonStacks++;
      final poisonDot = (maxHp * 0.02 * poisonStacks).toInt();
      heroEffects.removeWhere((e) => e.name == "Jed (Prokletí)");
      heroEffects.add(StatusEffect(name: "Jed (Prokletí)", description: "Jed $poisonDot/kolo (stack $poisonStacks)", duration: 3, isBuff: false, dotDamage: poisonDot));
    }
    if (monkAwakenedSpiritDmgReduction > 0) rawDamage = (rawDamage * (1 - monkAwakenedSpiritDmgReduction)).round(); // Probuzení Ducha: -15 % dmg taken
    rawDamage = _applyMonkRockDamageConversion(rawDamage); // Mnich Skála: 30 % dmg -> krvácení místo přímého zásahu
    onFinalDamage?.call(rawDamage); // Tower: DK soul runa za skutečně obdržené dmg (po všech redukcích)
    // Guardian Banner Lv90 "Nedobytná pevnost" / Wild Totem Lv90 "Srdce pralesa" (viz
    // _castWarriorSigil/_castDruidSigil): první smrtelný zásah v boji ponechá 1 HP a přidá
    // nouzový štít, místo aby hrdinu zabil. Jednou za boj (sdílené _guardianCheatDeathUsed).
    final bool _hasCheatDeathRelicA = isSpecRelicEquipped &&
        ((heroClass == HeroClass.warrior && currentSpecRelic.kind == SpecRelicKind.warriorGuardianBanner) ||
         (heroClass == HeroClass.druid && currentSpecRelic.kind == SpecRelicKind.druidWildTotem) ||
         (heroClass == HeroClass.paladin && currentSpecRelic.kind == SpecRelicKind.paladinGuardianSeal));
    if (_hasCheatDeathRelicA && relicEffectActive(90) && !_guardianCheatDeathUsed && hp > 0 && hp - rawDamage <= 0) {
      _guardianCheatDeathUsed = true;
      rawDamage = hp - 1;
      final emergencyShield = (maxHp * 0.15).round();
      bonusShield += emergencyShield;
      message = tr("✨ Přežíváš s 1 HP a nouzovým štítem!", "✨ You survive with 1 HP and an emergency shield!");
      _pushFx(FxKind.shieldGained, FxSide.hero, value: emergencyShield, burstKind: heroClass == HeroClass.druid ? RelicBurstKind.natureHeart : (heroClass == HeroClass.paladin ? RelicBurstKind.divineGrace : null));
    }
    // Stone Mala Lv90 "Nehybný svět" (viz _castMonkSigil): stejná mechanika jako Nedobytná pevnost
    // výš, jen spotřebuje nastřádané Pevnost stacky místo automatického nouzového štítu.
    if (heroClass == HeroClass.monk && isSpecRelicEquipped && currentSpecRelic.kind == SpecRelicKind.monkStoneMala &&
        relicEffectActive(90) && !_guardianCheatDeathUsed && hp > 0 && hp - rawDamage <= 0) {
      _guardianCheatDeathUsed = true;
      rawDamage = hp - 1;
      final emergencyShield = (maxHp * 0.10 + specRelicStacks * (maxHp * 0.03)).round();
      bonusShield += emergencyShield;
      specRelicStacks = 0;
      message = tr("🗻✨ Nehybný svět! Přežíváš s 1 HP - Pevnost se proměnila ve štít.", "🗻✨ Immovable World! You survive with 1 HP - Fortitude became a shield.");
      _pushFx(FxKind.shieldGained, FxSide.hero, value: emergencyShield);
    }
    hp -= rawDamage;
    if (blocked) message = tr("🛡️ Blokováno! Sníženo poškození na $rawDamage.", "🛡️ Blocked! Damage reduced to $rawDamage.");
    // Combat FX + haptika: jedno centrální místo pro VŠECHNO poškození, co hrdina obdrží
    // napříč Tower/Lair/Arénou/Riftem/World Bossem/Endless Scale - dodge se řeší zvlášť u
    // volajícího (ten svůj vlastní dodge check dělá dřív, než tuhle funkci vůbec zavolá).
    if (absorbedByShield > 0) _pushFx(FxKind.absorbed, FxSide.hero, value: absorbedByShield);
    if (rawDamage > 0) {
      _pushFx(blocked ? FxKind.blocked : (isCrit ? FxKind.critDamage : FxKind.normalDamage), FxSide.hero, value: rawDamage);
      hapticImpactMedium();
    } else if (blocked || absorbedByShield > 0) {
      hapticImpactLight();
    }
    return _applyGemDefense(rawDamage, enemyDamage);
  }

  // ===== SDÍLENÁ TIER1 SCHOPNOST (Schopnost 1 / Paragon 10 "Pokročilá třída") =====
  // Matematika byla 100% identická napříč Věží/Lairem/Arénou/World Bossem - lišily se jen HP
  // proměnná nepřítele, "použito" mechanismus (cooldown vs. flag) a textový prefix zprávy.
  // Věžina formulace textu se v čase mírně odchýlila (jiná slovní volba) - sjednoceno na
  // formulaci ostatních 3 módů, prefix teď dostává i Věž (dřív žádný neměla u DK zprávy).
  // enemyDefValue: aktuální Def nepřítele (před armor pen). enemyHp/enemyMaxHp: čtecí callbacky
  // (jen pro poměrové kontroly). enemyDamage: callback co UBERE poškození z HP nepřítele.
  void _castTier1Ability(String prefix, int enemyDefValue, int Function() enemyHp, int Function() enemyMaxHp, void Function(int) enemyDamage) {
    void dealAbilityDamage(int damage) =>
        enemyDamage(applyAbilityExecute(damage, enemyHp(), enemyMaxHp()));
    final armorPenL1 = runeEffect(RuneEffectType.armorPen);
    final effDef = armorPenL1 > 0 ? (enemyDefValue * (1 - armorPenL1)).clamp(0, double.infinity).toInt() : enemyDefValue;
    if (isBerserk) {
      int dmg = (physAtk * 2.5 * specAbilityDamageMod).toInt();
      if (specialization == 1 && activeHardcoreSetTier >= 2) dmg = (dmg * 1.25).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      dealAbilityDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.berserk);
      _applyAbilityDot(dmg);
      if (specialization == 3 && activeHardcoreSetTier >= 2 && appliesBleedOnAbility) {
        final bonusBleed = ((dmg * 0.20 / 3) * 0.5).round();
        final idx = enemyEffects.indexWhere((e) => e.name == "Krvácení (Krvežíznivý)");
        if (idx != -1) enemyEffects[idx] = StatusEffect(name: "Krvácení (Krvežíznivý)", description: "Krvácení ${enemyEffects[idx].dotDamage + bonusBleed}/kolo", duration: enemyEffects[idx].duration, isBuff: false, dotDamage: enemyEffects[idx].dotDamage + bonusBleed);
      }
      if (specialization == 2 && activeHardcoreSetTier >= 2) {
        final shieldGain = (maxHp * 0.15).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
      }
      message = tr("$prefix: Mocný úder! Způsobeno $dmg poškození.", "$prefix: Mocný úder! Dealt $dmg damage.");
    } else if (isAssassin) {
      int dmg = (physAtk * 2.0).toInt();
      if (specialization == 1 && activeHardcoreSetTier >= 2) dmg = (dmg * critDamageMultiplier).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      dealAbilityDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.assassin);
      int heal = (dmg * 0.5).toInt();
      if (specialization == 2 && activeHardcoreSetTier >= 2) heal *= 2;
      hp = (hp + heal).clamp(0, maxHp);
      _applyAbilityDot(dmg);
      if (specialization == 3 && activeHardcoreSetTier >= 2) {
        final idx = enemyEffects.indexWhere((e) => e.name == "Jed (Stín)");
        if (idx != -1) enemyEffects[idx] = StatusEffect(name: "Jed (Stín)", description: "Jed ${enemyEffects[idx].dotDamage * 2}/kolo", duration: enemyEffects[idx].duration, isBuff: false, dotDamage: enemyEffects[idx].dotDamage * 2);
      }
      message = tr("$prefix: Skrytý úder! Způsobeno $dmg poškození a vyléčeno $heal HP.", "$prefix: Skrytý úder! Dealt $dmg damage and healed $heal HP.");
    } else if (isPriest) {
      int heal = (maxHp * 0.5 * specAbilitySustainMod).toInt();
      if (specialization == 1 && activeHardcoreSetTier >= 2) heal = (heal * 1.5).toInt();
      hp = (hp + heal).clamp(0, maxHp);
      final shieldGain = (maxHp * 0.10 * specAbilitySustainMod).toInt();
      bonusShield += shieldGain;
      _applyShieldCap();
      _pushFx(FxKind.shieldGained, FxSide.hero, value: heal, spellFxKind: SpellFxKind.healerBlessing);
      heroEffects.add(StatusEffect(name: "Boží štít", description: "+10 % MaxHP absorpce", duration: 5, isBuff: true));
      message = tr("$prefix: Boží požehnání! Obnoveno $heal HP a přidán štít (+$shieldGain).", "$prefix: Boží požehnání! Restored $heal HP and added a shield (+$shieldGain).");
      if (specialization == 2 && activeHardcoreSetTier >= 2) {
        final reflectDmg = (shieldGain * 0.10).toInt();
        dealAbilityDamage(reflectDmg);
        message += tr(" (Odplata: -$reflectDmg nepříteli)", " (Retribution: -$reflectDmg to the enemy)");
      }
      if (specialization == 3 && activeHardcoreSetTier >= 2) {
        final punishDmg = (heal * 0.30).toInt();
        dealAbilityDamage(punishDmg);
        message += tr(" (+$punishDmg dmg nepříteli)", " (+$punishDmg dmg to the enemy)");
      }
    } else if (isDarkKnight) {
      final double triple = nextSpellTriple ? 3.0 : 1.0;
      if (nextSpellTriple) { nextSpellTriple = false; soulRunes = 0; }
      int physDmg = (physAtk * 1.5 * triple).toInt();
      if (specialization == 2 && activeHardcoreSetTier >= 2) physDmg = (physDmg * critDamageMultiplier).toInt();
      physDmg = _minDmg(physDmg, physDmg - effDef);
      dealAbilityDamage(physDmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: physDmg, spellFxKind: SpellFxKind.dkCursedStrike);
      _applyKrevPassiveLifesteal(physDmg);
      // Rebalance: DoT nyní 50 % MATK/kolo po 4 kola (celkem 2.0× MATK) - méně burst, více sustain.
      // Specializace: Nákaza posílí dmg/kolo, Mráz zkrátí trvání o 1 kolo (víc burst, míň sustain).
      int dotDmg = (magAtk * 0.5 * triple * curseDmgMod).toInt();
      int curseDuration = (4 + curseCastDurationDelta).clamp(1, 99);
      if (specialization == 3 && activeHardcoreSetTier >= 2) curseDuration += 2;
      enemyEffects.removeWhere((e) => e.name == "Prokletí");
      enemyEffects.add(StatusEffect(name: "Prokletí", description: "Prokletí $dotDmg/kolo ($curseDuration kola)", duration: curseDuration, isBuff: false, dotDamage: dotDmg));
      message = tr("$prefix ☠ Prokletý úder! $physDmg dmg + Prokletí $dotDmg/kolo po $curseDuration kola.${triple > 1 ? ' ✨ TROJNÁSOBEK!' : ''}", "$prefix ☠ Prokletý úder! $physDmg dmg + Curse $dotDmg/round for $curseDuration rounds.${triple > 1 ? ' ✨ TRIPLED!' : ''}");
      if (specialization == 1 && activeHardcoreSetTier >= 2) {
        final selfHeal = (physDmg * 0.15).toInt();
        hp = (hp + selfHeal).clamp(0, maxHp);
        message += tr(" (+$selfHeal HP)", " (+$selfHeal HP)");
      }
    } else if (isElementalist) {
      int dmg = (magAtk * 2.5 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      if (specialization == 1 && activeHardcoreSetTier >= 2) {
        final burnDmg = (magAtk * 0.15).toInt();
        enemyEffects.removeWhere((e) => e.name == "Popálení (Set)");
        enemyEffects.add(StatusEffect(name: "Popálení (Set)", description: "Popálení $burnDmg/kolo", duration: 3, isBuff: false, dotDamage: burnDmg));
      }
      if (specialization == 2 && activeHardcoreSetTier >= 2) {
        final shieldGain = (maxHp * 0.10).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
      }
      if (specialization == 3 && activeHardcoreSetTier >= 2) {
        arcaneChargeStacks = (arcaneChargeStacks + 2).clamp(0, arcaneChargeMaxStacks);
      }
      dealAbilityDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.elementalist);
      message = tr("$prefix: Elementální výbuch! Způsobeno $dmg poškození.", "$prefix: Elementální výbuch! Dealt $dmg damage.");
    } else if (isBladeDancer) {
      int dmg = (physAtk * 2.2 * specAbilityDamageMod).toInt();
      if (specialization == 1 && activeHardcoreSetTier >= 2 && enemyMaxHp() > 0 && enemyHp() / enemyMaxHp() < 0.3) {
        dmg = (dmg * 1.3).toInt();
      }
      if (specialization == 3 && activeHardcoreSetTier >= 2) dmg = (dmg * critDamageMultiplier).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      dealAbilityDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.bladeDancer);
      _applyAbilityDot(dmg);
      if (specialization == 2 && activeHardcoreSetTier >= 2) {
        heroEffects.removeWhere((e) => e.name == "Elegantní Tanec");
        heroEffects.add(StatusEffect(name: "Elegantní Tanec", description: "+10 % úhyb", duration: 3, isBuff: true));
      }
      message = tr("$prefix: Rychlé combo! Způsobeno $dmg poškození.", "$prefix: Rychlé combo! Dealt $dmg damage.");
    } else if (isDisciple) {
      int dmg = (physAtk * 2.2 * specAbilityDamageMod).toInt();
      if (specialization == 1 && activeHardcoreSetTier >= 2) dmg = (dmg * 1.25).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      dealAbilityDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.disciple);
      if (specialization == 1) {
        final dot = (dmg * 0.15 / 3).round();
        // Krvácení (Vichr) se SČÍTÁ, ne resetuje - další zásah přidá dmg k stávajícímu tiku a
        // obnoví trvání, takže už nastřádaný damage nikdy nezmizí, jen se rozloží do dalších kol.
        final vichrIdx = enemyEffects.indexWhere((e) => e.name == "Krvácení (Vichr)");
        if (vichrIdx != -1) {
          final stackedDot = cappedVichrBleed(enemyEffects[vichrIdx].dotDamage + dot);
          enemyEffects[vichrIdx] = StatusEffect(name: "Krvácení (Vichr)", description: "Krvácení $stackedDot/kolo", duration: 3, isBuff: false, dotDamage: stackedDot);
        } else {
          enemyEffects.add(StatusEffect(name: "Krvácení (Vichr)", description: "Krvácení $dot/kolo", duration: 3, isBuff: false, dotDamage: dot));
        }
      }
      if (specialization == 2 && activeHardcoreSetTier >= 2) {
        final shieldGain = (maxHp * 0.15).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
      }
      message = tr("$prefix: Úder tisíce dlaní! Způsobeno $dmg poškození.", "$prefix: Úder tisíce dlaní! Dealt $dmg damage.");
      if (monkCalmHealFromDamage > 0) {
        double healPercent = monkCalmHealFromDamage;
        if (specialization == 3 && activeHardcoreSetTier >= 2) healPercent *= 2;
        final selfHeal = (dmg * healPercent * specAbilitySustainMod).toInt();
        hp = (hp + selfHeal).clamp(0, maxHp);
        message += tr(" Vyléčeno $selfHeal HP.", " Healed $selfHeal HP.");
      }
    } else if (isAstralDruid) {
      int dmg = (magAtk * 2.3 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      dealAbilityDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.astralDruid);
      final dot = (dmg * 0.18 / 3).round();
      enemyEffects.removeWhere((e) => e.name == "Uvadnutí");
      enemyEffects.add(StatusEffect(name: "Uvadnutí", description: "Přírodní DoT $dot/kolo", duration: 3, isBuff: false, dotDamage: dot));
      if (specialization == 3) {
        final selfHeal = (dmg * 0.15 * specAbilitySustainMod).toInt();
        hp = (hp + selfHeal).clamp(0, maxHp);
      }
      if (specialization == 2) {
        final shieldGain = (maxHp * 0.15 * specAbilitySustainMod).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
      }
      message = tr("$prefix: Divoký spár! Způsobeno $dmg poškození a nasazeno Uvadnutí ($dot/kolo).", "$prefix: Divoký spár! Dealt $dmg damage and applied Wither ($dot/round).");
    } else if (isFaithGuardian) {
      // Úder Spravedlnosti: fyzický úder + malý štít (větší u tank specializace).
      int dmg = (physAtk * 2.2 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      dealAbilityDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.faithGuardian);
      double shieldMult = 0.12;
      if (specialization == 1) shieldMult = 0.18;
      final shieldGain = (maxHp * shieldMult * specAbilitySustainMod).toInt();
      bonusShield += shieldGain;
      _applyShieldCap();
      if (specialization == 3) {
        final selfHeal = (dmg * 0.15 * specAbilitySustainMod).toInt();
        hp = (hp + selfHeal).clamp(0, maxHp);
      }
      message = tr("$prefix: Úder Spravedlnosti! Způsobeno $dmg poškození a štít (+$shieldGain).", "$prefix: Úder Spravedlnosti! Dealt $dmg damage and shield (+$shieldGain).");
    } else if (isFelBlade) {
      // Rozseknutí čepelemi: fyzický úder + Fel oheň (DoT na 3 kola).
      int dmg = (physAtk * 2.4 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      dealAbilityDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.felBlade);
      final dot = (dmg * 0.15 / 3).round();
      enemyEffects.removeWhere((e) => e.name == "Fel oheň");
      enemyEffects.add(StatusEffect(name: "Fel oheň", description: "Fel DoT $dot/kolo", duration: 3, isBuff: false, dotDamage: dot));
      if (specialization == 2) {
        final selfHeal = (dmg * 0.20 * specAbilitySustainMod).toInt();
        hp = (hp + selfHeal).clamp(0, maxHp);
      }
      // Hardcore set bonusy (Čepele Nekonečné Zkázy/Pomsta Propasti/Rouno Fel Stínu).
      if (activeHardcoreSetTier >= 2) {
        if (specialization == 1) {
          final extraDmg = (dmg * 0.5).toInt();
          dealAbilityDamage(extraDmg);
        } else if (specialization == 2) {
          bonusShield += (maxHp * 0.15 * specAbilitySustainMod).toInt();
          _applyShieldCap();
        } else if (specialization == 3) {
          final extraDot = dot;
          enemyEffects.removeWhere((e) => e.name == "Fel oheň");
          enemyEffects.add(StatusEffect(name: "Fel oheň", description: "Fel DoT ${extraDot * 2}/kolo", duration: felFireDuration, isBuff: false, dotDamage: extraDot * 2));
        }
      }
      if (activeHardcoreSetTier >= 6 && specialization == 1) {
        nextAttackGuaranteedCrit = true;
      }
      if (activeHardcoreSetTier >= 6 && specialization == 2) {
        hardcoreInvulnerableActive = true;
      }
      message = tr("$prefix: Rozseknutí čepelemi! Způsobeno $dmg poškození a nasazen Fel oheň ($dot/kolo).", "$prefix: Rozseknutí čepelemi! Dealt $dmg damage and applied Fel Fire ($dot/round).");
    } else if (isBoneLord) {
      // Kostěný Sluha: magický úder + přivolaný kostěný sluha přidá bonusové poškození.
      int dmg = (magAtk * 2.3 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      dealAbilityDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.boneLord);
      final petDmg = (magAtk * 0.6 * specAbilityDamageMod * (specialization == 1 ? 1.25 : 1.0)).toInt();
      dealAbilityDamage(petDmg);
      if (specialization == 3) {
        final selfHeal = ((dmg + petDmg) * 0.15 * specAbilitySustainMod).toInt();
        hp = (hp + selfHeal).clamp(0, maxHp);
      }
      // Hardcore set bonusy (Armáda Nemrtvých/Vládce Rozkladu/Pakt s Podsvětím).
      if (activeHardcoreSetTier >= 2) {
        if (specialization == 1) {
          dealAbilityDamage(petDmg);
        } else if (specialization == 2) {
          final extraDmg = (dmg * 0.5).toInt();
          dealAbilityDamage(extraDmg);
        } else if (specialization == 3) {
          hp = (hp + ((dmg + petDmg) * 0.15 * specAbilitySustainMod).toInt()).clamp(0, maxHp);
        }
      }
      if (activeHardcoreSetTier >= 6 && specialization == 1) {
        nextAttackGuaranteedCrit = true;
      }
      if (activeHardcoreSetTier >= 6 && specialization == 2) {
        hardcoreInvulnerableActive = true;
      }
      message = tr("$prefix: Kostěný Sluha! Způsobeno $dmg poškození + $petDmg od přivolaného sluhy.", "$prefix: Kostěný Sluha! Dealt $dmg damage + $petDmg from the summoned servant.");
    }
  }

  // ===== SDÍLENÁ TIER2 SCHOPNOST (Schopnost 2 / Paragon 40 "Ultimátní třída") =====
  // Stejný vzor jako _castTier1Ability - matematika identická napříč Lairem/Arénou/World
  // Bossem, liší se jen HP nepřítele a prefix zprávy. Věž (useSecondAbility) NENÍ sloučená -
  // má vlastní nekonzistentní cooldown systém (mix _scaledCooldown(X) s raw hodnotami a
  // dodatečnými hardcore úpravami cooldownu), takže zůstává samostatná, funkční beze změny.
  void _castTier2Ability(String prefix, int enemyDefValue, int Function() enemyHp, int Function() enemyMaxHp, void Function(int) enemyDamage) {
    void dealAbilityDamage(int damage) =>
        enemyDamage(applyAbilityExecute(damage, enemyHp(), enemyMaxHp()));
    final armorPenL2 = runeEffect(RuneEffectType.armorPen);
    final effDef = armorPenL2 > 0 ? (enemyDefValue * (1 - armorPenL2)).clamp(0, double.infinity).toInt() : enemyDefValue;
    if (isWarlord) {
      int dmg = (physAtk * 4.0 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      dealAbilityDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.warlord);
      double shieldMult = 0.25;
      if (specialization == 2 && activeHardcoreSetTier >= 4) shieldMult *= 2;
      final shieldGain = (maxHp * shieldMult * specAbilitySustainMod).toInt();
      bonusShield += shieldGain;
      _applyShieldCap();
      _applyAbilityDot(dmg);
      if (specialization == 3 && activeHardcoreSetTier >= 4) {
        final idx = enemyEffects.indexWhere((e) => e.name == "Krvácení (Krvežíznivý)");
        if (idx != -1 && enemyEffects[idx].duration < 6) enemyEffects[idx].duration = 6;
      }
      heroEffects.add(StatusEffect(name: "Warlordova hradba", description: "+25 % MaxHP štít", duration: 8, isBuff: true));
      message = tr("$prefix: Rozdrcení světa za $dmg poškození a velký štít (+$shieldGain).", "$prefix: Rozdrcení světa for $dmg damage and a large shield (+$shieldGain).");
      if (specialization == 1 && activeHardcoreSetTier >= 4) {
        rage = (rage + ability2Cost).clamp(0, maxRage);
        message += "Krvavý Vztek: " + tr("zdroj vrácen!", "resource refunded!");
      }
    } else if (isShadowMaster) {
      int dmg = (physAtk * 5.0).toInt();
      if (specialization == 1 && activeHardcoreSetTier >= 4) dmg = (dmg * 1.5).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      dealAbilityDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.shadowMaster);
      _applyAbilityDot(dmg);
      if (specialization == 3 && activeHardcoreSetTier >= 4) {
        final dot = (dmg * 0.10 / 3).round();
        enemyEffects.removeWhere((e) => e.name == "Jed (Stín)");
        enemyEffects.add(StatusEffect(name: "Jed (Stín)", description: "Jed $dot/kolo", duration: 3, isBuff: false, dotDamage: dot));
      }
      message = tr("$prefix: Stínová poprava za $dmg poškození.", "$prefix: Stínová poprava for $dmg damage.");
    } else if (isProrok) {
      hp = maxHp;
      int dmg = (magAtk * 3.5 * specAbilityDamageMod).toInt();
      if (specialization == 3 && activeHardcoreSetTier >= 4) dmg = (dmg * 1.5).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      dealAbilityDamage(dmg);
      _pushFx(FxKind.explosionDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.healerJudgment);
      if (specialization == 1 && activeHardcoreSetTier >= 4) {
        final shieldGain = (maxHp * 0.30).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
        message = tr("$prefix: Boží soud! Plné HP, úder za $dmg poškození a štít (+$shieldGain).", "$prefix: Boží soud! Full HP, a strike for $dmg damage, and a shield (+$shieldGain).");
      } else {
        message = tr("$prefix: Boží soud! Plné HP a úder za $dmg poškození.", "$prefix: Boží soud! Full HP and a strike for $dmg damage.");
      }
      if (specialization == 2 && activeHardcoreSetTier >= 4) {
        final bonusDmg = (magAtk * 0.20).toInt();
        dealAbilityDamage(bonusDmg);
        message += tr(" (Odplata: +$bonusDmg dmg)", " (Retribution: +$bonusDmg dmg)");
      }
    } else if (isPlagueLord) {
      // Rebalance: druhý spell je vždy užitečný. Odpálí PŘESNĚ zbývající Curse damage (bez ×4 násobiče)
      // a vždy udělí adaptivní absorb štít - čím méně kol Prokletí zbývalo, tím větší štít.
      final double triple = nextSpellTriple ? 3.0 : 1.0;
      if (nextSpellTriple) { nextSpellTriple = false; soulRunes = 0; }
      final prokl = enemyEffects.firstWhere((e) => e.name == "Prokletí", orElse: () => StatusEffect(name: "", description: "", duration: 0, isBuff: false));
      final bool hasCurse = prokl.name == "Prokletí";
      final int remainingDotTurns = hasCurse ? prokl.duration : 0;
      final int originalDotDmg = hasCurse ? prokl.dotDamage : 0;
      int remainingCurseDamage = hasCurse ? (prokl.dotDamage * remainingDotTurns * triple * curseDmgMod).toInt() : 0;
      if (specialization == 2 && activeHardcoreSetTier >= 4) remainingCurseDamage = (remainingCurseDamage * 1.5).toInt();
      if (remainingCurseDamage > 0) dealAbilityDamage(remainingCurseDamage);
      _applyKrevPassiveLifesteal(remainingCurseDamage);
      if (hasCurse) {
        enemyEffects.removeWhere((e) => e.name == "Prokletí");
        if (specialization == 3 && activeHardcoreSetTier >= 4) {
          final newDuration = (4 + curseCastDurationDelta).clamp(1, 99);
          enemyEffects.add(StatusEffect(name: "Prokletí", description: "Prokletí $originalDotDmg/kolo", duration: newDuration, isBuff: false, dotDamage: originalDotDmg));
        }
      }
      const int maxDotTurns = 4;
      final double completion = 1.0 - (remainingDotTurns / maxDotTurns);
      final double shieldPercent = 25 + (completion * 50);
      final int shieldGain = (maxHp * (shieldPercent / 100)).toInt();
      bonusShield += shieldGain;
      _applyShieldCap();
      if (remainingCurseDamage > 0) {
        _pushFx(FxKind.explosionDamage, FxSide.enemy, value: remainingCurseDamage, spellFxKind: SpellFxKind.dkCurseExplosion);
      } else {
        _pushFx(FxKind.shieldGained, FxSide.hero, value: shieldGain, spellFxKind: SpellFxKind.dkCurseExplosion);
      }
      if (remainingCurseDamage > 0) {
        message = tr("$prefix 💥 Exploze prokletí za $remainingCurseDamage poškození a štít +$shieldGain!${triple > 1 ? ' ✨ TROJNÁSOBEK!' : ''}", "$prefix 💥 Curse Explosion for $remainingCurseDamage damage and shield +$shieldGain!${triple > 1 ? ' ✨ TRIPLED!' : ''}");
      } else {
        message = tr("$prefix: Žádné aktivní Prokletí - vytvořen absorb štít +$shieldGain.", "$prefix: No active Curse - created an absorb shield +$shieldGain.");
      }
      if (specialization == 1 && activeHardcoreSetTier >= 4 && remainingCurseDamage > 0) {
        hp = (hp + remainingCurseDamage).clamp(0, maxHp);
        message += tr(" (+$remainingCurseDamage HP)", " (+$remainingCurseDamage HP)");
      }
    } else if (isArcanist) {
      // Arcanista: silný burst + úspora many (refund části nákladu na tuto schopnost).
      int dmg = (magAtk * 4.5 * specAbilityDamageMod).toInt();
      if (specialization == 3 && activeHardcoreSetTier >= 4) {
        dmg = (dmg * (1 + arcaneChargeStacks * arcaneChargePerStack)).toInt();
      }
      dmg = _minDmg(dmg, dmg - effDef);
      dealAbilityDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.arcanist);
      double manaRefundMult = 0.3;
      if (specialization == 1 && activeHardcoreSetTier >= 4) manaRefundMult *= 2;
      mana = (mana + (ability2Cost * manaRefundMult).toInt()).clamp(0, maxMana);
      message = tr("$prefix: Arkánový nával za $dmg poškození (část many vrácena).", "$prefix: Arkánový nával for $dmg damage (part of the mana refunded).");
    } else if (isBladeMaster) {
      int dmg = (physAtk * 5.0 * specAbilityDamageMod).toInt();
      if (specialization == 1 && activeHardcoreSetTier >= 4 && enemyMaxHp() > 0 && enemyHp() / enemyMaxHp() < 0.3) {
        dmg = (dmg * 1.3).toInt();
      }
      if (specialization == 3 && activeHardcoreSetTier >= 4) dmg = (dmg * 1.5).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      dealAbilityDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.bladeMaster);
      _applyAbilityDot(dmg);
      message = tr("$prefix: Precizní výpad za $dmg poškození.", "$prefix: Precizní výpad for $dmg damage.");
    } else if (isGrandmaster) {
      int dmg = (physAtk * 4.5 * specAbilityDamageMod).toInt();
      if (specialization == 1 && activeHardcoreSetTier >= 4 && enemyMaxHp() > 0 && enemyHp() / enemyMaxHp() < 0.3) {
        dmg = (dmg * 1.3).toInt();
      }
      dmg = _minDmg(dmg, dmg - effDef);
      dealAbilityDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.grandmaster);
      double shieldMult = 0.20;
      if (specialization == 2 && activeHardcoreSetTier >= 4) shieldMult *= 2;
      final shieldGain = (maxHp * shieldMult * specAbilitySustainMod).toInt();
      bonusShield += shieldGain;
      _applyShieldCap();
      message = tr("$prefix: Dračí kop! Způsobeno $dmg poškození a získán štít (+$shieldGain).", "$prefix: Dračí kop! Dealt $dmg damage and gained a shield (+$shieldGain).");
      if (specialization == 1) {
        final dot = (dmg * 0.15 / 3).round();
        // Krvácení (Vichr) se SČÍTÁ, ne resetuje - další zásah přidá dmg k stávajícímu tiku a
        // obnoví trvání, takže už nastřádaný damage nikdy nezmizí, jen se rozloží do dalších kol.
        final vichrIdx = enemyEffects.indexWhere((e) => e.name == "Krvácení (Vichr)");
        if (vichrIdx != -1) {
          final stackedDot = cappedVichrBleed(enemyEffects[vichrIdx].dotDamage + dot);
          enemyEffects[vichrIdx] = StatusEffect(name: "Krvácení (Vichr)", description: "Krvácení $stackedDot/kolo", duration: 3, isBuff: false, dotDamage: stackedDot);
        } else {
          enemyEffects.add(StatusEffect(name: "Krvácení (Vichr)", description: "Krvácení $dot/kolo", duration: 3, isBuff: false, dotDamage: dot));
        }
      }
      if (monkCalmHealFromDamage > 0) {
        final selfHeal = (dmg * monkCalmHealFromDamage * specAbilitySustainMod).toInt();
        hp = (hp + selfHeal).clamp(0, maxHp);
        message += tr(" Vyléčeno $selfHeal HP.", " Healed $selfHeal HP.");
      }
      if (specialization == 3 && activeHardcoreSetTier >= 4) {
        final extraHeal = (dmg * 0.25).toInt();
        hp = (hp + extraHeal).clamp(0, maxHp);
        message += tr(" (+$extraHeal HP)", " (+$extraHeal HP)");
      }
    } else if (isMoonfury) {
      int dmg = (magAtk * 3.2 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      dealAbilityDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.moonfury);
      if (specialization == 2) {
        final shieldGain = (maxHp * 0.18 * specAbilitySustainMod).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
      }
      if (specialization == 3) {
        final selfHeal = (dmg * 0.15 * specAbilitySustainMod).toInt();
        hp = (hp + selfHeal).clamp(0, maxHp);
      }
      message = tr("$prefix: Hvězdný pád! Způsobeno $dmg poškození.", "$prefix: Hvězdný pád! Dealt $dmg damage.");
    } else if (isRetributor) {
      // Boží Trest: silný fyzický burst z posvátného hněvu.
      int dmg = (physAtk * 4.5 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      dealAbilityDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.retributor);
      if (specialization == 1) {
        final shieldGain = (maxHp * 0.15 * specAbilitySustainMod).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
      }
      if (specialization == 3) {
        final selfHeal = (dmg * 0.15 * specAbilitySustainMod).toInt();
        hp = (hp + selfHeal).clamp(0, maxHp);
      }
      message = tr("$prefix: Boží Trest! Způsobeno $dmg poškození.", "$prefix: Boží Trest! Dealt $dmg damage.");
    } else if (isDemonSlayer) {
      // Metamorfóza: masivní fyzický burst v démonické podobě.
      int dmg = (physAtk * 4.8 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      dealAbilityDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.demonSlayer);
      if (specialization == 2) {
        final selfHeal = (dmg * 0.25 * specAbilitySustainMod).toInt();
        hp = (hp + selfHeal).clamp(0, maxHp);
      }
      message = tr("$prefix: Metamorfóza! Způsobeno $dmg poškození.", "$prefix: Metamorfóza! Dealt $dmg damage.");
    } else if (isDeathSovereign) {
      // Volání Nemrtvých: přivolá vlnu nemrtvých za silný magický burst.
      int dmg = (magAtk * 4.5 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      dealAbilityDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.deathSovereign);
      if (specialization == 2) {
        final dot = (dmg * 0.15 / 3).round();
        enemyEffects.removeWhere((e) => e.name == "Rozklad");
        enemyEffects.add(StatusEffect(name: "Rozklad", description: "Rozklad $dot/kolo", duration: 3, isBuff: false, dotDamage: dot));
      }
      message = tr("$prefix: Volání Nemrtvých! Způsobeno $dmg poškození.", "$prefix: Volání Nemrtvých! Dealt $dmg damage.");
    }
  }

  // ===== SDÍLENÁ TIER3 SCHOPNOST (Schopnost 3 / Paragon 75 "Boží třída") =====
  // Stejný vzor jako _castTier1Ability/_castTier2Ability. Věž (useThirdAbility) NENÍ sloučená -
  // stejná cooldown nekonzistence jako u tier1/2 (raw hodnoty 12-16 dle třídy, +hardcore úprava).
  void _castTier3Ability(String prefix, int enemyDefValue, int Function() enemyHp, int Function() enemyMaxHp, void Function(int) enemyDamage) {
    void dealAbilityDamage(int damage) =>
        enemyDamage(applyAbilityExecute(damage, enemyHp(), enemyMaxHp()));
    final armorPenL3 = runeEffect(RuneEffectType.armorPen);
    final effDef = armorPenL3 > 0 ? (enemyDefValue * (1 - armorPenL3)).clamp(0, double.infinity).toInt() : enemyDefValue;
    if (isValhallaWarrior) {
      int dmg = (physAtk * 7.5 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      dealAbilityDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.valhallaWarrior);
      final shieldGain = (maxHp * 0.50 * specAbilitySustainMod).toInt();
      bonusShield += shieldGain;
      _applyShieldCap();
      _applyAbilityDot(dmg);
      if (specialization == 3 && activeHardcoreSetTier >= 6) {
        final dot = ((dmg * 0.20 / 3) * 2).round();
        enemyEffects.removeWhere((e) => e.name == "Krvácení (Krvežíznivý)");
        enemyEffects.add(StatusEffect(name: "Krvácení (Krvežíznivý)", description: "Krvácení $dot/kolo", duration: 6, isBuff: false, dotDamage: dot));
      }
      heroEffects.add(StatusEffect(name: "Valhalla", description: "+50 % MaxHP štít", duration: 10, isBuff: true));
      if (specialization == 2 && activeHardcoreSetTier >= 6) {
        hardcoreInvulnerableActive = true;
      }
      message = tr("$prefix: Boží hněv za $dmg poškození a obří štít (+$shieldGain).", "$prefix: Boží hněv for $dmg damage and a huge shield (+$shieldGain).");
    } else if (isVoidStalker) {
      int dmg = (physAtk * 8.0).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      dealAbilityDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.voidStalker);
      hp = maxHp;
      _applyAbilityDot(dmg);
      if (specialization == 3 && activeHardcoreSetTier >= 6) {
        final idx = enemyEffects.indexWhere((e) => e.name == "Jed (Stín)");
        if (idx != -1) enemyEffects[idx].duration = 10;
      }
      if (specialization == 2 && activeHardcoreSetTier >= 6) {
        heroEffects.removeWhere((e) => e.name == "Divoký Hon");
        heroEffects.add(StatusEffect(name: "Divoký Hon", description: "+20 % úhyb", duration: 5, isBuff: true));
      }
      message = tr("$prefix: Prázdnotová bouře za $dmg poškození a plné HP.", "$prefix: Prázdnotová bouře for $dmg damage and full HP.");
      if (specialization == 1 && activeHardcoreSetTier >= 6) {
        nextAttackGuaranteedCrit = true;
        message += "Neomylná Stopa: " + tr("další útok bude kritický!", "the next attack will be critical!");
      }
    } else if (isLightBearer) {
      int dmg = (magAtk * 7.0 * specAbilityDamageMod).toInt();
      if (specialization == 3 && activeHardcoreSetTier >= 6) dmg *= 2;
      dmg = _minDmg(dmg, dmg - effDef);
      dealAbilityDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.lightBearer);
      double shieldMult = 0.50;
      if (specialization == 2 && activeHardcoreSetTier >= 6) shieldMult *= 2;
      final shieldGain = (maxHp * shieldMult * specAbilitySustainMod).toInt();
      bonusShield += shieldGain;
      _applyShieldCap();
      hp = maxHp;
      message = tr("$prefix: Nebeský rozsudek za $dmg poškození, plné HP a štít (+$shieldGain).", "$prefix: Nebeský rozsudek for $dmg damage, full HP, and a shield (+$shieldGain).");
      if (specialization == 2 && activeHardcoreSetTier >= 6) {
        dealAbilityDamage(shieldGain);
        message += tr(" (Odplata: celý štít odražen, -$shieldGain nepříteli!)", " (Retribution: the entire shield reflected, -$shieldGain to the enemy!)");
      }
    } else if (isDeathReaper) {
      final double triple = nextSpellTriple ? 3.0 : 1.0;
      if (nextSpellTriple) { nextSpellTriple = false; soulRunes = 0; }
      int physDmg = (physAtk * 2.0 * triple).toInt();
      if (specialization == 2 && activeHardcoreSetTier >= 6) physDmg = (physDmg * critDamageMultiplier).toInt();
      physDmg = _minDmg(physDmg, physDmg - effDef);
      int magDmg  = (magAtk  * 2.0 * triple).toInt();
      dealAbilityDamage(physDmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: physDmg, spellFxKind: SpellFxKind.deathReaper);
      _applyKrevPassiveLifesteal(physDmg);
      if (specialization == 3 && activeHardcoreSetTier >= 6) {
        final dotDmg = (magAtk * 0.5 * curseDmgMod).toInt();
        final curseDuration = (4 + curseCastDurationDelta).clamp(1, 99);
        enemyEffects.removeWhere((e) => e.name == "Prokletí");
        enemyEffects.add(StatusEffect(name: "Prokletí", description: "Prokletí $dotDmg/kolo", duration: curseDuration, isBuff: false, dotDamage: dotDmg));
      }
      if (specialization == 1 && activeHardcoreSetTier >= 6) {
        bonusShield += magDmg;
        _applyShieldCap();
        hp = (hp + magDmg).clamp(0, maxHp);
        message = tr("$prefix 💀 Úder smrti! $physDmg dmg. Krvavý Pakt: +$magDmg HP i štít současně!${triple > 1 ? ' ✨ TROJNÁSOBEK!' : ''}", "$prefix 💀 Úder smrti! $physDmg dmg. Krvavý Pakt: +$magDmg HP and shield at once!${triple > 1 ? ' ✨ TRIPLED!' : ''}");
      } else if (hp >= maxHp) {
        bonusShield += magDmg;
        _applyShieldCap();
        message = tr("$prefix 💀 Úder smrti! $physDmg dmg + absorb $magDmg při plném HP.${triple > 1 ? ' ✨ TROJNÁSOBEK!' : ''}", "$prefix 💀 Úder smrti! $physDmg dmg + absorb $magDmg at full HP.${triple > 1 ? ' ✨ TRIPLED!' : ''}");
      } else {
        hp = (hp + magDmg).clamp(0, maxHp);
        message = tr("$prefix 💀 Úder smrti! $physDmg dmg + léčení $magDmg HP.${triple > 1 ? ' ✨ TROJNÁSOBEK!' : ''}", "$prefix 💀 Úder smrti! $physDmg dmg + healed $magDmg HP.${triple > 1 ? ' ✨ TRIPLED!' : ''}");
      }
    } else if (isArchmage) {
      int dmg = (magAtk * 8.0 * specAbilityDamageMod).toInt();
      if (specialization == 1 && activeHardcoreSetTier >= 6) {
        final burnDmg = (magAtk * 0.20).toInt();
        enemyEffects.removeWhere((e) => e.name == "Popálení (Set)");
        enemyEffects.add(StatusEffect(name: "Popálení (Set)", description: "Popálení $burnDmg/kolo", duration: 3, isBuff: false, dotDamage: burnDmg));
      }
      dmg = _minDmg(dmg, dmg - effDef);
      dealAbilityDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.archmage);
      double shieldMult = 0.40;
      if (specialization == 2 && activeHardcoreSetTier >= 6) shieldMult *= 2;
      final shieldGain = (maxHp * shieldMult * specAbilitySustainMod).toInt();
      bonusShield += shieldGain;
      _applyShieldCap();
      message = tr("$prefix: Archmágův příval za $dmg poškození a arkánový ward (+$shieldGain).", "$prefix: Archmágův příval for $dmg damage and an arcane ward (+$shieldGain).");
      if (specialization == 3 && activeHardcoreSetTier >= 6) {
        mana = (mana + ability3Cost).clamp(0, maxMana);
        message += "Arkánová Nekonečnost: " + tr("schopnost byla zdarma!", "the ability was free!");
      }
    } else if (isStormblade) {
      int dmg = (physAtk * 8.5 * specAbilityDamageMod).toInt();
      if (specialization == 1 && activeHardcoreSetTier >= 6 && enemyMaxHp() > 0 && enemyHp() / enemyMaxHp() < 0.3) {
        dmg = (dmg * 1.6).toInt();
      }
      if (specialization == 3 && activeHardcoreSetTier >= 6) dmg = (dmg * critDamageMultiplier).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      dealAbilityDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.stormblade);
      hp = maxHp;
      _applyAbilityDot(dmg);
      message = tr("$prefix: Bouře čepelí za $dmg poškození a plné HP.", "$prefix: Bouře čepelí for $dmg damage and full HP.");
      if (specialization == 2 && activeHardcoreSetTier >= 6) {
        heroEffects.removeWhere((e) => e.name == "Elegantní Tanec");
        heroEffects.add(StatusEffect(name: "Elegantní Tanec", description: "+10 % úhyb", duration: 8, isBuff: true));
        message += "Elegantní Tanec: " + tr("+10 % úhyb na 8 kol!", "+10% dodge for 8 rounds!");
      }
    } else if (isEnlightened) {
      int dmg = (physAtk * 7.5 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      dealAbilityDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.enlightened);
      hp = maxHp;
      final shieldGain = (maxHp * 0.40 * specAbilitySustainMod).toInt();
      bonusShield += shieldGain;
      _applyShieldCap();
      heroEffects.add(StatusEffect(name: "Nebeská Harmonie", description: "+40 % MaxHP štít", duration: 10, isBuff: true));
      message = tr("$prefix: Nebeská Harmonie! $dmg poškození, plné HP a štít (+$shieldGain).", "$prefix: Nebeská Harmonie! $dmg damage, full HP, and a shield (+$shieldGain).");
      if (specialization == 1) {
        double bleedMult = 1.5;
        if (activeHardcoreSetTier >= 6) bleedMult *= 2;
        final dot = ((dmg * 0.15 / 3) * bleedMult).round();
        // Krvácení (Vichr) se SČÍTÁ, ne resetuje - další zásah přidá dmg k stávajícímu tiku a
        // obnoví trvání, takže už nastřádaný damage nikdy nezmizí, jen se rozloží do dalších kol.
        final vichrIdx = enemyEffects.indexWhere((e) => e.name == "Krvácení (Vichr)");
        if (vichrIdx != -1) {
          final stackedDot = cappedVichrBleed(enemyEffects[vichrIdx].dotDamage + dot);
          enemyEffects[vichrIdx] = StatusEffect(name: "Krvácení (Vichr)", description: "Krvácení $stackedDot/kolo", duration: 3, isBuff: false, dotDamage: stackedDot);
        } else {
          enemyEffects.add(StatusEffect(name: "Krvácení (Vichr)", description: "Krvácení $dot/kolo", duration: 3, isBuff: false, dotDamage: dot));
        }
      }
      if (specialization == 2 && activeHardcoreSetTier >= 6) {
        hardcoreInvulnerableActive = true;
      }
      if (specialization == 3 && activeHardcoreSetTier >= 6) {
        heroEffects.removeWhere((e) => e.name == "Probuzení Ducha");
        heroEffects.add(StatusEffect(name: "Probuzení Ducha", description: "+15 % heal/absorb, -15 % dmg taken", duration: 3, isBuff: true));
        message += "Tichá Meditace: " + tr("Probuzení Ducha na 3 kola!", "Awakened Spirit for 3 rounds!");
      }
    } else if (isElderTreant) {
      int dmg = (magAtk * 3.6 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      dealAbilityDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.elderTreant);
      hp = maxHp;
      final shieldGain = (maxHp * 0.35 * specAbilitySustainMod).toInt();
      bonusShield += shieldGain;
      _applyShieldCap();
      message = tr("$prefix: Srdce Lesa! $dmg poškození, plné HP a štít (+$shieldGain).", "$prefix: Srdce Lesa! $dmg damage, full HP, and a shield (+$shieldGain).");
    } else if (isCrusader) {
      // Posvátný Val: fyzický úder + plné HP + velký štít - ultimátní "vše v jednom".
      int dmg = (physAtk * 3.6 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      dealAbilityDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.crusader);
      hp = maxHp;
      final shieldGain = (maxHp * 0.40 * specAbilitySustainMod).toInt();
      bonusShield += shieldGain;
      _applyShieldCap();
      message = tr("$prefix: Posvátný Val! $dmg poškození, plné HP a štít (+$shieldGain).", "$prefix: Posvátný Val! $dmg damage, full HP, and a shield (+$shieldGain).");
    } else if (isAbyssWalker) {
      // Pekelný Žár: fyzický úder + silný lifesteal na dlouho (Pomsta navíc dostane štít).
      int dmg = (physAtk * 3.2 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      dealAbilityDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.abyssWalker);
      lifestealTurns += 10;
      if (specialization == 2) {
        final shieldGain = (maxHp * 0.30 * specAbilitySustainMod).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
      }
      message = tr("$prefix: Pekelný Žár! $dmg poškození a silný lifesteal na 10 kol.", "$prefix: Pekelný Žár! $dmg damage and strong lifesteal for 10 rounds.");
    } else if (isGraveWarden) {
      // Rituál Krve a Kostí: obětuje kostěné sluhy za magický úder, plné HP a dlouhý lifesteal.
      int dmg = (magAtk * 3.2 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      dealAbilityDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.graveWarden);
      hp = maxHp;
      lifestealTurns += 8;
      message = tr("$prefix: Rituál Krve a Kostí! $dmg poškození, plné HP a lifesteal na 8 kol.", "$prefix: Rituál Krve a Kostí! $dmg damage, full HP, and lifesteal for 8 rounds.");
    }
  }

  // ===== SDÍLENÁ TIER4 SCHOPNOST (Rank 100, 3 volby na třídu) =====
  // Stejný vzor jako tier1-3. Věž (useFourthAbility) NENÍ sloučená - nejrozmanitější cooldown
  // ze všech tierů (33 různých hodnot, 3 na třídu). Navíc objevena skutečná mode-specific
  // mechanika: Chronomancer/Bleskový Mistr (volba 3) resetují "použito" flagy Schopnosti 1-3
  // v TOMTO souboji - řešeno přes resetLowerAbilities() callback (Lair/Aréna/World Boss mají
  // každý svoje vlastní flagy).
  void _castTier4Ability(String prefix, int enemyDefValue, int Function() enemyHp, int Function() enemyMaxHp, void Function(int) enemyDamage, void Function() resetLowerAbilities) {
    void dealAbilityDamage(int damage) =>
        enemyDamage(applyAbilityExecute(damage, enemyHp(), enemyMaxHp()));
    final armorPenL4 = runeEffect(RuneEffectType.armorPen);
    final effDef = armorPenL4 > 0 ? (enemyDefValue * (1 - armorPenL4)).clamp(0, double.infinity).toInt() : enemyDefValue;
    if (heroClass == HeroClass.warrior) {
      if (rank100Choice == 1) {
        int dmg = (physAtk * 12.0 * specAbilityDamageMod).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        dealAbilityDamage(dmg);
        final shieldGain = (maxHp * 0.75 * specAbilitySustainMod).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
        _applyAbilityDot(dmg);
        message = tr("$prefix (Titan): Patář světa za $dmg poškození a obří štít (+$shieldGain)!", "$prefix (Titan): World-Breaker for $dmg damage and a huge shield (+$shieldGain)!");
      } else if (rank100Choice == 2) {
        int dmg = (physAtk * 15.0 * specAbilityDamageMod).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        dealAbilityDamage(dmg);
        _applyAbilityDot(dmg);
        message = tr("$prefix (Juggernaut): Nezničitelný úder za $dmg poškození!", "$prefix (Juggernaut): Unstoppable Strike for $dmg damage!");
      } else if (rank100Choice == 3) {
        hp = maxHp;
        final shieldGain = (maxHp * 0.75 * specAbilitySustainMod).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
        message = tr("$prefix (Svořitel Války): Válečný vládce - plné HP a štít (+$shieldGain)!", "$prefix (Svořitel Války): Warlord - full HP and a shield (+$shieldGain)!");
      }
    } else if (heroClass == HeroClass.hunter) {
      if (rank100Choice == 1) {
        int dmg = (physAtk * 13.0).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        dealAbilityDamage(dmg);
        _applyAbilityDot(dmg);
        message = tr("$prefix (Vendeta): Mistrovská poprava za $dmg poškození!", "$prefix (Vendeta): Masterful Execution for $dmg damage!");
      } else if (rank100Choice == 2) {
        int dmg = (physAtk * 11.0).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        dealAbilityDamage(dmg);
        lifestealTurns += 15;
        _applyAbilityDot(dmg);
        message = tr("$prefix (Přízrak): Přízračný skok za $dmg poškození!", "$prefix (Přízrak): Phantom Leap for $dmg damage!");
      } else if (rank100Choice == 3) {
        int dmg = (physAtk * 14.0).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        dealAbilityDamage(dmg);
        hp = maxHp;
        _applyAbilityDot(dmg);
        message = tr("$prefix (Kosmický Lovec): Kosmická bouře za $dmg poškození!", "$prefix (Kosmický Lovec): Cosmic Storm for $dmg damage!");
      }
    } else if (heroClass == HeroClass.healer) {
      if (rank100Choice == 1) {
        hp = maxHp;
        final shieldGain = (maxHp * 0.75 * specAbilitySustainMod).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
        int dmg = (magAtk * 10.0 * specAbilityDamageMod).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        dealAbilityDamage(dmg);
        message = tr("$prefix (Vládce magie): Astrální výbuch za $dmg poškození a štít (+$shieldGain)!", "$prefix (Vládce magie): Astral Burst for $dmg damage and a shield (+$shieldGain)!");
      } else if (rank100Choice == 2) {
        hp = maxHp;
        lifestealTurns += 20;
        message = tr("$prefix (Mistr Života): Věčný život - plné HP a lifesteal!", "$prefix (Mistr Života): Eternal Life - full HP and lifesteal!");
      } else if (rank100Choice == 3) {
        int dmg = (magAtk * 16.0 * specAbilityDamageMod).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        dealAbilityDamage(dmg);
        message = tr("$prefix (Svatý Osvícený): Boží paprsek za $dmg poškození!", "$prefix (Svatý Osvícený): Divine Ray for $dmg damage!");
      }
    } else if (heroClass == HeroClass.deathknight) {
      final double triple = nextSpellTriple ? 3.0 : 1.0;
      if (nextSpellTriple) { nextSpellTriple = false; soulRunes = 0; }
      if (rank100Choice == 1) {
        int physDmg = (physAtk * 2.0 * triple).toInt();
        physDmg = _minDmg(physDmg, physDmg - effDef);
        int explodeDmg = (magAtk * 5 * 4 * triple * curseDmgMod).toInt();
        dealAbilityDamage((physDmg + explodeDmg));
        _applyKrevPassiveLifesteal(physDmg + explodeDmg);
        message = tr("$prefix (Kostěný Lich): Prokletí za ${physDmg + explodeDmg} poškození!${triple > 1 ? ' ✨ TROJNÁSOBEK!' : ''}", "$prefix (Kostěný Lich): Curse for ${physDmg + explodeDmg} damage!${triple > 1 ? ' ✨ TRIPLED!' : ''}");
      } else if (rank100Choice == 2) {
        int dmg = ((physAtk + magAtk) * 5.0 * triple).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        dealAbilityDamage(dmg);
        _applyKrevPassiveLifesteal(dmg);
        lifestealTurns += 15;
        message = tr("$prefix (Temný Reaper): Smrtící řez za $dmg dmg + lifesteal!${triple > 1 ? ' ✨ TROJNÁSOBEK!' : ''}", "$prefix (Temný Reaper): Deadly Cut for $dmg dmg + lifesteal!${triple > 1 ? ' ✨ TRIPLED!' : ''}");
      } else if (rank100Choice == 3) {
        int dmg = (magAtk * 4.0 * triple).toInt();
