        bonusShield += (maxHp * 0.5 * triple).toInt();
        _applyShieldCap();
        soulRunes = 7; // unikátní bonus Pán Duší - viz stejná oprava/poznámka u Tower verze v useFourthAbility().
        message = tr("$prefix (Pán Duší): $dmg dmg + plné HP + masivní štít!${triple > 1 ? ' ✨ TROJNÁSOBEK!' : ''}", "$prefix (Pán Duší): $dmg dmg + full HP + massive shield!${triple > 1 ? ' ✨ TRIPLED!' : ''}");
      }
    } else if (heroClass == HeroClass.mage) {
      if (rank100Choice == 1) {
