  }

  bool _applyGemDefense(int rawDamageTaken, void Function(int reflectedDmg) dealReflectedDamage) {
    if (activeGemType == null) return false;
    if (gemReflectionActive && rawDamageTaken > 0) {
      final reflected = (rawDamageTaken * activeGemMagnitude).round();
      if (reflected > 0) {
        dealReflectedDamage(reflected);
        message += "Gem Odrazu: " + tr("$reflected dmg vráceno!", "$reflected dmg reflected back!");
      }
      // ===== SYNERGIE: Gem Odrazu =====
      if (_hasGemSynergy("Gem Odrazu", "ws_reflection7")) {
        if (_isWarriorLikeClass) {
          heroEffects.removeWhere((e) => e.name == "Odrazový štít");
          heroEffects.add(StatusEffect(name: "Odrazový štít", description: "+10 % šance na blok", duration: 2, isBuff: true));
          message += "Odrazový štít: " + tr("+10 % blok na 2 kola!", "+10% block for 2 rounds!");
        } else if (_isHealLikeClass && reflected > 0) {
          final healBack = (reflected * 0.30).round();
          hp = (hp + healBack).clamp(0, maxHp);
          message += "Odražené milosrdenství: " + tr("+$healBack HP!", "+$healBack HP!");
        } else if (_isCasterLikeClass && reflected > 0) {
          final dot = (reflected * 0.5).round().clamp(1, 999999);
          enemyEffects.removeWhere((e) => e.name == "Zrcadlový mor");
          enemyEffects.add(StatusEffect(name: "Zrcadlový mor", description: "Jed $dot/kolo", duration: 2, isBuff: false, dotDamage: dot));
          message += " ☠️ Zrcadlový mor!";
        } else if (heroClass == HeroClass.hunter) {
          final counter = (physAtk * 0.25).round();
          currentEnemyHp -= counter;
          message += "Protistřela: " + tr("$counter dmg navíc!", "$counter extra dmg!");
        } else if (_isDruidClass && reflected > 0) {
          final shield = (reflected * 0.5).round();
          bonusShield += shield;
          _applyShieldCap();
          message += "Kůra stromu: " + tr("+$shield štít!", "+$shield shield!");
        } else if (_isPaladinClass) {
          heroEffects.removeWhere((e) => e.name == "Val víry");
          heroEffects.add(StatusEffect(name: "Val víry", description: "+10 % šance na blok", duration: 2, isBuff: true));
          message += "Val víry: " + tr("+10 % blok na 2 kola!", "+10% block for 2 rounds!");
        } else if (_isDemonHunterClass) {
          final counter = (physAtk * 0.25).round();
          currentEnemyHp -= counter;
          message += "Fel odolnost: " + tr("$counter dmg navíc!", "$counter extra dmg!");
        } else if (_isNecromancerClass) {
          heroEffects.removeWhere((e) => e.name == "Nekrotická odolnost");
          heroEffects.add(StatusEffect(name: "Nekrotická odolnost", description: "+10 % redukce poškození", duration: 2, isBuff: true));
          message += "Nekrotická odolnost: " + tr("+10 % redukce na 2 kola!", "+10% reduction for 2 rounds!");
        }
      }
    }
    if (hp <= 0 && gemRevivalActive && Random().nextDouble() < activeGemMagnitude) {
      hp = (maxHp * 0.33).toInt();
      message += "Gem Oživení: " + tr("unikl jsi smrti s ${hp} HP!", "you escaped death with ${hp} HP!");
      // ===== SYNERGIE: Gem Oživení =====
      if (_hasGemSynergy("Gem Oživení", "ws_revival7")) {
        if (_isWarriorLikeClass) {
          heroEffects.removeWhere((e) => e.name == "Bojový vztek");
          heroEffects.add(StatusEffect(name: "Bojový vztek", description: "+50 % kritické poškození příštího útoku", duration: 1, isBuff: true));
          message += "Bojový vztek: " + tr("příští útok +50 % krit dmg!", "next attack +50% crit dmg!");
        } else if (_isHealLikeClass) {
          final healPulse = (magAtk * 0.20).round();
          hp = (hp + healPulse).clamp(0, maxHp);
          message += "Vlna obnovy: " + tr("+$healPulse HP navíc!", "+$healPulse extra HP!");
        } else if (_isCasterLikeClass) {
          final shield = (magAtk * 0.30).round();
          bonusShield += shield;
          _applyShieldCap();
          message += "Nouzový štít: " + tr("+$shield na 2 kola!", "+$shield for 2 rounds!");
        } else if (heroClass == HeroClass.hunter) {
          final bonus = (physAtk * 0.5).round();
          currentEnemyHp -= bonus;
          message += "Druhý dech: " + tr("volný výstřel za $bonus dmg!", "a free shot for $bonus dmg!");
        } else if (_isDruidClass) {
          final shield = (maxHp * 0.10).round();
          bonusShield += shield;
          _applyShieldCap();
          message += "Srdce pralesa: " + tr("+$shield štít navíc!", "+$shield extra shield!");
        } else if (_isPaladinClass) {
          final shield = (maxHp * 0.10).round();
          bonusShield += shield;
          _applyShieldCap();
          message += "Nezdolná hradba: " + tr("+$shield štít navíc!", "+$shield extra shield!");
        } else if (_isDemonHunterClass) {
          heroEffects.removeWhere((e) => e.name == "Nesmrtelná Pomsta");
          heroEffects.add(StatusEffect(name: "Nesmrtelná Pomsta", description: "Zdvojnásobený lifesteal", duration: 2, isBuff: true));
          message += "Nesmrtelná Pomsta: " + tr("lifesteal zdvojnásoben na 2 kola!", "lifesteal doubled for 2 rounds!");
        } else if (_isNecromancerClass) {
          final shield = (magAtk * 0.30).round();
          bonusShield += shield;
          _applyShieldCap();
          message += "Vládce Kostí: " + tr("sluha vstřebá $shield dmg!", "the servant absorbs $shield dmg!");
        }
      }
      return true;
    }
    return false;
  }

  // Gem Temnoty -> "Ochrana": +X % k účinnosti heal/block/dodge/absorb (opak prokletí Temnoty).
  double get gemSustainBonus => gemDarknessActive ? (1 + activeGemMagnitude) : 1.0;

  // ===== SYNERGIE: Gem Temnoty — dává třídám zcela NOVÝ zdroj sustainu, co by jinak neměly.
  // Volá se z fight() po výpočtu dealtDmg (má tedy k dispozici finální hodnotu útoku).
  void _applyDarknessSynergy(int dealtDmg) {
    if (dealtDmg <= 0) return;
    if (!_hasGemSynergy("Gem Temnoty", "ws_darkness7")) return;
    if (_isWarriorLikeClass) {
      final heal = (dealtDmg * 0.10).round();
      hp = (hp + heal).clamp(0, maxHp);
      message += "Temný nádech: " + tr("+$heal HP!", "+$heal HP!");
    } else if (_isCasterLikeClass) {
      final heal = (dealtDmg * 0.08).round();
      hp = (hp + heal).clamp(0, maxHp);
      message += "Temné sání: " + tr("+$heal HP!", "+$heal HP!");
    } else if (heroClass == HeroClass.hunter && huntersMarkStacks > 0) {
      final heal = (dealtDmg * 0.05 * huntersMarkStacks).round();
      hp = (hp + heal).clamp(0, maxHp);
      message += "Značka temnoty: " + tr("+$heal HP!", "+$heal HP!");
    } else if (_isDemonHunterClass) {
      final heal = (dealtDmg * 0.09).round();
      hp = (hp + heal).clamp(0, maxHp);
      message += "Fel hlad: " + tr("+$heal HP!", "+$heal HP!");
    } else if (_isNecromancerClass) {
      final heal = (dealtDmg * 0.09).round();
      hp = (hp + heal).clamp(0, maxHp);
      message += "Krvavý pakt: " + tr("+$heal HP!", "+$heal HP!");
    }
    // Mnich/Léčitel + Druid/Paladin: jejich Temnoty synergie je "heal-into-shield" - viz _healIntoShieldSynergy(),
    // volá se odkudkoliv, kde už dochází k self-healu (lifesteal/štít z útoku léčitele).
  }

  void _healIntoShieldSynergy(int healAmount) {
    if (healAmount <= 0 || !(_isHealLikeClass || _isDruidClass || _isPaladinClass)) return;
    if (!_hasGemSynergy("Gem Temnoty", "ws_darkness7")) return;
    final ratio = _isHealLikeClass ? 0.25 : 0.15;
    final shield = (healAmount * ratio).round();
    if (shield > 0) {
      bonusShield += shield;
      _applyShieldCap();
      final label = _isDruidClass ? "Symbióza" : (_isPaladinClass ? "Světlo v temnotě" : "Temný závoj");
      message += "$label: " + tr("+$shield štít!", "+$shield shield!");
    }
  }

  // ===== PROKLETÍ OSUDU — odměna za aktivní prokletí: (25×tier) % zlato/dust/xp, (1×tier) % loot =====
  // Odměna škáluje s hardcoreTier, aby risk/reward zůstal proporční i v pozdějších tierech
  // (obtížnost roste × (1.0 + 0.5×tier), takže odměna roste podobným tempem: +25 %/tier, +1 %/tier).
  // Předpeklí a Peklo přidávají další flat vrstvy navrch, nezávisle na tom, jestli je zrovna
  // aktivní i prokletí.
  double get curseRewardMultiplier {
    double mult = activeCurse != CurseOfFate.none ? 1.0 + 0.25 * hardcoreTier : 1.0;
    if (atLeastPredpekli && predpekliUnlocked) mult += predpekliRewardBonus;
    if (pekloMode && pekloUnlocked) mult += pekloRewardBonus;
    return mult;
  }

  double get curseLootBonus {
    double bonus = activeCurse != CurseOfFate.none ? 0.01 * hardcoreTier : 0.0;
    if (atLeastPredpekli && predpekliUnlocked) bonus += predpekliLootBonus;
    if (pekloMode && pekloUnlocked) bonus += pekloLootBonus;
    return bonus;
  }

  // Temnota: sníží efektivitu heal/block/dodge/absorb o 30 %.
  double get curseDarknessMod => activeCurse == CurseOfFate.darkness ? 0.70 : 1.0;

  // Vrátí násobitel pro daný stat POUZE pokud ho aktuální třída na Paragonu posiluje.
  // Vitalitu posiluje Paragon vždy (u všech tříd), Sílu jen Warrior, Wisdom jen Léčitel, Agility jen Lovec.
  // Deathknight posiluje obojí — Sílu i Moudrost (hybridní třída).
  // Příklad: Paragon 3 u Warriora vrátí pro "Strength" 1.30 (tj. +30 %).
  double paragonMultiplierFor(String statName) {
    if (paragonLevel <= 0) return 1.0;
    final profile = specStatProfile;
    double weight = 0.0;
    if (statName == "Vitality" || statName == profile.mainStat) {
      weight = 1.0;
    } else if (statName == profile.secondaryStat) {
      weight = profile.secondaryWeight;
    }
    return 1.0 + paragonLevel * 0.10 * weight;
  }

  bool get isBerserk => heroClass == HeroClass.warrior && (classRanks[HeroClass.warrior] ?? 0) >= 15;

  // Živý číselný náhled Tier 1 schopnosti pro dlouhé podržení (viz SpellIconButton.description) -
  // vzorce ověřené přímo z useActiveAbility()/useLairActiveAbility()/atd. (matematika je napříč
  // Věží/Lairem/Arénou/World Bossem/Riftem stejná, liší se jen cíl útoku, ne čísla samotná).
  // POZOR: pokrývá zatím jen Tier 1 - Tier 2-4 a Relikvie mají vlastní, zatím nezmapované vzorce.
  String tier1NumericPreview() {
    switch (heroClass) {
      case HeroClass.warrior:
        final dmg = (physAtk * 2.5 * specAbilityDamageMod).round();
        return tr('Poškození: ~$dmg (fyzické)', 'Damage: ~$dmg (physical)');
      case HeroClass.hunter:
        final dmg = (physAtk * 2.0).round();
        final heal = (dmg * 0.5).round();
        return tr('Poškození: ~$dmg (fyzické)\nLéčení: ~$heal HP (50 % dmg)', 'Damage: ~$dmg (physical)\nHeal: ~$heal HP (50% of dmg)');
      case HeroClass.healer:
        final heal = (maxHp * 0.5 * specAbilitySustainMod).round();
        final shield = (maxHp * 0.10 * specAbilitySustainMod).round();
        return tr('Léčení: ~$heal HP (50 % MaxHP)\nŠtít: +$shield (10 % MaxHP)', 'Heal: ~$heal HP (50% MaxHP)\nShield: +$shield (10% MaxHP)');
      case HeroClass.deathknight:
        final dmg = (physAtk * 1.5).round();
        final dotPerRound = (magAtk * 0.5).round();
        return tr('Poškození: ~$dmg (fyzické)\nProkletí: ~$dotPerRound/kolo po 4 kola', 'Damage: ~$dmg (physical)\nCurse: ~$dotPerRound/round for 4 rounds');
      case HeroClass.mage:
        final dmg = (magAtk * 2.5 * specAbilityDamageMod).round();
        return tr('Poškození: ~$dmg (magické)', 'Damage: ~$dmg (magic)');
      case HeroClass.duelist:
        final dmg = (physAtk * 2.2 * specAbilityDamageMod).round();
        return tr('Poškození: ~$dmg (fyzické)', 'Damage: ~$dmg (physical)');
      case HeroClass.monk:
        final dmg = (physAtk * 2.2 * specAbilityDamageMod).round();
        if (monkCalmHealFromDamage > 0) {
          final heal = (dmg * monkCalmHealFromDamage * specAbilitySustainMod).round();
          return tr('Poškození: ~$dmg (fyzické)\nLéčení: ~$heal HP', 'Damage: ~$dmg (physical)\nHeal: ~$heal HP');
        }
        return tr('Poškození: ~$dmg (fyzické)', 'Damage: ~$dmg (physical)');
      case HeroClass.druid:
        final dmg = (magAtk * 2.3 * specAbilityDamageMod).round();
        final dot = (dmg * 0.18 / 3).round();
        return tr('Poškození: ~$dmg (magické)\nUvadnutí: ~$dot/kolo po 3 kola', 'Damage: ~$dmg (magic)\nWither: ~$dot/round for 3 rounds');
      case HeroClass.paladin:
        final dmg = (physAtk * 2.2 * specAbilityDamageMod).round();
        final shieldMult = specialization == 1 ? 0.18 : 0.12;
        final shield = (maxHp * shieldMult * specAbilitySustainMod).round();
        return tr('Poškození: ~$dmg (fyzické)\nŠtít: +$shield', 'Damage: ~$dmg (physical)\nShield: +$shield');
      case HeroClass.demonhunter:
        final dmg = (physAtk * 2.4 * specAbilityDamageMod).round();
        final dot = (dmg * 0.15 / 3).round();
        return tr('Poškození: ~$dmg (fyzické)\nFel oheň: ~$dot/kolo po 3 kola', 'Damage: ~$dmg (physical)\nFel Fire: ~$dot/round for 3 rounds');
      case HeroClass.necromancer:
        final dmg = (magAtk * 2.3 * specAbilityDamageMod).round();
        final petDmg = (magAtk * 0.6 * specAbilityDamageMod).round();
        return tr('Poškození: ~$dmg (magické)\nSluha: +$petDmg navíc', 'Damage: ~$dmg (magic)\nServant: +$petDmg extra');
      case HeroClass.none:
        return '';
    }
  }

