  // Ikona aktuální třídy pro FantasyIconFrame (viz fantasy_icons.dart) - reflektuje
  // odemčenou "flavor" podtřídu (Priest/Necromancer), ne jen základní třídu.
  FantasyIconType get heroClassIcon {
    switch (heroClass) {
      case HeroClass.warrior:
        return FantasyIconType.classWarrior;
      case HeroClass.hunter:
        return FantasyIconType.classHunter;
      case HeroClass.healer:
        return FantasyIconType.classPriest;
      case HeroClass.deathknight:
        return (isPlagueLord || isDeathReaper) ? FantasyIconType.classNecromancer : FantasyIconType.classDeathKnight;
      case HeroClass.mage:
        return FantasyIconType.classMage;
      case HeroClass.duelist:
        return FantasyIconType.classDuelist;
      case HeroClass.monk:
        return FantasyIconType.classMonk;
      case HeroClass.druid:
        return FantasyIconType.classDruid;
      case HeroClass.paladin:
        return FantasyIconType.classPaladin;
      case HeroClass.demonhunter:
        return FantasyIconType.classDemonHunter;
      case HeroClass.necromancer:
        return FantasyIconType.classNecromancer;
      case HeroClass.none:
        return FantasyIconType.classWarrior;
    }
  }

  bool get isRank100Unlocked => (classRanks[heroClass] ?? 0) >= 100;
  bool get hasRank100Class => isRank100Unlocked && rank100Choice > 0;

  bool get canAbsorbOverheal => alchemistRank >= 10 || isPriest || isProrok || hasGodClass || hasRank100Class || activeCompanions.any((c) => c.role == CompanionRole.healer);

  // ===== BUILD INSPECTOR / DENNÍ CÍLE =====
  // ===== UI PREHLEDNOST: GEAR SCORE, BUILD, BOSS GUIDE, ADVENTURE GUIDE =====
  // Gear Score jako % vůči doporučené hodnotě pro aktuální patro (100 = na úrovni patra), ne
  // syrové číslo ze statů - to by na Normal obtížnost rostlo do statisíců. 100-400 pokrývá
  // rozpětí od "podgearovaný" po "výrazně nad doporučením" v rámci Normal progrese.
  int get gearScore {
    final attack = physAtk > magAtk ? physAtk : magAtk;
    final defense = armor;
    final chances = ((critChance + dodgeChance + blockChance) * 1000).round();
    final rawPower = (attack * 12 + defense * 6 + maxHp * 2 + chances).round();
    final recommended = recommendedGearScoreForFloor(floor);
    return recommended > 0 ? ((rawPower / recommended) * 100).round() : rawPower;
  }
  int recommendedGearScoreForFloor(int targetFloor) {
    final f=targetFloor.clamp(1,99999);
    return (500+165*f+5.5*f*f).round();
  }
  // ===== SÍLA JEDNOTLIVÉHO ITEMU — pro srovnání "je tohle lepší než co mám nasazené?" =====
  // SPECIALIZAČNĚ VÁŽENÉ (ne jen class-přesně) - čte přímo ze specStatProfile, stejný zdroj
  // pravdy jako physAtk/magAtk/armor. Hlavní stat aktuální specializace plná váha, vedlejší
  // stat váha úměrná jeho secondaryWeight (0,2-0,5 v profilu -> 1,0-2,5 zde), "cizí" třetí stat
  // jen okrajová hodnota. Používá se JEN pro relativní srovnání dvou itemů stejného slotu.
  int itemPowerScore(Item item) {
    double score = 0;
    final profile = specStatProfile;
    final isTankSpec = specialization != 0 && profile.tankArmorCoefficient > 1.0;
    // Násobiče podle zvolené loot priority (viz LootPriorityMode) - balanced nechává poměr
    // ofenziva/defenziva netknutý (jak to dřív vždy bylo), offensive/defensive ho vychýlí.
    // Pozn.: přiřazeno rovnou při deklaraci (ne ve switch větvích) - jinak Dart flow analysis
    // u proměnných rozdělených přes samostatné case větve neumí staticky ověřit definitivní
    // přiřazení, i když je to logicky vždy pokryté (viz historie stejného problému u main.dart).
    double offW = 1.0, defW = 1.0;
    if (lootPriorityMode == LootPriorityMode.offensive) { offW = 1.6; defW = 0.4; }
    else if (lootPriorityMode == LootPriorityMode.defensive) { offW = 0.4; defW = 1.6; }
    for (final k in item.stats.keys) {
      final effective = (item.stats[k] ?? 0) * item.upgradeMultiplier * setSlotUpgradeMultiplier(item);
      switch (k) {
        case "Strength": case "Agility": case "Wisdom":
          double w;
          if (k == profile.mainStat) {
            w = 5;
          } else if (k == profile.secondaryStat) {
            w = profile.secondaryWeight * 5; // 0,2-0,5 v profilu škáluje na 1,0-2,5 zde
          } else {
            w = 0.3; // "cizí" stat, co tahle specializace prakticky nevyužije
          }
          score += effective * w * offW;
          break;
        case "Vitality":
          score += effective * 2 * defW; // univerzální, hodí se každé třídě/specializaci stejně
          break;
        case "Armor":
          // Tank specializace z Armoru těží násobně víc (viz tankArmorCoefficient v armor getteru).
          score += effective * (isTankSpec ? 12 : 6) * defW;
          break;
        case "Block":
          // Blok je teď univerzálně navázaný na Sílu, ale hodnotu z NĚJ táhne hlavně Tank build.
          score += effective * (isTankSpec ? 50 : 15) * defW;
          break;
        case "Crit": case "Dodge":
          // Univerzální ofenzivní staty (Agility i Wisdom oba živí Crit) - Tank z nich těží méně.
          score += effective * (isTankSpec ? 15 : 35) * offW;
          break;
        case "Attack Speed":
          score += effective * 40 * offW; // úmyslně univerzální balance páka, viz design poznámky
          break;
        default:
          score += effective * 3;
      }
    }
    if (item.gemSlotCount > 0) score += item.gemSlots.where((g) => g != null).length * 25;
    // Elitní sety (Hardcore/Předpeklí/Peklo) mají mainstat bonus počítaný ŽIVĚ z počtu nasazených
    // kusů (viz _activeEliteSetMainStatBonus: statValue × level × count), NE zapečený do item.stats
    // - takže smyčka výš tenhle příspěvek nikdy nevidí a osamocený kus setu vychází v score katastrofálně
    // slabý proti legendary itemu se stejným iLvl (přesně nahlášený bug). Marginální příspěvek JEDNOHO
    // kusu k živému bonusu je konstantní statValue × level (bonus roste lineárně s počtem kusů), takže
    // ho ohodnotíme stejnou váhou, jakou by dostal jako mainstat, kdyby byl normálně zapečený.
    HardcoreSetDef? eliteSetDef;
    if (item.hardcoreSetId != null) {
      final m = hardcoreSets.where((s) => s.id == item.hardcoreSetId);
      eliteSetDef = m.isNotEmpty ? m.first : null;
    } else if (item.predpekliSetId != null) {
      final m = predpekliSets.where((s) => s.id == item.predpekliSetId);
      eliteSetDef = m.isNotEmpty ? m.first : null;
    } else if (item.pekloSetId != null) {
      final m = pekloSets.where((s) => s.id == item.pekloSetId);
      eliteSetDef = m.isNotEmpty ? m.first : null;
    }
    if (eliteSetDef != null) {
      final marginal = (eliteSetDef.statValue * level).toDouble();
      final isMainOrSecondary = eliteSetDef.statName == profile.mainStat || eliteSetDef.statName == profile.secondaryStat;
      final w = eliteSetDef.statName == profile.mainStat ? 5.0 : (isMainOrSecondary ? profile.secondaryWeight * 5 : 0.3);
      score += marginal * w * offW;
      // Paušální odhad hodnoty 4/6/8pc bonusů (dmg/def % škálující s celým buildem) - nejde přesně
      // vyčíslit z jednoho itemu izolovaně, ale i hrubý odhad je nesrovnatelně lepší než nula.
      score += 400;
    }
    score *= (1 + item.rarity.index * 0.05); // drobný bonus za vzácnost při shodných statech
    return score.round();
  }

  // ===== ITEM LEVEL — objektivní síla itemu, NEZÁVISLE na tom, kdo ho nosí =====
  // Na rozdíl od itemPowerScore ("Gear Score" - jak je item výhodný PRO TEBE, váženo dle
  // aktuální třídy/specializace) tahle funkce bere všechny staty ROVNOCENNĚ - stejné váhy pro
  // každého, bez ohledu na main/secondary/combat stat profil. Určuje, jak silný item objektivně
  // je, ne jak moc se hodí právě tobě. Váhy jsou průměrem toho, co itemPowerScore dává
  // primárním/sekundárním statům (aby čísla zůstala v podobném řádu, jen bez preferencí).
  int itemLevelScore(Item item) {
    double score = 0;
    for (final k in item.stats.keys) {
      final effective = (item.stats[k] ?? 0) * item.upgradeMultiplier * setSlotUpgradeMultiplier(item);
      switch (k) {
        case "Strength": case "Agility": case "Wisdom":
          score += effective * 2.7; // generická váha - průměr mezi hlavním (5) a "cizím" (0,3) statem
          break;
        case "Vitality":
          score += effective * 2;
          break;
        case "Armor":
          score += effective * 9; // průměr Tank (12) / non-Tank (6)
          break;
        case "Block":
          score += effective * 32.5; // průměr Tank (50) / non-Tank (15)
          break;
        case "Crit": case "Dodge":
          score += effective * 25; // průměr Tank (15) / non-Tank (35)
          break;
        case "Attack Speed":
          score += effective * 40;
          break;
        default:
          score += effective * 3;
      }
    }
    if (item.gemSlotCount > 0) score += item.gemSlots.where((g) => g != null).length * 25;
    score *= (1 + item.rarity.index * 0.05);
    // SET itemy nesou navíc pasivku (2pc/4pc/6pc/8pc bonusy) - klasický item se stejnými staty
    // ji nemá, takže je objektivně slabší. Peklo set (rudý) je nejsilnější, Předpeklí (fialový)
    // o stupeň níž, Hardcore (modrý) další, klasický set (zelený) nejslabší z SET vybavení.
    if (item.pekloSetId != null) {
      score *= 1.45;
    } else if (item.predpekliSetId != null) {
      score *= 1.35;
    } else if (item.hardcoreSetId != null) {
      score *= 1.25;
    } else if (item.setId != null) {
      score *= 1.15;
    }
    return score.round();
  }

  // ===== NEJLEPŠÍ MOŽNÝ GEAR — pro Arénu, aby hráč nemohl gearRatio uměle snížit tím, že si
  // záměrně něco nenasadí. Počítá se z CELÉHO inventáře (nasazené i uskladněné), pro každý slot
  // se vezme nejsilnější vlastněný kus dle itemLevelScore. Přívěsek má 2 sloty - vezmou se 2
  // nejlepší kusy, ne jen 1. Relic slot se nepočítá (má vlastní pity/progres systém, nezávislý
  // na běžném dropu, nedává smysl srovnávat proti obecné referenční křivce).
  int get bestPossibleGearItemLevel {
    const singleSlots = [EquipSlot.weapon, EquipSlot.armor, EquipSlot.gloves, EquipSlot.boots, EquipSlot.ring, EquipSlot.helmet, EquipSlot.belt, EquipSlot.cloak, EquipSlot.shoulders];
    int total = 0;
    for (final slot in singleSlots) {
      final candidates = inventory.where((i) => i.slot == slot).map(itemLevelScore);
      if (candidates.isNotEmpty) total += candidates.reduce((a, b) => a > b ? a : b);
    }
    final accessoryScores = inventory.where((i) => i.slot == EquipSlot.accessory).map(itemLevelScore).toList()..sort((a, b) => b.compareTo(a));
    for (int i = 0; i < 2 && i < accessoryScores.length; i++) {
      total += accessoryScores[i];
    }
    return total;
  }

  // ===== REFERENČNÍ KŘIVKA ITEM LEVELU PRO ARÉNU — lineární podle ligy (ne exponenciální jako
  // Věž), protože soupeř je "AI bot", co jede stále stejným tempem, zatímco hráč (chytřejší,
  // umí spelly/rotaci) má nad ním mít navrch PŘI stejném nebo lepším gearu. Čísla jsou první
  // odhad, ne změřená z reálných dat - je třeba doladit po testování s reálnými hráči/postupem.
  static const double _arenaItemLevelBase = 3000; // referenční hodnota pro ligu 1
  static const double _arenaItemLevelPerLeague = 3000; // přírůstek za KAŽDOU další ligu (i v Gladiátorovi, přes rating)
  double get arenaItemLevelReference {
    if (arenaIsGladiator) {
      // Gladiátor pokračuje ve STEJNÉ přímce - každých 100 ratingu = "jedna další liga" tempa růstu.
      return _arenaItemLevelBase + 9 * _arenaItemLevelPerLeague + (arenaRating / 100) * _arenaItemLevelPerLeague;
    }
    return _arenaItemLevelBase + arenaLeagueIndex * _arenaItemLevelPerLeague;
  }

  // Poměr tvého nejlepšího možného gearu k referenci pro tvoji ligu, a z něj koeficient síly
  // soupeře. 1,2 / gearRatio znamená: i na PŘESNĚ doporučeném gearu (gearRatio=1,0) je soupeř
  // o 20 % silnější (koeficient 1,2) - to je záměrný handicap, co má simulovat "AI bot bez
  // chytrosti hráče". Lepší gear než referenci koeficient sníží pod 1,0 (soupeř slabší).
  double get arenaGearAdjustedMult {
    final ratio = (bestPossibleGearItemLevel / arenaItemLevelReference).clamp(0.1, double.infinity);
    return (1.2 / ratio).clamp(0.7, 2.0);
  }

  // Nejslabší aktuálně nasazený item v daném slotu (Přívěsek má 2 sloty - porovnává se
  // s tím SLABŠÍM, protože ten bys reálně vyměnil). Null = slot je prázdný/nic tam nemáš.
  int? weakestEquippedScoreForSlot(EquipSlot? slot) {
    if (slot == null) return null;
    final inSlot = equipment.where((e) => e.slot == slot).toList();
    if (inSlot.isEmpty) return null;
    return inSlot.map(itemPowerScore).reduce((a, b) => a < b ? a : b);
  }
  String get buildRoleLabel => specialization==0 ? 'Nespecializovany hrdina' : specializationRoleFor(specialization);
  String get buildSetLabel => activeHardcoreSetDef?.name ?? activeGearSetDef?.name ?? 'Zadny aktivni set';
  String get buildRelicLabel => activeRelic?.displayName ?? 'Zadny aktivni amulet';
  String get buildArtifactLabel => activeArtifactWeaponDef?.name ?? 'Zadny aktivni artefakt';
  List<String> get buildOverview => [
    'Class: ${heroClass.name.toUpperCase()}', 'Specializace: $specializationName',
    'Role: $buildRoleLabel', 'Set: $buildSetLabel', 'Amulet: $buildRelicLabel',
    'Artefakt: $buildArtifactLabel', 'Gem: ${activeGemType ?? "Zadny"}',
  ];
  String get towerBossStrongAgainst {
    final r=<String>[];
    if(r.isEmpty)r.add(currentEnemyIsMagical?'nizka odolnost vuci magii':'nizka odolnost vuci fyzickemu utoku'); return r.join(', ');
  }
  String get towerBossCounter {
    final r=<String>[];
    if(currentEnemyIsMagical)r.add('Armor (poloviční efekt) a HP');else r.add('Armor a blok');
    return r.join(', ');
  }
  List<Map<String,Object>> get adventureGuideChapters => [
    {'title':'Dosahni levelu 20','done':level>=20,'progress':'${level.clamp(0,20)}/20','reward':'Gold a lektvary'},
    {'title':'Odemkni signature Basic Attack','done':paragonLevel>=15,'progress':'${paragonLevel.clamp(0,15)}/15 Paragon','reward':'Novy Basic Attack'},
    {'title':'Vyber specializaci','done':specialization!=0,'progress':specialization==0?'Nezvoleno':specializationName,'reward':'Specializacni build'},
    {'title':'Dosahni Tower 100','done':floor>=100,'progress':'${floor.clamp(0,100)}/100','reward':'Endgame postup'},
    {'title':'Dokonci Rift Tier 10','done':riftTier>=10,'progress':'${riftTier.clamp(0,10)}/10','reward':'Amulet XP'},
    {'title':'Ziskej prvni amulet','done':unlockedRelicIds.isNotEmpty,'progress':'${unlockedRelicIds.length}/1','reward':'Amulet system'},
    {'title':'Poraz World Bosse','done':worldBossKills>0,'progress':'$worldBossKills kill','reward':'Runovy kamen a Amulet XP'},
    {'title':'Dokonci Lair 100','done':defeatedLairFloors.contains(100),'progress':defeatedLairFloors.contains(100)?'Dokonceno':'Nedokonceno','reward':'Prsten Osudu'},
  ];

  int get inspectorGearScore => gearScore;
  String get inspectorPrimaryDamage {
    if (activeGemType != null && activeGemType!.toLowerCase().contains('jed')) return 'Poškození v čase / Jed';
    if (heroClass==HeroClass.deathknight && specialization==3) return 'Prokletí a DoT';
    if ((heroClass==HeroClass.warrior && specialization==3)) return 'Krvácení';
    if (critChance>=0.30) return 'Kritické zásahy';
    return classIsMagicAttack?'Magické schopnosti':'Fyzické schopnosti';
  }
  String get inspectorPrimaryDefense {
    if (blockChance>=dodgeChance && blockChance>=0.20) return 'Block a redukce zásahu';
    if (dodgeChance>blockChance && dodgeChance>=0.20) return 'Dodge';
    if (bonusShield>maxHp*0.25) return 'Absorb štít';
    return 'Armor a HP';
  }
  List<String> get buildInspectorRecommendations {
    final r=<String>[];
    if (specialization==0) r.add('Dosáhni level 25 a Paragon 10 a vyber specializaci.');
    if (activeHardcoreSetTier<4) r.add('Aktivuj alespoň 4dílný Hardcore set pro výraznější mechanickou synergii.');
    if (activeRelic==null) r.add('Aktivuj amulet odpovídající roli buildu.');
    if (critChance<0.20 && (specialization==1 || heroClass==HeroClass.duelist)) r.add('Pro DPS větev zvyš Crit Chance alespoň k 20 %.');
    if (heroClass==HeroClass.warrior && specialization==2 && blockChance<0.25) r.add('Ochránce potřebuje více Block Chance.');
    if (r.isEmpty) r.add('Build je funkční. Další růst směřuj do hlavního damage statutu a setové synergie.');
    return r;
  }
  bool get dailyWorldBossDone => !worldBossAvailable;
  bool get dailyRiftDone => riftClearsToday>0;
  bool get dailyQuestDone => quests.any((q)=>q.type==QuestType.daily && q.isCompleted);
  bool get dailyRuneDone => weeklyRuneBossKills>0;
  int get dailyGoalsDone => [dailyWorldBossDone,dailyRiftDone,dailyQuestDone,dailyRuneDone].where((v)=>v).length;
  bool get dailyCacheReady => dailyGoalsDone>=3 && !dailyCacheClaimed;

  // Kronika: +1 Mince Osudu za KAŽDÝ ze 4 denních cílů, jednorázově za den (nezávislé na
  // dailyCacheClaimed výš, což je samostatná bonusová odměna za 3+/4). dailyGoalCoinsClaimed
  // sleduje které indexy (0=WorldBoss,1=Rift,2=Quest,3=Rune) už dnes minci daly. Volá se přímo
  // v místech, kde se podkladový stav mění (viz komentáře u volání), ne globálně přes
  // notifyListeners(), ať se to nevolá zbytečně na každý překreslení.
  void _checkDailyChronicleCoin(int goalIndex, bool done) {
    if (!done || dailyGoalCoinsClaimed.contains(goalIndex)) return;
    dailyGoalCoinsClaimed.add(goalIndex);
    fateCoins++;
    message = tr("🪙 Denní cíl splněn! +1 Mince Osudu (na roll v Kronice).", "🪙 Daily goal completed! +1 Coin of Fate (for rolling in the Chronicle).");
  }

  void claimDailyCache() {
    if (!dailyCacheReady) return;
    dailyCacheClaimed = true;
    gold += 500;
    magicDust += 150;
    crystals += (30 * kCrystalDropBonus).round();
    addRelicXp(5);
    message = tr("📦 Denní Cache vyzvednuta! +500 🪙, +150 Dust, +30 💎, +5 Amulet XP.", "📦 Daily Cache claimed! +500 🪙, +150 Dust, +30 💎, +5 Amulet XP.");
    notifyListeners();
  }

  bool get isTowerDefenseSpecialist=>isBoss&&((heroClass==HeroClass.mage&&specialization==2)||(heroClass==HeroClass.monk&&specialization==2));
  void _rewardTowerDefense(){if(!isTowerDefenseSpecialist)return;final sh=(maxHp*(heroClass==HeroClass.mage?0.04:0.05)).round();bonusShield+=sh;_applyShieldCap();final r=heroClass==HeroClass.mage?8:10;if(heroClass==HeroClass.mage)mana=(mana+r).clamp(0,maxMana);else energy=(energy+r).clamp(0,maxEnergy);message+=" " + tr("Obranná odměna: štít +$sh, zdroj +$r.", "Defensive reward: shield +$sh, resource +$r.");}
  int get maxHp {
    double modifier = 1 + (0.05 * (classMultiplier - 1));
    if (isBerserk || isWarlord) modifier += 0.15;
    if (isPriest || isProrok) modifier += 0.15;
    if (isDarkKnight || isPlagueLord) modifier += 0.10; // DK: solidní výdrž
    if (hasGodClass) modifier += 0.30;
    if (hasRank100Class) modifier += 0.50;
    modifier += gearSetDefHpBonus;
    modifier += eliteSet8pcDefHpBonus;
    return ((baseMaxHp + itemBonusHp + (totalVitality * 8)) * modifier * relicHpMult / ascensionPowerSquish).toInt();
  }

  int get physAtk {
    int bonus = 0;
    if (heroClass == HeroClass.warrior || heroClass == HeroClass.hunter) bonus = (classMultiplier - 1) * 5;
    if (heroClass == HeroClass.deathknight) bonus = (classMultiplier - 1) * 4; // DK: mírně nižší než čistý fyzický
    if (heroClass == HeroClass.duelist) bonus = (classMultiplier - 1) * 5;
    if (heroClass == HeroClass.monk) bonus = (classMultiplier - 1) * 5; // Mnich: melee, ale škáluje z Moudrosti
    if (heroClass == HeroClass.paladin) bonus = (classMultiplier - 1) * 5; // Paladin: fyzický jako Warrior
    if (heroClass == HeroClass.demonhunter) bonus = (classMultiplier - 1) * 5; // Lovec Démonů: fyzický jako Duelist
    double modifier = 1 + (0.01 * (classMultiplier - 1));
    if (hasAdvancedClass) modifier += 0.10;
    if (hasUltimateClass) modifier += 0.15;
    if (hasGodClass) modifier += 0.25;
    if (hasRank100Class) modifier += 0.40;
    modifier += gearSetPhysDmgBonus;
    modifier += eliteSet8pcDmgBonus;
    // Fyzický scaling stat teď čte ze specStatProfile (spec-přesný, ne jen class-přesný) -
    // Strength/Agility přispívají do physAtk JEN pokud jsou hlavní nebo vedlejší stat AKTUÁLNÍ
    // specializace; Wisdom do physAtk nikdy nepřispívá (feeds jen magAtk, viz níže).
    final profile = specStatProfile;
    double physScaling = 0;
    if (profile.mainStat == "Strength" || profile.mainStat == "Agility") physScaling += _statValueByKey(profile.mainStat) * 1.0;
    if (profile.secondaryStat == "Strength" || profile.secondaryStat == "Agility") physScaling += _statValueByKey(profile.secondaryStat) * profile.secondaryWeight;
    final int strTerm = physScaling.toInt();
    // Obecný modifikátor z nepřátelských schopností (viz enemyAbilityEffects) - součet přes
    // všechny aktivní heroEffects, záporná hodnota = debuff. clamp na >=0, ať to nejde do minusu.
    final double physAtkEffMod = (1 + heroEffects.fold(0.0, (s, e) => s + e.physAtkMod)).clamp(0.0, 10.0).toDouble();
    return ((basePhysAtk + itemBonusPhysAtk + strTerm + bonus) * modifier * physAtkPotionModifier * relicDamageMult * relicMasteryDamageMult * (gladiatorSetSynergy?1.15:1.0) / ascensionPowerSquish * physAtkEffMod).toInt();
  }

  // +15 % z Lektvaru Síly, pokud je aktivní.
  double get physAtkPotionModifier =>
      heroEffects.any((e) => e.name == "Lektvar Síly") ? 1.15 : 1.0;

  int get magAtk {
    int bonus = 0;
    if (heroClass == HeroClass.healer) bonus = (classMultiplier - 1) * 5;
    if (heroClass == HeroClass.deathknight) bonus = (classMultiplier - 1) * 4; // DK: hybridní mag složka
    if (heroClass == HeroClass.mage) bonus = (classMultiplier - 1) * 6; // Mág: čistě magická třída, nejsilnější mag bonus
    if (heroClass == HeroClass.druid) bonus = (classMultiplier - 1) * 5; // Druid: čistě magická třída jako Healer
    if (heroClass == HeroClass.necromancer) bonus = (classMultiplier - 1) * 5; // Nekromant: čistě magická třída jako Healer
    double modifier = 1 + (0.01 * (classMultiplier - 1));
    if (isPriest || isProrok) modifier += 0.10;
    if (isProrok) modifier += 0.15;
    if (isDarkKnight) modifier += 0.05; // DK: základní mag bonus
    if (isPlagueLord) modifier += 0.10;
    if (isElementalist || isArcanist) modifier += 0.12; // Mág: silnější škálování než hybridní třídy
    if (isArcanist) modifier += 0.13;
    if (isAstralDruid || isMoonfury) modifier += 0.11; // Druid: podobné škálování jako Mág
    if (isMoonfury) modifier += 0.12;
    if (isBoneLord || isDeathSovereign) modifier += 0.11; // Nekromant: podobné škálování jako Druid
    if (isDeathSovereign) modifier += 0.12;
    if (hasGodClass) modifier += 0.25;
    if (hasRank100Class) modifier += 0.40;
    modifier += gearSetMagDmgBonus;
    modifier += eliteSet8pcDmgBonus;
    // Magický scaling stat teď čte ze specStatProfile - Wisdom přispívá do magAtk JEN pokud je
    // hlavní nebo vedlejší stat AKTUÁLNÍ specializace (u čistých casterů vždy hlavní; u hybridů
    // jako DK/Paladin-Posvěcený/Necromancer-Krvavý Rituál jde o vedlejší stat s příslušnou váhou).
    final profile = specStatProfile;
    double magScaling = 0;
    if (profile.mainStat == "Wisdom") magScaling += _statValueByKey("Wisdom") * 1.0;
    if (profile.secondaryStat == "Wisdom") magScaling += _statValueByKey("Wisdom") * profile.secondaryWeight;
    final int wisTerm = magScaling.toInt();
    final double magAtkEffMod = (1 + heroEffects.fold(0.0, (s, e) => s + e.magAtkMod)).clamp(0.0, 10.0).toDouble();
    return ((baseMagAtk + itemBonusMagAtk + wisTerm + bonus) * modifier * magAtkPotionModifier * relicDamageMult * relicMasteryDamageMult * (gladiatorSetSynergy?1.15:1.0) / ascensionPowerSquish * magAtkEffMod).toInt();
  }

  // +15 % z Lektvaru Moudrosti, pokud je aktivní.
  double get magAtkPotionModifier =>
      heroEffects.any((e) => e.name == "Lektvar Moudrosti") ? 1.15 : 1.0;

  // ===== ARMOR — TEĎ ČISTĚ Z ITEMŮ (stat "Armor" na gearu) + Tank koeficient dle specStatProfile =====
  // Nahrazuje starý dvoukanálový systém (fyzický z Strength/Agility, magický z Wisdom) - Armor je
  // teď jednotný item stat jako Crit/Dodge/Block, ne odvozenina primárních statů. baseArmorFlat
  // je záměrně vyšší startovní hodnota (50), ať postava není najednou křehká, než jí začne padat
  // gear s Armor statem. Tank specializace dostávají násobný koeficient (1.2-1.6× dle tabulky).
  static const double baseArmorFlat = 50;
  static const double armorPerItemPoint = 8; // multiplikátor bodu Armor statu z itemu (srovnatelné měřítko se starým Strength×5/Agility×10)
  int get armor {
    // Stejná oprava jako u basicAttackRoleMod výš - tank koeficient smí platit až po skutečné
    // volbě specializace (specialization != 0), ne z fallbacku na spec 1 pro nezvolený stav.
    final effectiveTankCoefficient = specialization != 0 ? specStatProfile.tankArmorCoefficient : 1.0;
    double base = (baseArmorFlat + _itemStatSum("Armor") * armorPerItemPoint) * effectiveTankCoefficient;
    if (hasGodClass) base *= 1.5;
    if (hasRank100Class) base *= 2.0;
    if (gearSetDefHpBonus > 0) base *= (1 + gearSetDefHpBonus);
    if (eliteSet8pcDefHpBonus > 0) base *= (1 + eliteSet8pcDefHpBonus);
    for (var c in activeCompanions) {
      if (c.role == CompanionRole.tank) base += c.level * 15;
    }
    // Zohlednění debuffů na Armor u hrdiny
    for (var eff in heroEffects) {
      if (eff.name.contains("Snížená Armor")) base *= 0.8;
    }
    // Lektvar Kamenné kůže: +25 % Armor
    if (heroEffects.any((e) => e.name == "Lektvar Kamenné kůže")) base *= 1.25;
    final double armorEffMod = (1 + heroEffects.fold(0.0, (s, e) => s + e.armorMod)).clamp(0.0, 10.0).toDouble();
    return max(0, (base * armorEffMod / ascensionPowerSquish).round());
  }

  // ===== BOJOVÉ STATY: KRITICKÝ ZÁSAH / ÚHYB / BLOK =====
  // Každý bod z itemu (stat "Crit"/"Dodge"/"Block") přidává 0.1 % šance.
  // Crit a Dodge škálují navíc s Agilitou (hbitost = přesnost i úhybnost), Block s Vitalitou (výdrž = odolnost).
  // Každá třída má navíc "signature" stat, který posiluje postupem přes rankové stupně (15/40/75/100) -
  // dává buildu identitu a smysl investovat do konkrétní třídy, ne jen do čistého poškození.
  // ===== RUNOVÝ ČARODĚJ: pomocné gettery =====
  // Kolik slotů na runy má zbraň odemčeno (roste s počtem odemčených běžných run v talentovém stromu).
  int get unlockedRuneSlotCount {
    final regular = unlockedRuneNodeIds.where((id) => RuneTree.byId(id)?.isMaster != true).length;
    if (regular >= 6) return 3;
    if (regular >= 3) return 2;
    return 1;
  }

  int get runeStoneCost => 50; // Magic Dust za 1 Runový kámen.

  // Součet hodnoty daného typu efektu ze všech osazených run (běžných i Master runy).
  // Zbraň, kterou má hráč fyzicky nasazenou (EquipSlot.weapon) - určuje, jestli platí bonusy
  // z weaponRuneSlots/regular gearu, nebo z artifactRuneSlots/WeaponSkillTree (viz runeEffect()).
  Item? get equippedWeapon {
    final matches = equipment.where((i) => i.slot == EquipSlot.weapon);
    return matches.isNotEmpty ? matches.first : null;
  }

  // Runový čaroděj vsazuje runy do BĚŽNÝCH zbraní (weaponRuneSlots) - do artefaktu ne.
  // Runový kovář vsazuje runy (a strom schopností) do ARTEFAKTU (artifactRuneSlots) - do
  // běžné zbraně ne. Platí vždy jen ten pool, co odpovídá PRÁVĚ nasazené zbrani, aby runa
  // nemohla "táhnout" bonus ze dvou různých zbraní zároveň.
  double runeEffect(RuneEffectType type) {
    double total = 0;
    final bool artifactEquipped = equippedWeapon?.isArtifact == true;
    if (!artifactEquipped) {
      for (final id in weaponRuneSlots) {
        if (id == null) continue;
        if (id == 'MASTER') {
          if (masterRune != null) {
            for (int i = 0; i < masterRune!.effects.length; i++) {
              if (masterRune!.effects[i] == type) total += masterRune!.values[i];
            }
          }
          continue;
        }
        final node = RuneTree.byId(id);
        if (node != null && node.effectType == type) total += node.value;
      }
    } else {
      // Strom schopností artefaktové zbraně (Runový kovář) - platí jen dokud je artefakt nasazený.
      // Jen NEUTRÁLNÍ větev sem přispívá klasickým součtem - gemové větve (poison/revival/
      // darkness/bloodbath/fragmentation/reflection) posilují magnitude AKTIVNÍHO gemu místo
      // toho (viz weaponSkillGemBonus/activeGemMagnitude), takže se tady záměrně přeskakují.
      for (final id in unlockedWeaponSkillNodeIds) {
        final node = WeaponSkillTree.byId(id);
        if (node == null || node.branch != WeaponSkillBranch.neutral) continue;
        if (node.isMaster) {
          // Artefaktová Master runa (ws_neutral7) - efekt je variabilní, viz craftArtifactMasterRune().
          if (artifactMasterRune != null) {
            for (int i = 0; i < artifactMasterRune!.effects.length; i++) {
              if (artifactMasterRune!.effects[i] == type) total += artifactMasterRune!.values[i];
            }
          }
          continue;
        }
        if (node.effectType == type) total += node.value;
      }
      // Sloty artefaktové zbraně - stejný princip jako weaponRuneSlots výše, jen vlastní pole.
      for (final id in artifactRuneSlots) {
        if (id == null) continue;
        if (id == 'MASTER') {
          if (masterRune != null) {
            for (int i = 0; i < masterRune!.effects.length; i++) {
              if (masterRune!.effects[i] == type) total += masterRune!.values[i];
            }
          }
          continue;
        }
        final node = RuneTree.byId(id);
        if (node != null && node.effectType == type) total += node.value;
      }
    }
    if(type==RuneEffectType.lifesteal)total+=relicLifesteal*(reaperSetSynergy?1.15:1.0);
    return total;
  }

  // Po zásahu se pokusí vyvolat krvácení/zapálení (runy Uruz/Kenaz) - DoT tikne v _tickEffects().
  void _applyRuneProcs(int dealtDmg) {
    final bleed = runeEffect(RuneEffectType.bleedChance);
    if (bleed > 0 && Random().nextDouble() < bleed) {
      enemyEffects.removeWhere((e) => e.name == "Krvácení (runa)");
      enemyEffects.add(StatusEffect(name: "Krvácení (runa)", description: "Krvácí a ztrácí zdraví každé kolo.", duration: 3, isBuff: false, dotDamage: max(1, (dealtDmg * 0.25).toInt())));
    }
    final burn = runeEffect(RuneEffectType.burnChance);
    if (burn > 0 && Random().nextDouble() < burn) {
      enemyEffects.removeWhere((e) => e.name == "Zapálení (runa)");
      enemyEffects.add(StatusEffect(name: "Zapálení (runa)", description: "Hoří a ztrácí zdraví každé kolo.", duration: 3, isBuff: false, dotDamage: max(1, (dealtDmg * 0.25).toInt())));
    }
  }

  bool canUnlockRuneNode(RuneNode node) {
    if (!runeWizardUnlocked) return false;
    if (unlockedRuneNodeIds.contains(node.id)) return false;
    if (runeTalentPoints <= 0) return false;
    if (node.tier == 1) return true;
    final prevTier = RuneTree.allNodes.firstWhere((n) => n.branch == node.branch && n.tier == node.tier - 1);
    return unlockedRuneNodeIds.contains(prevTier.id);
  }

  // ===== STROM SCHOPNOSTÍ ARTEFAKTOVÉ ZBRANĚ (Runový kovář) =====
  // Vyžaduje vykovanou artefaktovou zbraň pro aktuální (třídu, specializaci) - bez zbraně
  // strom nedává smysl. Lineární odemykání po tierech, stejně jako u RuneTree.
  // Neutrální větev je dostupná hned s vytvořením zbraně. Gemové větve (poison/revival/
  // darkness/bloodbath/fragmentation/reflection) navíc vyžadují Hardcore Mode A odpovídající
  // gem fyzicky vsazený v Prstenu Osudu - bez toho nejde odemknout ani tier 1.
  // Cena za uzel: eskalující Esence Moci (10, 15, 20, 25...), ne body za boss killy.
  int get nextWeaponSkillNodeCost => 10 + 5 * unlockedWeaponSkillNodeIds.length;

  bool canUnlockWeaponSkillNode(WeaponSkillNode node) {
    if (!hasCraftedActiveArtifactWeapon) return false;
    if (unlockedWeaponSkillNodeIds.contains(node.id)) return false;
    if (node.branch != WeaponSkillBranch.neutral) {
      if (!atLeastHardcore) return false;
      final gemName = _gemBranchMap.entries.firstWhere((e) => e.value == node.branch, orElse: () => const MapEntry("", WeaponSkillBranch.neutral)).key;
      if (gemName.isEmpty || gemCountOf(gemName) <= 0) return false;
    }
    if (legendaryEssence < nextWeaponSkillNodeCost) return false;
    if (node.tier == 1) return true;
    final prevTier = WeaponSkillTree.allNodes.firstWhere((n) => n.branch == node.branch && n.tier == node.tier - 1);
    return unlockedWeaponSkillNodeIds.contains(prevTier.id);
  }

  void unlockWeaponSkillNode(WeaponSkillNode node) {
    if (!canUnlockWeaponSkillNode(node)) return;
    legendaryEssence -= nextWeaponSkillNodeCost;
    unlockedWeaponSkillNodeIds.add(node.id);
    message = tr("⚔️ Odemčen uzel zbraně: ${node.name}!", "⚔️ Weapon node unlocked: ${node.name}!");
    notifyListeners();
  }

  void unlockRuneNode(RuneNode node) {
    if (!canUnlockRuneNode(node)) return;
    runeTalentPoints--;
    unlockedRuneNodeIds.add(node.id);
    message = tr("Odemčena runa v talentovém stromu: ${node.name}!", "Rune unlocked in the talent tree: ${node.name}!");
    notifyListeners();
  }

  void buyRuneStone() {
    if (magicDust < runeStoneCost) {
      message = tr("Nedostatek Magic Dust na Runový kámen (potřeba $runeStoneCost).", "Not enough Magic Dust for a Rune Stone (needed: $runeStoneCost).");
      notifyListeners();
      return;
    }
    magicDust -= runeStoneCost;
    runeStones++;
    message = tr("Získán Runový kámen! (Máš $runeStones)", "Rune Stone obtained! (You have $runeStones)");
    notifyListeners();
  }

  void activateRune(RuneNode node) {
    if (!unlockedRuneNodeIds.contains(node.id)) return;
    if (node.isMaster) {
      message = tr("Master runu vytvoříš tlačítkem u Master runy, ne přes běžnou aktivaci.", "You craft a Master rune using its own button, not through regular activation.");
      notifyListeners();
      return;
    }
    if (runeLibrary.contains(node.id)) {
      message = tr("Runa ${node.name} už je aktivována v knihovně.", "The rune ${node.name} is already activated in your library.");
      notifyListeners();
      return;
    }
    if (runeStones < 1) {
      message = tr("Potřebuješ alespoň 1 Runový kámen.", "You need at least 1 Rune Stone.");
      notifyListeners();
      return;
    }
    runeStones -= 1;
    runeLibrary.add(node.id);
    message = tr("Runa ${node.name} aktivována a přidána do knihovny run!", "Rune ${node.name} activated and added to your rune library!");
    notifyListeners();
  }

  void craftMasterRune(RuneBranch branch) {
    final masterNode = RuneTree.masterFor(branch);
    if (!unlockedRuneNodeIds.contains(masterNode.id)) {
      message = tr("Nejdřív odemkni Master runu (${masterNode.name}) v talentovém stromu.", "First unlock the Master rune (${masterNode.name}) in the talent tree.");
      notifyListeners();
      return;
    }
    const cost = 4; // Master runa stojí čtyřnásobek běžné ceny (dle konceptu).
    if (runeStones < cost) {
      message = tr("Master runa vyžaduje $cost Runové kameny.", "The Master rune requires $cost Rune Stones.");
      notifyListeners();
      return;
    }
    runeStones -= cost;
    final pool = RuneTree.branchNodes(branch).where((n) => !n.isMaster).toList()..shuffle();
    final picks = pool.take(2).toList();
    masterRune = MasterRuneData(
      branch: branch,
      effects: picks.map((p) => p.effectType).toList(),
      values: picks.map((p) => p.value * 1.5).toList(), // Master efekty jsou o 50 % silnější.
    );
    message = tr("Master runa ${masterNode.name} vytvořena! Efekty: ${picks.map((p) => p.name).join(', ')}.", "Master rune ${masterNode.name} crafted! Effects: ${picks.map((p) => p.name).join(', ')}.");
    notifyListeners();
  }

  // Reroll Master runy zlevní na Mastery Level 3+ (4 -> 2 kameny) - odměna za další progres
  // ve weekly úkolu nad rámec pouhého odemčení feature na levelu 2.
  int get masterRuneRerollCost => runicMasteryLevel >= 3 ? 2 : 4;

  void rerollMasterRune() {
    if (masterRune == null) return;
    if (runicMasteryLevel < 2) {
      message = tr("Reroll efektů Master runy se odemyká na Runic Mastery Level 2.", "Rerolling Master rune effects unlocks at Runic Mastery Level 2.");
      notifyListeners();
      return;
    }
    final cost = masterRuneRerollCost;
    if (runeStones < cost) {
      message = tr("Reroll Master runy vyžaduje $cost Runové kameny.", "Rerolling the Master rune requires $cost Rune Stones.");
      notifyListeners();
      return;
    }
    runeStones -= cost;
    final pool = RuneTree.branchNodes(masterRune!.branch).where((n) => !n.isMaster).toList()..shuffle();
    final picks = pool.take(2).toList();
    masterRune = MasterRuneData(
      branch: masterRune!.branch,
      effects: picks.map((p) => p.effectType).toList(),
      values: picks.map((p) => p.value * 1.5).toList(),
    );
    message = tr("Master runa přerolována! Nové efekty: ${picks.map((p) => p.name).join(', ')}.", "Master rune rerolled! New effects: ${picks.map((p) => p.name).join(', ')}.");
    notifyListeners();
  }

  // ===== ARTEFAKTOVÁ MASTER RUNA (neutrální větev, tier 7) =====
  // Na rozdíl od čarodějovy craftMasterRune() (2 efekty z JEDNÉ větve) tahle čerpá ze VŠECH
  // běžných run čaroděje napříč všemi 3 větvemi (obranná/útočná/průrazná) - je to "univerzální"
  // shrnutí toho nejsilnějšího, co čaroděj umí, proto patří do neutrální větve artefaktu.
  void craftArtifactMasterRune() {
    if (!unlockedWeaponSkillNodeIds.contains('ws_neutral7')) {
      message = tr("Nejdřív odemkni Artefaktovou Master runu (tier 7 neutrální větve).", "First unlock the Artifact Master rune (tier 7 of the neutral branch).");
      notifyListeners();
      return;
    }
    const cost = 6; // Dražší než čarodějova (4) - efekty čerpá napříč celým stromem run.
    if (runeStones < cost) {
      message = tr("Artefaktová Master runa vyžaduje $cost Runové kameny.", "The Artifact Master rune requires $cost Rune Stones.");
      notifyListeners();
      return;
    }
    runeStones -= cost;
    final pool = RuneTree.allNodes.where((n) => !n.isMaster).toList()..shuffle();
    final picks = pool.take(2).toList();
    artifactMasterRune = MasterRuneData(
      branch: picks.first.branch,
      effects: picks.map((p) => p.effectType).toList(),
      values: picks.map((p) => p.value * 1.5).toList(),
    );
    message = tr("Artefaktová Master runa vykována! Efekty: ${picks.map((p) => p.name).join(', ')}.", "Artifact Master rune forged! Effects: ${picks.map((p) => p.name).join(', ')}.");
    notifyListeners();
  }

  void rerollArtifactMasterRune() {
    if (artifactMasterRune == null) return;
    const cost = 6;
    if (runeStones < cost) {
      message = tr("Reroll Artefaktové Master runy vyžaduje $cost Runové kameny.", "Rerolling the Artifact Master rune requires $cost Rune Stones.");
      notifyListeners();
      return;
    }
    runeStones -= cost;
    final pool = RuneTree.allNodes.where((n) => !n.isMaster).toList()..shuffle();
    final picks = pool.take(2).toList();
    artifactMasterRune = MasterRuneData(
      branch: picks.first.branch,
      effects: picks.map((p) => p.effectType).toList(),
      values: picks.map((p) => p.value * 1.5).toList(),
    );
    message = tr("Artefaktová Master runa přerolována! Nové efekty: ${picks.map((p) => p.name).join(', ')}.", "Artifact Master rune rerolled! New effects: ${picks.map((p) => p.name).join(', ')}.");
    notifyListeners();
  }

  void equipRune(int slot, String runeIdOrMaster) {
    if (slot < 0 || slot >= unlockedRuneSlotCount) return;
    if (runeIdOrMaster != 'MASTER' && !runeLibrary.contains(runeIdOrMaster)) return;
    if (runeIdOrMaster == 'MASTER' && masterRune == null) return;
    // Stejná runa/master nemůže být ve dvou slotech zároveň.
    for (int i = 0; i < weaponRuneSlots.length; i++) {
      if (weaponRuneSlots[i] == runeIdOrMaster) weaponRuneSlots[i] = null;
    }
    weaponRuneSlots[slot] = runeIdOrMaster;
    notifyListeners();
  }

  void unequipRune(int slot) {
    if (slot < 0 || slot >= weaponRuneSlots.length) return;
    weaponRuneSlots[slot] = null;
    notifyListeners();
  }

  // ===== SLOTY ARTEFAKTOVÉ ZBRANĚ =====
  // Na rozdíl od equipRune (vyžaduje runeLibrary - runa musí být "vyrobená" za Runový kámen)
  // sem jde vsadit runa, co je jen ODEMČENÁ (unlockedRuneNodeIds) - žádný Runový kámen netřeba.
  // Vyžaduje vykovanou artefaktovou zbraň pro aktuální (třídu, specializaci).
  void equipArtifactRune(int slot, String runeIdOrMaster) {
    if (!hasCraftedActiveArtifactWeapon) return;
    if (slot < 0 || slot >= artifactRuneSlots.length) return;
    if (runeIdOrMaster != 'MASTER' && !unlockedRuneNodeIds.contains(runeIdOrMaster)) return;
    if (runeIdOrMaster == 'MASTER' && masterRune == null) return;
    for (int i = 0; i < artifactRuneSlots.length; i++) {
      if (artifactRuneSlots[i] == runeIdOrMaster) artifactRuneSlots[i] = null;
    }
    artifactRuneSlots[slot] = runeIdOrMaster;
    notifyListeners();
  }

  void unequipArtifactRune(int slot) {
    if (slot < 0 || slot >= artifactRuneSlots.length) return;
    artifactRuneSlots[slot] = null;
    notifyListeners();
  }

  void claimWeeklyRuneQuest() {
    if (weeklyRuneQuestClaimed || weeklyRuneBossKills < weeklyRuneBossTarget) return;
    weeklyRuneQuestClaimed = true;
    runicMasteryLevel++;
    message = tr("Weekly úkol Runového Čaroděje splněn! Runic Mastery Level: $runicMasteryLevel.", "Rune Wizard weekly task completed! Runic Mastery Level: $runicMasteryLevel.");
    notifyListeners();
  }

  // Voláno při zabití bosse v Lairu na patře 15+ (jen Lair - viz _handleLairBossDeath).
  void _registerLairBoss15PlusKill() {
    if (!runeWizardUnlocked) {
      runeWizardUnlocked = true;
      message = tr("🔮 Odemčen Runový Čaroděj! Navštiv jeho sekci ve světě.", "🔮 Rune Wizard unlocked! Visit their section in the World.");
      _queueContextTip(TutorialTipId.tipRune);
    }
    lairBoss15PlusKills++;
    // Strom run má celkem RuneTree.allNodes.length uzlů (3 větve × 7 tierů = 21), takže
    // celoživotní zisk talentových bodů (už odemčené uzly + aktuálně nevyužité body) je
    // zastropovaný přesně na tenhle počet - stejná hranice jako u _grantBonusRuneTalentPoint().
    if (lairBoss15PlusKills % 5 == 0 && (unlockedRuneNodeIds.length + runeTalentPoints) < RuneTree.allNodes.length) {
      runeTalentPoints++;
    }
    // Strom zbraně (Runový kovář) už neběží na bodech z boss killů - odemyká se za eskalující
    // Esenci Moci (viz nextWeaponSkillNodeCost/canUnlockWeaponSkillNode), plus u gemových větví
    // navíc vyžaduje Hardcore Mode a odpovídající gem v Prstenu.
    if (!weeklyRuneQuestClaimed && weeklyRuneBossKills < weeklyRuneBossTarget) {
      weeklyRuneBossKills++;
      _checkDailyChronicleCoin(3, true);
    }
  }


  double get critChance {
    // BUG FIX 3 (viz konverzace - "itemy dávají staty ve velkém"): totalAgility/totalWisdom
    // sahají do tisíců až desetitisíců u gearnutého hardcore hrdiny (Paragon multiplikátor na
    // item statech nemá strop), takže i po opravě 1/2 (oddělení item statů od talentového
    // sebe-násobení) byl SUROVÝ stat pořád o řády větší, než na jaký byl kalibrovaný převodní
    // koeficient (Agility*0.0015 apod.) - crit/dodge/block se tak sytily téměř okamžitě.
    // Řešení: stat se PŘED převodem na raw% nejdřív sám změkčí přes DR křivku (_diminish s
    // "měkkým stropem" 800) - u nízkých hodnot skoro nezasáhne (crit citelně roste od začátku
    // hry), u vysokých hodnot ale i statisíce Agility/Wisdom asymptoticky míří k témuž stropu
    // místo aby lineárně drtily cap. Váhový poměr Agility:Wisdom (4:3) zachován.
    double raw = 0.05 + (_diminish(totalAgility, 800) * 0.001) + (_diminish(totalWisdom, 800) * 0.00075) + (_itemStatSum("Crit") * 0.001);
    if (hasGodClass) raw += 0.05;
    if (hasRank100Class) raw += 0.05;
    // Léčitel: Posvátný úsudek - crit je JEHO hlavní signature stat (DK Mráz je specializovaný
    // crit build, ne obecná identita třídy - Healer musí být silnější v základu i bez speců).
    // Bonus na všech 4 tierech (na rozdíl od dřívějších jen 2), škáluje o 25 % silněji.
    if (heroClass == HeroClass.healer) {
      double healerTierBonus = 0;
      if (hasAdvancedClass) healerTierBonus += 0.05;
      if (hasUltimateClass) healerTierBonus += 0.05;
      if (hasGodClass) healerTierBonus += 0.05;
      if (hasRank100Class) healerTierBonus += 0.05;
      raw += healerTierBonus * 1.25;
    }
    // Deathknight: Smrtící přesnost - solidní hybridní bonus, ne hlavní crit identita (ta je Healerova).
    // Pozn.: dřív tu byly navíc `hasGodClass`/`hasRank100Class` podmínky, co duplikovaly stejné
    // bonusy už započítané výš v obecné vrstvě (řádky nad tímto blokem) - odstraněno, DK teď
    // dává 0,10 (obecné) + 0,10 (isDarkKnight+isPlagueLord) = 0,20 raw v základu.
    if (heroClass == HeroClass.deathknight) {
      if (hasAdvancedClass) raw += 0.05;  // isDarkKnight
      if (hasUltimateClass) raw += 0.05;  // isPlagueLord
    }
    raw += runeEffect(RuneEffectType.critChance)+relicCritBonus+relicMasteryCritBonus;
    raw += specCritBonus; // Hunter Stopař / DK Mráz
    raw += heroEffects.fold(0.0, (s, e) => s + e.critMod); // nepřátelské schopnosti (viz enemyAbilityEffects)
    for (var c in activeCompanions) {
      if (c.role == CompanionRole.rogue) raw += c.level * 0.003; // Laufer
    }
    const cap = 0.60; // max 60 %
    return _diminish(raw, cap).clamp(0.0, cap);
  }

  double get critDamageMultiplier => 1.5 + runeEffect(RuneEffectType.critDamage) + specializationCritDamageBonus; // kritický zásah = +50 % poškození (+ runy)

  double get dodgeChance {
    // Lovec: Hbitost lovce - úhyb je jeho signature stat. Jeho vlastní dodge zdroje (Agility + tier
    // bonusy) škálují o 10 % silněji než u ostatních tříd.
    final bool isHunter = heroClass == HeroClass.hunter;
    final double hunterScale = isHunter ? 1.10 : 1.0;
    // BUG FIX 3 (viz konverzace, stejná oprava jako u critChance) - Agility se před převodem na
    // raw% nejdřív změkčí přes DR (měkký strop 800), ať i statisíce Agility z gearu/Paragonu
    // asymptoticky míří k rozumnému stropu, ne aby okamžitě saturovaly dodge cap.
    double raw = 0.03 + (_diminish(totalAgility, 800) * 0.0013 * hunterScale) + (_itemStatSum("Dodge") * 0.001);
    if (isHunter) {
      double tierBonus = 0;
      if (hasAdvancedClass) tierBonus += 0.04;
      if (hasUltimateClass) tierBonus += 0.04;
      if (hasGodClass) tierBonus += 0.04;
      if (hasRank100Class) tierBonus += 0.04;
      raw += tierBonus * hunterScale;
    }
    raw += runeEffect(RuneEffectType.dodgeChance);
    raw += specDodgeBonus; // Hunter Divočina/Stín
    if (heroEffects.any((e) => e.name == "Elegantní výpad")) raw += 0.10; // Duelist signature útok
    if (heroEffects.any((e) => e.name == "Divoký Hon")) raw += 0.20; // Hardcore set "Divoký Hon" 6pc
    if (heroEffects.any((e) => e.name == "Elegantní Tanec")) raw += 0.10; // Hardcore set "Elegantní Tanec" 2pc/6pc
    raw += monkRockDodgeBonus; // Mnich Skála (Tank): +2,5 % flat dodge
    raw += heroEffects.fold(0.0, (s, e) => s + e.dodgeMod); // nepřátelské schopnosti (viz enemyAbilityEffects)
    const cap = 0.40; // max 40 %
    // Vyčerpávací debuff (Aréna, od 11. kola): -1 %/kolo Dodge - viz arenaStallRounds.
    final double stallPenalty = arenaStallRounds > 0 ? 0.01 * arenaStallRounds : 0.0;
    return (_diminish(raw, cap).clamp(0.0, cap) - stallPenalty).clamp(0.0, cap) * curseDarknessMod * gemSustainBonus; // Temnota (curse) vs. Gem Temnoty (opačný efekt)
  }

  double get blockChance {
    // Blok teď škáluje ze Strength místo Vitality ("Síla protěžuje fyzický dmg a blok").
    // BUG FIX 3 (viz konverzace, stejná oprava jako u critChance/dodgeChance) - Strength se před
    // převodem na raw% nejdřív změkčí přes DR (měkký strop 800).
    double raw = 0.05 + (_diminish(totalStrength, 800) * 0.0013) + (_itemStatSum("Block") * 0.001);
    // Válečník: Nezlomná hradba - blok je jeho signature stat
    if (heroClass == HeroClass.warrior) {
      if (hasAdvancedClass) raw += 0.04;
      if (hasUltimateClass) raw += 0.04;
      if (hasGodClass) raw += 0.04;
      if (hasRank100Class) raw += 0.04;
    }
    raw += runeEffect(RuneEffectType.blockChance);
    raw += specBlockBonus; // Warrior Ochránce
    raw += heroEffects.fold(0.0, (s, e) => s + e.blockMod); // nepřátelské schopnosti (viz enemyAbilityEffects)
    for (var c in activeCompanions) {
      if (c.role == CompanionRole.guardian) raw += c.level * 0.002; // Fenwick
    }
    // Válečník: dynamický strop – základ 40 %, extra až +10 % dle chybějícího HP
    // (čím méně HP, tím vyšší cap; max 50 % při 0 HP)
    double cap = 0.40;
    if (heroClass == HeroClass.warrior && maxHp > 0) {
      final missingHpRatio = (1.0 - hp / maxHp).clamp(0.0, 1.0);
      cap += 0.10 * missingHpRatio;
    }
    // Vyčerpávací debuff (Aréna, od 11. kola): -1 %/kolo Block - viz arenaStallRounds.
    final double stallPenalty = arenaStallRounds > 0 ? 0.01 * arenaStallRounds : 0.0;
    final result = (_diminish(raw, cap).clamp(0.0, cap) - stallPenalty).clamp(0.0, cap) * curseDarknessMod * gemSustainBonus;
    return isInLair ? max(0.0, result - lairBlockPenalty) : result; // Temnota (curse) vs. Gem Temnoty (opačný efekt)
  }

  // ===== TOWER MODIFIKÁTOR - NEPŘÍTEL =====
  // towerModCritStacks/DodgeStacks/BlockStacks/AbsorbStacks dřív posilovaly HRDINU (viz výš).
  // Teď je dostává NEPŘÍTEL ve Věži (viz fight()/_resolveCombatRound()/_generateNextEnemy) -
  // Tower modifikátor tak dělá nepřátele odolnější/nebezpečnější místo hráče silnějším.
  // Stejná +1 %/stack škála jako dřív u hráče, jen s vlastním (o něco vyšším) stropem, protože
  // stacky rostou neomezeně s postupem patry a jde čistě o obtížnost, ne o hráčovu buildovou volbu.
  double get enemyCritChance => (towerModCritStacks * 0.01).clamp(0.0, 0.75);
  double get enemyDodgeChance => (towerModDodgeStacks * 0.01).clamp(0.0, 0.75);
  double get enemyBlockChance => (towerModBlockStacks * 0.01).clamp(0.0, 0.75);
  static const double enemyBlockReduction = 0.5; // stejná redukce jako hráčův blok
  static const double enemyCritDamageMultiplier = 1.5; // stejný násobič jako hráčův crit

  double get blockReduction => 0.5 * curseDarknessMod * gemSustainBonus; // úspěšný blok sníží poškození o 50 % (Temnota vs. Gem Temnoty)

  bool get isBoss => enemiesDefeatedOnFloor >= 4;

  GameState() {
    WidgetsBinding.instance.addObserver(this);
    _generateNextEnemy();
    _checkQuestResets(); // hned při startu hry - vyřeší i případ "hráč nehrál přes půlnoc/týden"
    _ensureMarketOffers(); // hned při startu hry - i pro čerstvě založenou postavu
    Timer.periodic(const Duration(milliseconds: 100), (_) {
      // Auto-boj dřív tikal napevno každých 500ms. Teď je interval proměnný (1.5s základ,
      // kupovatelné -0.1s/10g až na strop 0.5s - viz autoCombatIntervalMs/upgradeAutoCombatSpeed),
      // takže tickujeme jemněji (100ms) a spouštíme skutečnou akci až po nasbírání dost času.
      // Pokud právě dohrává SpellFxOverlay animace (viz isSpellSlowMo/_pushFx výš), auto-boj se
      // úplně zastaví - "slow motion" pocit, ať hráč tu animaci stihne doopravdy vidět.
      if (isSpellSlowMo) return;
      _autoCombatElapsedMs += 100;
      if (_autoCombatElapsedMs < autoCombatIntervalMs) return;
      _autoCombatElapsedMs = 0;
      // Věžin auto-boj se nesmí spouštět na pozadí, dokud je hráč aktivně v jiném combat módu
      // (Lair/World Boss/Rift/Aréna) - dřív chybělo World Boss/Rift/Aréna, takže se Věž tiše
      // "bojovala sama" na pozadí i tam a přepisovala message/postup, aniž by o tom hráč věděl.
      final bool inOtherCombat = isInLair || isInWorldBoss || isInRift || (arenaOpponentClass != null && arenaOpponentHp > 0);
      // Auto-boj se na ~2s pozastaví, dokud běží velký celebration popup (level up / achievement /
      // atd.) - viz celebrationTitle/_triggerCelebration a CelebrationOverlayHost, který ho po
      // 2200ms sám schová. Ať hráč tu animaci stihne vidět, ne že mu ji auto-boj hned přebije.
      if (autoCombatEnabled && heroClass != HeroClass.none && !inOtherCombat && !isDead && celebrationTitle == null) {
        if (isMerchantEncounter) {
          // Potulný obchodník: podle nastavení buď auto-boj pozastavíme (fight() se nezavolá,
          // hráč dostane šanci obchodovat), nebo - pokud si hráč přeje neustávat - obchodníka
          // rovnou automaticky opustíme, ať auto-boj plynule pokračuje dál na dalšího nepřítele.
          if (!pauseAutoBattleOnMerchant) leaveMerchant();
        } else {
          fight(classIsMagicAttack);
        }
      }
      final autoBuyPrice = getPotionPrice(20);
      if (autoBuyPotionsEnabled && gold >= autoBuyPrice) {
        final potion = consumables.where((i) => i.name == "Léčivý lektvar").fold(0, (sum, i) => sum + i.stackCount);
        if (potion < 5) {
          buyItem("Léčivý lektvar", {"HP": 0}, autoBuyPrice, isConsumable: true);
        }
      }
    });
    // Pozn.: Cooldowny schopností se odečítají po kolech, ne reálným časem - viz _tickEffects(),
    // volaná z _resolveCombatRound()/_resolveLairCombatRound() po každé akci hráče.
    // Kontrola dne/týdne pro reset denních/týdenních questů - stačí jednou za minutu,
    // aby se reset projevil i když appka zůstane otevřená přes půlnoc/pondělí.
    Timer.periodic(const Duration(minutes: 1), (_) {
      _checkQuestResets();
      _ensureMarketOffers();
      // Autosave - hlavně kvůli čerstvému lastActiveTimestamp pro offline progress (viz
      // _computeOfflineProgress), i kdyby appku zabili bez čistého vypnutí.
      if (heroClass != HeroClass.none) saveGame();
    });
  }

  bool _isNewCalendarDay(DateTime now, DateTime last) => now.year != last.year || now.month != last.month || now.day != last.day;

  // Vrátí datum nejbližšího minulého pondělí (00:00) - používá se jako hranice pro týdenní reset.
  DateTime _mostRecentMonday(DateTime now) {
    final daysSinceMonday = (now.weekday - DateTime.monday) % 7; // weekday: po=1 ... ne=7
    return DateTime(now.year, now.month, now.day).subtract(Duration(days: daysSinceMonday));
  }

  DateTime get nextDailyReset {
    final now = DateTime.now();
    return DateTime(now.year, now.month, now.day).add(const Duration(days: 1));
  }

  DateTime get nextWeeklyReset => _mostRecentMonday(DateTime.now()).add(const Duration(days: 7));

  // Vrátí 1. den příštího kalendářního měsíce (00:00) - hranice pro měsíční reset.
  DateTime get nextMonthlyReset {
    final now = DateTime.now();
    return now.month == 12 ? DateTime(now.year + 1, 1, 1) : DateTime(now.year, now.month + 1, 1);
  }

