  // ===== PROMO KÓDY — katalog =====
  // Přidávej sem nové kódy. validUntil: null = bez expirace. Musí jít s novou verzí appky
  // (offline hra, žádný server) - viz poznámka u PromoCodeDef.
  // Pozn.: "jen jednou" = jednou na hráče (redeemedPromoCodes), ne globálně napříč všemi hráči -
  // globální jednorázovost by šla vynutit jen přes skutečný backend, který tahle hra nemá.
  static final List<PromoCodeDef> promoCodeCatalog = [
    PromoCodeDef(code: "GOLD1000", description: tr("Odměna 1000 zlata", "Reward: 1000 gold"), rewardGold: 1000, requiredLevel: 5, floatingExpiry: const Duration(days: 10)),
    PromoCodeDef(code: "SPARK", description: tr("Odměna 1000 Jisker (na Kosmetiku)", "Reward: 1000 Sparks (for Cosmetics)"), rewardCosmeticSparks: 1000),
    // MASTER: kalibrováno přesně na Paragon 30 pro aktuální třídu. Cena ranku je flat 50 💎
    // (viz upgradeClass/rankGainMultiplierFor, main třída má multiplier 1.0) a classRanks
    // startuje na 1 (paragonLevel = classMultiplier ~/ 100), takže na Paragon 30 (classMultiplier
    // 3000+) je potřeba 2999 ranků × 50 💎 = 149 950 💎. 150 000 dává přesně 3000 ranků =
    // classMultiplier 3001 = Paragon 30 bez zbytku.
    PromoCodeDef(code: "MASTER", description: tr("Odměna: dost krystalů na Paragon 30 (150 000 💎) a 1 000 000 Magic Dustu", "Reward: enough crystals for Paragon 30 (150,000 💎) and 1,000,000 Magic Dust"), rewardCrystals: 150000, rewardDust: 1000000),
    // ESSENCE: kalibrováno přesně na cenu první artefaktové zbraně u Runového Kováře (viz
    // craftArtifactWeapon/artifactWeaponDustCost/artifactWeaponEssenceCost/artifactWeaponMaterialsCost).
    // requiredLevel 15 = stejný práh, na kterém se Runový Kovář vůbec odemyká.
    PromoCodeDef(
      code: "ESSENCE",
      description: tr(
        "Odměna: přesně na vykování artefaktové zbraně (${GameState.artifactWeaponDustCost} ✨ Dust, ${GameState.artifactWeaponEssenceCost} 🔥 Esence, ${GameState.artifactWeaponMaterialsCost} ⚒️ Surovin)",
        "Reward: exactly enough to forge the artifact weapon (${GameState.artifactWeaponDustCost} ✨ Dust, ${GameState.artifactWeaponEssenceCost} 🔥 Essence, ${GameState.artifactWeaponMaterialsCost} ⚒️ Materials)",
      ),
      rewardDust: GameState.artifactWeaponDustCost,
      rewardLegendaryEssence: GameState.artifactWeaponEssenceCost,
      rewardMaterials: GameState.artifactWeaponMaterialsCost,
      requiredLevel: 15,
    ),
    // ARENA: kalibrováno přesně na vymaxování Specializačního Relicu (level 0 -> 100, viz
    // specRelicUpgradeCost/maxSpecRelicLevel/levelCurrentSpecRelic). Cena roste postupně
    // (100/150/225/300/425 za první 4 levely, pak 425 + n×150 + n(n-1)/2×25 pro n = level-5) -
    // součet za všech 100 levelů vychází přesně na 4 297 575 🏅, zaokrouhleno nahoru na
    // 4 300 000 🏅 (stejná drobná rezerva jako u MASTER kódu). requiredLevel 20 = stejný práh,
    // na kterém se Aréna vůbec odemyká.
    PromoCodeDef(
      code: "ARENA",
      description: tr(
        "Odměna: přesně na vymaxování Specializačního Relicu na level ${GameState.maxSpecRelicLevel} (4 300 000 🏅 Mincí dobyvatele)",
        "Reward: exactly enough to max out the Specialization Relic to level ${GameState.maxSpecRelicLevel} (4,300,000 🏅 Conqueror Coins)",
      ),
      rewardConquerorCoins: 4300000,
      requiredLevel: GameState.arenaUnlockLevel,
    ),
  ];

  String redeemPromoCode(String input) {
    final code = input.trim().toUpperCase();
    if (code.isEmpty) {
      message = tr("Zadej promo kód.", "Enter a promo code.");
      notifyListeners();
      return message;
    }
    if (redeemedPromoCodes.contains(code)) {
      message = tr("Tento kód už jsi uplatnil.", "You have already redeemed this code.");
      notifyListeners();
      return message;
    }
    final matches = promoCodeCatalog.where((p) => p.code.toUpperCase() == code);
    if (matches.isEmpty) {
      message = tr("Neplatný promo kód.", "Invalid promo code.");
      notifyListeners();
      return message;
    }
    final def = matches.first;
    if (def.requiredLevel > 0 && level < def.requiredLevel) {
      message = tr("Kód „${def.code}“ jde uplatnit až od levelu ${def.requiredLevel} (aktuálně: level $level).", "Code \u201e${def.code}\u201c can only be redeemed from level ${def.requiredLevel} (currently: level $level).");
      notifyListeners();
      return message;
    }
    // Plovoucí expirace: platnost běží od okamžiku, kdy hráč SPLNIL requiredLevel, ne od pevného
    // data. Pokud hráč měl požadovaný level už předtím, než tahle mechanika existovala (starý
    // save), bereme "teď" jako okamžik splnění - je to čestnější než ho nechat navěky vyloučeného.
    if (def.floatingExpiry != null && def.requiredLevel > 0) {
      final unlockedAt = levelMilestoneReachedAt.putIfAbsent(def.requiredLevel, () => DateTime.now());
      final deadline = unlockedAt.add(def.floatingExpiry!);
      if (DateTime.now().isAfter(deadline)) {
        message = tr("Platnost kódu „${def.code}“ vypršela (běžela ${def.floatingExpiry!.inDays} dní od dosažení levelu ${def.requiredLevel}).", "Code \u201e${def.code}\u201c has expired (it was valid for ${def.floatingExpiry!.inDays} days after reaching level ${def.requiredLevel}).");
        notifyListeners();
        return message;
      }
    } else if (def.validUntil != null && DateTime.now().isAfter(def.validUntil!)) {
      message = tr("Platnost kódu „${def.code}“ vypršela.", "Code \u201e${def.code}\u201c has expired.");
      notifyListeners();
      return message;
    }
    redeemedPromoCodes.add(def.code);
    gold += def.rewardGold;
    crystals += def.rewardCrystals;
    magicDust += def.rewardDust;
    legendaryEssence += def.rewardLegendaryEssence;
    materials += def.rewardMaterials;
    conquerorCoins += def.rewardConquerorCoins;
    cosmeticSparks += def.rewardCosmeticSparks;
    message = tr("🎁 Kód uplatněn: ${def.description}! +${def.rewardGold} 🪙 +${def.rewardCrystals} 💎 +${def.rewardDust} Dust"
        "${def.rewardLegendaryEssence > 0 ? ' +${def.rewardLegendaryEssence} 🔥 Esence' : ''}"
        "${def.rewardConquerorCoins > 0 ? ' +${def.rewardConquerorCoins} 🏅 Mincí dobyvatele' : ''}"
        "${def.rewardCosmeticSparks > 0 ? ' +${def.rewardCosmeticSparks} ✦ Jisker' : ''}",
        "🎁 Code redeemed: ${def.description}! +${def.rewardGold} 🪙 +${def.rewardCrystals} 💎 +${def.rewardDust} Dust"
        "${def.rewardLegendaryEssence > 0 ? ' +${def.rewardLegendaryEssence} 🔥 Essence' : ''}"
        "${def.rewardConquerorCoins > 0 ? ' +${def.rewardConquerorCoins} 🏅 Conqueror Coins' : ''}"
        "${def.rewardCosmeticSparks > 0 ? ' +${def.rewardCosmeticSparks} ✦ Sparks' : ''}");
    _checkAchievements();
    notifyListeners();
    return message;
  }

  // Bonusový TALENTOVÝ BOD (ne rovnou runa!) mimo běžnou ekonomiku boss-killů - používá se pro
  // achievement odměny a vzácné dropy z Hardcore/vyšší obtížnosti Lairu (viz volání níže). Runy
  // se odemykají VÝHRADNĚ za runeTalentPoints skrz unlockRuneNode() - žádný zdroj v celé hře
  // nesmí přiřadit konkrétní runu napřímo, jinak by strop (unlocked+points ≤ 21, přesně na počet
  // uzlů ve stromu) přestal sedět s tím, kolik bodů hráč skutečně nasbíral.
  void _grantBonusRuneTalentPoint() {
    if (unlockedRuneNodeIds.length + runeTalentPoints >= RuneTree.allNodes.length) return; // strop už na maximu
    runeTalentPoints++;
    message += tr(" 🔮 Bonusový talentový bod pro Runového čaroděje!", " 🔮 Bonus talent point for the Rune Wizard!");
  }

  void _unlockAchievement(AchievementId id) {
    if (unlockedAchievements.contains(id)) return;
    unlockedAchievements.add(id);
    final def = achievementDefs[id]!;
    gold += def.rewardGold;
    magicDust += def.rewardDust;
    if (def.rewardButtonColor != null) unlockedButtonColorNames.add(def.rewardButtonColor!);
    if (def.rewardAuraId != null) unlockedAuras.add(def.rewardAuraId!);
    if (def.rewardFrameId != null) unlockedFrames.add(def.rewardFrameId!);
    if (def.rewardCardBackgroundId != null) unlockedCardBackgrounds.add(def.rewardCardBackgroundId!);
    if (def.rewardAttackSkinId != null) unlockedAttackSkins.add(def.rewardAttackSkinId!);
    activeTitle ??= id; // první odemčený achievement se rovnou nastaví jako aktivní titul
    message = tr("🏆 Achievement odemčen: ${def.name}! Titul „${def.title}“ k dispozici.", "🏆 Achievement unlocked: ${def.name}! Title \u201e${def.title}\u201c now available.");
    _triggerCelebration('ACHIEVEMENT!', subtitle: def.name, icon: Icons.emoji_events, color: const Color(0xFFFFD700));
    // Vybrané "milníkové" achievementy navíc odemknou bonusovou runu (appendne se do message výše).
    const runeRewardAchievements = {
      AchievementId.floor50,
      AchievementId.towerConqueror,
      AchievementId.lairFloor70,
      AchievementId.lairFloor85,
      AchievementId.lairFloorFinal,
      AchievementId.hardcoreAwakened,
      AchievementId.riftPusher50,
      AchievementId.riftPusher100,
      AchievementId.paragon500,
      AchievementId.paragon1000,
    };
    if (runeRewardAchievements.contains(id)) _grantBonusRuneTalentPoint();
    notifyListeners();
  }

  void setActiveTitle(AchievementId? id) {
    if (id != null && !unlockedAchievements.contains(id)) return;
    activeTitle = id;
    notifyListeners();
  }

  // Volá se po klíčových událostech (kill, level up, floor advance, Lair kill, spec zvolena...) -
  // levné kontroly, bezpečné volat často.
  // Katalyzátor "alt" postupu - viz komentář u paragonCentMilestones výše. +50 % rank/Paragon
  // rychlosti za KAŽDÝCH 100 Paragon dosažených na nejvyšší třídě účtu (ne nasčítáno napříč
  // třídami), uplatní se na třídy aktuálně POZADU za nejvyšší třídou (aby to nebylo "zdarma" i pro hlavní postavu).
  double get altCatchUpBonus => 1.0 + 0.5 * paragonCentMilestones.length;

  int get _highestClassRank {
    if (classRanks.isEmpty) return 0;
    return classRanks.values.reduce((a, b) => a > b ? a : b);
  }

  // Která třída aktuálně drží nejvyšší rank na účtu - používá se jen pro zobrazení v Alt Catch-up
  // panelu, aby bylo hned vidět, PROTI ČEMU se aktuální třída porovnává (viz isPlayingAlt).
  HeroClass get highestRankClass {
    HeroClass best = HeroClass.warrior;
    int bestRank = -1;
    for (final entry in classRanks.entries) {
      if (entry.value > bestRank) {
        bestRank = entry.value;
        best = entry.key;
      }
    }
    return best;
  }

  bool get isPlayingAlt => (classRanks[heroClass] ?? 0) < _highestClassRank;

  // Pro upgradeClass()/upgradeClassMax(), kde se dá vylepšovat i třída, co zrovna nehraješ.
  double rankGainMultiplierFor(HeroClass cls) => (classRanks[cls] ?? 0) < _highestClassRank ? altCatchUpBonus : 1.0;

  // Zkontroluje, jestli daná třída právě překročila novou "paragon setninu" (Paragon 100/200/300...).
  // Volá se po každém navýšení ranku - viz upgradeClass()/upgradeClassMax()/selectClass().
  void _checkParagonMilestones(HeroClass cls) {
    // BUG FIX: currentParagon (= rank~/100) UŽ JE v jednotkách Paragon levelu (rank 3001 -> Paragon 30).
    // Smyčka dřív porovnávala "m <= currentParagon * 100" - tím se currentParagon vrátil zpátky do
    // rank-škály, takže se milník přidal při KAŽDÉM jednotlivém nárůstu Paragon o 1 (ne jen každých
    // 100), a paragonCentMilestones.length (= zdroj altCatchUpBonus) tak rostl ~100x rychleji, než
    // měl - navíc s chybným popiskem ("Paragon 3000 dosažen!" i když skutečný Paragon byl jen 30).
    final currentParagon = (classRanks[cls] ?? 0) ~/ 100;
    for (int m = 100; m <= currentParagon; m += 100) {
      if (paragonCentMilestones.add(m)) {
        message = tr("🏆 Paragon $m dosažen! Ostatní třídy na tomto účtu teď získávají rank/Paragon o +50 % rychleji (celkem: +${((altCatchUpBonus - 1) * 100).round().toString()} %).", "🏆 Paragon $m reached! Other classes on this account now gain rank/Paragon 50% faster (total: +${((altCatchUpBonus - 1) * 100).round().toString()}%).");
        _triggerCelebration('PARAGON $m!', subtitle: 'Ostatní třídy teď rostou rychleji', icon: Icons.military_tech, color: Colors.purpleAccent);
      }
    }
    // Odemčení nové vrstvy schopností (15/40/75/100 raw rank) - oslavíme jen pro AKTUÁLNĚ
    // hranou třídu, protože jen ta reálně ovlivní hráčův combat build právě teď.
    if (cls == heroClass) {
      final rank = classRanks[cls] ?? 0;
      const tiers = {15: 'Pokročilá schopnost odemčena!', 40: 'Ultimátní schopnost odemčena!', 75: 'Boží schopnost odemčena!', 100: 'Rank 100 - volba cesty odemčena!'};
      for (final t in tiers.keys) {
        if (rank >= t && classAbilityMilestonesReached.add('${cls.name}_$t')) {
          _triggerCelebration(tiers[t]!, subtitle: heroClassLabel(cls), icon: Icons.flare, color: const Color(0xFFFF8000));
        }
      }
    }
  }

  void _checkAchievements() {
    if (floor >= 20) _unlockAchievement(AchievementId.floor20);
    if (floor >= 50) _unlockAchievement(AchievementId.floor50);
    if (floor >= 100) _unlockAchievement(AchievementId.towerConqueror);
    if (defeatedLairFloors.contains(35)) _unlockAchievement(AchievementId.lairFloor35);
    if (defeatedLairFloors.contains(70)) _unlockAchievement(AchievementId.lairFloor70);
    if (defeatedLairFloors.contains(85)) _unlockAchievement(AchievementId.lairFloor85);
    if (defeatedLairFloors.contains(100)) _unlockAchievement(AchievementId.lairFloorFinal);
    if (paragonLevel >= 100) _unlockAchievement(AchievementId.paragon100);
    if (paragonLevel >= 500) _unlockAchievement(AchievementId.paragon500);
    if (paragonLevel >= 1000) _unlockAchievement(AchievementId.paragon1000);
    if (specialization != 0) _unlockAchievement(AchievementId.firstSpecialization);
    if (everRecruitedCompanions.length >= companions.length) _unlockAchievement(AchievementId.fullSquad);
    if (inventory.any((i) => i.rarity == Rarity.legendary)) _unlockAchievement(AchievementId.firstLegendary);
    if (inventory.any((i) => i.setId != null)) _unlockAchievement(AchievementId.firstSet);
    if (hardcoreUnlocked) _unlockAchievement(AchievementId.hardcoreAwakened);
    if (activeCurse != CurseOfFate.none) {
      _unlockAchievement(AchievementId.curseChosen);
      triedCurses.add(activeCurse);
      if (triedCurses.length >= 6) _unlockAchievement(AchievementId.allCursesTried);
    }
    if (inventory.any((i) => i.isArtifact && i.gemSlots.any((g) => g != null))) _unlockAchievement(AchievementId.gemSocketed);
    if (riftTier >= 10) _unlockAchievement(AchievementId.riftPusher10);
    if (riftTier >= 40) _unlockAchievement(AchievementId.riftSeasonBastion);
    if (riftTier >= 60) _unlockAchievement(AchievementId.riftSeasonPlague);
    if (riftTier >= 80) _unlockAchievement(AchievementId.riftSeasonPrecision);
    if (riftTier >= 100) _unlockAchievement(AchievementId.riftSeasonChaos);
    if (riftTier >= 50) _unlockAchievement(AchievementId.riftPusher50);
    if (riftTier >= 100) _unlockAchievement(AchievementId.riftPusher100);
    // ===== ROZŠÍŘENÍ =====
    if (heroClass == HeroClass.mage && floor >= 5) _unlockAchievement(AchievementId.magePioneer);
    if (heroClass == HeroClass.duelist && floor >= 5) _unlockAchievement(AchievementId.duelistPioneer);
    if (totalDeaths >= 20) _unlockAchievement(AchievementId.survivor20);
    if (totalDeaths >= 100) _unlockAchievement(AchievementId.survivor100);
    if (redeemedPromoCodes.isNotEmpty) _unlockAchievement(AchievementId.promoRedeemer);
    if (blacksmithRank >= 50) _unlockAchievement(AchievementId.masterSmith);
    if (alchemistRank >= 50) _unlockAchievement(AchievementId.masterAlchemist);
    if (inventory.any((i) => i.upgradeLevel >= Item.maxUpgradeLevel)) _unlockAchievement(AchievementId.fullyUpgradedItem);
    if (equippedSetCounts.values.any((count) => count >= 4)) _unlockAchievement(AchievementId.setEquipped);
    if (totalQuestsCompleted >= 20) _unlockAchievement(AchievementId.questVeteran);
    if (everCompletedMonthlyQuest) _unlockAchievement(AchievementId.monthlyChampion);
    if (everWatchedRiftAd) _unlockAchievement(AchievementId.adSupporter);
    if (companions.any((c) => c.level >= 10)) _unlockAchievement(AchievementId.companionVeteran);
    if (atLeastPredpekli) _unlockAchievement(AchievementId.predpekliOpened);
    if (pekloMode) _unlockAchievement(AchievementId.pekloOpened);
    // (odstraněno: gatekeeperDefeated check - viz enum výš)
    // ===== ASCENSION / ENDLESS SCALE / ARTEFAKT FORGE / ELITNÍ SETY 8pc =====
    if (ascensionLevel >= 1) _unlockAchievement(AchievementId.ascensionHardcore);
    if (ascensionLevel >= 2) _unlockAchievement(AchievementId.ascensionPredpekli);
    if (ascensionLevel >= 3) _unlockAchievement(AchievementId.ascensionPeklo);
    if (ascensionLevel >= 4) _unlockAchievement(AchievementId.ascensionComplete);
    if (soulDemonKillCount >= 1) _unlockAchievement(AchievementId.soulDemonFirstBlood);
    if (soulDemonKillCount >= 50) _unlockAchievement(AchievementId.soulDemonSlayer);
    if (equipment.any((i) => i.isArtifact && i.slot == EquipSlot.weapon && i.artifactWeaponForgeLevel >= 1)) _unlockAchievement(AchievementId.artifactForged);
    if (equippedSetCounts.values.any((c) => c >= 8)) _unlockAchievement(AchievementId.setFull8pcClassic);
    if (equippedHardcoreSetCounts.values.any((c) => c >= 8)) _unlockAchievement(AchievementId.hardcoreSetFull8pc);
    if (equippedPredpekliSetCounts.values.any((c) => c >= 8)) _unlockAchievement(AchievementId.predpekliSetFull8pc);
    if (equippedPekloSetCounts.values.any((c) => c >= 8)) _unlockAchievement(AchievementId.pekloSetFull8pc);
    // ===== ROZŠÍŘENÍ 2 =====
    if (battlePassLevel >= battlePassMaxLevel) _unlockAchievement(AchievementId.battlePassGraduate);
    if (battlePassPremium) _unlockAchievement(AchievementId.battlePassPatron);
    if (worldBossKills >= 10) _unlockAchievement(AchievementId.worldBossHunter);
    if (worldBossKills >= 50) _unlockAchievement(AchievementId.worldBossNemesis);
    if (gold >= 1000000) _unlockAchievement(AchievementId.goldMillionaire);
    if (crystals >= 5000) _unlockAchievement(AchievementId.crystalBaron);
    if (magicDust >= 1000000) _unlockAchievement(AchievementId.dustTycoon);
    if (totalQuestsCompleted >= 100) _unlockAchievement(AchievementId.questLegend);
    if (companions.any((c) => c.level >= 25)) _unlockAchievement(AchievementId.companionElite);
    if (bankUnlockedSlots >= bankMaxSize) _unlockAchievement(AchievementId.bankVault);
    if (currentSpecRelicLevel >= 1) _unlockAchievement(AchievementId.relicAwakened);
    if (currentSpecRelicLevel >= 90) _unlockAchievement(AchievementId.relicAscended);
    if (riftTier >= 200) _unlockAchievement(AchievementId.riftPusher200);
    if (defeatedLairFloors.contains(50)) _unlockAchievement(AchievementId.lairFloor50Elite);
    if (gearScore >= 3000) _unlockAchievement(AchievementId.gearScoreElite);
    if (gearScore >= 6000) _unlockAchievement(AchievementId.gearScoreLegend);
    if (totalDeaths >= 250) _unlockAchievement(AchievementId.survivor250);
    if (heroClass == HeroClass.necromancer && floor >= 5) _unlockAchievement(AchievementId.necromancerPioneer);
    final ownedCosmetics = (unlockedFrames.length - 1) + (unlockedAttackSkins.length - 1) + (unlockedAuras.length - 1) + (unlockedButtonSkins.length - 1) + (unlockedCardBackgrounds.length - 1);
    if (ownedCosmetics >= 5) _unlockAchievement(AchievementId.cosmeticCollector);
    if (ownedCosmetics >= 15) _unlockAchievement(AchievementId.cosmeticConnoisseur);
  }

  void _checkQuestResets() {
    _checkBattlePassReset();
    final now = DateTime.now();
    bool changed = false;

    if (lastDailyReset == null || _isNewCalendarDay(now, lastDailyReset!)) {
      for (var q in quests) {
        if (q.type == QuestType.daily) {
          q.isCompleted = false;
          q.currentKills = 0;
        }
      }
      riftClearsToday = 0;
      dailyCacheClaimed = false;
      dailyGoalCoinsClaimed = {};
      cosmeticSparksFromAdsToday = 0;
      lastDailyReset = now;
      changed = true;
    }

    if (lastRiftReset == null || _isNewCalendarDay(now, lastRiftReset!)) {
      riftAttemptsToday = 0;
      riftBonusAttemptsToday = 0;
      lastRiftReset = now;
      changed = true;
    }

    if (lastWeeklyReset == null || lastWeeklyReset!.isBefore(_mostRecentMonday(now))) {
      for (var q in quests) {
        if (q.type == QuestType.weekly) {
          q.isCompleted = false;
          q.currentKills = 0;
        }
      }
      weeklyRuneBossKills = 0;
      weeklyRuneQuestClaimed = false;
      riftClearsThisWeek = 0;
      lastWeeklyReset = now;
      changed = true;
    }

    if (lastMonthlyReset == null || lastMonthlyReset!.year != now.year || lastMonthlyReset!.month != now.month) {
      for (var q in quests) {
        if (q.type == QuestType.monthly) {
          q.isCompleted = false;
          q.currentKills = 0;
        }
      }
      riftClearsThisMonth = 0;
      lastMonthlyReset = now;
      changed = true;
    }

    if (changed) {
      notifyListeners();
    }
  }

  void _checkQuests() {
    for (var q in quests) {
      if (q.isCompleted) continue;
      final hasCondition = q.targetFloor > 0 ||
          q.targetKills > 0 ||
          q.requiredLairFloor > 0 ||
          q.requiredParagonLevel > 0 ||
          q.requiresSpecialization ||
          q.requiresHardcore ||
          q.requiresCompanion ||
          q.requiredRiftTier > 0 ||
          q.requiresCurse ||
          q.requiredRiftClears > 0;
      if (!hasCondition) continue;

      final floorOk = q.targetFloor == 0 || floor >= q.targetFloor;
      final killsOk = q.targetKills == 0 || q.currentKills >= q.targetKills;
      final classOk = q.requiredClass == null || q.requiredClass == heroClass;
      final lairOk = q.requiredLairFloor == 0 || defeatedLairFloors.contains(q.requiredLairFloor);
      final paragonOk = q.requiredParagonLevel == 0 || paragonLevel >= q.requiredParagonLevel;
      final specOk = !q.requiresSpecialization || specialization != 0;
      final hardcoreOk = !q.requiresHardcore || hardcoreUnlocked;
      final companionOk = !q.requiresCompanion || everRecruitedCompanions.isNotEmpty;
      final riftOk = q.requiredRiftTier == 0 || riftTier >= q.requiredRiftTier;
      final curseOk = !q.requiresCurse || activeCurse != CurseOfFate.none;
      int riftClearsThisPeriod = q.type == QuestType.daily
          ? riftClearsToday
          : q.type == QuestType.weekly
              ? riftClearsThisWeek
              : q.type == QuestType.monthly
                  ? riftClearsThisMonth
                  : 0;
      final riftClearsOk = q.requiredRiftClears == 0 || riftClearsThisPeriod >= q.requiredRiftClears;

      if (floorOk && killsOk && classOk && lairOk && paragonOk && specOk && hardcoreOk && companionOk && riftOk && curseOk && riftClearsOk) {
        q.isCompleted = true;
        if (q.type == QuestType.daily) {
          _checkDailyChronicleCoin(2, true);
          _addBattlePassRenown(10);
        }
        if (q.type == QuestType.weekly) _addBattlePassRenown(30);
        totalQuestsCompleted++;
        if (q.type == QuestType.monthly) {
          everCompletedMonthlyQuest = true;
          _addBattlePassRenown(100);
        }
        magicDust += q.rewardDust;
        gold += q.rewardGold;
        crystals += q.rewardCrystals;
        message = q.rewardCrystals > 0
            ? tr("Splněn quest: ${q.title}! Odměna: ${q.rewardDust} Dust, ${q.rewardGold} Gold, ${q.rewardCrystals} 💎", "Quest completed: ${q.title}! Reward: ${q.rewardDust} Dust, ${q.rewardGold} Gold, ${q.rewardCrystals} 💎")
            : tr("Splněn quest: ${q.title}! Odměna: ${q.rewardDust} Dust, ${q.rewardGold} Gold", "Quest completed: ${q.title}! Reward: ${q.rewardDust} Dust, ${q.rewardGold} Gold");
        _checkAchievements();
      }
    }
  }

