  // ===== ASCENSION: dopočítá level z aktuálního stavu odemčení (idempotentní - lze volat kdykoliv) =====
  // 0=Normal, 1=Hardcore odemčen, 2=Předpeklí odemčeno, 3=Peklo odemčeno, 4=Peklo patro 100
  // poraženo (odemyká Endless Scale). Nikdy neklesá (max s aktuálním levelem), i kdyby se
  // hráč vrátil do nižšího módu.
  void _syncAscensionLevel() {
    int target = ascensionLevel;
    if (hardcoreUnlocked) target = max(target, 1);
    if (predpekliUnlocked) target = max(target, 2);
    if (pekloUnlocked) target = max(target, 3);
    if (pekloFloor100Cleared) target = max(target, 4);
    if (target > ascensionLevel) {
      final int clampedTarget = target.clamp(0, 4);
      // Nová obtížnostní vrstva s vlastním patrem 1 (1/2/3 - level 4 jen odemyká Endless Scale,
      // floor se u něj neresetuje, takže tam žádný nový squish snapshot netřeba): spočti hráčovu
      // AKTUÁLNÍ nesquishnutou útočnou sílu (physAtk/magAtk podle třídy) a přepočti
      // ascensionPowerSquish tak, aby na patře 1 nové vrstvy zabití běžného nepřítele trvalo
      // přibližně _ascensionTargetHits zásahů - bez ohledu na to, kolik už měl hráč nafarmeno.
      if (clampedTarget > ascensionLevel && clampedTarget >= 1 && clampedTarget <= 3) {
        final double rawOffense = (classIsMagicAttack ? magAtk : physAtk) * ascensionPowerSquish;
        final double targetOffense = _towerFloor1EnemyHp(clampedTarget) / _ascensionTargetHits;
        if (rawOffense > 0 && targetOffense > 0) {
          final double neededSquish = rawOffense / targetOffense;
          ascensionPowerSquish = max(ascensionPowerSquish, max(1.0, neededSquish));
        }
      }
      ascensionLevel = clampedTarget;
      if (ascensionLevel >= 1) _queueContextTip(TutorialTipId.tipAscension);
      if (ascensionLevel >= 4 && !endlessScaleUnlocked) {
        endlessScaleUnlocked = true;
        message = tr("👑 ASCENSION IV DOKONČENA! Peklo je poraženo. Odemčen nový nekonečný mód: ENDLESS SCALE - Soul Demon tě čeká.", "👑 ASCENSION IV COMPLETE! Hell has been defeated. A new endless mode is unlocked: ENDLESS SCALE - the Soul Demon awaits.");
        _queueContextTip(TutorialTipId.tipEndlessScale);
      }
    }
  }

  // Klíč BEZ prokletí - Dust/Crystals/Suroviny/Esence jsou sdílené napříč všemi prokletími na
  // stejné obtížnosti a patře, ať nejde stejnou odměnu vyzvednout 6× (jednou za každé prokletí) -
  // to řeší lairRewardKey/lairRewardClaims výš, ale ten se používá i pro gem-loop (sbírání 6 gemů
  // do Prstenu Osudu, kde JE žádoucí umožnit re-clear stejného patra pod jiným prokletím), takže
  // je potřeba oddělený klíč jen pro materiální odměnu.
  String lairTierRewardKey(int targetFloor) => '${targetFloor}_$currentDifficultyKey';
  bool isLairTierRewardClaimed(int targetFloor) => lairTierRewardClaims.contains(lairTierRewardKey(targetFloor));

  // Sdílené vzorce pro Lair boss odměnu (Dust/Crystals) - používá jak SKUTEČNÉ udělení odměny
  // (_handleLairBossDeath), tak náhledový seznam bossů v LairScreen. Bez tohohle sdílení šlo
  // snadno rozjet drift mezi tím, co se hráči SLIBUJE v náhledu, a co skutečně dostane po zabití
  // (přesně tenhle bug - Crystals v náhledu ukazovaly 50×patro, skutečná odměna je jiný vzorec).
  int lairRewardDustFor(int targetFloor) => (250 * targetFloor * curseRewardMultiplier).toInt();
  int lairRewardCrystalsFor(int targetFloor) => ((50 + (targetFloor - 1) * 5) * kCrystalDropBonus).round();

  void _handleLairBossDeath() {
    lastLairRounds = lairCombatRoundCount;
    if (bestLairRounds == 0 || lastLairRounds < bestLairRounds) bestLairRounds = lastLairRounds;
    lastLairDamageDealt = currentLairDamageDealt;
    lastLairHealingDone = currentLairHealingDone;
    lastLairAbsorbGenerated = currentLairAbsorbGenerated;
    addRelicXp(5);_rollRelicDrop(0.05);if(relicKillHeal)hp=(hp+(maxHp*0.10).round()).clamp(0,maxHp);
    defeatedLairFloors.add(lairTargetFloor);
    lairRewardClaims.add(lairRewardKey(lairTargetFloor));

    // Dust/Crystals/Suroviny/Esence se udílí jen PRVNÍ zúčtování tohohle patra na tuhle obtížnost -
    // ne znovu za každé další prokletí, se kterým se stejné patro/obtížnost proleze v gem-loopu.
    final bool tierRewardAlreadyClaimed = isLairTierRewardClaimed(lairTargetFloor);
    lairTierRewardClaims.add(lairTierRewardKey(lairTargetFloor));

    int rewardDust = tierRewardAlreadyClaimed ? 0 : lairRewardDustFor(lairTargetFloor);
    int rewardCrystals = tierRewardAlreadyClaimed ? 0 : lairRewardCrystalsFor(lairTargetFloor);
    magicDust += rewardDust;
    crystals += rewardCrystals;
    // Suroviny za KAŽDÉHO Lair bosse, fixně podle aktuální obtížnosti (ne podle patra/mult) -
    // Normal 10, Hardcore 20, Předpeklí 30, Peklo 40 (viz difficultyTier: 0/1/2/3). Stejně jako
    // Dust/Crystals výš - jen při první zúčtování patra na tuhle obtížnost, ne za každé prokletí.
    const List<int> lairMaterialReward = [10, 20, 30, 40];
    final int materialsGain = tierRewardAlreadyClaimed ? 0 : lairMaterialReward[difficultyTier];
    materials += materialsGain;
    message = tierRewardAlreadyClaimed
        ? tr("Boss v Lair ($currentLairBossName) poražen! Odměna za tohle patro na $currentDifficultyKey obtížnosti už byla vyzvednuta (jiné prokletí), ale postup pokračuje.", "Lair boss ($currentLairBossName) defeated! The reward for this floor on $currentDifficultyKey difficulty was already claimed (different curse), but progress continues.")
        : tr("Boss v Lair ($currentLairBossName) poražen! Získal jsi +$rewardDust Dust a +$rewardCrystals 💎 a +$materialsGain ⚒️ Surovin!", "Lair boss ($currentLairBossName) defeated! You gained +$rewardDust Dust, +$rewardCrystals 💎, and +$materialsGain ⚒️ Materials!");
    // Esence Moci na vylepšování legendárního vybavení - odemčeno od patra 30 (Lair je náročný, odměna vyšší než ve věži).
    // Hardcore Mode (a vyšší) dává 2× tolik esence za stejné patro - odměna za vyšší obtížnost.
    // Stejná sdílená pojistka jako výš - jen při první zúčtování patra na tuhle obtížnost.
    if (lairTargetFloor >= 30 && !tierRewardAlreadyClaimed) {
      int essenceGain = 2 + Random().nextInt(3);
      if (atLeastHardcore) essenceGain *= 2;
      legendaryEssence += essenceGain;
      message += tr(" +$essenceGain 🔥 Esence!", " +$essenceGain 🔥 Essence!");
    }
    // Talentový bod za PRVNÍ vyčištění tohohle patra na tuhle obtížnost - PERMANENTNÍ, přežívá
    // smrt (na rozdíl od Tower verze, viz towerFloorTalentClaims/resetGame()). Tower na stejném
    // patře+obtížnosti už bod nedá, pokud ho tu má hráč natrvalo (viz isLairFloorTalentClaimed
    // check v _generateNextEnemy()) - vyhledej pro to samostatnou opravu.
    // Odděleno od tierRewardAlreadyClaimed (ten řídí jen Dust/Crystals/Suroviny/Esenci) + strop 100/obtížnost.
    final bool floorTalentAlreadyClaimed = isLairFloorTalentClaimed(lairTargetFloor);
    final bool floorTalentCapReached = lairFloorTalentCapReachedForCurrentDifficulty;
    lairFloorTalentClaims.add(floorTalentKey(lairTargetFloor));
    if (!floorTalentAlreadyClaimed && !floorTalentCapReached) {
      talentPoints++;
      permanentLairTalentPoints++;
      if (autoTalentsEnabled && talentPoints > 0) {
        talents[preferredAutoTalent] = talents[preferredAutoTalent]! + 1;
        talentPoints--;
      }
      message += tr(" +1 🎓 Talentový bod (natrvalo)!", " +1 🎓 Talent point (permanent)!");
    }
    // Hardcore set drop - 5 % z Hardcore Lair bosse. powerLevel na stejném měřítku jako běžný
    // drop (floor/5, ne floor/10) - dřív dával Hardcore set nespravedlivě SLABŠÍ staty než
    // obyčejný legendary drop na stejném patře, i když nese navíc pasivku.
    _tryDropHardcoreSetPiece(0.05, powerLevel: (lairTargetFloor / 5).ceil());
    _tryDropPredpekliSetPiece(0.05, powerLevel: (lairTargetFloor / 5).ceil());
    _tryDropPekloSetPiece(0.05, powerLevel: (lairTargetFloor / 5).ceil());
    // ===== LAIR 100 — Prsten Osudu (jednorázově) + odemčení Hardcore Mode =====
    if (lairTargetFloor >= 100 && !fateRingDropped) {
      fateRingDropped = true;
      _addGuaranteedFateRing();
      hardcoreUnlocked = true;
      _queueContextTip(TutorialTipId.tipHardcoreUnlocked);
      message = tr("💍 PRSTEN OSUDU! Získal jsi artefakt s 6 gem sloty!\n"
          "☠ Vše, co jsi dosud zažil, byl Normal. Odemčen Hardcore Mode - probouzíš se do skutečného Osudu.",
          "💍 RING OF FATE! You obtained an artifact with 6 gem slots!\n"
          "☠ Everything you have experienced so far was Normal. Hardcore Mode unlocked - you awaken to true Fate.");
    } else if (lairTargetFloor >= 100 && atLeastHardcore && activeCurse != CurseOfFate.none) {
      // ===== LAIR 100 v HARDCORE s aktivním prokletím — gem + eskalace =====
      final earnedCurse = activeCurse;
      final gemName = gemNameFor(earnedCurse);
      final ringMatches = inventory.where((i) => i.isArtifact).toList();
      final ring = ringMatches.isNotEmpty ? ringMatches.first : null;
      bool gemInserted = ring != null && ring.insertGem(gemName);

      hardcoreTier++;
      if (hardcoreTier >= predpekliUnlockHardcoreTier) _queueContextTip(TutorialTipId.tipPredpekliUnlocked);
      if (hardcoreTier >= pekloUnlockHardcoreTier) _queueContextTip(TutorialTipId.tipPekloUnlocked);
      final otherCurses = CurseOfFate.values.where((c) => c != CurseOfFate.none && c != earnedCurse).toList();
      activeCurse = otherCurses[Random().nextInt(otherCurses.length)];

      message = gemInserted
          ? tr("💎 $gemName vsazen do Prstenu Osudu! Hardcore pokračuje (tier $hardcoreTier) s novým prokletím: ${curseNameFor(activeCurse)}.", "💎 $gemName socketed into the Ring of Fate! Hardcore continues (tier $hardcoreTier) with a new curse: ${curseNameFor(activeCurse)}.")
          : tr("💎 $gemName získán, ale Prsten Osudu nemá volný slot! Hardcore pokračuje (tier $hardcoreTier) s novým prokletím: ${curseNameFor(activeCurse)}.", "💎 $gemName obtained, but the Ring of Fate has no free slot! Hardcore continues (tier $hardcoreTier) with a new curse: ${curseNameFor(activeCurse)}.");
    }
    // ===== PEKLO 100 — první poražení otevírá 4. Ascend (Endless Scale) =====
    if (pekloMode && lairTargetFloor >= 100 && !pekloFloor100Cleared) {
      pekloFloor100Cleared = true;
      message += tr("\n👑 PEKLO PORAŽENO! Otevírá se poslední Ascend.", "\n👑 HELL DEFEATED! The final Ascend opens.");
    }
    isInLair = false;
    hp = maxHp;
    heroEffects.clear();
    enemyEffects.clear();
    // Vzácný bonusový drop runy - Hardcore mód nebo vyšší obtížnost Lairu (Předpeklí/Peklo).
    if (atLeastHardcore && Random().nextDouble() < 0.04) _grantBonusRuneTalentPoint();
    if ((predpekliMode || pekloMode) && Random().nextDouble() < 0.06) _grantBonusRuneTalentPoint();
    if (lairTargetFloor >= 15) _registerLairBoss15PlusKill();
    _syncAscensionLevel();
    _checkAchievements();
  }

  // ===== ENDLESS SCALE: Soul Demon (capstone farm boss, odemyká se dokončením Pekla - viz ascensionLevel==4) =====
  // Staty se přepočítávají živě z aktuálních hráčových statů (ne z floor/mult křivky jako
  // ostatní režimy) - proto tenhle mód nikdy nepodléhá overflow problému, který jsme řešili
  // jinde. +10 % HP/Armor kumulativně za KAŽDÝ dosavadní kill (soulDemonKillCount) - Atk se
  // NEROZE - jen HP/Armor. Dodge/Crit/Block jsou napevno na stejném stropu, na jaký může
  // dosáhnout hráč sám (viz dodgeChance/critChance/blockChance výše).
  static const double soulDemonDodge = 0.40;
  static const double soulDemonBlock = 0.40;
  static const double soulDemonCrit = 0.60;

  void enterEndlessScale() {
    if (!endlessScaleUnlocked) {
      message = tr("Endless Scale se odemyká až po poražení bosse na patře 100 v Peklu.", "Endless Scale unlocks after defeating the floor-100 boss in Hell.");
      notifyListeners();
      return;
    }
    if (isDead) return;
    isInEndlessScale = true;
    hp = maxHp;
    heroEffects.clear();
    enemyEffects.clear();
    bonusShield = 0;
    _lastKnownBonusShield = 0; // sync pro _applyShieldCap() FX diffing
    _resetResources();
    soulDemonRoundCount = 0;
    soulDemonSpell1Cd = 0;
    soulDemonSpell2Cd = 0;
    soulDemonSpell3Cd = 0;
    soulDemonSpell4Cd = 0;
    endlessScaleAbilityUsed = false;
    endlessScaleSecondAbilityUsed = false;
    endlessScaleThirdAbilityUsed = false;
    endlessScaleFourthAbilityUsed = false;
    final double growth = pow(1.10, soulDemonKillCount).toDouble();
    soulDemonMaxHp = (maxHp * 2.0 * growth).toInt();
    soulDemonHp = soulDemonMaxHp;
    soulDemonArmor = (armor * 1.5 * growth).toInt();
    // Hybridní útok: průměr fyzického a magického Atk hrdiny, ×1.2 - neroste s killy.
    soulDemonAtk = (((physAtk + magAtk) / 2.0) * 1.2).toInt();
    message = tr("😈 Soul Demon se zjevuje (dosud poraženo ${soulDemonKillCount}×). HP ${formatCompactNumber(soulDemonHp)}.", "😈 The Soul Demon appears (defeated ${soulDemonKillCount}× so far). HP ${formatCompactNumber(soulDemonHp)}.");    notifyListeners();
  }

  // Zasadí poškození hrdinovi od Soul Demona. isFixedTrue = true → ignoruje hráčův
  // dodge/block (Spell 4 "Vyrvání duše" je garantovaný zásah, ne obyčejný útok).
  int _dealSoulDemonDamageToHero(double baseDmg, {bool isFixedTrue = false, double enrageMult = 1.0, bool isMagicHit = false}) {
    if (!isFixedTrue && Random().nextDouble() < dodgeChance) { _pushFx(FxKind.miss, FxSide.hero); hapticSelectionClick(); return 0; }
    bool demonCrit = Random().nextDouble() < soulDemonCrit;
    double dmg = baseDmg * enrageMult;
    if (demonCrit) dmg *= critDamageMultiplier;
    int rawDamage = mitigateDamage(dmg, isMagicHit ? DamageKind.magical : DamageKind.physical, value: armor);
    if (!isFixedTrue && Random().nextDouble() < blockChance) rawDamage = (rawDamage * 0.5).toInt();
    _applyIncomingDamage(rawDamage, (reflected) => soulDemonHp -= reflected);
    return rawDamage;
  }

  void fightSoulDemon(bool isMagic) {
    if (isDead || !isInEndlessScale) return;
    bool isCrit = nextAttackGuaranteedCrit || Random().nextDouble() < critChance;
    if (nextAttackGuaranteedCrit) nextAttackGuaranteedCrit = false;
    // Soul Demon se může vyhnout / zablokovat útok hrdiny (vlastní pevný strop, viz výše).
    if (Random().nextDouble() < soulDemonDodge) {
      message = tr("😈 Soul Demon se vyhnul tvému útoku!", "😈 The Soul Demon evaded your attack!");
      _resolveSoulDemonRound();
      return;
    }
    int dmg = isMagic ? magAtk : physAtk;
    final armorPen = runeEffect(RuneEffectType.armorPen);
    int effDef = armorPen > 0 ? (soulDemonArmor * (1 - armorPen)).clamp(0, double.infinity).toInt() : soulDemonArmor;
    int dealtDmg = _minDmg(dmg, dmg - effDef);
    dealtDmg = (dealtDmg * basicAttackRoleMod).toInt();
    if (isCrit) dealtDmg = (dealtDmg * critDamageMultiplier).toInt();
    if (nextAttackDamageBoost) { dealtDmg = (dealtDmg * 1.1).toInt(); nextAttackDamageBoost = false; }
    dealtDmg = (dealtDmg * specializationBossDamageMod).toInt();
    if (Random().nextDouble() < soulDemonBlock) {
      dealtDmg = (dealtDmg * 0.5).toInt();
      message = "🛡 Soul Demon zablokoval polovinu útoku! ";
    } else {
      message = isCrit ? "💥 Kritický zásah! " : "";
    }
    dealtDmg = _applyGemOffense(dealtDmg, enemyHp: soulDemonHp, enemyMaxHp: soulDemonMaxHp);
    soulDemonHp -= dealtDmg;
    if (heroClass == HeroClass.deathknight) _gainSoulRune();
    _applyKrevPassiveLifesteal(dealtDmg);
    message += tr("Způsobeno $dealtDmg poškození.", "Dealt $dealtDmg damage.");
    _resolveSoulDemonRound();
  }

  void _resolveSoulDemonRound() {
    soulDemonRoundCount++;
    _tickEffects((dot) => soulDemonHp -= dot);
    _regenResource();
    if (soulDemonHp <= 0) {
      _handleSoulDemonDeath();
      notifyListeners();
      return;
    }
    if (soulDemonSpell1Cd > 0) soulDemonSpell1Cd--;
    if (soulDemonSpell2Cd > 0) soulDemonSpell2Cd--;
    if (soulDemonSpell3Cd > 0) soulDemonSpell3Cd--;
    if (soulDemonSpell4Cd > 0) soulDemonSpell4Cd--;

    // Pasivka "Démonův hněv": +1 %/kolo dmg od 1. kola, bez stropu, reset novým bojem.
    final double enrageMult = 1.0 + 0.01 * soulDemonRoundCount;
    String spellMsg = '';
    bool usedSpell = false;

    if (soulDemonSpell4Cd <= 0) {
      // Spell 4 — Vyrvání duše: fixní hit za 50 % max HP hráče, CD 20, ignoruje dodge/block.
      soulDemonSpell4Cd = 20;
      int fixedDmg = (maxHp * 0.5 * enrageMult).toInt();
      int dealt = _dealSoulDemonDamageToHero(fixedDmg.toDouble(), isFixedTrue: true, enrageMult: 1.0);
      spellMsg = "😈 Vyrvání duše! Zásah za $dealt (50 % max HP).";
      usedSpell = true;
    } else if (soulDemonSpell1Cd <= 0) {
      // Spell 1 — Pohlcení duše: 20 % current HP hráče + lifesteal 50 % způsobeného dmg, CD 2.
      soulDemonSpell1Cd = 2;
      double dmg = hp * 0.20;
      int dealt = _dealSoulDemonDamageToHero(dmg, enrageMult: enrageMult);
      if (dealt > 0) {
        int heal = (dealt * 0.5).toInt();
        soulDemonHp = (soulDemonHp + heal).clamp(0, soulDemonMaxHp);
        spellMsg = "😈 Pohlcení duše: $dealt dmg (Soul Demon se vyléčil o $heal).";
      } else {
        spellMsg = "😈 Pohlcení duše - vyhnul ses!";
      }
      usedSpell = true;
    } else if (soulDemonSpell2Cd <= 0) {
      // Spell 2 — Řetězy zatracených: -15 % Dodge/-15 % Block na 3 kola, CD 4.
      soulDemonSpell2Cd = 4;
      heroEffects.removeWhere((e) => e.name == "Řetězy zatracených");
      heroEffects.add(StatusEffect(name: "Řetězy zatracených", description: "-15 % Dodge, -15 % Block", duration: 3, isBuff: false));
      spellMsg = "😈 Řetězy zatracených: -15 % Dodge a Block na 3 kola!";
      usedSpell = true;
    } else if (soulDemonSpell3Cd <= 0) {
      // Spell 3 — Křik ztracených duší: magický zásah + DoT 10 % current HP/kolo (3 kola), CD 5.
      soulDemonSpell3Cd = 5;
      int dealt = _dealSoulDemonDamageToHero(soulDemonAtk * 0.5, enrageMult: enrageMult, isMagicHit: true);
      int dot = (hp * 0.10).toInt();
      heroEffects.removeWhere((e) => e.name == "Křik ztracených duší");
      heroEffects.add(StatusEffect(name: "Křik ztracených duší", description: "DoT $dot/kolo", duration: 3, isBuff: false, dotDamage: dot));
      spellMsg = "😈 Křik ztracených duší: $dealt dmg + prokletí ($dot/kolo, 3 kola).";
      usedSpell = true;
    }

    if (!usedSpell) {
      int dealt = _dealSoulDemonDamageToHero(soulDemonAtk.toDouble(), enrageMult: enrageMult);
      spellMsg = dealt > 0 ? "Soul Demon útočí za $dealt poškození." : "Uhnul jsi útoku Soul Demona!";
    }
    message = spellMsg;

    if (hp <= 0) {
      isInEndlessScale = false;
      heroEffects.clear();
      enemyEffects.clear();
      _triggerDeath(tr("Zemřel jsi proti Soul Demonovi!", "You died against the Soul Demon!"), killer: "Soul Demon");
      return;
    }
    notifyListeners();
  }

  void _handleSoulDemonDeath() {
    soulDemonKillCount++;
    int fragmentGain = 10 + Random().nextInt(11); // 10-20 za kill
    soulFragments += fragmentGain;
    isInEndlessScale = false;
    hp = maxHp;
    heroEffects.clear();
    enemyEffects.clear();
    message = tr("😈💀 Soul Demon poražen! +$fragmentGain 👻 Soul Fragment (celkem $soulFragments). Příště bude o 10 % silnější (kill #$soulDemonKillCount).", "😈💀 Soul Demon defeated! +$fragmentGain 👻 Soul Fragment (total $soulFragments). It will be 10% stronger next time (kill #$soulDemonKillCount).");
    _checkAchievements();
  }

  // Hrdinovy vlastní schopnosti v Endless Scale - stejný generický _castTierXAbility engine jako
  // Lair/Tower/Rift/Aréna (viz useLairActiveAbility), jen cílí na soulDemonHp/soulDemonArmor a mají
  // vlastní cooldown flagy (endlessScaleAbilityUsed atd.), aby nesdílely stav s ostatními módy.
  void useEndlessScaleActiveAbility() {
    if (isDead || !isInEndlessScale || endlessScaleAbilityUsed || !hasAdvancedClass) return;
    if (!_spendResource(ability1Cost)) {
      message = tr("Nedostatek zdroje ($resourceName)! Potřeba: $ability1Cost, máš: $currentResourceValue.", "Not enough resource ($resourceName)! Needed: $ability1Cost, you have: $currentResourceValue.");
      notifyListeners();
      return;
    }
    endlessScaleAbilityUsed = true;
    _castTier1Ability('Endless Scale', soulDemonArmor, () => soulDemonHp, () => soulDemonMaxHp, (d) => soulDemonHp -= d);
    _resolveSoulDemonRound();
  }

