    _resolveSoulDemonRound();
  }

  // ===== WORLD BOSS: schopnosti (zrcadlí Lair - viz useLairActiveAbility/_resolveLairCombatRound) =====
  void _handleWorldBossDeath() {
    worldBossKills++;
    isInWorldBoss = false;
    lastWorldBossAttempt = DateTime.now(); // teprve VÝHRA spotřebuje dnešní pokus - viz enterWorldBoss.
    _checkDailyChronicleCoin(0, true);
    addRelicXp(10);
    runeStones += 1;
    legendaryEssence += 3;
    gold += 1000;
    message = tr("World Boss poražen! +10 Amulet XP, +1 Runový kámen, +3 Esence, +1000 zlata.", "World Boss defeated! +10 Amulet XP, +1 Rune Stone, +3 Essence, +1000 gold.");
    heroEffects.clear();
    enemyEffects.clear();
    _checkAchievements();
  }

  void _resolveWorldBossCombatRound() {
    worldBossRoundCount++;
    // ===== Nepřátelská schopnost - VŽDY na 2. kole (viz enemyAbilityEffects, sdílené s Věží -
    // World Boss losuje bosse ze stejného 100-položkového poolu přes getBossDetails()). =====
    double abilityDamageBonusPct = 0;
    bool abilityGuaranteedCrit = false;
    double abilityBossLifestealPct = 0;
    if (worldBossRoundCount == 2) {
      final def = enemyAbilityEffects[worldBossAbility];
      if (def != null) {
        switch (def.kind) {
          case EnemyAbilityKind.statDebuff:
            heroEffects.add(StatusEffect.statDebuff(name: "Schopnost: $worldBossAbility", description: tr("$worldBossName použil svou schopnost.", "$worldBossName used its ability."), duration: def.duration, mods: def.mods));
            break;
          case EnemyAbilityKind.stackingDebuff:
            heroEffects.removeWhere((e) => e.name == "Schopnost: $worldBossAbility");
            heroEffects.add(StatusEffect.statDebuff(name: "Schopnost: $worldBossAbility", description: tr("$worldBossName použil svou schopnost (stackuje se).", "$worldBossName used its ability (stacks)."), duration: def.duration, mods: def.mods));
            break;
          case EnemyAbilityKind.dot:
            heroEffects.add(StatusEffect(name: "Schopnost: $worldBossAbility", description: tr("$worldBossName tě otrávil/zapálil.", "$worldBossName poisoned/burned you."), duration: def.duration, isBuff: false, dotDamage: (maxHp * def.amount).round()));
            break;
          case EnemyAbilityKind.trueDamage:
            hp = max(0, hp - (maxHp * def.amount).round());
            break;
          case EnemyAbilityKind.ignoreArmor:
            abilityDamageBonusPct += def.amount;
            break;
          case EnemyAbilityKind.ignoreBlockDodge:
            heroEffects.add(StatusEffect.statDebuff(name: "Schopnost: $worldBossAbility", description: tr("Tenhle útok nejde blokovat ani uhnout.", "This attack can't be blocked or dodged."), duration: 1, mods: {'dodge': -1.0, 'block': -1.0}));
            break;
          case EnemyAbilityKind.guaranteedCrit:
            abilityGuaranteedCrit = true;
            break;
          case EnemyAbilityKind.doubleAttack:
            abilityDamageBonusPct += 1.0;
            break;
          case EnemyAbilityKind.stun:
            heroStunTurns += def.duration;
            break;
          case EnemyAbilityKind.blockSpell:
            heroSpellBlockTurns += def.duration;
            break;
          case EnemyAbilityKind.bossBuff:
            worldBossAtk = (worldBossAtk * (1 + def.amount)).round();
            enemyEffects.add(StatusEffect(name: "Schopnost: $worldBossAbility", description: tr("Posílený útok.", "Empowered attack."), duration: def.duration, isBuff: true));
            break;
          case EnemyAbilityKind.bossArmorBuff:
            // World Boss nemá vlastní Def stat (mitigateDamage tu čte hrdinovu Armor) - schopnost
            // se projeví jen kosmeticky přes hlášku, bez mechanického dopadu.
            break;
          case EnemyAbilityKind.bossShield:
          case EnemyAbilityKind.bossHeal:
            worldBossHp = min(worldBossMaxHp, worldBossHp + (worldBossMaxHp * def.amount).round());
            break;
          case EnemyAbilityKind.bossLifesteal:
            abilityBossLifestealPct = def.amount;
            break;
          case EnemyAbilityKind.resourceDrain:
            _drainResourcePct(def.amount);
            break;
          case EnemyAbilityKind.goldDrain:
            gold = max(0, (gold * (1 - def.amount)).round());
            break;
          case EnemyAbilityKind.cancelShield:
            bonusShield = 0;
            break;
          case EnemyAbilityKind.cancelBuff:
            final activeBuffs = heroEffects.where((e) => e.isBuff).toList();
            if (activeBuffs.isNotEmpty) heroEffects.remove(activeBuffs.first);
            break;
        }
        message = tr("⚔️ $worldBossName použil schopnost: $worldBossAbility!", "⚔️ $worldBossName used its ability: $worldBossAbility!");
        notifyListeners();
      }
    }
    _checkHenryBuff();
    _checkLauferBuff();
    _checkFenwickBuff();
    _checkThorinBuff();
    _checkAnriBuff();
    _checkRawenBuff();
    _tickEffects((dot) => worldBossHp -= dot);
    _regenResource();
    if (worldBossHp <= 0) {
      _handleWorldBossDeath();
      notifyListeners();
      return;
    }
    // Hardcore set "Nezdolná Pevnost" 6pc: útok bosse zcela negován (jednorázově).
    if (hardcoreInvulnerableActive) {
      hardcoreInvulnerableActive = false;
      message = "🛡️✨ Nezdolná Pevnost: " + tr("útok bosse zcela odražen!", "the boss's attack was completely deflected!");
      notifyListeners();
      return;
    }
    // Úhyb: pokud uspěje, hrdina zcela vyhne útoku bosse.
    if (Random().nextDouble() < dodgeChance) {
      message = tr("✨ Úhyb! Vyhnul jsi se útoku bosse.", "✨ Dodge! You evaded the boss's attack.");
      _pushFx(FxKind.miss, FxSide.hero);
      hapticSelectionClick();
      // Duelist Grácie: úspěšný úhyb spustí counter-attack.
      if (hasGraceCounter) {
        final counterDmg = (physAtk * 0.5).toInt();
        worldBossHp -= counterDmg;
        message += tr(" Counter-attack za $counterDmg dmg!", " Counter-attack for $counterDmg dmg!");
      }
      notifyListeners();
      return;
    }
    int rawDamage = mitigateDamage((worldBossAtk * worldBossEnrageDmgMult).round(), DamageKind.physical);
    if (abilityDamageBonusPct > 0) rawDamage = (rawDamage * (1 + abilityDamageBonusPct)).round();
    // abilityGuaranteedCrit (schopnost na 2. kole) - World Boss jinak crit neroluje, tak jen
    // aplikuje stejný 1.5× multiplikátor jako Doupě bosse, když schopnost vynutí crit.
    if (abilityGuaranteedCrit) {
      rawDamage = (rawDamage * 1.5).toInt();
      message = tr("💥 $worldBossName zasáhl kriticky!", "💥 $worldBossName landed a critical hit!");
    }
    // Krvavá lázeň (curse): čím méně HP má boss, tím větší damage dává (až +100 % při umírání).
    if (activeCurse == CurseOfFate.bloodbath && worldBossMaxHp > 0) {
      final missingRatio = (1.0 - worldBossHp / worldBossMaxHp).clamp(0.0, 1.0);
      rawDamage = (rawDamage * (1 + missingRatio)).toInt();
    }
    int worldBossFinalDmg = 0;
    final gemSaved = _applyIncomingDamage(rawDamage, (reflected) => worldBossHp -= reflected, onFinalDamage: (d) => worldBossFinalDmg = d);
    if (abilityBossLifestealPct > 0 && worldBossFinalDmg > 0) {
      worldBossHp = min(worldBossMaxHp, worldBossHp + (worldBossFinalDmg * abilityBossLifestealPct).round());
    }
    if (worldBossHp <= 0) {
      _handleWorldBossDeath();
      notifyListeners();
      return;
    }
    if (hp <= 0 && !gemSaved) {
      if (phoenixChargeActive) {
        phoenixChargeActive = false;
        hp = (maxHp * 0.5).toInt();
        message = "Elixír Fénixe " + tr("tě zachránil před smrtí! Obnoveno 50% HP.", "saved you from death! 50% HP restored.");
      } else {
        // Prohra proti World Bossovi NENÍ permadeath jako jinde ve hře - jen tě vyžene z boje.
        // Dnešní pokus zůstává dostupný (worldBossAvailable se váže na výhru, viz _handleWorldBossDeath),
        // takže to můžeš rovnou zkusit znovu.
        isInWorldBoss = false;
        hp = 1;
        worldBossRoundCount = 0;
        heroEffects.clear();
        enemyEffects.clear();
        message = tr("World Boss tě porazil a vyhnal z boje. Přežil jsi - vylič se a zkus to znovu!", "The World Boss defeated you and drove you out of the fight. You survived - heal up and try again!");
        notifyListeners();
        return;
      }
    }
    notifyListeners();
  }

  void useWorldBossActiveAbility() {
    if (isDead || !isInWorldBoss || worldBossAbilityUsed || !hasAdvancedClass) return;
    if (!_spendResource(ability1Cost)) {
      message = tr("Nedostatek zdroje ($resourceName)! Potřeba: $ability1Cost, máš: $currentResourceValue.", "Not enough resource ($resourceName)! Needed: $ability1Cost, you have: $currentResourceValue.");
      notifyListeners();
      return;
    }
    worldBossAbilityUsed = true;
    _castTier1Ability('World Boss', worldBossDef, () => worldBossHp, () => worldBossMaxHp, (d) => worldBossHp -= d);
    _resolveWorldBossCombatRound();
  }

