  // ===== TRHLINY OSUDU (RIFTY) =====
  // Opakovatelný endless mód, oddělený od Lair - mírnější křivka obtížnosti (podobná Věži, ne
  // exponenciální jako Lair), denní limit pokusů, permanentní tier-rekord. Odměna škáluje s tierem.
  // Celkový denní strop pokusů včetně reklamou získaných bonusů.
  int get riftEffectiveDailyLimit => riftDailyAttempts + riftBonusAttemptsToday;

  void enterRift(int tier) {
    if (heroClass == HeroClass.none) {
      message = tr("Nejprve si vyber třídu!", "First choose your class!");
      notifyListeners();
      return;
    }
    if (tier > riftTier + 1) {
      message = tr("Nejdřív musíš zdolat tier ${riftTier + 1}!", "You must first clear tier ${riftTier + 1}!");
      notifyListeners();
      return;
    }
    if (riftAttemptsToday >= riftEffectiveDailyLimit) {
      message = tr("Došly ti dnešní pokusy do Trhliny ($riftEffectiveDailyLimit/den). Vrať se zítra, nebo si přidej pokus za reklamu!", "You are out of Rift attempts for today ($riftEffectiveDailyLimit/day). Come back tomorrow, or watch an ad for an extra attempt!");
      notifyListeners();
      return;
    }
    riftAttemptsToday++;
    isInRift = true;
    currentRiftTier = tier;
    riftCombatRoundCount=0;
    riftInstability = 0;
    riftFragmentThreshold = 40;
    riftFragmentPending = false;
    hp = maxHp;
    heroEffects.clear();
    enemyEffects.clear();
    huntersMarkStacks = 0;
    arcaneChargeStacks = 0;
    flowingChiStacks = 0;
    riftAbilityUsed = false;
    riftSecondAbilityUsed = false;
    riftThirdAbilityUsed = false;
    riftFourthAbilityUsed = false;
    _resetResources();

    // Mírnější křivka než Lair (2.0 × 1.3^floor) - Rift je opakovatelný denní obsah, ne exponenciální capstone.
    double mult = 1.5 * pow(1.15, tier - 1).toDouble();
    if (atLeastHardcore) mult *= (1.0 + 0.5 * hardcoreTier);
    if (atLeastPredpekli && predpekliUnlocked) mult *= predpekliDifficultyMult; // Předpeklí: další vrstva navrch
    if (pekloMode && pekloUnlocked) mult *= pekloDifficultyMult; // Peklo: další vrstva navrch Předpeklí
    mult /= currentFightAscensionSquishDivisor; // viz Lair - stejný Ascension squish (jen pro vrstvu, ve které se právě bojuje - BUG FIX: dřív i Normal)
    mult = mult.clamp(0.0, 1e14); // pojistka proti přetečení int64 - viz stejná poznámka u Lair výš
    if (isMerchantEncounter) {
      isTreasureGoblinFight = false;
      message = tr("🧳 Potulný obchodník! Nabízí ocel, kůži a dřevo za zlato.", "🧳 A wandering merchant! Offering steel, leather, and wood for gold.");
      notifyListeners();
      return;
    }

    isTreasureGoblinFight = Random().nextDouble() < treasureGoblinSpawnChance;
    if (isTreasureGoblinFight) {
      treasureGoblinTurnsLeft = treasureGoblinMaxTurns;
      // Nízké HP a nulová obrana (padne rychle, pokud ho vůbec trefíš), minimální hrozba pro hráče -
      // hlavní výzva je stihnout ho zabít, než uteče, ne přežít jeho útok.
      currentRiftGuardianMaxHp = (25 * mult).clamp(0.0, 9e17).toInt();
      currentRiftGuardianHp = currentRiftGuardianMaxHp;
      currentRiftGuardianAtk = (4 * mult).clamp(0.0, 9e17).toInt();
      currentRiftGuardianDef = 0;
      message = tr("💰 POKLAD-SKŘET! Vzácný host se objevil v Trhlině - rychle ho zabij, než uteče s kořistí!", "💰 TREASURE GOBLIN! A rare visitor appeared in the Rift - kill it quickly before it flees with the loot!");
    } else {
      // Stejný princip jako u "Strážce Brány" v Lairu: víc HP (delší, vydatnější boj), ale ATK
      // NEroste stejným tempem - ať souboj neskáče hráči ze 100 % HP na 0 jedním-dvěma zásahy.
      currentRiftGuardianMaxHp = (120 * mult * 2.5).clamp(0.0, 9e17).toInt();
      currentRiftGuardianHp = currentRiftGuardianMaxHp;
      currentRiftGuardianAtk = (18 * mult * 0.6).clamp(0.0, 9e17).toInt();
      currentRiftGuardianDef = (6 * mult).clamp(0.0, 9e17).toInt();
      if (currentRiftMutator == RiftDailyMutator.frozenCurse) {
        currentRiftGuardianMaxHp = (currentRiftGuardianMaxHp * 1.40).round(); currentRiftGuardianHp = currentRiftGuardianMaxHp;
      } else if (currentRiftMutator == RiftDailyMutator.arcaneStorm) {
        currentRiftGuardianAtk = (currentRiftGuardianAtk * 1.50).round();
      } else if (currentRiftMutator == RiftDailyMutator.shatteredArmor) {
        currentRiftGuardianDef = (currentRiftGuardianDef * 0.50).round(); currentRiftGuardianAtk = (currentRiftGuardianAtk * 1.25).round();
      }
      message = tr("Vstoupil jsi do Trhliny Osudu (tier $tier)! Mutátor: ${currentRiftMutator.displayName}.", "You entered the Rift of Fate (tier $tier)! Mutator: ${currentRiftMutator.displayName}.");
    }
    notifyListeners();
  }

  // Monetizace: hráč zhlédne rewarded reklamu výměnou za +1 pokus do Trhliny dnes.
  // Skutečné přehrání/callback řeší RewardedAdService (Google Mobile Ads SDK) - tahle
  // metoda jen aplikuje odměnu, jakmile SDK potvrdí, že reklama doběhla (onUserEarnedReward).
  bool get canWatchAdForRiftAttempt => riftBonusAttemptsToday < riftMaxBonusAdsPerDay;

  void grantRiftAttemptFromAd() {
    if (!canWatchAdForRiftAttempt) return;
    riftBonusAttemptsToday++;
    everWatchedRiftAd = true;
    message = tr("🎬 Reklama dokoukána! +1 pokus do Trhliny Osudu dnes ($riftBonusAttemptsToday/$riftMaxBonusAdsPerDay bonusů).", "🎬 Ad watched! +1 Rift of Fate attempt today ($riftBonusAttemptsToday/$riftMaxBonusAdsPerDay bonuses).");
    _checkAchievements();
    notifyListeners();
  }

  // Skutečné přehrání reklamy řeší RewardedAdService (viz UI) - tahle metoda jen aplikuje
  // odměnu po potvrzeném zhlédnutí (onUserEarnedReward), stejný vzor jako grantRiftAttemptFromAd/
  // rerollMarketSlotFromAd. +1 Jiskra za každé zhlédnutí, max 10 denně (reset spolu s ostatními
  // denními věcmi v _checkQuestResets()).
  void grantCosmeticSparkFromAd() {
    if (!canWatchAdForCosmeticSpark) return;
    cosmeticSparks += 1;
    cosmeticSparksFromAdsToday++;
    everWatchedRiftAd = true; // sdílí achievement "adSupporter" se všemi zdroji rewarded reklam
    message = tr("🎬 Reklama dokoukána! +1 Jiskra ($cosmeticSparksFromAdsToday/$cosmeticSparksMaxPerDay dnes, celkem: $cosmeticSparks ✦).", "🎬 Ad watched! +1 Spark ($cosmeticSparksFromAdsToday/$cosmeticSparksMaxPerDay today, total: $cosmeticSparks ✦).");
    _checkAchievements();
    notifyListeners();
  }

  // ===== MANUÁLNÍ SCHOPNOSTI V RIFT (zrcadlí Lair - viz useLairActiveAbility) =====
  // Dřív se sesílaly automaticky na začátku kola - hráč chtěl mít nad tím kontrolu stejně
  // jako ve Věži/Lairu, takže teď je potřeba kliknout, jednou za pokus na schopnost.
  void useRiftActiveAbility() {
    if (isDead || !isInRift || isTreasureGoblinFight || riftAbilityUsed || !hasAdvancedClass) return;
    if (riftFragmentPending) { message = tr("Nejdřív vyřeš nestabilitu Trhliny!", "Resolve the Rift's instability first!"); notifyListeners(); return; }
    if (!_spendResource(ability1Cost)) {
      message = tr("Nedostatek zdroje ($resourceName)! Potřeba: $ability1Cost, máš: $currentResourceValue.", "Not enough resource ($resourceName)! Needed: $ability1Cost, you have: $currentResourceValue.");
      notifyListeners();
      return;
    }
    riftAbilityUsed = true;
    _castRiftAbility1();
    _resolveRiftCombatRound();
  }

  void useRiftSecondAbility() {
    if (isDead || !isInRift || isTreasureGoblinFight || riftSecondAbilityUsed || !hasUltimateClass) return;
    if (riftFragmentPending) { message = tr("Nejdřív vyřeš nestabilitu Trhliny!", "Resolve the Rift's instability first!"); notifyListeners(); return; }
    if (!_spendResource(ability2Cost)) {
      message = tr("Nedostatek zdroje ($resourceName)! Potřeba: $ability2Cost, máš: $currentResourceValue.", "Not enough resource ($resourceName)! Needed: $ability2Cost, you have: $currentResourceValue.");
      notifyListeners();
      return;
    }
    riftSecondAbilityUsed = true;
    _castRiftAbility2();
    _resolveRiftCombatRound();
  }

  void useRiftThirdAbility() {
    if (isDead || !isInRift || isTreasureGoblinFight || riftThirdAbilityUsed || !hasGodClass) return;
    if (riftFragmentPending) { message = tr("Nejdřív vyřeš nestabilitu Trhliny!", "Resolve the Rift's instability first!"); notifyListeners(); return; }
    if (!_spendResource(ability3Cost)) {
      message = tr("Nedostatek zdroje ($resourceName)! Potřeba: $ability3Cost, máš: $currentResourceValue.", "Not enough resource ($resourceName)! Needed: $ability3Cost, you have: $currentResourceValue.");
      notifyListeners();
      return;
    }
    riftThirdAbilityUsed = true;
    _castRiftAbility3();
    _resolveRiftCombatRound();
  }

  void useRiftFourthAbility() {
    if (isDead || !isInRift || isTreasureGoblinFight || riftFourthAbilityUsed || !hasRank100Class) return;
    if (riftFragmentPending) { message = tr("Nejdřív vyřeš nestabilitu Trhliny!", "Resolve the Rift's instability first!"); notifyListeners(); return; }
    if (!_spendResource(ability4Cost)) {
      message = tr("Nedostatek zdroje ($resourceName)! Potřeba: $ability4Cost, máš: $currentResourceValue.", "Not enough resource ($resourceName)! Needed: $ability4Cost, you have: $currentResourceValue.");
      notifyListeners();
      return;
    }
    riftFourthAbilityUsed = true;
    _castRiftAbility4();
    _resolveRiftCombatRound();
  }

  void _castRiftAbility1() {
    final armorPenR1 = runeEffect(RuneEffectType.armorPen);
    final effDef = armorPenR1 > 0 ? (currentRiftGuardianDef * (1 - armorPenR1)).clamp(0, double.infinity).toInt() : currentRiftGuardianDef;
    if (isBerserk) {
      int dmg = (physAtk * 2.5 * specAbilityDamageMod).toInt();
      if (specialization == 1 && activeHardcoreSetTier >= 2) dmg = (dmg * 1.25).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentRiftGuardianHp -= dmg;
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.berserk);
      _applyAbilityDot(dmg);
      if (specialization == 3 && activeHardcoreSetTier >= 2 && appliesBleedOnAbility) {
        final bonusBleed = ((dmg * 0.20 / 3) * 0.5).round();
        final idx = enemyEffects.indexWhere((e) => e.name == "Krvácení (Krvežíznivý)");
        if (idx != -1) enemyEffects[idx] = StatusEffect(name: "Krvácení (Krvežíznivý)", description: "Krvácení ${enemyEffects[idx].dotDamage + bonusBleed}/kolo", duration: enemyEffects[idx].duration, isBuff: false, dotDamage: enemyEffects[idx].dotDamage + bonusBleed);
      }
      if (specialization == 2 && activeHardcoreSetTier >= 2) {
        final shieldGain = (maxHp * 0.15).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
      }
      message = tr("🔄 Auto-cast: Mocný úder! Způsobeno $dmg poškození.", "🔄 Auto-cast: Mocný úder! Dealt $dmg damage.");
    } else if (isAssassin) {
      int dmg = (physAtk * 2.0).toInt();
      if (specialization == 1 && activeHardcoreSetTier >= 2) dmg = (dmg * critDamageMultiplier).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentRiftGuardianHp -= dmg;
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.assassin);
      int heal = (dmg * 0.5).toInt();
      if (specialization == 2 && activeHardcoreSetTier >= 2) heal *= 2;
      hp = (hp + heal).clamp(0, maxHp);
      _applyAbilityDot(dmg);
      if (specialization == 3 && activeHardcoreSetTier >= 2) {
        final idx = enemyEffects.indexWhere((e) => e.name == "Jed (Stín)");
        if (idx != -1) enemyEffects[idx] = StatusEffect(name: "Jed (Stín)", description: "Jed ${enemyEffects[idx].dotDamage * 2}/kolo", duration: enemyEffects[idx].duration, isBuff: false, dotDamage: enemyEffects[idx].dotDamage * 2);
      }
      message = tr("🔄 Auto-cast: Skrytý úder! Způsobeno $dmg poškození a vyléčeno $heal HP.", "🔄 Auto-cast: Skrytý úder! Dealt $dmg damage and healed $heal HP.");
    } else if (isPriest) {
      int heal = (maxHp * 0.5 * specAbilitySustainMod).toInt();
      if (specialization == 1 && activeHardcoreSetTier >= 2) heal = (heal * 1.5).toInt();
      hp = (hp + heal).clamp(0, maxHp);
      final shieldGain = (maxHp * 0.10 * specAbilitySustainMod).toInt();
      bonusShield += shieldGain;
      _applyShieldCap();
      _pushFx(FxKind.shieldGained, FxSide.hero, value: heal, spellFxKind: SpellFxKind.healerBlessing);
      heroEffects.add(StatusEffect(name: "Boží štít", description: "+10 % MaxHP absorpce", duration: 5, isBuff: true));
      message = tr("🔄 Auto-cast: Boží požehnání! Obnoveno $heal HP a přidán štít (+$shieldGain).", "🔄 Auto-cast: Boží požehnání! Restored $heal HP and added a shield (+$shieldGain).");
      if (specialization == 2 && activeHardcoreSetTier >= 2) {
        final reflectDmg = (shieldGain * 0.10).toInt();
        currentRiftGuardianHp -= reflectDmg;
        message += tr(" (Odplata: -$reflectDmg nepříteli)", " (Retribution: -$reflectDmg to the enemy)");
      }
      if (specialization == 3 && activeHardcoreSetTier >= 2) {
        final punishDmg = (heal * 0.30).toInt();
        currentRiftGuardianHp -= punishDmg;
        message += tr(" (+$punishDmg dmg nepříteli)", " (+$punishDmg dmg to the enemy)");
      }
    } else if (isDarkKnight) {
      final double triple = nextSpellTriple ? 3.0 : 1.0;
      if (nextSpellTriple) { nextSpellTriple = false; soulRunes = 0; }
      int physDmg = (physAtk * 1.5 * triple).toInt();
      if (specialization == 2 && activeHardcoreSetTier >= 2) physDmg = (physDmg * critDamageMultiplier).toInt();
      physDmg = _minDmg(physDmg, physDmg - effDef);
      currentRiftGuardianHp -= physDmg;
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: physDmg, spellFxKind: SpellFxKind.dkCursedStrike);
      _applyKrevPassiveLifesteal(physDmg);
      int dotDmg = (magAtk * 0.5 * triple * curseDmgMod).toInt();
      int curseDuration = (4 + curseCastDurationDelta).clamp(1, 99);
      if (specialization == 3 && activeHardcoreSetTier >= 2) curseDuration += 2;
      enemyEffects.removeWhere((e) => e.name == "Prokletí");
      enemyEffects.add(StatusEffect(name: "Prokletí", description: "Prokletí $dotDmg/kolo ($curseDuration kola)", duration: curseDuration, isBuff: false, dotDamage: dotDmg));
      message = tr("🔄 Auto-cast ☠ Prokletý úder! $physDmg dmg + Prokletí $dotDmg/kolo po $curseDuration kola.${triple > 1 ? ' ✨ TROJNÁSOBEK!' : ''}", "🔄 Auto-cast ☠ Prokletý úder! $physDmg dmg + Curse $dotDmg/round for $curseDuration rounds.${triple > 1 ? ' ✨ TRIPLED!' : ''}");
      if (specialization == 1 && activeHardcoreSetTier >= 2) {
        final selfHeal = (physDmg * 0.15).toInt();
        hp = (hp + selfHeal).clamp(0, maxHp);
        message += tr(" (+$selfHeal HP)", " (+$selfHeal HP)");
      }
    } else if (isElementalist) {
      int dmg = (magAtk * 2.5 * specAbilityDamageMod).toInt();
      if (specialization == 1 && activeHardcoreSetTier >= 2) {
        final burnDmg = (magAtk * 0.15).toInt();
        enemyEffects.removeWhere((e) => e.name == "Popálení (Set)");
        enemyEffects.add(StatusEffect(name: "Popálení (Set)", description: "Popálení $burnDmg/kolo", duration: 3, isBuff: false, dotDamage: burnDmg));
      }
      if (specialization == 2 && activeHardcoreSetTier >= 2) {
        final shieldGain = (maxHp * 0.10).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
      }
      if (specialization == 3 && activeHardcoreSetTier >= 2) {
        arcaneChargeStacks = (arcaneChargeStacks + 2).clamp(0, arcaneChargeMaxStacks);
      }
      dmg = _minDmg(dmg, dmg - effDef);
      currentRiftGuardianHp -= dmg;
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.elementalist);
      message = tr("🔄 Auto-cast: Elementální výbuch! Způsobeno $dmg poškození.", "🔄 Auto-cast: Elementální výbuch! Dealt $dmg damage.");
    } else if (isBladeDancer) {
      int dmg = (physAtk * 2.2 * specAbilityDamageMod).toInt();
      if (specialization == 1 && activeHardcoreSetTier >= 2 && currentRiftGuardianMaxHp > 0 && currentRiftGuardianHp / currentRiftGuardianMaxHp < 0.3) {
        dmg = (dmg * 1.3).toInt();
      }
      if (specialization == 3 && activeHardcoreSetTier >= 2) dmg = (dmg * critDamageMultiplier).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentRiftGuardianHp -= dmg;
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.bladeDancer);
      _applyAbilityDot(dmg);
      if (specialization == 2 && activeHardcoreSetTier >= 2) {
        heroEffects.removeWhere((e) => e.name == "Elegantní Tanec");
        heroEffects.add(StatusEffect(name: "Elegantní Tanec", description: "+10 % úhyb", duration: 3, isBuff: true));
      }
      message = tr("🔄 Auto-cast: Rychlé combo! Způsobeno $dmg poškození.", "🔄 Auto-cast: Rychlé combo! Dealt $dmg damage.");
    } else if (isDisciple) {
      int dmg = (physAtk * 2.2 * specAbilityDamageMod).toInt();
      if (specialization == 1 && activeHardcoreSetTier >= 2) dmg = (dmg * 1.25).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentRiftGuardianHp -= dmg;
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.disciple);
      if (specialization == 1) {
        final dot = (dmg * 0.15 / 3).round();
        // Krvácení (Vichr) se SČÍTÁ, ne resetuje - další zásah přidá dmg k stávajícímu tiku a
        // obnoví trvání, takže už nastřádaný damage nikdy nezmizí, jen se rozloží do dalších kol.
        final vichrIdx = enemyEffects.indexWhere((e) => e.name == "Krvácení (Vichr)");
        if (vichrIdx != -1) {
          final stackedDot = cappedVichrBleed(enemyEffects[vichrIdx].dotDamage + dot);
          enemyEffects[vichrIdx] = StatusEffect(name: "Krvácení (Vichr)", description: "Krvácení $stackedDot/kolo", duration: 3, isBuff: false, dotDamage: stackedDot);
        } else {
          enemyEffects.add(StatusEffect(name: "Krvácení (Vichr)", description: "Krvácení $dot/kolo", duration: 3, isBuff: false, dotDamage: dot));
        }
      }
      if (specialization == 2 && activeHardcoreSetTier >= 2) {
        final shieldGain = (maxHp * 0.15).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
      }
      message = tr("🔄 Auto-cast: Úder tisíce dlaní! Způsobeno $dmg poškození.", "🔄 Auto-cast: Úder tisíce dlaní! Dealt $dmg damage.");
      if (monkCalmHealFromDamage > 0) {
        double healPercent = monkCalmHealFromDamage;
        if (specialization == 3 && activeHardcoreSetTier >= 2) healPercent *= 2;
        final selfHeal = (dmg * healPercent * specAbilitySustainMod).toInt();
        hp = (hp + selfHeal).clamp(0, maxHp);
        message += tr(" Vyléčeno $selfHeal HP.", " Healed $selfHeal HP.");
      }
    }
  }

  void _castRiftAbility2() {
    final armorPenR2 = runeEffect(RuneEffectType.armorPen);
    final effDef = armorPenR2 > 0 ? (currentRiftGuardianDef * (1 - armorPenR2)).clamp(0, double.infinity).toInt() : currentRiftGuardianDef;
    if (isWarlord) {
      int dmg = (physAtk * 4.0 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentRiftGuardianHp -= dmg;
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.warlord);
      double shieldMult = 0.25;
      if (specialization == 2 && activeHardcoreSetTier >= 4) shieldMult *= 2;
      final shieldGain = (maxHp * shieldMult * specAbilitySustainMod).toInt();
      bonusShield += shieldGain;
      _applyShieldCap();
      _applyAbilityDot(dmg);
      if (specialization == 3 && activeHardcoreSetTier >= 4) {
        final idx = enemyEffects.indexWhere((e) => e.name == "Krvácení (Krvežíznivý)");
        if (idx != -1 && enemyEffects[idx].duration < 6) enemyEffects[idx].duration = 6;
      }
      heroEffects.add(StatusEffect(name: "Warlordova hradba", description: "+25 % MaxHP štít", duration: 8, isBuff: true));
      message = tr("🔄 Auto-cast: Rozdrcení světa za $dmg poškození a štít (+$shieldGain).", "🔄 Auto-cast: Rozdrcení světa for $dmg damage and a shield (+$shieldGain).");
      if (specialization == 1 && activeHardcoreSetTier >= 4) {
        rage = (rage + ability2Cost).clamp(0, maxRage);
        message += "Krvavý Vztek: " + tr("zdroj vrácen!", "resource refunded!");
      }
    } else if (isShadowMaster) {
      int dmg = (physAtk * 5.0).toInt();
      if (specialization == 1 && activeHardcoreSetTier >= 4) dmg = (dmg * 1.5).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentRiftGuardianHp -= dmg;
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.shadowMaster);
      _applyAbilityDot(dmg);
      if (specialization == 3 && activeHardcoreSetTier >= 4) {
        final dot = (dmg * 0.10 / 3).round();
        enemyEffects.removeWhere((e) => e.name == "Jed (Stín)");
        enemyEffects.add(StatusEffect(name: "Jed (Stín)", description: "Jed $dot/kolo", duration: 3, isBuff: false, dotDamage: dot));
      }
      message = tr("🔄 Auto-cast: Stínová poprava za $dmg poškození.", "🔄 Auto-cast: Stínová poprava for $dmg damage.");
    } else if (isProrok) {
      hp = maxHp;
      int dmg = (magAtk * 3.5 * specAbilityDamageMod).toInt();
      if (specialization == 3 && activeHardcoreSetTier >= 4) dmg = (dmg * 1.5).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentRiftGuardianHp -= dmg;
      _pushFx(FxKind.explosionDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.healerJudgment);
      if (specialization == 1 && activeHardcoreSetTier >= 4) {
        final shieldGain = (maxHp * 0.30).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
        message = tr("🔄 Auto-cast: Boží soud! Plné HP, úder za $dmg poškození a štít (+$shieldGain).", "🔄 Auto-cast: Boží soud! Full HP, a strike for $dmg damage, and a shield (+$shieldGain).");
      } else {
        message = tr("🔄 Auto-cast: Boží soud! Plné HP a úder za $dmg poškození.", "🔄 Auto-cast: Boží soud! Full HP and a strike for $dmg damage.");
      }
      if (specialization == 2 && activeHardcoreSetTier >= 4) {
        final bonusDmg = (magAtk * 0.20).toInt();
        currentRiftGuardianHp -= bonusDmg;
        message += tr(" (Odplata: +$bonusDmg dmg)", " (Retribution: +$bonusDmg dmg)");
      }
    } else if (isPlagueLord) {
      final double triple = nextSpellTriple ? 3.0 : 1.0;
      if (nextSpellTriple) { nextSpellTriple = false; soulRunes = 0; }
      final prokl = enemyEffects.firstWhere((e) => e.name == "Prokletí", orElse: () => StatusEffect(name: "", description: "", duration: 0, isBuff: false));
      final bool hasCurse = prokl.name == "Prokletí";
      final int remainingDotTurns = hasCurse ? prokl.duration : 0;
      final int originalDotDmg = hasCurse ? prokl.dotDamage : 0;
      int remainingCurseDamage = hasCurse ? (prokl.dotDamage * remainingDotTurns * triple * curseDmgMod).toInt() : 0;
      if (specialization == 2 && activeHardcoreSetTier >= 4) remainingCurseDamage = (remainingCurseDamage * 1.5).toInt();
      if (remainingCurseDamage > 0) currentRiftGuardianHp -= remainingCurseDamage;
      _applyKrevPassiveLifesteal(remainingCurseDamage);
      if (hasCurse) {
        enemyEffects.removeWhere((e) => e.name == "Prokletí");
        if (specialization == 3 && activeHardcoreSetTier >= 4) {
          final newDuration = (4 + curseCastDurationDelta).clamp(1, 99);
          enemyEffects.add(StatusEffect(name: "Prokletí", description: "Prokletí $originalDotDmg/kolo", duration: newDuration, isBuff: false, dotDamage: originalDotDmg));
        }
      }
      const int maxDotTurns = 4;
      final double completion = 1.0 - (remainingDotTurns / maxDotTurns);
      final double shieldPercent = 25 + (completion * 50);
      final int shieldGain = (maxHp * (shieldPercent / 100)).toInt();
      bonusShield += shieldGain;
      _applyShieldCap();
      if (remainingCurseDamage > 0) {
        _pushFx(FxKind.explosionDamage, FxSide.enemy, value: remainingCurseDamage, spellFxKind: SpellFxKind.dkCurseExplosion);
      } else {
        _pushFx(FxKind.shieldGained, FxSide.hero, value: shieldGain, spellFxKind: SpellFxKind.dkCurseExplosion);
      }
      if (remainingCurseDamage > 0) {
        message = tr("🔄 Auto-cast 💥 Exploze prokletí za $remainingCurseDamage poškození a štít +$shieldGain!${triple > 1 ? ' ✨ TROJNÁSOBEK!' : ''}", "🔄 Auto-cast 💥 Curse Explosion for $remainingCurseDamage damage and shield +$shieldGain!${triple > 1 ? ' ✨ TRIPLED!' : ''}");
      } else {
        message = tr("🔄 Auto-cast: Žádné aktivní Prokletí - vytvořen absorb štít +$shieldGain.", "🔄 Auto-cast: No active Curse - created an absorb shield +$shieldGain.");
      }
      if (specialization == 1 && activeHardcoreSetTier >= 4 && remainingCurseDamage > 0) {
        hp = (hp + remainingCurseDamage).clamp(0, maxHp);
        message += tr(" (+$remainingCurseDamage HP)", " (+$remainingCurseDamage HP)");
      }
    } else if (isArcanist) {
      int dmg = (magAtk * 4.5 * specAbilityDamageMod).toInt();
      if (specialization == 3 && activeHardcoreSetTier >= 4) {
        dmg = (dmg * (1 + arcaneChargeStacks * arcaneChargePerStack)).toInt();
      }
      dmg = _minDmg(dmg, dmg - effDef);
      currentRiftGuardianHp -= dmg;
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.arcanist);
      double manaRefundMult = 0.3;
      if (specialization == 1 && activeHardcoreSetTier >= 4) manaRefundMult *= 2;
      mana = (mana + (ability2Cost * manaRefundMult).toInt()).clamp(0, maxMana);
      message = tr("🔄 Auto-cast: Arkánový nával za $dmg poškození (část many vrácena).", "🔄 Auto-cast: Arkánový nával for $dmg damage (part of the mana refunded).");
    } else if (isBladeMaster) {
      int dmg = (physAtk * 5.0 * specAbilityDamageMod).toInt();
      if (specialization == 1 && activeHardcoreSetTier >= 4 && currentRiftGuardianMaxHp > 0 && currentRiftGuardianHp / currentRiftGuardianMaxHp < 0.3) {
        dmg = (dmg * 1.3).toInt();
      }
      if (specialization == 3 && activeHardcoreSetTier >= 4) dmg = (dmg * 1.5).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentRiftGuardianHp -= dmg;
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.bladeMaster);
      _applyAbilityDot(dmg);
      message = tr("🔄 Auto-cast: Precizní výpad za $dmg poškození.", "🔄 Auto-cast: Precizní výpad for $dmg damage.");
    } else if (isGrandmaster) {
      int dmg = (physAtk * 4.5 * specAbilityDamageMod).toInt();
      if (specialization == 1 && activeHardcoreSetTier >= 4 && currentRiftGuardianMaxHp > 0 && currentRiftGuardianHp / currentRiftGuardianMaxHp < 0.3) {
        dmg = (dmg * 1.3).toInt();
      }
      dmg = _minDmg(dmg, dmg - effDef);
      currentRiftGuardianHp -= dmg;
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.grandmaster);
      double shieldMult = 0.20;
      if (specialization == 2 && activeHardcoreSetTier >= 4) shieldMult *= 2;
      final shieldGain = (maxHp * shieldMult * specAbilitySustainMod).toInt();
      bonusShield += shieldGain;
      _applyShieldCap();
      message = tr("🔄 Auto-cast: Dračí kop! Způsobeno $dmg poškození a získán štít (+$shieldGain).", "🔄 Auto-cast: Dračí kop! Dealt $dmg damage and gained a shield (+$shieldGain).");
      if (specialization == 1) {
        final dot = (dmg * 0.15 / 3).round();
        // Krvácení (Vichr) se SČÍTÁ, ne resetuje - další zásah přidá dmg k stávajícímu tiku a
        // obnoví trvání, takže už nastřádaný damage nikdy nezmizí, jen se rozloží do dalších kol.
        final vichrIdx = enemyEffects.indexWhere((e) => e.name == "Krvácení (Vichr)");
        if (vichrIdx != -1) {
          final stackedDot = cappedVichrBleed(enemyEffects[vichrIdx].dotDamage + dot);
          enemyEffects[vichrIdx] = StatusEffect(name: "Krvácení (Vichr)", description: "Krvácení $stackedDot/kolo", duration: 3, isBuff: false, dotDamage: stackedDot);
        } else {
          enemyEffects.add(StatusEffect(name: "Krvácení (Vichr)", description: "Krvácení $dot/kolo", duration: 3, isBuff: false, dotDamage: dot));
        }
      }
      if (monkCalmHealFromDamage > 0) {
        final selfHeal = (dmg * monkCalmHealFromDamage * specAbilitySustainMod).toInt();
        hp = (hp + selfHeal).clamp(0, maxHp);
        message += tr(" Vyléčeno $selfHeal HP.", " Healed $selfHeal HP.");
      }
      if (specialization == 3 && activeHardcoreSetTier >= 4) {
        final extraHeal = (dmg * 0.25).toInt();
        hp = (hp + extraHeal).clamp(0, maxHp);
        message += tr(" (+$extraHeal HP)", " (+$extraHeal HP)");
      }
    }
  }

  void _castRiftAbility3() {
    final armorPenR3 = runeEffect(RuneEffectType.armorPen);
    final effDef = armorPenR3 > 0 ? (currentRiftGuardianDef * (1 - armorPenR3)).clamp(0, double.infinity).toInt() : currentRiftGuardianDef;
    if (isValhallaWarrior) {
      int dmg = (physAtk * 7.5 * specAbilityDamageMod).toInt();
