        hp = maxHp;
        lifestealTurns += 20;
        message = tr("🔄 Auto-cast (Mistr Života): plné HP a trvalý lifesteal!", "🔄 Auto-cast (Mistr Života): full HP and lasting lifesteal!");
      } else if (rank100Choice == 3) {
        int dmg = (magAtk * 16.0 * specAbilityDamageMod).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentRiftGuardianHp -= dmg;
        message = tr("🔄 Auto-cast (Svatý Osvícený): Boží paprsek za $dmg poškození!", "🔄 Auto-cast (Svatý Osvícený): Divine Ray for $dmg damage!");
      }
    } else if (heroClass == HeroClass.deathknight) {
      final double triple = nextSpellTriple ? 3.0 : 1.0;
      if (nextSpellTriple) { nextSpellTriple = false; soulRunes = 0; }
      if (rank100Choice == 1) {
        int physDmg = (physAtk * 2.0 * triple).toInt();
        physDmg = _minDmg(physDmg, physDmg - effDef);
        int dotDmg = magAtk;
        int explodeDmg = (dotDmg * 5 * 4 * triple * curseDmgMod).toInt();
        currentRiftGuardianHp -= (physDmg + explodeDmg);
        _applyKrevPassiveLifesteal(physDmg + explodeDmg);
        message = tr("🔄 Auto-cast 💀 Kostěný Lich: Prokletí vypáleno za ${physDmg + explodeDmg} celkového poškození!${triple > 1 ? ' ✨ TROJNÁSOBEK!' : ''}", "🔄 Auto-cast 💀 Kostěný Lich: Curse detonated for ${physDmg + explodeDmg} total damage!${triple > 1 ? ' ✨ TRIPLED!' : ''}");
      } else if (rank100Choice == 2) {
        int dmg = ((physAtk + magAtk) * 5.0 * triple).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentRiftGuardianHp -= dmg;
        _applyKrevPassiveLifesteal(dmg);
        lifestealTurns += 15;
        message = tr("🔄 Auto-cast ⚔️ Temný Reaper: Smrtící řez za $dmg dmg + silný lifesteal!${triple > 1 ? ' ✨ TROJNÁSOBEK!' : ''}", "🔄 Auto-cast ⚔️ Temný Reaper: Deadly Cut for $dmg dmg + strong lifesteal!${triple > 1 ? ' ✨ TRIPLED!' : ''}");
      } else if (rank100Choice == 3) {
        int dmg = (magAtk * 4.0 * triple).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentRiftGuardianHp -= dmg;
        _applyKrevPassiveLifesteal(dmg);
        hp = maxHp;
        bonusShield += (maxHp * 0.5 * triple).toInt();
        _applyShieldCap();
        soulRunes = 7; // unikátní bonus Pán Duší - viz stejná oprava/poznámka u Tower verze výš.
        nextSpellTriple = false;
        message = tr("🔄 Auto-cast 👻 Pán Duší: Duše pohlceny za $dmg dmg, plné HP a masivní štít!${triple > 1 ? ' ✨ TROJNÁSOBEK!' : ''}", "🔄 Auto-cast 👻 Pán Duší: Souls consumed for $dmg dmg, full HP, and a massive shield!${triple > 1 ? ' ✨ TRIPLED!' : ''}");
      }
    } else if (heroClass == HeroClass.mage) {
      if (rank100Choice == 1) {
        int dmg = (magAtk * 11.0 * specAbilityDamageMod).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentRiftGuardianHp -= dmg;
        final burnDmg = (magAtk * 0.4).toInt();
        enemyEffects.removeWhere((e) => e.name == "Popálení");
        enemyEffects.add(StatusEffect(name: "Popálení", description: "Popálení $burnDmg/kolo", duration: 3, isBuff: false, dotDamage: burnDmg));
        message = tr("🔄 Auto-cast (Pyromancer): Ohnivý příval za $dmg poškození + Popálení $burnDmg/kolo!", "🔄 Auto-cast (Pyromancer): Firestorm for $dmg damage + Burn $burnDmg/round!");
      } else if (rank100Choice == 2) {
        int dmg = (magAtk * 9.0 * specAbilityDamageMod).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentRiftGuardianHp -= dmg;
        final shieldGain = (maxHp * 0.5 * specAbilitySustainMod).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
        message = tr("🔄 Auto-cast (Cryomancer): Mrazivý úder za $dmg poškození a ledový ward (+$shieldGain)!", "🔄 Auto-cast (Cryomancer): Frost Strike for $dmg damage and an ice ward (+$shieldGain)!");
      } else if (rank100Choice == 3) {
        int dmg = (magAtk * 8.0 * specAbilityDamageMod).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentRiftGuardianHp -= dmg;
        message = tr("🔄 Auto-cast (Chronomancer): Zvrácení času za $dmg poškození!", "🔄 Auto-cast (Chronomancer): Time Reversal for $dmg damage!");
      }
    } else if (heroClass == HeroClass.duelist) {
      if (rank100Choice == 1) {
        int dmg = (physAtk * 13.0 * specAbilityDamageMod).toInt();
        final hpRatio = currentRiftGuardianMaxHp > 0 ? currentRiftGuardianHp / currentRiftGuardianMaxHp : 1.0;
        if (hpRatio < 0.3) dmg = (dmg * 1.5).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentRiftGuardianHp -= dmg;
        _applyAbilityDot(dmg);
        message = tr("🔄 Auto-cast (Nemesis): Poprava za $dmg poškození${hpRatio < 0.3 ? ' (execute!)' : ''}!", "🔄 Auto-cast (Nemesis): Execution for $dmg damage${hpRatio < 0.3 ? ' (execute!)' : ''}!");
      } else if (rank100Choice == 2) {
        int dmg = (physAtk * 11.0 * specAbilityDamageMod).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentRiftGuardianHp -= dmg;
        hp = maxHp;
        message = tr("🔄 Auto-cast (Tanečník Čepelí): Tanec ostří za $dmg poškození a plné HP!", "🔄 Auto-cast (Tanečník Čepelí): Blade Dance for $dmg damage and full HP!");
      } else if (rank100Choice == 3) {
        int dmg = (physAtk * 12.0 * specAbilityDamageMod).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentRiftGuardianHp -= dmg;
        message = tr("🔄 Auto-cast (Bleskový Mistr): Bleskový úder za $dmg poškození!", "🔄 Auto-cast (Bleskový Mistr): Lightning Strike for $dmg damage!");
      }
    } else if (heroClass == HeroClass.monk) {
      if (rank100Choice == 1) {
        int dmg = (physAtk * 10.0 * specAbilityDamageMod).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentRiftGuardianHp -= dmg;
        _applyAbilityDot(dmg);
        message = tr("🔄 Auto-cast (Pěst tisíce bouří): Drtivý úder za $dmg poškození!", "🔄 Auto-cast (Pěst tisíce bouří): Crushing Blow for $dmg damage!");
      } else if (rank100Choice == 2) {
        int dmg = (physAtk * 6.0 * specAbilityDamageMod).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentRiftGuardianHp -= dmg;
        final shieldGain = (maxHp * 0.60 * specAbilitySustainMod).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
        hardcoreInvulnerableActive = true;
        message = tr("🔄 Auto-cast (Kamenný Strážce): $dmg poškození, obří štít (+$shieldGain) a nezranitelnost!", "🔄 Auto-cast (Kamenný Strážce): $dmg damage, a huge shield (+$shieldGain), and invulnerability!");
      } else if (rank100Choice == 3) {
        int dmg = (physAtk * 5.0 * specAbilityDamageMod).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentRiftGuardianHp -= dmg;
        hp = maxHp;
        heroEffects.removeWhere((e) => e.name == "Probuzení Ducha");
        heroEffects.add(StatusEffect(name: "Probuzení Ducha", description: "+15 % heal/absorb, -15 % dmg taken", duration: 3, isBuff: true));
        message = tr("🔄 Auto-cast (Probuzení Ducha): $dmg poškození, plné vyléčení HP a buff na 3 kola!", "🔄 Auto-cast (Probuzení Ducha): $dmg damage, full HP heal, and a buff for 3 rounds!");
      }
    }
  }

  // ===== ARÉNA =====
  ArenaLeague get arenaLeague => ArenaLeague.values[arenaLeagueIndex];

  // Strop bonusové síly soupeřů v Gladiátorské lize: +2 % za každých 100 ratingu, max +100 %
  // (dosaženo na ratingu 5000). Nad tímhle ratingem síla soupeřů dál neroste - stabilní vrchol.
  static const double arenaGladiatorMaxBonus = 1.0;

  // ===== SEZÓNY ARÉNY (kalendářní kvartál) =====
  static const List<String> arenaSeasonNames = [
    "Chaos", "Ohně", "Ledu", "Stínů", "Krve", "Bouře", "Přízraků", "Popela", "Zatmění", "Bezčasí",
  ];

  int computeCurrentArenaSeasonNumber() {
    final now = DateTime.now();
    final quarter = (now.month - 1) ~/ 3; // 0-3
    return (now.year - 2025) * 4 + quarter; // sezóna 0 = Q1 2025
  }

  String arenaSeasonNameFor(int seasonNumber) => arenaSeasonNames[seasonNumber % arenaSeasonNames.length];

  // Volá se při každém vstupu do Arény (generateArenaOpponent). Při přechodu do nového
  // kalendářního kvartálu měkce resetuje PROGRES (liga/úroveň/hvězdy/rating), ale NIKDY
  // nemaže historii už vybojovaných sezónních titulů (arenaSeasonTitleHistory) ani
  // achievementy/statistiky výher-proher - to je trvalá historie hráče.
  void _checkArenaSeason() {
    final current = computeCurrentArenaSeasonNumber();
    if (arenaCurrentSeasonNumber == -1) {
      arenaCurrentSeasonNumber = current; // první spuštění Arény - jen si zapamatuj sezónu
      return;
    }
    if (current != arenaCurrentSeasonNumber) {
      arenaCurrentSeasonNumber = current;
      arenaLeagueIndex = 0;
      arenaLevelIndex = 0;
      arenaStars = 0;
      arenaIsGladiator = false;
      arenaRating = 0;
      message = tr("🎊 Nová sezóna Arény začala: „${arenaSeasonNameFor(current)}“! Postup v ligách se resetoval, tvé vybojované tituly zůstávají.", "🎊 A new Arena season has begun: \u201e${arenaSeasonNameFor(current)}\u201c! League progress has reset, but your earned titles remain.");
    }
  }

  // Ruční reroll soupeře za Mince dobyvatele - dřív to šlo zdarma a bez omezení, což
  // podkopávalo risk/reward ligového postupu (šlo si "vyscroutit" nejsnazší matchup).
  // Cena roste s ligou, ať zůstane smysluplná i v pozdější hře.
  int get arenaRerollCost => 3 + arenaLeagueIndex;
  void rerollArenaOpponent() {
    if (conquerorCoins < arenaRerollCost) {
      message = tr("Nedostatek Mincí dobyvatele! Potřeba: $arenaRerollCost 🏅.", "Not enough Conqueror Coins! Needed: $arenaRerollCost 🏅.");
      notifyListeners();
      return;
    }
    conquerorCoins -= arenaRerollCost;
    generateArenaOpponent();
  }

  // Hráč potvrdí, že chce další soupeře - volá se z tlačítka v Aréně místo automatického
  // generování po výhře/prohře, ať má hráč vždy kontrolu nad tím, kdy jde do dalšího souboje.
  void confirmNextArenaFight() {
    arenaAwaitingConfirm = false;
    generateArenaOpponent();
  }

  void generateArenaOpponent() {
    _checkArenaSeason();
    final classes = HeroClass.values.where((c) => c != HeroClass.none).toList();
    final oppClass = classes[Random().nextInt(classes.length)];
    final oppSpec = 1 + Random().nextInt(3);
    final bool oppMagic = oppClass == HeroClass.mage || oppClass == HeroClass.healer;
    // Liga 1 = žádný bonus (soupeř stejně silný jako hrdina), +2 % za KAŽDOU další ligu (liga 2 =
    // ×1,02 ... liga 10 = ×1,18). Gladiátor navazuje jako "11. stupeň" = ×1,20 vstupně, a dál roste
    // +2 % za každých 100 ratingu, se stropem (arenaGladiatorMaxBonus = +100 %, na ratingu 5000),
    // ať i endgame progress jednou dojde na definitivní, stabilní vrchol místo nekonečné exploze čísel.
    final double gladiatorBonus = (0.02 * (arenaRating / 100)).clamp(0.0, arenaGladiatorMaxBonus);
    final double mult = arenaIsGladiator ? 1.20 + gladiatorBonus : 1 + 0.02 * arenaLeagueIndex;
    arenaOpponentClass = oppClass;
    arenaOpponentSpec = oppSpec;
    // HP soupeře vychází z hrdinova SKUTEČNÉHO poškození po redukci obranou soupeře (ne ze
    // surového útočného statu - to byla chyba: obrana soupeře (Def × mult) mohla hrdinovu
    // poškození sníst až 85 % (armorHardCap u fyzického dmg, ~42,5 % u magického), takže reálný
    // boj mohl trvat klidně 60-80 kol místo zamýšlených ~10-15. Def se teď počítá PŘED HP a HP
    // se dopočítá zpětně z toho, kolik hrdina PO redukci skutečně za kolo udá.
    final double heroAtkStat = (classIsMagicAttack ? magAtk : physAtk).toDouble().clamp(1, double.infinity);
    const double arenaTargetHits = 12.0;
    arenaOpponentDef = (armor * mult).toInt();
    arenaOpponentDefBase = arenaOpponentDef; // nezmenšená hodnota - viz arenaStallRounds/_resolveArenaCombatRound()
    final double heroMitigation = armorReduction(classIsMagicAttack ? DamageKind.magical : DamageKind.physical, value: arenaOpponentDef);
    final double effectiveDmgPerHit = heroAtkStat * (1 - heroMitigation);
    arenaOpponentMaxHp = (effectiveDmgPerHit * arenaTargetHits * mult).toInt();
    arenaOpponentHp = arenaOpponentMaxHp;
    // Soupeřův útok TAKY dopočítán zpětně ze stejného cíle (~12 zásahů), ne přímým zrcadlením
    // hrdinova magAtk/physAtk - jinak Attack roste s gearem (crit, zbraň, class multiplikátory)
    // rychleji než hrdinova výdrž (HP + Armor, navíc s tvrdým stropem mitigace 85 %/42,5 %), takže
    // by na lepším gearu soupeř zabíjel hrdinu za pár ran místo zamýšlených ~10-15 kol. Symetrický
    // modifikátor funguje na jakékoli úrovni gearu stejně, protože se pokaždé přepočítá znovu.
    final double heroMitigationIncoming = armorReduction(oppMagic ? DamageKind.magical : DamageKind.physical);
    // Hrdina navíc může zásah ÚPLNĚ uhnout (dodgeChance) nebo zablokovat (blockChance) - binární
    // negace celého zásahu, ne procentuální snížení jako Armor výše. Bez tohohle by soupeř dostal
    // zaplaceno jen za Armor mitigaci a v praxi hrdinu skoro nikdy neškrábl (odtud "127 výher,
    // 0 proher") - kalibrace teď počítá i s podílem ran, co hrdinu vůbec nezasáhnou.
    final double hitChance = (1 - dodgeChance - blockChance).clamp(0.15, 1.0);
    final double desiredDmgPerHitToHero = maxHp / arenaTargetHits;
    arenaOpponentAtk = (desiredDmgPerHitToHero / (1 - heroMitigationIncoming).clamp(0.05, 1.0) / hitChance * mult).toInt();
    // ===== GEAR ADVANTAGE — item level (ne live staty) rozhoduje, KDO v tomhle boji má navrch,
    // beze změny cíleného počtu kol (~10-15) z Osy 1 výše. Na přesně doporučeném gearu je soupeř
    // úmyslně o 20 % silnější (handicap za to, že hráč umí spelly/rotaci líp než AI bot) - lepší
    // gear než referenci tenhle handicap smaže a otočí ve tvůj prospěch. Počítá se z NEJLEPŠÍHO
    // možného gearu (celý inventář, ne jen nasazené kusy) - viz bestPossibleGearItemLevel.
    final double gearMult = arenaGearAdjustedMult;
    arenaOpponentMaxHp = (arenaOpponentMaxHp * gearMult).toInt();
    arenaOpponentHp = arenaOpponentMaxHp;
    arenaOpponentShield = 0;
    arenaOpponentAtk = (arenaOpponentAtk * gearMult).toInt();
    // Soupeř teď "používá spelly" (viz _resolveArenaCombatRound - arenaAbilityChance šance na
    // pojmenovanou schopnost místo obyčejného útoku, arenaAbilityDmgMult× silnější). Základní
    // ATK se dělí očekávaným váženým multiplikátorem, ať průměrné poškození za kolo zůstane na
    // stejné kalibraci ~12 zásahů (viz Osa 1 výše) - jinak by přidání spellů nechtěně navýšilo
    // celkový DPS soupeře nad zamýšlenou úroveň.
    arenaOpponentAtk = (arenaOpponentAtk / arenaExpectedAtkMult).round();
    // Balance požadavek: soupeř má dvojnásobné HP a o 10 % větší Atk oproti kalibraci výš
    // (Osa 1/2 nad tím zůstávají beze změny - tohle je čistý multiplikátor navrch).
    arenaOpponentMaxHp = (arenaOpponentMaxHp * 2.0).toInt();
    // Samostatný růst HP podle ligy (+5 %/liga, viz konverzace "větší růst HP enemy v rámci
    // každé ligy") - záměrně ODDĚLENÝ od `mult` výš (ten škáluje ATK/Def stejně jako dřív), ať
    // vyšší ligy znamenají delší, vytrvalostnější souboje, ne jen tvrdší rány. Gladiátorská liga
    // (arenaIsGladiator) roste dál přes gladiatorBonus zabudovaný v `mult`/HP výpočtu výš, tahle
    // přirážka se týká jen běžných lig 1-10 (arenaLeagueIndex).
    if (!arenaIsGladiator) {
      arenaOpponentMaxHp = (arenaOpponentMaxHp * (1 + 0.05 * arenaLeagueIndex)).toInt();
    } else {
      // Gladiátorská liga nemá arenaLeagueIndex škálování (je to jeden nejvyšší stupeň, ne
      // 1-10 jako běžné ligy) - dostává místo toho flat +50 % HP navrch.
      arenaOpponentMaxHp = (arenaOpponentMaxHp * 1.5).toInt();
    }
    arenaOpponentHp = arenaOpponentMaxHp;
    arenaOpponentAtk = (arenaOpponentAtk * 1.1).toInt();
    arenaOpponentIsMagic = oppMagic;
    arenaCombatRoundCount = 0;
    // BUG FIX (viz konverzace - "absorb se netestuje na 0 před každým novým soubojem"): tahle
    // funkce resetovala SOUPEŘŮV štít (arenaOpponentShield) a spoustu dalších bojových
    // proměnných, ale HRDINOVO vlastní hp/bonusShield vůbec nezmiňovala - takže zbytkový štít
    // (a teoreticky i HP) z PŘEDCHOZÍHO boje (Věž/Doupě/cokoliv) přetekl do nové arény.
    hp = maxHp;
    bonusShield = 0;
    specRelicUsedArena = false; specRelicStacks = 0; specRelicDuration = 0; enemyStunTurns = 0; _dkBloodEmergencyShieldUsed = false; _dkBloodEnemyDmgReductionPct = 0; _dkPlagueStackCount = 0; _relicArmorShredAmount = 0; _relicArmorShredDebuffName = null; _guardianCheatDeathUsed = false; _duelistDanceFirstProcUsed = false;
    huntersMarkStacks = 0;
    arcaneChargeStacks = 0;
    flowingChiStacks = 0;
    _resetResources();
    heroEffects.clear();
    enemyEffects.clear();
    final label = arenaIsGladiator ? "Gladiátorská liga (rating $arenaRating)" : "${arenaLeague.label} liga, úroveň ${arenaLevelIndex + 1}/5";
    message = tr("⚔️ Nový soupeř: ${heroClassLabel(oppClass)} (${specNameForClass(oppClass, oppSpec)}) - $label.", "⚔️ New opponent: ${heroClassLabel(oppClass)} (${specNameForClass(oppClass, oppSpec)}) - $label.");
    notifyListeners();
  }

  // Plná parita s fightRiftGuardian()/fight() - stejné Paragon 150 signature útoky, Hardcore
  // set bonusy, DK Krev/Soul Rune, Léčitel štít, lifesteal+cleanse synergie, Temnota synergie
  // i enrage (jako Věž) - žádné ořezané "arena-lite" verze mechanik.
  void fightArenaOpponent(bool isMagic) {
    if (isDead) return;
    if (arenaOpponentClass == null || arenaOpponentHp <= 0) return;

    int dealtDmg;
    bool isCrit = nextAttackGuaranteedCrit || Random().nextDouble() < critChance;
    if (nextAttackGuaranteedCrit) nextAttackGuaranteedCrit = false;
    final armorPen = runeEffect(RuneEffectType.armorPen);
    int effDef = armorPen > 0 ? (arenaOpponentDef * (1 - armorPen)).clamp(0, double.infinity).toInt() : arenaOpponentDef;

    if (heroClass == HeroClass.deathknight) {
      // Viz fight() pro plné vysvětlení - dmg = (physAtk+magAtk)/2, poměr fyz/mag se počítá
      // zvlášť z physAtk/magAtk (vždy nenulové, ne z raw talent bodů = 0/0 na levelu 1).
      final int totalAtk = physAtk + magAtk;
      final int combined = (totalAtk / 2).round();
      final double physShare = totalAtk > 0 ? physAtk / totalAtk : 0.5;
      final double magShare = totalAtk > 0 ? magAtk / totalAtk : 0.5;
      final int mitigated = max(0, combined - effDef);
      final int physPart = (mitigated * physShare * specDkPhysMod).toInt();
      final int magPart = (mitigated * magShare * specDkMagMod).toInt();
      dealtDmg = _minDmg(combined, physPart + magPart);
    } else if (hasParagon150 && heroClass == HeroClass.warrior) {
      final double rageRatio = maxRage > 0 ? (rage / maxRage).clamp(0.0, 1.0) : 0.0;
      int dmg = (physAtk + physAtk * rageRatio * 0.30).toInt();
      dealtDmg = _minDmg(dmg, dmg - effDef);
    } else if (hasParagon150 && heroClass == HeroClass.hunter) {
      int dmg = physAtk;
      dealtDmg = _minDmg(dmg, dmg - effDef);
      dealtDmg = (dealtDmg * (1 + huntersMarkStacks * huntersMarkPerStack)).toInt();
    } else if (hasParagon150 && heroClass == HeroClass.healer) {
      int dmg = magAtk;
      dealtDmg = _minDmg(dmg, dmg - effDef);
    } else if (hasParagon150 && heroClass == HeroClass.mage) {
      int dmg = magAtk;
      dealtDmg = _minDmg(dmg, dmg - effDef);
      dealtDmg = (dealtDmg * (1 + arcaneChargeStacks * arcaneChargePerStack)).toInt();
    } else if (hasParagon150 && heroClass == HeroClass.duelist) {
      int dmg = physAtk;
      dealtDmg = _minDmg(dmg, dmg - effDef);
    } else if (hasParagon150 && heroClass == HeroClass.monk) {
      int dmg = physAtk;
      dealtDmg = _minDmg(dmg, dmg - effDef);
      dealtDmg = (dealtDmg * (1 + flowingChiStacks * flowingChiPerStack)).toInt();
    } else {
      int dmg = (isMagic ? magAtk : physAtk);
      dealtDmg = _minDmg(dmg, dmg - effDef);
    }
    dealtDmg = (dealtDmg * basicAttackRoleMod).toInt();
    if (isCrit) dealtDmg = (dealtDmg * critDamageMultiplier).toInt();
    if (nextAttackDamageBoost) { dealtDmg = (dealtDmg * 1.1).toInt(); nextAttackDamageBoost = false; }
    final bossDmgBonus = runeEffect(RuneEffectType.bossDamage);
    if (bossDmgBonus > 0) dealtDmg = (dealtDmg * (1 + bossDmgBonus)).toInt();
    if (isCrit) message = tr("💥 Kritický zásah! Způsobeno $dealtDmg poškození.", "💥 Critical hit! Dealt $dealtDmg damage.");
    dealtDmg = _applyHardcoreSetRiftOffense(dealtDmg); // Hardcore set DMG role bonus
    dealtDmg = _applyGemOffense(dealtDmg, enemyHp: arenaOpponentHp, enemyMaxHp: arenaOpponentMaxHp, allowPoisonDot: false);
    // Absorb štít soupeře (viz _resolveArenaCombatRound) pohltí poškození dřív než HP.
    if (arenaOpponentShield > 0) {
      final absorbed = min(arenaOpponentShield, dealtDmg);
      arenaOpponentShield -= absorbed;
      dealtDmg -= absorbed;
      if (absorbed > 0) message += ' (🛡️ štít soupeře pohltil $absorbed dmg)';
    }
    arenaOpponentHp -= dealtDmg;
    _applyHardcoreSetRiftSustain(dealtDmg); // Hardcore set Tank/Heal role bonus

    if (heroClass == HeroClass.deathknight) _gainSoulRune();
    _applyKrevPassiveLifesteal(dealtDmg); // Krev: pasivní 5 % lifesteal ze základního útoku

    // ===== PARAGON 150 SIGNATURE ÚTOK — synergie po zásahu (stejná jako Věž/Lair/Rift) =====
    if (hasParagon150) {
      final critPrefix = isCrit ? '💥 Kritický zásah! ' : '';
      if (heroClass == HeroClass.warrior) {
        rage = (rage + 10).clamp(0, maxRage);
        message = tr("$critPrefix Hněv šampiona: $dealtDmg dmg (+10 Hněvu)!", "$critPrefix Hněv šampiona: $dealtDmg dmg (+10 Rage)!");
      } else if (heroClass == HeroClass.hunter) {
        huntersMarkStacks = (huntersMarkStacks + 1).clamp(0, huntersMarkMaxStacks);
        message = tr("$critPrefix Znamení lovce: $dealtDmg dmg (stack $huntersMarkStacks/$huntersMarkMaxStacks)!", "$critPrefix Znamení lovce: $dealtDmg dmg (stack $huntersMarkStacks/$huntersMarkMaxStacks)!");
      } else if (heroClass == HeroClass.deathknight) {
        final curseIdx = enemyEffects.indexWhere((e) => e.name == "Prokletí");
        if (curseIdx != -1) {
          final curse = enemyEffects[curseIdx];
          if (curse.duration < curseMaxDuration) curse.duration += 1;
          message = tr("$critPrefix Runová trhlina: $dealtDmg dmg (Prokletí prodlouženo na ${curse.duration} kol)!", "$critPrefix Runová trhlina: $dealtDmg dmg (Curse extended to ${curse.duration} rounds)!");
        } else {
          message = tr("$critPrefix Runová trhlina: $dealtDmg dmg.", "$critPrefix Runová trhlina: $dealtDmg dmg.");
        }
      } else if (heroClass == HeroClass.mage) {
        arcaneChargeStacks = (arcaneChargeStacks + arcaneChargeGainPerHit).clamp(0, arcaneChargeMaxStacks);
        message = tr("$critPrefix Arkánový výbuch: $dealtDmg dmg (stack $arcaneChargeStacks/$arcaneChargeMaxStacks)!", "$critPrefix Arkánový výbuch: $dealtDmg dmg (stack $arcaneChargeStacks/$arcaneChargeMaxStacks)!");
      } else if (heroClass == HeroClass.duelist) {
        heroEffects.removeWhere((e) => e.name == "Elegantní výpad");
        heroEffects.add(StatusEffect(name: "Elegantní výpad", description: "+10 % dodge", duration: 3, isBuff: true));
        message = tr("$critPrefix Elegantní výpad: $dealtDmg dmg (+10 % dodge na 3 kola)!", "$critPrefix Elegantní výpad: $dealtDmg dmg (+10% dodge for 3 rounds)!");
      } else if (heroClass == HeroClass.monk) {
        flowingChiStacks = (flowingChiStacks + 1).clamp(0, flowingChiMaxStacks);
        message = tr("$critPrefix Plynoucí Čchi: $dealtDmg dmg (stack $flowingChiStacks/$flowingChiMaxStacks)!", "$critPrefix Plynoucí Čchi: $dealtDmg dmg (stack $flowingChiStacks/$flowingChiMaxStacks)!");
      }
    }

    // Léčitel: základní útok vytváří absorb (štít) ve výši 15 % způsobeného poškození
    // (Paragon 150 "Trest Světla" navíc přidá 10 % dealtDmg jako self-heal.)
    if (heroClass == HeroClass.healer) {
      final absorb = (dealtDmg * 0.15).toInt();
      if (absorb > 0) {
        bonusShield += absorb;
        _applyShieldCap();
        final critPrefix = isCrit ? '💥 Kritický zásah! ' : '';
        if (hasParagon150) {
          final selfHeal = (dealtDmg * 0.10).toInt();
          hp = (hp + selfHeal).clamp(0, maxHp);
          message = tr("$critPrefix Trest Světla: $dealtDmg dmg → štít +$absorb, heal +$selfHeal.", "$critPrefix Trest Světla: $dealtDmg dmg → shield +$absorb, heal +$selfHeal.");
          _cleansePoisonSynergy();
          _healIntoShieldSynergy(selfHeal);
        } else {
          message = tr("$critPrefix Útok léčitele: $dealtDmg dmg → štít +$absorb.", "$critPrefix Healer's attack: $dealtDmg dmg → shield +$absorb.");
        }
      }
    }
    if (lifestealTurns > 0) {
      final heal = (dealtDmg * 0.2 * specLifestealMod).toInt();
      hp = (hp + heal).clamp(0, maxHp);
      _cleansePoisonSynergy();
      _healIntoShieldSynergy(heal);
    }
    final runeLs = runeEffect(RuneEffectType.lifesteal);
    if (runeLs > 0) {
      final lsHeal = (dealtDmg * runeLs * specLifestealMod).toInt();
      hp = (hp + lsHeal).clamp(0, maxHp);
      _cleansePoisonSynergy();
      _healIntoShieldSynergy(lsHeal);
    }
    _applyDarknessSynergy(dealtDmg);

    if (arenaOpponentHp > 0 && rollExtraAttack()) {
      message += tr(' ⚡ Extra Attack!', ' ⚡ Extra Attack!');
      _extraAttackInProgress = true;
      fightArenaOpponent(isMagic);
      _extraAttackInProgress = false;
      return;
    }
    _resolveArenaCombatRound();
  }

  void _resolveArenaCombatRound() {
    arenaCombatRoundCount++; // enrage: počítá se každá vyměněná rána, i uhnutá/blokovaná
    // Vyčerpávací debuff (od 11. kola): soupeřova Def klesá -1 %/kolo (jeho ekvivalent bloku) -
    // stejná "safe" mechanika jako hrdinův Dodge/Block/Heal/Absorb výše, jen z druhé strany.
    // Přepočítá se vždy znovu z NEZMENŠENÉ arenaOpponentDefBase, ať se to nekumuluje geometricky.
    if (arenaStallRounds > 0) {
      arenaOpponentDef = (arenaOpponentDefBase * (1 - 0.01 * arenaStallRounds)).clamp(0, arenaOpponentDefBase).toInt();
    }
    _checkHenryBuff();
    _checkLauferBuff();
    _checkFenwickBuff();
    _checkThorinBuff();
    _checkAnriBuff();
    _checkRawenBuff();
    _tickEffects((dot) => arenaOpponentHp -= dot);
    _regenResource();
    if (arenaOpponentHp <= 0) {
      _handleArenaWin();
      return;
    }
    // Hardcore set "Tank role" 6pc: útok soupeře zcela negován (jednorázově).
    if (hardcoreInvulnerableActive) {
      hardcoreInvulnerableActive = false;
      message = "🛡️✨ Hardcore set: " + tr("útok soupeře zcela odražen!", "the opponent's attack was completely deflected!");
      notifyListeners();
      return;
    }
    if (Random().nextDouble() < dodgeChance) {
      message = tr("✨ Úhyb! Vyhnul jsi se útoku soupeře.", "✨ Dodge! You evaded the opponent's attack.");
      _pushFx(FxKind.miss, FxSide.hero);
      hapticSelectionClick();
      notifyListeners();
      return;
    }
    // Soupeř "používá spelly" - arenaAbilityChance šance na pojmenovanou schopnost (tier1 dle
    // JEHO přiřazené třídy, viz spellVisualTier1) místo obyčejného útoku, NÁHODNĚ 2-4× silnější
    // (losuje se zvlášť pokaždé). arenaOpponentAtk je předem přebalancovaný na PRŮMĚR tohoto
    // rozsahu (viz generateArenaOpponent/arenaAbilityDmgMultAvg), ať se celkový očekávaný DPS
    // nezmění - jen přibude variace (občas tvrdý spell zásah) a jmenovaná zpráva v logu.
    final bool usesAbility = arenaOpponentClass != null && Random().nextDouble() < arenaAbilityChance;
    final double abilityMult = usesAbility ? (arenaAbilityDmgMultMin + Random().nextDouble() * (arenaAbilityDmgMultMax - arenaAbilityDmgMultMin)) : 1.0;
    int rawDamage = mitigateDamage((arenaOpponentAtk * abilityMult).toInt(), arenaOpponentIsMagic ? DamageKind.magical : DamageKind.physical);
    if (usesAbility) {
      final spellName = spellVisualTier1(arenaOpponentClass!).name;
      message = tr("⚡ ${heroClassLabel(arenaOpponentClass!)} použil $spellName! (${abilityMult.toStringAsFixed(1)}× dmg)", "⚡ ${heroClassLabel(arenaOpponentClass!)} used $spellName! (${abilityMult.toStringAsFixed(1)}× dmg)");
    }
    // ===== ENRAGE (nad 20. kolo) - stejná mechanika jako ve Věži =====
    if (arenaCombatRoundCount > 20) {
      final int n = arenaCombatRoundCount - 20;
      final double totalBonusPercent = n * (30 + (n - 1) * 5) / 2;
      final double enrageMult = 1 + totalBonusPercent / 100;
      rawDamage = (rawDamage * enrageMult).toInt();
      message += tr(" 🔥 ZUŘÍ! (+${totalBonusPercent.toInt()} % útoku)", " 🔥 ENRAGED! (+${totalBonusPercent.toInt()}% attack)");
    }
    // ===== SOUPEŘŮV ÚTOK MŮŽE NAVÍC DÁT ABSORB ŠTÍT NEBO LIFESTEAL - podle JEHO třídy =====
    // Stejná filozofie jako u hrdinových vlastních class pasivek (Léčitel štít z útoku, DK/Lovec
    // Démonů/Nekromant lifesteal). 25 % šance/kolo, štít/heal počítaný z rawDamage (než ho hrdina
    // případně uhne/zablokuje - viz dodge/block check výš, který už proběhl).
    if (arenaOpponentClass != null && rawDamage > 0 && Random().nextDouble() < 0.25) {
      final bool healLike = arenaOpponentClass == HeroClass.healer || arenaOpponentClass == HeroClass.monk || arenaOpponentClass == HeroClass.paladin || arenaOpponentClass == HeroClass.druid;
      final bool lifestealLike = arenaOpponentClass == HeroClass.deathknight || arenaOpponentClass == HeroClass.demonhunter || arenaOpponentClass == HeroClass.necromancer || arenaOpponentClass == HeroClass.warrior || arenaOpponentClass == HeroClass.duelist;
      if (healLike) {
        final shieldGain = (rawDamage * 0.30).round();
        arenaOpponentShield += shieldGain;
        message += tr(' 🛡️ ${heroClassLabel(arenaOpponentClass!)} soupeř získal $shieldGain štítu!', ' 🛡️ ${heroClassLabel(arenaOpponentClass!)} opponent gained $shieldGain shield!');
      } else if (lifestealLike) {
        final healGain = (rawDamage * 0.25).round();
        arenaOpponentHp = min(arenaOpponentMaxHp, arenaOpponentHp + healGain);
        message += tr(' 🩸 ${heroClassLabel(arenaOpponentClass!)} soupeř nasál $healGain HP!', ' 🩸 ${heroClassLabel(arenaOpponentClass!)} opponent drained $healGain HP!');
      }
    }
    final gemSaved = _applyIncomingDamage(rawDamage, (reflected) => arenaOpponentHp -= reflected);
    if (hp <= 0 && !gemSaved) {
      hp = 0;
      _handleArenaLoss();
      return;
    }
    notifyListeners();
  }

  // Odemkne achievement A rovnou zaznamená plný sezónní titul ("Rival od Chaos" /
  // "Nezničitelný od Chaos" / "God of Arena od Chaos") do trvalé historie.
  // _unlockAchievement() sama achievement udělí, sezónní formátování textu je specifické
  // pro Arénu, proto se řeší tady zvlášť.
  void _grantArenaTitle(String titleWord, AchievementId achievementId) {
    _unlockAchievement(achievementId);
    final fullTitle = "$titleWord od ${arenaSeasonNameFor(arenaCurrentSeasonNumber)}";
    if (!arenaSeasonTitleHistory.contains(fullTitle)) {
      arenaSeasonTitleHistory.add(fullTitle);
    }
  }

  void _handleArenaWin() {
    arenaWins++;
    String progressMsg;
    if (arenaIsGladiator) {
      // Gladiátor: endless rating, žádné hvězdy/ligy/postupy - jen roste nahoru bez stropu.
      final gain = 20 + (arenaRating ~/ 100); // vyšší rating = o trochu vyšší zisk, ať grind neztuhne
      final ratingBefore = arenaRating;
      arenaRating += gain;
      progressMsg = tr("Rating +$gain → $arenaRating", "Rating +$gain → $arenaRating");
      // Ratingové milníky - titul se udělí přesně jednou, když hráč práh PŘEKROČÍ.
      if (ratingBefore < 2500 && arenaRating >= 2500) {
        _grantArenaTitle(tr("Nezničitelný", "Indestructible"), AchievementId.arenaRating2500);
        progressMsg += tr(" 🏆 Dosažen rating 2500 - titul „Nezničitelný“!", " 🏆 Reached rating 2500 - title \u201eIndestructible\u201c!");
      }
      if (ratingBefore < 5000 && arenaRating >= 5000) {
        _grantArenaTitle("God of Arena", AchievementId.arenaRating5000);
        progressMsg += tr(" 👑 Dosažen rating 5000 - titul „God of Arena“ (strop síly soupeřů)!", " 👑 Reached rating 5000 - title \u201eGod of Arena\u201c (opponent strength cap)!");
      }
    } else {
      arenaStars++;
      if (arenaStars >= 5) {
        arenaStars = 0;
        arenaLevelIndex++;
        if (arenaLevelIndex >= 5) {
          // Celá liga (5/5 úrovní) dokončena - titul + achievement za TUHLE ligu.
          arenaLevelIndex = 0;
          final completedLeague = arenaLeague;
          _grantArenaTitle(completedLeague.titleWord, completedLeague.achievementId);
          // Číslo dokončené ligy 1 (Dřevo) .. 10 (Mýtická) - určuje škálování truhly níže.
          final int completedLeagueNumber = arenaLeagueIndex + 1;
          if (arenaLeagueIndex >= ArenaLeague.values.length - 1) {
            arenaIsGladiator = true;
            _unlockAchievement(AchievementId.arenaGladiator);
            progressMsg = tr("🎉🎉 VŠECHNY ligy dokončeny! Titul „${completedLeague.titleWord} od ${arenaSeasonNameFor(arenaCurrentSeasonNumber)}“ získán. Vstupuješ do endless Gladiátorské ligy!", "🎉🎉 ALL leagues completed! Title \u201e${completedLeague.titleWord} of ${arenaSeasonNameFor(arenaCurrentSeasonNumber)}\u201c earned. Entering the endless Gladiator league!");
          } else {
            arenaLeagueIndex++;
            progressMsg = tr("🎉 Liga ${completedLeague.label} dokončena! Titul „${completedLeague.titleWord} od ${arenaSeasonNameFor(arenaCurrentSeasonNumber)}“ získán. Postup do ligy ${arenaLeague.label}.", "🎉 League ${completedLeague.label} completed! Title \u201e${completedLeague.titleWord} of ${arenaSeasonNameFor(arenaCurrentSeasonNumber)}\u201c earned. Advancing to league ${arenaLeague.label}.");
          }
          _generateArenaLeagueChest(completedLeagueNumber);
        } else {
          progressMsg = tr("Úroveň ${arenaLevelIndex + 1}/5 v lize ${arenaLeague.label} (⭐0/5)", "Level ${arenaLevelIndex + 1}/5 in league ${arenaLeague.label} (⭐0/5)");
        }
      } else {
        progressMsg = tr("+1 ⭐ (${arenaStars}/5), úroveň ${arenaLevelIndex + 1}/5, liga ${arenaLeague.label}", "+1 ⭐ (${arenaStars}/5), level ${arenaLevelIndex + 1}/5, league ${arenaLeague.label}");
      }
    }
    // ×1,5 na výslovné přání - Mince dobyvatele se získávají rychleji ze všech zdrojů.
    final rewardCoins = ((arenaLeagueIndex + 1).clamp(1, 10) * 1.5).round();
    conquerorCoins += rewardCoins;
    tryDropCurrentSpecRelic();
    message = tr("🏆 Výhra! $progressMsg. +$rewardCoins 🏅 Mincí dobyvatele.", "🏆 Victory! $progressMsg. +$rewardCoins 🏅 Conqueror Coins.");
    hp = maxHp;
    heroEffects.clear();
    arenaOpponentClass = null;
    arenaAwaitingConfirm = true;
    notifyListeners();
  }

  void _handleArenaLoss() {
    arenaLosses++;
    if (arenaIsGladiator) {
      final loss = 15;
      arenaRating = (arenaRating - loss).clamp(0, 999999999);
      message = tr("💀 Prohra! Rating -$loss → $arenaRating.", "💀 Defeat! Rating -$loss → $arenaRating.");
    } else {
      arenaStars = (arenaStars - 1).clamp(0, 5);
      message = tr("💀 Prohra! -1 ⭐ (${arenaStars}/5), úroveň ${arenaLevelIndex + 1}/5, liga ${arenaLeague.label}.", "💀 Defeat! -1 ⭐ (${arenaStars}/5), level ${arenaLevelIndex + 1}/5, league ${arenaLeague.label}.");
    }
    hp = maxHp;
    heroEffects.clear();
    arenaOpponentClass = null;
    arenaAwaitingConfirm = true;
    notifyListeners();
  }

  // ===== ARÉNA: TRUHLA ZA DOKONČENÍ LIGY (loot box vzor Poklad-skřeta) =====
  // leagueNumber: 1 (Dřevo) .. 10 (Mýtická/vstup do Gladiátora) - lineární škálování odměny.
  void _generateArenaLeagueChest(int leagueNumber) {
    final n = leagueNumber.clamp(1, 10);
    arenaChestGold = 200 * n;
    arenaChestDust = 250 * n;
    arenaChestCrystals = (50 * n * kCrystalDropBonus).round();
    arenaChestCoins = (5 * n * 1.5).round(); // ×1,5 na výslovné přání - Mince dobyvatele rychleji ze všech zdrojů.
    final invCountBefore = inventory.length;
    // Šance na Hardcore set item roste s ligou (2 % za ligu, max 20 % v Mýtické/Gladiátorovi).
    _tryDropHardcoreSetPiece((0.02 * n).clamp(0.0, 0.20), powerLevel: n);
    _tryDropPredpekliSetPiece((0.02 * n).clamp(0.0, 0.20), powerLevel: n);
    _tryDropPekloSetPiece((0.02 * n).clamp(0.0, 0.20), powerLevel: n);
    arenaChestSetItemName = inventory.length > invCountBefore ? inventory.last.name : null;
    arenaChestPending = true;
  }

  void openArenaChest() {
    if (!arenaChestPending) return;
    gold += arenaChestGold;
    magicDust += arenaChestDust;
    crystals += arenaChestCrystals;
    conquerorCoins += arenaChestCoins;
    arenaChestLoot = [
      "+$arenaChestGold 🪙 " + tr("Zlato", "Gold"),
      "+$arenaChestDust ✨ " + tr("Magický prach", "Magic Dust"),
      "+$arenaChestCrystals 💎 " + tr("Krystaly", "Crystals"),
      "+$arenaChestCoins 🏅 " + tr("Mincí dobyvatele", "Conqueror Coins"),
      if (arenaChestSetItemName != null) "💠 " + tr("Hardcore set:", "Hardcore set:") + " $arenaChestSetItemName",
    ];
    arenaChestPending = false;
    arenaChestGold = 0;
    arenaChestDust = 0;
    arenaChestCrystals = 0;
    arenaChestCoins = 0;
    arenaChestSetItemName = null;
    message = tr("🏆 Truhla ligy otevřena!", "🏆 League chest opened!");
    notifyListeners();
  }

  void dismissArenaChestLoot() {
    arenaChestLoot = [];
    notifyListeners();
  }

  // ===== ARÉNA: schopnosti (zrcadlí Lair - viz useLairActiveAbility/_resolveLairCombatRound) =====
  // Balance: na rozdíl od dřívějška NEJSOU schopnosti v Aréně omezené na jedno použití za souboj -
  // dají se sesílat opakovaně, limitované jen zdrojem (Víra/Mana/atd.), stejně jako ve Věži/Lairu.
  void useArenaActiveAbility() {
    if (isDead || (arenaOpponentClass == null || arenaOpponentHp <= 0) || !hasAdvancedClass) return;
    if (!_spendResource(ability1Cost)) {
      message = tr("Nedostatek zdroje ($resourceName)! Potřeba: $ability1Cost, máš: $currentResourceValue.", "Not enough resource ($resourceName)! Needed: $ability1Cost, you have: $currentResourceValue.");
      notifyListeners();
      return;
    }
    _castTier1Ability('Aréna', arenaOpponentDef, () => arenaOpponentHp, () => arenaOpponentMaxHp, (d) => arenaOpponentHp -= d);
    _resolveArenaCombatRound();
  }

  void useArenaSecondAbility() {
    if (isDead || (arenaOpponentClass == null || arenaOpponentHp <= 0) || !hasUltimateClass) return;
    if (!_spendResource(ability2Cost)) {
      message = tr("Nedostatek zdroje ($resourceName)! Potřeba: $ability2Cost, máš: $currentResourceValue.", "Not enough resource ($resourceName)! Needed: $ability2Cost, you have: $currentResourceValue.");
      notifyListeners();
      return;
    }
    _castTier2Ability('Aréna', arenaOpponentDef, () => arenaOpponentHp, () => arenaOpponentMaxHp, (d) => arenaOpponentHp -= d);
    _resolveArenaCombatRound();
  }

