  void useArenaFourthAbility() {
    if (isDead || (arenaOpponentClass == null || arenaOpponentHp <= 0) || !hasRank100Class) return;
    if (!_spendResource(ability4Cost)) {
      message = tr("Nedostatek zdroje ($resourceName)! Potřeba: $ability4Cost, máš: $currentResourceValue.", "Not enough resource ($resourceName)! Needed: $ability4Cost, you have: $currentResourceValue.");
      notifyListeners();
      return;
    }
    _castTier4Ability('Aréna', arenaOpponentDef, () => arenaOpponentHp, () => arenaOpponentMaxHp, (d) => arenaOpponentHp -= d,
        () {});
    _resolveArenaCombatRound();
  }


  void fightRiftGuardian(bool isMagic) {
    if (isDead || !isInRift) return;
    if (riftFragmentPending) { message = tr("Nejdřív vyřeš nestabilitu Trhliny!", "Resolve the Rift's instability first!"); notifyListeners(); return; }

    // Poklad-skřet: šance na úhyb PŘED každým útokem hráče - pokud uhne, žádné poškození.
    // Odpočet kol běží bez ohledu na to, jestli útok trefil nebo ne.
    if (isTreasureGoblinFight && Random().nextDouble() < treasureGoblinDodgeChance) {
      message = tr("💨 Poklad-skřet mrštně uhnul!", "💨 The Treasure Goblin nimbly dodged!");
      treasureGoblinTurnsLeft--;
      if (treasureGoblinTurnsLeft <= 0) {
        _handleTreasureGoblinEscape();
        return;
      }
      _resolveRiftCombatRound();
      return;
    }

    int dealtDmg;
    bool isCrit = nextAttackGuaranteedCrit || Random().nextDouble() < critChance;
    if (nextAttackGuaranteedCrit) nextAttackGuaranteedCrit = false;
    final armorPen = runeEffect(RuneEffectType.armorPen);
    int effDef = armorPen > 0 ? (currentRiftGuardianDef * (1 - armorPen)).clamp(0, double.infinity).toInt() : currentRiftGuardianDef;

    if (heroClass == HeroClass.deathknight) {
      // Viz fight() pro plné vysvětlení - dmg = (physAtk+magAtk)/2, poměr fyz/mag se počítá
      // zvlášť z physAtk/magAtk (vždy nenulové, ne z raw talent bodů = 0/0 na levelu 1).
      final int totalAtk = physAtk + magAtk;
      final int combined = (totalAtk / 2).round();
      final double physShare = totalAtk > 0 ? physAtk / totalAtk : 0.5;
      final double magShare = totalAtk > 0 ? magAtk / totalAtk : 0.5;
      final int mitigated = max(0, combined - effDef);
      final int physPart = (mitigated * physShare * specDkPhysMod).toInt();
      final int magPart  = (mitigated * magShare * specDkMagMod).toInt();
      dealtDmg = _minDmg(combined, physPart + magPart);
    } else if (hasParagon150 && heroClass == HeroClass.warrior) {
      // Hněv šampiona: fyzický útok posílený aktuální hladinou Hněvu (až +30 % při plném Hněvu).
      final double rageRatio = maxRage > 0 ? (rage / maxRage).clamp(0.0, 1.0) : 0.0;
      int dmg = (physAtk + physAtk * rageRatio * 0.30).toInt();
      dealtDmg = _minDmg(dmg, dmg - effDef);
    } else if (hasParagon150 && heroClass == HeroClass.hunter) {
      // Znamení lovce: fyzický útok, stávající stacky (0-5) přidávají +3 % dmg/stack.
      int dmg = physAtk;
      dealtDmg = _minDmg(dmg, dmg - effDef);
      dealtDmg = (dealtDmg * (1 + huntersMarkStacks * huntersMarkPerStack)).toInt();
    } else if (hasParagon150 && heroClass == HeroClass.healer) {
      // Trest Světla: čistě magický útok (heal/shield synergie se řeší níže).
      int dmg = magAtk;
      dealtDmg = _minDmg(dmg, dmg - effDef);
    } else if (hasParagon150 && heroClass == HeroClass.mage) {
      // Arkánový výbuch: magický útok, existující Arcane Charge stacky (0-5) přidávají +4 % dmg/stack.
      int dmg = magAtk;
      dealtDmg = _minDmg(dmg, dmg - effDef);
      dealtDmg = (dealtDmg * (1 + arcaneChargeStacks * arcaneChargePerStack)).toInt();
    } else if (hasParagon150 && heroClass == HeroClass.duelist) {
      // Elegantní výpad: fyzický útok, uděluje dočasný dodge buff.
      int dmg = physAtk;
      dealtDmg = _minDmg(dmg, dmg - effDef);
    } else if (hasParagon150 && heroClass == HeroClass.monk) {
      // Plynoucí Čchi: fyzický útok, stávající stacky (0-5) přidávají +3 % dmg/stack.
      int dmg = physAtk;
      dealtDmg = _minDmg(dmg, dmg - effDef);
      dealtDmg = (dealtDmg * (1 + flowingChiStacks * flowingChiPerStack)).toInt();
    } else {
      int dmg = (isMagic ? magAtk : physAtk);
      dealtDmg = _minDmg(dmg, dmg - effDef);
    }
    dealtDmg = (dealtDmg * basicAttackRoleMod).toInt();
    if (isCrit) dealtDmg = (dealtDmg * critDamageMultiplier).toInt();
    if (nextAttackDamageBoost) { dealtDmg = (dealtDmg * 1.1).toInt(); nextAttackDamageBoost = false; }
    final bossDmgBonus = runeEffect(RuneEffectType.bossDamage);
    if (bossDmgBonus > 0) dealtDmg = (dealtDmg * (1 + bossDmgBonus)).toInt();
    dealtDmg = (dealtDmg * specializationBossDamageMod).toInt();
    if (isCrit) message = tr("💥 Kritický zásah! Způsobeno $dealtDmg poškození.", "💥 Critical hit! Dealt $dealtDmg damage.");
    dealtDmg = _applyHardcoreSetRiftOffense(dealtDmg); // Hardcore set DMG role bonus
    dealtDmg = _applyGemOffense(dealtDmg, enemyHp: currentRiftGuardianHp, enemyMaxHp: currentRiftGuardianMaxHp, allowPoisonDot: false);
    dealtDmg=(dealtDmg*riftMutatorDirectDamageMult).round();
    currentRiftGuardianHp -= dealtDmg;
    _applyHardcoreSetRiftSustain(dealtDmg); // Hardcore set Tank/Heal role bonus

    if (heroClass == HeroClass.deathknight) _gainSoulRune();
    _applyKrevPassiveLifesteal(dealtDmg); // Krev: pasivní 5 % lifesteal ze základního útoku

    // ===== PARAGON 150 SIGNATURE ÚTOK — synergie po zásahu (stejná jako Věž/Lair) =====
    if (hasParagon150) {
      final critPrefix = isCrit ? '💥 Kritický zásah! ' : '';
      if (heroClass == HeroClass.warrior) {
        rage = (rage + 10).clamp(0, maxRage);
        message = tr("$critPrefix Hněv šampiona: $dealtDmg dmg (+10 Hněvu)!", "$critPrefix Hněv šampiona: $dealtDmg dmg (+10 Rage)!");
      } else if (heroClass == HeroClass.hunter) {
        huntersMarkStacks = (huntersMarkStacks + 1).clamp(0, huntersMarkMaxStacks);
        message = tr("$critPrefix Znamení lovce: $dealtDmg dmg (stack $huntersMarkStacks/$huntersMarkMaxStacks)!", "$critPrefix Znamení lovce: $dealtDmg dmg (stack $huntersMarkStacks/$huntersMarkMaxStacks)!");
      } else if (heroClass == HeroClass.deathknight) {
        // Nyní funkční - auto-cast ability1 ("Prokletý úder") může v Rift Prokletí založit dřív
        // v tomtéž pokusu, takže je co prodlužovat (stejná logika jako Věž/Lair).
        final curseIdx = enemyEffects.indexWhere((e) => e.name == "Prokletí");
        if (curseIdx != -1) {
          final curse = enemyEffects[curseIdx];
          if (curse.duration < curseMaxDuration) curse.duration += 1;
          message = tr("$critPrefix Runová trhlina: $dealtDmg dmg (Prokletí prodlouženo na ${curse.duration} kol)!", "$critPrefix Runová trhlina: $dealtDmg dmg (Curse extended to ${curse.duration} rounds)!");
        } else {
          message = tr("$critPrefix Runová trhlina: $dealtDmg dmg.", "$critPrefix Runová trhlina: $dealtDmg dmg.");
        }
      } else if (heroClass == HeroClass.mage) {
        arcaneChargeStacks = (arcaneChargeStacks + arcaneChargeGainPerHit).clamp(0, arcaneChargeMaxStacks);
        message = tr("$critPrefix Arkánový výbuch: $dealtDmg dmg (stack $arcaneChargeStacks/$arcaneChargeMaxStacks)!", "$critPrefix Arkánový výbuch: $dealtDmg dmg (stack $arcaneChargeStacks/$arcaneChargeMaxStacks)!");
      } else if (heroClass == HeroClass.duelist) {
        heroEffects.removeWhere((e) => e.name == "Elegantní výpad");
        heroEffects.add(StatusEffect(name: "Elegantní výpad", description: "+10 % dodge", duration: 3, isBuff: true));
        message = tr("$critPrefix Elegantní výpad: $dealtDmg dmg (+10 % dodge na 3 kola)!", "$critPrefix Elegantní výpad: $dealtDmg dmg (+10% dodge for 3 rounds)!");
      } else if (heroClass == HeroClass.monk) {
        flowingChiStacks = (flowingChiStacks + 1).clamp(0, flowingChiMaxStacks);
        message = tr("$critPrefix Plynoucí Čchi: $dealtDmg dmg (stack $flowingChiStacks/$flowingChiMaxStacks)!", "$critPrefix Plynoucí Čchi: $dealtDmg dmg (stack $flowingChiStacks/$flowingChiMaxStacks)!");
      }
    }

    // Léčitel: základní útok vytváří absorb (štít) ve výši 15 % způsobeného poškození
    // (Paragon 150 "Trest Světla" navíc přidá 10 % dealtDmg jako self-heal.)
    if (heroClass == HeroClass.healer) {
      final absorb = (dealtDmg * 0.15).toInt();
      if (absorb > 0) {
        bonusShield += absorb;
        _applyShieldCap();
        final critPrefix = isCrit ? '💥 Kritický zásah! ' : '';
        if (hasParagon150) {
          final selfHeal = (dealtDmg * 0.10 * riftMutatorHealingMult).toInt();
          hp = (hp + selfHeal).clamp(0, maxHp);
          message = tr("$critPrefix Trest Světla: $dealtDmg dmg → štít +$absorb, heal +$selfHeal.", "$critPrefix Trest Světla: $dealtDmg dmg → shield +$absorb, heal +$selfHeal.");
          _cleansePoisonSynergy();
          _healIntoShieldSynergy(selfHeal);
        } else {
          message = tr("$critPrefix Útok léčitele: $dealtDmg dmg → štít +$absorb.", "$critPrefix Healer's attack: $dealtDmg dmg → shield +$absorb.");
        }
      }
    }
    if (lifestealTurns > 0) {
      final heal = (dealtDmg * 0.2 * specLifestealMod * riftMutatorLifestealMult).toInt();
      hp = (hp + heal).clamp(0, maxHp);
      _cleansePoisonSynergy();
      _healIntoShieldSynergy(heal);
    }
    final runeLs = runeEffect(RuneEffectType.lifesteal);
    if (runeLs > 0) {
      final lsHeal = (dealtDmg * runeLs * specLifestealMod * riftMutatorLifestealMult).toInt();
      hp = (hp + lsHeal).clamp(0, maxHp);
      _cleansePoisonSynergy();
      _healIntoShieldSynergy(lsHeal);
    }
    _applyDarknessSynergy(dealtDmg);

    if (isTreasureGoblinFight) {
      treasureGoblinCoinFxSeq++;
      treasureGoblinTurnsLeft--;
      if (currentRiftGuardianHp > 0 && treasureGoblinTurnsLeft <= 0) {
        _handleTreasureGoblinEscape();
        return;
      }
    }

    if (currentRiftGuardianHp > 0 && rollExtraAttack()) {
      message += tr(' ⚡ Extra Attack!', ' ⚡ Extra Attack!');
      _extraAttackInProgress = true;
      fightRiftGuardian(isMagic);
      _extraAttackInProgress = false;
      return;
    }
    _resolveRiftCombatRound();
  }

  void _handleTreasureGoblinEscape() {
    isTreasureGoblinFight = false;
    isInRift = false;
    hp = maxHp;
    heroEffects.clear();
    enemyEffects.clear();
    message = tr("💨 Poklad-skřet utekl s kořistí! Pokus je pryč, ale zkus to znovu příště.", "💨 The Treasure Goblin fled with the loot! The attempt is gone, but try again next time.");
    notifyListeners();
  }

  void _resolveRiftCombatRound() {
    riftCombatRoundCount++;
    // ===== TRHLINOVÁ NESTABILITA - vlastní mechanika jen pro skutečný souboj se Strážcem (ne
    // Poklad-skřet, který má svou vlastní "uteče za pár kol" tenzi). Roste +14/kolo; při dosažení
    // prahu se boj POZASTAVÍ (nepřítel tohle kolo neudeří) a hráč dostane binární volbu - viz
    // sealRiftFragment()/harnessRiftFragment(), zobrazené v UI (RiftScreen). Když nestabilita
    // dosáhne 100 dřív, než ji hráč vyřeší, Trhlina se zhroutí a bolestivě ho to zasáhne.
    if (!isTreasureGoblinFight) {
      riftInstability += 14;
      if (riftInstability >= 100) {
        riftInstability = 50; // zhroucení uleví tlaku napůl, ne úplně - tlak se vrací rychleji
        riftFragmentPending = false;
        riftCollapseFlashSeq++;
        final collapseDmg = (maxHp * 0.20).round();
        hp = max(0, hp - collapseDmg);
        message = tr("💥 Trhlina se ZHROUTILA! Nestabilita nebyla zvládnuta včas - $collapseDmg true dmg!", "💥 The Rift COLLAPSED! Instability wasn't managed in time - $collapseDmg true damage!");
        notifyListeners();
        if (hp <= 0) {
          isDead = true;
          isInRift = false;
          isTreasureGoblinFight = false;
          deathKiller = tr("Zhroucení Trhliny", "Rift Collapse");
          message += tr(" Zhroucení tě zabilo.", " The collapse killed you.");
          notifyListeners();
        }
        return;
      } else if (riftInstability >= riftFragmentThreshold) {
        riftFragmentThreshold += 40;
        riftFragmentPending = true;
        message = tr("🌀 Trhlina se chvěje... zvol si, jak zareagovat!", "🌀 The Rift trembles... choose how to react!");
        notifyListeners();
        return; // pozastaví kolo - strážce tohle kolo neudeří, čeká se na volbu hráče
      }
    }
    _checkHenryBuff();
    _checkLauferBuff();
    _checkFenwickBuff();
    _checkThorinBuff();
    _checkAnriBuff();
    _checkRawenBuff();
    _tickEffects((dot) => currentRiftGuardianHp -= (dot * riftMutatorDotMult).round());
    if(currentRiftMutator==RiftDailyMutator.unstableTime&&riftCombatRoundCount%4==0){if(activeAbilityCooldown>0)activeAbilityCooldown--;if(secondAbilityCooldown>0)secondAbilityCooldown--;if(thirdAbilityCooldown>0)thirdAbilityCooldown--;if(fourthAbilityCooldown>0)fourthAbilityCooldown--;}
    _regenResource();
    if (currentRiftGuardianHp <= 0) {
      _handleRiftGuardianDeath();
      notifyListeners();
      return;
    }
    // Hardcore set "Tank role" 6pc (Rift verze): útok strážce zcela negován (jednorázově).
    if (hardcoreInvulnerableActive) {
      hardcoreInvulnerableActive = false;
      message = "🛡️✨ Hardcore set: " + tr("útok strážce zcela odražen!", "the guardian's attack was completely deflected!");
      notifyListeners();
      return;
    }
    if (Random().nextDouble() < dodgeChance) {
      message = tr("✨ Úhyb! Vyhnul jsi se útoku strážce Trhliny.", "✨ Dodge! You evaded the Rift Guardian's attack.");
      _pushFx(FxKind.miss, FxSide.hero);
      hapticSelectionClick();
      notifyListeners();
      return;
    }
    int rawDamage = mitigateDamage(currentRiftGuardianAtk, DamageKind.physical);
    final gemSaved = _applyIncomingDamage(rawDamage, (reflected) => currentRiftGuardianHp -= reflected);
    if (hp <= 0 && !gemSaved) {
      isDead = true;
      isInRift = false;
      isTreasureGoblinFight = false;
      deathKiller = "Strážce Trhliny";
      message = tr("Padl jsi strážci Trhliny. Zkus to znovu zítra nebo posilni se ve Věži.", "You fell to the Rift Guardian. Try again tomorrow or grow stronger in the Tower.");
    }
    notifyListeners();
  }

  // ===== TRHLINOVÁ NESTABILITA: volby hráče (viz _resolveRiftCombatRound) =====
  // Uzavřít: bezpečnější, uleví nestabilitě víc, ale menší okamžitý dmg strážci.
  void sealRiftFragment() {
    if (!riftFragmentPending) return;
    riftFragmentPending = false;
    riftInstability = max(0, riftInstability - 30);
    final dmg = (currentRiftGuardianMaxHp * 0.12).round();
    currentRiftGuardianHp = max(0, currentRiftGuardianHp - dmg);
    message = tr("🔒 Trhlina uzavřena. Nestabilita klesla, strážce utrpěl $dmg dmg.", "🔒 Rift sealed. Instability dropped, the guardian took $dmg damage.");
    if (currentRiftGuardianHp <= 0) {
      _handleRiftGuardianDeath();
    }
    notifyListeners();
  }

  // Využít: riskantnější, nestabilita dál roste, ale výrazně větší okamžitý dmg strážci.
  void harnessRiftFragment() {
    if (!riftFragmentPending) return;
    riftFragmentPending = false;
    riftInstability = min(99, riftInstability + 20);
    final dmg = (currentRiftGuardianMaxHp * 0.22).round();
    currentRiftGuardianHp = max(0, currentRiftGuardianHp - dmg);
    message = tr("⚡ Energie Trhliny využita! Strážce utrpěl $dmg dmg, ale nestabilita dál roste.", "⚡ Rift energy harnessed! The guardian took $dmg damage, but instability keeps rising.");
    if (currentRiftGuardianHp <= 0) {
      _handleRiftGuardianDeath();
    }
    notifyListeners();
  }

  void _handleRiftGuardianDeath() {
    final rewardMult = curseRewardMultiplier*seasonRewardMult*riftMutatorRewardMult*riftDefenseRewardMult; addRelicXp(2); _rollRelicDrop(0.03); if(relicKillHeal)hp=(hp+(maxHp*0.10).round()).clamp(0,maxHp);

    if (isTreasureGoblinFight) {
      isTreasureGoblinFight = false;
      // Poklad-skřet nahrazuje tier fight, nepočítá se jako "zdolání tieru" (žádný rekord/quest progres) -
      // je to čistě bonusová vzácná odměna. Násobky výrazně vyšší, ať to stojí za to riziko utíkání.
      // Odměna se negeneruje rovnou - čeká v truhle, dokud ji hráč sám neotevře (openRiftChest).
      // Lineární škálování (ne exponenciální ×1,2 - to na tieru 50 dávalo ~7584× základ, viz
      // historie). 16/100/10 × tier přesně sedí na cílová čísla: tier 50 = 800g/5000 dust/500 krystalů.
      final int t = currentRiftTier.clamp(1, 999);
      riftChestGold = (16 * t * rewardMult).toInt();
      riftChestDust = (100 * t * rewardMult).toInt();
      riftChestCrystals = (10 * t * rewardMult * kCrystalDropBonus).round();
      final invCountBefore = inventory.length;
      // Hardcore set drop - 2 % z Poklad-skřeta v Rift. powerLevel stejné měřítko jako Tower/Lair
      // (/5, ne /10) - stejná oprava jako u Lairu výše.
      _tryDropHardcoreSetPiece(0.02, powerLevel: (currentRiftTier / 5).ceil());
      _tryDropPredpekliSetPiece(0.02, powerLevel: (currentRiftTier / 5).ceil());
      _tryDropPekloSetPiece(0.02, powerLevel: (currentRiftTier / 5).ceil());
      riftChestSetItemName = inventory.length > invCountBefore ? inventory.last.name : null;
      riftChestPending = true;
      isInRift = false;
      hp = maxHp;
      heroEffects.clear();
      enemyEffects.clear();
      message = tr("💰✨ Poklad-skřet poražen! Truhla s kořistí čeká na otevření.", "💰✨ The Treasure Goblin was defeated! A loot chest is waiting to be opened.");
      notifyListeners();
      return;
    }

    final isNewRecord = currentRiftTier > riftTier;
    if (isNewRecord) riftTier = currentRiftTier;
    riftClearsToday++;
    _checkDailyChronicleCoin(1, true);
    riftClearsThisWeek++;
    riftClearsThisMonth++;
    int rewardGold = (30 * currentRiftTier * rewardMult).toInt();
    int rewardDust = (40 * currentRiftTier * rewardMult).toInt();
    int rewardCrystals = (5 * currentRiftTier * rewardMult * kCrystalDropBonus).round();
    gold += rewardGold;
    magicDust += rewardDust;
    crystals += rewardCrystals;
    isInRift = false;
    hp = maxHp;
    heroEffects.clear();
    enemyEffects.clear();
    message = tr("Strážce Trhliny (tier $currentRiftTier) poražen! +$rewardGold 🪙 +$rewardDust Dust +$rewardCrystals 💎"
        "${isNewRecord ? ' — NOVÝ REKORD (tier $riftTier)!' : ''}",
        "Rift Guardian (tier $currentRiftTier) defeated! +$rewardGold 🪙 +$rewardDust Dust +$rewardCrystals 💎"
        "${isNewRecord ? ' — NEW RECORD (tier $riftTier)!' : ''}");
    _checkAchievements();
    _checkQuests();
  }

  void openRiftChest() {
    if (!riftChestPending) return;
    gold += riftChestGold;
    magicDust += riftChestDust;
    crystals += riftChestCrystals;
    riftChestLoot = [
      "+$riftChestGold 🪙 " + tr("Zlato", "Gold"),
      "+$riftChestDust ✨ " + tr("Magický prach", "Magic Dust"),
      "+$riftChestCrystals 💎 " + tr("Krystaly", "Crystals"),
      if (riftChestSetItemName != null) "💠 " + tr("Hardcore set:", "Hardcore set:") + " $riftChestSetItemName",
    ];
    riftChestPending = false;
    riftChestGold = 0;
    riftChestDust = 0;
    riftChestCrystals = 0;
    riftChestSetItemName = null;
    message = tr("💰 Truhla otevřena!", "💰 Chest opened!");
    notifyListeners();
  }

  void dismissRiftChestLoot() {
    riftChestLoot = [];
    notifyListeners();
  }

  void _checkHenryBuff() {
    if (activeCompanions.any((c) => c.name == "Henry")) {
      henryTurnCounter++;
      if (henryTurnCounter >= 150) {
        henryTurnCounter = 0;
        lifestealTurns += 10;
        heroEffects.add(StatusEffect(name: "Henryho Lifesteal", description: "+20% zotavení", duration: 10, isBuff: true));
        message = "Henry " + tr("seslal upíří lektvar! (Aktivován lifesteal na 10 tahů)", "cast a vampire potion! (Lifesteal activated for 10 turns)");
      }
    }
  }

  void _checkLauferBuff() {
    if (activeCompanions.any((c) => c.name == "Laufer")) {
      vexTurnCounter++;
      if (vexTurnCounter >= 100) {
        vexTurnCounter = 0;
        nextAttackGuaranteedCrit = true;
        message = "Laufer " + tr("připravil zteč! (Příští útok bude zaručený crit)", "prepared a charge! (The next attack is a guaranteed crit)");
      }
    }
  }

  void _checkFenwickBuff() {
    if (activeCompanions.any((c) => c.name == "Fenwick")) {
      fenwickTurnCounter++;
      if (fenwickTurnCounter >= 130) {
        fenwickTurnCounter = 0;
        final shieldGain = (maxHp * 0.20).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
        message = "Fenwick " + tr("seslal požehnání! (+$shieldGain absorb štítu)", "cast a blessing! (+$shieldGain absorb shield)");
      }
    }
  }

  void _checkThorinBuff() {
    if (activeCompanions.any((c) => c.name == "Thorin")) {
      thorinTurnCounter++;
      if (thorinTurnCounter >= 160) {
        thorinTurnCounter = 0;
        final shieldGain = (maxHp * 0.30).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
        message = "Thorin " + tr("postavil hradbu! (+$shieldGain absorb štítu)", "raised a wall! (+$shieldGain absorb shield)");
      }
    }
  }

  // Anri (Válečník): pasivně dává bonus k fyzickému Atk (viz companionPhysBonus, role .warrior)
  // + každý 10. útok nabije příští útok o +10 % dmg (viz nextAttackDamageBoost, konzumováno ve
  // fight()/fightLairBoss()/fightArenaOpponent()/fightSoulDemon()/rift a world boss útoku -
  // stejná místa jako nextAttackGuaranteedCrit od Laufera).
  void _checkAnriBuff() {
    if (activeCompanions.any((c) => c.name == "Anri")) {
      anriTurnCounter++;
      if (anriTurnCounter >= 10) {
        anriTurnCounter = 0;
        nextAttackDamageBoost = true;
        message = "Anri " + tr("zařvala bojový pokřik! (Příští útok +10 % dmg)", "let out a battle cry! (Next attack +10% dmg)");
      }
    }
  }

  void _checkRawenBuff() {
    if (activeCompanions.any((c) => c.name == "Rawen")) {
      rawenTurnCounter++;
      if (rawenTurnCounter >= 110) {
        rawenTurnCounter = 0;
        final healAmt = ((maxHp - hp) * 0.30).toInt().clamp(0, maxHp);
        hp = (hp + healAmt).clamp(0, maxHp);
        message = "Rawen " + tr("seslala léčivé kouzlo! (+$healAmt HP)", "cast a healing spell! (+$healAmt HP)");
      }
    }
  }

  // Cíl DoT se předává z konkrétního bojového režimu. Tím se zabrání tomu,
  // aby Arena nebo World Boss omylem odečítaly DoT z HP nepřítele ve Věži.
  void _tickEffects(void Function(int damage) dealEnemyDot) {
    // Cooldowny schopností se odečítají po kolech (jedna akce = jedno kolo), ne reálným časem -
    // hráč tak nikdy nečeká na hodiny, a třída s rychlejší regenerací zdroje (např. Energie)
    // z toho nemá žádnou výhodu navíc oproti pomalejší regeneraci (Mana/Hněv).
    if (activeAbilityCooldown > 0) activeAbilityCooldown--;
    if (secondAbilityCooldown > 0) secondAbilityCooldown--;
    if (thirdAbilityCooldown > 0) thirdAbilityCooldown--;
    if (fourthAbilityCooldown > 0) fourthAbilityCooldown--;
    if (healPotionCooldown > 0) healPotionCooldown--;
    // Snížení trvání efektů hrdiny + aplikace DoT poškození (Jed z prokletí Osudu apod.)
    for (var i = heroEffects.length - 1; i >= 0; i--) {
      if (heroEffects[i].dotDamage > 0) {
        // DoT tik nejde block/dodge (to dává smysl jen u diskrétního útoku), ale STÁLE ho má
        // nejdřív sežrat štít, stejně jako přímé zásahy v _applyIncomingDamage - BUG FIX: dřív
        // šlo DoT (Jed z curse) rovnou na hp a štít úplně obcházelo.
        int dmg = heroEffects[i].dotDamage;
        if (bonusShield > 0) {
          final effectiveShield = (bonusShield * curseDarknessMod).toInt(); // Temnota (curse): -30 % efektivní absorpce, stejně jako u přímého dmg
          final absorbed = dmg > effectiveShield ? effectiveShield : dmg;
          bonusShield -= absorbed;
          dmg -= absorbed;
          _lastKnownBonusShield = bonusShield; // sync pro _applyShieldCap() FX diffing
        }
        hp -= dmg;
      }
      heroEffects[i].duration--;
      if (heroEffects[i].duration <= 0) {
        heroEffects.removeAt(i);
      }
    }
    // Jed (curse): pokud efekt úplně vypršel (žádný "Jed (Prokletí)" už neběží), vynuluj stack počítadlo.
    if (activeCurse == CurseOfFate.poison && !heroEffects.any((e) => e.name == "Jed (Prokletí)")) {
      poisonStacks = 0;
    }
    // Snížení trvání efektů nepřítele + aplikace DoT poškození
    for (var i = enemyEffects.length - 1; i >= 0; i--) {
      if (enemyEffects[i].dotDamage > 0) {
        int dot = (enemyEffects[i].dotDamage * specializationDotDamageMod).round();
        // Deathknight – Prokletí DoT může kritit → dává soul runu
        if (heroClass == HeroClass.deathknight && enemyEffects[i].name == "Prokletí") {
          bool dotCrit = Random().nextDouble() < critChance;
          if (dotCrit) {
            dot = (dot * critDamageMultiplier).toInt();
            _gainSoulRune();
            message = tr("☠ Prokletí kriticky tiklo za $dot poškození!", "☠ The Curse critically ticked for $dot damage!");
          }
        }
        dealEnemyDot(dot);
      }
      enemyEffects[i].duration--;
      if (enemyEffects[i].duration <= 0) {
        // "Snižuje/sníží Armor" efekty napříč relicy (viz _castXSigil funkce) - vypršel debuff, co
        // Armor srazil, vrátit ho přesně zpět. Jen ve Věži (currentEnemyDef je Tower-specifické pole).
        _restoreRelicArmorShredIfMatches(enemyEffects[i].name);
        // Necrotic Apocalypse (Plague Sigil Lv90, viz _castDkSigil): vypršení DoT exploduje podle
        // nastřádaných stacků. _tickEffects je sdílená napříč Tower/Lair/Arena/WorldBoss/Rift/
        // Soul Demon, takže funguje všude, kde dealEnemyDot ukazuje na správné HP proměnné.
        if (enemyEffects[i].name == 'Nekrotická hniloba' && heroClass == HeroClass.deathknight &&
            isSpecRelicEquipped && currentSpecRelic.kind == SpecRelicKind.deathKnightPlagueSigil &&
            relicEffectActive(90) && _dkPlagueStackCount > 0) {
          // dotDamage už v sobě má stack multiplier zapečený (viz oprava v _castDkSigil), takže
          // se tu násobí jen fixním "explozním" koeficientem, ne stack countem znovu.
          final apocDmg = enemyEffects[i].dotDamage * 2;
          dealEnemyDot(apocDmg);
          _pushFx(FxKind.explosionDamage, FxSide.enemy, value: apocDmg, burstKind: RelicBurstKind.plagueApocalypse);
          message = tr("☣️💥 Necrotic Apocalypse: $apocDmg poškození!", "☣️💥 Necrotic Apocalypse: $apocDmg damage!");
          _dkPlagueStackCount = 0;
        }
        // Inferno (Fire Tome Lv90, viz _castMageSigil): vypršení Hoření exploduje a obnoví část Žáru.
        if (enemyEffects[i].name == 'Hoření' && heroClass == HeroClass.mage &&
            isSpecRelicEquipped && currentSpecRelic.kind == SpecRelicKind.mageFireTome && relicEffectActive(90)) {
          final infernoDmg = enemyEffects[i].dotDamage * 2;
          dealEnemyDot(infernoDmg);
          _pushFx(FxKind.explosionDamage, FxSide.enemy, value: infernoDmg, burstKind: RelicBurstKind.flashover);
          specRelicStacks = min(5, specRelicStacks + 2);
          message = tr("🔥💥 Inferno: $infernoDmg poškození!", "🔥💥 Inferno: $infernoDmg damage!");
        }
        // Hvězdný pád (Balance Totem Lv90, viz _castDruidSigil): vypršení Astrálního rozkladu
        // exploduje podle poškození, které by ještě zbývalo (dotDamage × zbývající kola).
        if (enemyEffects[i].name == 'Astrální rozklad' && heroClass == HeroClass.druid &&
            isSpecRelicEquipped && currentSpecRelic.kind == SpecRelicKind.druidBalanceTotem && relicEffectActive(90)) {
          final starfallDmg = enemyEffects[i].dotDamage * 2;
          dealEnemyDot(starfallDmg);
          _pushFx(FxKind.explosionDamage, FxSide.enemy, value: starfallDmg, burstKind: RelicBurstKind.starfall);
          message = tr("🌌💥 Hvězdný pád: $starfallDmg poškození!", "🌌💥 Starfall: $starfallDmg damage!");
        }
        // Morový pád (Plague Tome Lv90, viz _castNecromancerSigil): vypršení Morové kletby exploduje.
        if (enemyEffects[i].name == 'Morová kletba' && heroClass == HeroClass.necromancer &&
            isSpecRelicEquipped && currentSpecRelic.kind == SpecRelicKind.necromancerPlagueTome && relicEffectActive(90)) {
          final plagueFallDmg = enemyEffects[i].dotDamage * 2;
          dealEnemyDot(plagueFallDmg);
          _pushFx(FxKind.explosionDamage, FxSide.enemy, value: plagueFallDmg, burstKind: RelicBurstKind.plagueFall);
          message = tr("☣️💥 Morový pád: $plagueFallDmg poškození!", "☣️💥 Plague Fall: $plagueFallDmg damage!");
        }
        // Propastný pád (Shadow Glaive Lv90, viz _castDemonHunterSigil): vypršení Fel ohně exploduje.
        if (enemyEffects[i].name == 'Fel oheň' && heroClass == HeroClass.demonhunter &&
            isSpecRelicEquipped && currentSpecRelic.kind == SpecRelicKind.demonHunterShadowGlaive && relicEffectActive(90)) {
          final abyssFallDmg = enemyEffects[i].dotDamage * 2;
          dealEnemyDot(abyssFallDmg);
          _pushFx(FxKind.explosionDamage, FxSide.enemy, value: abyssFallDmg, burstKind: RelicBurstKind.abyssFall);
          message = tr("👁️💥 Propastný pád: $abyssFallDmg poškození!", "👁️💥 Abyss Fall: $abyssFallDmg damage!");
        }
        enemyEffects.removeAt(i);
      }
    }
    if (lifestealTurns > 0) lifestealTurns--;
  }

  // ===== DEATHKNIGHT: Vysátí duše – pasivní zásobník soul run =====
  // Triggruje při: útoku, obdržení dmg, zabití nepřítele, DoT critu.
  // Při 7 runách → příští aktivní spell = 3× efekt.
  void _gainSoulRune() {
    if (heroClass != HeroClass.deathknight) return;
    if (nextSpellTriple) return; // Již aktivní
    soulRunes = (soulRunes + 1).clamp(0, 7);
    if (soulRunes >= 7) {
      soulRunes = 0; // Reset okamžitě při triggeru
      nextSpellTriple = true;
      message += "☠ " + tr("Vysátí duše: PŘÍŠTÍ SPELL = 3× efekt!", "Soul Drain: NEXT SPELL = 3× effect!");
    }
  }

  // Vyřeší jedno kolo boje v Lair (protiúder bosse, tik efektů, regenerace zdroje).
  // Volá se jak po základním útoku, tak po seslání schopnosti - použití schopnosti = jedno kolo.
  void _resolveLairCombatRound() {
    lairCombatRoundCount++;
    // ===== Nepřátelská schopnost - VŽDY na 2. kole (viz enemyAbilityEffects, sdílené s Věží -
    // Doupě bosse losuje bosse ze stejného 100-položkového poolu přes getBossDetails()). =====
    double abilityDamageBonusPct = 0;
    bool abilityGuaranteedCrit = false;
    double abilityBossLifestealPct = 0;
    if (lairCombatRoundCount == 2) {
      final def = enemyAbilityEffects[currentLairBossAbility];
      if (def != null) {
        switch (def.kind) {
          case EnemyAbilityKind.statDebuff:
            heroEffects.add(StatusEffect.statDebuff(name: "Schopnost: $currentLairBossAbility", description: tr("$currentLairBossName použil svou schopnost.", "$currentLairBossName used its ability."), duration: def.duration, mods: def.mods));
            _pushFx(FxKind.statusApplied, FxSide.hero, label: currentLairBossAbility, spellFxKind: SpellFxKind.lairBossCurse);
            break;
          case EnemyAbilityKind.stackingDebuff:
            heroEffects.removeWhere((e) => e.name == "Schopnost: $currentLairBossAbility");
            heroEffects.add(StatusEffect.statDebuff(name: "Schopnost: $currentLairBossAbility", description: tr("$currentLairBossName použil svou schopnost (stackuje se).", "$currentLairBossName used its ability (stacks)."), duration: def.duration, mods: def.mods));
            _pushFx(FxKind.statusApplied, FxSide.hero, label: currentLairBossAbility, spellFxKind: SpellFxKind.lairBossCurse);
            break;
          case EnemyAbilityKind.dot:
            heroEffects.add(StatusEffect(name: "Schopnost: $currentLairBossAbility", description: tr("$currentLairBossName tě otrávil/zapálil.", "$currentLairBossName poisoned/burned you."), duration: def.duration, isBuff: false, dotDamage: (maxHp * def.amount).round()));
            _pushFx(FxKind.statusApplied, FxSide.hero, label: currentLairBossAbility, spellFxKind: SpellFxKind.lairBossPlague);
            break;
          case EnemyAbilityKind.trueDamage:
            final trueDmg = (maxHp * def.amount).round();
            hp = max(0, hp - trueDmg);
            _pushFx(FxKind.normalDamage, FxSide.hero, value: trueDmg, spellFxKind: SpellFxKind.lairBossStrike);
            break;
          case EnemyAbilityKind.ignoreArmor:
            abilityDamageBonusPct += def.amount;
            _pushFx(FxKind.statusApplied, FxSide.hero, label: currentLairBossAbility, spellFxKind: SpellFxKind.lairBossStrike);
            break;
          case EnemyAbilityKind.ignoreBlockDodge:
            heroEffects.add(StatusEffect.statDebuff(name: "Schopnost: $currentLairBossAbility", description: tr("Tenhle útok nejde blokovat ani uhnout.", "This attack can't be blocked or dodged."), duration: 1, mods: {'dodge': -1.0, 'block': -1.0}));
            _pushFx(FxKind.statusApplied, FxSide.hero, label: currentLairBossAbility, spellFxKind: SpellFxKind.lairBossStrike);
            break;
          case EnemyAbilityKind.guaranteedCrit:
            abilityGuaranteedCrit = true;
            _pushFx(FxKind.statusApplied, FxSide.hero, label: currentLairBossAbility, spellFxKind: SpellFxKind.lairBossStrike);
            break;
          case EnemyAbilityKind.doubleAttack:
            abilityDamageBonusPct += 1.0;
            _pushFx(FxKind.statusApplied, FxSide.hero, label: currentLairBossAbility, spellFxKind: SpellFxKind.lairBossStrike);
            break;
          case EnemyAbilityKind.stun:
            heroStunTurns += def.duration;
            _pushFx(FxKind.stunned, FxSide.hero, spellFxKind: SpellFxKind.lairBossBind);
            break;
          case EnemyAbilityKind.blockSpell:
            heroSpellBlockTurns += def.duration;
            _pushFx(FxKind.statusApplied, FxSide.hero, label: currentLairBossAbility, spellFxKind: SpellFxKind.lairBossBind);
            break;
          case EnemyAbilityKind.bossBuff:
            currentLairBossAtk = (currentLairBossAtk * (1 + def.amount)).round();
            enemyEffects.add(StatusEffect(name: "Schopnost: $currentLairBossAbility", description: tr("Posílený útok.", "Empowered attack."), duration: def.duration, isBuff: true));
            _pushFx(FxKind.statusApplied, FxSide.enemy, label: currentLairBossAbility, spellFxKind: SpellFxKind.lairBossEmpower);
            break;
          case EnemyAbilityKind.bossArmorBuff:
            currentLairBossDef = (currentLairBossDef * (1 + def.amount)).round();
            enemyEffects.add(StatusEffect(name: "Schopnost: $currentLairBossAbility", description: tr("Posílená obrana.", "Empowered defense."), duration: def.duration, isBuff: true));
            _pushFx(FxKind.statusApplied, FxSide.enemy, label: currentLairBossAbility, spellFxKind: SpellFxKind.lairBossEmpower);
            break;
          case EnemyAbilityKind.bossShield:
            // Doupě bosse nemá vlastní shield stat u bosse (na rozdíl od Věže) - nahrazeno healem.
            final bossShieldGain = min(currentLairBossMaxHp - currentLairBossHp, (currentLairBossMaxHp * def.amount).round());
            currentLairBossHp = min(currentLairBossMaxHp, currentLairBossHp + (currentLairBossMaxHp * def.amount).round());
            _pushFx(FxKind.shieldGained, FxSide.enemy, value: bossShieldGain, spellFxKind: SpellFxKind.lairBossEmpower);
            break;
          case EnemyAbilityKind.bossHeal:
            final bossHealGain = min(currentLairBossMaxHp - currentLairBossHp, (currentLairBossMaxHp * def.amount).round());
            currentLairBossHp = min(currentLairBossMaxHp, currentLairBossHp + (currentLairBossMaxHp * def.amount).round());
            _pushFx(FxKind.shieldGained, FxSide.enemy, value: bossHealGain, spellFxKind: SpellFxKind.lairBossEmpower);
            break;
          case EnemyAbilityKind.bossLifesteal:
            abilityBossLifestealPct = def.amount;
            _pushFx(FxKind.statusApplied, FxSide.enemy, label: currentLairBossAbility, spellFxKind: SpellFxKind.lairBossEmpower);
            break;
          case EnemyAbilityKind.resourceDrain:
            _drainResourcePct(def.amount);
            _pushFx(FxKind.statusApplied, FxSide.hero, label: currentLairBossAbility, spellFxKind: SpellFxKind.lairBossDrain);
            break;
          case EnemyAbilityKind.goldDrain:
            gold = max(0, (gold * (1 - def.amount)).round());
            _pushFx(FxKind.statusApplied, FxSide.hero, label: currentLairBossAbility, spellFxKind: SpellFxKind.lairBossDrain);
            break;
          case EnemyAbilityKind.cancelShield:
            bonusShield = 0;
            _pushFx(FxKind.statusApplied, FxSide.hero, label: currentLairBossAbility, spellFxKind: SpellFxKind.lairBossCurse);
            break;
          case EnemyAbilityKind.cancelBuff:
            final activeBuffs = heroEffects.where((e) => e.isBuff).toList();
            if (activeBuffs.isNotEmpty) heroEffects.remove(activeBuffs.first);
            _pushFx(FxKind.statusApplied, FxSide.hero, label: currentLairBossAbility, spellFxKind: SpellFxKind.lairBossCurse);
            break;
        }
        message = tr("⚔️ $currentLairBossName použil schopnost: $currentLairBossAbility!", "⚔️ $currentLairBossName used its ability: $currentLairBossAbility!");
        notifyListeners();
      }
    }
    _checkHenryBuff();
    _checkLauferBuff();
    _checkFenwickBuff();
    _checkThorinBuff();
    _checkAnriBuff();
    _checkRawenBuff();
    _tickEffects((dot) => currentLairBossHp -= dot);
    _regenResource();
    if (currentLairBossHp <= 0) {
      _handleLairBossDeath();
      notifyListeners();
      return;
    }
    // Hardcore set "Nezdolná Pevnost" 6pc: útok bosse zcela negován (jednorázově).
    if (hardcoreInvulnerableActive) {
      hardcoreInvulnerableActive = false;
      message = "🛡️✨ Nezdolná Pevnost: " + tr("útok bosse zcela odražen!", "the boss's attack was completely deflected!");
      notifyListeners();
      return;
    }
    // Úhyb: pokud uspěje, hrdina zcela vyhne útoku bosse.
    if (Random().nextDouble() < dodgeChance) {
      message = tr("✨ Úhyb! Vyhnul jsi se útoku bosse.", "✨ Dodge! You evaded the boss's attack.");
      _pushFx(FxKind.miss, FxSide.hero);
      hapticSelectionClick();
      // Duelist Grácie: úspěšný úhyb spustí counter-attack.
      if (hasGraceCounter) {
        final counterDmg = (physAtk * 0.5).toInt();
        currentLairBossHp -= counterDmg;
        message += tr(" Counter-attack za $counterDmg dmg!", " Counter-attack for $counterDmg dmg!");
      }
      notifyListeners();
      return;
    }
    final effectiveHeroArmor = (armor * (1.0 - lairArmorIgnore)).round();
    int rawDamage = mitigateDamage(currentLairBossAtk, DamageKind.physical, value: effectiveHeroArmor);
    if (abilityDamageBonusPct > 0) rawDamage = (rawDamage * (1 + abilityDamageBonusPct)).round();
    // Minimální poškození lair bosse: 10 % hráčova max HP (dvojnásobek Věže - lair je tvrdší
    // capstone obsah). Enrage/Krvavá lázeň níž ještě může jít nad tenhle floor.
    final int lairMinDmg = (maxHp * 0.10).toInt();
    if (rawDamage < lairMinDmg) rawDamage = lairMinDmg;
    rawDamage = (rawDamage * lairEnrageDamageMult).round();
    // Krvavá lázeň (curse): čím méně HP má boss, tím větší damage dává (až +100 % při umírání).
    if (activeCurse == CurseOfFate.bloodbath && currentLairBossMaxHp > 0) {
      final missingRatio = (1.0 - currentLairBossHp / currentLairBossMaxHp).clamp(0.0, 1.0);
      rawDamage = (rawDamage * (1 + missingRatio)).toInt();
    }
    // Boss crit: boss s určitou šancí (podle obtížnosti) dá kritický zásah (+50 % dmg).
    // abilityGuaranteedCrit (schopnost na 2. kole) vynutí crit bez ohledu na roll.
    bool bossCrit = abilityGuaranteedCrit || Random().nextDouble() < lairBossSpecialChance;
    if (bossCrit) {
      rawDamage = (rawDamage * 1.5).toInt();
      message = tr("💥 $currentLairBossName zasáhl kriticky!", "💥 $currentLairBossName landed a critical hit!");
    }
    int lairFinalDmg = 0;
    final gemSaved = _applyIncomingDamage(rawDamage, (reflected) => currentLairBossHp -= reflected, onFinalDamage: (d) => lairFinalDmg = d);
    if (abilityBossLifestealPct > 0 && lairFinalDmg > 0) {
      currentLairBossHp = min(currentLairBossMaxHp, currentLairBossHp + (lairFinalDmg * abilityBossLifestealPct).round());
    }
    if (currentLairBossHp <= 0) {
      _handleLairBossDeath();
      notifyListeners();
      return;
    }
    if (hp <= 0 && !gemSaved) {
      if (phoenixChargeActive) {
        phoenixChargeActive = false;
        hp = (maxHp * 0.5).toInt();
        message = "Elixír Fénixe " + tr("tě zachránil před smrtí! Obnoveno 50% HP.", "saved you from death! 50% HP restored.");
      } else {
        isInLair = false;
        heroEffects.clear();
        enemyEffects.clear();
        _triggerDeath(tr("Zemřel jsi v Doupěti Bosse ($currentLairBossName)!", "You died in the Lair Boss chamber ($currentLairBossName)!"), killer: currentLairBossName);
        return;
      }
    }
    notifyListeners();
  }

  void fightLairBoss(bool isMagic) {
    if (isDead || !isInLair) return;

    // Boss dodge: boss se s určitou šancí (podle obtížnosti) zcela vyhne útoku, žádné poškození.
    if (Random().nextDouble() < lairBossSpecialChance) {
      message = tr("💨 $currentLairBossName uhnul tvému útoku!", "💨 $currentLairBossName dodged your attack!");
      notifyListeners();
      return;
    }

    int dealtDmg;
    bool isCrit = nextAttackGuaranteedCrit || Random().nextDouble() < critChance;
    if (nextAttackGuaranteedCrit) nextAttackGuaranteedCrit = false;

    if (heroClass == HeroClass.deathknight) {
      // Hybridní Lair útok: stejná logika jako fight() - dmg = (physAtk+magAtk)/2, poměr fyz/mag
      // se počítá zvlášť z physAtk/magAtk (vždy nenulové, ne z raw talent bodů = 0/0 na levelu 1).
      final int totalAtk = physAtk + magAtk;
      final int combined = (totalAtk / 2).round();
      final double physShare = totalAtk > 0 ? physAtk / totalAtk : 0.5;
      final double magShare = totalAtk > 0 ? magAtk / totalAtk : 0.5;
      final armorPen = runeEffect(RuneEffectType.armorPen);
      final int effDef = armorPen > 0 ? (currentLairBossDef * (1 - armorPen)).clamp(0, double.infinity).toInt() : currentLairBossDef;
      // Specializace: Mráz posiluje fyzickou složku, Nákaza magickou/DoT složku (viz specDkPhysMod/specDkMagMod).
      final int mitigated = max(0, combined - effDef);
      final int physPart = (mitigated * physShare * specDkPhysMod).toInt();
      final int magPart  = (mitigated * magShare * specDkMagMod).toInt();
      dealtDmg = _minDmg(combined, physPart + magPart);
    } else if (hasParagon150 && heroClass == HeroClass.warrior) {
      // Hněv šampiona: fyzický útok posílený aktuální hladinou Hněvu (až +30 % při plném Hněvu).
      final armorPen = runeEffect(RuneEffectType.armorPen);
      int effDef = armorPen > 0 ? (currentLairBossDef * (1 - armorPen)).clamp(0, double.infinity).toInt() : currentLairBossDef;
      final double rageRatio = maxRage > 0 ? (rage / maxRage).clamp(0.0, 1.0) : 0.0;
      int dmg = (physAtk + physAtk * rageRatio * 0.30).toInt();
      dealtDmg = _minDmg(dmg, dmg - effDef);
    } else if (hasParagon150 && heroClass == HeroClass.hunter) {
      // Znamení lovce: fyzický útok, stávající stacky (0-5) přidávají +3 % dmg/stack.
      final armorPen = runeEffect(RuneEffectType.armorPen);
      int effDef = armorPen > 0 ? (currentLairBossDef * (1 - armorPen)).clamp(0, double.infinity).toInt() : currentLairBossDef;
      int dmg = physAtk;
      dealtDmg = _minDmg(dmg, dmg - effDef);
      dealtDmg = (dealtDmg * (1 + huntersMarkStacks * huntersMarkPerStack)).toInt();
    } else if (hasParagon150 && heroClass == HeroClass.healer) {
      // Trest Světla: čistě magický útok (heal/shield synergie se řeší níže).
      final armorPen = runeEffect(RuneEffectType.armorPen);
      int effDef = armorPen > 0 ? (currentLairBossDef * (1 - armorPen)).clamp(0, double.infinity).toInt() : currentLairBossDef;
      int dmg = magAtk;
      dealtDmg = _minDmg(dmg, dmg - effDef);
    } else if (hasParagon150 && heroClass == HeroClass.mage) {
      // Arkánový výbuch: magický útok, existující Arcane Charge stacky (0-5) přidávají +4 % dmg/stack.
      final armorPen = runeEffect(RuneEffectType.armorPen);
      int effDef = armorPen > 0 ? (currentLairBossDef * (1 - armorPen)).clamp(0, double.infinity).toInt() : currentLairBossDef;
      int dmg = magAtk;
      dealtDmg = _minDmg(dmg, dmg - effDef);
      dealtDmg = (dealtDmg * (1 + arcaneChargeStacks * arcaneChargePerStack)).toInt();
    } else if (hasParagon150 && heroClass == HeroClass.duelist) {
      // Elegantní výpad: fyzický útok, uděluje dočasný dodge buff (a u Grácie counter-attack šanci).
      final armorPen = runeEffect(RuneEffectType.armorPen);
      int effDef = armorPen > 0 ? (currentLairBossDef * (1 - armorPen)).clamp(0, double.infinity).toInt() : currentLairBossDef;
      int dmg = physAtk;
      dealtDmg = _minDmg(dmg, dmg - effDef);
    } else if (hasParagon150 && heroClass == HeroClass.monk) {
      // Plynoucí Čchi: fyzický útok, stávající stacky (0-5) přidávají +3 % dmg/stack.
      final armorPen = runeEffect(RuneEffectType.armorPen);
      int effDef = armorPen > 0 ? (currentLairBossDef * (1 - armorPen)).clamp(0, double.infinity).toInt() : currentLairBossDef;
      int dmg = physAtk;
      dealtDmg = _minDmg(dmg, dmg - effDef);
      dealtDmg = (dealtDmg * (1 + flowingChiStacks * flowingChiPerStack)).toInt();
    } else {
      int dmg = (isMagic ? magAtk : physAtk);
      // Runa průrazu: sníží efektivní obranu bosse.
      final armorPen = runeEffect(RuneEffectType.armorPen);
      int effDef = armorPen > 0 ? (currentLairBossDef * (1 - armorPen)).clamp(0, double.infinity).toInt() : currentLairBossDef;
      dealtDmg = _minDmg(dmg, dmg - effDef);
    }

    dealtDmg = (dealtDmg * basicAttackRoleMod).toInt();
    if (isCrit) dealtDmg = (dealtDmg * critDamageMultiplier).toInt();
    if (nextAttackDamageBoost) { dealtDmg = (dealtDmg * 1.1).toInt(); nextAttackDamageBoost = false; }
    // Runa "poškození bossům" – Lair souboj je vždy boss.
    final bossDmgBonus = runeEffect(RuneEffectType.bossDamage);
    if (bossDmgBonus > 0) dealtDmg = (dealtDmg * (1 + bossDmgBonus)).toInt();
    dealtDmg = (dealtDmg * specializationBossDamageMod).toInt();
    if (isCrit) message = tr("💥 Kritický zásah! Způsobeno $dealtDmg poškození.", "💥 Critical hit! Dealt $dealtDmg damage.");
    if(heroClass==HeroClass.hunter&&specialization==1&&huntersMarkStacks>=huntersMarkMaxStacks){dealtDmg=(dealtDmg*1.15).round();message+=" " + tr("Plné Znamení lovce: +15 % boss damage.", "Full Hunter's Mark: +15% boss damage.");}
    dealtDmg = _applyGemOffense(dealtDmg, enemyHp: currentLairBossHp, enemyMaxHp: currentLairBossMaxHp);
    // Boss block: boss s určitou šancí (podle obtížnosti) sníží obdržené poškození o 50 %.
    bool bossBlocked = Random().nextDouble() < lairBossSpecialChance;
    if (bossBlocked) {
      dealtDmg = (dealtDmg * 0.5).toInt();
      message = tr("🛡️ $currentLairBossName zablokoval část útoku! Sníženo na $dealtDmg poškození.", "🛡️ $currentLairBossName blocked part of the attack! Reduced to $dealtDmg damage.");
    }
    currentLairDamageDealt += dealtDmg;
    currentLairBossHp -= dealtDmg;

    // Deathknight: soul runa za Lair útok
    if (heroClass == HeroClass.deathknight) _gainSoulRune();
    _applyKrevPassiveLifesteal(dealtDmg); // Krev: pasivní 5 % lifesteal ze základního útoku

    // ===== PARAGON 150 — signature synergie =====
    if (hasParagon150) {
      final critPrefix = isCrit ? '💥 Kritický zásah! ' : '';
      if (heroClass == HeroClass.warrior) {
        rage = (rage + 10).clamp(0, maxRage);
        message = tr("$critPrefix Hněv šampiona: $dealtDmg dmg (+10 Hněvu)!", "$critPrefix Hněv šampiona: $dealtDmg dmg (+10 Rage)!");
      } else if (heroClass == HeroClass.hunter) {
        huntersMarkStacks = (huntersMarkStacks + 1).clamp(0, huntersMarkMaxStacks);
        message = tr("$critPrefix Znamení lovce: $dealtDmg dmg (stack $huntersMarkStacks/$huntersMarkMaxStacks)!", "$critPrefix Znamení lovce: $dealtDmg dmg (stack $huntersMarkStacks/$huntersMarkMaxStacks)!");
      } else if (heroClass == HeroClass.deathknight) {
        final curseIdx = enemyEffects.indexWhere((e) => e.name == "Prokletí");
        if (curseIdx != -1) {
          final curse = enemyEffects[curseIdx];
          if (curse.duration < curseMaxDuration) curse.duration += 1;
          message = tr("$critPrefix Runová trhlina: $dealtDmg dmg (Prokletí prodlouženo na ${curse.duration} kol)!", "$critPrefix Runová trhlina: $dealtDmg dmg (Curse extended to ${curse.duration} rounds)!");
        } else {
          message = tr("$critPrefix Runová trhlina: $dealtDmg dmg.", "$critPrefix Runová trhlina: $dealtDmg dmg.");
        }
      } else if (heroClass == HeroClass.mage) {
        arcaneChargeStacks = (arcaneChargeStacks + arcaneChargeGainPerHit).clamp(0, arcaneChargeMaxStacks);
        message = tr("$critPrefix Arkánový výbuch: $dealtDmg dmg (stack $arcaneChargeStacks/$arcaneChargeMaxStacks)!", "$critPrefix Arkánový výbuch: $dealtDmg dmg (stack $arcaneChargeStacks/$arcaneChargeMaxStacks)!");
      } else if (heroClass == HeroClass.duelist) {
        heroEffects.removeWhere((e) => e.name == "Elegantní výpad");
        heroEffects.add(StatusEffect(name: "Elegantní výpad", description: "+10 % dodge", duration: 3, isBuff: true));
        message = tr("$critPrefix Elegantní výpad: $dealtDmg dmg (+10 % dodge na 3 kola)!", "$critPrefix Elegantní výpad: $dealtDmg dmg (+10% dodge for 3 rounds)!");
      } else if (heroClass == HeroClass.monk) {
        flowingChiStacks = (flowingChiStacks + 1).clamp(0, flowingChiMaxStacks);
        message = tr("$critPrefix Plynoucí Čchi: $dealtDmg dmg (stack $flowingChiStacks/$flowingChiMaxStacks)!", "$critPrefix Plynoucí Čchi: $dealtDmg dmg (stack $flowingChiStacks/$flowingChiMaxStacks)!");
      }
    }

    // Léčitel: základní útok vytváří absorb (štít) ve výši 15 % způsobeného poškození
    // (Paragon 150 "Trest Světla" navíc přidá 10 % dealtDmg jako self-heal.)
    if (heroClass == HeroClass.healer) {
      final absorb = (dealtDmg * 0.15).toInt();
      if (absorb > 0) {
        bonusShield += absorb;
        _applyShieldCap();
        final critPrefix = isCrit ? '💥 Kritický zásah! ' : '';
        if (hasParagon150) {
          final selfHeal = (dealtDmg * 0.10).toInt();
          hp = (hp + selfHeal).clamp(0, maxHp);
          message = tr("$critPrefix Trest Světla: $dealtDmg dmg → štít +$absorb, heal +$selfHeal.", "$critPrefix Trest Světla: $dealtDmg dmg → shield +$absorb, heal +$selfHeal.");
          _cleansePoisonSynergy();
          _healIntoShieldSynergy(selfHeal);
        } else {
          message = tr("$critPrefix Útok léčitele: $dealtDmg dmg → štít +$absorb.", "$critPrefix Healer's attack: $dealtDmg dmg → shield +$absorb.");
        }
      }
    }

    if (lifestealTurns > 0) {
      int heal = (dealtDmg * 0.2 * specLifestealMod).toInt();
      hp = (hp + heal).clamp(0, maxHp);
      _cleansePoisonSynergy();
      _healIntoShieldSynergy(heal);
    }
    final runeLs = runeEffect(RuneEffectType.lifesteal);
    if (runeLs > 0) {
      final lsHeal = (dealtDmg * runeLs * specLifestealMod).toInt();
      hp = (hp + lsHeal).clamp(0, maxHp);
      _cleansePoisonSynergy();
      _healIntoShieldSynergy(lsHeal);
    }
    _applyDarknessSynergy(dealtDmg);
    // Odraz (curse): 15 % způsobeného poškození se vrátí hrdinovi jako damage.
    if (activeCurse == CurseOfFate.reflection && dealtDmg > 0) {
      final reflectedDmg = (dealtDmg * 0.15).toInt();
      hp -= reflectedDmg;
      if (reflectedDmg > 0) message += " (Odraz: -$reflectedDmg HP)";
    }
    _applyRuneProcs(dealtDmg);
    if (currentLairBossHp > 0 && rollExtraAttack()) {
      message += tr(' ⚡ Extra Attack!', ' ⚡ Extra Attack!');
      _extraAttackInProgress = true;
      fightLairBoss(isMagic);
      _extraAttackInProgress = false;
      return;
    }
    _resolveLairCombatRound();
  }

  void toggleCompanion(Companion companion) {
    if (companion.isRecruited) {
      companion.isRecruited = false;
      message = tr("Společník ${companion.name} propuštěn z družiny.", "Companion ${companion.name} dismissed from the party.");
    } else {
      if (activeCompanions.length >= 2) {
        message = tr("V družize můžeš mít maximálně 2 společníky současně!", "You can have at most 2 companions in your party at once!");
      } else if (!everRecruitedCompanions.contains(companion.name)) {
        // Odemčení NOVÉHO společníka (poprvé v historii účtu) stojí zlato, dvojnásobně za
        // každého dalšího - ALE úplně první společník v historii účtu je zdarma (viz
        // mustHireFirstCompanion výš), teprve druhý stojí 150, třetí 300, čtvrtý 600...
        // Znovupřijetí už dřív odemčeného společníka (po propuštění) je taky zdarma - platí se
        // jen prvotní odemčení.
        final cost = everRecruitedCompanions.isEmpty ? 0 : 150 * pow(2, everRecruitedCompanions.length - 1).toInt();
        if (gold < cost) {
          message = tr("Nedostatek zlata! Odemčení ${companion.name} stojí $cost 🪙 (máš $gold 🪙).", "Not enough gold! Unlocking ${companion.name} costs $cost 🪙 (you have $gold 🪙).");
        } else {
          gold -= cost;
          companion.isRecruited = true;
          everRecruitedCompanions.add(companion.name);
          message = cost == 0
              ? tr("Společník ${companion.name} odemčen a přidán do družiny zdarma!", "Companion ${companion.name} unlocked and added to the party for free!")
              : tr("Společník ${companion.name} odemčen a přidán do družiny za $cost 🪙!", "Companion ${companion.name} unlocked and added to the party for $cost 🪙!");
          if (everRecruitedCompanions.length == 1) _queueContextTip(TutorialTipId.tipCompanionsUnlocked);
          _checkAchievements();
        }
      } else {
        companion.isRecruited = true;
        message = tr("Společník ${companion.name} přidán do družiny!", "Companion ${companion.name} added to the party!");
        _checkAchievements();
      }
    }
    notifyListeners();
  }

  void upgradeCompanion(Companion companion) {
    int cost = companion.level * 200;
    if (magicDust >= cost) {
      magicDust -= cost;
      companion.level++;
      message = tr("Společník ${companion.name} vylepšen na level ${companion.level}!", "Companion ${companion.name} upgraded to level ${companion.level}!");
      notifyListeners();
    } else {
      message = tr("Nedostatek Magic Dust pro vylepšení společníka.", "Not enough Magic Dust to upgrade the companion.");
      notifyListeners();
    }
  }

  void chooseRank100Path(int choice) {
    if (isRank100Unlocked && rank100Choice == 0) {
      rank100Choice = choice;
      hp = maxHp;
      message = tr("Zvolena pokročilá cesta na Ranku 100!", "Advanced Rank 100 path chosen!");
      _triggerCelebration('RANK 100 CESTA ZVOLENA!', subtitle: spellVisualTier4(heroClass, choice).name, icon: Icons.military_tech, color: const Color(0xFFFF1744));
      notifyListeners();
    }
  }

  // ===== Sdílená brána pro stun/umlčení z nepřátelských schopností (viz enemyAbilityEffects) =====
  // Volá se na začátku KAŽDÉ akce hráče v boji (základní útok i spelly) - pokud je hráč omráčený,
  // zablokuje úplně vše; pokud jsou jen umlčená kouzla, zablokuje jen spell metody (isSpell:true),
  // základní útok (fight()) projde dál. Vrací true = akce byla zablokována (volající musí return).
  bool _checkCombatGate({required bool isSpell}) {
    if (heroStunTurns > 0) {
      heroStunTurns--;
      message = tr("😵 Jsi omráčen a nemůžeš jednat!", "😵 You are stunned and cannot act!");
      notifyListeners();
      return true;
    }
    if (isSpell && heroSpellBlockTurns > 0) {
      heroSpellBlockTurns--;
      message = tr("🔇 Kouzla jsou umlčena - použij základní útok!", "🔇 Spells are silenced - use your basic attack!");
      notifyListeners();
      return true;
    }
    return false;
  }

  void useActiveAbility() {
    if (isDead || !hasAdvancedClass || activeAbilityCooldown > 0) return;
    if (_checkCombatGate(isSpell: true)) return;
    if (!_spendResource(ability1Cost)) {
      message = tr("Nedostatek zdroje ($resourceName)! Potřeba: $ability1Cost, máš: $currentResourceValue.", "Not enough resource ($resourceName)! Needed: $ability1Cost, you have: $currentResourceValue.");
      notifyListeners();
      return;
    }
    final armorPen = runeEffect(RuneEffectType.armorPen);
    final effDef = armorPen > 0 ? (currentEnemyDef * (1 - armorPen)).clamp(0, double.infinity).toInt() : currentEnemyDef;
    if (isBerserk) {
      int dmg = (physAtk * 2.5 * specAbilityDamageMod).toInt();
      // Hardcore set "Krvavý Vztek" (Berserk, 2pc): +25 % dmg.
      if (specialization == 1 && activeHardcoreSetTier >= 2) dmg = (dmg * 1.25).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.berserk);
      _applyAbilityDot(dmg);
      // Hardcore set "Krvavá Žeň" (Krvežíznivý, 2pc): krvácení z tohohle útoku +50 % dmg.
      if (specialization == 3 && activeHardcoreSetTier >= 2 && appliesBleedOnAbility) {
        final bonusBleed = ((dmg * 0.20 / 3) * 0.5).round();
        final idx = enemyEffects.indexWhere((e) => e.name == "Krvácení (Krvežíznivý)");
        if (idx != -1) enemyEffects[idx] = StatusEffect(name: "Krvácení (Krvežíznivý)", description: "Krvácení ${enemyEffects[idx].dotDamage + bonusBleed}/kolo", duration: enemyEffects[idx].duration, isBuff: false, dotDamage: enemyEffects[idx].dotDamage + bonusBleed);
      }
      // Hardcore set "Nezdolná Pevnost" (Ochránce, 2pc): navíc štít +15 % MaxHP.
      if (specialization == 2 && activeHardcoreSetTier >= 2) {
        final shieldGain = (maxHp * 0.15).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
      }
      activeAbilityCooldown = _scaledCooldown(5);
      message = tr("Použito: Mocný úder! Způsobeno $dmg poškození.", "Used: Mocný úder! Dealt $dmg damage.");
    } else if (isAssassin) {
      int dmg = (physAtk * 2.0).toInt();
      // Hardcore set "Neomylná Stopa" (Stopař, 2pc): vždy kritický zásah.
      if (specialization == 1 && activeHardcoreSetTier >= 2) dmg = (dmg * critDamageMultiplier).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.assassin);
      int heal = (dmg * 0.5).toInt();
      // Hardcore set "Divoký Hon" (Divočina, 2pc): dvojnásobné léčení.
      if (specialization == 2 && activeHardcoreSetTier >= 2) heal *= 2;
      hp = (hp + heal).clamp(0, maxHp);
      _applyAbilityDot(dmg);
      // Hardcore set "Stínový Vládce" (Stín, 2pc): Jed dává dvojnásobný dmg/kolo.
      if (specialization == 3 && activeHardcoreSetTier >= 2) {
        final idx = enemyEffects.indexWhere((e) => e.name == "Jed (Stín)");
        if (idx != -1) enemyEffects[idx] = StatusEffect(name: "Jed (Stín)", description: "Jed ${enemyEffects[idx].dotDamage * 2}/kolo", duration: enemyEffects[idx].duration, isBuff: false, dotDamage: enemyEffects[idx].dotDamage * 2);
      }
      activeAbilityCooldown = _scaledCooldown(4);
      message = tr("Použito: Skrytý úder! Masivní poškození a vyléčení $heal HP.", "Used: Skrytý úder! Massive damage and healed $heal HP.");
    } else if (isPriest) {
      int heal = (maxHp * 0.5 * specAbilitySustainMod).toInt();
      // Hardcore set "Posvátné Světlo" (Světlo, 2pc): +50 % heal.
      if (specialization == 1 && activeHardcoreSetTier >= 2) heal = (heal * 1.5).toInt();
      hp = (hp + heal).clamp(0, maxHp);
      final shieldGain = (maxHp * 0.10 * specAbilitySustainMod).toInt();
      bonusShield += shieldGain;
      _applyShieldCap();
      _pushFx(FxKind.shieldGained, FxSide.hero, value: heal, spellFxKind: SpellFxKind.healerBlessing);
      heroEffects.add(StatusEffect(name: "Boží štít", description: "+10 % MaxHP absorpce", duration: 5, isBuff: true));
      activeAbilityCooldown = _scaledCooldown(6);
      message = tr("Použito: Boží požehnání! Obnoveno $heal HP a přidán štít (+$shieldGain).", "Used: Boží požehnání! Restored $heal HP and added a shield (+$shieldGain).");
      // Hardcore set "Božská Odplata" (Odplata, 2pc): okamžitě odrazí 10 % štítu na nepřítele.
      if (specialization == 2 && activeHardcoreSetTier >= 2) {
        final reflectDmg = (shieldGain * 0.10).toInt();
        currentEnemyHp -= reflectDmg;
        message += tr(" (Odplata: -$reflectDmg nepříteli)", " (Retribution: -$reflectDmg to the enemy)");
      }
      // Hardcore set "Bojový Kněz" (Battle Priest, 2pc): zraní nepřítele za 30 % vyléčeného HP.
      if (specialization == 3 && activeHardcoreSetTier >= 2) {
        final punishDmg = (heal * 0.30).toInt();
        currentEnemyHp -= punishDmg;
        message += tr(" (+$punishDmg dmg nepříteli)", " (+$punishDmg dmg to the enemy)");
      }
    } else if (isDarkKnight) {
      // Prokletý úder: fyzický úder + magický DoT prokletí na 4 kola.
      // Rebalance: 50 % MATK/kolo po 4 kola (celkem 2.0× MATK) - méně burst, více sustain.
      // Specializace: Nákaza posílí dmg/kolo, Mráz zkrátí trvání o 1 kolo (víc burst, míň sustain).
      final double triple = nextSpellTriple ? 3.0 : 1.0;
      if (nextSpellTriple) { nextSpellTriple = false; soulRunes = 0; }
      int physDmg = (physAtk * 1.5 * triple).toInt();
      // Hardcore set "Věčný Mráz" (Mráz, 2pc): fyzická složka je vždy kritická.
      if (specialization == 2 && activeHardcoreSetTier >= 2) physDmg = (physDmg * critDamageMultiplier).toInt();
      physDmg = _minDmg(physDmg, physDmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(physDmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: physDmg, spellFxKind: SpellFxKind.dkCursedStrike);
      _applyKrevPassiveLifesteal(physDmg);
      int dotDmg = (magAtk * 0.5 * triple * curseDmgMod).toInt();
      int curseDuration = (4 + curseCastDurationDelta).clamp(1, 99);
      // Hardcore set "Morová Rána" (Nákaza, 2pc): Prokletí trvá o 2 kola déle.
      if (specialization == 3 && activeHardcoreSetTier >= 2) curseDuration += 2;
      enemyEffects.removeWhere((e) => e.name == "Prokletí"); // přepis existujícího
      enemyEffects.add(StatusEffect(name: "Prokletí", description: "Magické prokletí — $dotDmg dmg/kolo", duration: curseDuration, isBuff: false, dotDamage: dotDmg));
      activeAbilityCooldown = _scaledCooldown(5);
      message = tr("☠ Prokletý úder! $physDmg fyzického dmg + Prokletí $dotDmg/kolo po $curseDuration kola.${triple > 1 ? ' ✨ TROJNÁSOBEK!' : ''}", "☠ Prokletý úder! $physDmg physical dmg + Curse $dotDmg/round for $curseDuration rounds.${triple > 1 ? ' ✨ TRIPLED!' : ''}");
      // Hardcore set "Krvavý Pakt" (Krev, 2pc): vyléčí 15 % fyzického dmg.
      if (specialization == 1 && activeHardcoreSetTier >= 2) {
        final selfHeal = (physDmg * 0.15).toInt();
        hp = (hp + selfHeal).clamp(0, maxHp);
        message += tr(" (+$selfHeal HP)", " (+$selfHeal HP)");
      }
    } else if (isElementalist) {
      int dmg = (magAtk * 2.5 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.elementalist);
      // Hardcore set "Věčný Plamen" (Plamen, 2pc): navíc zapálí nepřítele.
      if (specialization == 1 && activeHardcoreSetTier >= 2) {
        final burnDmg = (magAtk * 0.15).toInt();
        enemyEffects.removeWhere((e) => e.name == "Popálení (Set)");
        enemyEffects.add(StatusEffect(name: "Popálení (Set)", description: "Popálení $burnDmg/kolo", duration: 3, isBuff: false, dotDamage: burnDmg));
      }
      // Hardcore set "Věčný Led" (Led, 2pc): navíc dá štít (+10 % MaxHP).
      if (specialization == 2 && activeHardcoreSetTier >= 2) {
        final shieldGain = (maxHp * 0.10).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
      }
      // Hardcore set "Arkánová Nekonečnost" (Aether, 2pc): +2 Arcane Charge.
      if (specialization == 3 && activeHardcoreSetTier >= 2) {
        arcaneChargeStacks = (arcaneChargeStacks + 2).clamp(0, arcaneChargeMaxStacks);
      }
      activeAbilityCooldown = _scaledCooldown(5);
      message = tr("Použito: Elementální výbuch! Způsobeno $dmg poškození.", "Used: Elementální výbuch! Dealt $dmg damage.");
    } else if (isBladeDancer) {
      int dmg = (physAtk * 2.2 * specAbilityDamageMod).toInt();
      // Hardcore set "Krvavá Msta" (Vendetta, 2pc): +30 % dmg proti nepříteli pod 30 % HP.
      if (specialization == 1 && activeHardcoreSetTier >= 2 && currentEnemyMaxHp > 0 && currentEnemyHp / currentEnemyMaxHp < 0.3) {
        dmg = (dmg * 1.3).toInt();
      }
      // Hardcore set "Mistrovská Čepel" (Virtuóz, 2pc): vždy kritické.
      if (specialization == 3 && activeHardcoreSetTier >= 2) dmg = (dmg * critDamageMultiplier).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.bladeDancer);
      _applyAbilityDot(dmg);
      // Hardcore set "Elegantní Tanec" (Grácie, 2pc): +10 % úhyb na 3 kola.
      if (specialization == 2 && activeHardcoreSetTier >= 2) {
        heroEffects.removeWhere((e) => e.name == "Elegantní Tanec");
        heroEffects.add(StatusEffect(name: "Elegantní Tanec", description: "+10 % úhyb", duration: 3, isBuff: true));
      }
      activeAbilityCooldown = _scaledCooldown(5);
      message = tr("Použito: Rychlé combo! Způsobeno $dmg poškození.", "Used: Rychlé combo! Dealt $dmg damage.");
    } else if (isDisciple) {
      int dmg = (physAtk * 2.2 * specAbilityDamageMod).toInt();
      // Hardcore set "Vichr Bouře" (Vichr, 2pc): +25 % dmg.
      if (specialization == 1 && activeHardcoreSetTier >= 2) dmg = (dmg * 1.25).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.disciple);
      // Vichr (DMG): fyzické ability aplikují krvácení (15 % dmg / 3 kola).
      if (specialization == 1) {
        final dot = (dmg * 0.15 / 3).round();
        // Krvácení (Vichr) se SČÍTÁ, ne resetuje - další zásah přidá dmg k stávajícímu tiku a
        // obnoví trvání, takže už nastřádaný damage nikdy nezmizí, jen se rozloží do dalších kol.
        final vichrIdx = enemyEffects.indexWhere((e) => e.name == "Krvácení (Vichr)");
        if (vichrIdx != -1) {
          final stackedDot = cappedVichrBleed(enemyEffects[vichrIdx].dotDamage + dot);
          enemyEffects[vichrIdx] = StatusEffect(name: "Krvácení (Vichr)", description: "Krvácení $stackedDot/kolo", duration: 3, isBuff: false, dotDamage: stackedDot);
        } else {
          enemyEffects.add(StatusEffect(name: "Krvácení (Vichr)", description: "Krvácení $dot/kolo", duration: 3, isBuff: false, dotDamage: dot));
        }
      }
      // Hardcore set "Skalní Pevnost" (Skála, 2pc): navíc dá štít (+15 % MaxHP).
      if (specialization == 2 && activeHardcoreSetTier >= 2) {
        final shieldGain = (maxHp * 0.15).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
      }
      activeAbilityCooldown = _scaledCooldown(5);
      message = tr("Použito: Úder tisíce dlaní! Způsobeno $dmg poškození.", "Used: Úder tisíce dlaní! Dealt $dmg damage.");
      // Klid (Heal): abilita navíc vyléčí 25 % způsobeného poškození jako HP.
      // Hardcore set "Tichá Meditace" (Klid, 2pc): heal zdvojnásoben (50 % místo 25 %).
      if (monkCalmHealFromDamage > 0) {
        double healPercent = monkCalmHealFromDamage;
        if (specialization == 3 && activeHardcoreSetTier >= 2) healPercent *= 2;
        final selfHeal = (dmg * healPercent * specAbilitySustainMod).toInt();
        hp = (hp + selfHeal).clamp(0, maxHp);
        message += tr(" Vyléčeno $selfHeal HP.", " Healed $selfHeal HP.");
      }
    } else if (isAstralDruid) {
      // Divoký spár: magický úder + DoT "Uvadnutí" na 3 kola (nature damage-over-time).
      int dmg = (magAtk * 2.3 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.astralDruid);
      final dot = (dmg * 0.18 / 3).round();
      enemyEffects.removeWhere((e) => e.name == "Uvadnutí");
      enemyEffects.add(StatusEffect(name: "Uvadnutí", description: "Přírodní DoT $dot/kolo", duration: 3, isBuff: false, dotDamage: dot));
      // Obnova (Heal): signature/ability navíc vyléčí 15 % způsobeného poškození jako HP.
      if (specialization == 3) {
        final selfHeal = (dmg * 0.15 * specAbilitySustainMod).toInt();
        hp = (hp + selfHeal).clamp(0, maxHp);
      }
      // Divoký tvar (Tank): navíc dá štít (+15 % MaxHP) ze zvířecí kůže.
      if (specialization == 2) {
        final shieldGain = (maxHp * 0.15 * specAbilitySustainMod).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
      }
      // Hardcore set bonusy (Astrální Tlak/Forma Prastarého Medvěda/Srdce Šeptajícího Lesa).
      if (activeHardcoreSetTier >= 2) {
        if (specialization == 1) {
          final extraDot = dot;
          enemyEffects.removeWhere((e) => e.name == "Uvadnutí");
          enemyEffects.add(StatusEffect(name: "Uvadnutí", description: "Přírodní DoT ${extraDot * 2}/kolo", duration: felFireDuration, isBuff: false, dotDamage: extraDot * 2));
        } else if (specialization == 2) {
          bonusShield += (maxHp * 0.15 * specAbilitySustainMod).toInt();
          _applyShieldCap();
        } else if (specialization == 3) {
          hp = (hp + (dmg * 0.15 * specAbilitySustainMod).toInt()).clamp(0, maxHp);
        }
      }
      if (activeHardcoreSetTier >= 6 && specialization == 2) {
        hardcoreInvulnerableActive = true;
      }
      // Hardcore set bonusy (Astrální Tlak/Forma Prastarého Medvěda/Srdce Šeptajícího Lesa).
      if (activeHardcoreSetTier >= 2) {
        if (specialization == 1) {
          final extraDot = dot;
          enemyEffects.removeWhere((e) => e.name == "Uvadnutí");
          enemyEffects.add(StatusEffect(name: "Uvadnutí", description: "Přírodní DoT ${extraDot * 2}/kolo", duration: felFireDuration, isBuff: false, dotDamage: extraDot * 2));
        } else if (specialization == 2) {
          bonusShield += (maxHp * 0.15 * specAbilitySustainMod).toInt();
          _applyShieldCap();
        } else if (specialization == 3) {
          hp = (hp + (dmg * 0.15 * specAbilitySustainMod).toInt()).clamp(0, maxHp);
        }
      }
      if (activeHardcoreSetTier >= 6 && specialization == 2) {
        hardcoreInvulnerableActive = true;
      }
      // Hardcore set bonusy (Astrální Tlak/Forma Prastarého Medvěda/Srdce Šeptajícího Lesa).
      if (activeHardcoreSetTier >= 2) {
        if (specialization == 1) {
          final extraDot = dot;
          enemyEffects.removeWhere((e) => e.name == "Uvadnutí");
          enemyEffects.add(StatusEffect(name: "Uvadnutí", description: "Přírodní DoT ${extraDot * 2}/kolo", duration: felFireDuration, isBuff: false, dotDamage: extraDot * 2));
        } else if (specialization == 2) {
          bonusShield += (maxHp * 0.15 * specAbilitySustainMod).toInt();
          _applyShieldCap();
        } else if (specialization == 3) {
          hp = (hp + (dmg * 0.15 * specAbilitySustainMod).toInt()).clamp(0, maxHp);
        }
      }
      if (activeHardcoreSetTier >= 6 && specialization == 2) {
        hardcoreInvulnerableActive = true;
      }
      // Hardcore set bonusy (Astrální Tlak/Forma Prastarého Medvěda/Srdce Šeptajícího Lesa).
      if (activeHardcoreSetTier >= 2) {
        if (specialization == 1) {
          final extraDot = dot;
          enemyEffects.removeWhere((e) => e.name == "Uvadnutí");
          enemyEffects.add(StatusEffect(name: "Uvadnutí", description: "Přírodní DoT ${extraDot * 2}/kolo", duration: felFireDuration, isBuff: false, dotDamage: extraDot * 2));
        } else if (specialization == 2) {
          bonusShield += (maxHp * 0.15 * specAbilitySustainMod).toInt();
          _applyShieldCap();
        } else if (specialization == 3) {
          hp = (hp + (dmg * 0.15 * specAbilitySustainMod).toInt()).clamp(0, maxHp);
        }
      }
      if (activeHardcoreSetTier >= 6 && specialization == 2) {
        hardcoreInvulnerableActive = true;
      }
      activeAbilityCooldown = _scaledCooldown(5);
      message = tr("Divoký spár! Způsobeno $dmg poškození a nasazeno Uvadnutí ($dot/kolo).", "Divoký spár! Dealt $dmg damage and applied Wither ($dot/round).");
    } else if (isFaithGuardian) {
      // Úder Spravedlnosti: fyzický úder + malý štít (větší u tank specializace).
      int dmg = (physAtk * 2.2 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.faithGuardian);
      double shieldMult = 0.12;
      if (specialization == 1) shieldMult = 0.18;
      final shieldGain = (maxHp * shieldMult * specAbilitySustainMod).toInt();
      bonusShield += shieldGain;
      _applyShieldCap();
      if (specialization == 3) {
        final selfHeal = (dmg * 0.15 * specAbilitySustainMod).toInt();
        hp = (hp + selfHeal).clamp(0, maxHp);
      }
      // Hardcore set bonusy (Posvátný Val/Boží Trest/Posvěcená Cesta).
      if (activeHardcoreSetTier >= 2) {
        if (specialization == 1) {
          bonusShield += shieldGain;
          _applyShieldCap();
        } else if (specialization == 2) {
          final extraDmg = (dmg * 0.5).toInt();
          currentEnemyHp -= _mitigateEnemyDamage(extraDmg);
        } else if (specialization == 3) {
          hp = (hp + (dmg * 0.15 * specAbilitySustainMod).toInt()).clamp(0, maxHp);
        }
      }
      if (activeHardcoreSetTier >= 6 && specialization == 1) {
        hardcoreInvulnerableActive = true;
      }
      if (activeHardcoreSetTier >= 6 && specialization == 2) {
        nextAttackGuaranteedCrit = true;
      }
      activeAbilityCooldown = _scaledCooldown(5);
      message = tr("Úder Spravedlnosti! Způsobeno $dmg poškození a štít (+$shieldGain).", "Úder Spravedlnosti! Dealt $dmg damage and shield (+$shieldGain).");
    } else if (isFelBlade) {
      int dmg = (physAtk * 2.4 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.felBlade);
      final dot = (dmg * 0.15 / 3).round();
      enemyEffects.removeWhere((e) => e.name == "Fel oheň");
      enemyEffects.add(StatusEffect(name: "Fel oheň", description: "Fel DoT $dot/kolo", duration: 3, isBuff: false, dotDamage: dot));
      if (specialization == 2) {
        final selfHeal = (dmg * 0.20 * specAbilitySustainMod).toInt();
        hp = (hp + selfHeal).clamp(0, maxHp);
      }
      // Hardcore set bonusy (Čepele Nekonečné Zkázy/Pomsta Propasti/Rouno Fel Stínu).
      if (activeHardcoreSetTier >= 2) {
        if (specialization == 1) {
          final extraDmg = (dmg * 0.5).toInt();
          currentEnemyHp -= _mitigateEnemyDamage(extraDmg);
        } else if (specialization == 2) {
          bonusShield += (maxHp * 0.15 * specAbilitySustainMod).toInt();
          _applyShieldCap();
        } else if (specialization == 3) {
          final extraDot = dot;
          enemyEffects.removeWhere((e) => e.name == "Fel oheň");
          enemyEffects.add(StatusEffect(name: "Fel oheň", description: "Fel DoT ${extraDot * 2}/kolo", duration: felFireDuration, isBuff: false, dotDamage: extraDot * 2));
        }
      }
      if (activeHardcoreSetTier >= 6 && specialization == 1) {
        nextAttackGuaranteedCrit = true;
      }
      if (activeHardcoreSetTier >= 6 && specialization == 2) {
        hardcoreInvulnerableActive = true;
      }
      activeAbilityCooldown = _scaledCooldown(5);
      message = tr("Rozseknutí čepelemi! Způsobeno $dmg poškození a nasazen Fel oheň ($dot/kolo).", "Rozseknutí čepelemi! Dealt $dmg damage and applied Fel Fire ($dot/round).");
    } else if (isBoneLord) {
      int dmg = (magAtk * 2.3 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(dmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.boneLord);
      final petDmg = (magAtk * 0.6 * specAbilityDamageMod * (specialization == 1 ? 1.25 : 1.0)).toInt();
      currentEnemyHp -= _mitigateEnemyDamage(petDmg);
      if (specialization == 3) {
        final selfHeal = ((dmg + petDmg) * 0.15 * specAbilitySustainMod).toInt();
        hp = (hp + selfHeal).clamp(0, maxHp);
      }
      // Hardcore set bonusy (Armáda Nemrtvých/Vládce Rozkladu/Pakt s Podsvětím).
      if (activeHardcoreSetTier >= 2) {
        if (specialization == 1) {
          currentEnemyHp -= _mitigateEnemyDamage(petDmg);
        } else if (specialization == 2) {
          final extraDmg = (dmg * 0.5).toInt();
          currentEnemyHp -= _mitigateEnemyDamage(extraDmg);
        } else if (specialization == 3) {
          hp = (hp + ((dmg + petDmg) * 0.15 * specAbilitySustainMod).toInt()).clamp(0, maxHp);
        }
      }
      if (activeHardcoreSetTier >= 6 && specialization == 1) {
        nextAttackGuaranteedCrit = true;
      }
      if (activeHardcoreSetTier >= 6 && specialization == 2) {
        hardcoreInvulnerableActive = true;
      }
      activeAbilityCooldown = _scaledCooldown(5);
      message = tr("Kostěný Sluha! Způsobeno $dmg poškození + $petDmg od přivolaného sluhy.", "Kostěný Sluha! Dealt $dmg damage + $petDmg from the summoned servant.");
    }
    _resolveCombatRound();
  }

  void useSecondAbility() {
    if (isDead || !hasUltimateClass || secondAbilityCooldown > 0) return;
    if (_checkCombatGate(isSpell: true)) return;
    if (!_spendResource(ability2Cost)) {
      message = tr("Nedostatek zdroje ($resourceName)! Potřeba: $ability2Cost, máš: $currentResourceValue.", "Not enough resource ($resourceName)! Needed: $ability2Cost, you have: $currentResourceValue.");
      notifyListeners();
      return;
    }
    final armorPen2 = runeEffect(RuneEffectType.armorPen);
    final effDef = armorPen2 > 0 ? (currentEnemyDef * (1 - armorPen2)).clamp(0, double.infinity).toInt() : currentEnemyDef;
    if (isWarlord) {
      int dmg = (physAtk * 4.0 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.warlord);
      double shieldMult = 0.25;
      // Hardcore set "Nezdolná Pevnost" (Ochránce, 4pc): dvojnásobný štít.
      if (specialization == 2 && activeHardcoreSetTier >= 4) shieldMult *= 2;
      final shieldGain = (maxHp * shieldMult * specAbilitySustainMod).toInt();
      bonusShield += shieldGain;
      _applyShieldCap();
      _applyAbilityDot(dmg);
      // Hardcore set "Krvavá Žeň" (Krvežíznivý, 4pc): krvácení trvá 6 kol místo 3.
      if (specialization == 3 && activeHardcoreSetTier >= 4) {
        final idx = enemyEffects.indexWhere((e) => e.name == "Krvácení (Krvežíznivý)");
        if (idx != -1 && enemyEffects[idx].duration < 6) enemyEffects[idx].duration = 6;
      }
      heroEffects.add(StatusEffect(name: "Warlordova hradba", description: "+25 % MaxHP štít", duration: 8, isBuff: true));
      secondAbilityCooldown = _scaledCooldown(10);
      message = tr("Použito: Rozdrcení světa! Způsobeno $dmg poškození a získán velký štít (+$shieldGain).", "Used: Rozdrcení světa! Dealt $dmg damage and gained a large shield (+$shieldGain).");
      // Hardcore set "Krvavý Vztek" (Berserk, 4pc): schopnost nestojí žádný zdroj - vrátit útratu.
      if (specialization == 1 && activeHardcoreSetTier >= 4) {
        rage = (rage + ability2Cost).clamp(0, maxRage);
        message += "Krvavý Vztek: " + tr("schopnost byla zdarma!", "the ability was free!");
      }
    } else if (isShadowMaster) {
      int dmg = (physAtk * 5.0).toInt();
      // Hardcore set "Neomylná Stopa" (Stopař, 4pc): +50 % kritického poškození na tenhle útok.
      if (specialization == 1 && activeHardcoreSetTier >= 4) dmg = (dmg * 1.5).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.shadowMaster);
      _applyAbilityDot(dmg);
      // Hardcore set "Stínový Vládce" (Stín, 4pc): aplikuje i Jed.
      if (specialization == 3 && activeHardcoreSetTier >= 4) {
        final dot = (dmg * 0.10 / 3).round();
        enemyEffects.removeWhere((e) => e.name == "Jed (Stín)");
        enemyEffects.add(StatusEffect(name: "Jed (Stín)", description: "Jed $dot/kolo", duration: 3, isBuff: false, dotDamage: dot));
      }
      secondAbilityCooldown = _scaledCooldown(8);
      // Hardcore set "Divoký Hon" (Divočina, 4pc): poloviční cooldown.
      if (specialization == 2 && activeHardcoreSetTier >= 4) secondAbilityCooldown = (secondAbilityCooldown / 2).ceil();
      message = tr("Použito: Stínová poprava! Způsobeno brutálních $dmg poškození.", "Used: Stínová poprava! Dealt a brutal $dmg damage.");
    } else if (isProrok) {
      hp = maxHp;
      int dmg = (magAtk * 3.5 * specAbilityDamageMod).toInt();
      // Hardcore set "Bojový Kněz" (Battle Priest, 4pc): +50 % poškození.
      if (specialization == 3 && activeHardcoreSetTier >= 4) dmg = (dmg * 1.5).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
      _pushFx(FxKind.explosionDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.healerJudgment);
      // Hardcore set "Posvátné Světlo" (Světlo, 4pc): navíc dá štít (+30 % MaxHP).
      if (specialization == 1 && activeHardcoreSetTier >= 4) {
        final shieldGain = (maxHp * 0.30).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
        message = tr("Použito: Boží soud! Plné vyléčení HP, svatý úder za $dmg poškození a štít (+$shieldGain).", "Used: Boží soud! Full HP heal, a holy strike for $dmg damage, and a shield (+$shieldGain).");
      } else {
        message = tr("Použito: Boží soud! Plné vyléčení HP a svatý úder za $dmg poškození.", "Used: Boží soud! Full HP heal and a holy strike for $dmg damage.");
      }
      // Hardcore set "Božská Odplata" (Odplata, 4pc): navíc odrazí 20 % M.Atk jako bonus dmg.
      if (specialization == 2 && activeHardcoreSetTier >= 4) {
        final bonusDmg = (magAtk * 0.20).toInt();
        currentEnemyHp -= bonusDmg;
        message += tr(" (Odplata: +$bonusDmg dmg)", " (Retribution: +$bonusDmg dmg)");
      }
      secondAbilityCooldown = _scaledCooldown(12);
    } else if (isPlagueLord) {
      // Rebalance: druhý spell je vždy užitečný. Odpálí PŘESNĚ zbývající Curse damage (bez ×4 násobiče)
      // a vždy udělí adaptivní absorb štít - čím méně kol Prokletí zbývalo, tím větší štít.
      // "Odpálí zbývající poškození tvé kletby a současně vytvoří absorb štít. Čím déle byla kletba aktivní, tím silnější štít získáš."
      final double triple = nextSpellTriple ? 3.0 : 1.0;
      if (nextSpellTriple) { nextSpellTriple = false; soulRunes = 0; }
      final prokl = enemyEffects.firstWhere((e) => e.name == "Prokletí", orElse: () => StatusEffect(name: "", description: "", duration: 0, isBuff: false));
      final bool hasCurse = prokl.name == "Prokletí";
      final int remainingDotTurns = hasCurse ? prokl.duration : 0;
      final int originalDotDmg = hasCurse ? prokl.dotDamage : 0;
      int remainingCurseDamage = hasCurse ? (prokl.dotDamage * remainingDotTurns * triple * curseDmgMod).toInt() : 0;
      // Hardcore set "Věčný Mráz" (Mráz, 4pc): +50 % poškození.
      if (specialization == 2 && activeHardcoreSetTier >= 4) remainingCurseDamage = (remainingCurseDamage * 1.5).toInt();
      if (remainingCurseDamage > 0) currentEnemyHp -= remainingCurseDamage;
      _applyKrevPassiveLifesteal(remainingCurseDamage);
      if (hasCurse) {
        enemyEffects.removeWhere((e) => e.name == "Prokletí");
        // Hardcore set "Morová Rána" (Nákaza, 4pc): kletba se ihned znovu nasadí místo spotřebování.
        if (specialization == 3 && activeHardcoreSetTier >= 4) {
          final newDuration = (4 + curseCastDurationDelta).clamp(1, 99);
          enemyEffects.add(StatusEffect(name: "Prokletí", description: "Magické prokletí — $originalDotDmg dmg/kolo", duration: newDuration, isBuff: false, dotDamage: originalDotDmg));
        }
      }
      const int maxDotTurns = 4;
      final double completion = 1.0 - (remainingDotTurns / maxDotTurns);
      final double shieldPercent = 25 + (completion * 50);
      final int shieldGain = (maxHp * (shieldPercent / 100)).toInt();
      bonusShield += shieldGain;
      _applyShieldCap();
      secondAbilityCooldown = _scaledCooldown(8);
      if (remainingCurseDamage > 0) {
        _pushFx(FxKind.explosionDamage, FxSide.enemy, value: remainingCurseDamage, spellFxKind: SpellFxKind.dkCurseExplosion);
      } else {
        _pushFx(FxKind.shieldGained, FxSide.hero, value: shieldGain, spellFxKind: SpellFxKind.dkCurseExplosion);
      }
      if (remainingCurseDamage > 0) {
        message = tr("💥 Exploze prokletí! Zbývající DoT exploduje za $remainingCurseDamage okamžitého poškození a získáváš štít +$shieldGain!${triple > 1 ? ' ✨ TROJNÁSOBEK!' : ''}", "💥 Curse Explosion! The remaining DoT detonates for $remainingCurseDamage instant damage and you gain a shield +$shieldGain!${triple > 1 ? ' ✨ TRIPLED!' : ''}");
      } else {
        message = tr("Žádné aktivní Prokletí - vytvořen absorb štít +$shieldGain.", "No active Curse - created an absorb shield +$shieldGain.");
      }
      // Hardcore set "Krvavý Pakt" (Krev, 4pc): vyléčí 100 % vybuchlého dmg jako HP.
      if (specialization == 1 && activeHardcoreSetTier >= 4 && remainingCurseDamage > 0) {
        hp = (hp + remainingCurseDamage).clamp(0, maxHp);
        message += tr(" (+$remainingCurseDamage HP)", " (+$remainingCurseDamage HP)");
      }
    } else if (isArcanist) {
      int dmg = (magAtk * 4.5 * specAbilityDamageMod).toInt();
      // Hardcore set "Arkánová Nekonečnost" (Aether, 4pc): bonus dmg za každý Arcane Charge stack.
      if (specialization == 3 && activeHardcoreSetTier >= 4) {
        dmg = (dmg * (1 + arcaneChargeStacks * arcaneChargePerStack)).toInt();
      }
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.arcanist);
      double manaRefundMult = 0.3;
      // Hardcore set "Věčný Plamen" (Plamen, 4pc): vrátí dvojnásobek many.
      if (specialization == 1 && activeHardcoreSetTier >= 4) manaRefundMult *= 2;
      mana = (mana + (ability2Cost * manaRefundMult).toInt()).clamp(0, maxMana);
      secondAbilityCooldown = _scaledCooldown(9);
      // Hardcore set "Věčný Led" (Led, 4pc): poloviční cooldown.
      if (specialization == 2 && activeHardcoreSetTier >= 4) secondAbilityCooldown = (secondAbilityCooldown / 2).ceil();
      message = tr("Použito: Arkánový nával za $dmg poškození (část many vrácena).", "Used: Arkánový nával for $dmg damage (part of the mana refunded).");
    } else if (isBladeMaster) {
      int dmg = (physAtk * 5.0 * specAbilityDamageMod).toInt();
      // Hardcore set "Krvavá Msta" (Vendetta, 4pc): +30 % dmg proti nepříteli pod 30 % HP.
      if (specialization == 1 && activeHardcoreSetTier >= 4 && currentEnemyMaxHp > 0 && currentEnemyHp / currentEnemyMaxHp < 0.3) {
        dmg = (dmg * 1.3).toInt();
      }
      // Hardcore set "Mistrovská Čepel" (Virtuóz, 4pc): +50 % kritického poškození.
      if (specialization == 3 && activeHardcoreSetTier >= 4) dmg = (dmg * 1.5).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.bladeMaster);
      _applyAbilityDot(dmg);
      secondAbilityCooldown = _scaledCooldown(9);
      // Hardcore set "Elegantní Tanec" (Grácie, 4pc): -30 % cooldown.
      if (specialization == 2 && activeHardcoreSetTier >= 4) secondAbilityCooldown = (secondAbilityCooldown * 0.7).ceil();
      message = tr("Použito: Precizní výpad za $dmg poškození.", "Used: Precizní výpad for $dmg damage.");
    } else if (isGrandmaster) {
      int dmg = (physAtk * 4.5 * specAbilityDamageMod).toInt();
      // Hardcore set "Vichr Bouře" (Vichr, 4pc): +30 % dmg proti nepříteli pod 30 % HP.
      if (specialization == 1 && activeHardcoreSetTier >= 4 && currentEnemyMaxHp > 0 && currentEnemyHp / currentEnemyMaxHp < 0.3) {
        dmg = (dmg * 1.3).toInt();
      }
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.grandmaster);
      double shieldMult = 0.20;
      // Hardcore set "Skalní Pevnost" (Skála, 4pc): dvojnásobný štít.
      if (specialization == 2 && activeHardcoreSetTier >= 4) shieldMult *= 2;
      final shieldGain = (maxHp * shieldMult * specAbilitySustainMod).toInt();
      bonusShield += shieldGain;
      _applyShieldCap();
      secondAbilityCooldown = _scaledCooldown(9);
      message = tr("Použito: Dračí kop! Způsobeno $dmg poškození a získán štít (+$shieldGain).", "Used: Dračí kop! Dealt $dmg damage and gained a shield (+$shieldGain).");
      if (specialization == 1) {
        final dot = (dmg * 0.15 / 3).round();
        // Krvácení (Vichr) se SČÍTÁ, ne resetuje - další zásah přidá dmg k stávajícímu tiku a
        // obnoví trvání, takže už nastřádaný damage nikdy nezmizí, jen se rozloží do dalších kol.
        final vichrIdx = enemyEffects.indexWhere((e) => e.name == "Krvácení (Vichr)");
        if (vichrIdx != -1) {
          final stackedDot = cappedVichrBleed(enemyEffects[vichrIdx].dotDamage + dot);
          enemyEffects[vichrIdx] = StatusEffect(name: "Krvácení (Vichr)", description: "Krvácení $stackedDot/kolo", duration: 3, isBuff: false, dotDamage: stackedDot);
        } else {
          enemyEffects.add(StatusEffect(name: "Krvácení (Vichr)", description: "Krvácení $dot/kolo", duration: 3, isBuff: false, dotDamage: dot));
        }
      }
      if (monkCalmHealFromDamage > 0) {
        final selfHeal = (dmg * monkCalmHealFromDamage * specAbilitySustainMod).toInt();
        hp = (hp + selfHeal).clamp(0, maxHp);
        message += tr(" Vyléčeno $selfHeal HP.", " Healed $selfHeal HP.");
      }
      // Hardcore set "Tichá Meditace" (Klid, 4pc): navíc vyléčí 25 % způsobeného dmg jako HP.
      if (specialization == 3 && activeHardcoreSetTier >= 4) {
        final extraHeal = (dmg * 0.25).toInt();
        hp = (hp + extraHeal).clamp(0, maxHp);
        message += tr(" (+$extraHeal HP)", " (+$extraHeal HP)");
      }
    } else if (isMoonfury) {
      // Hvězdný pád: silný magický burst z astrální energie.
      int dmg = (magAtk * 3.2 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.moonfury);
      if (specialization == 2) {
        final shieldGain = (maxHp * 0.18 * specAbilitySustainMod).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
      }
      if (specialization == 3) {
        final selfHeal = (dmg * 0.15 * specAbilitySustainMod).toInt();
        hp = (hp + selfHeal).clamp(0, maxHp);
      }
      secondAbilityCooldown = _scaledCooldown(9);
      message = tr("Použito: Hvězdný pád! Způsobeno $dmg poškození.", "Used: Hvězdný pád! Dealt $dmg damage.");
    } else if (isRetributor) {
      int dmg = (physAtk * 4.5 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.retributor);
      if (specialization == 1) {
        final shieldGain = (maxHp * 0.15 * specAbilitySustainMod).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
      }
      if (specialization == 3) {
        final selfHeal = (dmg * 0.15 * specAbilitySustainMod).toInt();
        hp = (hp + selfHeal).clamp(0, maxHp);
      }
      secondAbilityCooldown = _scaledCooldown(9);
      message = tr("Použito: Boží Trest! Způsobeno $dmg poškození.", "Used: Boží Trest! Dealt $dmg damage.");
    } else if (isDemonSlayer) {
      int dmg = (physAtk * 4.8 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.demonSlayer);
      if (specialization == 2) {
        final selfHeal = (dmg * 0.25 * specAbilitySustainMod).toInt();
        hp = (hp + selfHeal).clamp(0, maxHp);
      }
      secondAbilityCooldown = _scaledCooldown(9);
      message = tr("Použito: Metamorfóza! Způsobeno $dmg poškození.", "Used: Metamorfóza! Dealt $dmg damage.");
    } else if (isDeathSovereign) {
      int dmg = (magAtk * 4.5 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.deathSovereign);
      if (specialization == 2) {
        final dot = (dmg * 0.15 / 3).round();
        enemyEffects.removeWhere((e) => e.name == "Rozklad");
        enemyEffects.add(StatusEffect(name: "Rozklad", description: "Rozklad $dot/kolo", duration: 3, isBuff: false, dotDamage: dot));
      }
      secondAbilityCooldown = _scaledCooldown(9);
      message = tr("Použito: Volání Nemrtvých! Způsobeno $dmg poškození.", "Used: Volání Nemrtvých! Dealt $dmg damage.");
    }
    _resolveCombatRound();
  }

  void useThirdAbility() {
    if (isDead || !hasGodClass || thirdAbilityCooldown > 0) return;
    if (_checkCombatGate(isSpell: true)) return;
    if (!_spendResource(ability3Cost)) {
      message = tr("Nedostatek zdroje ($resourceName)! Potřeba: $ability3Cost, máš: $currentResourceValue.", "Not enough resource ($resourceName)! Needed: $ability3Cost, you have: $currentResourceValue.");
      notifyListeners();
      return;
    }
    final armorPen3 = runeEffect(RuneEffectType.armorPen);
    final effDef = armorPen3 > 0 ? (currentEnemyDef * (1 - armorPen3)).clamp(0, double.infinity).toInt() : currentEnemyDef;
    if (isValhallaWarrior) {
      int dmg = (physAtk * 7.5 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.valhallaWarrior);
      final shieldGain = (maxHp * 0.50 * specAbilitySustainMod).toInt();
      bonusShield += shieldGain;
      _applyShieldCap();
      _applyAbilityDot(dmg);
      // Hardcore set "Krvavá Žeň" (Krvežíznivý, 6pc): Boží hněv aplikuje krvácení za dvojnásobnou sílu.
      if (specialization == 3 && activeHardcoreSetTier >= 6) {
        final dot = ((dmg * 0.20 / 3) * 2).round();
        enemyEffects.removeWhere((e) => e.name == "Krvácení (Krvežíznivý)");
        enemyEffects.add(StatusEffect(name: "Krvácení (Krvežíznivý)", description: "Krvácení $dot/kolo", duration: 6, isBuff: false, dotDamage: dot));
      }
      heroEffects.add(StatusEffect(name: "Valhalla", description: "+50 % MaxHP štít", duration: 10, isBuff: true));
      // Hardcore set "Nezdolná Pevnost" (Ochránce, 6pc): 1 kolo naprosté nezranitelnosti.
      if (specialization == 2 && activeHardcoreSetTier >= 6) {
        hardcoreInvulnerableActive = true;
      }
      thirdAbilityCooldown = _scaledCooldown(15);
      // Hardcore set "Krvavý Vztek" (Berserk, 6pc): cooldown snížený z 15 na 6 kol.
      if (specialization == 1 && activeHardcoreSetTier >= 6) thirdAbilityCooldown = _scaledCooldown(6);
      message = tr("Použito: Boží hněv! Extrémní fyzická erupce za $dmg poškození a obří štít (+$shieldGain).", "Used: Boží hněv! An extreme physical eruption for $dmg damage and a huge shield (+$shieldGain).");
    } else if (isVoidStalker) {
      int dmg = (physAtk * 8.0).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.voidStalker);
      hp = maxHp;
      _applyAbilityDot(dmg);
      // Hardcore set "Stínový Vládce" (Stín, 6pc): Jed prodloužen na 10 kol.
      if (specialization == 3 && activeHardcoreSetTier >= 6) {
        final idx = enemyEffects.indexWhere((e) => e.name == "Jed (Stín)");
        if (idx != -1) enemyEffects[idx].duration = 10;
      }
      // Hardcore set "Divoký Hon" (Divočina, 6pc): +20 % úhyb na 5 kol.
      if (specialization == 2 && activeHardcoreSetTier >= 6) {
        heroEffects.removeWhere((e) => e.name == "Divoký Hon");
        heroEffects.add(StatusEffect(name: "Divoký Hon", description: "+20 % úhyb", duration: 5, isBuff: true));
      }
      thirdAbilityCooldown = _scaledCooldown(14);
      message = tr("Použito: Prázdnotová bouře! Zasazeno smrtících $dmg poškození a plně obnoveno HP.", "Used: Prázdnotová bouře! Dealt a deadly $dmg damage and fully restored HP.");
      // Hardcore set "Neomylná Stopa" (Stopař, 6pc): zaručený crit na další základní útok.
      if (specialization == 1 && activeHardcoreSetTier >= 6) {
        nextAttackGuaranteedCrit = true;
        message += "Neomylná Stopa: " + tr("další útok bude kritický!", "the next attack will be critical!");
      }
    } else if (isLightBearer) {
      int dmg = (magAtk * 7.0 * specAbilityDamageMod).toInt();
      // Hardcore set "Bojový Kněz" (Battle Priest, 6pc): +100 % poškození.
      if (specialization == 3 && activeHardcoreSetTier >= 6) dmg *= 2;
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.lightBearer);
      final shieldGain = (maxHp * 0.50 * specAbilitySustainMod).toInt();
      bonusShield += shieldGain;
      _applyShieldCap();
      int shieldDuration = 10;
      // Hardcore set "Posvátné Světlo" (Světlo, 6pc): štít vydrží 30 kol místo 10.
      if (specialization == 1 && activeHardcoreSetTier >= 6) shieldDuration = 30;
      heroEffects.add(StatusEffect(name: "Světelný štít", description: "+50 % MaxHP štít", duration: shieldDuration, isBuff: true));
      thirdAbilityCooldown = _scaledCooldown(16);
      message = tr("Použito: Nebeský rozsudek! Božská sprcha za $dmg poškození, plné HP a štít (+$shieldGain).", "Used: Nebeský rozsudek! A divine downpour for $dmg damage, full HP, and a shield (+$shieldGain).");
      // Hardcore set "Božská Odplata" (Odplata, 6pc): celý štít se okamžitě odrazí na nepřítele.
      if (specialization == 2 && activeHardcoreSetTier >= 6) {
        currentEnemyHp -= shieldGain;
        message += tr(" (Odplata: celý štít odražen, -$shieldGain nepříteli!)", " (Retribution: the entire shield reflected, -$shieldGain to the enemy!)");
      }
    } else if (isDeathReaper) {
      // Úder smrti: fyzický dmg + magický dmg → mag se konvertuje na léčení (nebo absorb při plném HP)
      final double triple = nextSpellTriple ? 3.0 : 1.0;
      if (nextSpellTriple) { nextSpellTriple = false; soulRunes = 0; }
      int physDmg = (physAtk * 2.0 * triple).toInt();
      // Hardcore set "Věčný Mráz" (Mráz, 6pc): fyzická složka je vždy kritická.
      if (specialization == 2 && activeHardcoreSetTier >= 6) physDmg = (physDmg * critDamageMultiplier).toInt();
      physDmg = _minDmg(physDmg, physDmg - effDef);
      int magDmg  = (magAtk  * 2.0 * triple).toInt();
      currentEnemyHp -= _mitigateEnemyDamage(physDmg);
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: physDmg, spellFxKind: SpellFxKind.deathReaper);
      _applyKrevPassiveLifesteal(physDmg);
      // Hardcore set "Morová Rána" (Nákaza, 6pc): navíc nasadí Prokletí.
      if (specialization == 3 && activeHardcoreSetTier >= 6) {
        final dotDmg = (magAtk * 0.5 * curseDmgMod).toInt();
        final curseDuration = (4 + curseCastDurationDelta).clamp(1, 99);
        enemyEffects.removeWhere((e) => e.name == "Prokletí");
        enemyEffects.add(StatusEffect(name: "Prokletí", description: "Magické prokletí — $dotDmg dmg/kolo", duration: curseDuration, isBuff: false, dotDamage: dotDmg));
      }
      // Hardcore set "Krvavý Pakt" (Krev, 6pc): heal I štít současně, ne jen jedno podle HP.
      if (specialization == 1 && activeHardcoreSetTier >= 6) {
        bonusShield += magDmg;
        _applyShieldCap();
        hp = (hp + magDmg).clamp(0, maxHp);
        heroEffects.add(StatusEffect(name: "Smrtící štít", description: "+$magDmg absorb ze Smrtelného úderu", duration: 8, isBuff: true));
        thirdAbilityCooldown = _scaledCooldown(12);
        message = tr("💀 Úder smrti! $physDmg fyzického dmg. Krvavý Pakt: +$magDmg HP i štít současně!${triple > 1 ? ' ✨ TROJNÁSOBEK!' : ''}", "💀 Úder smrti! $physDmg physical dmg. Krvavý Pakt: +$magDmg HP and shield at once!${triple > 1 ? ' ✨ TRIPLED!' : ''}");
      } else if (hp >= maxHp) {
        // Magická složka → heal; při plném HP → absorb
        bonusShield += magDmg;
        _applyShieldCap();
        heroEffects.add(StatusEffect(name: "Smrtící štít", description: "+$magDmg absorb ze Smrtelného úderu", duration: 8, isBuff: true));
        thirdAbilityCooldown = _scaledCooldown(12);
        message = tr("💀 Úder smrti! $physDmg fyzického dmg. HP plné → absorb +$magDmg.${triple > 1 ? ' ✨ TROJNÁSOBEK!' : ''}", "💀 Úder smrti! $physDmg physical dmg. HP full → absorb +$magDmg.${triple > 1 ? ' ✨ TRIPLED!' : ''}");
      } else {
        int healed = magDmg;
        hp = (hp + healed).clamp(0, maxHp);
        thirdAbilityCooldown = _scaledCooldown(12);
        message = tr("💀 Úder smrti! $physDmg fyzického dmg + $healed HP vyléčeno magickou silou.${triple > 1 ? ' ✨ TROJNÁSOBEK!' : ''}", "💀 Úder smrti! $physDmg physical dmg + $healed HP healed by magic power.${triple > 1 ? ' ✨ TRIPLED!' : ''}");
      }
    } else if (isArchmage) {
      int dmg = (magAtk * 8.0 * specAbilityDamageMod).toInt();
      // Hardcore set "Věčný Plamen" (Plamen, 6pc): navíc zapálí nepřítele.
      if (specialization == 1 && activeHardcoreSetTier >= 6) {
        final burnDmg = (magAtk * 0.20).toInt();
        enemyEffects.removeWhere((e) => e.name == "Popálení (Set)");
        enemyEffects.add(StatusEffect(name: "Popálení (Set)", description: "Popálení $burnDmg/kolo", duration: 3, isBuff: false, dotDamage: burnDmg));
      }
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.archmage);
      double shieldMult = 0.40;
      // Hardcore set "Věčný Led" (Led, 6pc): dvojnásobný štít.
      if (specialization == 2 && activeHardcoreSetTier >= 6) shieldMult *= 2;
      final shieldGain = (maxHp * shieldMult * specAbilitySustainMod).toInt();
      bonusShield += shieldGain;
      _applyShieldCap();
      thirdAbilityCooldown = _scaledCooldown(16);
      message = tr("Použito: Archmágův příval za $dmg poškození a arkánový ward (+$shieldGain).", "Used: Archmágův příval for $dmg damage and an arcane ward (+$shieldGain).");
      // Hardcore set "Arkánová Nekonečnost" (Aether, 6pc): schopnost nestojí žádnou manu.
      if (specialization == 3 && activeHardcoreSetTier >= 6) {
        mana = (mana + ability3Cost).clamp(0, maxMana);
        message += "Arkánová Nekonečnost: " + tr("schopnost byla zdarma!", "the ability was free!");
      }
    } else if (isStormblade) {
      int dmg = (physAtk * 8.5 * specAbilityDamageMod).toInt();
      // Hardcore set "Krvavá Msta" (Vendetta, 6pc): execute bonus zdvojnásobený (+60 %).
      if (specialization == 1 && activeHardcoreSetTier >= 6 && currentEnemyMaxHp > 0 && currentEnemyHp / currentEnemyMaxHp < 0.3) {
        dmg = (dmg * 1.6).toInt();
      }
      // Hardcore set "Mistrovská Čepel" (Virtuóz, 6pc): vždy kritické.
      if (specialization == 3 && activeHardcoreSetTier >= 6) dmg = (dmg * critDamageMultiplier).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.stormblade);
      hp = maxHp;
      _applyAbilityDot(dmg);
      thirdAbilityCooldown = _scaledCooldown(15);
      message = tr("Použito: Bouře čepelí za $dmg poškození a plné HP.", "Used: Bouře čepelí for $dmg damage and full HP.");
      // Hardcore set "Elegantní Tanec" (Grácie, 6pc): prodlouží úhybový buff na 8 kol.
      if (specialization == 2 && activeHardcoreSetTier >= 6) {
        heroEffects.removeWhere((e) => e.name == "Elegantní Tanec");
        heroEffects.add(StatusEffect(name: "Elegantní Tanec", description: "+10 % úhyb", duration: 8, isBuff: true));
        message += "Elegantní Tanec: " + tr("+10 % úhyb na 8 kol!", "+10% dodge for 8 rounds!");
      }
    } else if (isEnlightened) {
      int dmg = (physAtk * 7.5 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.enlightened);
      hp = maxHp;
      double shieldMult = 0.40;
      // Hardcore set "Skalní Pevnost" (Skála, 6pc): 1 kolo naprosté nezranitelnosti - řešeno níž samostatně.
      final shieldGain = (maxHp * shieldMult * specAbilitySustainMod).toInt();
      bonusShield += shieldGain;
      _applyShieldCap();
      heroEffects.add(StatusEffect(name: "Nebeská Harmonie", description: "+40 % MaxHP štít", duration: 10, isBuff: true));
      thirdAbilityCooldown = _scaledCooldown(15);
      message = tr("Použito: Nebeská Harmonie! $dmg poškození, plné HP a štít (+$shieldGain).", "Used: Nebeská Harmonie! $dmg damage, full HP, and a shield (+$shieldGain).");
      if (specialization == 1) {
        double bleedMult = 1.5;
        // Hardcore set "Vichr Bouře" (Vichr, 6pc): krvácení za dvojnásobnou sílu.
        if (activeHardcoreSetTier >= 6) bleedMult *= 2;
        final dot = ((dmg * 0.15 / 3) * bleedMult).round();
        // Krvácení (Vichr) se SČÍTÁ, ne resetuje - další zásah přidá dmg k stávajícímu tiku a
        // obnoví trvání, takže už nastřádaný damage nikdy nezmizí, jen se rozloží do dalších kol.
        final vichrIdx = enemyEffects.indexWhere((e) => e.name == "Krvácení (Vichr)");
        if (vichrIdx != -1) {
          final stackedDot = cappedVichrBleed(enemyEffects[vichrIdx].dotDamage + dot);
          enemyEffects[vichrIdx] = StatusEffect(name: "Krvácení (Vichr)", description: "Krvácení $stackedDot/kolo", duration: 3, isBuff: false, dotDamage: stackedDot);
        } else {
          enemyEffects.add(StatusEffect(name: "Krvácení (Vichr)", description: "Krvácení $dot/kolo", duration: 3, isBuff: false, dotDamage: dot));
        }
      }
      // Hardcore set "Skalní Pevnost" (Skála, 6pc): 1 kolo naprosté nezranitelnosti.
      if (specialization == 2 && activeHardcoreSetTier >= 6) {
        hardcoreInvulnerableActive = true;
      }
      // Hardcore set "Tichá Meditace" (Klid, 6pc): navíc udělí Probuzení Ducha.
      if (specialization == 3 && activeHardcoreSetTier >= 6) {
        heroEffects.removeWhere((e) => e.name == "Probuzení Ducha");
        heroEffects.add(StatusEffect(name: "Probuzení Ducha", description: "+15 % heal/absorb, -15 % dmg taken", duration: 3, isBuff: true));
        message += "Tichá Meditace: " + tr("Probuzení Ducha na 3 kola!", "Awakened Spirit for 3 rounds!");
      }
    } else if (isElderTreant) {
      // Srdce Lesa: magický úder + plné HP + štít - stejná "vše v jednom" ultimátní filozofie
      // jako u ostatních tříd na tomto tieru (Boží hněv/Nebeská Harmonie...).
      int dmg = (magAtk * 3.6 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.elderTreant);
      hp = maxHp;
      final shieldGain = (maxHp * 0.35 * specAbilitySustainMod).toInt();
      bonusShield += shieldGain;
      _applyShieldCap();
      heroEffects.add(StatusEffect(name: "Srdce Lesa", description: "+35 % MaxHP štít", duration: 10, isBuff: true));
      thirdAbilityCooldown = _scaledCooldown(15);
      message = tr("Použito: Srdce Lesa! $dmg poškození, plné HP a štít (+$shieldGain).", "Used: Srdce Lesa! $dmg damage, full HP, and a shield (+$shieldGain).");
    } else if (isCrusader) {
      int dmg = (physAtk * 3.6 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.crusader);
      hp = maxHp;
      final shieldGain = (maxHp * 0.40 * specAbilitySustainMod).toInt();
      bonusShield += shieldGain;
      _applyShieldCap();
      heroEffects.add(StatusEffect(name: "Posvátný Val", description: "+40 % MaxHP štít", duration: 10, isBuff: true));
      thirdAbilityCooldown = _scaledCooldown(15);
      message = tr("Použito: Posvátný Val! $dmg poškození, plné HP a štít (+$shieldGain).", "Used: Posvátný Val! $dmg damage, full HP, and a shield (+$shieldGain).");
    } else if (isAbyssWalker) {
      int dmg = (physAtk * 3.2 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.abyssWalker);
      lifestealTurns += 10;
      if (specialization == 2) {
        final shieldGain = (maxHp * 0.30 * specAbilitySustainMod).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
      }
      thirdAbilityCooldown = _scaledCooldown(15);
      message = tr("Použito: Pekelný Žár! $dmg poškození a silný lifesteal na 10 kol.", "Used: Pekelný Žár! $dmg damage and strong lifesteal for 10 rounds.");
    } else if (isGraveWarden) {
      int dmg = (magAtk * 3.2 * specAbilityDamageMod).toInt();
      dmg = _minDmg(dmg, dmg - effDef);
      currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
      _pushFx(FxKind.normalDamage, FxSide.enemy, value: dmg, spellFxKind: SpellFxKind.graveWarden);
      hp = maxHp;
      lifestealTurns += 8;
      thirdAbilityCooldown = _scaledCooldown(15);
      message = tr("Použito: Rituál Krve a Kostí! $dmg poškození, plné HP a lifesteal na 8 kol.", "Used: Rituál Krve a Kostí! $dmg damage, full HP, and lifesteal for 8 rounds.");
    }
    _resolveCombatRound();
  }

  void useFourthAbility() {
    if (isDead || !hasRank100Class || fourthAbilityCooldown > 0) return;
    if (_checkCombatGate(isSpell: true)) return;
    if (!_spendResource(ability4Cost)) {
      message = tr("Nedostatek zdroje ($resourceName)! Potřeba: $ability4Cost, máš: $currentResourceValue.", "Not enough resource ($resourceName)! Needed: $ability4Cost, you have: $currentResourceValue.");
      notifyListeners();
      return;
    }
    final armorPen4 = runeEffect(RuneEffectType.armorPen);
    final effDef = armorPen4 > 0 ? (currentEnemyDef * (1 - armorPen4)).clamp(0, double.infinity).toInt() : currentEnemyDef;
    if (heroClass == HeroClass.warrior) {
      if (rank100Choice == 1) {
        int dmg = (physAtk * 12.0 * specAbilityDamageMod).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
        final shieldGain = (maxHp * 0.75 * specAbilitySustainMod).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
        _applyAbilityDot(dmg);
        fourthAbilityCooldown = _scaledCooldown(20);
        message = tr("Použito (Titan): Patář světa za $dmg poškození a obří štít (+$shieldGain)!", "Used (Titan): World-Breaker for $dmg damage and a huge shield (+$shieldGain)!");
      } else if (rank100Choice == 2) {
        int dmg = (physAtk * 15.0 * specAbilityDamageMod).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
        _applyAbilityDot(dmg);
        fourthAbilityCooldown = _scaledCooldown(18);
        message = tr("Použito (Nezničitelný Juggernaut): Nezničitelný úder za $dmg poškození!", "Used (Nezničitelný Juggernaut): Unstoppable Strike for $dmg damage!");
      } else if (rank100Choice == 3) {
        hp = maxHp;
        final shieldGain = (maxHp * 0.75 * specAbilitySustainMod).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
        fourthAbilityCooldown = _scaledCooldown(25);
        message = tr("Použito (Svořitel Války): Válečný vládce - plné HP a masivní štít (+$shieldGain)!", "Used (Svořitel Války): Warlord - full HP and a massive shield (+$shieldGain)!");
      }
    } else if (heroClass == HeroClass.hunter) {
      if (rank100Choice == 1) {
        int dmg = (physAtk * 13.0).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
        _applyAbilityDot(dmg);
        fourthAbilityCooldown = _scaledCooldown(16);
        message = tr("Použito (Vendeta incarnate): Mistrovská poprava za $dmg poškození!", "Used (Vendeta incarnate): Masterful Execution for $dmg damage!");
      } else if (rank100Choice == 2) {
        int dmg = (physAtk * 11.0).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
        lifestealTurns += 15;
        _applyAbilityDot(dmg);
        fourthAbilityCooldown = _scaledCooldown(18);
        message = tr("Použito (Přízrak): Přízračný skok za $dmg poškození a silný lifesteal!", "Used (Přízrak): Phantom Leap for $dmg damage and strong lifesteal!");
      } else if (rank100Choice == 3) {
        int dmg = (physAtk * 14.0).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
        hp = maxHp;
        _applyAbilityDot(dmg);
        fourthAbilityCooldown = _scaledCooldown(22);
        message = tr("Použito (Kosmický Lovec): Kosmická bouře za $dmg poškození a obnovení HP!", "Used (Kosmický Lovec): Cosmic Storm for $dmg damage and HP restored!");
      }
    } else if (heroClass == HeroClass.healer) {
      if (rank100Choice == 1) {
        hp = maxHp;
        final shieldGain = (maxHp * 0.75 * specAbilitySustainMod).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
        int dmg = (magAtk * 10.0 * specAbilityDamageMod).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
        fourthAbilityCooldown = _scaledCooldown(20);
        message = tr("Použito (Vládce magie): Astrální výbuch za $dmg poškození, plné HP a štít (+$shieldGain)!", "Used (Vládce magie): Astral Burst for $dmg damage, full HP, and a shield (+$shieldGain)!");
      } else if (rank100Choice == 2) {
        hp = maxHp;
        lifestealTurns += 20;
        fourthAbilityCooldown = _scaledCooldown(22);
        message = tr("Použito (Mistr Života): Věčný život - plné HP a trvalý lifesteal!", "Used (Mistr Života): Eternal Life - full HP and lasting lifesteal!");
      } else if (rank100Choice == 3) {
        int dmg = (magAtk * 16.0 * specAbilityDamageMod).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
        fourthAbilityCooldown = _scaledCooldown(24);
        message = tr("Použito (Svatý Osvícený): Boží paprsek smazal nepřítele za $dmg poškození!", "Used (Svatý Osvícený): Divine Ray erased the enemy for $dmg damage!");
      }
    } else if (heroClass == HeroClass.deathknight) {
      final double triple = nextSpellTriple ? 3.0 : 1.0;
      if (nextSpellTriple) { nextSpellTriple = false; soulRunes = 0; }
      if (rank100Choice == 1) {
        // Kostěný Lich: Prokletý úder + okamžitá Exploze prokletí v jednom. Detonace DoT (jako
        // Exploze prokletí ability2) obranu neignoruje - odečet je vyřešen ve fyzické složce
        // physDmg zvlášť, explodeDmg zůstává čistě z magAtk/DoT (bez mitigace, jako u ability2).
        int physDmg = (physAtk * 2.0 * triple).toInt();
        physDmg = _minDmg(physDmg, physDmg - effDef);
        int dotDmg = magAtk;
        int explodeDmg = (dotDmg * 5 * 4 * triple * curseDmgMod).toInt(); // 5 kol × 4 jako plná exploze
        currentEnemyHp -= _mitigateEnemyDamage((physDmg + explodeDmg));
        _applyKrevPassiveLifesteal(physDmg + explodeDmg);
        fourthAbilityCooldown = _scaledCooldown(22);
        message = tr("💀 Kostěný Lich: Prokletí vypáleno za ${physDmg + explodeDmg} celkového poškození!${triple > 1 ? ' ✨ TROJNÁSOBEK!' : ''}", "💀 Kostěný Lich: Curse detonated for ${physDmg + explodeDmg} total damage!${triple > 1 ? ' ✨ TRIPLED!' : ''}");
      } else if (rank100Choice == 2) {
        // Temný Reaper: masivní smrtící úder s lifestealem
        int dmg = ((physAtk + magAtk) * 5.0 * triple).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
        _applyKrevPassiveLifesteal(dmg);
        lifestealTurns += 15;
        fourthAbilityCooldown = _scaledCooldown(20);
        message = tr("⚔️ Temný Reaper: Smrtící řez za $dmg dmg + silný lifesteal!${triple > 1 ? ' ✨ TROJNÁSOBEK!' : ''}", "⚔️ Temný Reaper: Deadly Cut for $dmg dmg + strong lifesteal!${triple > 1 ? ' ✨ TRIPLED!' : ''}");
      } else if (rank100Choice == 3) {
        // Pán Duší: masivní léčení + soul runes reset na maximum
        int dmg = (magAtk * 4.0 * triple).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
        _applyKrevPassiveLifesteal(dmg);
        hp = maxHp;
        bonusShield += (maxHp * 0.5 * triple).toInt();
        _applyShieldCap();
        soulRunes = 7; // unikátní bonus Pán Duší: naplní zásobník na max místo vynulování, takže hráč
        // je hned připraven na další Vysátí duše/trojnásobek (viz _gainSoulRune) - dřív tu bylo
        // omylem "= 0" (stejné jako Kostěný Lich/Temný Reaper), takže tenhle bonus nikdy reálně nenastal.
        nextSpellTriple = false;
        fourthAbilityCooldown = _scaledCooldown(24);
        message = tr("👻 Pán Duší: Duše pohlceny za $dmg dmg, plné HP a masivní štít!${triple > 1 ? ' ✨ TROJNÁSOBEK!' : ''}", "👻 Pán Duší: Souls consumed for $dmg dmg, full HP, and a massive shield!${triple > 1 ? ' ✨ TRIPLED!' : ''}");
      }
    } else if (heroClass == HeroClass.mage) {
      if (rank100Choice == 1) {
        int dmg = (magAtk * 11.0 * specAbilityDamageMod).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
