        message = tr("Použito (Nemesis): Poprava za $dmg poškození${hpRatio < 0.3 ? ' (execute!)' : ''}!", "Used (Nemesis): Execution for $dmg damage${hpRatio < 0.3 ? ' (execute!)' : ''}!");
      } else if (rank100Choice == 2) {
        int dmg = (physAtk * 11.0 * specAbilityDamageMod).toInt();
