        int dmg = (physAtk * 7.0 * specAbilityDamageMod).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
        final shieldGain = (maxHp * 0.80 * specAbilitySustainMod).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
        fourthAbilityCooldown = _scaledCooldown(22);
        message = tr("Použito (Věčný Strážce): $dmg poškození a obří štít (+$shieldGain)!", "Used (Věčný Strážce): $dmg damage and a huge shield (+$shieldGain)!");
      } else if (rank100Choice == 2) {
        int dmg = (physAtk * 15.0 * specAbilityDamageMod).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
        fourthAbilityCooldown = _scaledCooldown(18);
        message = tr("Použito (Boží Meč): Nejvyšší poškození za $dmg!", "Used (Boží Meč): Ultimate damage for $dmg!");
      } else if (rank100Choice == 3) {
        hp = maxHp;
        final shieldGain = (maxHp * 0.40 * specAbilitySustainMod).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
        fourthAbilityCooldown = _scaledCooldown(20);
        message = tr("Použito (Posvěcení): plné HP a štít (+$shieldGain)!", "Used (Posvěcení): full HP and a shield (+$shieldGain)!");
      }
    } else if (heroClass == HeroClass.demonhunter) {
      if (rank100Choice == 1) {
        int dmg = (physAtk * 14.0 * specAbilityDamageMod).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
        fourthAbilityCooldown = _scaledCooldown(18);
        message = tr("Použito (Čepele Zkázy): Nejvyšší poškození za $dmg!", "Used (Čepele Zkázy): Ultimate damage for $dmg!");
      } else if (rank100Choice == 2) {
        int dmg = (physAtk * 7.0 * specAbilityDamageMod).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
        final shieldGain = (maxHp * 0.70 * specAbilitySustainMod).toInt();
        bonusShield += shieldGain;
        _applyShieldCap();
        lifestealTurns += 10;
        fourthAbilityCooldown = _scaledCooldown(22);
        message = tr("Použito (Pomsta Propasti): $dmg poškození, obří štít (+$shieldGain) a lifesteal!", "Used (Pomsta Propasti): $dmg damage, a huge shield (+$shieldGain), and lifesteal!");
      } else if (rank100Choice == 3) {
        int dmg = (physAtk * 9.0 * specAbilityDamageMod).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
        final dot = (dmg * 0.20 / 3).round();
        enemyEffects.removeWhere((e) => e.name == "Fel oheň");
        enemyEffects.add(StatusEffect(name: "Fel oheň", description: "Fel DoT $dot/kolo", duration: 3, isBuff: false, dotDamage: dot));
        fourthAbilityCooldown = _scaledCooldown(20);
        message = tr("Použito (Fel Zúčtování): $dmg poškození a silný Fel oheň ($dot/kolo)!", "Used (Fel Zúčtování): $dmg damage and strong Fel Fire ($dot/round)!");
      }
    } else if (heroClass == HeroClass.necromancer) {
      if (rank100Choice == 1) {
        int dmg = (magAtk * 11.0 * specAbilityDamageMod).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
        fourthAbilityCooldown = _scaledCooldown(18);
        message = tr("Použito (Armáda Nemrtvých): Nejvyšší poškození za $dmg!", "Used (Armáda Nemrtvých): Ultimate damage for $dmg!");
      } else if (rank100Choice == 2) {
        int dmg = (magAtk * 6.0 * specAbilityDamageMod).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
        final dot = (dmg * 0.30 / 3).round();
        enemyEffects.removeWhere((e) => e.name == "Rozklad");
        enemyEffects.add(StatusEffect(name: "Rozklad", description: "Rozklad $dot/kolo", duration: 3, isBuff: false, dotDamage: dot));
        fourthAbilityCooldown = _scaledCooldown(20);
        message = tr("Použito (Vládce Rozkladu): $dmg poškození a silný Rozklad ($dot/kolo)!", "Used (Vládce Rozkladu): $dmg damage and strong Decay ($dot/round)!");
      } else if (rank100Choice == 3) {
        int dmg = (magAtk * 7.0 * specAbilityDamageMod).toInt();
        dmg = _minDmg(dmg, dmg - effDef);
        currentEnemyHp -= _mitigateEnemyDamage(applyAbilityExecute(dmg, currentEnemyHp, currentEnemyMaxHp));
        hp = maxHp;
        lifestealTurns += 12;
        fourthAbilityCooldown = _scaledCooldown(22);
        message = tr("Použito (Pakt s Podsvětím): $dmg poškození, plné HP a lifesteal na 12 kol!", "Used (Pakt s Podsvětím): $dmg damage, full HP, and lifesteal for 12 rounds!");
      }
    }
    _resolveCombatRound();
  }

  void toggleAutoCombat() {
    autoCombatEnabled = !autoCombatEnabled;
    notifyListeners();
  }

  // ===== RYCHLOST AUTO-BOJE =====
  // Základní interval auto-boje (Věž) je 1.5s. Za 10g lze koupit -0.1s, až na strop 10 levelů
  // (= 0.5s, což je zároveň i nejrychlejší tick, jaký hra jinde používá - viz Timer.periodic
  // v konstruktoru GameState()).
  static const int maxAutoCombatSpeedLevel = 10;
  static const int autoCombatSpeedUpgradeCost = 10;
  int get autoCombatIntervalMs => 1500 - autoCombatSpeedLevel * 100;

  void upgradeAutoCombatSpeed() {
    if (autoCombatSpeedLevel >= maxAutoCombatSpeedLevel) {
      message = tr("Auto-boj je už na maximální rychlosti (0.5s).", "Auto-fight is already at maximum speed (0.5s).");
      notifyListeners();
      return;
    }
    if (gold < autoCombatSpeedUpgradeCost) {
      message = tr("Nedostatek zlata na zrychlení auto-boje (cena: $autoCombatSpeedUpgradeCost 🪙).", "Not enough gold to speed up auto-fight (price: $autoCombatSpeedUpgradeCost 🪙).");
      notifyListeners();
      return;
    }
    gold -= autoCombatSpeedUpgradeCost;
    autoCombatSpeedLevel++;
    final newIntervalS = (autoCombatIntervalMs / 1000).toStringAsFixed(1);
    message = tr("⚡ Auto-boj zrychlen na ${newIntervalS}s/útok!", "⚡ Auto-fight sped up to ${newIntervalS}s/attack!");
    saveGame();
    notifyListeners();
  }

