  void upgradeInventoryCapacity() {
    int cost = (maxInventorySize - 15) * 50;
    if (gold >= cost) {
      gold -= cost;
      maxInventorySize += 5;
      message = tr("Inventář zvětšen na kapacitu $maxInventorySize!", "Inventory expanded to capacity $maxInventorySize!");
      notifyListeners();
    } else {
      message = tr("Nedostatek zlata pro rozšíření inventáře.", "Not enough gold to expand the inventory.");
      notifyListeners();
    }
  }

  // ===== AUTO-OBLÉKNUTÍ: nasadí nejsilnější kus z batohu do každého slotu (podle itemPowerScore),
  // pokud je silnější než to, co už tam nosíš. Relic slot se přeskakuje záměrně - relic je vázaný
  // na aktuální třídu/specializaci, ne na obecnou "sílu", takže by auto-obléknutí mohlo nasadit
  // relic pro úplně jinou specializaci jen proto, že má vyšší power score.
  void autoEquipBestGear() {
    int swapped = 0;
    for (final slot in EquipSlot.values) {
      if (slot == EquipSlot.relic) continue;
      final cap = slot == EquipSlot.accessory ? 2 : 1;
      final candidates = inventory.where((i) => i.slot == slot && !i.isActive && !i.isConsumable).toList()
        ..sort((a, b) => itemPowerScore(b).compareTo(itemPowerScore(a)));
      for (final candidate in candidates) {
        final currentInSlot = equipment.where((e) => e.slot == slot).toList();
        if (currentInSlot.length < cap) {
          candidate.isActive = true;
          swapped++;
        } else {
          final weakest = currentInSlot.reduce((a, b) => itemPowerScore(a) <= itemPowerScore(b) ? a : b);
          if (itemPowerScore(candidate) > itemPowerScore(weakest)) {
            weakest.isActive = false;
            candidate.isActive = true;
            swapped++;
          }
        }
      }
    }
    message = swapped > 0
        ? tr("⚡ Auto-obléknuto: $swapped kus(ů) vyměněno za silnější (Relic se řídí zvlášť, viz specializace).", "⚡ Auto-equipped: $swapped piece(s) swapped for stronger ones (Relic is handled separately via specialization).")
        : tr("Už máš nasazené to nejlepší, co máš v batohu.", "You already have the best gear from your bag equipped.");
    notifyListeners();
  }

  void toggleItemActive(Item item) {
    if (!item.isActive) {
      if (item.slot == null) {
        message = tr("Tento předmět nelze nasadit.", "This item cannot be equipped.");
        notifyListeners();
        return;
      }
      // Sloty podle typu: 1x zbraň, 1x zbroj, 2x přívěsek (celkem 4 aktivní kusy).
      final int cap = item.slot == EquipSlot.accessory ? 2 : 1;
      final currentInSlot = equipment.where((e) => e.slot == item.slot).toList();
      if (currentInSlot.length >= cap) {
        // Slot je plný - místo hlášky "nejdřív sundej" rovnou vyměníme za nejslabší kus ve
        // stejném slotu (dle itemPowerScore), ať nemusíš klikat sundat + nasadit zvlášť.
        final weakest = currentInSlot.reduce((a, b) => itemPowerScore(a) <= itemPowerScore(b) ? a : b);
        weakest.isActive = false;
        item.isActive = true;
        message = tr("Vyměněno: ${weakest.name} → ${item.name} (${slotDisplayName(item.slot)}).", "Swapped: ${weakest.name} → ${item.name} (${slotDisplayName(item.slot)}).");
        notifyListeners();
        return;
      }
      item.isActive = true;
      message = tr("Předmět ${item.name} nasazen (${slotDisplayName(item.slot)}).", "Item ${item.name} equipped (${slotDisplayName(item.slot)}).");
    } else {
      item.isActive = false;
      message = tr("Předmět ${item.name} odložen.", "Item ${item.name} unequipped.");
    }
    notifyListeners();
  }

  // ===== BANKA — přesun mezi inventářem a trvalým úložištěm =====
  void depositToBank(Item item) {
    if (item.isActive) {
      message = tr("Nejdřív předmět odlož, než ho uložíš do Banky.", "Unequip the item first before storing it in the Bank.");
      notifyListeners();
      return;
    }
    if (item.isLocked) {
      message = tr("Zamčený předmět nelze uložit do Banky. Nejdřív ho odemkni.", "A locked item cannot be stored in the Bank. Unlock it first.");
      notifyListeners();
      return;
    }
    if (bankItems.length >= bankUnlockedSlots) {
      message = bankUnlockedSlots >= bankMaxSize
          ? "Banka je plná (max $bankMaxSize kusů)."
          : "Banka je plná (odemčeno $bankUnlockedSlots/$bankMaxSize slotů) - odemkni další slot za zlato.";
      notifyListeners();
      return;
    }
    if (!inventory.remove(item)) return;
    bankItems.add(item);
    message = tr("${item.name} uložen do Banky.", "${item.name} stored in the Bank.");
    notifyListeners();
  }

  void withdrawFromBank(Item item) {
    if (bagItemCount >= maxInventorySize) {
      message = tr("Inventář je plný - nejdřív ho ulehči, než z Banky něco vytáhneš.", "Your inventory is full - free up space first before withdrawing from the Bank.");
      notifyListeners();
      return;
    }
    if (!bankItems.remove(item)) return;
    inventory.add(item);
    message = tr("${item.name} vytažen z Banky do inventáře.", "${item.name} withdrawn from the Bank into your inventory.");
    notifyListeners();
  }

  void upgradeBlacksmith() {
    int cost = blacksmithRank * 400;
    if (magicDust >= cost) {
      magicDust -= cost;
      blacksmithRank++;
      message = tr("Theodor vylepšen na rank $blacksmithRank!", "Theodor upgraded to rank $blacksmithRank!");
      notifyListeners();
    }
  }

  void unlockResourceDrop() {
    if (blacksmithRank >= 5 && !resourceDropUnlocked && magicDust >= 1000) {
      magicDust -= 1000;
      resourceDropUnlocked = true;
      message = tr("Schopnost sběru surovin odemčena!", "Material gathering ability unlocked!");
      notifyListeners();
    }
  }

  void craftItem(String rarityType) {
    Rarity itemRarity = Rarity.common;
    Map<String, int> itemStats = {};
    final allStats = ["Strength", "Agility", "Wisdom", "Vitality", "Armor"];
    final combatStats = ["Crit", "Dodge", "Block", "Attack Speed"];
    final basicSlots = [EquipSlot.weapon, EquipSlot.armor, EquipSlot.accessory, EquipSlot.gloves, EquipSlot.boots, EquipSlot.helmet, EquipSlot.belt, EquipSlot.cloak, EquipSlot.shoulders];
    final chosenSlot = basicSlots[Random().nextInt(basicSlots.length)];
    if (rarityType == "rare" && blacksmithRank >= 5) {
      if (materials >= 5) {
        materials -= 5;
        itemRarity = Rarity.rare;
        String s1 = allStats[Random().nextInt(allStats.length)];
        String s2 = allStats.where((s) => s != s1).toList()[Random().nextInt(allStats.length - 1)];
        itemStats[s1] = (1 * blacksmithRank).round();
        itemStats[s2] = (0.5 * blacksmithRank).round();
      } else {
        message = tr("Nedostatek surovin (potřeba 5x suroviny).", "Not enough materials (need 5x materials).");
        notifyListeners();
        return;
      }
    } else if (rarityType == "epic" && blacksmithRank >= 10) {
      if (materials >= 15) {
        materials -= 15;
        itemRarity = Rarity.epic;
        List<String> shuffled = List.from(allStats)..shuffle();
        itemStats[shuffled[0]] = (1.5 * blacksmithRank).round();
        itemStats[shuffled[1]] = (0.8 * blacksmithRank).round();
        itemStats[shuffled[2]] = (0.7 * blacksmithRank).round();
        // 40% šance na sekundární bojový stat (Crit/Dodge/Block).
        if (Random().nextDouble() < 0.4) {
          final secondaryStat = combatStats[Random().nextInt(combatStats.length)];
          itemStats[secondaryStat] = (0.3 * blacksmithRank).round();
        }
      } else {
        message = tr("Nedostatek surovin (potřeba 15x suroviny).", "Not enough materials (need 15x materials).");
        notifyListeners();
        return;
      }
    } else if (rarityType == "legendary" && blacksmithRank >= 15) {
      if (materials >= 80) {
        materials -= 80;
        itemRarity = Rarity.legendary;

        // 15% šance, že se místo obyčejného legendary vykove kus SETu (zelená) - jen pokud má
        // hráč zvolenou specializaci (SET je vázaný na (třída, specializace), viz activeGearSetDef).
        // Suroviny už jsou odečtené výše, takže bez aktivního setu tahle větev jen propadne dál
        // na normální legendary craft níže - hráč o materiály nepřijde naprázdno.
        final craftSet = activeGearSetDef;
        if (craftSet != null && Random().nextDouble() < 0.15) {
          if (bagItemCount >= maxInventorySize) {
            message = tr("Inventář je plný!", "Your inventory is full!");
            notifyListeners();
            return;
          }
          const setSlots = [EquipSlot.armor, EquipSlot.accessory, EquipSlot.accessory, EquipSlot.gloves, EquipSlot.boots, EquipSlot.helmet, EquipSlot.belt, EquipSlot.cloak, EquipSlot.shoulders];
          final setSlot = setSlots[Random().nextInt(setSlots.length)];
          inventory.add(_createSetItem(craftSet, setSlot, blacksmithRank));
          message = tr("✨ Vykován SET předmět: ${craftSet.name} (${slotDisplayName(setSlot)})!", "✨ SET item forged: ${craftSet.name} (${slotDisplayName(setSlot)})!");
          notifyListeners();
          return;
        }

        List<String> shuffled = List.from(allStats)..shuffle();
        itemStats[shuffled[0]] = (3 * blacksmithRank).round();
        itemStats[shuffled[1]] = (2.5 * blacksmithRank).round();
        itemStats[shuffled[2]] = (2 * blacksmithRank).round();
        // 60% šance na sekundární bojový stat (Crit/Dodge/Block), legendary má vyšší šanci i hodnotu.
        if (Random().nextDouble() < 0.6) {
          final secondaryStat = combatStats[Random().nextInt(combatStats.length)];
          itemStats[secondaryStat] = (0.5 * blacksmithRank).round();
        }
      } else {
        message = tr("Nedostatek materiálu (potřeba celkem 80 kusů).", "Not enough material (need 80 pieces total).");
        notifyListeners();
        return;
      }
    } else {
      message = tr("Požadavek nesplněn.", "Requirement not met.");
      notifyListeners();
      return;
    }
    if (bagItemCount >= maxInventorySize) {
      message = tr("Inventář je plný!", "Your inventory is full!");
      notifyListeners();
      return;
    }
    _applySlotClassBias(itemStats, chosenSlot);
    inventory.add(Item(
      name: "Vybavení (${itemRarity.name.toUpperCase()})",
      value: 200 * blacksmithRank,
      stats: itemStats,
      rarity: itemRarity,
      slot: chosenSlot,
    ));
    message = tr("Vyrobeno ${itemRarity.name.toUpperCase()} vybavení (${slotDisplayName(chosenSlot)})!", "Crafted ${itemRarity.name.toUpperCase()} gear (${slotDisplayName(chosenSlot)})!");
    notifyListeners();
  }

  void salvageItem(Item item) {
    if (item.isArtifact) {
      message = tr("${item.name} je artefakt - nelze ho zničit ani roztavit.", "${item.name} is an artifact - it cannot be destroyed or salvaged.");
      notifyListeners();
      return;
    }
    inventory.remove(item);
    int gain = _salvageMaterialGain(item.rarity);
    materials += gain;
    message = gain > 0 ? tr("Předmět roztaven (+$gain surovin).", "Item salvaged (+$gain materials).") : tr("Předmět roztaven.", "Item salvaged.");
    notifyListeners();
  }

  // Odměna surovin za roztavení podle vzácnosti - fixní/šancí, NE odvozeno z hodnoty předmětu
  // nebo aktuální zásoby (viz historie - dřív byl vzorec self-referenční a nekontrolovatelně
  // rostl). Legendary 2 (jisté), Epic 1 (jisté), Rare 50 % šance na 1, Common 25 % šance na 1.
  int _salvageMaterialGain(Rarity rarity) {
    switch (rarity) {
      case Rarity.legendary:
        return 2;
      case Rarity.epic:
        return 1;
      case Rarity.rare:
        return Random().nextDouble() < 0.50 ? 1 : 0;
      case Rarity.common:
        return Random().nextDouble() < 0.25 ? 1 : 0;
      case Rarity.artifact:
        return 0;
    }
  }

  // Hromadně roztaví všechno nenasazené a nezamčené vybavení dané kvality (např. "všechno RARE").
  // Zamčené (🔒) kusy a nasazené vybavení se přeskočí stejně jako u salvageItem(); artefakt se
  // do žádné kvality nepočítá (viz Rarity.artifact - vyhrazeno pro Prsten Osudu).
  void salvageAllByRarity(Rarity targetRarity) {
    final targets = inventory.where((i) => !i.isConsumable && !i.isActive && !i.isArtifact && !i.isLocked && i.rarity == targetRarity).toList();
    if (targets.isEmpty) {
      final lockedCount = inventory.where((i) => !i.isConsumable && !i.isActive && !i.isArtifact && i.isLocked && i.rarity == targetRarity).length;
      message = lockedCount > 0
          ? tr("Všechno ${targetRarity.name.toUpperCase()} vybavení je zamčené (🔒) - nejdřív ho odemkni, pokud ho chceš roztavit.", "All ${targetRarity.name.toUpperCase()} gear is locked (🔒) - unlock it first if you want to salvage it.")
          : tr("Žádné nenasazené ${targetRarity.name.toUpperCase()} vybavení k roztavení.", "No unequipped ${targetRarity.name.toUpperCase()} gear to salvage.");
      notifyListeners();
      return;
    }
    int materialsGain = 0;
    for (final item in targets) {
      inventory.remove(item);
      final gain = _salvageMaterialGain(item.rarity);
      materials += gain;
      materialsGain += gain;
    }
    message = tr("Roztaveno ${targets.length}× ${targetRarity.name.toUpperCase()} vybavení (+$materialsGain surovin).", "Salvaged ${targets.length}× ${targetRarity.name.toUpperCase()} gear (+$materialsGain materials).");
    notifyListeners();
  }

  // ===== VYLEPŠOVÁNÍ LEGENDÁRNÍHO/SET VYBAVENÍ =====
  // Každá úroveň (+1 až +10) přidá +8 % ke všem statům daného předmětu (viz Item.upgradeMultiplier).
  // Cena roste s aktuální úrovní vybavení, aby vyšší úrovně byly čím dál nákladnější.
  int upgradeEssenceCost(Item item) => (item.upgradeLevel + 1) * 3;
  int upgradeGoldCost(Item item) => (item.upgradeLevel + 1) * 500;

  void upgradeItem(Item item) {
    if (!item.isUpgradable) {
      message = tr("Vylepšovat lze pouze legendární (a SET) vybavení.", "Only legendary (and SET) gear can be upgraded.");
      notifyListeners();
      return;
    }
    if (item.upgradeLevel >= Item.maxUpgradeLevel) {
      message = tr("${item.name} je už na maximální úrovni vylepšení (+${Item.maxUpgradeLevel}).", "${item.name} is already at maximum upgrade level (+${Item.maxUpgradeLevel}).");
      notifyListeners();
      return;
    }
    final essenceCost = upgradeEssenceCost(item);
    final goldCost = upgradeGoldCost(item);
    if (legendaryEssence < essenceCost || gold < goldCost) {
      message = tr("Nedostatek zdrojů pro vylepšení (potřeba: $essenceCost 🔥 Esence, $goldCost 🪙 Zlato).", "Not enough resources to upgrade (needed: $essenceCost 🔥 Essence, $goldCost 🪙 Gold).");
      notifyListeners();
      return;
    }
    legendaryEssence -= essenceCost;
    gold -= goldCost;
    item.upgradeLevel++;
    message = tr("✨ ${item.name} vylepšeno na +${item.upgradeLevel}! (+${(item.upgradeLevel * Item.upgradeBonusPerLevel * 100).toInt()} % staty)", "✨ ${item.name} upgraded to +${item.upgradeLevel}! (+${(item.upgradeLevel * Item.upgradeBonusPerLevel * 100).toInt()}% stats)");
    notifyListeners();
  }

  // ===== VYLEPŠOVÁNÍ SET VYBAVENÍ ZA SUROVINY =====
  // Druhá, nezávislá cesta jak posílit SET item (na rozdíl od upgradeItem výše, který běží na
  // Esenci+Zlato a funguje na legendary i SET). Tahle běží na ocel/kůže/dřevo (stejné suroviny
  // jako crafting) a funguje JEN na SET vybavení (setId != null) - protože kombinuje obojí
  // (až +80 % z Esence × +60 % ze surovin), plně vylepšený SET item reálně předčí kovářský
  // legendary kus, který žádný z těchto dvou systémů nemá. Viz Item.materialUpgradeMultiplier.
  int materialUpgradeCost(Item item) => (setSlotUpgradeLevel(item) + 1) * 8;
  void upgradeSetMaterial(Item item) {
    final key = setSlotUpgradeKey(item);
    if (key == null) {
      message = tr("Materiálem lze vylepšit jen SET vybavení (běžné i Hardcore).", "Only SET gear (regular or Hardcore) can be upgraded with materials.");
      notifyListeners();
      return;
    }
    final current = setSlotUpgradeLevels[key] ?? 0;
    if (current >= Item.maxMaterialUpgradeLevel) {
      message = tr("${slotDisplayName(item.slot)} setu je už na maximální úrovni +${Item.maxMaterialUpgradeLevel}.", "The ${slotDisplayName(item.slot)} set piece is already at maximum level +${Item.maxMaterialUpgradeLevel}.");
      notifyListeners();
      return;
    }
    final cost = (current + 1) * 8;
    if (materials < cost) {
      message = tr("Nedostatek surovin (potřeba: ${cost}x suroviny).", "Not enough materials (needed: ${cost}x materials).");
      notifyListeners();
      return;
    }
    materials -= cost;
    setSlotUpgradeLevels[key] = current + 1;
    message = tr("🔨 ${slotDisplayName(item.slot)} tohoto setu vylepšen na +${current + 1}. Upgrade platí pro každý současný i budoucí kus stejného setu a slotu.", "🔨 The ${slotDisplayName(item.slot)} piece of this set was upgraded to +${current + 1}. The upgrade applies to every current and future piece of the same set and slot.");
    notifyListeners();
  }

  // ===== ZÁMKY: OCHRANA ITEMŮ PŘED ZNIČENÍM PO SMRTI =====
  // Nasazené vybavení přežije smrt vždy zdarma (viz resetGame()). Zámky navíc chrání i itemy
  // v batohu, které zrovna nejsou nasazené. Cena roste za každý další zámek: 500, 1000, 1500, 2000 g.
  int get nextLockSlotCost => 500 * (unlockedLockSlots + 1);
  int get lockedItemCount => inventory.where((i) => i.isLocked).length;

  void unlockLockSlot() {
    if (unlockedLockSlots >= maxLockSlots) {
      message = tr("Už máš odemčené všechny zámky (max $maxLockSlots).", "You already have all locks unlocked (max $maxLockSlots).");
      notifyListeners();
      return;
    }
    final cost = nextLockSlotCost;
    if (gold < cost) {
      message = tr("Nedostatek zlata na odemčení dalšího zámku (cena: $cost 🪙).", "Not enough gold to unlock another lock (price: $cost 🪙).");
      notifyListeners();
      return;
    }
    gold -= cost;
    unlockedLockSlots++;
    message = tr("🔒 Odemčen zámek $unlockedLockSlots/$maxLockSlots! Nyní můžeš uzamknout $unlockedLockSlots ${unlockedLockSlots == 1 ? 'předmět' : 'předměty'} proti zničení po smrti.", "🔒 Lock $unlockedLockSlots/$maxLockSlots unlocked! You can now lock $unlockedLockSlots ${unlockedLockSlots == 1 ? 'item' : 'items'} against destruction on death.");
    notifyListeners();
  }

  void toggleItemLock(Item item) {
    if (item.isConsumable) {
      message = tr("Lektvary nelze zamykat.", "Potions cannot be locked.");
      notifyListeners();
      return;
    }
    if (item.isLocked) {
      item.isLocked = false;
      message = tr("${item.name} odemčen.", "${item.name} unlocked.");
    } else {
      if (lockedItemCount >= unlockedLockSlots) {
        message = unlockedLockSlots == 0 ? tr("Nejprve si u kováře odemkni zámek za $nextLockSlotCost 🪙.", "First unlock a lock slot at the blacksmith for $nextLockSlotCost 🪙.") : tr("Všechny zámky ($unlockedLockSlots/$unlockedLockSlots) jsou už obsazené jinými itemy.", "All locks ($unlockedLockSlots/$unlockedLockSlots) are already occupied by other items.");
        notifyListeners();
        return;
      }
      item.isLocked = true;
      message = tr("🔒 ${item.name} uzamčen - přežije i smrt hrdiny.", "🔒 ${item.name} locked - will survive even the hero's death.");
    }
    notifyListeners();
  }

  void upgradeAlchemist() {
    int cost = alchemistRank * 500;
    if (magicDust >= cost) {
      magicDust -= cost;
      alchemistRank++;
      message = tr("Alchymista vylepšen na rank $alchemistRank!", "Alchemist upgraded to rank $alchemistRank!");
      notifyListeners();
    }
  }

  // Sleva na lektvary z tržiště: 2 % za každý rank alchymisty nad 1.
  // Rank 1 = 0 % sleva, rank 2 = 2 %, rank 10 = 18 %...
  // Omezeno na max. 70 %, aby lektvary nebyly nikdy zadarmo.
  double get potionDiscount => ((alchemistRank - 1) * 0.02).clamp(0.0, 0.7);

  int getPotionPrice(int basePrice) {
    final discounted = basePrice * (1 - potionDiscount);
    // Kulaté nahoru a nikdy pod 1 zlato.
    return discounted.ceil().clamp(1, basePrice);
  }

  void unlockAutoHeal() {
    if (magicDust >= 1000 && !autoHealUnlocked) {
      magicDust -= 1000;
      autoHealUnlocked = true;
      autoHealEnabled = true;
      message = tr("Automatické léčení odemčeno!", "Auto-Heal unlocked!");
      notifyListeners();
    }
  }

  void addTalent(String name) {
    if (talentPoints > 0) {
      talents[name] = talents[name]! + 1;
      talentPoints--;
      message = tr("Talent $name vylepšen!", "Talent $name upgraded!");
      notifyListeners();
    }
  }

  // Stejné jako addTalent(), jen najednou utratí až `count` bodů (oříznuto na to, co hráč
  // reálně má) - pro tlačítko "+10" v UI, ať se nemusí ťukat desetkrát po jednom.
  void addTalentMulti(String name, int count) {
    final spend = min(count, talentPoints);
    if (spend <= 0) return;
    talents[name] = talents[name]! + spend;
    talentPoints -= spend;
    message = tr("Talent $name vylepšen (+$spend)!", "Talent $name upgraded (+$spend)!");
    notifyListeners();
  }

  // Zastaví hru a vyžádá potvrzení od hráče, než se smaže postup (aby ho neztratil jedním
  // nešťastným zásahem bez varování). Skutečné smazání proběhne až v confirmDeath().
  // Vybavené a zamčené itemy přežijí smrt - spočítá jen to, co se skutečně zničí (do Magic Dust).
  List<Item> get _itemsLostOnDeath => inventory.where((i) => !i.isActive && !i.isLocked).toList();

  void _triggerDeath(String reason, {String killer = ""}) {
    int salvagedDust = 0;
    for (var item in _itemsLostOnDeath) {
      salvagedDust += (item.value ~/ 4);
    }
    deathSalvagePreview = salvagedDust;
    deathKiller = killer;
    isDead = true;
    autoCombatEnabled = false;
    isInLair = false;
    message = reason;
    notifyListeners();
  }

  // Epitaf zobrazený v death dialogu - jméno, aktivní titul, pár klíčových statů a kdo hrdinu
  // zabil. Čte se live (floor/level/gearScore ještě nejsou resetnuté - to se stane až
  // v resetGame(), volaném teprve z confirmDeath() po zavření dialogu), jen deathKiller je
  // potřeba ukládat zvlášť, protože "aktuální nepřítel" se jmenuje jinak v každém módu
  // (currentEnemyName/currentLairBossName/worldBossName/...).
  String get deathEpitaph {
    final displayName = heroName.isNotEmpty ? heroName : "Bezejmenný hrdina";
    final className = heroClassLabel(heroClass);
    final title = activeTitle != null ? achievementDefs[activeTitle]!.title : null;
    final totalAch = AchievementId.values.length;
    final unlockedAch = unlockedAchievements.length;
    final buf = StringBuffer();
    buf.writeln("⚰️ Zde odpočívá $displayName${title != null ? ', $title,' : ','} $className.");
    buf.writeln("Dosáhl úrovně $level, vystoupal do patra $floor Věže Osudu (Gear Score $gearScore).");
    buf.writeln("Splnil $unlockedAch z $totalAch achievementů.");
    if (deathKiller.isNotEmpty) buf.write("Zabit rukou: $deathKiller.");
    return buf.toString().trim();
  }

  // Voláno z UI po potvrzení dialogu smrti - teprve teď se postup skutečně smaže.
  void confirmDeath() {
    isDead = false;
    final bool isFirstDeathEver = totalDeaths == 0; // zjištěno PŘED incrementem níže
    totalDeaths++;
    _checkAchievements();
    // Zaznamenat pokus do žebříčku, než resetGame() smaže patro a třídu.
    if (heroClass != HeroClass.none && heroName.isNotEmpty) {
      ladder.add(LadderEntry(heroName: heroName, heroClass: heroClass, floorReached: floor, date: DateTime.now()));
      ladder.sort((a, b) => b.floorReached.compareTo(a.floorReached));
      if (ladder.length > 50) ladder = ladder.sublist(0, 50); // omezit velikost historie
      saveGame(); // auto-uložení po zápisu do žebříčku
    }
    heroName = ""; // Nový hrdina po smrti dostane nové jméno.
    resetGame();
    if (isFirstDeathEver) {
      // Tutorial gate: první smrt v historii účtu dá útěchu ve zlatě - hráč teď nemůže dělat nic
      // jiného než si najmout svého prvního společníka (viz mustHireFirstCompanion + overlay
      // v hlavní obrazovce), což je od teď zdarma (viz toggleCompanion), takže tohle zlato už
      // není vázané na jeho cenu, jen obecná útěcha do dalšího pokusu.
      // Přidáno AŽ PO resetGame(), aby ho neshodila poloviční penalizace zlata za smrt.
      gold += 150;
      message += tr("\n\n💀 Tvá první smrt tě naučila cenit si spojenců. Najmi si prvního společníka v Družině zdarma, než budeš pokračovat.",
          "\n\n💀 Your first death taught you to value allies. Hire your first companion in the Companions screen for free before you continue.");
    }
  }

  void resetGame() {
    int salvagedDust = 0;
    final survivors = <Item>[];
    for (var item in inventory) {
      if (item.isActive || item.isLocked || item.isArtifact) {
        survivors.add(item); // Nasazené/zamčené itemy i artefakty (Prsten Osudu, artefaktová zbraň) přežijí smrt hrdiny - artefakt nelze zničit ani roztavit, viz salvageItem().
      } else {
        salvagedDust += (item.value ~/ 4);
      }
    }
    magicDust += salvagedDust;
    hp = 150;
    gold = (gold * 0.5).floor(); // Smrt stojí polovinu zlata, zbytek zůstává.
    floor = 1;
    enemiesDefeatedOnFloor = 0;
    // Tower modifikátor (Crit/Block/Dodge/Absorb stacky nepřítele, viz enemyCritChance/DodgeChance/
    // BlockChance a currentEnemyShield) se váže na aktuální běh Věže od patra 1 - po smrti hrdiny
    // se Věž vrací na patro 1, takže se maže i tohle.
    towerModCritStacks = 0;
    towerModBlockStacks = 0;
    towerModDodgeStacks = 0;
    towerModAbsorbStacks = 0;
    heroClass = HeroClass.none;
    inventory = survivors;
    talents = {"Strength": 0, "Agility": 0, "Wisdom": 0, "Vitality": 0};
    // Level je permanentní (nereseuje se) - při smrti dostaneš zpět k rozdání
    // tolik nerozdaných talentových bodů, kolik je tvůj aktuální (permanentní) level, PLUS
    // natrvalo vydělané body z Lairu (permanentLairTalentPoints) - dřív se tu přepisovaly
    // natvrdo na level a Lair progress (i když samotný lairFloorTalentClaims Set přežil smrt)
    // se tak fakticky ztrácel, protože se z něj nikdy znovu nedopočítal do talentPoints.
    talentPoints = level + permanentLairTalentPoints;
    // Tower talent-progress (floor-clear body) se resetuje se smrtí jako talenty samotné -
    // příští život může tyhle body na Tower patrech znovu vydělat. lairFloorTalentClaims se
    // ZÁMĚRNĚ NERESETUJE (permanentní progress, viz jeho definice výš) - to je celý smysl:
    // po smrti nemusí hráč farmit VŠECHNY obtížnosti od nuly, Lair progres mu zůstává.
    towerFloorTalentClaims.clear();
    lifestealTurns = 0;
    bonusShield = 0;
    _lastKnownBonusShield = 0; // sync pro _applyShieldCap() FX diffing
    soulRunes = 0;
    nextSpellTriple = false;
    rank100Choice = 0;
    isInLair = false;
    henryTurnCounter = 0;
    vexTurnCounter = 0;
    fenwickTurnCounter = 0;
    thorinTurnCounter = 0;
    rawenTurnCounter = 0;
    nextAttackGuaranteedCrit = false;
    _resetResources();
    heroEffects.clear();
    enemyEffects.clear();
    message = survivors.isEmpty ? "Zemřel jsi. Předměty přeměněny na $salvagedDust Magic Dust!" : "Zemřel jsi. Předměty přeměněny na $salvagedDust Magic Dust! (${survivors.length} nasazených/zamčených kusů přežilo)";
    // Smrt tě posune o JEDNU úroveň obtížnosti dolů (skutečné riziko Hardcore/Předpeklí/Peklo) -
    // ne rovnou zpátky na Normal, jen o krok zpátky, kam ses přehnal.
    // Hardcore/Předpeklí/Peklo jsou exkluzivní (viz setDifficultyTier) - krok zpět znamená
    // nastavit o 1 nižší tier, ne jen vypnout aktuální flag (to by skočilo rovnou na Normal).
    if (pekloMode) {
      pekloMode = false;
      predpekliMode = true;
      message += tr("\n😈 Peklo tě přemohlo - spadl jsi zpátky do Předpeklí.", "\n😈 Hell overwhelmed you - you fell back to the Netherworld.");
    } else if (predpekliMode) {
      predpekliMode = false;
      hardcoreMode = true;
      message += tr("\n🔥 Předpeklí tě přemohlo - spadl jsi zpátky do Hardcore Mode.", "\n🔥 The Netherworld overwhelmed you - you fell back to Hardcore Mode.");
    } else if (hardcoreMode) {
      hardcoreMode = false;
      activeCurse = CurseOfFate.none;
      message += tr("\n☠ Hardcore tě přemohl - vrátil ses do Normal módu.", "\n☠ Hardcore overwhelmed you - you returned to Normal mode.");
    }
    _generateNextEnemy();
    notifyListeners();
  }

  void _tryDropItem() {
    if (bagItemCount >= maxInventorySize) return;
    final rng = Random();
    final dropSet = activeGearSetDef;
    if (floor >= 50 && dropSet != null && rng.nextDouble() < (0.08 + curseLootBonus)) {
      const setSlots = [EquipSlot.armor, EquipSlot.accessory, EquipSlot.accessory, EquipSlot.gloves, EquipSlot.boots, EquipSlot.helmet, EquipSlot.belt, EquipSlot.cloak, EquipSlot.shoulders];
      final setSlot = setSlots[rng.nextInt(setSlots.length)];
      final difficultyPower = [1.0, 1.5, 2.0, 3.0][difficultyTier];
      final powerLevel = max(1, ((floor / 5) * difficultyPower).ceil());
      inventory.add(_createSetItem(dropSet, setSlot, powerLevel));
      message = tr("✨ Boss upustil SET předmět: ${dropSet.name} (${slotDisplayName(setSlot)})!", "✨ The boss dropped a SET item: ${dropSet.name} (${slotDisplayName(setSlot)})!");
      return;
    }
    if (rng.nextDouble() >= (0.5 + curseLootBonus)) return;

    // Rarita určuje počet statů stejně jako u kováře. Vyšší obtížnost zvyšuje roll, ne pouze drop chance.
    final roll = rng.nextDouble();
    final Rarity rarity = roll < 0.45 ? Rarity.common : (roll < 0.75 ? Rarity.rare : (roll < 0.93 ? Rarity.epic : Rarity.legendary));
    final difficultyMult = [1.0, 1.5, 2.0, 3.0][difficultyTier];
    final floorPower = max(1, (floor / 5).ceil());
    final power = max(1, (max(floorPower, blacksmithRank * 0.75) * difficultyMult).round());
    final mainStats = <String>["Strength", "Agility", "Wisdom", "Vitality", "Armor"]..shuffle(rng);
    final combatStats = <String>["Crit", "Dodge", "Block", "Attack Speed"];
    final itemStats = <String, int>{};

    switch (rarity) {
      case Rarity.common:
        itemStats[mainStats[0]] = max(1, (1.0 * power).round());
        break;
      case Rarity.rare:
        itemStats[mainStats[0]] = max(1, (1.25 * power).round());
        itemStats[mainStats[1]] = max(1, (0.75 * power).round());
        break;
      case Rarity.epic:
        itemStats[mainStats[0]] = max(1, (1.8 * power).round());
        itemStats[mainStats[1]] = max(1, (1.2 * power).round());
        itemStats[mainStats[2]] = max(1, (0.9 * power).round());
        if (rng.nextDouble() < 0.40) itemStats[combatStats[rng.nextInt(combatStats.length)]] = max(1, (0.30 * power).round());
        break;
      case Rarity.legendary:
        itemStats[mainStats[0]] = max(1, (3.2 * power).round());
        itemStats[mainStats[1]] = max(1, (2.6 * power).round());
        itemStats[mainStats[2]] = max(1, (2.1 * power).round());
        if (rng.nextDouble() < 0.60) itemStats[combatStats[rng.nextInt(combatStats.length)]] = max(1, (0.55 * power).round());
        break;
      case Rarity.artifact:
        break;
    }
    final slots = [EquipSlot.weapon, EquipSlot.armor, EquipSlot.accessory, EquipSlot.gloves, EquipSlot.boots, EquipSlot.helmet, EquipSlot.belt, EquipSlot.cloak, EquipSlot.shoulders];
    final chosenSlot = slots[rng.nextInt(slots.length)];
    _applySlotClassBias(itemStats, chosenSlot);
    final item = Item(name: "Kořist z bosse (${rarity.name.toUpperCase()})", value: 50 * floor * (difficultyTier + 1), stats: itemStats, rarity: rarity, slot: chosenSlot);
    inventory.add(item);
    message = tr("Získal jsi ${rarity.name.toUpperCase()} ${slotDisplayName(chosenSlot)}: ${itemStats.entries.map((e) => '${e.key} +${e.value}').join(', ')}.", "You obtained ${rarity.name.toUpperCase()} ${slotDisplayName(chosenSlot)}: ${itemStats.entries.map((e) => '${e.key} +${e.value}').join(', ')}.");
  }

  void useItem(Item item) {
    if (item.name == "Léčivý lektvar") {
      if (healPotionCooldown > 0) {
        message = tr("Léčivý lektvar je ještě na cooldownu ($healPotionCooldown kolo).", "Healing potion is still on cooldown ($healPotionCooldown round).");
        notifyListeners();
        return;
      }
      healPotionCooldown = 1;
      final double healPercent = 0.4 + (alchemistRank * 0.01);
      final heal = (maxHp * healPercent * curseDarknessMod * gemSustainBonus).toInt(); // Temnota (curse) vs. Gem Temnoty (opačný efekt)
      int newHp = hp + heal;
      if (newHp > maxHp && canAbsorbOverheal) {
        bonusShield += (newHp - maxHp);
        _applyShieldCap();
        hp = maxHp;
        heroEffects.add(StatusEffect(name: "Overheal Štít", description: "Navýšen štít", duration: 5, isBuff: true));
        message = tr("Vypil jsi lektvar. Overheal převeden na štít (+$bonusShield).", "You drank the potion. Overheal converted into a shield (+$bonusShield).");
      } else {
        hp = newHp.clamp(0, maxHp);
        message = tr("Vypil jsi lektvar (léčba +$heal HP).", "You drank the potion (healed +$heal HP).");
      }

      item.stackCount--;
      if (item.stackCount <= 0) inventory.remove(item);
    } else if (item.name == "Upíří Lektvar") {
      lifestealTurns = 10 + alchemistRank;
      heroEffects.add(StatusEffect(name: "Upíří Lektvar", description: "Lifesteal 20%", duration: 10 + alchemistRank, isBuff: true));
      item.stackCount--;
      if (item.stackCount <= 0) inventory.remove(item);
      message = tr("Upíří lektvar aktivován na $lifestealTurns tahů!", "Vampire Potion activated for $lifestealTurns turns!");
    } else if (item.name == "Lektvar Síly") {
      heroEffects.removeWhere((e) => e.name == "Lektvar Síly"); // neskládat efekt, jen obnovit dobu trvání
      heroEffects.add(StatusEffect(name: "Lektvar Síly", description: "+15% Fyzický útok", duration: 5, isBuff: true));
      item.stackCount--;
      if (item.stackCount <= 0) inventory.remove(item);
      message = tr("Vypil jsi Lektvar Síly! Fyzický útok +15% na 5 kol.", "You drank the Lektvar Síly! Physical attack +15% for 5 rounds.");
    } else if (item.name == "Lektvar Kamenné kůže") {
      heroEffects.removeWhere((e) => e.name == "Lektvar Kamenné kůže");
      heroEffects.add(StatusEffect(name: "Lektvar Kamenné kůže", description: "+25% Obrana", duration: 5, isBuff: true));
      item.stackCount--;
      if (item.stackCount <= 0) inventory.remove(item);
      message = tr("Vypil jsi Lektvar Kamenné kůže! Obrana +25% na 5 kol.", "You drank the Lektvar Kamenné kůže! Defense +25% for 5 rounds.");
    } else if (item.name == "Lektvar Moudrosti") {
      heroEffects.removeWhere((e) => e.name == "Lektvar Moudrosti");
      heroEffects.add(StatusEffect(name: "Lektvar Moudrosti", description: "+15% Magický útok", duration: 5, isBuff: true));
      item.stackCount--;
      if (item.stackCount <= 0) inventory.remove(item);
      message = tr("Vypil jsi Lektvar Moudrosti! Magický útok +15% na 5 kol.", "You drank the Lektvar Moudrosti! Magic attack +15% for 5 rounds.");
    } else if (item.name == "Elixír Fénixe") {
      if (phoenixChargeActive) {
        message = tr("Elixír Fénixe už je aktivní, nelze mít dva najednou.", "Elixír Fénixe is already active, you cannot have two at once.");
        return;
      }
      phoenixChargeActive = true;
      item.stackCount--;
      if (item.stackCount <= 0) inventory.remove(item);
      message = tr("Elixír Fénixe je připraven. Při smrti tě vzkřísí na 50% HP!", "Elixír Fénixe is ready. It will revive you at 50% HP upon death!");
    }
    notifyListeners();
  }

  void useItemByName(String name) {
    final item = consumables.firstWhere((i) => i.name == name, orElse: () => Item(name: "None", value: 0, stats: {}, rarity: Rarity.common));
    if (item.name != "None") useItem(item);
  }

  void upgradeClass(HeroClass targetClass) {
    if (crystals >= 50) {
      crystals -= 50;
      final int gain = (1 * rankGainMultiplierFor(targetClass)).round().clamp(1, 999999);
      classRanks[targetClass] = (classRanks[targetClass] ?? 0) + gain;
      hp = maxHp;
      message = tr("Třída ${targetClass.name} vylepšena o $gain ${gain == 1 ? 'rank' : 'ranků'}!"
          "${gain > 1 ? ' (catch-up bonus alta)' : ''}",
          "Class ${targetClass.name} upgraded by $gain ${gain == 1 ? 'rank' : 'ranks'}!"
          "${gain > 1 ? ' (alt catch-up bonus)' : ''}");
      _checkParagonMilestones(targetClass);
    } else {
      message = tr("Nedostatek krystalů.", "Not enough crystals.");
    }
    notifyListeners();
  }

  // Utratí všechny dostupné krystaly najednou místo klikání po jednom (50 💎 za rank).
  void upgradeClassMax(HeroClass targetClass) {
    final int ranksBought = crystals ~/ 50;
    if (ranksBought <= 0) {
      message = tr("Nedostatek krystalů.", "Not enough crystals.");
      notifyListeners();
      return;
    }
    crystals -= ranksBought * 50;
    final int gain = (ranksBought * rankGainMultiplierFor(targetClass)).round();
    classRanks[targetClass] = (classRanks[targetClass] ?? 0) + gain;
    hp = maxHp;
    message = tr("Třída ${targetClass.name} vylepšena o $gain ${gain == 1 ? 'rank' : 'ranků'} najednou!"
        "${gain > ranksBought ? ' (catch-up bonus alta)' : ''}",
        "Class ${targetClass.name} upgraded by $gain ${gain == 1 ? 'rank' : 'ranks'} at once!"
        "${gain > ranksBought ? ' (alt catch-up bonus)' : ''}");
    _checkParagonMilestones(targetClass);
    notifyListeners();
  }

  void buyItem(String name, Map<String, int> stats, int cost, {bool isConsumable = false, EquipSlot? slot}) {
    if (gold >= cost) {
      gold -= cost;

      if (isConsumable) {
        final existing = inventory.where((i) => i.isConsumable && i.name == name).toList();
        if (existing.isNotEmpty) {
          existing.first.stackCount++;
          message = tr("Zakoupeno: $name (Celkem: ${existing.first.stackCount})", "Purchased: $name (Total: ${existing.first.stackCount})");
          notifyListeners();
          return;
        }
      }
      if (bagItemCount >= maxInventorySize) {
        message = tr("Inventář je plný!", "Your inventory is full!");
        notifyListeners();
        return;
      }
      // Kovář: základní vybavení na tržišti se vylepší o 2 % za každý rank kováře
      // (multiplikativně na základní staty, ne lektvary/spotřební předměty).
      final scaledStats = isConsumable
          ? stats
          : stats.map((k, v) => MapEntry(k, (v * (1 + blacksmithRank * 0.02)).round()));
      _applySlotClassBias(scaledStats, slot);
      inventory.add(Item(name: name, value: cost, stats: scaledStats, rarity: Rarity.common, isConsumable: isConsumable, stackCount: 1, slot: slot));
      message = tr("Zakoupeno: $name", "Purchased: $name");
    } else {
      message = tr("Nedostatek zlata.", "Not enough gold.");
    }
    notifyListeners();
  }

  // ===== TRŽIŠTĚ: FEATURED NABÍDKY (Rare/Epic/Legendary/SET, hodinová rotace) =====

  // Kombinovaný "progres" hráče 0..1 - průměr ranku kováře, levelu a ascension úrovně. Ovlivňuje
  // jen VÁHY jednotlivých rarit (viz _rollMarketOfferRarity), ne to, jestli se rarita vůbec může
  // objevit - to řeší prahy blacksmithRank stejné jako u craftItem (5/10), aby featured nabídky
  // nepředbíhaly to, co si hráč může sám vykovat.
  double get _marketProgressScore {
    final rankScore = (blacksmithRank / 20).clamp(0.0, 1.0);
    final levelScore = (level / 100).clamp(0.0, 1.0);
    final ascensionScore = (ascensionLevel / 4).clamp(0.0, 1.0);
    return (rankScore + levelScore + ascensionScore) / 3;
  }

  // Váhy: Rare vždy dostupný (klesá s progresem), Epic od rank 5, Legendary od rank 10,
  // SET od rank 10 A JEN pokud má hráč aktivní set (viz activeGearSetDef - vázaný na
  // zvolenou třídu/specializaci). Se stoupajícím progresem se váhy posouvají k vzácnějším kusům.
  String _rollMarketOfferRarity() {
    final progress = _marketProgressScore;
    final double rareW = 60 - 25 * progress;
    final double epicW = blacksmithRank >= 5 ? 25 + 20 * progress : 0;
    final double legendaryW = blacksmithRank >= 10 ? 8 + 25 * progress : 0;
    final double setW = (blacksmithRank >= 10 && activeGearSetDef != null) ? 2 + 15 * progress : 0;
    final total = rareW + epicW + legendaryW + setW;
    if (total <= 0) return "rare"; // fallback pro úplně čerstvou postavu bez ranku kováře
    double roll = Random().nextDouble() * total;
    if (roll < rareW) return "rare";
    roll -= rareW;
    if (roll < epicW) return "epic";
    roll -= epicW;
    if (roll < legendaryW) return "legendary";
    return "set";
  }

  // Cena v Zlatě - škáluje s raritou a rankem kováře (stejný "progres" metr, jaký kovář používá
  // pro vlastní craftItem ceny/staty).
  int _marketOfferPrice(String rarityType) {
    final rank = max(1, blacksmithRank);
    const base = {"rare": 100, "epic": 200, "legendary": 400, "set": 600};
    return (base[rarityType]! * rank);
  }

  static const List<EquipSlot> _marketOfferSlots = [
    EquipSlot.weapon, EquipSlot.armor, EquipSlot.accessory, EquipSlot.gloves,
    EquipSlot.boots, EquipSlot.helmet, EquipSlot.belt, EquipSlot.cloak, EquipSlot.shoulders,
  ];
  static const List<EquipSlot> _marketOfferSetSlots = [
    EquipSlot.armor, EquipSlot.accessory, EquipSlot.gloves, EquipSlot.boots,
    EquipSlot.helmet, EquipSlot.belt, EquipSlot.cloak, EquipSlot.shoulders,
  ];

  // Vygeneruje jeden featured kus - staty/vzorce sdílejí logiku s craftItem (jen bez spotřeby
  // surovin, protože se kupuje za Zlato), SET větev jde přes stávající _createSetItem.
  Item _generateMarketOffer() {
    final rarityType = _rollMarketOfferRarity();
    final rank = max(1, blacksmithRank);
    final price = _marketOfferPrice(rarityType);
    const allStats = ["Strength", "Agility", "Wisdom", "Vitality", "Armor"];
    const combatStats = ["Crit", "Dodge", "Block", "Attack Speed"];

    if (rarityType == "set") {
      final setDef = activeGearSetDef!;
      final slot = _marketOfferSetSlots[Random().nextInt(_marketOfferSetSlots.length)];
      final setItem = _createSetItem(setDef, slot, rank);
      return Item(name: setItem.name, value: price, stats: setItem.stats, rarity: setItem.rarity, slot: setItem.slot, setId: setItem.setId);
    }

    final slot = _marketOfferSlots[Random().nextInt(_marketOfferSlots.length)];
    Rarity rarity;
    Map<String, int> stats = {};
    if (rarityType == "rare") {
      rarity = Rarity.rare;
      String s1 = allStats[Random().nextInt(allStats.length)];
      String s2 = allStats.where((s) => s != s1).toList()[Random().nextInt(allStats.length - 1)];
      stats[s1] = (1 * rank).round();
      stats[s2] = (0.5 * rank).round();
    } else if (rarityType == "epic") {
      rarity = Rarity.epic;
      List<String> shuffled = List.from(allStats)..shuffle();
      stats[shuffled[0]] = (1.5 * rank).round();
      stats[shuffled[1]] = (0.8 * rank).round();
      stats[shuffled[2]] = (0.7 * rank).round();
      if (Random().nextDouble() < 0.4) stats[combatStats[Random().nextInt(combatStats.length)]] = (0.3 * rank).round();
    } else {
      rarity = Rarity.legendary;
      List<String> shuffled = List.from(allStats)..shuffle();
      stats[shuffled[0]] = (3 * rank).round();
      stats[shuffled[1]] = (2.5 * rank).round();
      stats[shuffled[2]] = (2 * rank).round();
      if (Random().nextDouble() < 0.6) stats[combatStats[Random().nextInt(combatStats.length)]] = (0.5 * rank).round();
    }
    _applySlotClassBias(stats, slot);
    return Item(name: "Tržní nabídka (${rarity.name.toUpperCase()})", value: price, stats: stats, rarity: rarity, slot: slot);
  }

  // Zkontroluje, jestli uplynula hodina od posledního refreshe - pokud ano, vygeneruje 2 nové
  // nabídky a resetuje reroll počítadla. Volá se z _checkQuestResets (start hry + minutový
  // Timer.periodic), takže funguje i po delší pauze/zavření appky (dohoní se hned při návratu).
  void _ensureMarketOffers() {
    final now = DateTime.now();
    if (marketOffersRefreshedAt == null || now.difference(marketOffersRefreshedAt!) >= marketRefreshInterval) {
      marketFeaturedSlots = [_generateMarketOffer(), _generateMarketOffer()];
      marketOffersRefreshedAt = now;
      marketFreeRerollsUsed = 0;
      marketAdRerollsUsed = 0;
    }
  }

  DateTime get nextMarketRefresh => (marketOffersRefreshedAt ?? DateTime.now()).add(marketRefreshInterval);
  bool get canFreeRerollMarket => marketFreeRerollsUsed < marketFreeRerollsPerCycle;
  bool get canWatchAdForMarketReroll => marketAdRerollsUsed < marketMaxAdRerollsPerCycle;

  void rerollMarketSlot(int index) {
    _ensureMarketOffers();
    if (index < 0 || index >= marketFeaturedSlots.length) return;
    if (!canFreeRerollMarket) {
      message = tr("Došly ti zdarma rerolly na tuto hodinu (${marketFreeRerollsUsed}/$marketFreeRerollsPerCycle). Zkus reklamu.", "You're out of free rerolls this hour (${marketFreeRerollsUsed}/$marketFreeRerollsPerCycle). Try watching an ad.");
      notifyListeners();
      return;
    }
    marketFreeRerollsUsed++;
    marketFeaturedSlots[index] = _generateMarketOffer();
    message = tr("Nabídka přehozena (zdarma reroll $marketFreeRerollsUsed/$marketFreeRerollsPerCycle).", "Offer rerolled (free reroll $marketFreeRerollsUsed/$marketFreeRerollsPerCycle).");
    notifyListeners();
  }

  // Skutečné přehrání reklamy řeší RewardedAdService (viz UI) - tahle metoda jen aplikuje odměnu
  // po potvrzeném zhlédnutí (onUserEarnedReward), stejný vzor jako grantRiftAttemptFromAd().
  void rerollMarketSlotFromAd(int index) {
    _ensureMarketOffers();
    if (index < 0 || index >= marketFeaturedSlots.length || !canWatchAdForMarketReroll) return;
    marketAdRerollsUsed++;
    everWatchedRiftAd = true; // sdílí achievement "adSupporter" se všemi zdroji rewarded reklam
    marketFeaturedSlots[index] = _generateMarketOffer();
    message = tr("🎬 Reklama dokoukána! Nabídka přehozena ($marketAdRerollsUsed/$marketMaxAdRerollsPerCycle reklam tuto hodinu).", "🎬 Ad watched! Offer rerolled ($marketAdRerollsUsed/$marketMaxAdRerollsPerCycle ads this hour).");
    _checkAchievements();
    notifyListeners();
  }

  void buyMarketFeaturedItem(int index) {
    _ensureMarketOffers();
    if (index < 0 || index >= marketFeaturedSlots.length) return;
    final offer = marketFeaturedSlots[index];
    if (offer == null) {
      message = tr("Tahle nabídka je vyprodaná - počkej na hodinový refresh.", "This offer is sold out - wait for the hourly refresh.");
      notifyListeners();
      return;
    }
    if (gold < offer.value) {
      message = tr("Nedostatek zlata.", "Not enough gold.");
      notifyListeners();
      return;
    }
    if (bagItemCount >= maxInventorySize) {
      message = tr("Inventář je plný!", "Your inventory is full!");
      notifyListeners();
      return;
    }
    gold -= offer.value;
    inventory.add(offer);
    marketFeaturedSlots[index] = null; // "vyprodáno" do dalšího hodinového refreshe
    message = tr("Zakoupeno: ${offer.name}!", "Purchased: ${offer.name}!");
    if (inventory.any((i) => i.rarity == Rarity.legendary)) _unlockAchievement(AchievementId.firstLegendary);
    notifyListeners();
  }

  void _generateNextEnemy({bool allowMerchant = true}) {
    isMerchantEncounter = false;
    comboStreak = 0; // nový nepřítel = nový combo streak, ať jde vždy jen o "za sebou proti TOMUHLE nepříteli"
    if (allowMerchant && level >= merchantMinLevel && Random().nextDouble() < merchantSpawnChance) {
      isMerchantEncounter = true;
      message = tr("🧳 Potulný obchodník! Nabízí ocel, kůži a dřevo za zlato.", "🧳 A wandering merchant! Offering steel, leather, and wood for gold.");
      return;
    }
    // Fragmentace (curse): pokud čekají úlomky rozštěpeného nepřítele, vygeneruj slabší kopii místo běžného nepřítele.
    if (pendingFragments > 0) {
      pendingFragments--;
      currentEnemyIsFragment = true;
      // Sourozenecká zuřivost: dokud po tomhle úlomku ještě čeká další (pendingFragments > 0 PO
      // dekrementu výš = tohle NENÍ poslední úlomek), dostává +30 % Atk - cítí za zády druhého
      // úlomka a bije tvrději, ať fragmentace není jen "delší fight", ale i reálně nebezpečnější.
      final bool hasSurvivingSibling = pendingFragments > 0;
      currentEnemyName = hasSurvivingSibling ? tr("Úlomek nepřítele (posílen sourozencem)", "Enemy fragment (bolstered by its sibling)") : tr("Úlomek nepřítele", "Enemy fragment");
      currentEnemyAbility = "";
      currentEnemyMaxHp = fragmentMaxHp;
      currentEnemyHp = fragmentMaxHp;
      currentEnemyAtk = hasSurvivingSibling ? (fragmentAtk * 1.3).toInt() : fragmentAtk;
      currentEnemyDef = fragmentDef;
      currentEnemyIsMagical = fragmentIsMagical;
      enemyEffects.clear();
      enemyStunTurns = 0;
      huntersMarkStacks = 0;
      arcaneChargeStacks = 0;
      flowingChiStacks = 0;
      currentEnemyRevived = false;
      specRelicUsedTower = false;
      currentEnemyShield = towerModAbsorbStacks > 0 ? (currentEnemyMaxHp * 0.05 * towerModAbsorbStacks).toInt() : 0;
      if (currentEnemyShield > 0) _pushFx(FxKind.shieldGained, FxSide.enemy, value: currentEnemyShield);
      enemySpawnSeq++;
      return;
    }
    currentEnemyIsFragment = false;
    double mult = pow(1.1, floor - 1).toDouble();
    // Hardcore Mode: vše obtížnější - nepřátelé mají o 50 % víc síly.
    if (atLeastHardcore) mult *= (1.0 + 0.5 * hardcoreTier); // tier 1 = ×1.5 (jako dřív), roste s dalšími Lair 100 clearama
    if (atLeastPredpekli && predpekliUnlocked) mult *= predpekliDifficultyMult; // Předpeklí: další vrstva navrch
    if (pekloMode && pekloUnlocked) mult *= pekloDifficultyMult; // Peklo: další vrstva navrch Předpeklí
    mult /= currentFightAscensionSquishDivisor; // viz Lair - stejný Ascension squish (jen pro vrstvu, ve které se právě bojuje - BUG FIX: dřív i Normal)
    // Pojistka proti přetečení int64 - viz stejná poznámka u Lair výš.
    mult = mult.clamp(0.0, 1e14);
    if (isBoss) {
      var bDetails = getBossDetails(floor);
      currentEnemyName = bDetails["name"]!;
      currentEnemyAbility = bDetails["ability"]!;
    } else {
      final e = _regularEnemyPool[(floor + enemiesDefeatedOnFloor) % _regularEnemyPool.length];
      currentEnemyName = e["name"]!;
      currentEnemyAbility = e["ability"]!;
    }
    currentEnemyMaxHp = (100 * mult).clamp(0.0, 9e17).toInt();
    currentEnemyHp = currentEnemyMaxHp;
    // Enemy Atk koeficient zvýšen z 8 na 11 (+~37 %) - hráčovy staty rostou z gearu/paragonu/setů
    // rychleji než tahle křivka, takže i Normal obtížnost byla znatelně měkká navzdory obtížnosti
    // dobře namodelované na patrech samotných (viz "Normal - hráč má velké staty" balance zpětná
    // vazba). HP/Def zůstávají beze změny - jde jen o to, aby nepřátelé bolely víc, ne o delší boje.
    currentEnemyAtk = (11 * mult).clamp(0.0, 9e17).toInt();
    currentEnemyDef = (5 * mult).clamp(0.0, 9e17).toInt();
    // Boss (5. nepřítel na patře): extra HP i ATK navrch nad běžnou škálovací křivku, aby
    // souboj s ním citelně vynikl (déle vydrží a útočí tvrději než běžný mob stejného patra).
    if (isBoss) {
      currentEnemyMaxHp = (currentEnemyMaxHp * 1.83).toInt();
      currentEnemyHp = currentEnemyMaxHp;
      currentEnemyAtk = (currentEnemyAtk * 1.6).toInt();
    }
    currentEnemyIsMagical = Random().nextBool();
    // Balance Totem Lv80 "Kořeny Věže" (viz _castDruidSigil): zachytit dotDamage starého
    // Astrálního rozkladu PŘED vyčištěním enemyEffects, ať se má co přenést do dalšího boje.
    final int _balanceTotemOldDot = enemyEffects.firstWhere((e) => e.name == 'Astrální rozklad', orElse: () => StatusEffect(name: '', description: '', duration: 0, isBuff: false)).dotDamage;
    final int _plagueTomeOldDot = enemyEffects.firstWhere((e) => e.name == 'Morová kletba', orElse: () => StatusEffect(name: '', description: '', duration: 0, isBuff: false)).dotDamage;
    final int _shadowGlaiveOldDot = enemyEffects.firstWhere((e) => e.name == 'Fel oheň', orElse: () => StatusEffect(name: '', description: '', duration: 0, isBuff: false)).dotDamage;
    enemyEffects.clear();
    // Relic Lv80 "carry" mechanika (viz _castDkSigil/_castHunterSigil) - DK Frost "Putující zima" /
    // DK Plague "Přenos epidemie" / Hunter Marksman "Další terč": beze zamčeného Lv80 se stack/DoT
    // při přechodu na dalšího nepřítele resetuje jako dřív. Beast Quiver a Ghost Quiver naopak
    // POTŘEBUJÍ, aby specRelicStacks fungoval jako persistentní počítadlo napříč souboji (viz
    // "každý třetí" proc v _castHunterSigil/_hunterGhostCounter), takže se u nich nikdy neresetuje.
    // CC (enemyStunTurns) a Blood dmg-reduction nikdy nepřechází mezi nepřáteli.
    enemyStunTurns = 0;
    _dkBloodEnemyDmgReductionPct = 0;
    _guardianCheatDeathUsed = false;
    _relicArmorShredAmount = 0; // nová hodnota currentEnemyDef se hned přepíše na fresh nepřítele, jen ať tracker nezůstane stale
    _relicArmorShredDebuffName = null;
    _duelistDanceFirstProcUsed = false;
    final bool dkFrostCarries = heroClass == HeroClass.deathknight && isSpecRelicEquipped &&
        currentSpecRelic.kind == SpecRelicKind.deathKnightFrostSigil && relicEffectActive(80);
    final bool dkPlagueCarries = heroClass == HeroClass.deathknight && isSpecRelicEquipped &&
        currentSpecRelic.kind == SpecRelicKind.deathKnightPlagueSigil && relicEffectActive(80);
    final bool marksmanCarries = heroClass == HeroClass.hunter && isSpecRelicEquipped &&
        currentSpecRelic.kind == SpecRelicKind.hunterMarksmanQuiver && relicEffectActive(80);
    final bool judgementCarries = isSpecRelicEquipped &&
        ((heroClass == HeroClass.healer && currentSpecRelic.kind == SpecRelicKind.healerJudgementSymbol) ||
         (heroClass == HeroClass.paladin && currentSpecRelic.kind == SpecRelicKind.paladinJudgementSeal)) && relicEffectActive(80);
    final bool fireCarries = heroClass == HeroClass.mage && isSpecRelicEquipped &&
        currentSpecRelic.kind == SpecRelicKind.mageFireTome && relicEffectActive(80);
    final bool frostTomeCarries = heroClass == HeroClass.mage && isSpecRelicEquipped &&
        currentSpecRelic.kind == SpecRelicKind.mageFrostTome && relicEffectActive(80);
    final bool stormCarries = heroClass == HeroClass.monk && isSpecRelicEquipped &&
        currentSpecRelic.kind == SpecRelicKind.monkStormMala && relicEffectActive(80);
    final bool balanceTotemCarries = heroClass == HeroClass.druid && isSpecRelicEquipped &&
        currentSpecRelic.kind == SpecRelicKind.druidBalanceTotem && relicEffectActive(80);
    final bool plagueTomeCarries = heroClass == HeroClass.necromancer && isSpecRelicEquipped &&
        currentSpecRelic.kind == SpecRelicKind.necromancerPlagueTome && relicEffectActive(80);
    final bool nemesisCarries = heroClass == HeroClass.duelist && isSpecRelicEquipped &&
        currentSpecRelic.kind == SpecRelicKind.duelistNemesisCrest && relicEffectActive(80);
    final bool havocCarries = heroClass == HeroClass.demonhunter && isSpecRelicEquipped &&
        currentSpecRelic.kind == SpecRelicKind.demonHunterHavocGlaive && relicEffectActive(80);
    final bool shadowGlaiveCarries = heroClass == HeroClass.demonhunter && isSpecRelicEquipped &&
        currentSpecRelic.kind == SpecRelicKind.demonHunterShadowGlaive && relicEffectActive(80);
    final bool keepsPersistentStacks = (heroClass == HeroClass.hunter && isSpecRelicEquipped &&
            (currentSpecRelic.kind == SpecRelicKind.hunterBeastQuiver || currentSpecRelic.kind == SpecRelicKind.hunterGhostQuiver)) ||
        (heroClass == HeroClass.healer && isSpecRelicEquipped &&
            (currentSpecRelic.kind == SpecRelicKind.healerDawnSymbol || currentSpecRelic.kind == SpecRelicKind.healerBattleSymbol)) ||
        (heroClass == HeroClass.mage && isSpecRelicEquipped && currentSpecRelic.kind == SpecRelicKind.mageArcaneTome) ||
        (heroClass == HeroClass.monk && isSpecRelicEquipped && currentSpecRelic.kind == SpecRelicKind.monkHarmonyMala) ||
        (heroClass == HeroClass.necromancer && isSpecRelicEquipped && currentSpecRelic.kind == SpecRelicKind.necromancerBoneTome) ||
        (heroClass == HeroClass.duelist && isSpecRelicEquipped && currentSpecRelic.kind == SpecRelicKind.duelistLightningCrest);
    if (dkFrostCarries && specRelicStacks > 0) {
      if (relicEffectActive(30)) _applyRelicArmorShred('Zmrzlá duše', 0.12);
      enemyEffects.add(StatusEffect(name: 'Zmrzlá duše', description: 'Přenesený stack $specRelicStacks', duration: 3, isBuff: false));
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '❄️ Přenesená Zmrzlá duše x$specRelicStacks');
    } else if (marksmanCarries && specRelicStacks > 0) {
      enemyEffects.add(StatusEffect(name: 'Záměrný bod', description: 'Přenesená Přesnost $specRelicStacks/5', duration: 3, isBuff: false));
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '🎯 Přenesený Záměrný bod x$specRelicStacks');
    } else if (judgementCarries && specRelicStacks > 0) {
      enemyEffects.add(StatusEffect(name: 'Rozsudek', description: 'Přenesený Rozsudek', duration: 4, isBuff: false));
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '⚖️ Přenesený Rozsudek');
    } else if (fireCarries && specRelicStacks > 0) {
      final carryDot = (currentEnemyMaxHp * 0.01 * specRelicStacks).round();
      enemyEffects.add(StatusEffect(name: 'Hoření', description: 'Přenesené Hoření (Žár $specRelicStacks)', duration: 2, isBuff: false, dotDamage: carryDot));
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '🔥 Přenesené Hoření x$specRelicStacks');
    } else if (frostTomeCarries && specRelicStacks > 0) {
      enemyEffects.add(StatusEffect(name: 'Chlad', description: 'Přenesené Zamrznutí $specRelicStacks/3', duration: 3, isBuff: false));
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '❄️ Přenesený Chlad x$specRelicStacks');
    } else if (stormCarries && specRelicStacks > 0) {
      final carried = (specRelicStacks / 2).ceil();
      specRelicStacks = carried;
      heroEffects.removeWhere((e) => e.name == 'Combo');
      heroEffects.add(StatusEffect(name: 'Combo', description: 'Nesené Combo $carried/5', duration: 3, isBuff: true));
      _pushFx(FxKind.statusApplied, FxSide.hero, label: '👊 Nesené Combo x$carried');
    } else if (balanceTotemCarries && _balanceTotemOldDot > 0) {
      enemyEffects.add(StatusEffect(name: 'Astrální rozklad', description: 'Přenesený rozklad', duration: 2, isBuff: false, dotDamage: (_balanceTotemOldDot * 0.5).round()));
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '🌌 Přenesený rozklad');
    } else if (plagueTomeCarries && _plagueTomeOldDot > 0) {
      enemyEffects.add(StatusEffect(name: 'Morová kletba', description: 'Přenesená kletba', duration: 2, isBuff: false, dotDamage: (_plagueTomeOldDot * 0.5).round()));
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '☣️ Přenesená kletba');
    } else if (nemesisCarries && specRelicStacks > 0) {
      enemyEffects.add(StatusEffect(name: 'Označení pomsty', description: 'Přenesená Odplata $specRelicStacks/5', duration: 3, isBuff: false));
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '🎯 Přenesené Označení pomsty x$specRelicStacks');
    } else if (havocCarries && specRelicStacks > 0) {
      enemyEffects.add(StatusEffect(name: 'Znamení Zkázy', description: 'Přenesená Zkáza $specRelicStacks/5', duration: 3, isBuff: false));
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '🎯 Přenesené Znamení Zkázy x$specRelicStacks');
    } else if (shadowGlaiveCarries && _shadowGlaiveOldDot > 0) {
      enemyEffects.add(StatusEffect(name: 'Fel oheň', description: 'Přenesený Fel oheň', duration: 2, isBuff: false, dotDamage: (_shadowGlaiveOldDot * 0.5).round()));
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '👁️ Přenesený Fel oheň');
    } else if (!keepsPersistentStacks) {
      specRelicStacks = 0;
    }
    if (dkPlagueCarries && _dkPlagueStackCount > 0) {
      final carryDot = (currentEnemyMaxHp * 0.01 * _dkPlagueStackCount).round();
      enemyEffects.add(StatusEffect(name: 'Nekrotická hniloba', description: 'Přenesený mor (stack $_dkPlagueStackCount)', duration: 2, isBuff: false, dotDamage: carryDot));
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '☣️ Přenesená nákaza x$_dkPlagueStackCount');
    } else if (!dkPlagueCarries) {
      _dkPlagueStackCount = 0;
    }
    huntersMarkStacks = 0;
    arcaneChargeStacks = 0;
    flowingChiStacks = 0;
    currentEnemyRevived = false;
    combatRoundCount = 0; // nový nepřítel = nový boj, enrage čítač jde od nuly
    specRelicUsedTower = false;
    // Tower modifikátor Absorb: na začátku každého souboje ve Věži dostane NEPŘÍTEL štít ve výši
    // (5 % jeho maxHp × počet nastřádaných Absorb stacků) - viz enemyCritChance/DodgeChance/
    // BlockChance výš, tenhle modifikátor teď posiluje nepřítele místo hráče.
    currentEnemyShield = towerModAbsorbStacks > 0 ? (currentEnemyMaxHp * 0.05 * towerModAbsorbStacks).toInt() : 0;
    if (currentEnemyShield > 0) _pushFx(FxKind.shieldGained, FxSide.enemy, value: currentEnemyShield);
    enemySpawnSeq++;
  }

  // ===== POTULNÝ OBCHODNÍK =====
  // buyFromMerchant() funguje shodně ve Věži i v Rift (kontroluje se přes isInRift, aby vědělo,
  // jestli po odchodu má vygenerovat nového Tower nepřítele, nebo se vrátit na Rift tier picker).
  void buyFromMerchant(int quantity) {
    if (!isMerchantEncounter || quantity <= 0) return;
    final totalCost = merchantMaterialsPrice * quantity;
    if (gold < totalCost) {
      message = tr("Nedostatek zlata! Potřeba: $totalCost 🪙.", "Not enough gold! Needed: $totalCost 🪙.");
      notifyListeners();
      return;
    }
    gold -= totalCost;
    materials += quantity;
    message = tr("Koupeno: $quantity× suroviny za $totalCost 🪙.", "Purchased: $quantity× materials for $totalCost 🪙.");
    notifyListeners();
  }

  void leaveMerchant() {
    if (!isMerchantEncounter) return;
    isMerchantEncounter = false;
    if (isInRift) {
      // V Rift obchodník nahrazuje setkání pro tenhle pokus - odchod ukončí pokus (stejně jako
      // útěk Poklad-skřeta), bez odměny/tier progresu, ale materiály zůstávají koupené.
      isInRift = false;
      hp = maxHp;
      message = tr("Opustil jsi obchodníka a vrátil ses z Trhliny.", "You left the merchant and returned from the Rift.");
    } else {
      message = tr("Rozloučil ses s obchodníkem.", "You said goodbye to the merchant.");
      _generateNextEnemy(allowMerchant: false); // zaručeně reálný souboj hned po odchodu
    }
    notifyListeners();
  }

  void selectClass(HeroClass newClass) {
    heroClass = newClass;
    hp = maxHp;
    rank100Choice = 0;
    _resetResources();
    // Startovní lektvary: úplně první postava na účtu (totalDeaths==0) dostane plnou
    // bezpečnostní síť 5 kusů, každá další (po smrti) jen 1 - už ví jak hra funguje,
    // nepotřebuje tolik jako úplný začátečník.
    final int startingPotions = totalDeaths == 0 ? 5 : 1;
    if (totalDeaths == 0) {
      // Úplně první postava na účtu - spusť lineární úvodní tutoriál (viz introTutorialActive).
      introTutorialDone = false;
      introTutorialStep = 0;
    }
    final existingPotions = inventory.where((i) => i.isConsumable && i.name == "Léčivý lektvar").toList();
    if (existingPotions.isNotEmpty) {
      existingPotions.first.stackCount += startingPotions;
    } else {
      inventory.add(Item(name: "Léčivý lektvar", value: getPotionPrice(20), stats: const {"HP": 0}, rarity: Rarity.common, isConsumable: true, stackCount: startingPotions));
    }
    message = tr("Třída ${newClass.name.toUpperCase()} zvolena! Získal jsi $startingPotions Léčivý(ch) lektvar(ů).", "Class ${newClass.name.toUpperCase()} chosen! You received $startingPotions Healing Potion(s).");
    _checkParagonMilestones(newClass);
    _checkQuests();
    _checkAchievements();
    notifyListeners();
  }

  void completeIntro() {
    introSeen = true;
    notifyListeners();
  }

  void _handleEnemyDeath() {
    if(relicKillHeal)hp=(hp+(maxHp*0.10).round()).clamp(0,maxHp);
    // Blood Sigil Lv70 "Hostina" (viz _castDkSigil): zabití cíle nakaženého Krvavým parazitem obnoví HP.
    if (heroClass == HeroClass.deathknight && isSpecRelicEquipped && currentSpecRelic.kind == SpecRelicKind.deathKnightBloodSigil &&
        relicEffectActive(70) && enemyEffects.any((e) => e.name == 'Krvavý parazit')) {
      hp = min(maxHp, hp + (maxHp * 0.08).round());
    }
    // Beast Quiver Lv80 "Hostina vítězů" (viz _castHunterSigil): companion HP se netrackuje jako
    // samostatný stat, takže zjednodušeno na heal hráče při zabití.
    if (heroClass == HeroClass.hunter && isSpecRelicEquipped && currentSpecRelic.kind == SpecRelicKind.hunterBeastQuiver && relicEffectActive(80)) {
      hp = min(maxHp, hp + (maxHp * 0.06).round());
    }
    // Bone Tome Lv80 "Hostina duší" (viz _castNecromancerSigil): zabití cíle obnoví HP nekromanta.
    if (heroClass == HeroClass.necromancer && isSpecRelicEquipped && currentSpecRelic.kind == SpecRelicKind.necromancerBoneTome && relicEffectActive(80)) {
      hp = min(maxHp, hp + (maxHp * 0.06).round());
    }
    // Nemesis Crest Lv70 "Vrácená síla" (viz _castDuelistSigil): zabití označeného cíle vrátí energii.
    if (heroClass == HeroClass.duelist && isSpecRelicEquipped && currentSpecRelic.kind == SpecRelicKind.duelistNemesisCrest &&
        relicEffectActive(70) && enemyEffects.any((e) => e.name == 'Označení pomsty')) {
      energy = (energy + 20).clamp(0, maxEnergy);
    }
    // Havoc Glaive Lv70 "Vrácená zuřivost" (viz _castDemonHunterSigil): zabití označeného cíle vrátí energii.
    if (heroClass == HeroClass.demonhunter && isSpecRelicEquipped && currentSpecRelic.kind == SpecRelicKind.demonHunterHavocGlaive &&
        relicEffectActive(70) && enemyEffects.any((e) => e.name == 'Znamení Zkázy')) {
      energy = (energy + 20).clamp(0, maxEnergy);
    }
    // Oživení padlých (curse): zabitý nepřítel se jednou oživí na 33 % HP místo skutečné smrti.
    // Vrátí se "naštvanější" - trvalý +50 % Atk na zbytek fightu, ať to není jen HP reset se
    // stejnou hrozbou jako předtím (viz diskuse o podobnosti s Roztříštěním).
    if (activeCurse == CurseOfFate.revival && !currentEnemyRevived && !currentEnemyIsFragment) {
      currentEnemyRevived = true;
      currentEnemyHp = (currentEnemyMaxHp * 0.33).toInt();
      currentEnemyAtk = (currentEnemyAtk * 1.5).toInt();
      message = tr("☠ Oživení padlých! Nepřítel povstal s 33 % HP a +50 % útokem!", "☠ Revival of the Fallen! The enemy rose again with 33% HP and +50% attack!");
      notifyListeners();
      return;
    }

    xp += (20 * curseRewardMultiplier * xpDifficultyPenalty).toInt();

    // Deathknight: Vysátí duše – soul runa za každého zabitého nepřítele
    if (heroClass == HeroClass.deathknight) _gainSoulRune();

    for (var q in quests) {
      if (!q.isCompleted && q.targetKills > 0) {
        if (floor >= q.targetFloor) {
          if (q.requiredEnemyName != null && q.requiredEnemyName != currentEnemyName) continue;
          if (q.requiresNormalDifficulty && difficultyTier != 0) continue;
          q.currentKills++;
        }
      }
    }
    if (resourceDropUnlocked && Random().nextDouble() < 0.3) {
      magicDust += 5;
      materials++;
      message += tr(" (Získal jsi surovinu)", " (You obtained a material)");
    }
    if (xp >= xpToLevel) {
      final levelBeforeUp = level;
      while (xp >= xpToLevel) {
        xp -= xpToLevel;
        // Růst 1.5x/level byl příliš strmý - level 30 by vyžadoval přes milion zabití (XP je
        // flat 20/kill, netočí se s patrem). Zmírněno na 1.13x, aby dohrání normal Lairu (100
        // pater) vycházelo zhruba na level ~30 při běžném tempu grindění ve Věži.
        xpToLevel = (xpToLevel * 1.13).toInt();
        level++;
        levelMilestoneReachedAt.putIfAbsent(level, () => DateTime.now());
        talentPoints++;

        if (autoTalentsEnabled && talentPoints > 0) {
          talents[preferredAutoTalent] = talents[preferredAutoTalent]! + 1;
          talentPoints--;
        }
      }
      hp = maxHp; // Level up plně vyléčí hrdinu.
      if (levelBeforeUp < lairUnlockLevel && level >= lairUnlockLevel) _queueContextTip(TutorialTipId.tipLairUnlocked);
      if (levelBeforeUp < arenaUnlockLevel && level >= arenaUnlockLevel) _queueContextTip(TutorialTipId.tipArenaUnlocked);
      if (levelBeforeUp < worldBossUnlockLevel && level >= worldBossUnlockLevel) _queueContextTip(TutorialTipId.tipWorldBossUnlocked);
      if (levelBeforeUp < riftUnlockLevel && level >= riftUnlockLevel) _queueContextTip(TutorialTipId.tipRiftUnlocked);
      if (levelBeforeUp < specializationUnlockLevel && level >= specializationUnlockLevel && canChooseSpecialization) _queueContextTip(TutorialTipId.tipSpecialization);
      _refreshArtifactStats(); // Prsten Osudu a artefaktová zbraň mají hlavní staty svázané s levelem - viz _refreshArtifactStats().
      message = tr("Level Up! Nyní jsi level $level. Máš nové talentové body.", "Level Up! You are now level $level. You have new talent points.");
      // Jednorázové varování při PŘEKROČENÍ prahu XP penalty (ne při každém kill) - viz
      // xpDifficultyPenalty. Kontrolujeme rozsah (levelBeforeUp < práh <= level), ne přesnou
      // rovnost, aby to nevynechalo hráče, co v jednom skoku přeskočí víc levelů najednou.
      if (levelBeforeUp < 30 && level >= 30) {
        message += tr(" ⚠️ Od teď dává Normal jen 10 % XP - čas postoupit na Hardcore!", " ⚠️ From now on, Normal only grants 10% XP - time to move up to Hardcore!");
      } else if (levelBeforeUp < 60 && level >= 60) {
        message += tr(" ⚠️ Od teď dává Hardcore jen 10 % XP - čas postoupit na Předpeklí!", " ⚠️ From now on, Hardcore only grants 10% XP - time to move up to Předpeklí!");
      } else if (levelBeforeUp < 90 && level >= 90) {
        message += tr(" ⚠️ Od teď dává Předpeklí jen 10 % XP - čas postoupit na Peklo!", " ⚠️ From now on, Předpeklí only grants 10% XP - time to move up to Peklo!");
      }
      _triggerCelebration('LEVEL UP!', subtitle: 'Nyní jsi level $level', icon: Icons.star, color: FantasyColors.gold);
    }
    if (isBoss) {
      _tryDropItem();
      // Esence Moci na vylepšování legendárního vybavení - odemčeno od patra 30. Hardcore Mode
      // (a vyšší) dává 2× tolik esence za stejné patro - odměna za vyšší obtížnost nepřátel.
      if (floor >= 30) {
        int essenceGain = 1 + Random().nextInt(2);
        if (atLeastHardcore) essenceGain *= 2;
        legendaryEssence += essenceGain;
        message += tr(" (+$essenceGain 🔥 Esence)", " (+$essenceGain 🔥 Essence)");
      }
      // Hardcore set drop - 1 % z Tower bosse. powerLevel na stejném měřítku jako běžný Tower
      // drop (floor/5, viz _tryDropItem) - stejná oprava jako u Lairu/Riftu výše.
      _tryDropHardcoreSetPiece(0.01, powerLevel: (floor / 5).ceil()); _tryDropPredpekliSetPiece(0.01, powerLevel: (floor / 5).ceil()); _tryDropPekloSetPiece(0.01, powerLevel: (floor / 5).ceil()); addRelicXp(1); _rollRelicDrop(0.01);
      // (Talentové body Runového Čaroděje se od téhle úpravy počítají jen z Lair bossů - viz
      // _registerLairBoss15PlusKill - Tower boss killy do nich už nepřispívají.)
      // Suroviny za Tower bosse od patra 100+ (viz Lair boss reward výš) - fixní +1/kill.
      if (floor >= 100) {
        materials += 1;
        message += tr(" (+1 ⚒️ Surovina)", " (+1 ⚒️ Material)");
      }
    }
    enemiesDefeatedOnFloor++;
    gold += (10 * curseRewardMultiplier).toInt();
    if (Random().nextInt(10) > 7) crystals += (5 * kCrystalDropBonus).round();
    if (enemiesDefeatedOnFloor >= 5) {
      // Talent bod za PRVNÍ vyčištění tohohle patra na tuhle obtížnost, jen PRO TUHLE ŽIVOTNOST -
      // resetuje se při smrti (viz resetGame()/towerFloorTalentClaims). Pokud je stejné patro na
      // stejné obtížnosti už TRVALE získané z Lairu (lairFloorTalentClaims), Tower za něj bod
      // znovu nedává - hráč tak nemusí farmit oboje, aby měl dané patro "odškrtnuté".
      // + strop 100 bodů/obtížnost (Lair permanent + Tower this-life dohromady).
      // Klíč bereme z patra, které se PRÁVĚ dokončuje (před floor++).
      final bool floorTalentAlreadyClaimed = isTowerFloorTalentClaimed(floor) || isLairFloorTalentClaimed(floor);
      final bool capReached = towerFloorTalentCapReachedForCurrentDifficulty;
      towerFloorTalentClaims.add(floorTalentKey(floor));
      floor++;
      if (!floorTalentAlreadyClaimed && !capReached) {
        talentPoints++;
        if (autoTalentsEnabled && talentPoints > 0) {
          talents[preferredAutoTalent] = talents[preferredAutoTalent]! + 1;
          talentPoints--;
        }
      }
      enemiesDefeatedOnFloor = 0;
      // Tower modifikátor: náhodně JEDEN ze 4 permanentních bonusů za tohle poražené patro.
      String towerModText;
      switch (Random().nextInt(4)) {
        case 0:
          towerModCritStacks++;
          towerModText = tr("+1 % Crit", "+1% Crit");
          break;
        case 1:
          towerModBlockStacks++;
          towerModText = tr("+1 % Block", "+1% Block");
          break;
        case 2:
          towerModDodgeStacks++;
          towerModText = tr("+1 % Dodge", "+1% Dodge");
          break;
        default:
          towerModAbsorbStacks++;
          towerModText = tr("+5 % Absorb štít na začátku boje", "+5% Absorb shield at the start of combat");
      }
      message = tr("Postoupil jsi do patra $floor! Máš nové talentové body. 🌟 Tower modifikátor: $towerModText!", "You advanced to floor $floor! You have new talent points. 🌟 Tower modifier: $towerModText!");
    }

    // Roztříštění (curse): nepřítel (ne boss, ne už úlomek) se při smrti rozštěpí na 2 slabší kopie.
    if (activeCurse == CurseOfFate.fragmentation && !isBoss && !currentEnemyIsFragment) {
      pendingFragments = 2;
      fragmentAtk = (currentEnemyAtk * 0.4).toInt();
      fragmentDef = (currentEnemyDef * 0.4).toInt();
      fragmentMaxHp = (currentEnemyMaxHp * 0.4).toInt();
      fragmentIsMagical = currentEnemyIsMagical;
      message += tr(" 💥 Nepřítel se rozštěpil na 2 úlomky!", " 💥 The enemy split into 2 fragments!");
    }

    _checkQuests();
    _checkAchievements();
    _generateNextEnemy();
  }

  // Vyřeší jedno kolo boje ve věži (protiúder nepřítele, tik efektů, regenerace zdroje, auto-heal).
  // Volá se jak po základním útoku, tak po seslání schopnosti - použití schopnosti = jedno kolo.
  void _resolveCombatRound() {
    combatRoundCount++; // enrage: počítá se každá vyměněná rána, i uhnutá/blokovaná
    // ===== Nepřátelská schopnost - VŽDY na 2. kole (viz enemyAbilityEffects) =====
    // Musí proběhnout PŘED dodge rollem níž, ať ignoreBlockDodge/stun/blockSpell stihnou
    // ovlivnit tohle samé kolo. Kinds co potřebují znát rawDamage (ignoreArmor/guaranteedCrit/
    // doubleAttack/bossLifesteal) si jen "poznamenají" lokální proměnnou, spotřebovanou později
    // při výpočtu rawDamage/enemyCrit/finalDmg níž ve stejné funkci.
    double abilityDamageBonusPct = 0;
    bool abilityGuaranteedCrit = false;
    double abilityBossLifestealPct = 0;
    if (combatRoundCount == 2) {
      final def = enemyAbilityEffects[currentEnemyAbility];
      if (def != null) {
        switch (def.kind) {
          case EnemyAbilityKind.statDebuff:
            heroEffects.add(StatusEffect.statDebuff(name: "Schopnost: $currentEnemyAbility", description: tr("$currentEnemyName použil svou schopnost.", "$currentEnemyName used its ability."), duration: def.duration, mods: def.mods));
            break;
          case EnemyAbilityKind.stackingDebuff:
            heroEffects.removeWhere((e) => e.name == "Schopnost: $currentEnemyAbility");
            heroEffects.add(StatusEffect.statDebuff(name: "Schopnost: $currentEnemyAbility", description: tr("$currentEnemyName použil svou schopnost (stackuje se).", "$currentEnemyName used its ability (stacks)."), duration: def.duration, mods: def.mods));
            break;
          case EnemyAbilityKind.dot:
            heroEffects.add(StatusEffect(name: "Schopnost: $currentEnemyAbility", description: tr("$currentEnemyName tě otrávil/zapálil.", "$currentEnemyName poisoned/burned you."), duration: def.duration, isBuff: false, dotDamage: (maxHp * def.amount).round()));
            break;
          case EnemyAbilityKind.trueDamage:
            hp = max(0, hp - (maxHp * def.amount).round());
            break;
          case EnemyAbilityKind.ignoreArmor:
            abilityDamageBonusPct += def.amount;
            break;
          case EnemyAbilityKind.ignoreBlockDodge:
            heroEffects.add(StatusEffect.statDebuff(name: "Schopnost: $currentEnemyAbility", description: tr("Tenhle útok nejde blokovat ani uhnout.", "This attack can't be blocked or dodged."), duration: 1, mods: {'dodge': -1.0, 'block': -1.0}));
            break;
          case EnemyAbilityKind.guaranteedCrit:
            abilityGuaranteedCrit = true;
            break;
          case EnemyAbilityKind.doubleAttack:
            abilityDamageBonusPct += 1.0;
            break;
          case EnemyAbilityKind.stun:
            heroStunTurns += def.duration;
            break;
          case EnemyAbilityKind.blockSpell:
            heroSpellBlockTurns += def.duration;
            break;
          case EnemyAbilityKind.bossBuff:
            currentEnemyAtk = (currentEnemyAtk * (1 + def.amount)).round();
            enemyEffects.add(StatusEffect(name: "Schopnost: $currentEnemyAbility", description: tr("Posílený útok.", "Empowered attack."), duration: def.duration, isBuff: true));
            break;
          case EnemyAbilityKind.bossArmorBuff:
            currentEnemyDef = (currentEnemyDef * (1 + def.amount)).round();
            enemyEffects.add(StatusEffect(name: "Schopnost: $currentEnemyAbility", description: tr("Posílená obrana.", "Empowered defense."), duration: def.duration, isBuff: true));
            break;
          case EnemyAbilityKind.bossShield:
            currentEnemyShield += (currentEnemyMaxHp * def.amount).round();
            break;
          case EnemyAbilityKind.bossHeal:
            currentEnemyHp = min(currentEnemyMaxHp, currentEnemyHp + (currentEnemyMaxHp * def.amount).round());
            break;
          case EnemyAbilityKind.bossLifesteal:
            abilityBossLifestealPct = def.amount;
            break;
          case EnemyAbilityKind.resourceDrain:
            _drainResourcePct(def.amount);
            break;
          case EnemyAbilityKind.goldDrain:
            gold = max(0, (gold * (1 - def.amount)).round());
            break;
          case EnemyAbilityKind.cancelShield:
            bonusShield = 0;
            break;
          case EnemyAbilityKind.cancelBuff:
            final activeBuffs = heroEffects.where((e) => e.isBuff).toList();
            if (activeBuffs.isNotEmpty) heroEffects.remove(activeBuffs.first);
            break;
        }
        message = tr("⚔️ $currentEnemyName použil schopnost: $currentEnemyAbility!", "⚔️ $currentEnemyName used its ability: $currentEnemyAbility!");
        notifyListeners();
      }
    }
    _checkHenryBuff();
    _checkLauferBuff();
    _checkFenwickBuff();
    _checkThorinBuff();
    _checkAnriBuff();
    _checkRawenBuff();
    _tickEffects((dot) => currentEnemyHp -= dot);
    _regenResource();
    if (currentEnemyHp <= 0) {
      _handleEnemyDeath();
      notifyListeners();
      return;
    }
    // Freeze (Frost Sigil Lv70, viz _castDkSigil): nepřítel na tolik svých útoků "vynechá tah".
    if (enemyStunTurns > 0) {
      enemyStunTurns--;
      message = tr("🥶 Nepřítel je zmrazený a nemůže zaútočit!", "🥶 The enemy is frozen and cannot attack!");
      notifyListeners();
      return;
    }
    // Hardcore set "Nezdolná Pevnost" 6pc: útok nepřítele zcela negován (jednorázově).
    if (hardcoreInvulnerableActive) {
      hardcoreInvulnerableActive = false;
      message = "🛡️✨ Nezdolná Pevnost: " + tr("útok zcela odražen!", "the attack was completely deflected!");
      notifyListeners();
      return;
    }
    // Úhyb: pokud uspěje, hrdina se zcela vyhne útoku nepřítele (i jeho jmenované schopnosti).
    if (Random().nextDouble() < dodgeChance) {
      message = tr("✨ Úhyb! Vyhnul jsi se útoku nepřítele.", "✨ Dodge! You evaded the enemy's attack.");
      _pushFx(FxKind.miss, FxSide.hero);
      hapticSelectionClick();
      // Duelist Grácie: úspěšný úhyb spustí counter-attack.
      if (hasGraceCounter) {
        final counterDmg = (physAtk * 0.70).toInt();
        currentEnemyHp -= counterDmg;
        message += tr(" Counter-attack za $counterDmg dmg!", " Counter-attack for $counterDmg dmg!");
      }
      // Hunter Ghost Sigil: úspěšný úhyb vyvolá přízračnou odvetu, dokud běží "Ve stínu" (viz _castHunterSigil).
      if (heroClass == HeroClass.hunter && isSpecRelicEquipped && currentSpecRelic.kind == SpecRelicKind.hunterGhostQuiver && heroEffects.any((e) => e.name == 'Ve stínu')) {
        _hunterGhostCounter();
      }
      // Duelist Dance Crest: úspěšný úhyb vyvolá Riposte navíc k vrozené Duelist Grácii výš, dokud běží "Ve tanci" (viz _castDuelistSigil).
      if (heroClass == HeroClass.duelist && isSpecRelicEquipped && currentSpecRelic.kind == SpecRelicKind.duelistDanceCrest && heroEffects.any((e) => e.name == 'Ve tanci')) {
        _duelistDanceCounter();
      }
      if(isBoss)_rewardTowerDefense();
      notifyListeners();
      return;
    }
    int rawDamage;
    if (isBoss) {
      int phys = mitigateDamage(currentEnemyAtk, DamageKind.physical);
      int mag = mitigateDamage(currentEnemyAtk, DamageKind.magical);
      rawDamage = ((phys + mag) / 2).toInt();
    } else {
      // Sjednoceno na stejnou Armor křivku (mitigateDamage) jako u bossů výš - dřív tu byl
      // starý plochý odečet (currentEnemyAtk - def), nekonzistentní se zbytkem systému.
      rawDamage = mitigateDamage(currentEnemyAtk, currentEnemyIsMagical ? DamageKind.magical : DamageKind.physical);
    }
    // Nepřátelská schopnost (2. kolo) - ignoreArmor/doubleAttack se projeví jako bonus k rawDamage
    // (viz abilityDamageBonusPct výš), guaranteedCrit se sloučí do enemyCrit rollu níž.
    if (abilityDamageBonusPct > 0) rawDamage = (rawDamage * (1 + abilityDamageBonusPct)).round();
    // Blood Sigil Lv30 (viz _castDkSigil): Krvavý parazit oslabuje útok nepřítele po zbytek souboje.
    if (_dkBloodEnemyDmgReductionPct > 0) rawDamage = (rawDamage * (1 - _dkBloodEnemyDmgReductionPct)).round();
    // Minimální poškození nepřítele ve Věži: 5 % hráčova max HP, ať Armor útok nikdy
    // nezredukuje na zanedbatelné číslo. Enrage/Krvavá lázeň níž ještě může jít nad tenhle floor.
    final int towerMinDmg = (maxHp * 0.05).toInt();
    if (rawDamage < towerMinDmg) rawDamage = towerMinDmg;

    // Tower modifikátor: NEPŘÍTEL může kritnout na svém útoku (viz enemyCritChance) - dřív
    // tenhle stack posiloval hrdinův critChance, teď posiluje nepřítele. abilityGuaranteedCrit
    // (viz 2. kolo výš) vynutí crit bez ohledu na roll.
    final bool enemyCrit = abilityGuaranteedCrit || Random().nextDouble() < enemyCritChance;
    if (enemyCrit) {
      rawDamage = (rawDamage * enemyCritDamageMultiplier).toInt();
      message = tr("💥 Nepřítel zasáhl kriticky!", "💥 The enemy landed a critical hit!");
    }

    // ===== ENRAGE (nad 20. kolo, jen v Hardcore Mode a výš) =====
    // Aritmetická řada +15 %, +20 %, +25 %, +30 %... (krok +5 % za každé další kolo nad limit),
    // sčítá se kumulativně a bez stropu - přirozeným stropem je, že jeden zásah stejně nikdy
    // neublíží víc, než kolik má hráč max HP, takže to dřív nebo později boj prostě ukončí.
    // Na Normal obtížnost enrage neplatí - hráč je na začátku slabý a boje jsou i tak dost dlouhé.
    // Hardcore/Předpeklí/Peklo jsou exkluzivní volba obtížnosti (viz setDifficultyTier), takže
    // atLeastHardcore pokrývá všechny tři, ne jen doslova zapnutý hardcoreMode.
    if (atLeastHardcore && combatRoundCount > 20) {
      final int n = combatRoundCount - 20;
      final double totalBonusPercent = n * (30 + (n - 1) * 5) / 2;
      final double enrageMult = 1 + totalBonusPercent / 100;
      rawDamage = (rawDamage * enrageMult).toInt();
      message += tr(" 🔥 ZUŘÍ! (+${totalBonusPercent.toInt()} % útoku)", " 🔥 ENRAGED! (+${totalBonusPercent.toInt()}% attack)");
    }

    // Krvavá lázeň (curse): čím méně HP má nepřítel, tím větší damage dává (až +100 % při umírání).
    if (activeCurse == CurseOfFate.bloodbath && currentEnemyMaxHp > 0) {
      final missingRatio = (1.0 - currentEnemyHp / currentEnemyMaxHp).clamp(0.0, 1.0);
      rawDamage = (rawDamage * (1 + missingRatio)).toInt();
    }

    // Válečník: reflect magického poškození – šance = polovina aktuální šance na blok
    if (heroClass == HeroClass.warrior && currentEnemyIsMagical) {
      if (Random().nextDouble() < blockChance / 2) {
        currentEnemyHp -= rawDamage;
        message = tr("⚡ Magický odraz! $rawDamage poškození odráženo zpět nepříteli!", "⚡ Magic reflect! $rawDamage damage reflected back at the enemy!");
        if (currentEnemyHp <= 0) {
          _handleEnemyDeath();
          notifyListeners();
          return;
        }
        notifyListeners();
        return;
      }
    }

    // Blok, redukce z run, absorpce štítem, Božská odplata, Jed, Mnich konverze, HP odečet,
    // gem defense - sdílená pipeline (viz _applyIncomingDamage), + Tower-specific hooky přes callbacky.
    int finalDmg = 0;
    final gemSaved = _applyIncomingDamage(
      rawDamage,
      (reflected) => currentEnemyHp -= reflected,
      onShieldAbsorbed: (absorbed) { if (isBoss && rawDamage == 0 && absorbed > 0) _rewardTowerDefense(); },
      onFinalDamage: (d) => finalDmg = d,
      isCrit: enemyCrit,
    );
    if (currentEnemyHp <= 0) {
      _handleEnemyDeath();
      notifyListeners();
      return;
    }
    // Deathknight: soul runa za obdržené poškození (dmg taken)
    if (heroClass == HeroClass.deathknight && finalDmg > 0) _gainSoulRune();
    // Nepřátelská schopnost (2. kolo): lifesteal boss - vyléčí bosse o % z tohoto úderu.
    if (abilityBossLifestealPct > 0 && finalDmg > 0) {
      currentEnemyHp = min(currentEnemyMaxHp, currentEnemyHp + (finalDmg * abilityBossLifestealPct).round());
    }
    if (autoHealUnlocked && autoHealEnabled && hp <= (maxHp * autoHealThreshold) && hp > 0) {
      final potion = consumables.firstWhere((i) => i.name == "Léčivý lektvar", orElse: () => Item(name: "None", value: 0, stats: {}, rarity: Rarity.common));
      if (potion.name == "Léčivý lektvar") useItem(potion);
    }
    if (hp <= 0 && !gemSaved) {
      if (phoenixChargeActive) {
        phoenixChargeActive = false;
        hp = (maxHp * 0.5).toInt();
        message = "Elixír Fénixe " + tr("tě zachránil před smrtí! Obnoveno 50% HP.", "saved you from death! 50% HP restored.");
      } else {
        _triggerDeath(tr("Zemřel jsi na patře $floor! (${currentEnemyName})", "You died on floor $floor! (${currentEnemyName})"), killer: currentEnemyName);
        return;
      }
    }
    notifyListeners();
  }

  // Tower modifikátor: aplikuje enemyDodgeChance/enemyBlockChance/currentEnemyShield na přímé
  // poškození, které hráč (základní útok i schopnosti) udílí Tower nepříteli. Záměrně se
  // NEVZTAHUJE na DoT tiky, kletby ani na explicitní "ignoruje mitigaci" reflect procy (Božská
  // Odplata apod.) - stejně jako tyhle typy poškození nikdy neprocházely hráčovou vlastní
  // obranou (dodge/block/štít) na druhé straně souboje.
  int _mitigateEnemyDamage(int dmg, {bool isCrit = false}) {
    if (dmg <= 0) return dmg;
    if (Random().nextDouble() < enemyDodgeChance) {
      _pushFx(FxKind.miss, FxSide.enemy);
      hapticSelectionClick();
      return 0;
    }
    bool blocked = false;
    if (Random().nextDouble() < enemyBlockChance) {
      dmg = (dmg * (1 - enemyBlockReduction)).toInt();
      blocked = true;
    }
    int absorbed = 0;
    if (currentEnemyShield > 0 && dmg > 0) {
      if (dmg > currentEnemyShield) {
        absorbed = currentEnemyShield;
        dmg -= currentEnemyShield;
        currentEnemyShield = 0;
      } else {
        absorbed = dmg;
        currentEnemyShield -= dmg;
        dmg = 0;
      }
    }
    if (absorbed > 0) _pushFx(FxKind.absorbed, FxSide.enemy, value: absorbed);
    if (dmg > 0) {
      _pushFx(blocked ? FxKind.blocked : (isCrit ? FxKind.critDamage : FxKind.normalDamage), FxSide.enemy, value: dmg);
      hapticImpactMedium();
    } else if (blocked) {
      hapticImpactLight();
    }
    return dmg;
  }

  void fight(bool isMagic) {
    if (isDead || heroClass == HeroClass.none || isInLair) return;
    if (_checkCombatGate(isSpell: false)) return;

    int dealtDmg;
    bool isCrit = nextAttackGuaranteedCrit || Random().nextDouble() < critChance;
    if (nextAttackGuaranteedCrit) nextAttackGuaranteedCrit = false;

    if (heroClass == HeroClass.deathknight) {
      // Hybridní úder: poměr fyz/mag podílu se počítá z physAtk/magAtk samotných (base staty +
      // itemy + spec váha už jsou v nich zahrnuté), NE z holých talent bodů v Síle/Moudrosti.
      // Oprava: dřív se používalo totalStrength/totalWisdom, což je na levelu 1 (než hráč rozdá
      // první talent bod) 0/0 - strRatio i wisRatio vyšly 0, takže se z mitigated poškození
      // rozdělilo 0+0 a útok spadl na 10% floor místo skutečné (mitigated) hodnoty. DK tak dával
      // ~5x míň dmg než Warrior hned na startu hry. physAtk/magAtk mají vždy základ 20+20 i bez
      // jediného investovaného bodu, takže touhle cestou nikdy nevyjde degenerované 0/0.
      // Vzorec: základní dmg = průměr (physAtk+magAtk)/2 - poměr fyz/mag složky (pro
      // specDkPhysMod/specDkMagMod) se počítá zvlášť z toho, který stat dělá větší část.
      final int totalAtk = physAtk + magAtk;
      final int combined = (totalAtk / 2).round();
      final double physShare = totalAtk > 0 ? physAtk / totalAtk : 0.5;
      final double magShare = totalAtk > 0 ? magAtk / totalAtk : 0.5;
      final armorPen = runeEffect(RuneEffectType.armorPen);
      // Pozn.: opraveno - dřív se tu chybně používala vlastní obrana hrdiny (Armor)
      // místo obrany nepřítele (currentEnemyDef).
      final int effDef = armorPen > 0 ? (currentEnemyDef * (1 - armorPen)).clamp(0, double.infinity).toInt() : currentEnemyDef;
      final int mitigated = max(0, combined - effDef);
      // Specializace: Mráz posiluje fyzickou složku, Nákaza magickou/DoT složku (viz specDkPhysMod/specDkMagMod).
      final int physPart = (mitigated * physShare * specDkPhysMod).toInt();
      final int magPart  = (mitigated * magShare * specDkMagMod).toInt();
      dealtDmg = _minDmg(combined, physPart + magPart);
    } else if (hasParagon150 && heroClass == HeroClass.warrior) {
      // Hněv šampiona: fyzický útok posílený aktuální hladinou Hněvu (až +30 % při plném Hněvu).
      final armorPen = runeEffect(RuneEffectType.armorPen);
      int effDef = armorPen > 0 ? (currentEnemyDef * (1 - armorPen)).clamp(0, double.infinity).toInt() : currentEnemyDef;
      final double rageRatio = maxRage > 0 ? (rage / maxRage).clamp(0.0, 1.0) : 0.0;
      int dmg = (physAtk + physAtk * rageRatio * 0.30).toInt();
      dealtDmg = _minDmg(dmg, dmg - effDef);
    } else if (hasParagon150 && heroClass == HeroClass.hunter) {
      // Znamení lovce: fyzický útok, stávající stacky (0-5) přidávají +3 % dmg/stack.
      final armorPen = runeEffect(RuneEffectType.armorPen);
      int effDef = armorPen > 0 ? (currentEnemyDef * (1 - armorPen)).clamp(0, double.infinity).toInt() : currentEnemyDef;
      int dmg = physAtk;
      dealtDmg = _minDmg(dmg, dmg - effDef);
      dealtDmg = (dealtDmg * (1 + huntersMarkStacks * huntersMarkPerStack)).toInt();
    } else if (hasParagon150 && heroClass == HeroClass.healer) {
      // Trest Světla: čistě magický útok (heal/shield synergie se řeší níže).
      final armorPen = runeEffect(RuneEffectType.armorPen);
      int effDef = armorPen > 0 ? (currentEnemyDef * (1 - armorPen)).clamp(0, double.infinity).toInt() : currentEnemyDef;
      int dmg = magAtk;
      dealtDmg = _minDmg(dmg, dmg - effDef);
    } else if (hasParagon150 && heroClass == HeroClass.mage) {
      // Arkánový výbuch: magický útok, existující Arcane Charge stacky (0-5) přidávají +4 % dmg/stack.
      final armorPen = runeEffect(RuneEffectType.armorPen);
      int effDef = armorPen > 0 ? (currentEnemyDef * (1 - armorPen)).clamp(0, double.infinity).toInt() : currentEnemyDef;
      int dmg = magAtk;
      dealtDmg = _minDmg(dmg, dmg - effDef);
      dealtDmg = (dealtDmg * (1 + arcaneChargeStacks * arcaneChargePerStack)).toInt();
    } else if (hasParagon150 && heroClass == HeroClass.duelist) {
      // Elegantní výpad: fyzický útok, uděluje dočasný dodge buff (a u Grácie counter-attack šanci).
      final armorPen = runeEffect(RuneEffectType.armorPen);
      int effDef = armorPen > 0 ? (currentEnemyDef * (1 - armorPen)).clamp(0, double.infinity).toInt() : currentEnemyDef;
      int dmg = physAtk;
      dealtDmg = _minDmg(dmg, dmg - effDef);
    } else if (hasParagon150 && heroClass == HeroClass.monk) {
      // Plynoucí Čchi: fyzický útok, stávající stacky (0-5) přidávají +3 % dmg/stack.
      final armorPen = runeEffect(RuneEffectType.armorPen);
      int effDef = armorPen > 0 ? (currentEnemyDef * (1 - armorPen)).clamp(0, double.infinity).toInt() : currentEnemyDef;
      int dmg = physAtk;
      dealtDmg = _minDmg(dmg, dmg - effDef);
      dealtDmg = (dealtDmg * (1 + flowingChiStacks * flowingChiPerStack)).toInt();
    } else {
      int dmg = (isMagic ? magAtk : physAtk);
      // Pozn.: opraveno - dřív se tu chybně používala vlastní obrana hrdiny (Armor)
      // místo obrany nepřítele (currentEnemyDef).
      int targetDef = currentEnemyDef;
      // Runa průrazu: sníží efektivní obranu nepřítele.
      final armorPen = runeEffect(RuneEffectType.armorPen);
      if (armorPen > 0) targetDef = (targetDef * (1 - armorPen)).clamp(0, double.infinity).toInt();
      dealtDmg = _minDmg(dmg, dmg - targetDef);
    }

    dealtDmg = (dealtDmg * basicAttackRoleMod).toInt();
    if (isCrit) dealtDmg = (dealtDmg * critDamageMultiplier).toInt();
    if (nextAttackDamageBoost) { dealtDmg = (dealtDmg * 1.1).toInt(); nextAttackDamageBoost = false; }
    // Runa "poškození bossům" - platí jen proti bossům ve věži.
    if (isBoss) {
      final bossDmgBonus = runeEffect(RuneEffectType.bossDamage);
      if (bossDmgBonus > 0) dealtDmg = (dealtDmg * (1 + bossDmgBonus)).toInt();
    dealtDmg = (dealtDmg * specializationBossDamageMod).toInt();
    }
    if (isCrit) message = tr("💥 Kritický zásah! Způsobeno $dealtDmg poškození.", "💥 Critical hit! Dealt $dealtDmg damage.");
    dealtDmg = _applyGemOffense(dealtDmg, enemyHp: currentEnemyHp, enemyMaxHp: currentEnemyMaxHp);
    // Tower modifikátor: NEPŘÍTEL má šanci hráčův útok uhnout/zablokovat a na začátku boje
    // dostal absorb štít (viz _mitigateEnemyDamage) - dřív tyhle bonusy dostával hráč, teď je
    // dostává nepřítel, takže Věž s postupem přituhuje na jeho straně. _mitigateEnemyDamage si
    // sama řeší FX/haptiku, tady jen doplníme zprávu a combo streak.
    final int preMitigationDmg = dealtDmg;
    dealtDmg = _mitigateEnemyDamage(dealtDmg, isCrit: isCrit);
    if (dealtDmg == 0 && preMitigationDmg > 0) {
      message = tr("💨 Nepřítel uhnul tvému útoku!", "💨 The enemy dodged your attack!");
      comboStreak = 0;
    } else {
      if (dealtDmg < preMitigationDmg) message = tr("🛡️ Nepřítel zablokoval/vykryl útok! Sníženo na $dealtDmg.", "🛡️ The enemy blocked/parried the attack! Reduced to $dealtDmg.");
      comboStreak++;
    }
    currentEnemyHp -= dealtDmg;
    // Signál pro UI (viz _BasicAttackSkinOverlay) - přehraje krátký burst v barvě nasazeného
    // skinu základního útoku. Musí být tady (jednou za KAŽDÝ skutečný zásah, včetně Extra
    // Attack rekurze níž), ne až za _resolveCombatRound(), aby chytil i extra útoky zvlášť.
    basicAttackFxSeq++;

    // Deathknight: soul runa za každý útok (dmg done)
    if (heroClass == HeroClass.deathknight) _gainSoulRune();
    _applyKrevPassiveLifesteal(dealtDmg); // Krev: pasivní 5 % lifesteal ze základního útoku

    // ===== PARAGON 150 — signature synergie =====
    if (hasParagon150) {
      final critPrefix = isCrit ? '💥 Kritický zásah! ' : '';
      if (heroClass == HeroClass.warrior) {
        rage = (rage + 10).clamp(0, maxRage);
        message = tr("$critPrefix Hněv šampiona: $dealtDmg dmg (+10 Hněvu)!", "$critPrefix Hněv šampiona: $dealtDmg dmg (+10 Rage)!");
      } else if (heroClass == HeroClass.hunter) {
        huntersMarkStacks = (huntersMarkStacks + 1).clamp(0, huntersMarkMaxStacks);
        message = tr("$critPrefix Znamení lovce: $dealtDmg dmg (stack $huntersMarkStacks/$huntersMarkMaxStacks)!", "$critPrefix Znamení lovce: $dealtDmg dmg (stack $huntersMarkStacks/$huntersMarkMaxStacks)!");
      } else if (heroClass == HeroClass.deathknight) {
        final curseIdx = enemyEffects.indexWhere((e) => e.name == "Prokletí");
        if (curseIdx != -1) {
          final curse = enemyEffects[curseIdx];
          if (curse.duration < curseMaxDuration) curse.duration += 1;
          message = tr("$critPrefix Runová trhlina: $dealtDmg dmg (Prokletí prodlouženo na ${curse.duration} kol)!", "$critPrefix Runová trhlina: $dealtDmg dmg (Curse extended to ${curse.duration} rounds)!");
        } else {
          message = tr("$critPrefix Runová trhlina: $dealtDmg dmg.", "$critPrefix Runová trhlina: $dealtDmg dmg.");
        }
      } else if (heroClass == HeroClass.mage) {
        arcaneChargeStacks = (arcaneChargeStacks + arcaneChargeGainPerHit).clamp(0, arcaneChargeMaxStacks);
        message = tr("$critPrefix Arkánový výbuch: $dealtDmg dmg (stack $arcaneChargeStacks/$arcaneChargeMaxStacks)!", "$critPrefix Arkánový výbuch: $dealtDmg dmg (stack $arcaneChargeStacks/$arcaneChargeMaxStacks)!");
      } else if (heroClass == HeroClass.duelist) {
        heroEffects.removeWhere((e) => e.name == "Elegantní výpad");
        heroEffects.add(StatusEffect(name: "Elegantní výpad", description: "+10 % dodge", duration: 3, isBuff: true));
        message = tr("$critPrefix Elegantní výpad: $dealtDmg dmg (+10 % dodge na 3 kola)!", "$critPrefix Elegantní výpad: $dealtDmg dmg (+10% dodge for 3 rounds)!");
      } else if (heroClass == HeroClass.monk) {
        flowingChiStacks = (flowingChiStacks + 1).clamp(0, flowingChiMaxStacks);
        message = tr("$critPrefix Plynoucí Čchi: $dealtDmg dmg (stack $flowingChiStacks/$flowingChiMaxStacks)!", "$critPrefix Plynoucí Čchi: $dealtDmg dmg (stack $flowingChiStacks/$flowingChiMaxStacks)!");
      }
    }

    // Léčitel: základní útok vytváří absorb (štít) ve výši 15 % způsobeného poškození
    // (Paragon 150 "Trest Světla" navíc přidá 10 % dealtDmg jako self-heal.)
    if (heroClass == HeroClass.healer) {
      final absorb = (dealtDmg * 0.15).toInt();
      if (absorb > 0) {
        bonusShield += absorb;
        _applyShieldCap();
        final critPrefix = isCrit ? '💥 Kritický zásah! ' : '';
        if (hasParagon150) {
          final selfHeal = (dealtDmg * 0.10).toInt();
          hp = (hp + selfHeal).clamp(0, maxHp);
          message = tr("$critPrefix Trest Světla: $dealtDmg dmg → štít +$absorb, heal +$selfHeal.", "$critPrefix Trest Světla: $dealtDmg dmg → shield +$absorb, heal +$selfHeal.");
          _cleansePoisonSynergy();
          _healIntoShieldSynergy(selfHeal);
        } else {
          message = tr("$critPrefix Útok léčitele: $dealtDmg dmg → štít +$absorb.", "$critPrefix Healer's attack: $dealtDmg dmg → shield +$absorb.");
        }
      }
    }

    if (lifestealTurns > 0) {
      int heal = (dealtDmg * 0.2 * specLifestealMod).toInt();
      hp = (hp + heal).clamp(0, maxHp);
      _cleansePoisonSynergy();
      _healIntoShieldSynergy(heal);
    }
    final runeLs = runeEffect(RuneEffectType.lifesteal);
    if (runeLs > 0) {
      final lsHeal = (dealtDmg * runeLs * specLifestealMod).toInt();
      hp = (hp + lsHeal).clamp(0, maxHp);
      _cleansePoisonSynergy();
      _healIntoShieldSynergy(lsHeal);
    }
    _applyDarknessSynergy(dealtDmg);
    // Odraz (curse): 15 % způsobeného poškození se vrátí hrdinovi jako damage.
    if (activeCurse == CurseOfFate.reflection && dealtDmg > 0) {
      final reflectedDmg = (dealtDmg * 0.15).toInt();
      hp -= reflectedDmg;
      if (reflectedDmg > 0) message += " (Odraz: -$reflectedDmg HP)";
    }
    _applyRuneProcs(dealtDmg);
    if (currentEnemyHp > 0 && rollExtraAttack()) {
      message += tr(' ⚡ Extra Attack!', ' ⚡ Extra Attack!');
      _extraAttackInProgress = true;
      fight(isMagic);
      _extraAttackInProgress = false;
      return;
    }
    _resolveCombatRound();
  }

  bool relicEffectActive(int requiredLevel)=>currentSpecRelicLevel>=requiredLevel;
  double get relicLevelScalar=>1+currentSpecRelicLevel*.01;

  // ===== DK Sigil implementace (Blood/Frost/Plague) =====
  // Nahrazuje pro tyhle 3 kindy generický switch(r.mechanic) - viz volání v
  // useSpecRelicArenaSpell/TowerSpell/LairSpell/WorldBossSpell výš. isBossTarget: Tower posílá
  // skutečné isBoss, ostatní módy (Arena/Lair/WorldBoss) vždy true (jsou to "boss" souboje,
  // takže Freeze CC tam nedává smysl - dostanou jen bonus damage variantu).
  // POZNÁMKA K ROZSAHU: efekty co podle textu v UI ovlivňují VŠECHNY další útoky hráče (ne jen
  // tenhle cast relicu) jsou zjednodušené - "Armor cíle sníženo" (Frost Lv30/Plague Lv30) je
  // propsáno jen do vlastního burst damage tohohle castu, ne jako trvalý debuff feedující do
  // celé útočné pipeline (ta je rozeseta v desítkách funkcí přes hru a bezpečně to editovat by
  // vyžadovalo samostatný průchod). Věcně to pořád dělá nepřítele znatelně křehčí vůči Shatter/
  // Apocalypse burstu, jen ne vůči základnímu útoku/schopnostem mimo relic.
  _DkSigilResult _castDkSigil(SpecRelicDef r, int dmg, {required bool isBossTarget}) {
    int heal = 0, shield = 0;
    String extra = '';
    if (r.kind == SpecRelicKind.deathKnightBloodSigil) {
      // ----- BLOOD: Krvavý parazit (DoT + sebeléčení + štít + armor stacky) -----
      final int parasiteDot = (dmg * (0.30 + currentSpecRelicLevel * .004)).round();
      enemyEffects.add(StatusEffect(
        name: 'Krvavý parazit',
        description: 'DoT $parasiteDot/kolo${relicEffectActive(30) ? " • oslabuje útok nepřítele" : ""}',
        duration: 3, isBuff: false, dotDamage: parasiteDot,
      ));
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '🩸 Krvavý parazit');
      heal = (parasiteDot * 3 * (0.5 + (relicEffectActive(20) ? 0.20 : 0))).round();
      bool healCrit = false;
      if (relicEffectActive(60) && Random().nextDouble() < critChance) { heal = (heal * 1.5).round(); healCrit = true; }
      hp = min(maxHp, hp + heal);
      if (healCrit) extra += ' • 🩸 heal CRIT';
      if (relicEffectActive(30)) _dkBloodEnemyDmgReductionPct = 0.15; // po zbytek souboje, jen ve Věži - viz _resolveCombatRound
      if (relicEffectActive(40)) {
        final vitBonus = relicEffectActive(50) ? (totalVitality * 0.02).round() : 0;
        shield = (heal * 0.4).round() + vitBonus;
        bonusShield += shield;
      }
      if (relicEffectActive(80)) {
        specRelicStacks = min(5, specRelicStacks + 1);
        heroEffects.removeWhere((e) => e.name == 'Krvavá zbroj');
        heroEffects.add(StatusEffect(name: 'Krvavá zbroj', description: '+${specRelicStacks * 3}% Armor', duration: 4, isBuff: true, armorMod: specRelicStacks * 0.03));
        extra += ' • 🩸 stack $specRelicStacks';
      }
      if (relicEffectActive(90) && maxHp > 0 && hp / maxHp < 0.35 && !_dkBloodEmergencyShieldUsed) {
        _dkBloodEmergencyShieldUsed = true;
        final emergency = (maxHp * 0.25).round();
        bonusShield += emergency;
        _pushFx(FxKind.shieldGained, FxSide.hero, value: emergency, burstKind: RelicBurstKind.bloodEmperor);
        extra += ' • 🩸 Crimson Emperor!';
      }
    } else if (r.kind == SpecRelicKind.deathKnightFrostSigil) {
      // ----- FROST: Frozen Soul stacky -> Shatter burst -> Freeze/Avatar zimy -----
      final int maxStacks = relicEffectActive(40) ? 2 : 1;
      if (relicEffectActive(10)) dmg = (dmg * 1.15).round();
      bool frostCrit = false;
      if (relicEffectActive(20) && specRelicStacks > 0 && Random().nextDouble() < 0.30) {
        dmg = (dmg * critDamageMultiplier).round();
        frostCrit = true;
      }
      specRelicStacks = min(maxStacks, specRelicStacks + 1);
      _restoreRelicArmorShredIfMatches('Zmrzlá duše'); // refresh debuffu - obnovit starý shred před přepočtem nového
      enemyEffects.removeWhere((e) => e.name == 'Zmrzlá duše');
      if (relicEffectActive(30)) _applyRelicArmorShred('Zmrzlá duše', 0.12);
      enemyEffects.add(StatusEffect(
        name: 'Zmrzlá duše',
        description: 'Stack $specRelicStacks/$maxStacks${relicEffectActive(30) ? " • Armor cíle -12 %" : ""}',
        duration: 3, isBuff: false,
      ));
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '❄️ Zmrzlá duše x$specRelicStacks');
      if (frostCrit) extra += ' • ❄️ CRIT';
      if (specRelicStacks >= maxStacks && relicEffectActive(50)) {
        int explosion = (dmg * (0.9 + specRelicStacks * 0.5)).round();
        bool shatterCrit = false;
        if (relicEffectActive(60) && Random().nextDouble() < critChance) { explosion = (explosion * critDamageMultiplier).round(); shatterCrit = true; }
        dmg += explosion;
        _restoreRelicArmorShredIfMatches('Zmrzlá duše'); // Shatter spotřebuje debuff - vrátit Armor
        enemyEffects.removeWhere((e) => e.name == 'Zmrzlá duše');
        specRelicStacks = 0;
        _pushFx(FxKind.explosionDamage, FxSide.enemy, value: explosion, burstKind: RelicBurstKind.iceShatter);
        extra += ' • 💥 Shatter${shatterCrit ? " CRIT" : ""}: +$explosion';
        if (relicEffectActive(70)) {
          if (!isBossTarget) {
            enemyStunTurns += 1;
            _pushFx(FxKind.stunned, FxSide.enemy, label: '🥶 ZMRAZEN!');
            extra += ' • Freeze!';
          } else {
            dmg = (dmg * 1.15).round();
            extra += ' • boss bonus dmg';
          }
        }
        if (relicEffectActive(90)) {
          heroEffects.removeWhere((e) => e.name == 'Avatar zimy');
          heroEffects.add(StatusEffect(name: 'Avatar zimy', description: '+15% Frost dmg, +10% Crit', duration: 2, isBuff: true, physAtkMod: 0.15, magAtkMod: 0.15, critMod: 0.10));
          extra += ' • ❄️ Avatar zimy!';
        }
      }
      // Lv80 "Putující zima" (carry stacku do dalšího nepřítele ve Věži) - viz guard v _generateNextEnemy().
    } else if (r.kind == SpecRelicKind.deathKnightPlagueSigil) {
      // ----- PLAGUE: Nekrotická hniloba (multi-stack DoT) -> Necrotic Apocalypse při vypršení -----
      final int maxPlagueStacks = relicEffectActive(70) ? 3 : 1;
      _dkPlagueStackCount = min(maxPlagueStacks, _dkPlagueStackCount + 1);
      int dotPerStack = (dmg * (0.22 + currentSpecRelicLevel * .005)).round();
      bool plagueCrit = relicEffectActive(50) && Random().nextDouble() < critChance;
      if (plagueCrit) dotPerStack = (dotPerStack * 1.4).round();
      // "Množení" (Lv70): stack počet dřív byl jen kosmetický text v popisku, dotDamage se jím
      // vůbec nenásobil - DoT dával stejně na stacku 1 i 3. Teď skutečně násobí tik podle
      // aktuálního počtu stacků (Necrotic Apocalypse níž s tím počítá taky, ne navíc).
      final int dot = dotPerStack * _dkPlagueStackCount;
      // "Rozklad zbroje" (Lv30): dřív jen text v popisku bez efektu. Teď skutečně sníží
      // currentEnemyDef o 15 % (jen ve Věži - Lair/Arena/WorldBoss mají vlastní def pole a tahle
      // oprava je necílí, viz _tickEffects() pro obnovu při vypršení DoT). Nekumuluje se, pokud by
      // relic šlo seslat vícekrát za boj (_relicArmorShredAmount==0 hlídá, že se to strhne jen jednou).
      if (relicEffectActive(30)) _applyRelicArmorShred('Nekrotická hniloba', 0.15);
      enemyEffects.add(StatusEffect(
        name: 'Nekrotická hniloba',
        description: 'DoT $dot/kolo${relicEffectActive(30) ? " • Armor cíle -15 %" : ""}${plagueCrit ? " • CRIT" : ""} (stack $_dkPlagueStackCount/$maxPlagueStacks)',
        duration: 3, isBuff: false, dotDamage: dot,
      ));
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '☣️ Nekrotická hniloba x$_dkPlagueStackCount');
      if (relicEffectActive(20)) {
        heal = (dot * 1.5).round();
        hp = min(maxHp, hp + heal);
      }
      if (relicEffectActive(40)) {
        heroEffects.removeWhere((e) => e.name == 'Nakažená kořist');
        heroEffects.add(StatusEffect(name: 'Nakažená kořist', description: '+10% dmg proti nakaženému cíli', duration: 3, isBuff: true, physAtkMod: 0.10, magAtkMod: 0.10));
      }
      if (relicEffectActive(60) && Random().nextDouble() < 0.35) {
        for (final e in enemyEffects.where((e) => e.name == 'Nekrotická hniloba')) { e.duration += 1; }
        extra += ' • ☣️ prodlouženo';
      }
      // Lv80 "Přenos epidemie" (carry stacku do dalšího nepřítele ve Věži) - viz guard v _generateNextEnemy().
      // Lv90 "Necrotic Apocalypse" (exploze při vypršení DoT) - viz hook v _tickEffects().
    }
    return _DkSigilResult(dmg, heal, shield, extra);
  }

  // ===== Hunter Quiver implementace (Marksman/Beast/Ghost) =====
  // Stejný vzorec jako _castDkSigil() výš - viz jeho úvodní poznámka k rozsahu (armor-pen/dodge-
  // debuff efekty co by jinak musely zasahovat do celé útočné pipeline jsou zjednodušené na bonus
  // k téhle konkrétní ráně). Ghost Quiver navíc má vlastní pasivní hák na Dodge - viz
  // _hunterGhostCounter(), volaný z _resolveCombatRound().
  _DkSigilResult _castHunterSigil(SpecRelicDef r, int dmg, {required double targetHpRatio, required bool isBossTarget}) {
    int heal = 0, shield = 0;
    String extra = '';
    if (r.kind == SpecRelicKind.hunterMarksmanQuiver) {
      // ----- MARKSMAN: Záměrný bod stacky (Přesnost) + execute + guaranteed crit finisher -----
      bool crit = (relicEffectActive(90) && targetHpRatio < 0.20) || Random().nextDouble() < critChance;
      if (crit) dmg = (dmg * (critDamageMultiplier + (relicEffectActive(60) ? 0.15 : 0))).round();
      final gain = (relicEffectActive(20) && crit) ? 2 : 1;
      specRelicStacks = min(5, specRelicStacks + gain);
      enemyEffects.removeWhere((e) => e.name == 'Záměrný bod');
      enemyEffects.add(StatusEffect(name: 'Záměrný bod', description: 'Přesnost $specRelicStacks/5${relicEffectActive(10) ? " • cíl má snížený Dodge" : ""}', duration: 3, isBuff: false));
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '🎯 Záměrný bod x$specRelicStacks');
      if (crit) extra += ' • 🎯 CRIT';
      if (relicEffectActive(10)) dmg = (dmg * 1.08).round();
      if (relicEffectActive(30)) dmg = (dmg * 1.12).round();
      if (relicEffectActive(50) && targetHpRatio < 0.30) { dmg = (dmg * 1.35).round(); extra += ' • Popravčí střela'; }
      if (relicEffectActive(70) && crit) { energy = (energy + 15).clamp(0, maxEnergy); extra += ' • +15 energie'; }
      if (relicEffectActive(90) && targetHpRatio < 0.20) {
        _pushFx(FxKind.explosionDamage, FxSide.enemy, value: dmg, burstKind: RelicBurstKind.executionShot);
        extra += ' • 🎯 Dokonalá poprava!';
      }
      // Lv80 "Další terč" (carry Záměrného bodu do dalšího nepřítele ve Věži) - viz guard v _generateNextEnemy().
    } else if (r.kind == SpecRelicKind.hunterBeastQuiver) {
      // ----- BEAST: společný útok s companionem, Lovecká horečka každý 3. cast, Pravý alfa finisher -----
      dmg = (dmg * 1.35).round();
      specRelicStacks += 1; // persistentní počítadlo lovů (napříč souboji) - řídí "každý třetí" proc
      huntersMarkStacks = min(huntersMarkMaxStacks, huntersMarkStacks + 1);
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '🐺 Povel alfy');
      bool beastCrit = Random().nextDouble() < critChance;
      if (beastCrit) {
        dmg = (dmg * critDamageMultiplier).round();
        if (relicEffectActive(70)) huntersMarkStacks = min(huntersMarkMaxStacks, huntersMarkStacks + 1);
        extra += ' • 🐺 CRIT';
      }
      if (relicEffectActive(20)) { heal = (dmg * 0.20).round(); hp = min(maxHp, hp + heal); }
      if (relicEffectActive(40)) dmg = (dmg * 1.10).round();
      if (relicEffectActive(50) && specRelicStacks % 3 == 0) {
        heroEffects.removeWhere((e) => e.name == 'Lovecká horečka');
        heroEffects.add(StatusEffect(name: 'Lovecká horečka', description: '+15% Atk${relicEffectActive(60) ? " • +10% Crit" : ""} na 2 kola', duration: 2, isBuff: true, physAtkMod: 0.15, magAtkMod: 0.15, critMod: relicEffectActive(60) ? 0.10 : 0));
        extra += ' • 🐺 Horečka!';
      }
      if (relicEffectActive(90)) {
        dmg = (dmg * (isBossTarget ? 1.22 : 1.12)).round();
        extra += ' • 🐺 Pravý alfa';
        _pushFx(FxKind.explosionDamage, FxSide.enemy, value: dmg, burstKind: RelicBurstKind.alphaHowl);
      }
      // Lv80 "Hostina vítězů" (heal na zabití nakaženého cíle) - viz hook v _handleEnemyDeath().
    } else if (r.kind == SpecRelicKind.hunterGhostQuiver) {
      // ----- GHOST: cast jen aktivuje "Ve stínu" - skutečná odveta běží z _hunterGhostCounter() -----
      heroEffects.removeWhere((e) => e.name == 'Ve stínu');
      heroEffects.add(StatusEffect(name: 'Ve stínu', description: 'Dodge vyvolá přízračnou odvetu', duration: 3, isBuff: true, dodgeMod: 0.05));
      _pushFx(FxKind.statusApplied, FxSide.hero, label: '👻 Ve stínu');
      dmg = (dmg * 1.10).round();
      extra += ' • 👻 Ve stínu aktivní';
    }
    return _DkSigilResult(dmg, heal, shield, extra);
  }

  // Hunter Ghost Sigil: úspěšný úhyb (dokud běží "Ve stínu", viz _castHunterSigil) vyvolá
  // přízračnou odvetu - dmg + jed (Lv10+) + crit šance (Lv40+) + počítá odvety pro Stínový skok
  // (Lv50, každá 3.) + heal ze skoku (Lv60+). Voláno z _resolveCombatRound() po dodge rollu.
  // Funguje jen ve Věži (míří přímo na currentEnemyHp).
  void _hunterGhostCounter() {
    final int counterDmg = (physAtk * (0.45 + currentSpecRelicLevel * .003)).round();
    final bool counterCrit = relicEffectActive(40) && Random().nextDouble() < (critChance + 0.15);
    int finalCounter = counterCrit ? (counterDmg * critDamageMultiplier).round() : counterDmg;
    currentEnemyHp -= finalCounter;
    String extra = ' 👻 Přízračná odveta: $finalCounter dmg${counterCrit ? " CRIT" : ""}!';
    _pushFx(FxKind.normalDamage, FxSide.enemy, value: finalCounter);
    if (relicEffectActive(10)) {
      final poisonDot = (finalCounter * 0.18).round();
      final poisonDur = 3 + (relicEffectActive(30) ? 1 : 0);
      enemyEffects.add(StatusEffect(name: 'Přízračný jed', description: 'Jed $poisonDot/kolo', duration: poisonDur, isBuff: false, dotDamage: poisonDot));
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '☠️ Přízračný jed');
    }
    specRelicStacks += 1;
    if (relicEffectActive(50) && specRelicStacks % 3 == 0) {
      final jumpDmg = (finalCounter * 0.9).round();
      currentEnemyHp -= jumpDmg;
      _pushFx(FxKind.explosionDamage, FxSide.enemy, value: jumpDmg, burstKind: RelicBurstKind.ghostLeap);
      if (relicEffectActive(60)) hp = min(maxHp, hp + (jumpDmg * 0.3).round());
      extra += ' • 👻 Stínový skok +$jumpDmg';
    }
    message += extra;
    if (currentEnemyHp <= 0) _handleEnemyDeath();
  }

  // ===== Warrior Banner implementace (Berserk/Guardian/Warlord) =====
  // Berserk a Warlord fungují stejným cast-based vzorem jako DK/Hunter výš. Guardian Banner je
  // jiný případ - je to obranný relic, takže jeho nejdůležitější efekty (Block counter, Výbuch
  // bašty, Nedobytná pevnost) NEJSOU v tomhle castu, ale hákují přímo do _applyIncomingDamage()
  // (sdílená pipeline pro VEŠKERÉ poškození, co hrdina dostane - viz komentáře tam).
  _DkSigilResult _castWarriorSigil(SpecRelicDef r, int dmg, {required double targetHpRatio, required bool isBossTarget}) {
    int heal = 0, shield = 0;
    String extra = '';
    if (r.kind == SpecRelicKind.warriorBerserkBanner) {
      // ----- BERSERK: Nespoutaná zuřivost stacky -> Rampage při maximu -----
      bool crit = Random().nextDouble() < critChance;
      if (crit) dmg = (dmg * critDamageMultiplier).round();
      final gain = (relicEffectActive(20) && crit) ? 2 : 1;
      specRelicStacks = min(5, specRelicStacks + gain);
      if (relicEffectActive(10)) rage = (rage + 8).clamp(0, maxRage);
      heroEffects.removeWhere((e) => e.name == 'Nespoutaná zuřivost');
      heroEffects.add(StatusEffect(name: 'Nespoutaná zuřivost', description: 'Stack $specRelicStacks/5', duration: 3, isBuff: true, critMod: relicEffectActive(30) ? specRelicStacks * 0.02 : 0));
      _pushFx(FxKind.statusApplied, FxSide.hero, label: '🔥 Zuřivost x$specRelicStacks');
      if (crit) extra += ' • CRIT';
      if (relicEffectActive(70) && maxHp > 0 && hp / maxHp < 0.40) { dmg = (dmg * 1.20).round(); extra += ' • Na hraně smrti'; }
      if (specRelicStacks >= 5 && relicEffectActive(50)) {
        int rampageDmg = (dmg * (0.8 + (relicEffectActive(60) && isBossTarget ? 0.3 : 0))).round();
        dmg += rampageDmg;
        specRelicStacks = 0;
        _pushFx(FxKind.explosionDamage, FxSide.enemy, value: rampageDmg, burstKind: RelicBurstKind.rampage);
        extra += ' • 🔥 Rampage +$rampageDmg';
        if (relicEffectActive(90)) {
          heroEffects.removeWhere((e) => e.name == 'Avatar zuřivosti');
          heroEffects.add(StatusEffect(name: 'Avatar zuřivosti', description: 'Garantovaný Extra Attack na dalším útoku', duration: 2, isBuff: true));
          extra += ' • Avatar zuřivosti!';
        }
      }
      // Lv40 "Neutuchající zuřivost" a Lv80 "Dědictví hněvu": Rage se mezi nepřáteli ve Věži
      // NIKDY neresetuje (viz _generateNextEnemy), takže se přenáší do dalšího boje přirozeně
      // i bez extra kódu - Lv80 tenhle už existující chování jen pojmenovává.
    } else if (r.kind == SpecRelicKind.warriorGuardianBanner) {
      // ----- GUARDIAN: štít + protiútok při bloku (viz _applyIncomingDamage) -----
      shield = (armor * .35 + maxHp * .12 + currentSpecRelicLevel * level).round();
      if (relicEffectActive(10)) shield += (totalVitality * 0.08).round();
      bonusShield += shield;
      dmg = (dmg * .55).round();
      _pushFx(FxKind.shieldGained, FxSide.hero, value: shield);
      if (relicEffectActive(70)) {
        _dkBloodEnemyDmgReductionPct = max(_dkBloodEnemyDmgReductionPct, 0.12);
        extra += ' • Umlčená hrozba';
      }
      // Lv20/30/40/50/60/90 - viz _applyIncomingDamage() hook.
      // Lv80 "Pochod pevnosti": bonusShield se mezi nepřáteli ve Věži nikdy neresetuje samo o sobě
      // (jen ho spotřebuje dopadající poškození), takže se přirozeně přenáší i bez extra kódu.
    } else if (r.kind == SpecRelicKind.warriorWarlordBanner) {
      // ----- WARLORD: Rozkaz - buff k útoku, "Taktická převaha" každý 2. cast -----
      bool crit = Random().nextDouble() < critChance;
      if (crit) dmg = (dmg * critDamageMultiplier).round();
      if (relicEffectActive(10)) rage = (rage + 10).clamp(0, maxRage);
      if (relicEffectActive(20)) dmg = (dmg * 1.15).round();
      if (relicEffectActive(30) && crit) rage = (rage + 15).clamp(0, maxRage);
      specRelicStacks += 1;
      if (relicEffectActive(50) && specRelicStacks % 2 == 0) {
        dmg = (dmg * 1.30).round();
        if (relicEffectActive(60) && isBossTarget) dmg = (dmg * 1.15).round();
        extra += ' • Taktická převaha';
      }
      if (relicEffectActive(80)) rage = (rage + 20).clamp(0, maxRage); // Vítězný pokřik - zjednodušeno na bonus Rage (relic nemá numerický cooldown ke zkrácení)
      if (relicEffectActive(90)) {
        dmg = (dmg * 1.10).round();
        extra += ' • Válečný vládce';
        _pushFx(FxKind.explosionDamage, FxSide.enemy, value: dmg, burstKind: RelicBurstKind.warlordCommand);
      }
    }
    return _DkSigilResult(dmg, heal, shield, extra);
  }

  // ===== Healer Symbol implementace (Dawn/Judgement/Battle) =====
  // specRelicStacks tady slouží jako "Světlo úsvitu" / počítadlo zásahů Rozsudku / Liturgie
  // krok - u všech tří jde o kontinuálně rostoucí počítadlo (ne 0-5 display stack jako u DK/
  // Warrior), takže se u nich nikdy neresetuje automaticky za nového nepřítele stejně jako u
  // Hunter Beast/Ghost - viz rozšíření guardu v _generateNextEnemy().
  _DkSigilResult _castHealerSigil(SpecRelicDef r, int dmg, {required double targetHpRatio, required bool isBossTarget}) {
    int heal = 0, shield = 0;
    String extra = '';
    if (r.kind == SpecRelicKind.healerDawnSymbol) {
      // ----- DAWN: heal + banked "Světlo úsvitu" (overheal) -> shield/Holy Damage/emergency heal -----
      heal = (maxHp * (.18 + currentSpecRelicLevel * .0015)).round();
      bool healCrit = relicEffectActive(40) && Random().nextDouble() < critChance;
      if (healCrit) heal = (heal * 1.5).round();
      if (relicEffectActive(20) && bonusShield > 0) heal = (heal * 1.15).round();
      hp = min(maxHp, hp + heal);
      dmg = (dmg * .45).round();
      final lightGain = (heal * 0.4).round();
      specRelicStacks += lightGain;
      _pushFx(FxKind.statusApplied, FxSide.hero, label: '☀️ Světlo úsvitu +$lightGain');
      if (healCrit) extra += ' • heal CRIT';
      if (relicEffectActive(10)) { shield = (lightGain * 0.5).round(); bonusShield += shield; }
      if (relicEffectActive(30) && specRelicStacks > 0) {
        final consume = min(specRelicStacks, 60);
        dmg += consume * 2;
        specRelicStacks -= consume;
        extra += ' • Svatý přenos';
      }
      if (relicEffectActive(50) && maxHp > 0 && hp / maxHp < 0.30 && specRelicStacks > 0) {
        final burst = specRelicStacks * 3;
        hp = min(maxHp, hp + burst);
        specRelicStacks = 0;
        _pushFx(FxKind.shieldGained, FxSide.hero, value: burst, burstKind: RelicBurstKind.eternalDawn);
        extra += ' • ☀️ Nouzová záře +$burst';
      }
      if (relicEffectActive(60)) {
        heroEffects.removeWhere((e) => e.name == 'Rozsudek' || (!e.isBuff && e.dotDamage > 0));
        extra += ' • Očista';
      }
      if (relicEffectActive(70) && bonusShield > 0) {
        heroEffects.removeWhere((e) => e.name == 'Magická záštita');
        heroEffects.add(StatusEffect(name: 'Magická záštita', description: '+10% Armor', duration: 3, isBuff: true, armorMod: 0.10));
      }
      if (relicEffectActive(90) && specRelicStacks > 0) {
        if (specRelicStacks.isEven) { final s2 = min(specRelicStacks, 40); bonusShield += s2; extra += ' • ☀️ Věčný úsvit (štít)'; }
        else { final d2 = min(specRelicStacks, 40); dmg += d2; extra += ' • ☀️ Věčný úsvit (dmg)'; }
      }
      // Lv80 "Přenesené světlo" - viz guard v _generateNextEnemy() (specRelicStacks se u Dawn nikdy neresetuje).
    } else if (r.kind == SpecRelicKind.healerJudgementSymbol) {
      // ----- JUDGEMENT: Rozsudek debuff -> heal z útoku, burst "Vykoupení" každý 3. cast -----
      bool crit = relicEffectActive(20) && Random().nextDouble() < critChance;
      if (crit) dmg = (dmg * critDamageMultiplier).round();
      if (relicEffectActive(10)) dmg = (dmg * 1.10).round();
      enemyEffects.removeWhere((e) => e.name == 'Rozsudek');
      if (relicEffectActive(10)) _applyRelicArmorShred('Rozsudek', 0.10);
      enemyEffects.add(StatusEffect(name: 'Rozsudek', description: 'Útoky proti cíli léčí hráče${relicEffectActive(10) ? " • Armor cíle -10 %" : ""}', duration: 4, isBuff: false));
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '⚖️ Rozsudek');
      heal = (dmg * .12 * (crit ? 1.6 : 1.0)).round();
      bool healCrit = relicEffectActive(30) && Random().nextDouble() < critChance;
      if (healCrit) heal = (heal * 1.5).round();
      hp = min(maxHp, hp + heal);
      if (crit || healCrit) extra += ' • CRIT';
      if (relicEffectActive(40)) _dkBloodEnemyDmgReductionPct = max(_dkBloodEnemyDmgReductionPct, 0.12);
      if (relicEffectActive(60)) { final s = (heal * 0.3).round(); bonusShield += s; }
      if (relicEffectActive(70) && isBossTarget) dmg = (dmg * 1.20).round();
      specRelicStacks += 1;
      if (relicEffectActive(50) && specRelicStacks % 3 == 0) {
        final redemptionHeal = (maxHp * 0.15).round();
        hp = min(maxHp, hp + redemptionHeal);
        int redemptionDmg = (dmg * 0.5).round();
        if (relicEffectActive(90)) redemptionDmg = (redemptionDmg * 1.4).round();
        dmg += redemptionDmg;
        _pushFx(FxKind.explosionDamage, FxSide.enemy, value: redemptionDmg, burstKind: RelicBurstKind.lastJudgement);
        extra += ' • ⚖️ Vykoupení (+$redemptionHeal heal, +$redemptionDmg dmg)';
      }
      // Lv80 "Putující rozsudek" - viz guard v _generateNextEnemy().
    } else if (r.kind == SpecRelicKind.healerBattleSymbol) {
      // ----- BATTLE: Liturgie krok (útok+heal zároveň) - každý 5. krok silný buff -----
      dmg = (dmg * 1.15).round();
      heal = (dmg * 0.35).round();
      hp = min(maxHp, hp + heal);
      if (relicEffectActive(30)) mana = (mana + 10).clamp(0, maxMana);
      bool crit = Random().nextDouble() < critChance;
      if (crit) { dmg = (dmg * critDamageMultiplier).round(); if (relicEffectActive(70)) specRelicStacks += 1; extra += ' • CRIT'; }
      specRelicStacks += 1;
      _pushFx(FxKind.statusApplied, FxSide.hero, label: '📿 Liturgie x$specRelicStacks');
      if (relicEffectActive(40) && specRelicStacks % 3 == 0) { shield = (maxHp * 0.10).round(); bonusShield += shield; extra += ' • Ochranný verš'; }
      if (relicEffectActive(50) && specRelicStacks % 5 == 0) {
        heroEffects.removeWhere((e) => e.name == 'Svatá extáze');
        heroEffects.add(StatusEffect(name: 'Svatá extáze', description: '+15% Atk${relicEffectActive(60) ? " • +10% Crit" : ""}', duration: 3, isBuff: true, physAtkMod: 0.15, magAtkMod: 0.15, critMod: relicEffectActive(60) ? 0.10 : 0));
        extra += ' • 📿 Svatá extáze!';
        if (relicEffectActive(90)) {
          final apostleHeal = (maxHp * 0.12).round();
          final apostleDmg = (dmg * 0.4).round();
          hp = min(maxHp, hp + apostleHeal);
          dmg += apostleDmg;
          _pushFx(FxKind.explosionDamage, FxSide.enemy, value: apostleDmg, burstKind: RelicBurstKind.apostleZeal);
          extra += ' • 📿 Válečný apoštol (+$apostleHeal heal, +$apostleDmg dmg)';
        }
      }
      // Lv80 "Udržená modlitba" - relic cast nemá modelovaný stav "chyby" (vždy je to zároveň
      // útok i heal), takže je tahle podmínka strukturálně vždy splněná.
    }
    return _DkSigilResult(dmg, heal, shield, extra);
  }

  // ===== Mage Tome implementace (Fire/Frost/Arcane) =====
  // Fire Tome: specRelicStacks = Žár (Heat, max 5, resetuje se za nového nepřítele jako u DK/
  // Warrior). Frost Tome: specRelicStacks = Zamrznutí (max 3), stejný vzor jako DK Frost Sigil,
  // sdílí i enemyStunTurns hook z _resolveCombatRound(). Arcane Tome: specRelicStacks = perzistentní
  // počítadlo Ozvěn napříč souboji (jako Hunter Beast/Ghost).
  _DkSigilResult _castMageSigil(SpecRelicDef r, int dmg, {required double targetHpRatio, required bool isBossTarget}) {
    int heal = 0, shield = 0;
    String extra = '';
    if (r.kind == SpecRelicKind.mageFireTome) {
      // ----- FIRE: Burning DoT + Žár stacky -> Flashover při maximu -> Inferno explode na expiraci -----
      bool crit = Random().nextDouble() < critChance;
      if (crit) dmg = (dmg * critDamageMultiplier).round();
      final gain = (relicEffectActive(20) && crit) ? 2 : 1;
      specRelicStacks = min(5, specRelicStacks + gain);
      int burnDot = (dmg * (0.20 + currentSpecRelicLevel * .004)).round();
      _restoreRelicArmorShredIfMatches('Hoření');
      enemyEffects.removeWhere((e) => e.name == 'Hoření');
      if (relicEffectActive(30)) _applyRelicArmorShred('Hoření', 0.10);
      enemyEffects.add(StatusEffect(name: 'Hoření', description: 'Žár $specRelicStacks/5 • DoT $burnDot/kolo${relicEffectActive(30) ? " • Armor cíle -10 %" : ""}', duration: 3 + (relicEffectActive(70) ? 1 : 0), isBuff: false, dotDamage: burnDot));
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '🔥 Hoření x$specRelicStacks');
      if (crit) extra += ' • CRIT';
      if (relicEffectActive(40)) dmg = (dmg * (1 + specRelicStacks * 0.05)).round();
      if (specRelicStacks >= 5 && relicEffectActive(50)) {
        bool flashCrit = relicEffectActive(60) && Random().nextDouble() < critChance;
        int flashDmg = burnDot * 3;
        if (flashCrit) flashDmg = (flashDmg * critDamageMultiplier).round();
        dmg += flashDmg;
        specRelicStacks = 0;
        _pushFx(FxKind.explosionDamage, FxSide.enemy, value: flashDmg, burstKind: RelicBurstKind.flashover);
        extra += ' • 🔥 Flashover${flashCrit ? " CRIT" : ""} +$flashDmg';
      }
      // Lv80 "Šíření požáru" - viz guard v _generateNextEnemy(). Lv90 "Inferno" - viz hook v _tickEffects().
    } else if (r.kind == SpecRelicKind.mageFrostTome) {
      // ----- FROST: Chlad debuff + Ice Ward -> 3 stacky Zamrznutí spustí Shatter -----
      final wardBase = (totalWisdom * 0.04 + totalVitality * 0.03 + maxHp * 0.08).round();
      shield = wardBase;
      bonusShield += shield;
      final bool alreadyChilled = enemyEffects.any((e) => e.name == 'Chlad');
      enemyEffects.removeWhere((e) => e.name == 'Chlad');
      enemyEffects.add(StatusEffect(name: 'Chlad', description: 'Zamrznutí $specRelicStacks/3', duration: 3 + (relicEffectActive(70) ? 1 : 0), isBuff: false));
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '❄️ Chlad');
      if (relicEffectActive(10)) _dkBloodEnemyDmgReductionPct = max(_dkBloodEnemyDmgReductionPct, 0.12);
      bool crit = relicEffectActive(30) && alreadyChilled && Random().nextDouble() < critChance;
      if (crit) { dmg = (dmg * critDamageMultiplier).round(); extra += ' • CRIT'; }
      if (relicEffectActive(40) && crit) specRelicStacks = min(3, specRelicStacks + 1); else if (relicEffectActive(40)) specRelicStacks = min(3, specRelicStacks + (Random().nextDouble() < 0.4 ? 1 : 0));
      if (specRelicStacks >= 3 && relicEffectActive(50)) {
        int shatterDmg = (dmg * 1.1).round();
        dmg += shatterDmg;
        specRelicStacks = 0;
        _pushFx(FxKind.explosionDamage, FxSide.enemy, value: shatterDmg, burstKind: RelicBurstKind.absoluteZero);
        extra += ' • ❄️ Shatter +$shatterDmg';
        if (relicEffectActive(60)) { final restored = (wardBase * 0.4).round(); bonusShield += restored; }
        if (relicEffectActive(90)) {
          if (!isBossTarget) { enemyStunTurns += 1; _pushFx(FxKind.stunned, FxSide.enemy, label: '🥶 Absolutní nula!'); extra += ' • Freeze!'; }
          else { dmg = (dmg * 1.15).round(); extra += ' • boss bonus dmg'; }
        }
      }
      // Lv80 "Putující mráz" - viz guard v _generateNextEnemy().
    } else if (r.kind == SpecRelicKind.mageArcaneTome) {
      // ----- ARCANE: Ozvěna (echo hit) - perzistentní počítadlo řídí "každou třetí" Časový zlom -----
      bool crit = Random().nextDouble() < critChance;
      if (crit) dmg = (dmg * critDamageMultiplier).round();
      int echoDmg = (dmg * 0.5).round();
      if (relicEffectActive(70)) echoDmg = (echoDmg * 1.15).round();
      bool echoCrit = relicEffectActive(20) && Random().nextDouble() < critChance;
      if (echoCrit) echoDmg = (echoDmg * critDamageMultiplier).round();
      dmg += echoDmg;
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '🔮 Ozvěna');
      if (crit || echoCrit) extra += ' • CRIT';
      if (relicEffectActive(10)) mana = (mana + 8).clamp(0, maxMana);
      if (relicEffectActive(40)) {
        final buffs = heroEffects.where((e) => e.isBuff).toList();
        for (final b in buffs) { b.duration += 1; }
        if (buffs.isNotEmpty) extra += ' • Prodloužený okamžik';
      }
      specRelicStacks += 1;
      if (relicEffectActive(50) && specRelicStacks % 3 == 0) {
        int timeBreakDmg = (dmg * 0.6).round();
        dmg += timeBreakDmg;
        if (relicEffectActive(60)) mana = (mana + 20).clamp(0, maxMana);
        extra += ' • 🔮 Časový zlom +$timeBreakDmg';
        if (relicEffectActive(90)) {
          final paradoxDmg = (dmg * 0.4).round();
          dmg += paradoxDmg;
          _pushFx(FxKind.explosionDamage, FxSide.enemy, value: paradoxDmg, burstKind: RelicBurstKind.paradoxEcho);
          extra += ' • Paradox +$paradoxDmg';
        } else {
          _pushFx(FxKind.explosionDamage, FxSide.enemy, value: timeBreakDmg, burstKind: RelicBurstKind.paradoxEcho);
        }
      }
      // Lv80 "Uložený okamžik" - specRelicStacks se u Arcane nikdy neresetuje (viz guard v _generateNextEnemy()).
    }
    return _DkSigilResult(dmg, heal, shield, extra);
  }

  // ===== Monk Mala implementace (Storm/Stone/Harmony) =====
  // Storm: specRelicStacks = Combo (max 5, resetuje se za nového nepřítele). Stone: shield-based,
  // hlavní kus (Lv90 "Nehybný svět") sdílí stejný cheat-death hook v _applyIncomingDamage() jako
  // Warrior Guardian Banner (_guardianCheatDeathUsed - jen jeden relic je aktivní najednou, takže
  // sdílení proměnné je bezpečné). Harmony: perzistentní počítadlo jako Healer Battle Symbol -
  // každý cast je zároveň Yin i Yang (jinak by "správné střídání" vyžadovalo hák do celé rotace).
  _DkSigilResult _castMonkSigil(SpecRelicDef r, int dmg, {required double targetHpRatio, required bool isBossTarget}) {
    int heal = 0, shield = 0;
    String extra = '';
    if (r.kind == SpecRelicKind.monkStormMala) {
      // ----- STORM: Combo stacky -> Tisíc úderů při maximu -> exploze podle critů -----
      bool crit = Random().nextDouble() < critChance;
      if (crit) dmg = (dmg * critDamageMultiplier).round();
      final gain = (relicEffectActive(20) && crit) ? 2 : 1;
      specRelicStacks = min(5, specRelicStacks + gain);
      energy = (energy + (relicEffectActive(10) ? 14 : 8)).clamp(0, maxEnergy);
      heroEffects.removeWhere((e) => e.name == 'Combo');
      heroEffects.add(StatusEffect(name: 'Combo', description: 'Stack $specRelicStacks/5', duration: 3, isBuff: true));
      _pushFx(FxKind.statusApplied, FxSide.hero, label: '👊 Combo x$specRelicStacks');
      if (crit) extra += ' • CRIT';
      if (relicEffectActive(40)) dmg = (dmg * (1 + specRelicStacks * 0.05)).round();
      if (specRelicStacks >= 5 && relicEffectActive(50)) {
        int flurryDmg = 0, crits = 0;
        final hitBase = (dmg * 0.28).round();
        for (int i = 0; i < 5; i++) {
          int hit = hitBase;
          if (relicEffectActive(60) && Random().nextDouble() < critChance) { hit = (hit * critDamageMultiplier).round(); crits++; }
          flurryDmg += hit;
        }
        if (relicEffectActive(70)) {
          _restoreRelicArmorShredIfMatches('Lámající dlaň');
          enemyEffects.removeWhere((e) => e.name == 'Lámající dlaň');
          _applyRelicArmorShred('Lámající dlaň', 0.12);
          enemyEffects.add(StatusEffect(name: 'Lámající dlaň', description: 'Armor cíle -12 %', duration: 3, isBuff: false));
          extra += ' • Lámající dlaň';
        }
        dmg += flurryDmg;
        specRelicStacks = 0;
        _pushFx(FxKind.explosionDamage, FxSide.enemy, value: flurryDmg, burstKind: RelicBurstKind.thousandStrikes);
        extra += ' • 👊 Tisíc úderů +$flurryDmg ($crits crit)';
        if (relicEffectActive(90) && crits > 0) {
          final finale = (flurryDmg * 0.25 * crits).round();
          dmg += finale;
          extra += ' • finále +$finale';
        }
      }
      // Lv80 "Nesené kombo" - viz guard v _generateNextEnemy().
    } else if (r.kind == SpecRelicKind.monkStoneMala) {
      // ----- STONE: Kamenný štít + Pevnost stacky -> Úder hory při maximu -> Nehybný svět cheat death -----
      shield = (armor * .35 + maxHp * .12 + currentSpecRelicLevel * level).round();
      if (relicEffectActive(10)) shield += (totalVitality * 0.08).round();
      bonusShield += shield;
      dmg = (dmg * .55).round();
      _pushFx(FxKind.shieldGained, FxSide.hero, value: shield);
      if (relicEffectActive(20)) {
        heroEffects.removeWhere((e) => e.name == 'Pevný postoj');
        heroEffects.add(StatusEffect(name: 'Pevný postoj', description: '+8% Block', duration: 3, isBuff: true, blockMod: 0.08));
      }
      if (relicEffectActive(40) && specRelicStacks > 0) {
        heroEffects.removeWhere((e) => e.name == 'Pevnost');
        heroEffects.add(StatusEffect(name: 'Pevnost', description: '+${specRelicStacks * 2}% Armor', duration: 4, isBuff: true, armorMod: specRelicStacks * 0.02));
      }
      if (specRelicStacks >= 5 && relicEffectActive(50)) {
        final mountainDmg = (armor * (relicEffectActive(80) ? 1.3 : 0.9)).round();
        dmg += mountainDmg;
        specRelicStacks = max(0, specRelicStacks - 3); // Lv60 "Tvrdé jádro": nespotřebuje se úplně vše
        _pushFx(FxKind.explosionDamage, FxSide.enemy, value: mountainDmg, burstKind: RelicBurstKind.mountainStrike);
        extra += ' • 🗻 Úder hory +$mountainDmg';
        if (relicEffectActive(80)) { _dkBloodEnemyDmgReductionPct = max(_dkBloodEnemyDmgReductionPct, 0.15); extra += ' • Drtivá tíha'; }
      }
      // Lv30 "Pevnost stack z bloku" a Lv90 "Nehybný svět" - viz hooky v _applyIncomingDamage().
      // Lv70 "Pochod hory" - bonusShield se ve Věži nikdy neresetuje samo (jen ho spotřebuje
      // dopadající dmg), takže se přenáší přirozeně i bez extra kódu.
    } else if (r.kind == SpecRelicKind.monkHarmonyMala) {
      // ----- HARMONY: Yin (heal/štít) + Yang (dmg/energy) zároveň - perzistentní počítadlo -----
      final yinShield = (relicEffectActive(10) ? 1.4 : 1.0);
      final yangDmg = (relicEffectActive(20) ? 1.25 : 1.0);
      final int hpBeforeHeal = hp;
      heal = (maxHp * 0.12).round();
      hp = min(maxHp, hp + heal);
      final int overheal = heal - (hp - hpBeforeHeal);
      shield = (heal * 0.5 * yinShield).round();
      bonusShield += shield;
      dmg = (dmg * yangDmg).round();
      energy = (energy + 10).clamp(0, maxEnergy);
      specRelicStacks += 1;
      _pushFx(FxKind.statusApplied, FxSide.hero, label: '☯️ Harmonie x$specRelicStacks');
      if (relicEffectActive(40)) { final bonus = (specRelicStacks * 0.02).clamp(0.0, 0.30); dmg = (dmg * (1 + bonus)).round(); heal = (heal * (1 + bonus)).round(); }
      if (relicEffectActive(70) && overheal > 0) { dmg += (overheal * 0.5).round(); extra += ' • Přeměna energie'; }
      if (relicEffectActive(50) && specRelicStacks % 5 == 0) {
        heroEffects.removeWhere((e) => e.name == 'Probuzení ducha');
        heroEffects.add(StatusEffect(name: 'Probuzení ducha', description: '+15% Atk • +15% healing', duration: 3, isBuff: true, physAtkMod: 0.15, magAtkMod: 0.15));
        extra += ' • ☯️ Probuzení ducha!';
        if (relicEffectActive(60)) { heroEffects.removeWhere((e) => !e.isBuff); extra += ' • Očistný nádech'; }
        if (relicEffectActive(90)) {
          final bonusHeal = (maxHp * 0.10).round();
          final bonusDmg = (dmg * 0.35).round();
          hp = min(maxHp, hp + bonusHeal);
          dmg += bonusDmg;
          _pushFx(FxKind.explosionDamage, FxSide.enemy, value: bonusDmg, burstKind: RelicBurstKind.perfectBalance);
          extra += ' • ☯️ Dokonalá rovnováha (+$bonusHeal heal, +$bonusDmg dmg)';
        }
      }
      // Lv80 "Nesený klid" - specRelicStacks se u Harmony nikdy neresetuje (viz guard v _generateNextEnemy()).
    }
    return _DkSigilResult(dmg, heal, shield, extra);
  }

  // ===== Druid Totem implementace (Balance/Wild/Resto) =====
  // Wild Totem je strukturálně stejný relic jako Warrior Guardian Banner / Monk Stone Mala
  // (štít + block counter + shield-break exploze + Lv90 cheat death) - sdílí stejné hooky
  // v _applyIncomingDamage() a stejnou _guardianCheatDeathUsed proměnnou (jen jeden relic je
  // aktivní najednou). Balance Totem sdílí Lv90 exploze-na-expiraci vzor z _tickEffects() jako
  // DK Plague/Mage Fire. Resto Totem nemá perzistentní počítadlo - je to čistě per-cast heal/shield.
  _DkSigilResult _castDruidSigil(SpecRelicDef r, int dmg, {required double targetHpRatio, required bool isBossTarget}) {
    int heal = 0, shield = 0;
    String extra = '';
    if (r.kind == SpecRelicKind.druidBalanceTotem) {
      // ----- BALANCE: Astrální rozklad DoT -> magAtk buff dokud běží -> Hvězdný pád na expiraci -----
      int dot = (dmg * (0.24 + currentSpecRelicLevel * .0045)).round();
      if (relicEffectActive(30)) dmg = (dmg * 1.10).round();
      bool crit = Random().nextDouble() < critChance;
      int instantTick = 0;
      if (crit) { dmg = (dmg * critDamageMultiplier).round(); if (relicEffectActive(60)) { instantTick = dot; dmg += instantTick; } extra += ' • CRIT'; }
      final dur = 3 + (relicEffectActive(70) ? 1 : 0) + (relicEffectActive(20) && Random().nextDouble() < 0.35 ? 1 : 0);
      enemyEffects.removeWhere((e) => e.name == 'Astrální rozklad');
      if (relicEffectActive(40)) _applyRelicArmorShred('Astrální rozklad', 0.12);
      enemyEffects.add(StatusEffect(name: 'Astrální rozklad', description: 'DoT $dot/kolo${relicEffectActive(40) ? " • Armor cíle -12 %" : ""}', duration: dur, isBuff: false, dotDamage: dot));
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '🌌 Astrální rozklad');
      if (instantTick > 0) extra += ' • okamžitý tick +$instantTick';
      if (relicEffectActive(50)) {
        heroEffects.removeWhere((e) => e.name == 'Astrální příliv');
        heroEffects.add(StatusEffect(name: 'Astrální příliv', description: '+12% magický útok', duration: dur, isBuff: true, magAtkMod: 0.12));
      }
      // Lv80 "Kořeny Věže" - viz guard v _generateNextEnemy(). Lv90 "Hvězdný pád" - viz hook v _tickEffects().
    } else if (r.kind == SpecRelicKind.druidWildTotem) {
      // ----- WILD: štít z Armor+Vitality + block counter (viz _applyIncomingDamage) -----
      shield = (armor * .35 + maxHp * .12 + currentSpecRelicLevel * level).round();
      if (relicEffectActive(10)) shield += (totalVitality * 0.10).round();
      bonusShield += shield;
      dmg = (dmg * .55).round();
      _pushFx(FxKind.shieldGained, FxSide.hero, value: shield);
      if (relicEffectActive(20)) {
        heroEffects.removeWhere((e) => e.name == 'Pevný kmen');
        heroEffects.add(StatusEffect(name: 'Pevný kmen', description: '+8% Block', duration: 3, isBuff: true, blockMod: 0.08));
      }
      if (relicEffectActive(70)) { _dkBloodEnemyDmgReductionPct = max(_dkBloodEnemyDmgReductionPct, 0.12); extra += ' • Umlčující réva'; }
      // Lv30/40/50/60/90 - viz hooky v _applyIncomingDamage(). Lv80 "Pochod lesa" - bonusShield se
      // ve Věži nikdy neresetuje samo (jen ho spotřebuje dopadající dmg), přenáší se přirozeně.
    } else if (r.kind == SpecRelicKind.druidRestoTotem) {
      // ----- RESTO: heal + shield z healu, bez perzistentního počítadla (čistě per-cast) -----
      final missingHp = maxHp - hp;
      heal = (maxHp * (.20 + currentSpecRelicLevel * .0015) + (relicEffectActive(40) ? missingHp * 0.10 : 0)).round();
      final bool lowHp = maxHp > 0 && hp / maxHp < 0.30;
      if (relicEffectActive(90) && lowHp) heal = (heal * 2).round();
      final int hpBeforeHeal = hp;
      hp = min(maxHp, hp + heal);
      final int overheal = heal - (hp - hpBeforeHeal);
      dmg = (dmg * .45).round();
      final shieldMult = relicEffectActive(20) ? 0.55 : 0.35;
      shield = (heal * shieldMult).round();
      bonusShield += shield;
      _pushFx(FxKind.shieldGained, FxSide.hero, value: shield, burstKind: (relicEffectActive(90) && lowHp) ? RelicBurstKind.natureHeart : null);
      if (relicEffectActive(90) && lowHp) extra += ' • 💚 Srdce přírody (2×)!';
      if (relicEffectActive(30)) {
        heroEffects.removeWhere((e) => e.name == 'Proudící síla');
        heroEffects.add(StatusEffect(name: 'Proudící síla', description: '+10% magický útok', duration: 2, isBuff: true, magAtkMod: 0.10));
      }
      if (relicEffectActive(50) && heal > (maxHp * 0.25)) {
        final removed = heroEffects.where((e) => !e.isBuff).isNotEmpty;
        heroEffects.removeWhere((e) => !e.isBuff);
        if (removed) extra += ' • Rozkvět';
      }
      if (relicEffectActive(70) && overheal > 0) { final extraShield = (overheal * 0.6).round(); bonusShield += extraShield; extra += ' • Obnovující vlna +$extraShield'; }
      // Lv60 "Symbióza" (štít o kolo déle) a Lv80 "Nesený pramen" (bonusShield se ve Věži
      // nikdy neresetuje samo) jsou přirozeně splněné existující mechanikou štítu.
    }
    return _DkSigilResult(dmg, heal, shield, extra);
  }

  // ===== Necromancer Tome implementace (Bone/Plague/Blood) =====
  // Bone Tome je stejný vzor jako Hunter Beast Quiver (společný útok se "sluhou" místo
  // companiona). Plague Tome je stejný vzor jako Druid Balance Totem / DK Plague (DoT + magAtk
  // buff + exploze na expiraci). Blood Tome je nový flavor - čisté lifesteal z způsobeného dmg,
  // na rozdíl od DK Blood Sigil (který je heal-first s vlastním DoT).
  _DkSigilResult _castNecromancerSigil(SpecRelicDef r, int dmg, {required double targetHpRatio, required bool isBossTarget}) {
    int heal = 0, shield = 0;
    String extra = '';
    if (r.kind == SpecRelicKind.necromancerBoneTome) {
      // ----- BONE: společný útok s kostěným sluhou, perzistentní počítadlo -> horečka každý 3. -----
      dmg = (dmg * 1.35).round();
      specRelicStacks += 1; // persistentní počítadlo (napříč souboji), řídí "každý třetí" proc
      enemyEffects.removeWhere((e) => e.name == 'Znamení smrti');
      if (relicEffectActive(10)) enemyEffects.add(StatusEffect(name: 'Znamení smrti', description: 'Útoky proti cíli léčí', duration: 4, isBuff: false));
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '💀 Rozkaz sluhovi');
      bool crit = Random().nextDouble() < critChance;
      if (crit) { dmg = (dmg * critDamageMultiplier).round(); extra += ' • CRIT'; }
      if (relicEffectActive(20)) { heal = (dmg * 0.20).round(); hp = min(maxHp, hp + heal); }
      if (relicEffectActive(40)) dmg = (dmg * 1.10).round();
      if (relicEffectActive(50) && specRelicStacks % 3 == 0) {
        heroEffects.removeWhere((e) => e.name == 'Nekromantická horečka');
        heroEffects.add(StatusEffect(name: 'Nekromantická horečka', description: '+15% Atk${relicEffectActive(60) ? " • +10% Crit" : ""} na 2 kola', duration: 2, isBuff: true, physAtkMod: 0.15, magAtkMod: 0.15, critMod: relicEffectActive(60) ? 0.10 : 0));
        extra += ' • 💀 Horečka!';
      }
      if (relicEffectActive(90)) {
        dmg = (dmg * (isBossTarget ? 1.22 : 1.12)).round();
        extra += ' • 💀 Vládce Kostí';
        _pushFx(FxKind.explosionDamage, FxSide.enemy, value: dmg, burstKind: RelicBurstKind.boneLord);
      }
      // Lv80 "Hostina duší" (heal na zabití) - viz hook v _handleEnemyDeath().
    } else if (r.kind == SpecRelicKind.necromancerPlagueTome) {
      // ----- PLAGUE: Morová kletba DoT -> magAtk buff dokud běží -> Morový pád na expiraci -----
      int dot = (dmg * (0.24 + currentSpecRelicLevel * .0045)).round();
      if (relicEffectActive(30)) dmg = (dmg * 1.10).round();
      bool crit = Random().nextDouble() < critChance;
      int instantTick = 0;
      if (crit) { dmg = (dmg * critDamageMultiplier).round(); if (relicEffectActive(60)) { instantTick = dot; dmg += instantTick; } extra += ' • CRIT'; }
      final dur = 3 + (relicEffectActive(70) ? 1 : 0) + (relicEffectActive(20) && Random().nextDouble() < 0.35 ? 1 : 0);
      enemyEffects.removeWhere((e) => e.name == 'Morová kletba');
      if (relicEffectActive(40)) _applyRelicArmorShred('Morová kletba', 0.12);
      enemyEffects.add(StatusEffect(name: 'Morová kletba', description: 'DoT $dot/kolo${relicEffectActive(40) ? " • Armor cíle -12 %" : ""}', duration: dur, isBuff: false, dotDamage: dot));
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '☣️ Morová kletba');
      if (instantTick > 0) extra += ' • okamžitý tick +$instantTick';
      if (relicEffectActive(50)) {
        heroEffects.removeWhere((e) => e.name == 'Kletebný příliv');
        heroEffects.add(StatusEffect(name: 'Kletebný příliv', description: '+12% magický útok', duration: dur, isBuff: true, magAtkMod: 0.12));
      }
      // Lv80 "Kletba Věže" - viz guard v _generateNextEnemy(). Lv90 "Morový pád" - viz hook v _tickEffects().
    } else if (r.kind == SpecRelicKind.necromancerBloodTome) {
      // ----- BLOOD: čisté lifesteal z způsobeného poškození (jiný flavor než DK Blood Sigil) -----
      bool crit = Random().nextDouble() < critChance;
      if (crit) dmg = (dmg * critDamageMultiplier).round();
      double lifestealPct = 0.25 + currentSpecRelicLevel * .003;
      heal = (dmg * lifestealPct).round();
      final bool lowHp = maxHp > 0 && hp / maxHp < 0.30;
      if (relicEffectActive(90) && lowHp) heal = (heal * 2).round();
      hp = min(maxHp, hp + heal);
      _pushFx(FxKind.statusApplied, FxSide.hero, label: '🩸 Krvavý pakt', burstKind: (relicEffectActive(90) && lowHp) ? RelicBurstKind.immortalRitual : null);
      if (crit) extra += ' • CRIT';
      if (relicEffectActive(90) && lowHp) extra += ' • 🩸 Nesmrtelný Rituál (2×)!';
      if (relicEffectActive(30)) mana = (mana + (heal * 0.15).round()).clamp(0, maxMana);
      if (relicEffectActive(50)) {
        final shieldMult = relicEffectActive(60) ? 0.35 : 0.20;
        shield = (heal * shieldMult).round();
        bonusShield += shield;
      }
      if (relicEffectActive(70) && bonusShield > 0) {
        heroEffects.removeWhere((e) => e.name == 'Nekrotická odolnost');
        heroEffects.add(StatusEffect(name: 'Nekrotická odolnost', description: '-10% obdrženého poškození', duration: 3, isBuff: true, armorMod: 0.10));
      }
      // Lv80 "Nesená krev" - bonusShield/heroEffects buffy se ve Věži nikdy neresetují samy
      // (jen je spotřebuje čas/dopadající dmg), takže se přenáší přirozeně i bez extra kódu.
    }
    return _DkSigilResult(dmg, heal, shield, extra);
  }

  // ===== Duelist Crest implementace (Nemesis/Dance/Lightning) =====
  // Nemesis Crest sdílí strukturu s Hunter Marksman/DK Frost (stacky -> finisher). Dance Crest
  // je jako Hunter Ghost Quiver - cast aktivuje "Ve tanci" a skutečná Riposte běží z
  // _duelistDanceCounter(), volaného z dodge-bloku v _resolveCombatRound() VEDLE existující
  // vrozené Duelist Grácie (hasGraceCounter), kterou má spec 2 už bez relicu. Lightning Crest je
  // dvouúderový spell + Hybnost stacky -> Bleskovou smršť.
  _DkSigilResult _castDuelistSigil(SpecRelicDef r, int dmg, {required double targetHpRatio, required bool isBossTarget}) {
    int heal = 0, shield = 0;
    String extra = '';
    if (r.kind == SpecRelicKind.duelistNemesisCrest) {
      // ----- NEMESIS: Odplata stacky -> Rozsudek Nemesis finisher -> execute/garantovaný crit -----
      bool crit = (relicEffectActive(90) && targetHpRatio < 0.20) || Random().nextDouble() < critChance;
      if (crit) dmg = (dmg * (relicEffectActive(30) ? critDamageMultiplier * 1.1 : critDamageMultiplier)).round();
      final gain = 1 + (relicEffectActive(10) ? 1 : 0) + (relicEffectActive(30) && crit ? 1 : 0);
      specRelicStacks = min(5, specRelicStacks + gain);
      _restoreRelicArmorShredIfMatches('Označení pomsty');
      enemyEffects.removeWhere((e) => e.name == 'Označení pomsty');
      if (relicEffectActive(20)) _applyRelicArmorShred('Označení pomsty', 0.10);
      enemyEffects.add(StatusEffect(name: 'Označení pomsty', description: 'Odplata $specRelicStacks/5${relicEffectActive(20) ? " • Armor cíle -10 %" : ""}', duration: 3, isBuff: false));
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '🎯 Označení pomsty x$specRelicStacks');
      if (crit) extra += ' • CRIT';
      if (relicEffectActive(40)) dmg = (dmg * (1 + (1 - targetHpRatio) * 0.4)).round();
      if (specRelicStacks >= 5 && relicEffectActive(50)) {
        int judgementDmg = (dmg * 1.1).round();
        if (relicEffectActive(60) && targetHpRatio < 0.30) judgementDmg = (judgementDmg * 1.35).round();
        dmg += judgementDmg;
        specRelicStacks = 0;
        _pushFx(FxKind.explosionDamage, FxSide.enemy, value: judgementDmg, burstKind: RelicBurstKind.nemesisJudgement);
        extra += ' • ⚖️ Rozsudek Nemesis +$judgementDmg';
      }
      // Lv70 "Vrácená síla" - viz hook v _handleEnemyDeath(). Lv80 "Další viník" - viz guard v _generateNextEnemy().
    } else if (r.kind == SpecRelicKind.duelistDanceCrest) {
      // ----- DANCE: cast aktivuje "Ve tanci" - skutečná Riposte běží z _duelistDanceCounter() -----
      heroEffects.removeWhere((e) => e.name == 'Ve tanci');
      heroEffects.add(StatusEffect(name: 'Ve tanci', description: 'Dodge vyvolá zesílenou Riposte', duration: 3, isBuff: true, dodgeMod: relicEffectActive(10) ? 0.08 : 0.05));
      _pushFx(FxKind.statusApplied, FxSide.hero, label: '💃 Ve tanci');
      dmg = (dmg * 1.10).round();
      extra += ' • 💃 Ve tanci aktivní';
      _duelistDanceFirstProcUsed = false; // Lv90 "Dokonalý duel" - první dodge v tomhle okně bude zesílená
    } else if (r.kind == SpecRelicKind.duelistLightningCrest) {
      // ----- LIGHTNING: dva rychlé zásahy + Hybnost stacky -> Bleskovou smršť -----
      bool crit1 = Random().nextDouble() < critChance;
      int hit1 = (dmg * 0.55).round();
      if (crit1) hit1 = (hit1 * critDamageMultiplier).round();
      bool crit2 = Random().nextDouble() < (relicEffectActive(10) ? critChance + 0.15 : critChance);
      int hit2 = (dmg * 0.55).round();
      if (crit2) hit2 = (hit2 * critDamageMultiplier).round();
      dmg = hit1 + hit2;
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '⚡ Blesková sekvence');
      if (crit1 || crit2) extra += ' • CRIT';
      specRelicStacks += 1; // Hybnost - persistentní počítadlo napříč souboji
      if (relicEffectActive(30)) dmg = (dmg * (1 + specRelicStacks * 0.03).clamp(1.0, 1.45)).round();
      if (specRelicStacks % 5 == 0 && relicEffectActive(50)) {
        int burstDmg = 0, crits = 0;
        final hitBase = (dmg * 0.22).round();
        for (int i = 0; i < 4; i++) {
          int hit = hitBase;
          if (relicEffectActive(70) && Random().nextDouble() < critChance) { hit = (hit * critDamageMultiplier).round(); crits++; }
          burstDmg += hit;
        }
        dmg += burstDmg;
        _pushFx(FxKind.explosionDamage, FxSide.enemy, value: burstDmg, burstKind: RelicBurstKind.lightningStorm);
        extra += ' • ⚡ Blesková smršť +$burstDmg ($crits crit)';
        if (relicEffectActive(60)) energy = (energy + 20).clamp(0, maxEnergy);
      }
      // Lv80 "Nesená rychlost" - specRelicStacks se u Lightning nikdy neresetuje (viz guard v _generateNextEnemy()).
    }
    return _DkSigilResult(dmg, heal, shield, extra);
  }

  bool _duelistDanceFirstProcUsed = false; // Dance Crest Lv90 "Dokonalý duel" - viz _castDuelistSigil/_duelistDanceCounter.

  // Duelist Dance Crest: úspěšný úhyb (dokud běží "Ve tanci") vyvolá Riposte navíc k vrozené
  // Duelist Grácie. Tempo (specRelicStacks) při maximu spustí Tanec ostří. Volá se z dodge-bloku
  // v _resolveCombatRound(), funguje jen ve Věži (míří přímo na currentEnemyHp).
  void _duelistDanceCounter() {
    final bool firstProc = !_duelistDanceFirstProcUsed;
    _duelistDanceFirstProcUsed = true;
    final bool empowered = relicEffectActive(90) && firstProc;
    int counterDmg = (physAtk * (0.40 + currentSpecRelicLevel * .003) * (empowered ? 1.6 : 1.0)).round();
    bool counterCrit = Random().nextDouble() < critChance;
    if (counterCrit) counterDmg = (counterDmg * critDamageMultiplier).round();
    currentEnemyHp -= counterDmg;
    String extra = ' 💃 Riposte: $counterDmg dmg${empowered ? " (zesíleno)" : ""}${counterCrit ? " CRIT" : ""}!';
    _pushFx(FxKind.normalDamage, FxSide.enemy, value: counterDmg);
    if (relicEffectActive(30)) { final h = (counterDmg * 0.20).round(); hp = min(maxHp, hp + h); }
    specRelicStacks += 1;
    if (relicEffectActive(50) && specRelicStacks % 5 == 0) {
      int danceDmg = 0;
      final hitBase = (counterDmg * 0.35).round();
      for (int i = 0; i < 3; i++) danceDmg += hitBase;
      currentEnemyHp -= danceDmg;
      _pushFx(FxKind.explosionDamage, FxSide.enemy, value: danceDmg, burstKind: RelicBurstKind.bladeDance);
      if (relicEffectActive(60)) {
        heroEffects.removeWhere((e) => e.name == 'Tanec ostří');
        heroEffects.add(StatusEffect(name: 'Tanec ostří', description: '+15% Crit Chance', duration: 2, isBuff: true, critMod: 0.15));
      }
      extra += ' • 💃 Tanec ostří +$danceDmg';
    }
    message += extra;
    if (currentEnemyHp <= 0) _handleEnemyDeath();
  }

  // ===== Paladin Seal implementace (Guardian/Judgement/Dawn) =====
  // Guardian Seal je čtvrtý relic sdílející obrannou trojici hooků v _applyIncomingDamage()
  // (Warrior Guardian Banner / Monk Stone Mala / Druid Wild Totem). Judgement Seal navazuje na
  // Healer Judgement Symbol (sdílí i "Rozsudek" carry-guard). Dawn Seal je stejný vzor jako
  // Druid Resto Totem (heal/shield bez perzistentního počítadla).
  _DkSigilResult _castPaladinSigil(SpecRelicDef r, int dmg, {required double targetHpRatio, required bool isBossTarget}) {
    int heal = 0, shield = 0;
    String extra = '';
    if (r.kind == SpecRelicKind.paladinGuardianSeal) {
      // ----- GUARDIAN: posvátný štít z Armor+Vitality -> block counter/shield-break/cheat death (viz _applyIncomingDamage) -----
      shield = (armor * .35 + maxHp * .12 + currentSpecRelicLevel * level).round();
      if (relicEffectActive(10)) shield += (totalVitality * 0.08).round();
      bonusShield += shield;
      dmg = (dmg * .55).round();
      _pushFx(FxKind.shieldGained, FxSide.hero, value: shield);
      if (relicEffectActive(20)) {
        heroEffects.removeWhere((e) => e.name == 'Pevný postoj (Pečeť)');
        heroEffects.add(StatusEffect(name: 'Pevný postoj (Pečeť)', description: '+8% Block', duration: 3, isBuff: true, blockMod: 0.08));
      }
      if (relicEffectActive(70)) { _dkBloodEnemyDmgReductionPct = max(_dkBloodEnemyDmgReductionPct, 0.12); extra += ' • Umlčující světlo'; }
      // Lv30/40/50/60/90 - viz hooky v _applyIncomingDamage(). Lv80 "Pochod víry" - bonusShield se
      // ve Věži nikdy neresetuje samo, přenáší se přirozeně.
    } else if (r.kind == SpecRelicKind.paladinJudgementSeal) {
      // ----- JUDGEMENT: Boží rozsudek - útoky proti cíli léčí, DoT navíc, silný proti bossům -----
      bool crit = relicEffectActive(20) && Random().nextDouble() < critChance;
      if (crit) dmg = (dmg * critDamageMultiplier).round();
      final dur = 4 + (relicEffectActive(10) ? 1 : 0);
      final judgeDot = relicEffectActive(30) ? (dmg * 0.10).round() : 0;
      enemyEffects.removeWhere((e) => e.name == 'Rozsudek');
      _applyRelicArmorShred('Rozsudek', 0.10); // Lv1 base spell vždy oslabuje Armor (viz popis relicu)
      enemyEffects.add(StatusEffect(name: 'Rozsudek', description: 'Útoky proti cíli léčí hráče • Armor cíle -10 %${judgeDot > 0 ? " • DoT $judgeDot/kolo" : ""}', duration: dur, isBuff: false, dotDamage: judgeDot));
      specRelicStacks = 1; // "přítomnostní" flag pro Lv80 carry-guard v _generateNextEnemy() - Rozsudek nemá proměnlivé stacky
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '⚖️ Boží rozsudek');
      heal = (dmg * (relicEffectActive(40) ? 0.18 : 0.12) * (crit ? 1.6 : 1.0)).round();
      hp = min(maxHp, hp + heal);
      if (crit) extra += ' • CRIT';
      if (relicEffectActive(60)) activeAbilityCooldown = max(0, activeAbilityCooldown - 1);
      if (relicEffectActive(70) && crit) dmg = (dmg * 1.10).round(); // "oslepení" folded jako bonus dmg téhle rány
      if (relicEffectActive(90)) { specRelicUsedTower = false; specRelicUsedArena = false; extra += ' • Poslední soud'; } // "plně obnoví cooldown" - relic nemá číselný cooldown, zjednodušeno na okamžitou opětovnou dostupnost
      if (isBossTarget) { dmg = (dmg * 1.15).round(); extra += ' • boss bonus'; }
      // Lv50 "Nezvratný verdikt" - relic systém nemá modelovaný "interrupt" stav, takže je tahle
      // podmínka strukturálně vždy splněná. Lv80 "Věčný verdikt" - viz sdílený guard v _generateNextEnemy().
    } else if (r.kind == SpecRelicKind.paladinDawnSeal) {
      // ----- DAWN: heal + shield, bez perzistentního počítadla (čistě per-cast, jako Resto Totem) -----
      final missingHp = maxHp - hp;
      heal = (maxHp * (.20 + currentSpecRelicLevel * .0015) + (relicEffectActive(40) ? missingHp * 0.10 : 0)).round();
      final bool lowHp = maxHp > 0 && hp / maxHp < 0.30;
      if (relicEffectActive(90) && lowHp) heal = (heal * 2).round();
      final int hpBeforeHeal = hp;
      hp = min(maxHp, hp + heal);
      final int overheal = heal - (hp - hpBeforeHeal);
      dmg = (dmg * .45).round();
      final shieldMult = relicEffectActive(20) ? 0.55 : 0.35;
      shield = (heal * shieldMult).round();
      bonusShield += shield;
      _pushFx(FxKind.shieldGained, FxSide.hero, value: shield, burstKind: (relicEffectActive(90) && lowHp) ? RelicBurstKind.divineGrace : null);
      if (relicEffectActive(90) && lowHp) extra += ' • ✨ Boží milost (2×)!';
      if (relicEffectActive(30)) {
        heroEffects.removeWhere((e) => e.name == 'Milost světla');
        heroEffects.add(StatusEffect(name: 'Milost světla', description: '+10% fyzický útok', duration: 2, isBuff: true, physAtkMod: 0.10));
      }
      if (relicEffectActive(50) && heal > (maxHp * 0.25)) {
        final removed = heroEffects.where((e) => !e.isBuff).isNotEmpty;
        heroEffects.removeWhere((e) => !e.isBuff);
        if (removed) extra += ' • Rozbřesk';
      }
      if (relicEffectActive(70) && overheal > 0) { final extraShield = (overheal * 0.6).round(); bonusShield += extraShield; extra += ' • Zářivá vlna +$extraShield'; }
      // Lv60 "Posvěcení" a Lv80 "Nesené světlo" jsou přirozeně splněné existující mechanikou štítu.
    }
    return _DkSigilResult(dmg, heal, shield, extra);
  }

  // ===== Demon Hunter Glaive implementace (Havoc/Vengeance/Shadow) =====
  // Havoc Glaive je téměř 1:1 s Duelist Nemesis Crest (stejná nemesis mechanika, jiný flavor).
  // Vengeance Glaive je téměř 1:1 s Necromancer Blood Tome (čisté lifesteal). Shadow Glaive je
  // stejný DoT vzor jako Mage Fire Tome / Druid Balance Totem / Necromancer Plague Tome, jen
  // buffuje fyzický útok místo magického a "Fel zranitelnost" je vůči fyzickému dmg.
  _DkSigilResult _castDemonHunterSigil(SpecRelicDef r, int dmg, {required double targetHpRatio, required bool isBossTarget}) {
    int heal = 0, shield = 0;
    String extra = '';
    if (r.kind == SpecRelicKind.demonHunterHavocGlaive) {
      // ----- HAVOC: Zkáza stacky -> Rozsudek Zkázy finisher -> execute/garantovaný crit -----
      bool crit = (relicEffectActive(90) && targetHpRatio < 0.20) || Random().nextDouble() < critChance;
      if (crit) dmg = (dmg * (relicEffectActive(30) ? critDamageMultiplier * 1.1 : critDamageMultiplier)).round();
      final gain = 1 + (relicEffectActive(10) ? 1 : 0) + (relicEffectActive(30) && crit ? 1 : 0);
      specRelicStacks = min(5, specRelicStacks + gain);
      _restoreRelicArmorShredIfMatches('Znamení Zkázy');
      enemyEffects.removeWhere((e) => e.name == 'Znamení Zkázy');
      if (relicEffectActive(20)) _applyRelicArmorShred('Znamení Zkázy', 0.10);
      enemyEffects.add(StatusEffect(name: 'Znamení Zkázy', description: 'Zkáza $specRelicStacks/5${relicEffectActive(20) ? " • Armor cíle -10 %" : ""}', duration: 3, isBuff: false));
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '🎯 Znamení Zkázy x$specRelicStacks');
      if (crit) extra += ' • CRIT';
      if (relicEffectActive(40)) dmg = (dmg * (1 + (1 - targetHpRatio) * 0.4)).round();
      if (specRelicStacks >= 5 && relicEffectActive(50)) {
        int judgementDmg = (dmg * 1.1).round();
        if (relicEffectActive(60) && targetHpRatio < 0.30) judgementDmg = (judgementDmg * 1.35).round();
        dmg += judgementDmg;
        specRelicStacks = 0;
        _pushFx(FxKind.explosionDamage, FxSide.enemy, value: judgementDmg, burstKind: RelicBurstKind.doomVerdict);
        extra += ' • 💀 Rozsudek Zkázy +$judgementDmg';
      }
      // Lv70 "Vrácená zuřivost" - viz hook v _handleEnemyDeath(). Lv80 "Šířící se zkáza" - viz guard v _generateNextEnemy().
    } else if (r.kind == SpecRelicKind.demonHunterVengeanceGlaive) {
      // ----- VENGEANCE: čisté lifesteal z způsobeného poškození (stejný vzor jako Necromancer Blood Tome) -----
      bool crit = Random().nextDouble() < critChance;
      if (crit) dmg = (dmg * critDamageMultiplier).round();
      double lifestealPct = 0.25 + currentSpecRelicLevel * .003;
      heal = (dmg * lifestealPct).round();
      final bool lowHp = maxHp > 0 && hp / maxHp < 0.30;
      if (relicEffectActive(90) && lowHp) heal = (heal * 2).round();
      hp = min(maxHp, hp + heal);
      _pushFx(FxKind.statusApplied, FxSide.hero, label: '🩸 Krvavý řez Propasti', burstKind: (relicEffectActive(90) && lowHp) ? RelicBurstKind.abyssRitual : null);
      if (crit) extra += ' • CRIT';
      if (relicEffectActive(90) && lowHp) extra += ' • 🩸 Nesmrtelná Pomsta (2×)!';
      if (relicEffectActive(30)) energy = (energy + (heal * 0.15).round()).clamp(0, maxEnergy);
      if (relicEffectActive(50)) {
        final shieldMult = relicEffectActive(60) ? 0.35 : 0.20;
        shield = (heal * shieldMult).round();
        bonusShield += shield;
      }
      if (relicEffectActive(70) && bonusShield > 0) {
        heroEffects.removeWhere((e) => e.name == 'Fel odolnost');
        heroEffects.add(StatusEffect(name: 'Fel odolnost', description: '-10% obdrženého poškození', duration: 3, isBuff: true, armorMod: 0.10));
      }
      // Lv80 "Nesená krev" - bonusShield/heroEffects buffy se ve Věži nikdy neresetují samy, přenáší se přirozeně.
    } else if (r.kind == SpecRelicKind.demonHunterShadowGlaive) {
      // ----- SHADOW: Fel oheň DoT -> fyzický útok buff dokud běží -> Propastný pád na expiraci -----
      int dot = (dmg * (0.24 + currentSpecRelicLevel * .0045)).round();
      if (relicEffectActive(30)) dmg = (dmg * 1.10).round();
      bool crit = Random().nextDouble() < critChance;
      int instantTick = 0;
      if (crit) { dmg = (dmg * critDamageMultiplier).round(); if (relicEffectActive(60)) { instantTick = dot; dmg += instantTick; } extra += ' • CRIT'; }
      final dur = 3 + (relicEffectActive(70) ? 1 : 0) + (relicEffectActive(20) && Random().nextDouble() < 0.35 ? 1 : 0);
      enemyEffects.removeWhere((e) => e.name == 'Fel oheň');
      if (relicEffectActive(40)) _applyRelicArmorShred('Fel oheň', 0.12);
      enemyEffects.add(StatusEffect(name: 'Fel oheň', description: 'DoT $dot/kolo${relicEffectActive(40) ? " • Armor cíle -12 %" : ""}', duration: dur, isBuff: false, dotDamage: dot));
      _pushFx(FxKind.statusApplied, FxSide.enemy, label: '👁️ Fel oheň');
      if (instantTick > 0) extra += ' • okamžitý tick +$instantTick';
      if (relicEffectActive(50)) {
        heroEffects.removeWhere((e) => e.name == 'Stínový příliv');
        heroEffects.add(StatusEffect(name: 'Stínový příliv', description: '+12% fyzický útok', duration: dur, isBuff: true, physAtkMod: 0.12));
      }
      // Lv80 "Kořeny Propasti" - viz guard v _generateNextEnemy(). Lv90 "Propastný pád" - viz hook v _tickEffects().
    }
    return _DkSigilResult(dmg, heal, shield, extra);
  }

  void useSpecRelicArenaSpell(){
    if(!currentSpecRelicUnlocked||!isSpecRelicEquipped||specRelicUsedArena||arenaOpponentClass==null||arenaOpponentHp<=0)return;
    specRelicUsedArena=true; final r=currentSpecRelic; final atk=heroClass==HeroClass.mage||heroClass==HeroClass.healer?magAtk:physAtk;
    int dmg=(atk*(1.25+currentSpecRelicLevel*.025)).round(); int heal=0; int shield=0; String dkExtra='';
    if(r.kind==SpecRelicKind.deathKnightBloodSigil||r.kind==SpecRelicKind.deathKnightFrostSigil||r.kind==SpecRelicKind.deathKnightPlagueSigil){
      final res=_castDkSigil(r,dmg,isBossTarget:true);
      dmg=res.dmg; heal=res.heal; shield=res.shield; dkExtra=res.extra;
    } else if(r.kind==SpecRelicKind.hunterMarksmanQuiver||r.kind==SpecRelicKind.hunterBeastQuiver||r.kind==SpecRelicKind.hunterGhostQuiver){
      final res=_castHunterSigil(r,dmg,targetHpRatio:arenaOpponentHp/(arenaOpponentMaxHp==0?1:arenaOpponentMaxHp),isBossTarget:true);
      dmg=res.dmg; heal=res.heal; shield=res.shield; dkExtra=res.extra;
    } else if(r.kind==SpecRelicKind.warriorBerserkBanner||r.kind==SpecRelicKind.warriorGuardianBanner||r.kind==SpecRelicKind.warriorWarlordBanner){
      final res=_castWarriorSigil(r,dmg,targetHpRatio:arenaOpponentHp/(arenaOpponentMaxHp==0?1:arenaOpponentMaxHp),isBossTarget:true);
      dmg=res.dmg; heal=res.heal; shield=res.shield; dkExtra=res.extra;
    } else if(r.kind==SpecRelicKind.healerDawnSymbol||r.kind==SpecRelicKind.healerJudgementSymbol||r.kind==SpecRelicKind.healerBattleSymbol){
      final res=_castHealerSigil(r,dmg,targetHpRatio:arenaOpponentHp/(arenaOpponentMaxHp==0?1:arenaOpponentMaxHp),isBossTarget:true);
      dmg=res.dmg; heal=res.heal; shield=res.shield; dkExtra=res.extra;
    } else if(r.kind==SpecRelicKind.mageFireTome||r.kind==SpecRelicKind.mageFrostTome||r.kind==SpecRelicKind.mageArcaneTome){
      final res=_castMageSigil(r,dmg,targetHpRatio:arenaOpponentHp/(arenaOpponentMaxHp==0?1:arenaOpponentMaxHp),isBossTarget:true);
      dmg=res.dmg; heal=res.heal; shield=res.shield; dkExtra=res.extra;
    } else if(r.kind==SpecRelicKind.monkStormMala||r.kind==SpecRelicKind.monkStoneMala||r.kind==SpecRelicKind.monkHarmonyMala){
      final res=_castMonkSigil(r,dmg,targetHpRatio:arenaOpponentHp/(arenaOpponentMaxHp==0?1:arenaOpponentMaxHp),isBossTarget:true);
      dmg=res.dmg; heal=res.heal; shield=res.shield; dkExtra=res.extra;
    } else if(r.kind==SpecRelicKind.druidBalanceTotem||r.kind==SpecRelicKind.druidWildTotem||r.kind==SpecRelicKind.druidRestoTotem){
      final res=_castDruidSigil(r,dmg,targetHpRatio:arenaOpponentHp/(arenaOpponentMaxHp==0?1:arenaOpponentMaxHp),isBossTarget:true);
      dmg=res.dmg; heal=res.heal; shield=res.shield; dkExtra=res.extra;
    } else if(r.kind==SpecRelicKind.necromancerBoneTome||r.kind==SpecRelicKind.necromancerPlagueTome||r.kind==SpecRelicKind.necromancerBloodTome){
      final res=_castNecromancerSigil(r,dmg,targetHpRatio:arenaOpponentHp/(arenaOpponentMaxHp==0?1:arenaOpponentMaxHp),isBossTarget:true);
      dmg=res.dmg; heal=res.heal; shield=res.shield; dkExtra=res.extra;
    } else if(r.kind==SpecRelicKind.duelistNemesisCrest||r.kind==SpecRelicKind.duelistDanceCrest||r.kind==SpecRelicKind.duelistLightningCrest){
      final res=_castDuelistSigil(r,dmg,targetHpRatio:arenaOpponentHp/(arenaOpponentMaxHp==0?1:arenaOpponentMaxHp),isBossTarget:true);
      dmg=res.dmg; heal=res.heal; shield=res.shield; dkExtra=res.extra;
    } else if(r.kind==SpecRelicKind.paladinGuardianSeal||r.kind==SpecRelicKind.paladinJudgementSeal||r.kind==SpecRelicKind.paladinDawnSeal){
      final res=_castPaladinSigil(r,dmg,targetHpRatio:arenaOpponentHp/(arenaOpponentMaxHp==0?1:arenaOpponentMaxHp),isBossTarget:true);
      dmg=res.dmg; heal=res.heal; shield=res.shield; dkExtra=res.extra;
    } else if(r.kind==SpecRelicKind.demonHunterHavocGlaive||r.kind==SpecRelicKind.demonHunterVengeanceGlaive||r.kind==SpecRelicKind.demonHunterShadowGlaive){
      final res=_castDemonHunterSigil(r,dmg,targetHpRatio:arenaOpponentHp/(arenaOpponentMaxHp==0?1:arenaOpponentMaxHp),isBossTarget:true);
      dmg=res.dmg; heal=res.heal; shield=res.shield; dkExtra=res.extra;
    } else switch(r.mechanic){
      case RelicMechanic.guard: case RelicMechanic.iceWard: case RelicMechanic.stone:
        shield=(armor*.35+maxHp*.12+currentSpecRelicLevel*level).round(); bonusShield+=shield; dmg=(dmg*.55).round(); break;
      case RelicMechanic.dawn: case RelicMechanic.harmony:
        heal=(maxHp*(.18+currentSpecRelicLevel*.0015)).round(); hp=min(maxHp,hp+heal); shield=(heal*.35).round(); bonusShield+=shield; dmg=(dmg*.45).round(); break;
      case RelicMechanic.blood:
        heal=(dmg*(.15+(relicEffectActive(20)?0.10:0))).round(); hp=min(maxHp,hp+heal); if(relicEffectActive(50)){shield=(heal*.5).round();bonusShield+=shield;} break;
      case RelicMechanic.plague: case RelicMechanic.fire: case RelicMechanic.shadow:
        final dot=(dmg*(.22+currentSpecRelicLevel*.004)).round(); enemyEffects.add(StatusEffect(name:r.spell,description:'Relic DoT • ${relicEffectActive(40)?"snižuje Armor cíle":"postupné poškození"}',duration:3+(relicEffectActive(70)?1:0),isBuff:false,dotDamage:dot)); break;
      case RelicMechanic.frost: case RelicMechanic.mark: case RelicMechanic.nemesis:
        specRelicStacks=min(relicEffectActive(50)?2:1,specRelicStacks+1); if(relicEffectActive(60)&&specRelicStacks>=2)dmg=(dmg*1.8).round(); break;
      case RelicMechanic.rage: case RelicMechanic.command: case RelicMechanic.liturgy: case RelicMechanic.momentum: case RelicMechanic.chi:
        specRelicStacks=min(5,specRelicStacks+1); if(specRelicStacks>=5)dmg=(dmg*1.55).round(); break;
      case RelicMechanic.judgement:
        enemyEffects.add(StatusEffect(name:'Rozsudek',description:'Útoky proti cíli léčí hráče a oslabují jeho Armor.',duration:4,isBuff:false)); heal=(dmg*.12).round();hp=min(maxHp,hp+heal);break;
      case RelicMechanic.pet: dmg=(dmg*1.35).round(); huntersMarkStacks=min(5,huntersMarkStacks+1);break;
      case RelicMechanic.echo: dmg=(dmg*(1.05+currentSpecRelicLevel*.003)).round(); activeAbilityCooldown=max(0,activeAbilityCooldown-1);break;
      case RelicMechanic.riposte: heroEffects.add(StatusEffect(name:'Ve tanci',description:'Zvýšený Dodge a připravená Riposte (dodge spustí _duelistDanceCounter - musí se jmenovat přesně takhle, jinak se Riposte nespustí, viz _resolveCombatRound).',duration:2,isBuff:true,dodgeMod:0.05)); specRelicStacks=min(5,specRelicStacks+1);break;
    }
    arenaOpponentHp-=max(1,dmg); message='${r.spell}: $dmg damage${heal>0?' • heal $heal':''}${shield>0?' • shield $shield':''}.$dkExtra Relic Lv $currentSpecRelicLevel.';
    if(arenaOpponentHp<=0)_handleArenaWin(); notifyListeners();
  }

