    if(!currentSpecRelicUnlocked||!isSpecRelicEquipped||specRelicUsedLair||currentLairBossHp<=0)return;
    specRelicUsedLair=true; final r=currentSpecRelic; final atk=heroClass==HeroClass.mage||heroClass==HeroClass.healer?magAtk:physAtk;
