      final res=_castHealerSigil(r,dmg,targetHpRatio:currentLairBossHp/(currentLairBossMaxHp==0?1:currentLairBossMaxHp),isBossTarget:true);
      dmg=res.dmg; heal=res.heal; shield=res.shield; dkExtra=res.extra;
