  // bosse řeší přes _handleWorldBossDeath(). specRelicUsedWorldBoss se resetuje v enterWorldBoss().
  void useSpecRelicWorldBossSpell(){
    if(!currentSpecRelicUnlocked||!isSpecRelicEquipped||specRelicUsedWorldBoss||worldBossHp<=0)return;
    specRelicUsedWorldBoss=true; final r=currentSpecRelic; final atk=heroClass==HeroClass.mage||heroClass==HeroClass.healer?magAtk:physAtk;
