    worldBossHp-=max(1,dmg); message='${r.spell}: $dmg damage${heal>0?' • heal $heal':''}${shield>0?' • shield $shield':''}.$dkExtra Relic Lv $currentSpecRelicLevel.';
    if(worldBossHp<=0)_handleWorldBossDeath(); notifyListeners();
