  // Unified Armor: 100 % effectiveness against physical, 50 % against magical.
  // (samotný `armor` getter je teď definován výš, viz "ARMOR — TEĎ ČISTĚ Z ITEMŮ")
  double get armorScaling => max(250.0, level * 35.0 + maxHp * .018);
  double armorReduction(DamageKind type, {int? value}) { if (type == DamageKind.trueDamage) return 0; final a=max(0,value??armor).toDouble(); final physical=(a/(a+armorScaling)).clamp(0.0,armorHardCap); return type==DamageKind.magical?physical*.5:physical; }
  int mitigateDamage(num raw, DamageKind type, {int? value}) => max(1,(max(0,raw.toDouble())*(1-armorReduction(type,value:value))).round());
  double get physicalReduction => armorReduction(DamageKind.physical);
  double get magicalReduction => armorReduction(DamageKind.magical);
  // Attack Speed: sekundární stat na stejné úrovni jako Crit/Dodge/Block. Základ 1 (= 1 útok/kolo),
  // itemy (stat "Attack Speed") ho zvedají výš. Softcap 25 zvolen tak, aby rating 25 dal polovinu
  // maxima (17,5 % z 35 %) - na rozdíl od Agility (stovky až tisíce) tahle rating typicky poroste
  // jen v řádu jednotek/nízkých desítek, proto samostatný (nižší) softcap než u Agility jinde v souboru.
  double get attackSpeedRating => 1 + _itemStatSum("Attack Speed");
  double get extraAttackChance { final rating=attackSpeedRating; return ((rating/(rating+25.0))*.35).clamp(0.0,extraAttackHardCap); }
  // Proc je povolený jen ze základního útoku a nesmí spustit sám sebe (viz _extraAttackInProgress guard v fight*()).
  bool rollExtraAttack() => !_extraAttackInProgress && Random().nextDouble()<extraAttackChance;
  SpecRelicDef get currentSpecRelic => relicFor(heroClass,specialization);
  String get currentSpecRelicKey => currentSpecRelic.kind.name;
  int get currentSpecRelicLevel => specRelicLevels[currentSpecRelicKey]??0;
  bool get currentSpecRelicUnlocked => unlockedSpecRelics.contains(currentSpecRelicKey);
  int specRelicUpgradeCost(int target) { if(target<=1)return 100; const first=[100,150,225,300,425]; if(target<=5)return first[target-1]; final n=target-5; return 425+n*150+(n*(n-1)~/2)*25; }
  int get currentSpecRelicUpgradeCost => specRelicUpgradeCost(currentSpecRelicLevel+1);
  // Bonus se uplatní jen když je relic item skutečně NASAZEN v 11. slotu (EquipSlot.relic) -
  // vlastnictví (currentSpecRelicUnlocked) samo o sobě už nestačí, stejně jako u běžného gearu.
  bool get isSpecRelicEquipped => equipment.any((e) => e.slot == EquipSlot.relic && e.specRelicKey == currentSpecRelicKey);
  int get specRelicMainStatBonus => isSpecRelicEquipped ? level*currentSpecRelicLevel : 0;
  int get specRelicVitalityBonus => isSpecRelicEquipped ? level*currentSpecRelicLevel : 0;
  void tryDropCurrentSpecRelic() {
    if(currentSpecRelicUnlocked)return;
    final chance=(.03+arenaLeagueIndex*.004).clamp(.03,.10);
    final pity=(specRelicPityCounter[currentSpecRelicKey]??0)+1;
    final guaranteed=pity>=specRelicPityThreshold;
    if(guaranteed||Random().nextDouble()<chance){
      unlockedSpecRelics.add(currentSpecRelicKey);
      specRelicLevels[currentSpecRelicKey]=1;
      specRelicPityCounter[currentSpecRelicKey]=0;
      // Relic padá jako skutečný item v inventáři (11. slot, EquipSlot.relic), typu Artefakt -
      // nelze ho zničit/prodat/roztavit (viz Item.isArtifact, GameState.salvageItem()).
      // Musí se ručně nasadit, aby bonus/spell fungoval, ale nezabírá slot žádnému jinému gearu.
      if (bagItemCount < maxInventorySize) {
        inventory.add(Item(
          name: currentSpecRelic.name,
          value: 5000,
          stats: const {},
          rarity: Rarity.artifact,
          isArtifact: true,
          slot: EquipSlot.relic,
          specRelicKey: currentSpecRelicKey,
        ));
      }
      message=guaranteed
          ? 'Relic drop: ${currentSpecRelic.name}! (garantováno po $specRelicPityThreshold výhrách bez dropu) Nasaď ho v Inventáři (slot Relic), ať začne fungovat.'
          : 'Relic drop: ${currentSpecRelic.name}! Nasaď ho v Inventáři (slot Relic), ať začne fungovat.';
    } else {
      specRelicPityCounter[currentSpecRelicKey]=pity;
    }
  }
  void levelCurrentSpecRelic() { if(!currentSpecRelicUnlocked){message='Relic musí nejdříve padnout po vítězství v Aréně.';notifyListeners();return;} if(currentSpecRelicLevel>=maxSpecRelicLevel)return; final cost=currentSpecRelicUpgradeCost; if(conquerorCoins<cost){message='Potřebuješ $cost Mincí dobyvatele.';notifyListeners();return;} conquerorCoins-=cost;specRelicLevels[currentSpecRelicKey]=currentSpecRelicLevel+1;message='${currentSpecRelic.name}: level $currentSpecRelicLevel. Main stat +$specRelicMainStatBonus, Vitality +$specRelicVitalityBonus.';saveGame();notifyListeners(); }
}

